window.NCE.booksData[4] = {"id":4,"key":"NCE4","units":[{"id":"b4-u01","book":4,"unit":1,"key":"01","lessonFrom":1,"lessonTo":1,"title":"Finding Fossil Man","titleZh":"寻找化石人","question":"Why are legends handed down by storytellers useful?","sentences":[{"en":"We can read of things that happened 5,000 years ago in the Near East,","zh":"我们能读到5000年前近东发生的事，","t":17.43},{"en":"where people first learned to write.","zh":"那里的人们最早学会了书写。","t":23.28},{"en":"But there are some parts of the world where even now people cannot write.","zh":"但世界上的某些地方，即使到现在，人们仍然不会书写。","t":26.92},{"en":"The only way that they can preserve their history is to recount it as sagas legends handed down from one generation of storytellers to another.","zh":"他们保存历史的唯一方法，就是把一代代说书人流传下来的史诗故事讲述出来。","t":33.4},{"en":"These legends are useful because they can tell us something about migrations of people who lived long ago,","zh":"这些传说很有用，因为它们能告诉我们一些关于远古人类迁徙的信息，","t":46.15},{"en":"but none could write down what they did.","zh":"但没有人能记录下他们的所作所为。","t":54.22},{"en":"Anthropologists wondered where the remote ancestors of the Polynesian peoples now living in the Pacific Islandscame from.","zh":"人类学家们想知道，如今居住在太平洋岛屿上的波利尼西亚人的远古祖先来自何方。","t":57.67},{"en":"The sagas of these people explain that some of them came from Indonesia about 2,000 years ago.","zh":"这些人的史诗记载，他们中的一部分人大约在2000年前从印度尼西亚迁徙而来。","t":66.91},{"en":"But the first people who were like ourselves lived so long ago that even their sagas, if they had any, are forgotten.","zh":"但是，第一批与我们相似的人类生活在如此久远的年代，以至于即使他们曾有史诗，也早已被遗忘。","t":75.26},{"en":"So archaeologists have neither history nor legends to help them to find out where the first 'modern men' came from.","zh":"因此，考古学家既没有历史记载，也没有传说来帮助他们找出第一批“现代人”的起源。","t":85.71},{"en":"Fortunately, however, ancient men made tools of stone, especially flint,","zh":"然而，幸运的是，远古人类制造了石器，尤其是燧石工具，","t":94.84},{"en":"because this is easier to shape than other kinds.","zh":"因为它比其他种类的材料更容易塑形。","t":101.45},{"en":"They may also have used wood and skins, but these have rotted away.","zh":"他们也可能使用过木头和兽皮，但这些都已经腐烂殆尽了。","t":105.74},{"en":"Stone does not decay, and so the tools of long ago have remained when even the bones of the men who made them have disappeared without trace.","zh":"石头不会腐烂，因此，即使制造这些工具的人的骨骸早已消失得无影无踪，远古的石器工具依然留存至今。","t":112.16}],"vocab":[{"word":"fossil","phonetic":"/ˈfɒsl/","meanings":[{"pos":"noun","meaning":"化石","usage":"指远古生物的遗骸、遗迹经地质作用形成的石头，也可引申指思想守旧的人"}]},{"word":"legend","phonetic":"/ˈledʒənd/","meanings":[{"pos":"noun","meaning":"传说，传奇故事","usage":"指民间口头流传的历史相关故事，也可指传奇人物"}]},{"word":"preserve","phonetic":"/prɪˈzɜːv/","meanings":[{"pos":"verb","meaning":"保存，保留","usage":"强调使事物保持原有状态不被损坏，也可指食物保鲜、腌制"}]},{"word":"recount","phonetic":"/rɪˈkaʊnt/","meanings":[{"pos":"verb","meaning":"讲述，叙述","usage":"指详细复述已经发生的事，宾语多为故事、经历等"}]},{"word":"saga","phonetic":"/ˈsɑːɡə/","meanings":[{"pos":"noun","meaning":"英雄传说，长篇故事","usage":"指讲述家族、民族历史的长篇传奇叙事"}]},{"word":"migration","phonetic":"/maɪˈɡreɪʃn/","meanings":[{"pos":"noun","meaning":"迁移，迁徙","usage":"可指人类、动物的大规模迁居，也可指数据、人口的流动迁移"}]},{"word":"anthropologist","phonetic":"/ˌænθrəˈpɒlədʒɪst/","meanings":[{"pos":"noun","meaning":"人类学家","usage":"指研究人类起源、发展、文化习俗的专业学者"}]},{"word":"remote","phonetic":"/rɪˈməʊt/","meanings":[{"pos":"adjective","meaning":"遥远的，久远的","usage":"可表示时间、空间上的遥远，也可指关系疏远"}]},{"word":"ancestor","phonetic":"/ˈænsestə(r)/","meanings":[{"pos":"noun","meaning":"祖先，祖宗","usage":"指家族或民族的先辈，反义词为descendant（后代）"}]},{"word":"archaeologist","phonetic":"/ˌɑːkiˈɒlədʒɪst/","meanings":[{"pos":"noun","meaning":"考古学家","usage":"指通过研究古代遗存、文物还原历史的专业学者"}]},{"word":"flint","phonetic":"/flɪnt/","meanings":[{"pos":"noun","meaning":"燧石，火石","usage":"指一种坚硬的硅质岩石，古时用于制作工具或取火"}]},{"word":"shape","phonetic":"/ʃeɪp/","meanings":[{"pos":"verb","meaning":"塑造，使成形","usage":"指将材料加工为特定形状，也可引申为影响、塑造性格、观点等"}]},{"word":"rot","phonetic":"/rɒt/","meanings":[{"pos":"verb","meaning":"腐烂，腐败","usage":"指有机体被微生物分解变质，也可引申为制度、社会衰败"}]},{"word":"decay","phonetic":"/dɪˈkeɪ/","meanings":[{"pos":"verb","meaning":"腐烂，衰变","usage":"强调逐渐分解变坏的过程，可用于物质、建筑、社会制度等"}]}],"phrases":[{"phrase":"hand down","usage":"动词短语，指将传统、故事、财产等代代传承，常用被动语态be handed down","examples":[{"en":"These traditional crafts are handed down from generation to generation in this village.","zh":"这些传统手工艺在这个村子里代代相传。"}]},{"phrase":"read of","usage":"固定搭配，指读到、获悉某类信息，相当于read about","examples":[{"en":"I read of his outstanding contributions to medical research in the newspaper.","zh":"我在报纸上读到了他在医学研究方面做出的杰出贡献。"}]},{"phrase":"from generation to generation","usage":"副词短语，在句中作状语，表示一代接一代地","examples":[{"en":"The custom of eating mooncakes on Mid-Autumn Festival has been kept from generation to generation.","zh":"中秋节吃月饼的习俗被一代又一代地保留了下来。"}]},{"phrase":"neither...nor...","usage":"并列连词短语，连接两个并列成分，表示“既不…也不…”，连接主语时谓语动词遵循就近原则","examples":[{"en":"Neither my parents nor I am interested in this reality show.","zh":"我父母和我对这个真人秀都不感兴趣。"}]},{"phrase":"rot away","usage":"动词短语，指完全腐烂、烂掉，强调腐烂的最终结果","examples":[{"en":"The fallen leaves on the ground will rot away and become nutrients for the soil.","zh":"地上的落叶会腐烂掉，变成土壤的养分。"}]},{"phrase":"without trace","usage":"副词短语，在句中作状语，表示毫无踪迹、无影无踪","examples":[{"en":"The plane crashed into the mountain and disappeared without trace.","zh":"飞机撞上山后就消失得无影无踪了。"}]},{"phrase":"even now","usage":"副词短语，表强调，意为“即使到现在，即便在如今”","examples":[{"en":"Even now, many people in remote mountain areas still have no access to the Internet.","zh":"即使到现在，很多偏远山区的人们依然无法使用互联网。"}]},{"phrase":"long ago","usage":"副词短语，指很久以前，常用于一般过去时的句子中","examples":[{"en":"Long ago, there lived a kind old man in this small town.","zh":"很久以前，这个小镇上住着一位善良的老人。"}]}],"grammar":[{"title":"关系副词where与关系代词who引导的限定性定语从句","definition":"限定性定语从句用于修饰先行词，对先行词的范围进行限定，删除从句后主句意思会不完整。where指代表示地点的先行词，在从句中作地点状语；who指代表示人的先行词，在从句中作主语或宾语。","structure":"1. 表地点的先行词 + where + 完整从句；2. 表人的先行词 + who + 从句（who充当主语/宾语）","usage":"当需要对表示地点、人的名词进行限定说明时使用，使表达更准确具体。","examples":[{"en":"We can read of things that happened 5, 000 years ago in the Near East, where people first learned to write.","zh":"我们可以了解到5000年前近东发生的事情，那里的人最早学会了写字。"},{"en":"The professor who gave us a speech last week will come to our school again tomorrow.","zh":"上周给我们做演讲的那位教授明天会再次来我们学校。"}]},{"title":"may have done结构表对过去的推测","definition":"该结构用于表示说话人对过去已经发生的事情的不确定推测，推测发生的可能性中等，语气较为委婉。","structure":"主语 + may/might + have + 动词过去分词","usage":"当没有确切证据证明过去某事是否发生，仅进行可能性推测时使用。","examples":[{"en":"They may also have used wood and skins, but these have rotted away.","zh":"他们也可能使用过木头和兽皮，但这些东西都已经腐烂了。"},{"en":"She may have forgotten to inform us of the change of the meeting time.","zh":"她可能忘记通知我们会议时间变更的事了。"}]}],"patterns":[{"pattern":"The only way that sb can do sth is to do sth","explanation":"","original":{"en":"The only way that they can preserve their history is to recount it as sagas legends handed down from one generation of storytellers to another.","zh":"他们保存历史的唯一方法是将历史当作由一代又一代讲述人传承的英雄传说来复述。"},"examples":[{"en":"The only way that you can get high marks in the final exam is to review all the lessons carefully.","zh":"你在期末考试中取得高分的唯一方法是认真复习所有课程。"},{"en":"The only way that the company can reduce costs is to improve production efficiency.","zh":"这家公司降低成本的唯一方法是提升生产效率。"}]},{"pattern":"These ... are useful because they can tell us something about ...","explanation":"","original":{"en":"These legends are useful because they can tell us something about migrations of people who lived long ago.","zh":"这些传说很有用，因为它们能告诉我们生活在很久以前的人类迁徙的相关信息。"},"examples":[{"en":"These old photos are useful because they can tell us something about the city's great changes in the past 30 years.","zh":"这些老照片很有用，因为它们能告诉我们这座城市过去30年的巨大变化的相关信息。"},{"en":"These survey data are useful because they can tell us something about consumers' preference for new energy vehicles.","zh":"这些调查数据很有用，因为它们能告诉我们消费者对新能源汽车的偏好的相关信息。"}]},{"pattern":"..., and so ... have remained when even ... have disappeared.","explanation":"","original":{"en":"Stone does not decay, and so the tools of long ago have remained when even the bones of the men who made them have disappeared without trace.","zh":"石头不会腐烂，因此即使制造这些工具的人的骨头已经消失得无影无踪，远古的工具依然保留了下来。"},"examples":[{"en":"Paper is easy to preserve, and so the ancient books written thousands of years ago have remained when even the palaces where they were stored have disappeared.","zh":"纸张容易保存，因此即使存放这些古籍的宫殿已经消失，数千年前写下的古籍依然留存了下来。"},{"en":"True love does not change, and so the promise they made to each other has remained when even the ring that witnessed their engagement has been lost.","zh":"真爱不会改变，因此即使见证他们订婚的戒指已经丢失，他们对彼此许下的承诺依然留存。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“考古学家” 对应的单词是？","hint":"noun · /ˌɑːkiˈɒlədʒɪst/","options":["census","phase","archaeologist","immortal"],"answer":2,"explain":"archaeologist · /ˌɑːkiˈɒlədʒɪst/ · noun · 考古学家。指通过研究古代遗存、文物还原历史的专业学者","source":{"kind":"vocab","word":"archaeologist"},"id":"b4-u01-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：腐烂，衰变","hint":"/dɪˈkeɪ/ · verb","answer":"decay","placeholder":"输入英文单词","explain":"decay · /dɪˈkeɪ/ · verb · 腐烂，衰变。强调逐渐分解变坏的过程，可用于物质、建筑、社会制度等","source":{"kind":"vocab","word":"decay"},"id":"b4-u01-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The custom of eating mooncakes on Mid-Autumn Festival has been kept _____.","hint":"中秋节吃月饼的习俗被一代又一代地保留了下来。","answer":"from generation to generation","placeholder":"输入缺失的短语","explain":"from generation to generation：副词短语，在句中作状语，表示一代接一代地（中秋节吃月饼的习俗被一代又一代地保留了下来。）","source":{"kind":"phrase","phrase":"from generation to generation"},"id":"b4-u01-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Anthropologists wondered where the remote ancestors of the Polynesian peoples now living in the Pacific _____ from.","hint":"人类学家们想知道，如今居住在太平洋岛屿上的波利尼西亚人的远古祖先来自何方。","answer":"Islandscame","placeholder":"输入缺失的单词","explain":"Anthropologists wondered where the remote ancestors of the Polynesian peoples now living in the Pacific Islandscame from. — 人类学家们想知道，如今居住在太平洋岛屿上的波利尼西亚人的远古祖先来自何方。","source":{"kind":"sentence","en":"Anthropologists wondered where the remote ancestors of the Polynesian peoples now living in the Pacific Islandscame from."},"id":"b4-u01-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“限定性定语从句用于修饰先行词，对先行词的范围进行限定，删除从句后主句意思会不完整。where指代表示地点的先行词，在从句中作地点状语；who指代表示人的先行词，在从句中作主语或宾语。” 描述的是哪个语法点？","hint":"1. 表地点的先行词 + where + 完整从句；2. 表人的先行词 + who + 从句（who充当主语/宾语）","options":["It作形式主语的名词性从句","the + 比较级, the + 比较级 结构","过去分词作伴随状语","关系副词where与关系代词who引导的限定性定语从句"],"answer":3,"explain":"关系副词where与关系代词who引导的限定性定语从句：1. 表地点的先行词 + where + 完整从句；2. 表人的先行词 + who + 从句（who充当主语/宾语）：当需要对表示地点、人的名词进行限定说明时使用，使表达更准确具体。","source":{"kind":"grammar","title":"关系副词where与关系代词who引导的限定性定语从句"},"id":"b4-u01-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThese legends are useful because they can tell us something about migrations of people who lived long ago,","hint":"","options":["19世纪40年代用罗斯勋爵的大望远镜观察到的螺旋星云是研磨器留下的划痕的人更应受到谴责呢？","这些传说很有用，因为它们能告诉我们一些关于远古人类迁徙的信息，","他的巡逻队阻止了突袭队伍：饥饿侵袭着丹麦军队。","据记载，托马斯·卡莱尔听说他的朋友亨利·泰勒生病时，"],"answer":1,"explain":"These legends are useful because they can tell us something about migrations of people who lived long ago, — 这些传说很有用，因为它们能告诉我们一些关于远古人类迁徙的信息，","source":{"kind":"sentence","en":"These legends are useful because they can tell us something about migrations of people who lived long ago,"},"id":"b4-u01-q06"}]},{"id":"b4-u02","book":4,"unit":2,"key":"02","lessonFrom":2,"lessonTo":2,"title":"Spare That Spider","titleZh":"","question":"How much of each year do spiders spend killing insects?","sentences":[{"en":"Why, you may wonder, should spiders be our friends?","zh":"你可能要问，为什么蜘蛛应该是我们的朋友呢？","t":14.83},{"en":"Because they destroy so many insects, and insects include some of the greatest enemies of the human race.","zh":"因为它们消灭了那么多昆虫，而昆虫中有些是人类最大的敌人。","t":19.15},{"en":"Insects would make it impossible for us to live in the world;","zh":"昆虫会使我们无法在这个世界上生存；","t":26.74},{"en":"they would devour all our crops and kill our flocks and herds,","zh":"它们会吞噬我们所有的庄稼，杀死我们的家禽和牲畜，","t":30.38},{"en":"if it were not for the protection we get from insect eating animals.","zh":"如果不是因为食虫动物为我们提供保护的话。","t":34.62},{"en":"We owe a lot to the birds and beasts who eat insects","zh":"我们对那些吃昆虫的鸟兽负有很多，","t":39.77},{"en":"but all of them put together kill only a fraction of the number destroyed by spiders.","zh":"但它们合在一起消灭的昆虫数量，只是蜘蛛消灭数量的一小部分。","t":43.73},{"en":"Moreover, unlike some of the other insect eaters, spiders never do the least harm to us or our belongings.","zh":"此外，不像其他一些食虫动物，蜘蛛从不对我们或我们的财物造成丝毫损害。","t":49.79},{"en":"Spiders are not insects, as many people think, nor even nearly related to them.","zh":"蜘蛛不是昆虫，正如许多人认为的那样，甚至与昆虫没有多少亲缘关系。","t":58.72},{"en":"One can tell the difference almost at a glance, for a spider always has eight legs and an insect never more than six.","zh":"几乎一眼就能看出区别，因为蜘蛛总是有八条腿，而昆虫从不超过六条。","t":65.22},{"en":"How many spiders are engaged in this work on our behalf?","zh":"有多少蜘蛛正在为我们做这项工作呢？","t":74.93},{"en":"One authority on spiders made a census of the spiders in a grass field in the south of England,","zh":"一位研究蜘蛛的权威人士在英格兰南部的一片草地上对蜘蛛进行了普查，","t":79.25},{"en":"and he estimated that there were more than 2,250,000 in one acre;","zh":"他估计每英亩有225万多只蜘蛛；","t":85.79},{"en":"that is something like 6,000,000 spiders of different kinds on a football pitch.","zh":"这相当于一个足球场上有大约600万只不同种类的蜘蛛。","t":93.18},{"en":"Spiders are busy for at least half the year in killing insects.","zh":"蜘蛛每年至少有半年时间忙于捕杀昆虫。","t":99.86},{"en":"It is impossible to make more than the wildest guess at how many they kill, but they are hungry creatures, not content with only three meals a day.","zh":"要精确估计它们捕杀了多少昆虫是不可能的，只能进行最大胆的猜测，但它们是饥饿的生物，不满足于一天三餐。","t":104.98},{"en":"It has been estimated that the weight of all the insects destroyed by spiders in Britain in one year would be greater than the total weight of all the human beings in the country.","zh":"据估计，在英国一年内被蜘蛛消灭的所有昆虫的重量，将超过该国所有人类的总重量。","t":115.88}],"vocab":[{"word":"devour","phonetic":"/dɪˈvaʊə(r)/","meanings":[{"pos":"verb","meaning":"吞食；吞噬；毁灭","usage":"强调快速、贪婪地吃掉某物，也可引申指自然灾害等彻底毁坏事物"}]},{"word":"flock","phonetic":"/flɒk/","meanings":[{"pos":"noun","meaning":"羊群；(同类人的)群体","usage":"特指羊的群体，也可指代鸟群或人群"}]},{"word":"herd","phonetic":"/hɜːd/","meanings":[{"pos":"noun","meaning":"兽群；牧群(尤指牛群)","usage":"多指牛、马等大型家畜的群体"}]},{"word":"fraction","phonetic":"/ˈfrækʃn/","meanings":[{"pos":"noun","meaning":"小部分；少量；分数","usage":"强调只占整体的很小一部分"}]},{"word":"moreover","phonetic":"/mɔːrˈəʊvə(r)/","meanings":[{"pos":"adverb","meaning":"此外；而且","usage":"用于补充说明，递进逻辑连接词，比furthermore更正式"}]},{"word":"belongings","phonetic":"/bɪˈlɒŋɪŋz/","meanings":[{"pos":"noun","meaning":"所有物；财产","usage":"复数名词，指个人的随身物品或私有财产"}]},{"word":"related","phonetic":"/rɪˈleɪtɪd/","meanings":[{"pos":"adjective","meaning":"有关系的；有亲属关系的；同属一类的","usage":"常与介词to搭配，表示“与…相关/有亲缘关系”"}]},{"word":"census","phonetic":"/ˈsensəs/","meanings":[{"pos":"noun","meaning":"统计；普查；人口普查","usage":"指针对某一范围内的对象进行的全面统计调查"}]},{"word":"estimate","phonetic":"/ˈestɪmeɪt/","meanings":[{"pos":"verb","meaning":"估计；估算；判断","usage":"指根据现有信息进行大致的推算，名词形式为/ˈestɪmət/"}]},{"word":"acre","phonetic":"/ˈeɪkə(r)/","meanings":[{"pos":"noun","meaning":"英亩(面积单位，约等于4047平方米)","usage":"计量土地面积的英制单位"}]},{"word":"content","phonetic":"/kənˈtent/","meanings":[{"pos":"adjective","meaning":"满足的；满意的","usage":"常与with搭配，表示“对…感到满足”，名词形式/ˈkɒntent/意为“内容”"}]}],"phrases":[{"phrase":"owe sth to sb/sth","usage":"表示“把…归功于；欠…某物”，用于说明功劳、成果的来源","examples":[{"en":"We owe a lot to the birds and beasts who eat insects.","zh":"我们十分感激那些捕食昆虫的鸟类和兽类。"},{"en":"I owe my success to my family's support.","zh":"我把我的成功归功于家人的支持。"}]},{"phrase":"put together","usage":"表示“加起来；总共”，常用于对比某一群体和其他群体总和的差距","examples":[{"en":"All of them put together kill only a fraction of the number destroyed by spiders.","zh":"把它们所有加起来，杀死的昆虫数量也只是蜘蛛消灭数量的一小部分。"},{"en":"The profit of this month is more than the profit of the past three months put together.","zh":"这个月的利润比过去三个月的总和还多。"}]},{"phrase":"do harm to","usage":"表示“对…造成伤害/损害”，harm前可加little/any/the least等修饰词","examples":[{"en":"Spiders never do the least harm to us or our belongings.","zh":"蜘蛛从不对我们或我们的财物造成丝毫损害。"},{"en":"Smoking does great harm to people's lungs.","zh":"吸烟对人的肺部有很大伤害。"}]},{"phrase":"at a glance","usage":"表示“一眼；一看就”，强调识别、判断的速度非常快","examples":[{"en":"One can tell the difference almost at a glance.","zh":"人们几乎一眼就能看出两者的区别。"},{"en":"He recognized his old friend at a glance in the crowd.","zh":"他在人群里一眼就认出了自己的老朋友。"}]},{"phrase":"be engaged in","usage":"表示“忙于；从事于”，侧重指正在参与或忙于某项长期固定的活动","examples":[{"en":"How many spiders are engaged in this work on our behalf?","zh":"有多少蜘蛛在为我们做这项工作呢？"},{"en":"He has been engaged in environmental protection for 10 years.","zh":"他从事环保工作已经10年了。"}]},{"phrase":"on sb's behalf","usage":"表示“代表某人；为了某人的利益”，也可写作on behalf of sb","examples":[{"en":"Lawyers can make statements on their clients' behalf.","zh":"律师可以代表客户发表声明。"}]}],"grammar":[{"title":"虚拟条件句（与现在事实相反）","definition":"用来描述与现在真实情况不符的假设，表达不可能实现或假想的情况","structure":"If + 主语 + 动词过去式（be动词统一用were）, 主语 + would/could/might + 动词原形","usage":"用于表达非真实的假设，说明假设情况下会产生的结果","examples":[{"en":"If it were not for the protection we get from insect eating animals, they would devour all our crops and kill our flocks and herds.","zh":"若不是我们从食虫动物那里得到保护，它们就会吃光我们所有的庄稼，杀死我们的牛羊。"},{"en":"If I were you, I would choose to study abroad.","zh":"如果我是你，我会选择出国留学。"}]},{"title":"as引导的非限制性定语从句（否定转移）","definition":"as指代整个主句的内容，放在否定句中时，否定含义通常转移到as指代的内容上，表示“正如…不是那样”","structure":"主语 + 否定谓语 + ..., as + 从句","usage":"用于纠正大众的错误认知，说明“某件事并不像人们所想的那样”","examples":[{"en":"Spiders are not insects, as many people think, nor even nearly related to them.","zh":"蜘蛛并不像很多人认为的那样是昆虫，它们甚至和昆虫完全没有亲缘关系。"},{"en":"The elephant is not as big as you imagine.","zh":"大象并不像你想象的那么大。"}]}],"patterns":[{"pattern":"Why, you may wonder, should + 主语 + be + 表语?","explanation":"","original":{"en":"Why, you may wonder, should spiders be our friends?","zh":"你可能会好奇，为什么蜘蛛应该是我们的朋友呢？"},"examples":[{"en":"Why, you may wonder, should trees be so important to cities?","zh":"你可能会好奇，为什么树木对城市这么重要呢？"},{"en":"Why, you may wonder, should learning history be necessary for students?","zh":"你可能会好奇，为什么学习历史对学生来说是必要的？"}]},{"pattern":"It is impossible to do sth, but + 补充说明的分句","explanation":"","original":{"en":"It is impossible to make more than the wildest guess at how many they kill, but they are hungry creatures, not content with only three meals a day.","zh":"我们最多只能胡乱猜测它们杀死了多少昆虫，但它们是贪吃的生物，并不满足于一天只吃三餐。"},"examples":[{"en":"It is impossible to count how many stars are in the sky, but we know there are far more than we can see.","zh":"我们不可能数清天上有多少星星，但我们知道星星的数量远多于我们能看到的。"},{"en":"It is impossible to remember all the new words in one day, but we can memorize them step by step.","zh":"我们不可能一天记住所有的新单词，但我们可以一步步记住它们。"}]},{"pattern":"It has been estimated that + 从句","explanation":"","original":{"en":"It has been estimated that the weight of all the insects destroyed by spiders in Britain in one year would be greater than the total weight of all the human beings in the country.","zh":"据估计，英国境内的蜘蛛一年消灭的所有昆虫的总重量，比这个国家所有人口的总重量还要大。"},"examples":[{"en":"It has been estimated that over 50% of the city's population will choose public transport in 5 years.","zh":"据估计，五年内这个城市超过50%的人口会选择公共交通。"},{"en":"It has been estimated that the global temperature will rise by 1.5 degrees by 2050 if we don't reduce carbon emissions.","zh":"据估计，如果我们不减少碳排放，到2050年全球气温将上升1.5度。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“统计；普查；人口普查” 对应的单词是？","hint":"noun · /ˈsensəs/","options":["remote","steep","census","gigantic"],"answer":2,"explain":"census · /ˈsensəs/ · noun · 统计；普查；人口普查。指针对某一范围内的对象进行的全面统计调查","source":{"kind":"vocab","word":"census"},"id":"b4-u02-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：兽群；牧群(尤指牛群)","hint":"/hɜːd/ · noun","answer":"herd","placeholder":"输入英文单词","explain":"herd · /hɜːd/ · noun · 兽群；牧群(尤指牛群)。多指牛、马等大型家畜的群体","source":{"kind":"vocab","word":"herd"},"id":"b4-u02-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：One can tell the difference almost _____.","hint":"人们几乎一眼就能看出两者的区别。","answer":"at a glance","placeholder":"输入缺失的短语","explain":"at a glance：表示“一眼；一看就”，强调识别、判断的速度非常快（人们几乎一眼就能看出两者的区别。）","source":{"kind":"phrase","phrase":"at a glance"},"id":"b4-u02-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：One _____ on spiders made a census of the spiders in a grass field in the south of England,","hint":"一位研究蜘蛛的权威人士在英格兰南部的一片草地上对蜘蛛进行了普查，","answer":"authority","placeholder":"输入缺失的单词","explain":"One authority on spiders made a census of the spiders in a grass field in the south of England, — 一位研究蜘蛛的权威人士在英格兰南部的一片草地上对蜘蛛进行了普查，","source":{"kind":"sentence","en":"One authority on spiders made a census of the spiders in a grass field in the south of England,"},"id":"b4-u02-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“as指代整个主句的内容，放在否定句中时，否定含义通常转移到as指代的内容上，表示“正如…不是那样”” 描述的是哪个语法点？","hint":"主语 + 否定谓语 + ..., as + 从句","options":["as引导的非限制性定语从句（否定转移）","被动语态","定语从句的省略形式","比较状语从句 (Comparative Adverbial Clause)"],"answer":0,"explain":"as引导的非限制性定语从句（否定转移）：主语 + 否定谓语 + ..., as + 从句：用于纠正大众的错误认知，说明“某件事并不像人们所想的那样”","source":{"kind":"grammar","title":"as引导的非限制性定语从句（否定转移）"},"id":"b4-u02-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nSpiders are not insects, as many people think, nor even nearly related to them.","hint":"","options":["如果这些关于某种在后和在上的暗示","如果我们能真正看到一个粒子所描述的路径，","毒液并不是由生存竞争强加给它们的；","蜘蛛不是昆虫，正如许多人认为的那样，甚至与昆虫没有多少亲缘关系。"],"answer":3,"explain":"Spiders are not insects, as many people think, nor even nearly related to them. — 蜘蛛不是昆虫，正如许多人认为的那样，甚至与昆虫没有多少亲缘关系。","source":{"kind":"sentence","en":"Spiders are not insects, as many people think, nor even nearly related to them."},"id":"b4-u02-q06"}]},{"id":"b4-u03","book":4,"unit":3,"key":"03","lessonFrom":3,"lessonTo":3,"title":"Matterhorn Man","titleZh":"马特洪峰人","question":"What was the main objective of early mountain climbers?","sentences":[{"en":"Modern alpinists try to climb mountains by a route which will give them good sport,","zh":"现代登山者尝试通过一条能给他们带来良好体验的路线攀登山脉，","t":15.3},{"en":"and the more difficult it is, the more highly it is regarded.","zh":"越是困难，就越受推崇。","t":21.93},{"en":"In the pioneering days however, this was not the case at all.","zh":"然而，在开创时期，情况并非如此。","t":27.38},{"en":"The early climbers were looking for the easiest way to the top because the summit was the prize they sought,","zh":"早期登山者寻找最容易登顶的路线，因为山顶是他们追求的奖品，","t":33.65},{"en":"especially if it had never been attained before.","zh":"尤其是在从未有人登顶过的情况下。","t":41.88},{"en":"It is true that during their explorations they often faced difficulties and dangers of the most perilous nature,","zh":"诚然，在他们的探险过程中，他们经常面临最危险性质的困难和危险，","t":46.25},{"en":"equipped in a manner which would make a modern climber shudder at the thought,","zh":"他们所装备的方式会让现代登山者不寒而栗，","t":55.54},{"en":"but they did not go out of their way to court such excitement.","zh":"但他们并没有刻意追求这种刺激。","t":61.19},{"en":"They had a single aim, a solitary goal -- the top!","zh":"他们只有一个目的，一个唯一的目标——顶峰！","t":65.87},{"en":"It is hard for us to realize nowadays how difficult it was for the pioneers.","zh":"如今我们很难体会到先驱们当时所面临的困难。","t":72.55},{"en":"Except for one or two places such as Zermatt and Chamonix, which had rapidly become popular.","zh":"除了采尔马特和霞慕尼等一两个迅速变得受欢迎的地方，","t":79.21},{"en":"Alpine villages tended to be impoverished settlements cut off from civilization by the high mountains.","zh":"高山村庄往往是贫困的定居点，被高山与文明隔绝。","t":87.74},{"en":"Such inns as there were were generally dirty and flea-ridden;","zh":"那些仅有的旅馆通常肮脏且跳蚤遍布；","t":96.4},{"en":"the food simply local cheese accompanied by bread often twelve months old,","zh":"食物只是当地的奶酪，配上通常存放了十二个月的面包，","t":101.98},{"en":"all washed down with coarse wine.","zh":"所有这些都用粗劣的葡萄酒冲下。","t":107.86},{"en":"Often a valley boasted no inn at all, and climbers found shelter wherever they could --","zh":"通常一个山谷根本没有旅馆，登山者只好尽其所能寻找住处——","t":111.85},{"en":"sometimes with the local priest (who was usually as poor as his parishioners),","zh":"有时是和当地的牧师（他们通常和教区居民一样贫穷），","t":118.38},{"en":"sometimes with shepherds or cheese-makers.","zh":"有时是和牧羊人或奶酪制造者。","t":124.89},{"en":"Invariably the background was the same: dirt and poverty, and very uncomfortable.","zh":"背景总是相同的：肮脏和贫困，而且非常不舒服。","t":128.72},{"en":"For men accustomed to eating seven-course dinners and sleeping between fine linen sheets at home,","zh":"对于在家中习惯享用七道菜晚餐并睡在精细亚麻床单之间的人来说，","t":137.08},{"en":"the change to the Alps must have been very hard indeed.","zh":"这种阿尔卑斯山的生活转变一定非常艰难。","t":144.66}],"vocab":[{"word":"alpinist","phonetic":"/ˈælpɪnɪst/","meanings":[{"pos":"noun","meaning":"登山运动员；阿尔卑斯登山家","usage":"特指擅长攀登阿尔卑斯山脉的专业登山者"}]},{"word":"pioneering","phonetic":"/ˌpaɪəˈnɪərɪŋ/","meanings":[{"pos":"adjective","meaning":"先驱的；开创性的","usage":"用于描述某领域最早进行探索、开创先例的人或事物"}]},{"word":"summit","phonetic":"/ˈsʌmɪt/","meanings":[{"pos":"noun","meaning":"山顶；顶峰；峰会","usage":"可指山的最高点，也可引申为最高级别的官方会议"}]},{"word":"attain","phonetic":"/əˈteɪn/","meanings":[{"pos":"verb","meaning":"达到；获得；实现","usage":"正式用语，指经过努力实现目标或达到某个水平"}]},{"word":"perilous","phonetic":"/ˈperələs/","meanings":[{"pos":"adjective","meaning":"危险的；冒险的","usage":"书面语，强调风险极高、可能造成严重伤害的"}]},{"word":"shudder","phonetic":"/ˈʃʌdə(r)/","meanings":[{"pos":"verb","meaning":"发抖；战栗","usage":"通常因恐惧、寒冷或厌恶而不自觉地颤抖，常与at搭配"}]},{"word":"court","phonetic":"/kɔːt/","meanings":[{"pos":"verb","meaning":"招致；吸引；追求","usage":"此处指主动招致不好的事，也可表示追求异性、博取关注"}]},{"word":"solitary","phonetic":"/ˈsɒlətri/","meanings":[{"pos":"adjective","meaning":"唯一的；单独的；孤独的","usage":"强调单个的、没有其他伴随的"}]},{"word":"impoverished","phonetic":"/ɪmˈpɒvərɪʃt/","meanings":[{"pos":"adjective","meaning":"贫困的；赤贫的","usage":"正式用语，形容地区或人极度贫穷的状态"}]},{"word":"flea-ridden","phonetic":"/ˈfliː rɪdn/","meanings":[{"pos":"adjective","meaning":"布满跳蚤的","usage":"复合形容词，由名词+过去分词构成，表充满某个不好的事物的"}]},{"word":"coarse","phonetic":"/kɔːs/","meanings":[{"pos":"adjective","meaning":"粗糙的；粗劣的；粗俗的","usage":"可形容物品质量差，也可形容人的言行粗鲁"}]},{"word":"boast","phonetic":"/bəʊst/","meanings":[{"pos":"verb","meaning":"有（值得骄傲的东西）；吹嘘","usage":"中性义指某地/某人拥有某个好的事物，贬义指夸耀、说大话"}]},{"word":"parishioner","phonetic":"/pəˈrɪʃənə(r)/","meanings":[{"pos":"noun","meaning":"教区居民","usage":"指归某个教堂管辖的当地居民"}]},{"word":"invariably","phonetic":"/ɪnˈveəriəbli/","meanings":[{"pos":"adverb","meaning":"始终如一地；一贯地","usage":"强调情况没有例外、总是如此"}]},{"word":"accustomed","phonetic":"/əˈkʌstəmd/","meanings":[{"pos":"adjective","meaning":"习惯的；适应了的","usage":"固定搭配为be accustomed to (doing) sth，表习惯于某事"}]}],"phrases":[{"phrase":"the more...the more...","usage":"用于表示两个事物按比例同步变化，意为“越……就越……”","examples":[{"en":"The more difficult it is, the more highly it is regarded.","zh":"路线越难，就越被人们看重。"},{"en":"The more you practice, the more fluent your English will be.","zh":"你练习得越多，英语就会越流利。"}]},{"phrase":"in the pioneering days","usage":"指某个领域的初创、探索阶段，意为“在开创初期”","examples":[{"en":"In the pioneering days however, this was not the case at all.","zh":"然而在登山运动的初创时期，情况完全不是这样。"},{"en":"In the pioneering days of the Internet, few people could imagine its popularity today.","zh":"在互联网发展初期，很少有人能想象到它如今的普及程度。"}]},{"phrase":"go out of one's way to do sth","usage":"意为“特地、格外努力做某事；刻意做某事”","examples":[{"en":"They did not go out of their way to court such excitement.","zh":"他们并不是刻意追求这种刺激。"},{"en":"The host went out of his way to make every guest feel at home.","zh":"主人费尽心思让每位客人都感觉自在。"}]},{"phrase":"cut off from","usage":"意为“切断、隔绝与……的联系”，常用被动形式","examples":[{"en":"Alpine villages tended to be impoverished settlements cut off from civilization by the high mountains.","zh":"阿尔卑斯山区的村庄大多是贫穷的村落，被高山隔绝了与文明世界的联系。"},{"en":"The small town was cut off from the outside world due to the heavy snow.","zh":"由于大雪，这个小镇和外界失去了联系。"}]},{"phrase":"wash down","usage":"意为“（就着饮料）把食物送下；冲洗”","examples":[{"en":"All washed down with coarse wine.","zh":"所有食物都得就着粗劣的葡萄酒咽下。"},{"en":"You need some water to wash down the medicine.","zh":"你需要点水来把药送服下去。"}]},{"phrase":"accustomed to","usage":"意为“习惯于……”，to是介词，后接名词或动名词","examples":[{"en":"For men accustomed to eating seven-course dinners and sleeping between fine linen sheets at home.","zh":"对于那些习惯了在家吃七道菜的正餐、睡细亚麻床单的人来说。"},{"en":"She is accustomed to jogging for half an hour every morning.","zh":"她习惯了每天早上慢跑半小时。"}]}],"grammar":[{"title":"the + 比较级，the + 比较级结构","definition":"表示两个过程按比例同时增减，即前者变化的同时后者也随之发生相应变化","structure":"the + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子","usage":"用于说明两个变量的正相关或负相关关系，前半句相当于条件状语，后半句是结果","examples":[{"en":"The more difficult it is, the more highly it is regarded.","zh":"路线越难，就越被人们看重。"},{"en":"The earlier you start, the sooner you will finish the task.","zh":"你开始得越早，完成任务就越快。"}]},{"title":"过去分词作后置定语","definition":"过去分词放在被修饰的名词之后，相当于一个被动语态的定语从句，表被动或完成的含义","structure":"名词 + 过去分词短语","usage":"当定语内容较长时，常把过去分词短语后置，避免句子头重脚轻","examples":[{"en":"Alpine villages tended to be impoverished settlements cut off from civilization by the high mountains.","zh":"阿尔卑斯山区的村庄大多是贫穷的村落，被高山隔绝了与文明世界的联系。"},{"en":"The book written by my professor has been sold out nationwide.","zh":"我教授写的那本书已经在全国售罄了。"}]}],"patterns":[{"pattern":"It is true that..., but...","explanation":"","original":{"en":"It is true that during their explorations they often faced difficulties and dangers of the most perilous nature, equipped in a manner which would make a modern climber shudder at the thought, but they did not go out of their way to court such excitement.","zh":"诚然，在探险过程中他们经常面临极度的困难和危险，他们的装备简陋到现代登山者一想就会不寒而栗，但他们并不是刻意追求这种刺激。"},"examples":[{"en":"It is true that learning a new language takes a lot of time and effort, but the benefits it brings are priceless.","zh":"诚然，学习一门新语言需要投入大量时间和精力，但它带来的好处是无价的。"},{"en":"It is true that the team has made great progress this season, but they still have a long way to go to win the championship.","zh":"诚然，这支队伍本赛季已经取得了很大进步，但要赢得冠军他们还有很长的路要走。"}]},{"pattern":"It is hard for sb to do sth nowadays","explanation":"","original":{"en":"It is hard for us to realize nowadays how difficult it was for the pioneers.","zh":"如今我们很难想象当初的先驱者们面临的是怎样的困难。"},"examples":[{"en":"It is hard for young people nowadays to imagine how life was like without smartphones.","zh":"现在的年轻人很难想象没有智能手机的生活是什么样的。"},{"en":"It is hard for city dwellers nowadays to experience the quiet life in the countryside.","zh":"如今的城市居民很难体验到乡村的宁静生活。"}]},{"pattern":"For sb accustomed to..., sth must have been very hard indeed","explanation":"","original":{"en":"For men accustomed to eating seven-course dinners and sleeping between fine linen sheets at home, the change to the Alps must have been very hard indeed.","zh":"对于那些习惯了在家吃七道菜的正餐、睡细亚麻床单的人来说，到阿尔卑斯山的这种生活转变肯定非常艰难。"},"examples":[{"en":"For people accustomed to working in air-conditioned offices, doing physical work outdoors in summer must have been very hard indeed.","zh":"对于习惯了在空调办公室工作的人来说，夏天在户外做体力活肯定非常难熬。"},{"en":"For children accustomed to being taken care of by their parents, living alone in a new city must have been very hard indeed.","zh":"对于习惯了被父母照顾的孩子来说，独自在陌生城市生活肯定非常不容易。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“招致；吸引；追求” 对应的单词是？","hint":"verb · /kɔːt/","options":["herbage","court","submarine","spasm"],"answer":1,"explain":"court · /kɔːt/ · verb · 招致；吸引；追求。此处指主动招致不好的事，也可表示追求异性、博取关注","source":{"kind":"vocab","word":"court"},"id":"b4-u03-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：达到；获得；实现","hint":"/əˈteɪn/ · verb","answer":"attain","placeholder":"输入英文单词","explain":"attain · /əˈteɪn/ · verb · 达到；获得；实现。正式用语，指经过努力实现目标或达到某个水平","source":{"kind":"vocab","word":"attain"},"id":"b4-u03-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ of the Internet, few people could imagine its popularity today.","hint":"在互联网发展初期，很少有人能想象到它如今的普及程度。","answer":"in the pioneering days","placeholder":"输入缺失的短语","explain":"in the pioneering days：指某个领域的初创、探索阶段，意为“在开创初期”（在互联网发展初期，很少有人能想象到它如今的普及程度。）","source":{"kind":"phrase","phrase":"in the pioneering days"},"id":"b4-u03-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：sometimes with shepherds or _____","hint":"有时是和牧羊人或奶酪制造者。","answer":"cheese-makers","placeholder":"输入缺失的单词","explain":"sometimes with shepherds or cheese-makers. — 有时是和牧羊人或奶酪制造者。","source":{"kind":"sentence","en":"sometimes with shepherds or cheese-makers."},"id":"b4-u03-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示两个过程按比例同时增减，即前者变化的同时后者也随之发生相应变化” 描述的是哪个语法点？","hint":"the + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子","options":["may have done结构表对过去的推测","as if 引导的虚拟语气","插入语的用法","the + 比较级，the + 比较级结构"],"answer":3,"explain":"the + 比较级，the + 比较级结构：the + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子：用于说明两个变量的正相关或负相关关系，前半句相当于条件状语，后半句是结果","source":{"kind":"grammar","title":"the + 比较级，the + 比较级结构"},"id":"b4-u03-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nequipped in a manner which would make a modern climber shudder at the thought,","hint":"","options":["我们现在仍然如此；生活在一个不宣而战的侵略、战争、虚伪、","最近，俄罗斯报道了几宗这类事例，有人能用手指阅读和辨认颜色，甚至能看穿厚实的门和墙壁。","我们曾经能够自我修复——至少足以克服除了最即刻致命的疾病和事故之外的所有情况。","他们所装备的方式会让现代登山者不寒而栗，"],"answer":3,"explain":"equipped in a manner which would make a modern climber shudder at the thought, — 他们所装备的方式会让现代登山者不寒而栗，","source":{"kind":"sentence","en":"equipped in a manner which would make a modern climber shudder at the thought,"},"id":"b4-u03-q06"}]},{"id":"b4-u04","book":4,"unit":4,"key":"04","lessonFrom":4,"lessonTo":4,"title":"Seeing Hands","titleZh":"能看见东西的手","question":"How did Vera disover she had this gift of second sight?","sentences":[{"en":"Several cases have been reported in Russia recently of people who can read and detect colours with their fingers, and even see through solid doors and walls.","zh":"最近，俄罗斯报道了几宗这类事例，有人能用手指阅读和辨认颜色，甚至能看穿厚实的门和墙壁。","t":16.12},{"en":"One case concerns an 11-year-old schoolgirl Vera Petrova,","zh":"其中有一例是关于一个名叫维拉·彼得洛娃的11岁女学生。","t":27.32},{"en":"who has normal vision but who can also perceive things with different parts of her skin, and through solid walls.","zh":"她视力正常，但也同样能用皮肤的不同部位感知事物，并能看穿厚实的墙壁。","t":32.15},{"en":"This ability was first noticed by her father.","zh":"她父亲首先发现了她的这种能力。","t":40.7},{"en":"One day she came into his office and happened to put her hands on the door of a locked safe.","zh":"有一天，她走进她父亲的办公室，偶然把手放在一个锁着的保险柜的门上。","t":44.14},{"en":"Suddenly she asked her father why he kept so many old newspapers locked away there,","zh":"突然，她问父亲为什么把那么多旧报纸锁在里面，","t":50.44},{"en":"and even described the way they were done up in bundles.","zh":"她甚至说出了报纸捆扎的方式。","t":56.18},{"en":"Vera's curious talent was brought to the notice of a scientific research institute in the town of Ulyanovsk, near where she lives,","zh":"维拉的特异功能引起了她家附近，乌里扬诺夫斯克镇一家科研机构的注意。","t":60.32},{"en":"and in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic.","zh":"四月份，俄罗斯联邦共和国卫生部的一个特别委员会对她进行了一系列的测试。","t":69.76},{"en":"During these tests she was able to read a newspaper through an opaque screen and, stranger still,","zh":"在这些测试中，她能隔着不透明的屏幕阅读报纸；更奇怪的是，","t":79.54},{"en":"by moving her elbow over a child's game of Lotto she was able to describe the figures and colours printed on it;","zh":"她把胳膊肘放在儿童玩的“乐透”纸牌上，竟能说出上面印着的数字和颜色；","t":85.45},{"en":"and, in another instance, wearing stockings and slippers,","zh":"还有一次，她穿着长筒袜和拖鞋，","t":92.91},{"en":"to make out with her foot the outlines and colours of a picture hidden under a carpet.","zh":"用脚辨认出了藏在地毯下面的一幅画的轮廓和颜色。","t":96.72},{"en":"Other experiments showed that her knees and shoulders had a similar sensitivity.","zh":"其他实验表明，她的膝盖和肩膀也有类似的敏感性。","t":102.69},{"en":"During all these tests Vera was blindfold; and indeed, except when blindfold she lacked the ability to perceive things with her skin.","zh":"在所有这些实验中，维拉都是被蒙住眼睛的；的确，除了被蒙住眼睛，她就不具备用皮肤感知事物的能力。","t":108.26},{"en":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet.","zh":"人们还发现，尽管她能用手指感知事物，但她的手一湿，这种能力就消失了。","t":116.86}],"vocab":[{"word":"detect","phonetic":"/dɪˈtekt/","meanings":[{"pos":"verb","meaning":"察觉；发现；探测","usage":"指发现不易被注意到的事物、现象或问题，可接名词或从句作宾语"}]},{"word":"solid","phonetic":"/ˈsɒlɪd/","meanings":[{"pos":"adjective","meaning":"固体的；实心的；坚固的","usage":"可修饰物体的形态、质地，也可表示“可靠的”"}]},{"word":"perceive","phonetic":"/pəˈsiːv/","meanings":[{"pos":"verb","meaning":"感知；察觉；理解","usage":"强调通过感官或直觉意识到事物，可接名词、that从句或wh-从句"}]},{"word":"safe","phonetic":"/seɪf/","meanings":[{"pos":"noun","meaning":"保险箱；保险柜","usage":"指用于存放贵重物品的防盗容器，作形容词时意为“安全的”"}]},{"word":"bundle","phonetic":"/ˈbʌndl/","meanings":[{"pos":"noun","meaning":"捆；束；包","usage":"常与of搭配，a bundle of表示“一捆/一包某物”"}]},{"word":"talent","phonetic":"/ˈtælənt/","meanings":[{"pos":"noun","meaning":"天赋；才能；天才","usage":"可指天生具备的某种能力，have a talent for表示“有……的天赋”"}]},{"word":"institute","phonetic":"/ˈɪnstɪtjuːt/","meanings":[{"pos":"noun","meaning":"研究所；学院；机构","usage":"多指教育、科研等专业机构"}]},{"word":"commission","phonetic":"/kəˈmɪʃn/","meanings":[{"pos":"noun","meaning":"委员会；佣金","usage":"此处指官方成立的专门委员会，作“佣金”讲时不可数"}]},{"word":"opaque","phonetic":"/əʊˈpeɪk/","meanings":[{"pos":"adjective","meaning":"不透明的；难懂的","usage":"可修饰物体，也可指语言、含义晦涩难理解"}]},{"word":"elbow","phonetic":"/ˈelbəʊ/","meanings":[{"pos":"noun","meaning":"肘；肘部","usage":"指手臂关节处，也可作动词表示“用肘挤”"}]},{"word":"stocking","phonetic":"/ˈstɒkɪŋ/","meanings":[{"pos":"noun","meaning":"长筒袜","usage":"通常指女士穿的长筒袜，常用复数形式"}]},{"word":"slipper","phonetic":"/ˈslɪpə(r)/","meanings":[{"pos":"noun","meaning":"拖鞋","usage":"通常指室内穿的拖鞋，常用复数形式"}]},{"word":"outline","phonetic":"/ˈaʊtlaɪn/","meanings":[{"pos":"noun","meaning":"轮廓；大纲；概要","usage":"可指物体的外部形状，也可指文章、计划的要点"}]},{"word":"sensitivity","phonetic":"/ˌsensəˈtɪvəti/","meanings":[{"pos":"noun","meaning":"敏感性；灵敏度","usage":"是形容词sensitive的名词形式，可表示感官、仪器的灵敏度"}]},{"word":"blindfold","phonetic":"/ˈblaɪndfəʊld/","meanings":[{"pos":"adjective/adverb","meaning":"被蒙住眼睛的/地","usage":"作名词时指蒙眼布，作动词时表示“蒙住……的眼睛”"}]}],"phrases":[{"phrase":"second sight","usage":"固定表达，指预见未来的能力，或文中提到的“第二视觉”（不用眼睛看就能感知事物的能力）","examples":[{"en":"Some people believe that certain psychics have second sight.","zh":"一些人相信某些灵媒有预知能力。"}]},{"phrase":"concern sb/sth","usage":"表示“与……相关；涉及”，常用于介绍某个事件、情况的对象","examples":[{"en":"The report concerns the problem of air pollution in cities.","zh":"这份报告涉及城市空气污染的问题。"}]},{"phrase":"happen to do sth","usage":"表示“碰巧做某事；偶然发生某事”，强调偶然性","examples":[{"en":"I happened to meet my former teacher in the supermarket yesterday.","zh":"我昨天在超市碰巧遇到了我以前的老师。"}]},{"phrase":"do up","usage":"此处表示“捆；包；整理”，还可表示“扣上；修缮”","examples":[{"en":"Please do up these books and send them to the rural school.","zh":"请把这些书捆好，寄给那所乡村学校。"}]},{"phrase":"bring sth to the notice of sb","usage":"表示“使某人注意到某事”，是被动语态常用结构","examples":[{"en":"The student's excellent performance brought him to the notice of the professor.","zh":"这个学生的出色表现让教授注意到了他。"}]},{"phrase":"a series of","usage":"表示“一系列；一连串”，后接可数名词复数","examples":[{"en":"The school will hold a series of activities to celebrate its 100th anniversary.","zh":"学校将举办一系列活动来庆祝建校100周年。"}]},{"phrase":"make out","usage":"此处表示“辨认出；看出”，还可表示“理解；填写”","examples":[{"en":"It was so dark that I could hardly make out the road sign ahead.","zh":"天太黑了，我几乎看不清前面的路标。"}]},{"phrase":"the moment (that)","usage":"引导时间状语从句，表示“一……就……”，相当于as soon as","examples":[{"en":"The moment I got home, it began to rain heavily.","zh":"我一到家，就开始下大雨了。"}]}],"grammar":[{"title":"定语从句（定语后置分隔）","definition":"定语从句通常紧跟在先行词之后，但当先行词的定语较短时，为了避免句子头重脚轻，会将定语从句与先行词分隔开","structure":"名词 + 介词短语/其他短定语 + 定语从句","usage":"用于修饰前面的名词，解决长定语导致的句子结构失衡问题，翻译时需先判断先行词，再将定语含义补充到先行词前","examples":[{"en":"Several cases have been reported in Russia recently of people who can read and detect colours with their fingers.","zh":"最近俄罗斯报道了几起人们能用手指阅读和辨认颜色的案例。"},{"en":"I bought a picture yesterday which was painted by a famous artist.","zh":"我昨天买了一幅由著名艺术家绘制的画。"}]},{"title":"被动语态","definition":"表示主语是动作的承受者，强调动作的承受者或者不需要指出动作的执行者","structure":"be + 动词过去分词 + （by + 动作执行者）","usage":"常用于新闻、科普等正式文体中，突出客观事实，避免主观语气","examples":[{"en":"Vera's curious talent was brought to the notice of a scientific research institute.","zh":"薇拉奇特的天赋引起了一家科学研究所的注意。"},{"en":"The new library will be completed next month.","zh":"新图书馆将于下个月完工。"}]}],"patterns":[{"pattern":"One case concerns + 名词/名词短语, who/which + 定语从句","explanation":"","original":{"en":"One case concerns an 11-year-old schoolgirl Vera Petrova, who has normal vision but who can also perceive things with different parts of her skin, and through solid walls.","zh":"其中一个案例涉及一名11岁的女学生薇拉·佩特洛娃，她视力正常，但也能用身体不同部位的皮肤感知事物，并且能透过实心墙看东西。"},"examples":[{"en":"One case concerns a 7-year-old boy, who has a poor memory but can remember all the details of the paintings he has seen once.","zh":"其中一个案例涉及一名7岁的男孩，他记忆力很差，但能记住他只见过一次的画作的所有细节。"},{"en":"One case concerns a small coastal village, which has only 300 residents but attracts thousands of tourists every year.","zh":"其中一个案例涉及一个沿海小村庄，它只有300名居民，但每年吸引数千名游客。"}]},{"pattern":"It was also found that + 主语从句, although + 让步状语从句","explanation":"","original":{"en":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet.","zh":"人们还发现，虽然她能用手指感知事物，但她的手一湿，这种能力就消失了。"},"examples":[{"en":"It was also found that although the new drug can relieve pain effectively, it has obvious side effects on the elderly.","zh":"人们还发现，虽然这种新药能有效缓解疼痛，但它对老年人有明显的副作用。"},{"en":"It was found that although the device is very convenient to carry, its battery life is less than 5 hours.","zh":"人们发现，虽然这个设备携带起来很方便，但它的续航时间不到5小时。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“固体的；实心的；坚固的” 对应的单词是？","hint":"adjective · /ˈsɒlɪd/","options":["solid","rotate","estimate","compulsory"],"answer":0,"explain":"solid · /ˈsɒlɪd/ · adjective · 固体的；实心的；坚固的。可修饰物体的形态、质地，也可表示“可靠的”","source":{"kind":"vocab","word":"solid"},"id":"b4-u04-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It was so dark that I could hardly _____ the road sign ahead.","hint":"天太黑了，我几乎看不清前面的路标。","answer":"make out","placeholder":"输入缺失的短语","explain":"make out：此处表示“辨认出；看出”，还可表示“理解；填写”（天太黑了，我几乎看不清前面的路标。）","source":{"kind":"phrase","phrase":"make out"},"id":"b4-u04-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：It was also found that although she could perceive things with her fingers this _____ ceased the moment her hands were wet.","hint":"人们还发现，尽管她能用手指感知事物，但她的手一湿，这种能力就消失了。","answer":"ability","placeholder":"输入缺失的单词","explain":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet. — 人们还发现，尽管她能用手指感知事物，但她的手一湿，这种能力就消失了。","source":{"kind":"sentence","en":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet."},"id":"b4-u04-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“表示主语是动作的承受者，强调动作的承受者或者不需要指出动作的执行者” 描述的是哪个语法点？","hint":"be + 动词过去分词 + （by + 动作执行者）","options":["as引导的方式状语从句","被动语态","not until 强调句","完全倒装句（状语前置）"],"answer":1,"explain":"被动语态：be + 动词过去分词 + （by + 动作执行者）：常用于新闻、科普等正式文体中，突出客观事实，避免主观语气","source":{"kind":"grammar","title":"被动语态"},"id":"b4-u04-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nand in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic.","hint":"","options":["我们能读到5000年前近东发生的事，","四月份，俄罗斯联邦共和国卫生部的一个特别委员会对她进行了一系列的测试。","这些部分取决于个人情况，部分取决于心理因素。","他们徒劳地从一个地方狂奔到另一个地方，试图通过喧哗和移动来逃避复仇般的无聊。"],"answer":1,"explain":"and in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic. — 四月份，俄罗斯联邦共和国卫生部的一个特别委员会对她进行了一系列的测试。","source":{"kind":"sentence","en":"and in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic."},"id":"b4-u04-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 17 个单词","answer":"During these tests she was able to read a newspaper through an opaque screen and, stranger still,","placeholder":"输入完整英文句子","explain":"During these tests she was able to read a newspaper through an opaque screen and, stranger still, — 在这些测试中，她能隔着不透明的屏幕阅读报纸；更奇怪的是，","playText":"During these tests she was able to read a newspaper through an opaque screen and, stranger still,","source":{"kind":"sentence","en":"During these tests she was able to read a newspaper through an opaque screen and, stranger still,"},"id":"b4-u04-q06"}]},{"id":"b4-u05","book":4,"unit":5,"key":"05","lessonFrom":5,"lessonTo":5,"title":"Youth","titleZh":"青春","question":"How does the writer like to treat young people?","sentences":[{"en":"People are always talking about 'the problem of youth'.","zh":"人们总是在谈论“青年问题”。","t":14.44},{"en":"If there is one -- which I take leave to doubt","zh":"假如真有所谓“青年问题”——对此我不敢苟同","t":20.18},{"en":"-- then it is older people who create it, not the young themselves.","zh":"——那么这个问题是由老年人造成的，而不是年轻人本身造成的。","t":24.26},{"en":"Let us get down to fundamentals and agree that the young are after all human beings","zh":"让我们回归基本事实，承认年轻人毕竟也是人","t":29.98},{"en":"-- people just like their elders.","zh":"——和他们的长辈一样的人。","t":36.74},{"en":"There is only one difference between an old man and a young one:","zh":"老年人和年轻人只有一个区别：","t":39.6},{"en":"the young man has a glorious future before him","zh":"年轻人面前是光辉灿烂的未来","t":45},{"en":"and the old one has a splendid future behind him: and maybe that is where the rub is.","zh":"而老年人身后是辉煌的过去：也许症结就在这里。","t":48.85},{"en":"When I was a teenager, I felt that I was just young and uncertain --","zh":"当我还是个少年时，我觉得自己只是年轻和不确定——","t":57.12},{"en":"that I was a new boy in a huge school,","zh":"我就像一个庞大校园里的新生，","t":63.42},{"en":"and I would have been very pleased to be regarded as something so interesting as a problem.","zh":"如果被看作是像“问题”一样有趣的东西，我一定会非常高兴。","t":66.66},{"en":"For one thing, being a problem gives you a certain identity,","zh":"首先，成为一个“问题”会给你某种身份感，","t":73.57},{"en":"and that is one of the things the young are busily engaged in seeking.","zh":"而这正是年轻人正在努力寻找的东西之一。","t":78.92},{"en":"I find young people exciting.","zh":"我觉得年轻人令人兴奋。","t":84.14},{"en":"They have an air of freedom,","zh":"他们有一种自由的气息，","t":87.09},{"en":"and they have not a dreary commitment to mean ambitions or love of comfort.","zh":"他们对平庸的野心或安逸享乐没有沉闷的执着。","t":89.42},{"en":"They are not anxious social climbers, and they have no devotion to material things.","zh":"他们不是焦虑的社会攀爬者，他们对物质也没有任何执着。","t":95.47},{"en":"All this seems to me to link them with life and the origins of things.","zh":"这一切在我看来，都把他们与生命和万物本源联系在一起。","t":102.97},{"en":"It's as if they were in some sense cosmic beings in violent and lovely contrast with us suburban creatures.","zh":"仿佛他们在某种意义上是宇宙生灵，与我们这些市郊凡夫俗子形成强烈而可爱的对比。","t":109.63},{"en":"All that is in my mind when I meet a young person.","zh":"当我遇到一个年轻人时，我心里想的就是这些。","t":119.57},{"en":"He may be conceited, ill-mannered, presumptuous or fatuous, but I do not turn for protection to dreary cliches about respect for elders --","zh":"他可能自负、粗鲁、傲慢或愚蠢，但我不会用那些关于尊重长辈的陈词滥调来为自己辩护——","t":124.36},{"en":"as if mere age were a reason for respect.","zh":"仿佛仅仅年龄就是值得尊重的理由。","t":136.79},{"en":"I accept that we are equals, and I will argue with him, as an equal, if I think he is wrong.","zh":"我承认我们是平等的，如果我认为他错了，我会以平等的身份与他争辩。","t":141.38}],"vocab":[{"word":"glorious","phonetic":"/ˈɡlɔːriəs/","meanings":[{"pos":"adjective","meaning":"光荣的；辉煌的；极好的","usage":"用于描述值得称赞、非常美好或令人印象深刻的事物，可修饰未来、成就、风景等名词"}]},{"word":"splendid","phonetic":"/ˈsplendɪd/","meanings":[{"pos":"adjective","meaning":"极佳的；辉煌的；灿烂的","usage":"口语和书面语均常用，可表示对事物的赞赏，也可描述辉煌的经历、建筑等"}]},{"word":"rub","phonetic":"/rʌb/","meanings":[{"pos":"noun","meaning":"问题；困难；障碍","usage":"非正式用法，通常用单数形式，the rub 指某个情况中最难解决的问题所在"},{"pos":"verb","meaning":"擦；摩擦","usage":"表示用某物在表面来回移动擦拭的动作"}]},{"word":"identity","phonetic":"/aɪˈdentəti/","meanings":[{"pos":"noun","meaning":"身份；个性；认同感","usage":"指一个人区别于他人的固有特征，也可表示对自身所属群体的归属感"}]},{"word":"dreary","phonetic":"/ˈdrɪəri/","meanings":[{"pos":"adjective","meaning":"沉闷的；枯燥乏味的；令人沮丧的","usage":"用于描述事物或氛围无聊、缺乏趣味，使人感到消沉"}]},{"word":"commitment","phonetic":"/kəˈmɪtmənt/","meanings":[{"pos":"noun","meaning":"承诺；投入；献身","usage":"后常接介词to，表示对某事物的投入、承诺或责任"}]},{"word":"presumptuous","phonetic":"/prɪˈzʌmptʃuəs/","meanings":[{"pos":"adjective","meaning":"专横的；冒昧的；放肆的","usage":"用于描述人在没有得到许可的情况下做超出自己权限的事，带有贬义"}]},{"word":"fatuous","phonetic":"/ˈfætʃuəs/","meanings":[{"pos":"adjective","meaning":"愚蠢的；愚昧的；荒谬的","usage":"用于形容人或行为缺乏理智、十分荒唐"}]},{"word":"cliche","phonetic":"/ˈkliːʃeɪ/","meanings":[{"pos":"noun","meaning":"陈词滥调；老套的说法","usage":"指被过度使用以至于失去原有新意的表达或观点，带有贬义"}]},{"word":"cosmic","phonetic":"/ˈkɒzmɪk/","meanings":[{"pos":"adjective","meaning":"宇宙的；广大无边的","usage":"可描述和宇宙相关的事物，也可引申表示极其宏大、不受世俗局限的"}]},{"word":"suburban","phonetic":"/səˈbɜːbən/","meanings":[{"pos":"adjective","meaning":"郊区的；土气的；呆板的","usage":"除了表示地理位置在郊区，也可引申形容人思想偏狭、平淡无趣，带有贬义色彩"}]},{"word":"conceited","phonetic":"/kənˈsiːtɪd/","meanings":[{"pos":"adjective","meaning":"自负的；骄傲自大的","usage":"用于描述人过于高估自己，看不起他人，含贬义"}]},{"word":"fundamental","phonetic":"/ˌfʌndəˈmentl/","meanings":[{"pos":"noun","meaning":"基本原理；基础","usage":"常用复数形式fundamentals，指某一领域最核心、最基础的规则或事实"},{"pos":"adjective","meaning":"基础的；根本的","usage":"用于形容事物是核心的、至关重要的"}]},{"word":"devotion","phonetic":"/dɪˈvəʊʃn/","meanings":[{"pos":"noun","meaning":"深爱；奉献；热衷","usage":"后常接介词to，表示对某人、某事物的热爱或投入"}]}],"phrases":[{"phrase":"take leave to do sth","usage":"正式用语，用于礼貌地表示自己要做可能稍显冒昧的事，可译为“冒昧做某事，擅自做某事”","examples":[{"en":"If there is one -- which I take leave to doubt -- then it is older people who create it, not the young themselves.","zh":"如果确有这样一个问题的话——恕我对此表示怀疑——那也是老年人而非年轻人自己造成的。"},{"en":"I take leave to disagree with your view on this project.","zh":"请恕我冒昧，我不赞同你对这个项目的看法。"}]},{"phrase":"get down to fundamentals","usage":"表示开始探讨最核心、最根本的问题，get down to 意为“开始认真处理，着手做”","examples":[{"en":"Let us get down to fundamentals and agree that the young are after all human beings -- people just like their elders.","zh":"让我们来认真探讨一下根本问题，先承认年轻人毕竟也是人——和他们的长辈一样的人。"},{"en":"Instead of arguing about trivial details, we should get down to fundamentals of the plan.","zh":"我们与其争论无关紧要的细节，不如好好探讨这个计划的根本问题。"}]},{"phrase":"after all","usage":"常用于提醒对方某个容易被忽略的重要事实或理由，可译为“毕竟，终究”","examples":[{"en":"Let us get down to fundamentals and agree that the young are after all human beings -- people just like their elders.","zh":"让我们来认真探讨一下根本问题，先承认年轻人毕竟也是人——和他们的长辈一样的人。"},{"en":"You shouldn't scold him too much; after all, he is only a child.","zh":"你别太责怪他了，毕竟他还只是个孩子。"}]},{"phrase":"be engaged in (doing) sth","usage":"表示忙于做某事、参与某事，是正式表达","examples":[{"en":"For one thing, being a problem gives you a certain identity, and that is one of the things the young are busily engaged in seeking.","zh":"首先，成为问题能给你一种特定的身份，而这正是年轻人忙着追求的东西之一。"},{"en":"The researchers are engaged in studying the effect of climate change on local ecosystems.","zh":"研究人员正忙于研究气候变化对当地生态系统的影响。"}]},{"phrase":"an air of","usage":"用于描述人或事物带有某种气质、氛围，air在此处意为“神态，气质，氛围”","examples":[{"en":"They have an air of freedom, and they have not a dreary commitment to mean ambitions or love of comfort.","zh":"他们有一种自由的气质，不会乏味地投身于卑俗的野心或对安逸的追求中。"},{"en":"There is an air of mystery around the old castle at the top of the hill.","zh":"山顶上的那座古堡周围有一种神秘的氛围。"}]},{"phrase":"social climber","usage":"指试图通过结交上流社会人士来提高自身社会地位的人，含贬义，可译为“趋炎附势的人，想方设法跻身上流社会的人”","examples":[{"en":"They are not anxious social climbers, and they have no devotion to material things.","zh":"他们不是急着往上爬的趋炎附势之徒，也不执着于物质事物。"},{"en":"Everyone could tell that she was a social climber who only made friends with rich people.","zh":"所有人都能看出来她是个趋炎附势的人，只和有钱人交朋友。"}]},{"phrase":"in contrast with","usage":"表示“与……形成对比，和……相比”，用于突出两者之间的差异","examples":[{"en":"It's as if they were in some sense cosmic beings in violent and lovely contrast with us suburban creatures.","zh":"从某种意义上说，他们仿佛是宇宙的子民，与我们这些世俗庸人形成了强烈而美好的对比。"},{"en":"In contrast with last year's cold winter, this winter is unusually warm.","zh":"和去年寒冷的冬天相比，今年的冬天异常暖和。"}]},{"phrase":"turn to sb/sth for sth","usage":"表示“向……求助以获得某物”，是常用的固定搭配","examples":[{"en":"He may be conceited, ill-mannered, presumptuous or fatuous, but I do not turn for protection to dreary cliches about respect for elders -- as if mere age were a reason for respect.","zh":"他可能自负、无礼、放肆、愚蠢，但我不会用“要尊重长辈”这种陈腐的套话来为自己撑腰——好像仅凭年龄就值得尊重似的。"},{"en":"When you meet difficulties in study, you can turn to your teacher for help.","zh":"你在学习上遇到困难时，可以向老师求助。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用于突出句子中的某个成分（如主语、宾语、状语等），表达强烈语气的句式，常译为“正是……，就是……”","structure":"It is/was + 被强调部分 + that/who + 句子其余部分","usage":"被强调部分指人时可用who/that，指其他事物时只能用that；即使被强调部分是复数，be动词依然用is/was","examples":[{"en":"If there is one -- which I take leave to doubt -- then it is older people who create it, not the young themselves.","zh":"如果确有这样一个问题的话——恕我对此表示怀疑——那也是老年人而非年轻人自己造成的。"},{"en":"It is your hard work rather than luck that leads to your success.","zh":"正是你的努力而非运气造就了你的成功。"}]},{"title":"as if 引导的虚拟语气","definition":"as if意为“好像，仿佛”，当引导的从句表示的内容与事实不符或者是假想的情况时，需要使用虚拟语气","structure":"主句 + as if + 从句（从句用相应的过去时态表示虚拟）","usage":"表示与现在事实相反时，从句动词用一般过去时（be动词常用were，所有人称通用）；表示与过去事实相反时用过去完成时","examples":[{"en":"It's as if they were in some sense cosmic beings in violent and lovely contrast with us suburban creatures.","zh":"从某种意义上说，他们仿佛是宇宙的子民，与我们这些世俗庸人形成了强烈而美好的对比。"},{"en":"He talks as if he knew everything about this field, but actually he is a newcomer.","zh":"他说起话来好像对这个领域无所不知，但实际上他只是个新人。"}]},{"title":"as 引导的方式状语从句","definition":"as可引导方式状语从句，表示“按照，如同，就像”，说明动作的方式或两者的相似性","structure":"主句 + as + 从句","usage":"用于比较两个动作或情况的相似之处，从句通常是完整的句子，口语中可省略部分成分","examples":[{"en":"I accept that we are equals, and I will argue with him, as an equal, if I think he is wrong.","zh":"我认为我们是平等的，如果我觉得他错了，我会以平等的身份和他争论。"},{"en":"When in Rome, do as the Romans do.","zh":"入乡随俗。"}]}],"patterns":[{"pattern":"People are always talking about + 名词/名词短语.","explanation":"","original":{"en":"People are always talking about 'the problem of youth'.","zh":"人们总是在谈论“青年问题”。"},"examples":[{"en":"People are always talking about the impact of social media on teenagers.","zh":"人们总是在谈论社交媒体对青少年的影响。"},{"en":"People are always talking about the best way to keep healthy in modern society.","zh":"人们总是在谈论现代社会保持健康的最佳方式。"}]},{"pattern":"There is only one difference between A and B: A... and B...","explanation":"","original":{"en":"There is only one difference between an old man and a young one: the young man has a glorious future before him and the old one has a splendid future behind him.","zh":"老人和年轻人之间只有一个区别：年轻人的前面有辉煌的未来，而老人的辉煌未来已经在身后了。"},"examples":[{"en":"There is only one difference between optimistic people and pessimistic people: optimistic people always look for opportunities in difficulties, and pessimistic people always see difficulties in opportunities.","zh":"乐观的人和悲观的人之间只有一个区别：乐观的人总能在困难中寻找机会，而悲观的人总能在机会中看到困难。"},{"en":"There is only one difference between regular exercise and occasional exercise: regular exercise brings long-term health benefits, and occasional exercise only provides short-term comfort.","zh":"规律运动和偶尔运动只有一个区别：规律运动能带来长期的健康益处，而偶尔运动只能提供短期的安慰。"}]},{"pattern":"I find + 名词 + 形容词.","explanation":"","original":{"en":"I find young people exciting.","zh":"我觉得年轻人很有活力。"},"examples":[{"en":"I find reading books about history very interesting.","zh":"我觉得读历史相关的书非常有意思。"},{"en":"I find the process of learning a new language challenging but rewarding.","zh":"我觉得学习一门新语言的过程虽然有挑战，但很有收获。"}]},{"pattern":"Sb may be..., but I do not... -- as if...","explanation":"","original":{"en":"He may be conceited, ill-mannered, presumptuous or fatuous, but I do not turn for protection to dreary cliches about respect for elders -- as if mere age were a reason for respect.","zh":"他可能自负、无礼、放肆、愚蠢，但我不会用“要尊重长辈”这种陈腐的套话来为自己撑腰——好像仅凭年龄就值得尊重似的。"},"examples":[{"en":"He may be inexperienced and make mistakes sometimes, but I do not deny his value to the team -- as if seniority alone means everything.","zh":"他可能经验不足，偶尔会犯错，但我不会因此否定他对团队的价值——好像资历本身就代表一切似的。"},{"en":"This method may have some small flaws, but I do not reject it completely -- as if there was a perfect solution in the world.","zh":"这个方法可能有一些小缺陷，但我不会完全否定它——好像世界上存在完美的解决方案似的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“基本原理；基础” 对应的单词是？","hint":"noun · /ˌfʌndəˈmentl/","options":["fundamental","superstition","steep","remains"],"answer":0,"explain":"fundamental · /ˌfʌndəˈmentl/ · noun · 基本原理；基础。常用复数形式fundamentals，指某一领域最核心、最基础的规则或事实","source":{"kind":"vocab","word":"fundamental"},"id":"b4-u05-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：自负的；骄傲自大的","hint":"/kənˈsiːtɪd/ · adjective","answer":"conceited","placeholder":"输入英文单词","explain":"conceited · /kənˈsiːtɪd/ · adjective · 自负的；骄傲自大的。用于描述人过于高估自己，看不起他人，含贬义","source":{"kind":"vocab","word":"conceited"},"id":"b4-u05-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ last year's cold winter, this winter is unusually warm.","hint":"和去年寒冷的冬天相比，今年的冬天异常暖和。","answer":"in contrast with","placeholder":"输入缺失的短语","explain":"in contrast with：表示“与……形成对比，和……相比”，用于突出两者之间的差异（和去年寒冷的冬天相比，今年的冬天异常暖和。）","source":{"kind":"phrase","phrase":"in contrast with"},"id":"b4-u05-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：If there is one -- which I _____ leave to doubt","hint":"假如真有所谓“青年问题”——对此我不敢苟同","answer":"take","placeholder":"输入缺失的单词","explain":"If there is one -- which I take leave to doubt — 假如真有所谓“青年问题”——对此我不敢苟同","source":{"kind":"sentence","en":"If there is one -- which I take leave to doubt"},"id":"b4-u05-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“as if意为“好像，仿佛”，当引导的从句表示的内容与事实不符或者是假想的情况时，需要使用虚拟语气” 描述的是哪个语法点？","hint":"主句 + as if + 从句（从句用相应的过去时态表示虚拟）","options":["as if 引导的虚拟语气","while引导的让步状语从句","however引导的让步状语从句","suppose引导的假设条件句"],"answer":0,"explain":"as if 引导的虚拟语气：主句 + as if + 从句（从句用相应的过去时态表示虚拟）：表示与现在事实相反时，从句动词用一般过去时（be动词常用were，所有人称通用）；表示与过去事实相反时用过去完成时","source":{"kind":"grammar","title":"as if 引导的虚拟语气"},"id":"b4-u05-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAll that is in my mind when I meet a young person.","hint":"","options":["相比之下，一只旧表会变得磨损不堪，不可靠，最终不值得修理。","并且意识到这是孩子正在成长","当我遇到一个年轻人时，我心里想的就是这些。","这项研究被称为“阿内欣计划”。"],"answer":2,"explain":"All that is in my mind when I meet a young person. — 当我遇到一个年轻人时，我心里想的就是这些。","source":{"kind":"sentence","en":"All that is in my mind when I meet a young person."},"id":"b4-u05-q06"}]},{"id":"b4-u06","book":4,"unit":6,"key":"06","lessonFrom":6,"lessonTo":6,"title":"The Sporting Spirit","titleZh":"体育精神","question":"How does the writer describe sport at the international level?","sentences":[{"en":"I am always amazed when I hear people saying that sport creates goodwill between the nations, and that if only the common peoples of the world could meet one another at football or cricket, they would have no inclination to meet on the battlefield.","zh":"我听到人们说体育能在国家之间创造友谊，并且只要世界各国人民能在足球场或板球场上相遇，他们就无意在战场上相见时，我总是感到惊奇。","t":14.09},{"en":"Even if one didn't know from concrete examples (the 1936 Olympic Games, for instance) that international sporting contests lead to orgies of hatred, one could deduce it from general principles.","zh":"即使我们不知道具体的例子（例如1936年奥运会）表明国际体育比赛会导致仇恨的狂潮，我们也能从普遍原则中推断出来。","t":30.32},{"en":"Nearly all the sports practised nowadays are competitive.","zh":"如今几乎所有的体育运动都是竞技性的。","t":45.53},{"en":"You play to win, and the game has little meaning unless you do your utmost to win.","zh":"你比赛是为了赢，除非你尽力去赢，否则比赛就没有多大意义。","t":49.4},{"en":"On the village green, where you pick up sides and no feeling of local patriotism is involved, it is possible to play simply for the fun and exercise: but as soon as a the question of prestige arises, as soon as you feel that you and some larger unit will be disgraced if you lose, the most savage combative instincts are aroused.","zh":"在村庄草坪上，你随便组队，不涉及地方爱国主义情感，纯粹为了乐趣和锻炼而比赛是可能的：但一旦涉及声望问题，一旦你觉得你和某个更大的集体如果输了就会蒙羞，最原始的战斗本能就会被激发。","t":55.66},{"en":"Anyone who has played even in a school football match knows this.","zh":"即使是参加过学校足球比赛的人也知道这一点。","t":79.34},{"en":"At the international level, sport is frankly mimic warfare.","zh":"在国际层面，体育坦率地说是模仿战争。","t":83.62},{"en":"But the significant thing is not the behaviour of the players but the attitude of the spectators:","zh":"但重要的不是运动员的行为，而是观众的态度：","t":88.62},{"en":"and, behind the spectators, of the nations who work themselves into furies over these absurd contests,","zh":"在观众背后，是那些因这些荒谬的比赛而变得狂怒的国家，","t":94.89},{"en":"and seriously believe -- at any rate for short periods -- that running, jumping and kicking a ball are tests of national virtue.","zh":"并且——至少在短时间内——认真地相信跑步、跳跃和踢球是衡量民族美德的标准。","t":101.93}],"vocab":[{"word":"goodwill","phonetic":"/ˌɡʊdˈwɪl/","meanings":[{"pos":"noun","meaning":"善意，友好","usage":"不可数名词，常用来描述国家、组织或个人之间的友好态度"}]},{"word":"inclination","phonetic":"/ˌɪnklɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"倾向，意愿","usage":"常用搭配 have no inclination to do sth. 表示“没有做某事的意愿”"}]},{"word":"concrete","phonetic":"/ˈkɒŋkriːt/","meanings":[{"pos":"adjective","meaning":"具体的，确实的","usage":"常修饰evidence、example、proof等名词，与abstract（抽象的）相对"}]},{"word":"contest","phonetic":"/ˈkɒntest/","meanings":[{"pos":"noun","meaning":"比赛，竞赛","usage":"尤指会决出胜负的竞技类比赛，也可表示“争夺，竞争”"}]},{"word":"orgy","phonetic":"/ˈɔːdʒi/","meanings":[{"pos":"noun","meaning":"无节制的行为，放纵的活动","usage":"常用复数形式orgies，搭配of表示“大量的，肆意的”，文中orgies of hatred指“肆意宣泄的仇恨”"}]},{"word":"hatred","phonetic":"/ˈheɪtrɪd/","meanings":[{"pos":"noun","meaning":"仇恨，憎恨","usage":"不可数名词，语气比hate更强，常搭配介词for/of/between"}]},{"word":"deduce","phonetic":"/dɪˈdjuːs/","meanings":[{"pos":"verb","meaning":"推断，推论","usage":"常用搭配deduce sth. from sth. 表示“从……推断出……”"}]},{"word":"competitive","phonetic":"/kəmˈpetətɪv/","meanings":[{"pos":"adjective","meaning":"竞争的，竞技性的","usage":"可修饰活动、人或环境，指强调输赢、有竞争性质的"}]},{"word":"utmost","phonetic":"/ˈʌtməʊst/","meanings":[{"pos":"noun","meaning":"极限，最大可能","usage":"常用搭配do one's utmost to do sth. 表示“尽某人最大努力做某事”"}]},{"word":"patriotism","phonetic":"/ˈpeɪtriətɪzəm/","meanings":[{"pos":"noun","meaning":"爱国主义，爱国心","usage":"不可数名词，文中local patriotism指“地方集体荣誉感”"}]},{"word":"prestige","phonetic":"/preˈstiːʒ/","meanings":[{"pos":"noun","meaning":"声望，威望","usage":"不可数名词，指个人、集体或国家的声誉、脸面"}]},{"word":"disgraced","phonetic":"/dɪsˈɡreɪst/","meanings":[{"pos":"adjective","meaning":"丢脸的，蒙羞的","usage":"由动词disgrace派生而来，常用来描述人或集体因失败、犯错而失去名誉的状态"}]},{"word":"savage","phonetic":"/ˈsævɪdʒ/","meanings":[{"pos":"adjective","meaning":"野蛮的，凶猛的","usage":"常用来形容行为、情绪或动物带有攻击性、不受控制的特点"}]},{"word":"mimic","phonetic":"/ˈmɪmɪk/","meanings":[{"pos":"adjective","meaning":"模拟的，模仿的","usage":"用来描述不是真实的、只是对真实事物的模仿的事物"}]},{"word":"fury","phonetic":"/ˈfjʊəri/","meanings":[{"pos":"noun","meaning":"狂怒，暴怒","usage":"常用复数furies，指极度愤怒的情绪，搭配work oneself into furies表示“勃然大怒”"}]}],"phrases":[{"phrase":"if only","usage":"用来表示强烈的愿望或非真实的条件，常引导虚拟语气句子，意为“要是……就好了，只要”","examples":[{"en":"If only we could arrive there before the storm, we would be safe.","zh":"要是我们能在暴风雨来临前赶到那里，我们就安全了。"},{"en":"If only he had told me the truth earlier, I wouldn't have made such a mistake.","zh":"要是他早一点告诉我真相，我就不会犯这样的错误了。"}]},{"phrase":"have no inclination to do sth.","usage":"表示“没有做某事的意愿，不想做某事”，表达主观上的不情愿","examples":[{"en":"After a whole day of work, I have no inclination to go to the party tonight.","zh":"工作了一整天之后，我今晚不想去参加聚会。"},{"en":"He has no inclination to follow others' advice without thinking.","zh":"他不愿意不假思索就听从别人的建议。"}]},{"phrase":"lead to","usage":"动词短语，意为“导致，造成”，主语是原因，宾语是结果，to是介词，后接名词或动名词","examples":[{"en":"Lack of communication may lead to misunderstanding between friends.","zh":"缺乏沟通可能会导致朋友之间产生误会。"},{"en":"Hard work and careful planning finally led to the success of the project.","zh":"努力的工作和周密的计划最终让这个项目取得了成功。"}]},{"phrase":"do one's utmost to do sth.","usage":"固定搭配，表示“尽某人最大努力做某事”，和try one's best意思相近，语气更正式","examples":[{"en":"All the medical staff did their utmost to save the injured people in the accident.","zh":"所有医护人员都尽了最大努力抢救事故中的伤者。"},{"en":"We will do our utmost to finish the task before the deadline.","zh":"我们会尽最大努力在截止日期前完成任务。"}]},{"phrase":"pick up sides","usage":"指在比赛中临时组队，随意选择队员分成两队，没有刻意的安排","examples":[{"en":"When we play basketball on weekends, we usually pick up sides randomly.","zh":"我们周末打篮球的时候，通常都是随机组队的。"},{"en":"The children picked up sides on the playground to have a football match.","zh":"孩子们在操场上随便组队踢足球比赛。"}]},{"phrase":"arise","usage":"不及物动词，意为“出现，产生”，主语通常是problem、question、issue等抽象名词，不用于被动语态","examples":[{"en":"When difficulties arise, you should stay calm and find solutions.","zh":"当困难出现的时候，你应该保持冷静，寻找解决办法。"},{"en":"A new problem has arisen in the process of the experiment.","zh":"实验过程中出现了一个新问题。"}]},{"phrase":"at any rate","usage":"固定短语，意为“无论如何，至少”，用来对前面的说法进行补充说明或强调","examples":[{"en":"I'm not sure whether the plan will work, but at any rate we can have a try.","zh":"我不确定这个计划是否可行，但无论如何我们可以试一试。"},{"en":"At any rate, you should finish your homework before watching TV.","zh":"至少你应该先写完作业再看电视。"}]},{"phrase":"work oneself into furies","usage":"表示“使自己勃然大怒，陷入愤怒的情绪中”，强调情绪上的失控","examples":[{"en":"He always works himself into furies over small things that don't matter at all.","zh":"他总是因为一点无关紧要的小事就大发脾气。"},{"en":"There is no need to work yourself into furies just because of his rude words.","zh":"你没必要因为他的粗话就气得暴跳如雷。"}]}],"grammar":[{"title":"让步状语从句：even if/even though引导","definition":"用来引导让步状语从句，表达“即使，尽管”的含义，从句内容可以是真实的情况，也可以是假设的非真实情况，常使用虚拟语气","structure":"Even if + 从句, 主句","usage":"用于强调即使在某种条件下，主句的情况依然会发生，突出主句内容的必然性","examples":[{"en":"Even if you don't like him, you should still be polite to him.","zh":"即使你不喜欢他，你也应该对他保持礼貌。"},{"en":"Even if it rains tomorrow, we will still hold the sports meeting as scheduled.","zh":"即使明天下雨，我们还是会如期举办运动会。"}]},{"title":"条件状语从句：unless引导","definition":"unless表示“除非，如果不”，引导条件状语从句，相当于if...not，通常遵循“主将从现”的时态规则，即主句用将来时，从句用一般现在时表将来","structure":"主句 + unless + 从句","usage":"用来描述主句情况发生的唯一否定条件，即只有从句的情况不发生时，主句才会成立","examples":[{"en":"You won't pass the exam unless you study harder.","zh":"除非你更努力学习，否则你不会通过考试。"},{"en":"Unless we act now, the environmental problem will get worse and worse.","zh":"除非我们现在就采取行动，否则环境问题会越来越严重。"}]},{"title":"not...but...并列结构","definition":"用于连接两个并列的成分，表示“不是……而是……”，否定前者，肯定后者，连接的成分需要保持结构一致","structure":"not + 名词/短语/从句 + but + 名词/短语/从句","usage":"用来强调后者的重要性，纠正常见的误解，突出真正重要的内容","examples":[{"en":"The most important thing in learning a language is not memorizing grammar rules, but using it in real communication.","zh":"学习语言最重要的不是记忆语法规则，而是在真实交流中使用它。"},{"en":"What impressed me most was not the beautiful scenery there, but the kindness of the local people.","zh":"给我留下最深印象的不是那里的美景，而是当地人的友善。"}]}],"patterns":[{"pattern":"I am always amazed when I hear people saying that..., and that...","explanation":"","original":{"en":"I am always amazed when I hear people saying that sport creates goodwill between the nations, and that if only the common peoples of the world could meet one another at football or cricket, they would have no inclination to meet on the battlefield.","zh":"当我听人们说体育可以在国家之间创造善意，要是世界各国的普通民众能在足球场或板球场上相遇，他们就不会愿意在战场上兵戎相见，我总是感到十分惊讶。"},"examples":[{"en":"I am always amazed when I hear people saying that money can solve all problems, and that as long as one is rich, he can live a completely happy life.","zh":"当我听人们说钱可以解决所有问题，只要一个人有钱，他就能过得完全幸福，我总是感到十分惊讶。"},{"en":"I am always amazed when I hear people saying that hard work is the only factor leading to success, and that if you work hard enough, you will definitely achieve your goal.","zh":"当我听人们说努力是通往成功的唯一因素，只要你足够努力，就一定能实现目标，我总是感到十分惊讶。"}]},{"pattern":"Even if one didn't know from... that..., one could deduce it from...","explanation":"","original":{"en":"Even if one didn't know from concrete examples (the 1936 Olympic Games, for instance) that international sporting contests lead to orgies of hatred, one could deduce it from general principles.","zh":"即使人们没有从具体的例子（比如1936年奥运会）中了解到国际体育比赛会导致肆意的仇恨，也可以从一般原理中推断出这一点。"},"examples":[{"en":"Even if one didn't know from real cases that smoking does great harm to lung health, one could deduce it from scientific research results.","zh":"即使人们没有从真实案例中了解到吸烟对肺部健康有很大危害，也可以从科学研究结果中推断出这一点。"},{"en":"Even if one didn't know from daily experience that regular exercise can improve physical fitness, one could deduce it from relevant medical studies.","zh":"即使人们没有从日常经验中了解到规律锻炼可以提升身体素质，也可以从相关的医学研究中推断出这一点。"}]},{"pattern":"On..., where..., it is possible to...: but as soon as..., as soon as..., the most... instincts are aroused.","explanation":"","original":{"en":"On the village green, where you pick up sides and no feeling of local patriotism is involved, it is possible to play simply for the fun and exercise: but as soon as the question of prestige arises, as soon as you feel that you and some larger unit will be disgraced if you lose, the most savage combative instincts are aroused.","zh":"在乡村公共草地上，你可以随意组队，没有地方集体荣誉感的牵扯，可能仅仅为了乐趣和锻炼而玩耍：但一旦涉及声望的问题，一旦你觉得如果你输了，你和你所属的更大集体会蒙羞，最野蛮的好斗本能就会被激发出来。"},"examples":[{"en":"In a casual family game, where there is no prize or external judgment involved, it is possible to play board games simply for relaxation: but as soon as the sense of competition is stirred, as soon as you feel that you will be looked down upon if you lose, the strongest desire to win is aroused.","zh":"在随意的家庭游戏中，没有奖品也没有外界评判，你可能仅仅为了放松而玩桌游：但一旦竞争感被激发，一旦你觉得如果你输了就会被人看不起，最强烈的求胜欲就会被唤醒。"},{"en":"In the school art club, where you create works just for your own interest and no ranking is given, it is possible to draw simply for enjoyment: but as soon as there is a competition to take part in, as soon as you feel that your work represents the class, the greatest pressure to do well is aroused.","zh":"在学校美术社团里，你只是出于兴趣创作，没有排名，可能仅仅为了享受而画画：但一旦要参加比赛，一旦你觉得你的作品代表了班级，最大的想要做好的压力就会产生。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“丢脸的，蒙羞的” 对应的单词是？","hint":"adjective · /dɪsˈɡreɪst/","options":["incur","penalize","creditor","disgraced"],"answer":3,"explain":"disgraced · /dɪsˈɡreɪst/ · adjective · 丢脸的，蒙羞的。由动词disgrace派生而来，常用来描述人或集体因失败、犯错而失去名誉的状态","source":{"kind":"vocab","word":"disgraced"},"id":"b4-u06-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：仇恨，憎恨","hint":"/ˈheɪtrɪd/ · noun","answer":"hatred","placeholder":"输入英文单词","explain":"hatred · /ˈheɪtrɪd/ · noun · 仇恨，憎恨。不可数名词，语气比hate更强，常搭配介词for/of/between","source":{"kind":"vocab","word":"hatred"},"id":"b4-u06-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：When we play basketball on weekends, we usually _____ randomly.","hint":"我们周末打篮球的时候，通常都是随机组队的。","answer":"pick up sides","placeholder":"输入缺失的短语","explain":"pick up sides：指在比赛中临时组队，随意选择队员分成两队，没有刻意的安排（我们周末打篮球的时候，通常都是随机组队的。）","source":{"kind":"phrase","phrase":"pick up sides"},"id":"b4-u06-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ all the sports practised nowadays are competitive.","hint":"如今几乎所有的体育运动都是竞技性的。","answer":"Nearly","placeholder":"输入缺失的单词","explain":"Nearly all the sports practised nowadays are competitive. — 如今几乎所有的体育运动都是竞技性的。","source":{"kind":"sentence","en":"Nearly all the sports practised nowadays are competitive."},"id":"b4-u06-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“unless表示“除非，如果不”，引导条件状语从句，相当于if...not，通常遵循“主将从现”的时态规则，即主句用将来时，从句用一般现在时表将来” 描述的是哪个语法点？","hint":"主句 + unless + 从句","options":["条件状语从句：unless引导","if引导的非真实条件句（虚拟语气）","定语从句的省略结构","the + 比较级, the + 比较级 结构"],"answer":0,"explain":"条件状语从句：unless引导：主句 + unless + 从句：用来描述主句情况发生的唯一否定条件，即只有从句的情况不发生时，主句才会成立","source":{"kind":"grammar","title":"条件状语从句：unless引导"},"id":"b4-u06-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAt the international level, sport is frankly mimic warfare.","hint":"","options":["年纪越大越可能死亡的过程，是理所当然的事情，","在国际层面，体育坦率地说是模仿战争。","有时，作家内心的“酵母”比他写的一本书活得更久。","将海底视为地壳的基本形态是相当合理的，"],"answer":1,"explain":"At the international level, sport is frankly mimic warfare. — 在国际层面，体育坦率地说是模仿战争。","source":{"kind":"sentence","en":"At the international level, sport is frankly mimic warfare."},"id":"b4-u06-q06"}]},{"id":"b4-u07","book":4,"unit":7,"key":"07","lessonFrom":7,"lessonTo":7,"title":"Bats","titleZh":"蝙蝠","question":"In what way does echo-location in bats play an utilitarian role?","sentences":[{"en":"Not all sounds made by animals serve as language, and we have only to turn to that extraordinary discovery of echo-location in bats to see a case in which the voice plays a strictly utilitarian role.","zh":"并非所有动物发出的声音都作为语言，我们只需看看蝙蝠回声定位这项非凡的发现，就能明白声音在其中扮演着严格实用性角色的例子。","t":18.1},{"en":"To get a full appreciation of what this means we must turn first to some recent human inventions.","zh":"要充分理解这意味着什么，我们必须首先了解一些近期的人类发明。","t":35.97},{"en":"Everyone knows that if he shouts in the vicinity of a wall or a mountainside, an echo will come back.","zh":"每个人都知道，如果在墙壁或山边附近大喊，会听到回声。","t":44.33},{"en":"The further off this solid obstruction, the longer time will elapse for the return of the echo.","zh":"这种坚固障碍物越远，回声返回所需的时间就越长。","t":52.71},{"en":"A sound made by tapping on the hull of a ship will be reflected from the sea bottom, and by measuring the time interval between the taps and the receipt of the echoes the depth of the sea at that point can be calculated.","zh":"敲击船体发出的声音会从海底反射回来，通过测量敲击声和收到回声之间的时间间隔，可以计算出该点的海水深度。","t":61.27},{"en":"So was born the echo-sounding apparatus, now in general use in ships.","zh":"于是，回声测深仪应运而生，现在已普遍用于船只上。","t":79.36},{"en":"Every solid object will reflect a sound, varying according to the size and nature of the object.","zh":"每个固体物体都会反射声音，其反射效果因物体的大小和性质而异。","t":86.48},{"en":"A shoal of fish will do this.","zh":"一群鱼也会这样做。","t":94.94},{"en":"So it is a comparatively simple step from locating the sea bottom to locating a shoal of fish.","zh":"因此，从定位海底到定位一群鱼，这是一个相对简单的步骤。","t":97.58},{"en":"With experience, and with improved apparatus, it is now possible not only to locate a shoal but to tell if it is herring, cod, or other well-known fish, by the pattern of its echo.","zh":"凭借经验和改进后的设备，现在不仅可以定位鱼群，还可以通过其回声模式判断它们是鲱鱼、鳕鱼还是其他著名的鱼类。","t":105.89},{"en":"It has been found that certain bats emit squeaks and by receiving the echoes,","zh":"人们发现某些蝙蝠会发出吱吱声，并通过接收回声，","t":121.55},{"en":"they can locate and steer clear of obstacles -- or locate flying insects on which they feed.","zh":"它们可以定位并避开障碍物——或者定位它们赖以为食的飞行昆虫。","t":127.66},{"en":"This echo-location in bats is often compared with radar, the principle of which is similar.","zh":"蝙蝠的这种回声定位常与雷达相提并论，两者的原理相似。","t":135.81}],"vocab":[{"word":"echo-location","phonetic":"/ˈekəʊ ləʊˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"回声定位","usage":"指通过发出声音并接收回声来判断位置的生物或技术功能"}]},{"word":"utilitarian","phonetic":"/ˌjuːtɪlɪˈteəriən/","meanings":[{"pos":"adjective","meaning":"实用的，功利的","usage":"强调事物的实际用途而非装饰性或情感价值"}]},{"word":"vicinity","phonetic":"/vəˈsɪnəti/","meanings":[{"pos":"noun","meaning":"周围地区，邻近区域","usage":"常用搭配in the vicinity of表示“在……附近”"}]},{"word":"elapse","phonetic":"/ɪˈlæps/","meanings":[{"pos":"verb","meaning":"（时间）消逝，过去","usage":"主语通常为表示时间的名词，无被动语态"}]},{"word":"hull","phonetic":"/hʌl/","meanings":[{"pos":"noun","meaning":"船身，船体","usage":"指船的主体框架部分"}]},{"word":"interval","phonetic":"/ˈɪntəvl/","meanings":[{"pos":"noun","meaning":"间隔，间隙","usage":"可指时间或空间的间隔，常用搭配time interval表示“时间间隔”"}]},{"word":"apparatus","phonetic":"/ˌæpəˈreɪtəs/","meanings":[{"pos":"noun","meaning":"仪器，设备","usage":"指用于特定用途的成套或专用设备，复数可加es或保持原形"}]},{"word":"shoal","phonetic":"/ʃəʊl/","meanings":[{"pos":"noun","meaning":"鱼群；浅滩","usage":"表示鱼群时为可数名词，常用搭配a shoal of fish"}]},{"word":"herring","phonetic":"/ˈherɪŋ/","meanings":[{"pos":"noun","meaning":"鲱鱼","usage":"表示鱼类的可数名词，单复数同形"}]},{"word":"cod","phonetic":"/kɒd/","meanings":[{"pos":"noun","meaning":"鳕鱼","usage":"表示鱼类的可数名词，单复数同形"}]},{"word":"emit","phonetic":"/iˈmɪt/","meanings":[{"pos":"verb","meaning":"发出，散发（声、光、热等）","usage":"及物动词，宾语多为声音、光线、气味等名词"}]},{"word":"squeak","phonetic":"/skwiːk/","meanings":[{"pos":"noun","meaning":"短促的尖叫声，吱吱声","usage":"指尖锐、短促的声音，也可作动词表示“发出吱吱声”"}]},{"word":"steer","phonetic":"/stɪə(r)/","meanings":[{"pos":"verb","meaning":"驾驶，引导， steer clear of表示“避开，绕开”","usage":"既可以指操控交通工具，也可表示抽象的“引导、避开”"}]},{"word":"obstacle","phonetic":"/ˈɒbstəkl/","meanings":[{"pos":"noun","meaning":"障碍，障碍物","usage":"可指具体的阻挡物，也可指抽象的困难、阻碍"}]},{"word":"radar","phonetic":"/ˈreɪdɑː(r)/","meanings":[{"pos":"noun","meaning":"雷达","usage":"不可数名词，指利用无线电波探测目标的技术或设备"}]}],"phrases":[{"phrase":"serve as","usage":"表示“充当，用作，起……作用”，主语可以是人或物，后接表示身份、功能的名词","examples":[{"en":"Not all sounds made by animals serve as language.","zh":"动物发出的声音并不都起语言的作用。"},{"en":"The old sofa can serve as a bed for one night.","zh":"这个旧沙发可以当床睡一晚。"}]},{"phrase":"turn to","usage":"表示“求助于，查阅，转向”，后可接人、书籍、某个领域等名词","examples":[{"en":"To get a full appreciation of what this means we must turn first to some recent human inventions.","zh":"要充分理解这一点的含义，我们必须首先参考人类最近的一些发明。"},{"en":"When you meet new words, you can turn to a dictionary.","zh":"遇到生词时你可以查词典。"}]},{"phrase":"in the vicinity of","usage":"表示“在……附近，邻近”，为正式用语，后接地点名词","examples":[{"en":"If he shouts in the vicinity of a wall or a mountainside, an echo will come back.","zh":"如果人在墙壁或山坡附近大喊，就会传来回声。"},{"en":"There are three cafes in the vicinity of the campus.","zh":"校园附近有三家咖啡馆。"}]},{"phrase":"reflect from","usage":"表示“从……反射回来”，主语多为声音、光线等，后接反射的载体","examples":[{"en":"A sound made by tapping on the hull of a ship will be reflected from the sea bottom.","zh":"敲击船体发出的声音会从海底反射回来。"},{"en":"Sunlight reflects from the surface of the lake. 阳光从湖面反射回来。","zh":"阳光从湖面反射回来。"}]},{"phrase":"in general use","usage":"表示“普遍使用，通用”，描述某类设备、方法等被广泛应用的状态","examples":[{"en":"So was born the echo-sounding apparatus, now in general use in ships.","zh":"回声探测仪就这样诞生了，如今在船舶上被普遍使用。"},{"en":"Mobile payment is already in general use across the country.","zh":"移动支付已经在全国范围内普遍使用。"}]},{"phrase":"vary according to","usage":"表示“根据……而变化”，主语为被影响的对象，后接影响因素","examples":[{"en":"Every solid object will reflect a sound, varying according to the size and nature of the object.","zh":"所有固体都会反射声音，反射情况根据物体的大小和性质而不同。"},{"en":"The price of the product varies according to the season.","zh":"这款产品的价格随季节变化。"}]},{"phrase":"steer clear of","usage":"表示“避开，绕开”，既可指避开具体的障碍物，也可指避开抽象的人或麻烦","examples":[{"en":"They can locate and steer clear of obstacles.","zh":"它们能够定位并避开障碍物。"},{"en":"You should steer clear of that person; he is not reliable.","zh":"你应该离那个人远点，他不可靠。"}]},{"phrase":"feed on","usage":"表示“以……为食”，主语为动物或生物，后接食物来源","examples":[{"en":"They can locate flying insects on which they feed.","zh":"它们还能找到自己捕食的飞虫。"},{"en":"Owls feed on small mammals such as mice.","zh":"猫头鹰以老鼠之类的小型哺乳动物为食。"}]},{"phrase":"be compared with","usage":"表示“被与……相比”，用于同类事物的类比，主动形式为compare A with B","examples":[{"en":"This echo-location in bats is often compared with radar, the principle of which is similar.","zh":"蝙蝠的这种回声定位常被拿来和雷达作比较，二者原理相似。"},{"en":"The work of a teacher is often compared with that of a gardener.","zh":"教师的工作常被比作园丁的工作。"}]}],"grammar":[{"title":"完全倒装句","definition":"将谓语动词完全置于主语之前的倒装结构，常用于以so、only、表示地点/方向的副词开头的句子，且主语为名词时使用，作用是强调或保持句子平衡","structure":"So/状语 + 谓语 + 主语 + 其他成分","usage":"当前文描述的情况同样适用于后者，或者为了避免句子头重脚轻时使用完全倒装","examples":[{"en":"So was born the echo-sounding apparatus, now in general use in ships.","zh":"回声探测仪就这样诞生了，如今在船舶上被普遍使用。"},{"en":"Here comes the bus that we have been waiting for.","zh":"我们等的公交车来了。"}]},{"title":"介词+which引导的定语从句","definition":"定语从句的一种引导形式，当关系代词which在从句中作介词的宾语时，可将介词提前到which之前，使句子结构更紧凑，多用于正式文体","structure":"先行词 + 介词 + which + 从句剩余部分","usage":"介词的选择通常与先行词的搭配或从句中的动词/形容词搭配相关","examples":[{"en":"This echo-location in bats is often compared with radar, the principle of which is similar.","zh":"蝙蝠的这种回声定位常被拿来和雷达作比较，二者原理相似。"},{"en":"The book from which I got a lot of useful information was written by a famous scientist.","zh":"那本给了我很多有用信息的书是一位著名科学家写的。"}]},{"title":"it作形式主语的主语从句","definition":"当主语部分是较长的不定式、动名词或从句时，为了避免句子头重脚轻，用it作形式主语放在句首，真正的主语放在句子后半部分","structure":"It + be + 形容词/名词 + (for sb) + 真正主语（不定式/that从句等）","usage":"常用于表示“……是可能的/重要的/明显的”等含义的句子中","examples":[{"en":"It has been found that certain bats emit squeaks and by receiving the echoes, they can locate and steer clear of obstacles.","zh":"人们已经发现，某些蝙蝠会发出吱吱声，通过接收回声，它们能够定位并避开障碍物。"},{"en":"It is possible for us to finish the project ahead of time.","zh":"我们有可能提前完成这个项目。"}]}],"patterns":[{"pattern":"Not all + 名词 + 谓语 + 其他, and we have only to turn to + 例子 to see a case in which + 具体情况","explanation":"","original":{"en":"Not all sounds made by animals serve as language, and we have only to turn to that extraordinary discovery of echo-location in bats to see a case in which the voice plays a strictly utilitarian role.","zh":"动物发出的声音并不都起语言的作用，我们只要以蝙蝠回声定位这一非凡发现为例，就能看到声音发挥完全实用功能的情况。"},"examples":[{"en":"Not all after-school classes are beneficial to children, and we have only to turn to those repetitive training courses to see a case in which extra study actually reduces kids' interest in learning.","zh":"并非所有课外班都对孩子有益，我们只要看看那些重复性的训练课程，就能发现额外学习实际上会降低孩子学习兴趣的情况。"},{"en":"Not all technological advances bring positive effects, and we have only to turn to the problem of personal information leakage to see a case in which new technology creates unexpected risks.","zh":"并非所有技术进步都带来积极影响，我们只要看看个人信息泄露问题，就能发现新技术造成意外风险的情况。"}]},{"pattern":"With + 名词, it is now possible not only to do sth but to do sth by + 方式","explanation":"","original":{"en":"With experience, and with improved apparatus, it is now possible not only to locate a shoal but to tell if it is herring, cod, or other well-known fish, by the pattern of its echo.","zh":"凭借经验和改进的仪器，现在人们不仅能够定位鱼群，还能根据回声的模式判断它是鲱鱼、鳕鱼还是其他知名鱼类。"},"examples":[{"en":"With big data technology, and with optimized recommendation algorithms, it is now possible not only to predict users' preferences but to provide them with highly personalized services by their browsing history.","zh":"凭借大数据技术和优化的推荐算法，现在不仅能够预测用户的偏好，还能根据他们的浏览历史为其提供高度个性化的服务。"},{"en":"With better medical equipment, and with more professional medical staff, it is now possible not only to cure this rare disease but to reduce the possibility of its recurrence by regular follow-up checks.","zh":"凭借更好的医疗设备和更专业的医务人员，现在不仅能够治愈这种罕见病，还能通过定期随访降低其复发的可能性。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“间隔，间隙” 对应的单词是？","hint":"noun · /ˈɪntəvl/","options":["interval","defensive","odd","grimly"],"answer":0,"explain":"interval · /ˈɪntəvl/ · noun · 间隔，间隙。可指时间或空间的间隔，常用搭配time interval表示“时间间隔”","source":{"kind":"vocab","word":"interval"},"id":"b4-u07-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：实用的，功利的","hint":"/ˌjuːtɪlɪˈteəriən/ · adjective","answer":"utilitarian","placeholder":"输入英文单词","explain":"utilitarian · /ˌjuːtɪlɪˈteəriən/ · adjective · 实用的，功利的。强调事物的实际用途而非装饰性或情感价值","source":{"kind":"vocab","word":"utilitarian"},"id":"b4-u07-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：They can locate and _____ obstacles.","hint":"它们能够定位并避开障碍物。","answer":"steer clear of","placeholder":"输入缺失的短语","explain":"steer clear of：表示“避开，绕开”，既可指避开具体的障碍物，也可指避开抽象的人或麻烦（它们能够定位并避开障碍物。）","source":{"kind":"phrase","phrase":"steer clear of"},"id":"b4-u07-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It has been found that _____ bats emit squeaks and by receiving the echoes,","hint":"人们发现某些蝙蝠会发出吱吱声，并通过接收回声，","answer":"certain","placeholder":"输入缺失的单词","explain":"It has been found that certain bats emit squeaks and by receiving the echoes, — 人们发现某些蝙蝠会发出吱吱声，并通过接收回声，","source":{"kind":"sentence","en":"It has been found that certain bats emit squeaks and by receiving the echoes,"},"id":"b4-u07-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“将谓语动词完全置于主语之前的倒装结构，常用于以so、only、表示地点/方向的副词开头的句子，且主语为名词时使用，作用是强调或保持句子平衡” 描述的是哪个语法点？","hint":"So/状语 + 谓语 + 主语 + 其他成分","options":["such...that...结果状语从句","强调句 (Emphatic Sentence)","完全倒装句","现在分词短语作定语"],"answer":2,"explain":"完全倒装句：So/状语 + 谓语 + 主语 + 其他成分：当前文描述的情况同样适用于后者，或者为了避免句子头重脚轻时使用完全倒装","source":{"kind":"grammar","title":"完全倒装句"},"id":"b4-u07-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nthey can locate and steer clear of obstacles -- or locate flying insects on which they feed.","hint":"","options":["阿尔弗雷德在营地待了一周才返回阿瑟尔尼。","它们可以定位并避开障碍物——或者定位它们赖以为食的飞行昆虫。","还有一次，她穿着长筒袜和拖鞋，","如果不是身体休息的问题，那么也许是大脑需要休息？"],"answer":1,"explain":"they can locate and steer clear of obstacles -- or locate flying insects on which they feed. — 它们可以定位并避开障碍物——或者定位它们赖以为食的飞行昆虫。","source":{"kind":"sentence","en":"they can locate and steer clear of obstacles -- or locate flying insects on which they feed."},"id":"b4-u07-q06"}]},{"id":"b4-u08","book":4,"unit":8,"key":"08","lessonFrom":8,"lessonTo":8,"title":"Trading Standards","titleZh":"贸易标准","question":"What makes trading between rich countries difficult?","sentences":[{"en":"Chickens slaughtered in the United States, claim officials in Brussels, are not fit to grace European tables.","zh":"布鲁塞尔的官员声称，在美国宰杀的鸡不适合摆上欧洲餐桌。","t":13.09},{"en":"No, say the Americans: our fowl are fine, we simply clean them in a different way.","zh":"不，美国人说：我们的家禽很好，我们只是用不同的方式清洗它们。","t":22},{"en":"These days, it is differences in national regulations, far more than tariffs, that put sand in the wheels of trade between rich countries.","zh":"如今，是各国法规的差异，而不是关税，阻碍了富裕国家之间的贸易。","t":28.94},{"en":"It is not just farmers who are complaining.","zh":"抱怨的不仅仅是农民。","t":39.33},{"en":"An electric razor that meets the European Union's safety standards must be approved by American testers before it can be sold in the United States, and an American-made dialysis machine needs the EU's okay before it hits the market in Europe.","zh":"一款符合欧盟安全标准的电动剃须刀，在美国销售前必须通过美国测试员的批准；一台美国制造的透析机，在欧洲上市前需要得到欧盟的许可。","t":42.33},{"en":"As it happens, a razor that is safe in Europe is unlikely to electrocute Americans.","zh":"碰巧的是，在欧洲安全的剃须刀不太可能电死美国人。","t":61.16},{"en":"So, ask businesses on both sides of the Atlantic, why have two lots of tests where one would do?","zh":"因此，大西洋两岸的企业都在问，为什么需要进行两套测试，而一套就足够了？","t":67.6},{"en":"Politicians agree, in principle, so America and the EU have been trying to reach a deal which would eliminate the need to double-test many products.","zh":"政治家们原则上同意这一点，因此美国和欧盟一直在努力达成一项协议，以消除许多产品重复测试的必要性。","t":75.57},{"en":"They hope to finish in time for a trade summit between America and the EU on May 28th.","zh":"他们希望能在5月28日美国和欧盟贸易峰会前及时完成。","t":85.21},{"en":"Although negotiators are optimistic, the details are complex enough that they may be hard-pressed to get a deal at all.","zh":"尽管谈判代表持乐观态度，但细节足够复杂，他们可能很难达成协议。","t":92.01},{"en":"Why? One difficulty is to construct the agreements.","zh":"为什么？一个困难是构建协议。","t":100.07},{"en":"The Americans would happily reach one accord on standards for medical devices and then hammer out different pacts covering, say, electronic goods and drug manufacturing.","zh":"美国人乐意先就医疗器械标准达成一项协议，然后再敲定涵盖电子产品和药品生产等不同协议。","t":104.69},{"en":"The EU -- following fine continental traditions -- wants agreement on general principles,","zh":"欧盟——遵循优良的欧洲大陆传统——希望就普遍原则达成协议，","t":116.39},{"en":"which could be applied to many types of products and perhaps extended to other countries.","zh":"这些原则可以适用于多种类型的产品，并且可能扩展到其他国家。","t":122.77}],"vocab":[{"word":"slaughter","phonetic":"/ˈslɔːtə(r)/","meanings":[{"pos":"verb","meaning":"屠宰（动物）；屠杀，杀戮","usage":"可指为获取肉食宰杀牲畜，也可指暴力屠杀人类"}]},{"word":"grace","phonetic":"/ɡreɪs/","meanings":[{"pos":"verb","meaning":"为…增色；使优美；惠临","usage":"正式用语，常表示某物/某人为某个场合或地方增添光彩"},{"pos":"noun","meaning":"优美；优雅；恩惠","usage":"作名词可指动作的优雅，也可指上帝的恩典或他人的宽容"}]},{"word":"fowl","phonetic":"/faʊl/","meanings":[{"pos":"noun","meaning":"家禽（尤指鸡）；禽肉","usage":"可数名词，复数可作fowl或fowls，指家饲养的禽类，区别于野生鸟类"}]},{"word":"regulation","phonetic":"/ˌreɡjuˈleɪʃn/","meanings":[{"pos":"noun","meaning":"法规，规定；管理，控制","usage":"表示具体规章时为可数名词，表示监管的行为时为不可数名词"}]},{"word":"tariff","phonetic":"/ˈtærɪf/","meanings":[{"pos":"noun","meaning":"关税；（酒店、餐馆等的）价目表","usage":"外贸语境中通常指政府对进出口商品征收的关税"}]},{"word":"razor","phonetic":"/ˈreɪzə(r)/","meanings":[{"pos":"noun","meaning":"剃须刀，刮胡刀","usage":"指用于刮除毛发的刀具，常见搭配有electric razor（电动剃须刀）"}]},{"word":"dialysis","phonetic":"/daɪˈæləsɪs/","meanings":[{"pos":"noun","meaning":"透析，渗析（尤指肾透析）","usage":"医学术语，指通过过滤去除血液中废物的治疗方法，dialysis machine即透析机"}]},{"word":"electrocute","phonetic":"/ɪˈlektrəkjuːt/","meanings":[{"pos":"verb","meaning":"使触电身亡；以电刑处死","usage":"指电流通过人体导致死亡，被动形式be electrocuted十分常用"}]},{"word":"eliminate","phonetic":"/ɪˈlɪmɪneɪt/","meanings":[{"pos":"verb","meaning":"消除，排除；淘汰","usage":"强调完全去除不需要的事物，可接抽象名词如need、difficulty，也可表示比赛中淘汰队伍"}]},{"word":"summit","phonetic":"/ˈsʌmɪt/","meanings":[{"pos":"noun","meaning":"首脑会议，峰会；山顶，顶峰","usage":"国际政治经济语境中常指最高领导人之间的正式会议"}]},{"word":"negotiator","phonetic":"/nɪˈɡəʊʃieɪtə(r)/","meanings":[{"pos":"noun","meaning":"谈判代表，协商者","usage":"指参与正式谈判的人员，来自动词negotiate（谈判）"}]},{"word":"optimistic","phonetic":"/ˌɒptɪˈmɪstɪk/","meanings":[{"pos":"adjective","meaning":"乐观的，抱积极态度的","usage":"常搭配介词about，表示对某事持乐观态度，反义词为pessimistic"}]},{"word":"accord","phonetic":"/əˈkɔːd/","meanings":[{"pos":"noun","meaning":"协议，条约；一致，符合","usage":"正式用语，指国家或组织之间的正式协定，常见搭配reach an accord（达成协议）"},{"pos":"verb","meaning":"与…一致，符合；给予","usage":"作动词时可接with表示与某事一致，也可接双宾语表示授予某人某物"}]},{"word":"pact","phonetic":"/pækt/","meanings":[{"pos":"noun","meaning":"协定，契约，盟约","usage":"正式用语，指两方或多方之间的正式约定，语气比agreement更严肃"}]},{"word":"continental","phonetic":"/ˌkɒntɪˈnentl/","meanings":[{"pos":"adjective","meaning":"欧洲大陆的；大陆的，大洲的","usage":"英式英语中常用来指除英国群岛之外的欧洲大陆的"}]}],"phrases":[{"phrase":"put sand in the wheels of","usage":"非正式表达，比喻阻碍、阻挠某件事的顺利进行","examples":[{"en":"Strict visa rules put sand in the wheels of international academic exchanges.","zh":"严格的签证规定阻碍了国际学术交流的顺利进行。"}]},{"phrase":"meet ... standards","usage":"表示达到、符合某一标准，中间可接修饰标准的形容词或名词","examples":[{"en":"All our products meet the national environmental protection standards.","zh":"我们所有的产品都符合国家环保标准。"}]},{"phrase":"hit the market","usage":"指产品上市、进入市场销售，为非正式常用表达","examples":[{"en":"The new generation of smartphones will hit the market next month.","zh":"新一代智能手机将于下月上市。"}]},{"phrase":"as it happens","usage":"用作插入语，表示“碰巧，恰恰，实际上”，用来引出与话题相关的真实情况","examples":[{"en":"As it happens, I have the very book you are looking for in my bag.","zh":"真巧，我包里正好有你在找的那本书。"}]},{"phrase":"in principle","usage":"表示“原则上，大体上”，指在基本观点上同意，但细节尚未确定","examples":[{"en":"The board has approved the project in principle, but we still need to adjust the budget details.","zh":"董事会原则上批准了这个项目，但我们还需要调整预算细节。"}]},{"phrase":"in time for","usage":"表示“及时赶上，刚好来得及”做某事，后接名词或动名词","examples":[{"en":"We hurried to the station and arrived just in time for the last train.","zh":"我们匆忙赶到车站，刚好赶上最后一班火车。"}]},{"phrase":"be hard-pressed to do sth","usage":"表示做某事有很大困难，很难做成某事","examples":[{"en":"You would be hard-pressed to find a better coffee shop than this one in the whole city.","zh":"你很难在整个城市里找到比这家更好的咖啡店了。"}]},{"phrase":"hammer out","usage":"表示经过反复讨论、艰难谈判后最终制定出（方案、协议等）","examples":[{"en":"The two sides spent three days hammering out a compromise acceptable to everyone.","zh":"双方花了三天时间反复磋商，最终制定出了所有人都能接受的妥协方案。"}]},{"phrase":"apply to","usage":"表示“适用于，应用于”，后接适用的对象或范围","examples":[{"en":"This school rule applies to all students, no matter what grade they are in.","zh":"这条校规适用于所有学生，不管他们读几年级。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用来突出句子中某一成分（通常是主语、宾语、状语）的句型，用来加强语气","structure":"It is/was + 被强调部分 + that/who + 句子剩余部分","usage":"被强调部分指人时可以用who代替that，其他情况一律用that；去掉It is/was和that/who后句子仍然完整通顺","examples":[{"en":"It is differences in national regulations, far more than tariffs, that put sand in the wheels of trade between rich countries.","zh":"正是各国法规的差异，而非关税，给发达国家之间的贸易造成了阻碍。"},{"en":"It was my English teacher who inspired my interest in foreign cultures.","zh":"正是我的英语老师激发了我对外国文化的兴趣。"}]},{"title":"让步状语从句 (Adverbial Clause of Concession)","definition":"用来表示让步关系的从句，说明主句行为发生的不利条件或相反情况，翻译为“虽然，尽管”","structure":"Although/Though + 从句, 主句","usage":"although和though语气正式，通常不与but连用，但可以和yet、still搭配；放在句首或句中均可","examples":[{"en":"Although negotiators are optimistic, the details are complex enough that they may be hard-pressed to get a deal at all.","zh":"尽管谈判代表持乐观态度，但细节过于复杂，他们可能根本很难达成协议。"},{"en":"Although he is very busy every day, he still spares half an hour to read books.","zh":"尽管他每天都很忙，他还是会抽出半小时来读书。"}]},{"title":"非限制性定语从句 (Non-restrictive Attributive Clause)","definition":"对先行词起补充说明作用的定语从句，去掉后不影响主句意思的完整性，通常用逗号和主句隔开","structure":"主句, which/who/whose/where/when + 从句内容","usage":"不能用that引导，常用来修饰整个主句或者主句中的某个名词，翻译时通常单独成句","examples":[{"en":"The EU -- following fine continental traditions -- wants agreement on general principles, which could be applied to many types of products and perhaps extended to other countries.","zh":"欧盟遵循典型的欧洲大陆传统，希望就通用原则达成协议，这些原则可以适用于多种产品，甚至可能推广到其他国家。"},{"en":"She won the first prize in the speech contest, which made her parents very proud.","zh":"她在演讲比赛中获得了一等奖，这让她的父母非常骄傲。"}]}],"patterns":[{"pattern":"What makes + 名词/名词短语 + 形容词?","explanation":"","original":{"en":"What makes trading between rich countries difficult?","zh":"是什么让发达国家之间的贸易变得困难？"},"examples":[{"en":"What makes learning a foreign language challenging for many people?","zh":"是什么让学习外语对很多人来说充满挑战？"},{"en":"What makes the western region of the country so attractive to tourists?","zh":"是什么让这个国家的西部地区对游客如此有吸引力？"}]},{"pattern":"..., claim + 主语, ...","explanation":"","original":{"en":"Chickens slaughtered in the United States, claim officials in Brussels, are not fit to grace European tables.","zh":"布鲁塞尔的官员声称，在美国屠宰的鸡不配摆上欧洲的餐桌。"},"examples":[{"en":"Regular outdoor exercise can effectively reduce the risk of many chronic diseases, claim health experts.","zh":"健康专家声称，规律的户外运动可以有效降低很多慢性病的风险。"},{"en":"The new policy will bring more benefits to low-income families, claim local government officials.","zh":"当地政府官员声称，新政策将为低收入家庭带来更多福利。"}]},{"pattern":"One difficulty is to do sth","explanation":"","original":{"en":"One difficulty is to construct the agreements.","zh":"其中一个难点是制定相关协议。"},"examples":[{"en":"One difficulty for new graduates is to find a job that matches their professional skills and interests.","zh":"应届毕业生面临的一个难点是找到一份匹配他们专业技能和兴趣的工作。"},{"en":"One difficulty when travelling abroad is to overcome the language barrier.","zh":"出国旅行时的一个难点是克服语言障碍。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“剃须刀，刮胡刀” 对应的单词是？","hint":"noun · /ˈreɪzə(r)/","options":["virtual","cascade","boost","razor"],"answer":3,"explain":"razor · /ˈreɪzə(r)/ · noun · 剃须刀，刮胡刀。指用于刮除毛发的刀具，常见搭配有electric razor（电动剃须刀）","source":{"kind":"vocab","word":"razor"},"id":"b4-u08-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：屠宰（动物）；屠杀，杀戮","hint":"/ˈslɔːtə(r)/ · verb","answer":"slaughter","placeholder":"输入英文单词","explain":"slaughter · /ˈslɔːtə(r)/ · verb · 屠宰（动物）；屠杀，杀戮。可指为获取肉食宰杀牲畜，也可指暴力屠杀人类","source":{"kind":"vocab","word":"slaughter"},"id":"b4-u08-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The board has approved the project _____, but we still need to adjust the budget details.","hint":"董事会原则上批准了这个项目，但我们还需要调整预算细节。","answer":"in principle","placeholder":"输入缺失的短语","explain":"in principle：表示“原则上，大体上”，指在基本观点上同意，但细节尚未确定（董事会原则上批准了这个项目，但我们还需要调整预算细节。）","source":{"kind":"phrase","phrase":"in principle"},"id":"b4-u08-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：These days, it is differences in national regulations, far more than tariffs, that put sand in the _____ of trade between rich countries.","hint":"如今，是各国法规的差异，而不是关税，阻碍了富裕国家之间的贸易。","answer":"wheels","placeholder":"输入缺失的单词","explain":"These days, it is differences in national regulations, far more than tariffs, that put sand in the wheels of trade between rich countries. — 如今，是各国法规的差异，而不是关税，阻碍了富裕国家之间的贸易。","source":{"kind":"sentence","en":"These days, it is differences in national regulations, far more than tariffs, that put sand in the wheels of trade between rich countries."},"id":"b4-u08-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对先行词起补充说明作用的定语从句，去掉后不影响主句意思的完整性，通常用逗号和主句隔开” 描述的是哪个语法点？","hint":"主句, which/who/whose/where/when + 从句内容","options":["not until 强调句","非限制性定语从句 (Non-restrictive Attributive Clause)","虚拟语气在让步状语从句中的用法","强调句 (Emphatic Sentence)"],"answer":1,"explain":"非限制性定语从句 (Non-restrictive Attributive Clause)：主句, which/who/whose/where/when + 从句内容：不能用that引导，常用来修饰整个主句或者主句中的某个名词，翻译时通常单独成句","source":{"kind":"grammar","title":"非限制性定语从句 (Non-restrictive Attributive Clause)"},"id":"b4-u08-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nSo, ask businesses on both sides of the Atlantic, why have two lots of tests where one would do?","hint":"","options":["后来，为了自身的安全和实际需要，它必须培养（部分通过触摸）粗略判断三维距离的能力。","但重要的不是运动员的行为，而是观众的态度：","因此，大西洋两岸的企业都在问，为什么需要进行两套测试，而一套就足够了？","它必须很高，因为它就像一个巨大的滑轮组，我们必须把巨大的钻杆放下去，"],"answer":2,"explain":"So, ask businesses on both sides of the Atlantic, why have two lots of tests where one would do? — 因此，大西洋两岸的企业都在问，为什么需要进行两套测试，而一套就足够了？","source":{"kind":"sentence","en":"So, ask businesses on both sides of the Atlantic, why have two lots of tests where one would do?"},"id":"b4-u08-q06"}]},{"id":"b4-u09","book":4,"unit":9,"key":"09","lessonFrom":9,"lessonTo":9,"title":"Royal Espionage","titleZh":"王室谍报","question":"What important thing did King Alfred learn when he penetrated the Danish camp of Guthrum?","sentences":[{"en":"Alfred the Great acted as his own spy, visiting Danish camps disguised as a minstrel.","zh":"阿尔弗雷德大帝亲自充当间谍，乔装成吟游诗人，拜访丹麦营地。","t":20.72},{"en":"In those days wandering minstrels were welcome everywhere.","zh":"在那些日子里，四处游荡的吟游诗人在任何地方都受到欢迎。","t":29.54},{"en":"They were not fighting men, and their harp was their passport.","zh":"他们不是战士，他们的竖琴就是他们的通行证。","t":34.45},{"en":"Alfred had learned many of their ballads in his youth and could vary his programme with acrobatic tricks and simple conjuring.","zh":"阿尔弗雷德年轻时学过许多他们的民谣，并能通过杂技表演和简单的魔术来丰富他的节目。","t":39.2},{"en":"While Alfred's little army slowly began to gather at Athelney, the king himself set out to penetrate the camp of Guthrum, the commander of the Danish invaders.","zh":"当阿尔弗雷德的小部队在阿瑟尔尼缓慢集结时，国王亲自出发，潜入丹麦入侵者指挥官古特伦的营地。","t":49.17},{"en":"These had settled down for the winter at Chippenham: thither Alfred went.","zh":"他们在奇彭纳姆安顿下来过冬，阿尔弗雷德也去了那里。","t":62.26},{"en":"He noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual.","zh":"他立刻注意到纪律松懈：丹麦人有征服者的自信，他们的安全防范措施很随意。","t":69.32},{"en":"They lived well, on the proceeds of raids on neighbouring regions.","zh":"他们靠掠夺邻近地区的收益过着富裕的生活。","t":81.06},{"en":"There they collected women as well as food and drink, and a life of ease had made them soft.","zh":"他们在那里搜罗了妇女、食物和饮料，安逸的生活使他们变得软弱。","t":86.77},{"en":"Alfred stayed in the camp a week before he returned to Athelney.","zh":"阿尔弗雷德在营地待了一周才返回阿瑟尔尼。","t":94.89},{"en":"The force there assembled was trivial compared with the Danish horde.","zh":"在那里集结的部队与丹麦大军相比微不足道。","t":100.13},{"en":"But Alfred had deduced that the Danes were no longer fit for prolonged battle: and that their commissariat had no organization, but depended on irregular raids.","zh":"但阿尔弗雷德推断丹麦人已不再适合持久战，而且他们的军需供应没有组织，只依赖于不规律的突袭。","t":105.12},{"en":"So, faced with the Danish advance, Alfred did not risk open battle but harried the enemy.","zh":"因此，面对丹麦人的进攻，阿尔弗雷德没有冒险进行公开战斗，而是骚扰敌人。","t":118.52},{"en":"He was constantly on the move, drawing the Danes after him.","zh":"他不断移动，将丹麦人吸引到他身后。","t":126.57},{"en":"His patrols halted the raiding parties: hunger assailed the Danish army.","zh":"他的巡逻队阻止了突袭队伍：饥饿侵袭着丹麦军队。","t":131.58},{"en":"Now Alfred began a long series of skirmishes -- and within a month the Danes had surrendered.","zh":"接着，阿尔弗雷德开始了一系列漫长的遭遇战——一个月内丹麦人就投降了。","t":137.97},{"en":"The episode could reasonably serve as a unique epic of royal espionage!","zh":"这一事件完全可以作为一场独特的王室谍报史诗！","t":145.74}],"vocab":[{"word":"espionage","phonetic":"/ˈespiənɑːʒ/","meanings":[{"pos":"noun","meaning":"间谍活动；谍报活动","usage":"不可数名词，正式用语，指获取敌方情报的秘密活动"}]},{"word":"penetrate","phonetic":"/ˈpenətreɪt/","meanings":[{"pos":"verb","meaning":"渗入；潜入；穿透","usage":"可作及物/不及物动词，指进入某地或被允许进入某个组织/团体"}]},{"word":"disguise","phonetic":"/dɪsˈɡaɪz/","meanings":[{"pos":"verb","meaning":"假扮；伪装；掩饰","usage":"常用搭配：disguise sb as sth 把某人伪装成某物"}]},{"word":"minstrel","phonetic":"/ˈmɪnstrəl/","meanings":[{"pos":"noun","meaning":"(中世纪的)游吟歌手","usage":"指中世纪四处游历，通过演唱、表演为生的艺人"}]},{"word":"ballad","phonetic":"/ˈbæləd/","meanings":[{"pos":"noun","meaning":"民歌；民谣；叙事歌谣","usage":"通常指讲述故事的慢节奏歌曲或诗歌"}]},{"word":"acrobatic","phonetic":"/ˌækrəˈbætɪk/","meanings":[{"pos":"adjective","meaning":"杂技的；杂技演员的","usage":"用于描述和杂技相关的动作、技能或表演"}]},{"word":"conjuring","phonetic":"/ˈkʌndʒərɪŋ/","meanings":[{"pos":"noun","meaning":"魔术；变戏法","usage":"不可数名词，指通过技巧表演幻象、魔术的行为"}]},{"word":"slack","phonetic":"/slæk/","meanings":[{"pos":"adjective","meaning":"松懈的；懈怠的；松弛的","usage":"可形容纪律、管理松散，也可形容绳子等物品不紧"}]},{"word":"proceeds","phonetic":"/ˈprəʊsiːdz/","meanings":[{"pos":"noun","meaning":"(活动或售卖的)收入，收益","usage":"复数名词，通常指某一事件、交易获得的全部收入"}]},{"word":"raid","phonetic":"/reɪd/","meanings":[{"pos":"noun","meaning":"突袭；抢劫；搜查","usage":"可指军事突袭，也可指警方的突击搜查或盗贼的抢劫"}]},{"word":"assemble","phonetic":"/əˈsembl/","meanings":[{"pos":"verb","meaning":"集合；聚集；组装","usage":"可指人集合，也可指组装物品，及物不及物均可"}]},{"word":"trivial","phonetic":"/ˈtrɪviəl/","meanings":[{"pos":"adjective","meaning":"微不足道的；不重要的","usage":"用于形容事物价值、规模小到不值得重视"}]},{"word":"horde","phonetic":"/hɔːd/","meanings":[{"pos":"noun","meaning":"(人)群；游牧部落","usage":"通常指数量庞大、移动中的人群，可带有贬义"}]},{"word":"harry","phonetic":"/ˈhæri/","meanings":[{"pos":"verb","meaning":"不断袭击；骚扰；烦扰","usage":"指反复攻击、打扰某人或某物，使其不得安宁"}]},{"word":"skirmish","phonetic":"/ˈskɜːmɪʃ/","meanings":[{"pos":"noun","meaning":"小规模战斗；小冲突","usage":"指战争中双方小规模的、非正式的交锋"}]}],"phrases":[{"phrase":"disguised as","usage":"表示“伪装成”，常用作伴随状语，说明主语的状态","examples":[{"en":"He disguised himself as a delivery man to get into the building.","zh":"他伪装成快递员进入了那栋大楼。"}]},{"phrase":"settle down","usage":"此处表示“定居；安顿下来”，也可指“平静下来；安定下来过稳定生活”","examples":[{"en":"After travelling for years, he decided to settle down in the countryside.","zh":"游历多年后，他决定在乡村定居下来。"}]},{"phrase":"security precautions","usage":"名词短语，意为“安全防范措施”，可搭配take/adopt等动词使用","examples":[{"en":"The airport has strengthened security precautions ahead of the holiday.","zh":"假期来临前，机场加强了安全防范措施。"}]},{"phrase":"compared with","usage":"介词短语，意为“与……相比”，常用于句首或句中作比较状语","examples":[{"en":"Compared with last year, our sales have increased by 30% this year.","zh":"和去年相比，我们今年的销售额增长了30%。"}]},{"phrase":"be fit for","usage":"表示“适合；能胜任”，后接名词或动名词，说明主语的适用性","examples":[{"en":"This key is not fit for the front door, you must have taken the wrong one.","zh":"这把钥匙不适合前门，你肯定拿错了。"}]},{"phrase":"depend on","usage":"动词短语，意为“依赖；依靠；取决于”，后接名词、代词或从句","examples":[{"en":"Whether we will go hiking tomorrow depends on the weather.","zh":"我们明天是否去远足取决于天气。"}]},{"phrase":"be faced with","usage":"表示“面对；面临”，主语通常是人或组织，后接困难、问题等对象","examples":[{"en":"When faced with difficulties, we should try to find solutions instead of complaining.","zh":"面对困难时，我们应该努力寻找解决方法，而不是抱怨。"}]},{"phrase":"on the move","usage":"固定表达，意为“在行进中；在移动中；忙个不停”","examples":[{"en":"As a sales manager, she is always on the move, visiting different cities every week.","zh":"作为销售经理，她总是忙个不停，每周都要去不同的城市。"}]},{"phrase":"a series of","usage":"表示“一系列；一连串”，后接可数名词复数，整体作主语时谓语动词用单数","examples":[{"en":"The school has launched a series of activities to promote traditional culture.","zh":"学校推出了一系列活动来推广传统文化。"}]},{"phrase":"serve as","usage":"动词短语，意为“充当；担任；起……作用”，说明事物的功能或角色","examples":[{"en":"The old sofa in the study can serve as a temporary bed for guests.","zh":"书房里的旧沙发可以充当临时床供客人使用。"}]}],"grammar":[{"title":"过去分词作伴随状语","definition":"过去分词和句子主语构成被动关系，用来补充说明主语的状态，可放在句首或句中，用逗号和主句隔开","structure":"主语 + 谓语 + ... , + 过去分词短语 / 过去分词短语 , + 主语 + 谓语 + ...","usage":"用于简化从句，使句子更简洁，同时说明主语的伴随状态、背景信息等","examples":[{"en":"Alfred the Great acted as his own spy, visiting Danish camps disguised as a minstrel.","zh":"阿尔弗雷德大帝亲自充当间谍，扮作游吟歌手探访丹麦人的营地。"},{"en":"Seen from the top of the mountain, the village looks very small.","zh":"从山顶上看，这个村庄显得非常小。"}]},{"title":"宾语从句（deduce后接并列宾语从句）","definition":"在及物动词后作宾语的从句，当动词后有两个及以上的并列宾语从句时，第二个及之后的that通常不能省略","structure":"主语 + 及物动词 + that + 从句1 + and + that + 从句2","usage":"用于表达通过推理、判断等得出的多个结论，使逻辑更清晰","examples":[{"en":"But Alfred had deduced that the Danes were no longer fit for prolonged battle: and that their commissariat had no organization, but depended on irregular raids.","zh":"但是阿尔弗雷德推断，丹麦人已经不再适合持久战：而且他们的后勤没有组织，全靠不定期的劫掠维持。"},{"en":"The survey shows that most citizens are satisfied with the public transport, and that they hope more bike lanes will be built.","zh":"调查显示，大多数市民对公共交通感到满意，并且他们希望能修建更多的自行车道。"}]}],"patterns":[{"pattern":"While + 从句（进行/延续性动作）, 主句","explanation":"","original":{"en":"While Alfred's little army slowly began to gather at Athelney, the king himself set out to penetrate the camp of Guthrum, the commander of the Danish invaders.","zh":"当阿尔弗雷德的小部队在阿特尔尼慢慢集结的时候，国王本人则出发潜入了丹麦入侵者指挥官古瑟伦的营地。"},"examples":[{"en":"While the students are busy preparing for the final exam, the teachers are working hard to arrange the examination room.","zh":"当学生们忙着准备期末考试的时候，老师们也在努力布置考场。"},{"en":"While my mother was cooking in the kitchen, my father was tidying up the living room.","zh":"当我妈妈在厨房做饭的时候，我爸爸正在整理客厅。"}]},{"pattern":"主语 + noticed at once that + 宾语从句","explanation":"","original":{"en":"He noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual.","zh":"他立刻注意到那里纪律松懈：丹麦人有着征服者的自信，他们的安全防范非常随意。"},"examples":[{"en":"When she entered the office, she noticed at once that the atmosphere was very tense.","zh":"她走进办公室的时候，立刻注意到气氛非常紧张。"},{"en":"I noticed at once that he was upset, so I went over to ask what had happened.","zh":"我立刻注意到他心情不好，于是走过去问发生了什么事。"}]},{"pattern":"So, faced with + 名词, 主语 + did not do sth but did sth","explanation":"","original":{"en":"So, faced with the Danish advance, Alfred did not risk open battle but harried the enemy.","zh":"因此，面对丹麦人的进攻，阿尔弗雷德没有冒险打正面战，而是不断骚扰敌军。"},"examples":[{"en":"So, faced with the challenge of the new project, we did not give up easily but tried our best to find a solution.","zh":"因此，面对新项目的挑战，我们没有轻易放弃，而是尽全力寻找解决方案。"},{"en":"Faced with his misunderstanding, she did not argue with him but explained the whole thing calmly.","zh":"面对他的误解，她没有和他争吵，而是冷静地解释了整件事。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“假扮；伪装；掩饰” 对应的单词是？","hint":"verb · /dɪsˈɡaɪz/","options":["assign","conceive","submarine","disguise"],"answer":3,"explain":"disguise · /dɪsˈɡaɪz/ · verb · 假扮；伪装；掩饰。常用搭配：disguise sb as sth 把某人伪装成某物","source":{"kind":"vocab","word":"disguise"},"id":"b4-u09-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：民歌；民谣；叙事歌谣","hint":"/ˈbæləd/ · noun","answer":"ballad","placeholder":"输入英文单词","explain":"ballad · /ˈbæləd/ · noun · 民歌；民谣；叙事歌谣。通常指讲述故事的慢节奏歌曲或诗歌","source":{"kind":"vocab","word":"ballad"},"id":"b4-u09-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：As a sales manager, she is always _____, visiting different cities every week.","hint":"作为销售经理，她总是忙个不停，每周都要去不同的城市。","answer":"on the move","placeholder":"输入缺失的短语","explain":"on the move：固定表达，意为“在行进中；在移动中；忙个不停”（作为销售经理，她总是忙个不停，每周都要去不同的城市。）","source":{"kind":"phrase","phrase":"on the move"},"id":"b4-u09-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：There they collected women as _____ as food and drink, and a life of ease had made them soft.","hint":"他们在那里搜罗了妇女、食物和饮料，安逸的生活使他们变得软弱。","answer":"well","placeholder":"输入缺失的单词","explain":"There they collected women as well as food and drink, and a life of ease had made them soft. — 他们在那里搜罗了妇女、食物和饮料，安逸的生活使他们变得软弱。","source":{"kind":"sentence","en":"There they collected women as well as food and drink, and a life of ease had made them soft."},"id":"b4-u09-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“过去分词和句子主语构成被动关系，用来补充说明主语的状态，可放在句首或句中，用逗号和主句隔开” 描述的是哪个语法点？","hint":"主语 + 谓语 + ... , + 过去分词短语 / 过去分词短语 , + 主语 + 谓语 + ...","options":["as引导的比例状语从句","过去分词作伴随状语","定语从句 (Attributive Clause)","not...but... 并列结构"],"answer":1,"explain":"过去分词作伴随状语：主语 + 谓语 + ... , + 过去分词短语 / 过去分词短语 , + 主语 + 谓语 + ...：用于简化从句，使句子更简洁，同时说明主语的伴随状态、背景信息等","source":{"kind":"grammar","title":"过去分词作伴随状语"},"id":"b4-u09-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nHe noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual.","hint":"","options":["但如果一个国家是分裂的，政府就不能确定人民的行为是否符合国家利益；","他立刻注意到纪律松懈：丹麦人有征服者的自信，他们的安全防范措施很随意。","他向银行提供他的签名样本，并且有一条非常明确的规定：","如果我们回想起在他那个时代，就像几个世纪以前一样，曲面玻璃是制造幻觉、谎言而非真相的流行手段；"],"answer":1,"explain":"He noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual. — 他立刻注意到纪律松懈：丹麦人有征服者的自信，他们的安全防范措施很随意。","source":{"kind":"sentence","en":"He noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual."},"id":"b4-u09-q06"}]},{"id":"b4-u10","book":4,"unit":10,"key":"10","lessonFrom":10,"lessonTo":10,"title":"Silicon Valley","titleZh":"硅谷","question":"What does the computer industry thrive on apart from anarchy?","sentences":[{"en":"Technology trends may push Silicon Valley back to the future.","zh":"技术趋势可能将硅谷推向未来。","t":14.59},{"en":"Carver Mead, a pioneer in integrated circuits and a professor of computer science at the California Institute of Technology, notes there are now workstations that enable engineers to design, test and produce chips right on their desks, much the way and editor creates a newsletter on a Macintosh.","zh":"加州理工学院的集成电路先驱、计算机科学教授卡弗·米德指出，现在工程师可以在他们的办公桌上设计、测试和生产芯片，就像编辑在Macintosh上创建新闻通讯一样。","t":19.04},{"en":"As the time and cost of making a chip drop to a few days and a few hundred dollars, engineers may soon be free to let their imaginations soar without being penalized by expensive failures.","zh":"随着芯片制造的时间和成本降至几天和几百美元，工程师们可能很快就能自由发挥想象力，而不会因昂贵的失败而受到惩罚。","t":41.88},{"en":"Mead predicts that inventors will be able to perfect powerful customized chips over a weekend at the office --","zh":"米德预测，发明家将能够在办公室里用一个周末的时间完善功能强大的定制芯片——","t":55.03},{"en":"spawning a new generation of garage start-ups and giving the U. S. a jump on its foreign rivals in getting new products to market fast.","zh":"催生新一代的“车库创业公司”，并使美国在将新产品快速推向市场方面超越其外国竞争对手。","t":62.31},{"en":"'We've got more garages with smart people,' Mead observes. 'We really thrive on anarchy.'","zh":"米德观察道：“我们有更多拥有聪明人的车库。”“我们确实在无序状态中茁壮成长。”","t":73.1},{"en":"And on Asians. Already, orientals and Asian Americans constitute the majority of the engineering staffs at many Valley firms.","zh":"还有亚洲人。在许多硅谷公司，东方人和亚裔美国人已经构成了工程技术人员的大多数。","t":80.92},{"en":"And Chinese, Korean, Filipino and Indian engineers are graduating in droves from California's colleges.","zh":"中国、韩国、菲律宾和印度的工程师正从加州的大学里大量毕业。","t":91.09},{"en":"As the heads of next-generation start-ups, these Asian innovators can draw on customs and languages to forge tighter links with crucial Pacific Rim markets.","zh":"作为下一代创业公司的负责人，这些亚洲创新者可以利用习俗和语言与关键的环太平洋市场建立更紧密的联系。","t":100.09},{"en":"For instance, Alex Au, a Stanford Ph. D. from Hong Kong, has set up a Taiwan factory to challenge Japan's near lock on the memory-chip market.","zh":"例如，来自香港的斯坦福大学博士Alex Au在台湾设立了一家工厂，以挑战日本在内存芯片市场近乎垄断的地位。","t":112.17},{"en":"India-born N. Damodar Reddy's tiny California company reopened an AT&T chip plant in Kansas City last spring with financing from the state of Missouri.","zh":"去年春天，印度出生的N. Damodar Reddy在密苏里州的资助下，他那小小的加州公司在堪萨斯城重新启用了一家AT&T芯片工厂。","t":124.52},{"en":"Before it becomes a retirement village, Silicon Valley may prove a classroom for building a global business.","zh":"在它成为一个退休村之前，硅谷可能会成为一个建立全球业务的课堂。","t":137.26}],"vocab":[{"word":"thrive","phonetic":"/θraɪv/","meanings":[{"pos":"verb","meaning":"繁荣，兴旺，蓬勃发展","usage":"不及物动词，常与介词on搭配，表示“靠……繁荣发展”"}]},{"word":"anarchy","phonetic":"/ˈænəki/","meanings":[{"pos":"noun","meaning":"无政府状态，混乱无序","usage":"不可数名词，此处指硅谷宽松自由、不受过多规则约束的创新环境"}]},{"word":"integrated","phonetic":"/ˈɪntɪɡreɪtɪd/","meanings":[{"pos":"adjective","meaning":"集成的，综合的，完整统一的","usage":"常用于科技领域，如integrated circuit即“集成电路”"}]},{"word":"workstation","phonetic":"/ˈwɜːksteɪʃn/","meanings":[{"pos":"noun","meaning":"工作站","usage":"可数名词，指供专业人员使用的高性能计算机"}]},{"word":"penalize","phonetic":"/ˈpiːnəlaɪz/","meanings":[{"pos":"verb","meaning":"处罚，使处于不利地位，损害","usage":"及物动词，常用被动语态be penalized by表示“受到……的不利影响”"}]},{"word":"soar","phonetic":"/sɔː(r)/","meanings":[{"pos":"verb","meaning":"翱翔，猛增，放飞","usage":"不及物动词，此处指想象力不受限制地自由发挥"}]},{"word":"customized","phonetic":"/ˈkʌstəmaɪzd/","meanings":[{"pos":"adjective","meaning":"定制的，个性化的","usage":"可修饰产品、服务等，表示根据特定需求制作的"}]},{"word":"spawn","phonetic":"/spɔːn/","meanings":[{"pos":"verb","meaning":"催生，产生，引起","usage":"及物动词，通常指催生大量新事物、新现象"}]},{"word":"rival","phonetic":"/ˈraɪvl/","meanings":[{"pos":"noun","meaning":"竞争对手，敌手","usage":"可数名词，常与介词in/for搭配，表示某领域的对手"}]},{"word":"oriental","phonetic":"/ˌɔːriˈentl/","meanings":[{"pos":"noun","meaning":"东方人（尤指东亚人）","usage":"该词现在稍显过时，日常多用Asian指代亚洲人"}]},{"word":"constitute","phonetic":"/ˈkɒnstɪtjuːt/","meanings":[{"pos":"verb","meaning":"组成，构成，占","usage":"及物动词，主语为组成部分，宾语为整体，不用于被动语态"}]},{"word":"drove","phonetic":"/drəʊv/","meanings":[{"pos":"noun","meaning":"人群，畜群","usage":"常用复数形式droves，in droves表示“成群结队地，大量地”"}]},{"word":"innovator","phonetic":"/ˈɪnəveɪtə(r)/","meanings":[{"pos":"noun","meaning":"创新者，革新者","usage":"可数名词，指引入新事物、新方法的人"}]},{"word":"forge","phonetic":"/fɔːdʒ/","meanings":[{"pos":"verb","meaning":"锻造，建立，缔造","usage":"及物动词，常搭配link/relationship/partnership等词，表示建立牢固的关系"}]},{"word":"crucial","phonetic":"/ˈkruːʃl/","meanings":[{"pos":"adjective","meaning":"至关重要的，关键的","usage":"可修饰名词，或用于it is crucial that/to do结构中"}]}],"phrases":[{"phrase":"thrive on","usage":"动词短语，表示“靠……蓬勃发展，因……而兴旺”，主语通常为企业、组织或人，后接名词或动名词","examples":[{"en":"Many tech companies thrive on constant innovation.","zh":"许多科技公司靠持续的创新蓬勃发展。"},{"en":"He thrives on pressure and always performs best in challenging situations.","zh":"他在压力下状态很好，总是在有挑战的环境中表现最佳。"}]},{"phrase":"back to the future","usage":"固定表达，字面意思为“回到未来”，常指事物的发展在新的条件下重现过去的模式或特点","examples":[{"en":"The popularity of vinyl records is like a back to the future moment for the music industry.","zh":"黑胶唱片的流行对音乐行业来说就像是“回到未来”的时刻。"},{"en":"The new policy takes us back to the future, reviving the small business support schemes from the 1990s.","zh":"新政策让我们仿佛回到了未来，重启了上世纪90年代的小企业扶持计划。"}]},{"phrase":"much the way","usage":"连词短语，意为“就像……一样”，用于引导方式状语从句，类比两种相似的行为或情况","examples":[{"en":"You can adjust the settings of the software, much the way you customize your phone's home screen.","zh":"你可以调整这个软件的设置，就像你定制手机主屏幕一样。"},{"en":"The team works together to solve problems, much the way a family supports each other.","zh":"这个团队协作解决问题，就像一家人互相支持一样。"}]},{"phrase":"in droves","usage":"副词短语，意为“成群结队地，大量地”，修饰动词，表示人或事物大规模地出现或行动","examples":[{"en":"Tourists come to this coastal city in droves every summer.","zh":"每年夏天都有大量游客来到这座海滨城市。"},{"en":"Residents left the earthquake-stricken area in droves to seek safer shelter.","zh":"居民们成群结队地离开地震灾区，寻找更安全的避难所。"}]},{"phrase":"draw on","usage":"动词短语，意为“利用，凭借，依靠”，宾语通常为经验、知识、资源等抽象事物","examples":[{"en":"She drew on her childhood experiences to write the novel.","zh":"她凭借自己的童年经历创作了这本小说。"},{"en":"The project draws on the latest research in environmental science.","zh":"这个项目利用了环境科学领域的最新研究成果。"}]},{"phrase":"Pacific Rim","usage":"专有名词短语，意为“环太平洋地区”，指环太平洋沿岸的所有国家和地区，常用于经济、贸易语境","examples":[{"en":"Trade between Pacific Rim countries has increased significantly over the past decade.","zh":"过去十年间，环太平洋国家之间的贸易额大幅增长。"},{"en":"This summit focuses on sustainable development issues in the Pacific Rim.","zh":"本次峰会聚焦环太平洋地区的可持续发展问题。"}]},{"phrase":"lock on","usage":"名词短语，意为“垄断，牢牢控制”，常与介词on搭配，表示对某个市场、领域的绝对控制","examples":[{"en":"The company has a near lock on the global smartphone processor market.","zh":"这家公司几乎垄断了全球智能手机处理器市场。"},{"en":"Local businesses are trying to break the foreign brand's lock on the luxury goods market.","zh":"本土企业正试图打破外国品牌对奢侈品市场的垄断。"}]},{"phrase":"start-up","usage":"可数名词，意为“初创企业，新成立的公司”，尤指科技领域的新兴创业公司","examples":[{"en":"Many start-ups in this city have received investment from venture capital firms.","zh":"这座城市的很多初创企业都获得了风险投资公司的投资。"},{"en":"He quit his stable job to join a start-up focused on artificial intelligence.","zh":"他辞去了稳定的工作，加入了一家专注于人工智能的初创公司。"}]}],"grammar":[{"title":"方式状语从句：much the way引导的类比结构","definition":"用于比较两种动作或情况的相似性，说明主句的行为和从句的行为在方式上高度相似，相当于“就像……一样”","structure":"主句 + much the way + 从句（完整句子）","usage":"常用于说明文、议论文中，通过读者熟悉的场景解释不熟悉的概念，让表达更通俗易懂","examples":[{"en":"Carver Mead notes there are now workstations that enable engineers to design, test and produce chips right on their desks, much the way an editor creates a newsletter on a Macintosh.","zh":"卡弗·米德指出，现在的工作站能让工程师直接在自己的桌面上设计、测试和生产芯片，就像编辑在苹果电脑上制作时事通讯一样。"},{"en":"Teachers can use interactive tools to deliver online courses, much the way they teach in physical classrooms.","zh":"教师可以使用互动工具开展线上课程，就像他们在实体教室里授课一样。"}]},{"title":"as引导的原因/伴随状语从句","definition":"as在这里表示“随着，由于”，既可以说明主句动作发生的背景，也可以表示因果关系，从句的动作和主句的动作往往同时发生","structure":"As + 从句（主语+谓语）, + 主句","usage":"常用于描述某种趋势、变化带来的结果，从句描述前提或背景，主句描述随之产生的现象","examples":[{"en":"As the time and cost of making a chip drop to a few days and a few hundred dollars, engineers may soon be free to let their imaginations soar without being penalized by expensive failures.","zh":"随着制造芯片的时间缩短到几天，成本降到几百美元，工程师们很快就能尽情放飞想象力，不会因为失败成本高昂而受到限制。"},{"en":"As renewable energy technology becomes more affordable, more households are choosing to install solar panels on their roofs.","zh":"随着可再生能源技术的成本越来越低，更多家庭选择在屋顶安装太阳能板。"}]},{"title":"现在分词作结果状语","definition":"现在分词短语放在句末，前面用破折号或逗号隔开，用来表示主句动作产生的自然而然的结果，其逻辑主语就是主句的主语","structure":"主句 + ,/-- + 现在分词短语","usage":"可以避免使用多个独立短句，让句子结构更紧凑，逻辑更连贯","examples":[{"en":"Mead predicts that inventors will be able to perfect powerful customized chips over a weekend at the office -- spawning a new generation of garage start-ups and giving the U.S. a jump on its foreign rivals in getting new products to market fast.","zh":"米德预测，发明者们在办公室花一个周末就能做出完美的高性能定制芯片，这会催生新一代的车库初创企业，让美国在快速将新产品推向市场方面领先于外国竞争对手。"},{"en":"The new subway line has been put into use, greatly reducing the travel time between the two districts.","zh":"新的地铁线路已经投入使用，大大缩短了两个区之间的通勤时间。"}]}],"patterns":[{"pattern":"A predicts that 从句 -- spawning B and giving C a jump on D in (doing) sth","explanation":"","original":{"en":"Mead predicts that inventors will be able to perfect powerful customized chips over a weekend at the office -- spawning a new generation of garage start-ups and giving the U. S. a jump on its foreign rivals in getting new products to market fast.","zh":"米德预测，发明者们在办公室花一个周末就能做出完美的高性能定制芯片，这会催生新一代的车库初创企业，让美国在快速将新产品推向市场方面领先于外国竞争对手。"},"examples":[{"en":"Industry analysts predict that the new 5G technology will be widely applied in rural areas -- spawning a wave of digital agricultural innovations and giving domestic farmers a jump on their foreign counterparts in improving production efficiency.","zh":"行业分析师预测，新的5G技术将在农村地区广泛应用，这会催生一波数字农业创新浪潮，让国内农民在提升生产效率方面领先于国外同行。"},{"en":"Education experts predict that the new online learning platform will be promoted nationwide -- spawning a variety of personalized teaching modes and giving students in remote areas a jump on their peers in accessing high-quality educational resources.","zh":"教育专家预测，这个新的线上学习平台将在全国推广，这会催生多种个性化教学模式，让偏远地区的学生在获取优质教育资源方面领先于同龄人。"}]},{"pattern":"For instance, 人物身份 + 姓名, has done sth to challenge sb's near lock on sth","explanation":"","original":{"en":"For instance, Alex Au, a Stanford Ph. D. from Hong Kong, has set up a Taiwan factory to challenge Japan's near lock on the memory-chip market.","zh":"例如，来自香港的斯坦福博士欧德宁已经在台湾设立了一家工厂，挑战日本对存储芯片市场近乎垄断的地位。"},"examples":[{"en":"For instance, Li Ming, a Tsinghua graduate from Hunan, has launched a new energy battery brand to challenge foreign companies' near lock on the power battery market.","zh":"例如，来自湖南的清华毕业生李明推出了一个新的能源电池品牌，挑战外国企业对动力电池市场近乎垄断的地位。"},{"en":"For instance, Wang Jia, a designer who returned from studying abroad, has created a series of original domestic cosmetics to challenge international luxury brands' near lock on the high-end beauty market.","zh":"例如，留学归来的设计师王佳创作了一系列原创国货彩妆，挑战国际奢侈品牌对高端美妆市场近乎垄断的地位。"}]},{"pattern":"Before it becomes sth, 某事物 may prove sth for (doing) sth","explanation":"","original":{"en":"Before it becomes a retirement village, Silicon Valley may prove a classroom for building a global business.","zh":"在硅谷变成退休村之前，它或许会成为打造全球商业的课堂。"},"examples":[{"en":"Before the old industrial area becomes a commercial complex, it may prove a creative base for young artists to display their works.","zh":"在这片老工业区变成商业综合体之前，它或许会成为年轻艺术家展示作品的创意基地。"},{"en":"Before the traditional paper book is completely replaced by e-books, it may prove an important carrier for passing on cultural memories for future generations.","zh":"在传统纸质书被电子书完全取代之前，它或许会成为为后代传递文化记忆的重要载体。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“催生，产生，引起” 对应的单词是？","hint":"verb · /spɔːn/","options":["spawn","competitive","convulsive","rotate"],"answer":0,"explain":"spawn · /spɔːn/ · verb · 催生，产生，引起。及物动词，通常指催生大量新事物、新现象","source":{"kind":"vocab","word":"spawn"},"id":"b4-u10-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：集成的，综合的，完整统一的","hint":"/ˈɪntɪɡreɪtɪd/ · adjective","answer":"integrated","placeholder":"输入英文单词","explain":"integrated · /ˈɪntɪɡreɪtɪd/ · adjective · 集成的，综合的，完整统一的。常用于科技领域，如integrated circuit即“集成电路”","source":{"kind":"vocab","word":"integrated"},"id":"b4-u10-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Many tech companies _____ constant innovation.","hint":"许多科技公司靠持续的创新蓬勃发展。","answer":"thrive on","placeholder":"输入缺失的短语","explain":"thrive on：动词短语，表示“靠……蓬勃发展，因……而兴旺”，主语通常为企业、组织或人，后接名词或动名词（许多科技公司靠持续的创新蓬勃发展。）","source":{"kind":"phrase","phrase":"thrive on"},"id":"b4-u10-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Technology trends may _____ Silicon Valley back to the future.","hint":"技术趋势可能将硅谷推向未来。","answer":"push","placeholder":"输入缺失的单词","explain":"Technology trends may push Silicon Valley back to the future. — 技术趋势可能将硅谷推向未来。","source":{"kind":"sentence","en":"Technology trends may push Silicon Valley back to the future."},"id":"b4-u10-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于比较两种动作或情况的相似性，说明主句的行为和从句的行为在方式上高度相似，相当于“就像……一样”” 描述的是哪个语法点？","hint":"主句 + much the way + 从句（完整句子）","options":["强调句","be型虚拟语气在让步状语从句中的用法","the + 比较级，the + 比较级结构","方式状语从句：much the way引导的类比结构"],"answer":3,"explain":"方式状语从句：much the way引导的类比结构：主句 + much the way + 从句（完整句子）：常用于说明文、议论文中，通过读者熟悉的场景解释不熟悉的概念，让表达更通俗易懂","source":{"kind":"grammar","title":"方式状语从句：much the way引导的类比结构"},"id":"b4-u10-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\n'We've got more garages with smart people,' Mead observes. 'We really thrive on anarchy.'","hint":"","options":["米德观察道：“我们有更多拥有聪明人的车库。”“我们确实在无序状态中茁壮成长。”","当阿尔弗雷德的小部队在阿瑟尔尼缓慢集结时，国王亲自出发，潜入丹麦入侵者指挥官古特伦的营地。","有些蛇产生的毒液与另一些蛇的毒液在各个方面都不同，","合理猜测，他们平均可能在100光年之外。"],"answer":0,"explain":"'We've got more garages with smart people,' Mead observes. 'We really thrive on anarchy.' — 米德观察道：“我们有更多拥有聪明人的车库。”“我们确实在无序状态中茁壮成长。”","source":{"kind":"sentence","en":"'We've got more garages with smart people,' Mead observes. 'We really thrive on anarchy.'"},"id":"b4-u10-q06"}]},{"id":"b4-u11","book":4,"unit":11,"key":"11","lessonFrom":11,"lessonTo":11,"title":"How to Grow Old","titleZh":"如何安度晚年","question":"What, according to the author, is the best way to overcome the fear of death as you get older?","sentences":[{"en":"Some old people are oppressed by the fear of death.","zh":"有些老年人害怕死亡。","t":20.22},{"en":"In the young there is a justification for this feeling.","zh":"这种情绪如果发生在年轻人身上，是情有可原的。","t":25.14},{"en":"Young men who have reason to fear that they will be killed in battle","zh":"青年人有理由担心他们会战死沙场，","t":28.83},{"en":"may justifiably feel bitter in the thought","zh":"想到他们没有享受到人生最美好的东西，","t":33.24},{"en":"that they have been cheated of the best things that life has to offer.","zh":"因而感到痛苦，这也是情有可原的。","t":36.79},{"en":"But in an old man who has known human joys and sorrows,","zh":"但是，一个已经尝过人间甘苦的老人，","t":42.45},{"en":"and has achieved whatever work it was in him to do,","zh":"并且已经做完了他力所能及的一切工作，","t":48.12},{"en":"the fear of death is somewhat abject and ignoble.","zh":"如果他仍然害怕死亡，那就有几分可怜又可鄙了。","t":52.01},{"en":"The best way to overcome it--so at least it seems to me--","zh":"克服这种恐惧的最好办法——至少在我看来是如此——","t":56.93},{"en":"is to make your interests gradually wider and more impersonal,","zh":"是使你的兴趣逐渐扩大，变得更加超然物外，","t":62.67},{"en":"until bit by bit the walls of the ego recede,","zh":"直到自我的界限一点点地消退，","t":68.05},{"en":"and your life becomes increasingly merged in the universal life.","zh":"你的生命越来越融入到普遍的生命之中。","t":73.22},{"en":"An individual human existence should be like a river--","zh":"人的个体生命应该像一条河流——","t":77.73},{"en":"small at first, narrowly contained within its banks,","zh":"最初很小，被狭窄的河岸限制着，","t":83.51},{"en":"and rushing passionately past boulders and over waterfalls.","zh":"汹涌地冲过巨石，飞跃瀑布。","t":88.42},{"en":"Gradually the river grows wider, the banks recede, the waters flow more quietly,","zh":"渐渐地，河流变得宽阔，河岸后退，水流也变得更加平静，","t":93.7},{"en":"and in the end, without any visiblebreak, they become merged in the sea,","zh":"最终，在没有任何明显的断裂的情况下，它们汇入了大海，","t":101.18},{"en":"and painlessly lose their individual being.","zh":"并且毫无痛苦地失去了它们的个体存在。","t":107.44},{"en":"The man who, in old age can see his life in this way,","zh":"那些年老时能以这种方式看待自己生命的人，","t":111.19},{"en":"will not suffer from the fear of death,","zh":"将不会受到对死亡的恐惧的折磨，","t":116.77},{"en":"since the things he cares for will continue.","zh":"因为他所珍视的一切将会继续存在。","t":119.54},{"en":"And if, with the decay of vitality, weariness increases,","zh":"而且，如果随着活力的衰退，疲劳感增加，","t":123.38},{"en":"the thought of rest will be not unwelcome.","zh":"休息的念头将不会令人不快。","t":130.52},{"en":"I should wish to die while still at work,","zh":"我希望在工作时死去，","t":134.29},{"en":"knowing that others will carry on what I can no longer do,","zh":"知道别人会继续我无法再做的事情，","t":137.82},{"en":"and content in the thought that what was possible has been done.","zh":"并满意地想到，所有可能做的事情都已经完成了。","t":142.36}],"vocab":[{"word":"oppress","phonetic":"/əˈpres/","meanings":[{"pos":"verb","meaning":"使压抑，使烦恼；压迫，欺压","usage":"常用被动语态be oppressed by表示“被……困扰、压迫”"}]},{"word":"justification","phonetic":"/ˌdʒʌstɪfɪˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"正当理由，合理性","usage":"后常接for sth/doing sth表示“做某事的正当理由”"}]},{"word":"justifiably","phonetic":"/ˈdʒʌstɪfaɪəbli/","meanings":[{"pos":"adverb","meaning":"有正当理由地，无可非议地","usage":"修饰动词、形容词，说明行为或感受的合理性"}]},{"word":"bitter","phonetic":"/ˈbɪtə(r)/","meanings":[{"pos":"adjective","meaning":"痛苦的，愤愤不平的；苦的","usage":"可形容人的感受、经历或味道，后常接at/about sth表示“因某事不快”"}]},{"word":"abject","phonetic":"/ˈæbdʒekt/","meanings":[{"pos":"adjective","meaning":"可鄙的，卑劣的；凄惨的","usage":"用于形容行为、处境或状态的糟糕或不光彩"}]},{"word":"ignoble","phonetic":"/ɪɡˈnəʊbl/","meanings":[{"pos":"adjective","meaning":"不光彩的，卑劣的","usage":"正式用词，与noble（高尚的）语义相反，形容品格或行为"}]},{"word":"impersonal","phonetic":"/ɪmˈpɜːsənl/","meanings":[{"pos":"adjective","meaning":"不受个人情感影响的，客观的；非个人的","usage":"前缀im-表否定，对应personal（个人的，主观的）"}]},{"word":"ego","phonetic":"/ˈiːɡəʊ/","meanings":[{"pos":"noun","meaning":"自我，自我意识","usage":"心理学常用术语，也可日常表示“自尊心、自我中心”"}]},{"word":"recede","phonetic":"/rɪˈsiːd/","meanings":[{"pos":"verb","meaning":"逐渐减弱，慢慢消失；后退，退去","usage":"主语常为抽象事物（记忆、恐惧）或具体事物（潮水、边界）"}]},{"word":"merge","phonetic":"/mɜːdʒ/","meanings":[{"pos":"verb","meaning":"合并，融合，融入","usage":"常用搭配merge into表示“融入……，和……合并”"}]},{"word":"boulder","phonetic":"/ˈbəʊldə(r)/","meanings":[{"pos":"noun","meaning":"巨石，砾石","usage":"指体积较大的圆形岩石"}]},{"word":"decay","phonetic":"/dɪˈkeɪ/","meanings":[{"pos":"noun/verb","meaning":"衰退，衰落；腐烂","usage":"可作名词表示衰退状态，也可作动词表示“衰退、腐烂”的动作"}]},{"word":"vitality","phonetic":"/vaɪˈtæləti/","meanings":[{"pos":"noun","meaning":"活力，生命力","usage":"不可数名词，形容人或事物的生机活力"}]},{"word":"weariness","phonetic":"/ˈwɪərinəs/","meanings":[{"pos":"noun","meaning":"疲劳，疲倦","usage":"由形容词weary（疲劳的）派生而来，可指身体或精神上的疲惫"}]}],"phrases":[{"phrase":"be cheated of","usage":"表示“被剥夺了……，被骗走了……”，被动结构强调主体失去了本应获得的事物","examples":[{"en":"Many children in the poor area are cheated of the right to education.","zh":"贫困地区的很多孩子被剥夺了受教育的权利。"}]},{"phrase":"bit by bit","usage":"副词短语，意为“逐渐地，一点一点地”，等同于gradually，可放在句首或句中修饰动作","examples":[{"en":"Bit by bit, he learned how to communicate with others properly.","zh":"他逐渐学会了如何恰当地和他人沟通。"}]},{"phrase":"be merged in","usage":"表示“融入……，和……融为一体”，也可写作be merged into，强调个体融入更大的整体","examples":[{"en":"The small village was gradually merged in the expanding city.","zh":"这个小村庄逐渐被扩张的城市吞并了。"}]},{"phrase":"suffer from","usage":"表示“遭受……的痛苦，受……困扰”，后常接疾病、负面情绪或不利处境","examples":[{"en":"A lot of office workers suffer from neck pain due to long hours of sitting.","zh":"很多上班族因为长时间久坐受到颈椎痛的困扰。"}]},{"phrase":"in the thought that","usage":"表示“想到……”，后接同位语从句说明thought的具体内容，用于描述人的心理活动","examples":[{"en":"She smiled in the thought that her family would come to see her soon.","zh":"想到家人很快就要来看她，她露出了微笑。"}]},{"phrase":"it seems to me","usage":"插入语，意为“在我看来，我认为”，用于委婉表达个人观点，可放在句首或句中","examples":[{"en":"It seems to me that we should put off the meeting until next week.","zh":"在我看来我们应该把会议推迟到下周。"}]}],"grammar":[{"title":"定语从句","definition":"修饰名词或代词的从句，用于对先行词进行限定或补充说明，由关系代词或关系副词引导","structure":"先行词 + 关系代词/副词 + 从句剩余部分","usage":"当先行词是人时常用who/that引导，是物时常用which/that引导，从句用于补充先行词的相关信息","examples":[{"en":"Young men who have reason to fear that they will be killed in battle may justifiably feel bitter.","zh":"有理由担心自己会在战场上丧生的年轻人，想到自己被剥夺了生活所能给予的最美好的东西，感到痛苦，这是合乎情理的。"},{"en":"The book that you lent me last week is very interesting.","zh":"你上周借给我的那本书非常有趣。"}]},{"title":"同位语从句","definition":"在复合句中作名词的同位语的从句，用于说明该名词的具体内容，常跟在fact, thought, idea, hope等抽象名词后","structure":"抽象名词 + that + 完整的陈述句","usage":"that在同位语从句中不充当成分，只起连接作用，不能省略，用于对前面的抽象名词进行解释说明","examples":[{"en":"They were worried over the fact that you were sick.","zh":"他们为你生病的事发愁。"},{"en":"I hold the belief that we will finally achieve our goal.","zh":"我坚信我们最终会实现目标。"}]},{"title":"方式状语从句","definition":"用于描述动作的方式、状态的状语从句，常由as, like, as if等词引导","structure":"主句 + as/like + 从句","usage":"常用于打比方，说明主句动作或状态的特征，as是正式引导词，like多用于口语中","examples":[{"en":"An individual human existence should be like a river--small at first, narrowly contained within its banks.","zh":"人的一生应该像一条河——起初很窄，被紧紧地夹在两岸之间。"},{"en":"When in Rome, do as the Romans do.","zh":"入乡随俗。"}]}],"patterns":[{"pattern":"Some people are oppressed by the fear of + 名词.","explanation":"","original":{"en":"Some old people are oppressed by the fear of death.","zh":"有些老年人因为怕死而感到烦恼。"},"examples":[{"en":"Many job seekers are oppressed by the fear of unemployment.","zh":"很多求职者因为害怕失业而感到压抑。"},{"en":"Some students are oppressed by the fear of failure in exams.","zh":"有些学生因为害怕考试不及格而倍感压力。"}]},{"pattern":"The best way to overcome it is to + 动词短语, until + 结果状语从句.","explanation":"","original":{"en":"The best way to overcome it--so at least it seems to me--is to make your interests gradually wider and more impersonal, until bit by bit the walls of the ego recede, and your life becomes increasingly merged in the universal life.","zh":"克服怕死的最好办法——至少在我看来是这样——就是逐渐使自己的兴趣更加广泛，逐渐摆脱个人狭小的圈子，直到自我的屏障慢慢消失，你的生活越来越融入整个社会生活之中。"},"examples":[{"en":"The best way to overcome stage fright is to practice speaking in public more often, until you can express your ideas fluently in front of crowds.","zh":"克服怯场的最好办法就是多练习公开发言，直到你能在人群面前流利地表达自己的想法。"},{"en":"The best way to overcome language barriers is to immerse yourself in the language environment, until you can communicate with native speakers without difficulty.","zh":"克服语言障碍的最好办法就是把自己沉浸在语言环境中，直到你能毫不费力地和母语者交流。"}]},{"pattern":"The man who, in + 场景, can see his life in this way, will not suffer from + 负面事物.","explanation":"","original":{"en":"The man who, in old age can see his life in this way, will not suffer from the fear of death, since the things he cares for will continue.","zh":"人到老年如果这样看待人生，就不会因为怕死而感到痛苦，因为他所关心的事情还会继续下去。"},"examples":[{"en":"The man who, in face of setbacks, can see his life in this way, will not suffer from self-doubt, since he knows failure is a necessary part of growth.","zh":"面对挫折时如果这样看待人生的人，就不会陷入自我怀疑，因为他知道失败是成长的必经部分。"},{"en":"The student who, in the face of heavy study tasks, can see his efforts in this way, will not suffer from anxiety, since he knows every bit of effort pays off.","zh":"面对繁重的学习任务时如果这样看待自己的付出的学生，就不会饱受焦虑的困扰，因为他知道每一点努力都有回报。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“有正当理由地，无可非议地” 对应的单词是？","hint":"adverb · /ˈdʒʌstɪfaɪəbli/","options":["vicious","justifiably","spasm","maximum"],"answer":1,"explain":"justifiably · /ˈdʒʌstɪfaɪəbli/ · adverb · 有正当理由地，无可非议地。修饰动词、形容词，说明行为或感受的合理性","source":{"kind":"vocab","word":"justifiably"},"id":"b4-u11-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：使压抑，使烦恼；压迫，欺压","hint":"/əˈpres/ · verb","answer":"oppress","placeholder":"输入英文单词","explain":"oppress · /əˈpres/ · verb · 使压抑，使烦恼；压迫，欺压。常用被动语态be oppressed by表示“被……困扰、压迫”","source":{"kind":"vocab","word":"oppress"},"id":"b4-u11-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：A lot of office workers _____ neck pain due to long hours of sitting.","hint":"很多上班族因为长时间久坐受到颈椎痛的困扰。","answer":"suffer from","placeholder":"输入缺失的短语","explain":"suffer from：表示“遭受……的痛苦，受……困扰”，后常接疾病、负面情绪或不利处境（很多上班族因为长时间久坐受到颈椎痛的困扰。）","source":{"kind":"phrase","phrase":"suffer from"},"id":"b4-u11-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：the _____ of rest will be not unwelcome.","hint":"休息的念头将不会令人不快。","answer":"thought","placeholder":"输入缺失的单词","explain":"the thought of rest will be not unwelcome. — 休息的念头将不会令人不快。","source":{"kind":"sentence","en":"the thought of rest will be not unwelcome."},"id":"b4-u11-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“在复合句中作名词的同位语的从句，用于说明该名词的具体内容，常跟在fact, thought, idea, hope等抽象名词后” 描述的是哪个语法点？","hint":"抽象名词 + that + 完整的陈述句","options":["完全倒装句（状语前置）","定语从句的分隔现象","破折号的解释说明用法","同位语从句"],"answer":3,"explain":"同位语从句：抽象名词 + that + 完整的陈述句：that在同位语从句中不充当成分，只起连接作用，不能省略，用于对前面的抽象名词进行解释说明","source":{"kind":"grammar","title":"同位语从句"},"id":"b4-u11-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nand has achieved whatever work it was in him to do,","hint":"","options":["或者通过组成防御队形来保护他们免受鲨鱼的袭击。","波谷（最低点），波高（从波谷到波峰的垂直距离），","并且已经做完了他力所能及的一切工作，","只要我们与原始人、"],"answer":2,"explain":"and has achieved whatever work it was in him to do, — 并且已经做完了他力所能及的一切工作，","source":{"kind":"sentence","en":"and has achieved whatever work it was in him to do,"},"id":"b4-u11-q06"}]},{"id":"b4-u12","book":4,"unit":12,"key":"12","lessonFrom":12,"lessonTo":12,"title":"Banks and Their Customers","titleZh":"银行及其储户","question":"Why is there no risk to the customer when a bank prints the customer's name on his cheques?","sentences":[{"en":"When anyone opens a current account at a bank, he is lending the bank money,","zh":"任何人在银行开立活期账户，他就是在借钱给银行，","t":15.5},{"en":"repayment of which he may demand at any time either in cash or by drawing a cheque in favour of another person.","zh":"而他可以随时要求银行偿还这笔钱，方式可以是现金，也可以是开出支票给另一个人。","t":20.69},{"en":"Primarily, the banker-customer relationship is that of debtor and creditor--","zh":"银行和储户的关系主要是债务人和债权人的关系——","t":29.28},{"en":"who is which depending on whether the customer's account is in credit or is overdrawn.","zh":"谁是债务人，谁是债权人，取决于储户的账户是盈余还是透支。","t":35.26},{"en":"But, in addition to that basically simple concept,","zh":"但是，除了这个基本简单的概念之外，","t":40.53},{"en":"the bank and its customer owe a large number of obligations to one another.","zh":"银行和其储户彼此还负有大量的义务。","t":43.76},{"en":"Many of these obligations can give rise to problems and complications but a bank customer, unlike, say, a buyer of goods,","zh":"这些义务中的许多都可能引起问题和复杂情况，但是银行储户，不像（比如说）商品购买者，","t":49.72},{"en":"cannot complain that the law is loaded against him.","zh":"不能抱怨法律对他不利。","t":58.87},{"en":"The bank must obey its customer's instructions, and not those of anyone else.","zh":"银行必须服从其储户的指令，而不是其他任何人的指令。","t":62.59},{"en":"When, for example, a customer first opens an account, he instructs the bank to debit his account only in respect of cheques drawn by himself.","zh":"例如，当储户首次开立账户时，他会指示银行只对由他本人开出的支票进行借记。","t":67.79},{"en":"He gives the bank specimens of his signature, and there is a very firm rule","zh":"他向银行提供他的签名样本，并且有一条非常明确的规定：","t":77.88},{"en":"that the bank has no right or authority to pay out a customer's money on a cheque","zh":"银行无权或无权限根据一张支票支付储户的款项，","t":82.82},{"en":"on which its customer's signature has been forged.","zh":"如果这张支票上的储户签名被伪造。","t":87.94},{"en":"It makes no difference that the forgery may have been a very skillful one:","zh":"即使伪造得非常高明，也没有任何区别：","t":91.9},{"en":"the bank must recognize its customer's signature.","zh":"银行必须识别其储户的签名。","t":96.48},{"en":"For this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer's name on his cheques.","zh":"由于这个原因，银行采用的在储户支票上印上储户姓名的做法对储户来说没有风险。","t":100.24},{"en":"If this facilitates forgery, it is the bank which will lose, not the customer.","zh":"如果这有助于伪造，那么损失的是银行，而不是储户。","t":109}],"vocab":[{"word":"current","phonetic":"/ˈkʌrənt/","meanings":[{"pos":"adjective","meaning":"当前的；流通的","usage":"在本文中与account搭配指活期账户，可随时存取款项"},{"pos":"noun","meaning":"水流；电流；趋势","usage":"可表示自然流动的事物或社会发展的动向"}]},{"word":"repayment","phonetic":"/rɪˈpeɪmənt/","meanings":[{"pos":"noun","meaning":"偿还；还款；偿还的款项","usage":"是动词repay的名词形式，后常接of sth表示对某物的偿还"}]},{"word":"debtor","phonetic":"/ˈdetə(r)/","meanings":[{"pos":"noun","meaning":"债务人；借方","usage":"与creditor（债权人）相对，指欠别人钱的一方"}]},{"word":"creditor","phonetic":"/ˈkredɪtə(r)/","meanings":[{"pos":"noun","meaning":"债权人；贷方","usage":"指有权要求他人偿还欠款的一方"}]},{"word":"overdraw","phonetic":"/ˌəʊvəˈdrɔː/","meanings":[{"pos":"verb","meaning":"透支（银行账户）","usage":"常用被动形式be overdrawn表示账户处于透支状态"}]},{"word":"obligation","phonetic":"/ˌɒblɪˈɡeɪʃn/","meanings":[{"pos":"noun","meaning":"义务；责任；债务","usage":"常接to sb/sth表示对某人/某事物的义务，owe obligation to sb表示对某人负有义务"}]},{"word":"complication","phonetic":"/ˌkɒmplɪˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"复杂情况；并发症","usage":"指让原本的问题变得更难处理的额外状况"}]},{"word":"debit","phonetic":"/ˈdebɪt/","meanings":[{"pos":"verb","meaning":"记入（账户）的借方；从（账户）中扣除","usage":"常用结构debit sth against/to sb's account，表示将某笔款项记入账户借方"},{"pos":"noun","meaning":"借方；借记","usage":"与credit（贷方）相对，是会计常用术语"}]},{"word":"specimen","phonetic":"/ˈspesɪmən/","meanings":[{"pos":"noun","meaning":"样本；标本；签字样","usage":"可指用于检验、参考的各类样品，本文指签字样本"}]},{"word":"forge","phonetic":"/fɔːdʒ/","meanings":[{"pos":"verb","meaning":"伪造；假冒；锻造","usage":"可指伪造文件、签名等，也可指金属锻造工艺"}]},{"word":"forgery","phonetic":"/ˈfɔːdʒəri/","meanings":[{"pos":"noun","meaning":"伪造；伪造品；赝品","usage":"是forge的名词形式，可指伪造的行为或伪造出来的物品"}]},{"word":"facilitate","phonetic":"/fəˈsɪlɪteɪt/","meanings":[{"pos":"verb","meaning":"促进；使便利","usage":"主语通常为事物，强调让某件事更容易进行"}]}],"phrases":[{"phrase":"current account","usage":"银行术语，指可随时存取款、用于日常支付的活期存款账户，美语中常用checking account表示相同含义","examples":[{"en":"I need to open a current account to pay my monthly bills.","zh":"我需要开一个活期账户来支付我的每月账单。"}]},{"phrase":"in favour of","usage":"表示“以……为收款人；有利于；支持”，在金融场景中常指支票的收款方","examples":[{"en":"Please draw a cheque in favour of the charity organization.","zh":"请开一张以该慈善机构为收款人的支票。"}]},{"phrase":"in credit","usage":"银行账户用语，表示账户有余额、处于贷方余额状态，与be overdrawn（透支）相对","examples":[{"en":"Your account is still in credit, so you don't need to deposit more money right now.","zh":"你的账户还有余额，所以你现在不需要再存钱。"}]},{"phrase":"give rise to","usage":"正式表达，意为“引起；导致；使发生”，后接表示问题、变化等的名词","examples":[{"en":"Poor communication may give rise to misunderstandings between team members.","zh":"沟通不畅可能会引起团队成员之间的误解。"}]},{"phrase":"be loaded against","usage":"表示“对……不利；偏向于反对……”，常用来描述规则、制度等不公平地偏向某一方","examples":[{"en":"Many workers complain that the existing labour law is loaded against them.","zh":"许多工人抱怨现行的劳动法对他们不利。"}]},{"phrase":"in respect of","usage":"正式用语，意为“关于；涉及；就……而言”，用于引出相关的对象或范围","examples":[{"en":"The company will compensate you in respect of the losses caused by the delay.","zh":"公司将就延误给你造成的损失进行赔偿。"}]},{"phrase":"make no difference","usage":"表示“没有影响；无关紧要”，后可接that从句或疑问词引导的从句说明具体内容","examples":[{"en":"It makes no difference how much experience you have - we will all receive the same training.","zh":"你有多少经验都无关紧要，我们都会接受同样的培训。"}]}],"grammar":[{"title":"独立主格结构","definition":"由名词/代词 + 非谓语动词/形容词/副词/介词短语等构成，在句中作状语，其逻辑主语与句子主句的主语不一致，有独立的逻辑主语","structure":"名词/代词 + 现在分词/过去分词/形容词/副词/介词短语","usage":"常用于书面语中，可表示时间、原因、条件、伴随状况等，相当于一个状语从句","examples":[{"en":"who is which depending on whether the customer's account is in credit or is overdrawn.","zh":"谁是债务人谁是债权人取决于客户的账户是有余额还是透支。"},{"en":"The weather being fine, we decided to go hiking in the mountains.","zh":"天气很好，我们决定去山里徒步旅行。"}]},{"title":"It作形式主语的主语从句","definition":"当主语是较长的从句时，为了避免句子头重脚轻，通常用it作形式主语放在句首，而把真正的主语从句放到句子后面","structure":"It + 系动词/不及物动词 + 形容词/名词/短语 + that/wh-引导的主语从句","usage":"常用于表达事实、观点、可能性等，使句子结构更平衡","examples":[{"en":"It makes no difference that the forgery may have been a very skillful one.","zh":"伪造的技术可能非常高超，这也没有用。"},{"en":"It is obvious that regular exercise is beneficial to physical and mental health.","zh":"很明显，规律锻炼对身心健康有益。"}]},{"title":"强调句","definition":"用来突出句子中的某一部分（通常是主语、宾语、状语），强调该部分的重要性","structure":"It is/was + 被强调部分 + that/who + 句子其他部分","usage":"当被强调部分指人时可以用who，其他情况一律用that，去掉It is/was和that/who后句子依然完整","examples":[{"en":"If this facilitates forgery, it is the bank which will lose, not the customer.","zh":"如果这种做法便利了伪造，那么受损失的会是银行，而不是客户。"},{"en":"It was his hard work rather than luck that helped him achieve success.","zh":"是他的努力而非运气帮助他取得了成功。"}]}],"patterns":[{"pattern":"Primarily, A is that of B-- X depending on whether Y or Z.","explanation":"","original":{"en":"Primarily, the banker-customer relationship is that of debtor and creditor-- who is which depending on whether the customer's account is in credit or is overdrawn.","zh":"银行与客户的关系主要是债务人和债权人的关系——谁是债务人谁是债权人取决于客户的账户是有余额还是透支。"},"examples":[{"en":"Primarily, the teacher-student relationship is that of guider and learner-- what role each plays depending on whether the class is theory-based or practice-based.","zh":"师生关系主要是指导者和学习者的关系——各自扮演什么角色取决于课程是理论型还是实践型。"},{"en":"Primarily, the relationship between sellers and buyers is that of service provider and consumer-- who holds more initiative depending on whether the market is a buyer's market or a seller's market.","zh":"买卖双方的关系主要是服务提供者和消费者的关系——谁更有主动权取决于市场是买方市场还是卖方市场。"}]},{"pattern":"There is a very firm rule that A has no right or authority to do B on C.","explanation":"","original":{"en":"there is a very firm rule that the bank has no right or authority to pay out a customer's money on a cheque on which its customer's signature has been forged.","zh":"有一条非常严格的规定：银行没有权利或权限凭客户签名被伪造的支票支付客户的存款。"},"examples":[{"en":"There is a very firm rule in the company that managers have no right or authority to ask employees to work overtime without extra pay.","zh":"公司有一条非常严格的规定：管理者没有权利或权限要求员工无偿加班。"},{"en":"There is a very firm rule in the school that teachers have no right or authority to punish students physically on any ground.","zh":"学校有一条非常严格的规定：教师没有权利或权限以任何理由体罚学生。"}]},{"pattern":"For this reason there is no risk to A in the practice, adopted by B, of doing C.","explanation":"","original":{"en":"For this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer's name on his cheques.","zh":"因此，银行采取的把客户姓名印在支票上的做法对客户没有任何风险。"},"examples":[{"en":"For this reason there is no risk to consumers in the practice, adopted by the platform, of freezing transactions until the goods are confirmed received.","zh":"因此，平台采取的在确认收货前冻结交易的做法对消费者没有任何风险。"},{"en":"For this reason there is no risk to passengers in the practice, adopted by airlines, of checking the validity of ID documents before boarding.","zh":"因此，航空公司采取的登机前检查身份证件有效性的做法对乘客没有任何风险。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“促进；使便利” 对应的单词是？","hint":"verb · /fəˈsɪlɪteɪt/","options":["interval","potentiality","inclined","facilitate"],"answer":3,"explain":"facilitate · /fəˈsɪlɪteɪt/ · verb · 促进；使便利。主语通常为事物，强调让某件事更容易进行","source":{"kind":"vocab","word":"facilitate"},"id":"b4-u12-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：复杂情况；并发症","hint":"/ˌkɒmplɪˈkeɪʃn/ · noun","answer":"complication","placeholder":"输入英文单词","explain":"complication · /ˌkɒmplɪˈkeɪʃn/ · noun · 复杂情况；并发症。指让原本的问题变得更难处理的额外状况","source":{"kind":"vocab","word":"complication"},"id":"b4-u12-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Your account is still _____, so you don't need to deposit more money right now.","hint":"你的账户还有余额，所以你现在不需要再存钱。","answer":"in credit","placeholder":"输入缺失的短语","explain":"in credit：银行账户用语，表示账户有余额、处于贷方余额状态，与be overdrawn（透支）相对（你的账户还有余额，所以你现在不需要再存钱。）","source":{"kind":"phrase","phrase":"in credit"},"id":"b4-u12-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He gives the bank _____ of his signature, and there is a very firm rule","hint":"他向银行提供他的签名样本，并且有一条非常明确的规定：","answer":"specimens","placeholder":"输入缺失的单词","explain":"He gives the bank specimens of his signature, and there is a very firm rule — 他向银行提供他的签名样本，并且有一条非常明确的规定：","source":{"kind":"sentence","en":"He gives the bank specimens of his signature, and there is a very firm rule"},"id":"b4-u12-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当主语是较长的从句时，为了避免句子头重脚轻，通常用it作形式主语放在句首，而把真正的主语从句放到句子后面” 描述的是哪个语法点？","hint":"It + 系动词/不及物动词 + 形容词/名词/短语 + that/wh-引导的主语从句","options":["原因状语从句 (Adverbial Clause of Cause)","完全倒装句（状语前置）","It作形式主语的主语从句","插入语结构"],"answer":2,"explain":"It作形式主语的主语从句：It + 系动词/不及物动词 + 形容词/名词/短语 + that/wh-引导的主语从句：常用于表达事实、观点、可能性等，使句子结构更平衡","source":{"kind":"grammar","title":"It作形式主语的主语从句"},"id":"b4-u12-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nFor this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer's name on his cheques.","hint":"","options":["为什么只有蛇有毒液呢？","波浪是海洋与大气搏斗的产物，是永恒的无限的印记。","因此，保住你的本金并获得额外收入是你的主要优先事项。","由于这个原因，银行采用的在储户支票上印上储户姓名的做法对储户来说没有风险。"],"answer":3,"explain":"For this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer's name on his cheques. — 由于这个原因，银行采用的在储户支票上印上储户姓名的做法对储户来说没有风险。","source":{"kind":"sentence","en":"For this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer's name on his cheques."},"id":"b4-u12-q06"}]},{"id":"b4-u13","book":4,"unit":13,"key":"13","lessonFrom":13,"lessonTo":13,"title":"The Search for Oil","titleZh":"寻找石油","question":"What do oilmen want to achieve as soon as they strike oil?","sentences":[{"en":"The deepest holes of all are made for oil, and they go down to as much as 25,000 feet.","zh":"所有最深的孔都是为石油而钻的，它们深达25,000英尺。","t":16.98},{"en":"But we do not need to send man down to get the oil out, as we must with other mineral deposits.","zh":"但我们不需要像开采其他矿藏那样派人下去取油。","t":26.09},{"en":"The holes are only borings, less than a foot in diameter.","zh":"这些孔只是钻孔，直径不到一英尺。","t":34.31},{"en":"My particular experience is largely in oil, and the search for oil has done more to improve deep drilling than any other mining activity.","zh":"我尤其在石油方面经验丰富，而寻找石油对深层钻探的改进作用，比任何其他采矿活动都要大。","t":40.18},{"en":"When it has been decided where we are going to drill,","zh":"当我们决定了钻探地点之后，","t":52.31},{"en":"we put up at the surface an oil derrick.","zh":"我们就会在地面上架设一个采油井架。","t":56.08},{"en":"It has to be tall because it is like a giant block and tackle and we have to lower into the ground","zh":"它必须很高，因为它就像一个巨大的滑轮组，我们必须把巨大的钻杆放下去，","t":59.84},{"en":"and haul out of the ground great lengths of drill pipe which are rotated by an engine at the top","zh":"并把巨大的钻杆从地下拉上来，这些钻杆由顶部的发动机带动旋转，","t":66.82},{"en":"and are fitted with a cutting bit at the bottom.","zh":"底部装有钻头。","t":73.84},{"en":"The geologist needs to know what rocks the drill has reached,","zh":"地质学家需要知道钻头钻到了什么岩石，","t":77.95},{"en":"so every so often a sample is obtained with a coring bit.","zh":"因此，每隔一段时间就会用取心钻头取一个样本。","t":82.67},{"en":"It cuts a clean cylinder of rock, from which can be seen the strata the drill has been cutting through.","zh":"它能切下一段干净的圆柱形岩石，从中可以看到钻头穿过的地层。","t":88.11},{"en":"Once we get down to the oil, it usually flows to the surface because great pressure either from gas or water, is pushing it.","zh":"一旦我们钻到石油，它通常会流到地表，因为巨大的压力，无论是来自天然气还是水，都在推动它。","t":96.45},{"en":"This pressure must be under control, and we control it by means of the mud which we circulate down the drill pipe.","zh":"这种压力必须得到控制，我们通过循环注入钻杆的泥浆来控制它。","t":106.93},{"en":"We endeavour to avoid the old, romantic idea of a gusher, which wastes oil and gas.","zh":"我们努力避免那种老式的、浪漫的喷油井，那只会浪费石油和天然气。","t":116.22},{"en":"We want it to stay down the hole until we can lead it off in a controlled manner.","zh":"我们希望它留在井下，直到我们能以受控的方式将其引出。","t":124.33}],"vocab":[{"word":"strike","phonetic":"/straɪk/","meanings":[{"pos":"verb","meaning":"发现（石油、矿物等）；击打","usage":"作“发现”义时，常接oil/gold等矿产类名词；作“击打”义时为不及物或及物动词"}]},{"word":"boring","phonetic":"/ˈbɔːrɪŋ/","meanings":[{"pos":"noun","meaning":"钻孔；钻屑","usage":"指钻井作业中钻出的孔洞，也可表示钻井过程中产生的碎屑"}]},{"word":"diameter","phonetic":"/daɪˈæmɪtər/","meanings":[{"pos":"noun","meaning":"直径","usage":"表示圆形物体的直径，常用搭配：in diameter（直径为……）"}]},{"word":"derrick","phonetic":"/ˈderɪk/","meanings":[{"pos":"noun","meaning":"钻井架；起重机","usage":"石油行业中特指开采石油的井架，也可指港口的重型起重机"}]},{"word":"tackle","phonetic":"/ˈtækl/","meanings":[{"pos":"noun","meaning":"滑轮组；用具","usage":"block and tackle为固定搭配，指滑轮组；也可作动词表示“处理、解决”"}]},{"word":"rotate","phonetic":"/rəʊˈteɪt/","meanings":[{"pos":"verb","meaning":"旋转；轮流","usage":"作“旋转”义时可指物体绕轴转动；作“轮流”义时可指人员轮班"}]},{"word":"geologist","phonetic":"/dʒiˈɒlədʒɪst/","meanings":[{"pos":"noun","meaning":"地质学家","usage":"指研究地球物质结构、历史的专业人员，词根geology为地质学"}]},{"word":"cylinder","phonetic":"/ˈsɪlɪndər/","meanings":[{"pos":"noun","meaning":"圆柱体；气缸","usage":"可指几何形状的圆柱体，也可指发动机的气缸"}]},{"word":"strata","phonetic":"/ˈstrɑːtə/","meanings":[{"pos":"noun","meaning":"岩层；阶层（stratum的复数）","usage":"地质学中特指地层，也可引申指社会阶层"}]},{"word":"circulate","phonetic":"/ˈsɜːkjəleɪt/","meanings":[{"pos":"verb","meaning":"循环；流通","usage":"可指液体、气体的循环，也可指信息、货币的流通"}]},{"word":"endeavour","phonetic":"/ɪnˈdevər/","meanings":[{"pos":"verb","meaning":"努力；竭力","usage":"正式用词，搭配endeavour to do sth. 表示努力做某事"}]},{"word":"romantic","phonetic":"/rəʊˈmæntɪk/","meanings":[{"pos":"adjective","meaning":"浪漫的；不切实际的","usage":"除指爱情相关的浪漫外，还可表示想法脱离实际、理想化"}]},{"word":"gusher","phonetic":"/ˈɡʌʃər/","meanings":[{"pos":"noun","meaning":"喷油井；喷发井","usage":"石油行业特指会自动喷出石油的油井，词根gush为动词“喷涌”"}]},{"word":"deposit","phonetic":"/dɪˈpɒzɪt/","meanings":[{"pos":"noun","meaning":"矿床；存款；押金","usage":"mineral deposit为固定搭配，指矿床；也可指银行存款或租房押金"}]},{"word":"haul","phonetic":"/hɔːl/","meanings":[{"pos":"verb","meaning":"（用力）拖，拉","usage":"指需要付出很大力气拖拽重物，常用于工业、运输场景"}]}],"phrases":[{"phrase":"strike oil","usage":"字面义为钻探到石油，也可引申为突然发财、交好运","examples":[{"en":"After three years of exploration, the team finally struck oil in the desert.","zh":"经过三年勘探，团队终于在沙漠中钻探到了石油。"},{"en":"He struck oil when his small invention was bought by a big company.","zh":"他的小发明被大公司收购后，他一下子就发了财。"}]},{"phrase":"mineral deposit","usage":"固定搭配，指地壳中聚集的矿产资源","examples":[{"en":"Geologists have found a rich mineral deposit in the mountain area.","zh":"地质学家在山区发现了一处储量丰富的矿床。"},{"en":"The country's economy relies heavily on the exploitation of its mineral deposits.","zh":"该国经济严重依赖其矿产资源的开采。"}]},{"phrase":"put up","usage":"此处指搭建、建造；还可表示张贴、提供住宿","examples":[{"en":"They plan to put up a temporary office on the construction site.","zh":"他们计划在工地上搭建一间临时办公室。"},{"en":"We can put you up for the night if you miss the last train.","zh":"如果你赶不上末班车，我们可以给你提供一晚住宿。"}]},{"phrase":"block and tackle","usage":"固定术语，指滑轮组，用于吊运重物","examples":[{"en":"Workers used a block and tackle to lift the heavy machine onto the truck.","zh":"工人们用滑轮组把沉重的机器吊到了卡车上。"},{"en":"The oil derrick is equipped with a block and tackle to handle long drill pipes.","zh":"钻井架配备了滑轮组来搬运长钻杆。"}]},{"phrase":"be fitted with","usage":"表示“装有、配备有”，主语通常为物品","examples":[{"en":"All new cars in this country are fitted with safety belts as standard.","zh":"这个国家所有的新车都标配了安全带。"},{"en":"The laboratory is fitted with the latest testing equipment.","zh":"这个实验室配备了最新的检测设备。"}]},{"phrase":"every so often","usage":"表示“偶尔、有时”，相当于occasionally，作时间状语","examples":[{"en":"Every so often, I go hiking in the hills to relax.","zh":"我偶尔会去山里徒步放松一下。"},{"en":"You should check the tire pressure every so often to avoid accidents.","zh":"你应该偶尔检查一下胎压，避免发生事故。"}]},{"phrase":"by means of","usage":"正式表达，意为“通过、借助于”，后接名词或动名词","examples":[{"en":"The rescue team located the trapped miners by means of a special detector.","zh":"救援队借助一种特殊探测器找到了被困矿工的位置。"},{"en":"We can express our feelings by means of body language when we don't speak the same language.","zh":"当我们语言不通时，可以借助肢体语言来表达感受。"}]},{"phrase":"lead off","usage":"此处指“引导流出、引出”，还可表示“开始、开头”","examples":[{"en":"Pipes are installed to lead off the excess water from the reservoir.","zh":"安装了管道来引出水库里多余的水。"},{"en":"The singer will lead off the festival with a popular song.","zh":"这位歌手将演唱一首流行歌曲，拉开音乐节的序幕。"}]}],"grammar":[{"title":"被动语态的应用","definition":"用于强调动作的承受者，或动作的执行者不需要、不便指出的场景，在科普类说明文中使用广泛","structure":"be + 动词过去分词（+ by + 动作执行者）","usage":"常用于客观说明事物的原理、操作流程，避免主观表述，增强内容的客观性和专业性","examples":[{"en":"When it has been decided where we are going to drill, we put up at the surface an oil derrick.","zh":"当确定了钻探地点后，我们就在地面上搭起钻井架。"},{"en":"This pressure must be under control, and we control it by means of the mud which we circulate down the drill pipe.","zh":"这种压力必须得到控制，我们通过沿钻杆向下循环的泥浆来控制它。"},{"en":"All the samples will be analyzed in the laboratory next week.","zh":"所有样本下周都会在实验室进行分析。"}]},{"title":"定语从句的分隔结构","definition":"定语从句和所修饰的先行词之间被其他成分分隔，避免句子头重脚轻，常见于较长的复合句中","structure":"先行词 + 状语/其他修饰成分 + 关系代词/关系副词 + 定语从句","usage":"当先行词后的定语从句较长，或先行词后需要补充其他必要信息时，会使用分隔结构，识别时需先找准先行词","examples":[{"en":"It cuts a clean cylinder of rock, from which can be seen the strata the drill has been cutting through.","zh":"它切下一个光滑的岩石圆柱体，从中可以看到钻头钻过的岩层。"},{"en":"We endeavour to avoid the old, romantic idea of a gusher, which wastes oil and gas.","zh":"我们努力避免那种旧式的、理想化的井喷现象，这种现象会浪费石油和天然气。"},{"en":"A new teacher will come tomorrow who will teach you geography.","zh":"明天会来一位新老师，教你们地理。"}]},{"title":"原因状语从句","definition":"用于说明主句动作发生的原因，常由because, as, since等连词引导","structure":"主句 + because/as/since + 原因状语从句","usage":"because语气最强，用于回答why的提问，说明直接原因；as和since语气较弱，通常表示已知的、显而易见的原因","examples":[{"en":"It has to be tall because it is like a giant block and tackle and we have to lower into the ground and haul out of the ground great lengths of drill pipe.","zh":"它必须很高，因为它就像一个巨大的滑轮组，我们得把很长的钻杆放到地下，再从地下拉出来。"},{"en":"Once we get down to the oil, it usually flows to the surface because great pressure either from gas or water, is pushing it.","zh":"一旦我们钻到石油，石油通常会涌向地表，因为来自天然气或水的巨大压力在推着它。"},{"en":"As the weather is getting colder, we need to prepare more warm clothes for the elderly.","zh":"由于天气越来越冷，我们需要给老人准备更多保暖衣物。"}]}],"patterns":[{"pattern":"... has done more to ... than any other ...","explanation":"","original":{"en":"The search for oil has done more to improve deep drilling than any other mining activity.","zh":"钻探石油对改进深钻技术的贡献，比其他任何采矿活动都大。"},"examples":[{"en":"The development of mobile Internet has done more to change people's way of communication than any other technology in the past 20 years.","zh":"移动互联网的发展对改变人们沟通方式的贡献，比过去20年其他任何技术都大。"},{"en":"Regular exercise has done more to improve his physical condition than any other health care method.","zh":"规律锻炼对改善他身体状况的作用，比其他任何保健方法都大。"}]},{"pattern":"Once ..., ...","explanation":"","original":{"en":"Once we get down to the oil, it usually flows to the surface because great pressure either from gas or water, is pushing it.","zh":"一旦我们钻到石油，石油通常会涌向地表，因为来自天然气或水的巨大压力在推着它。"},"examples":[{"en":"Once you have mastered the basic rules of the language, you will be able to communicate with local people smoothly.","zh":"一旦你掌握了这门语言的基本规则，就能顺畅地和当地人交流了。"},{"en":"Once the project is approved, we will start the construction work as soon as possible.","zh":"一旦项目获得批准，我们就会尽快开工建设。"}]},{"pattern":"... has to be ... because ...","explanation":"","original":{"en":"It has to be tall because it is like a giant block and tackle and we have to lower into the ground and haul out of the ground great lengths of drill pipe.","zh":"它必须很高，因为它就像一个巨大的滑轮组，我们得把很长的钻杆放到地下，再从地下拉出来。"},"examples":[{"en":"The new library has to be designed with large open spaces because it needs to hold thousands of books and accommodate hundreds of readers at the same time.","zh":"新图书馆必须设计有大面积的开放空间，因为它需要存放数千册图书，同时容纳数百名读者。"},{"en":"The hospital's emergency passage has to be kept clear all the time because ambulances need to pass through at any time.","zh":"医院的应急通道必须时刻保持畅通，因为救护车随时都需要通行。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“循环；流通” 对应的单词是？","hint":"verb · /ˈsɜːkjəleɪt/","options":["circulate","complication","stereotype","weariness"],"answer":0,"explain":"circulate · /ˈsɜːkjəleɪt/ · verb · 循环；流通。可指液体、气体的循环，也可指信息、货币的流通","source":{"kind":"vocab","word":"circulate"},"id":"b4-u13-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：滑轮组；用具","hint":"/ˈtækl/ · noun","answer":"tackle","placeholder":"输入英文单词","explain":"tackle · /ˈtækl/ · noun · 滑轮组；用具。block and tackle为固定搭配，指滑轮组；也可作动词表示“处理、解决”","source":{"kind":"vocab","word":"tackle"},"id":"b4-u13-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The rescue team located the trapped miners _____ a special detector.","hint":"救援队借助一种特殊探测器找到了被困矿工的位置。","answer":"by means of","placeholder":"输入缺失的短语","explain":"by means of：正式表达，意为“通过、借助于”，后接名词或动名词（救援队借助一种特殊探测器找到了被困矿工的位置。）","source":{"kind":"phrase","phrase":"by means of"},"id":"b4-u13-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The holes are only borings, less _____ a foot in diameter.","hint":"这些孔只是钻孔，直径不到一英尺。","answer":"than","placeholder":"输入缺失的单词","explain":"The holes are only borings, less than a foot in diameter. — 这些孔只是钻孔，直径不到一英尺。","source":{"kind":"sentence","en":"The holes are only borings, less than a foot in diameter."},"id":"b4-u13-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于说明主句动作发生的原因，常由because, as, since等连词引导” 描述的是哪个语法点？","hint":"主句 + because/as/since + 原因状语从句","options":["so...that...引导的结果状语从句","定语从句的分隔结构","原因状语从句","It作形式主语的名词性从句"],"answer":2,"explain":"原因状语从句：主句 + because/as/since + 原因状语从句：because语气最强，用于回答why的提问，说明直接原因；as和since语气较弱，通常表示已知的、显而易见的原因","source":{"kind":"grammar","title":"原因状语从句"},"id":"b4-u13-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIt has to be tall because it is like a giant block and tackle and we have to lower into the ground","hint":"","options":["如今，尽管旧的伽利略形象依然存在于许多流行著作中，","摩天大楼的形状和尺寸完全取决于每平方英尺土地获取最大收入的需要，","哈特确实了解一些旧西部。","它必须很高，因为它就像一个巨大的滑轮组，我们必须把巨大的钻杆放下去，"],"answer":3,"explain":"It has to be tall because it is like a giant block and tackle and we have to lower into the ground — 它必须很高，因为它就像一个巨大的滑轮组，我们必须把巨大的钻杆放下去，","source":{"kind":"sentence","en":"It has to be tall because it is like a giant block and tackle and we have to lower into the ground"},"id":"b4-u13-q06"}]},{"id":"b4-u14","book":4,"unit":14,"key":"14","lessonFrom":14,"lessonTo":14,"title":"The Butterfly Effect","titleZh":"蝴蝶效应","question":"Why do small errors make it impossible to predict the weather system with a high degree of accuracy?","sentences":[{"en":"Beyond two or three days, the world's best weather forecasts are speculative,","zh":"超过两三天，世界上最好的天气预报都是推测性的，","t":17.46},{"en":"and beyond six or seven they are worthless.","zh":"超过六七天，它们就毫无价值了。","t":23.2},{"en":"The Butterfly Effect is the reason.","zh":"蝴蝶效应就是原因。","t":26.84},{"en":"For small pieces of weather--","zh":"对于局部天气——","t":30.02},{"en":"and to a global forecaster, small can mean thunderstorms and blizzards--","zh":"对于全球预报员来说，局部可能意味着雷暴和暴风雪——","t":32.07},{"en":"any prediction deteriorates rapidly.","zh":"任何预测都会迅速恶化。","t":37.13},{"en":"Errors and uncertainties multiply, cascading upward through a chain of turbulent features,","zh":"误差和不确定性倍增，通过一系列湍流特征向上级联，","t":40.35},{"en":"from dust devils and squalls up to continent-size eddies that only satellites can see.","zh":"从尘卷风和飑线直到只有卫星才能看到的洲际大小的涡流。","t":46.71},{"en":"The modern weather models work with a grid of points of the order of sixty miles apart,","zh":"现代天气模型采用相距约六十英里的网格点，","t":53.91},{"en":"and even so, some starting data has to be guessed,","zh":"即便如此，一些初始数据也必须是猜测的，","t":59.92},{"en":"since ground stations and satellites cannot see everywhere.","zh":"因为地面站和卫星无法看到所有地方。","t":64.08},{"en":"But suppose the earth could be covered with sensors spaced one foot apart,","zh":"但是假设地球可以被间隔一英尺的传感器覆盖，","t":68.69},{"en":"rising at one-foot intervals all the way to the top of the atmosphere.","zh":"并以一英尺的间隔一直上升到大气的顶端。","t":73.41},{"en":"Suppose every sensor gives perfectly accurate readings of temperature,","zh":"假设每个传感器都能提供完全准确的温度读数，","t":79},{"en":"pressure, humidity, and any other quantity a meteorologist would want.","zh":"压力、湿度以及气象学家想要的任何其他量。","t":84.13},{"en":"Precisely at noon an infinitely powerful computer takes all the data and calculates what will happen at each point","zh":"正午时分，一台无限强大的计算机获取所有数据，并计算出每个点将发生什么，","t":90.61},{"en":"at 12.01, then 12.02, then 12.03...","zh":"在12点01分，然后12点02分，然后12点03分……","t":99.25},{"en":"The computer will still be unable to predict whether Princeton, New Jersey, will have sun or rain on a day one month away.","zh":"这台计算机仍然无法预测一个月后新泽西州普林斯顿是晴天还是雨天。","t":105.38},{"en":"At noon the spaces between the sensors will hide fluctuations that the computer will not know about,","zh":"中午时，传感器之间的空间会隐藏计算机不知道的波动，","t":114.42},{"en":"tiny deviations from the average.","zh":"那些与平均值微小的偏差。","t":121.52},{"en":"By 12.01, those fluctuations will already have created small errors one foot away.","zh":"到12点01分，这些波动就已经在离传感器一英尺的地方造成了小误差。","t":124.37},{"en":"Soon the errors will have multiplied to the ten-foot scale, and so on up to the size of the globe.","zh":"很快，这些误差将倍增到十英尺的尺度，并以此类推，直到全球范围。","t":131.94}],"vocab":[{"word":"speculative","phonetic":"/ˈspekjələtɪv/","meanings":[{"pos":"adjective","meaning":"推测的，猜测的","usage":"形容基于猜测而非确切事实的事物"}]},{"word":"worthless","phonetic":"/ˈwɜːθləs/","meanings":[{"pos":"adjective","meaning":"无价值的，没用的","usage":"用来描述没有实用价值或意义的事物"}]},{"word":"deteriorate","phonetic":"/dɪˈtɪəriəreɪt/","meanings":[{"pos":"verb","meaning":"恶化，变差","usage":"表示情况、质量等逐渐变得更差"}]},{"word":"uncertainty","phonetic":"/ʌnˈsɜːtnti/","meanings":[{"pos":"noun","meaning":"不确定性，不确定因素","usage":"指无法确定的情况或事物"}]},{"word":"multiply","phonetic":"/ˈmʌltɪplaɪ/","meanings":[{"pos":"verb","meaning":"成倍增加，大量增多","usage":"表示数量在短时间内快速增长"}]},{"word":"cascade","phonetic":"/kæˈskeɪd/","meanings":[{"pos":"verb","meaning":"连锁反应，逐级传递","usage":"描述事物像瀑布一样层层传递、影响后续环节"}]},{"word":"turbulent","phonetic":"/ˈtɜːbjələnt/","meanings":[{"pos":"adjective","meaning":"湍流的，动荡的","usage":"可形容气流、水流不稳定，也可形容局势动荡"}]},{"word":"squall","phonetic":"/skwɔːl/","meanings":[{"pos":"noun","meaning":"飑，短时强风","usage":"气象学词汇，指突发的短时间强风"}]},{"word":"eddy","phonetic":"/ˈedi/","meanings":[{"pos":"noun","meaning":"涡流，漩涡","usage":"指气流、水流的漩涡状运动"}]},{"word":"grid","phonetic":"/ɡrɪd/","meanings":[{"pos":"noun","meaning":"网格，坐标网","usage":"可指地理测量、计算模型中的网格系统"}]},{"word":"sensor","phonetic":"/ˈsensə(r)/","meanings":[{"pos":"noun","meaning":"传感器，探测设备","usage":"指用于检测、测量特定物理量的设备"}]},{"word":"humidity","phonetic":"/hjuːˈmɪdəti/","meanings":[{"pos":"noun","meaning":"湿度，湿气","usage":"气象学常用词汇，指空气中水汽的含量"}]},{"word":"meteorologist","phonetic":"/ˌmiːtiəˈrɒlədʒɪst/","meanings":[{"pos":"noun","meaning":"气象学家","usage":"指研究气象学、从事天气预报相关工作的专业人员"}]},{"word":"fluctuation","phonetic":"/ˌflʌktʃuˈeɪʃn/","meanings":[{"pos":"noun","meaning":"波动，起伏","usage":"可指数值、状态等的不规则小幅变化"}]},{"word":"deviation","phonetic":"/ˌdiːviˈeɪʃn/","meanings":[{"pos":"noun","meaning":"偏差，偏离","usage":"指和标准、平均值之间的差异"}]}],"phrases":[{"phrase":"butterfly effect","usage":"指混沌理论中初始微小变化会导致后续系统巨大连锁反应的效应，可用于描述各领域的连锁影响现象","examples":[{"en":"The butterfly effect explains why a small decision today can completely change your life path years later.","zh":"蝴蝶效应解释了为什么今天的一个小决定可能会完全改变你多年后的人生轨迹。"}]},{"phrase":"a high degree of accuracy","usage":"用来形容极高的精准度，常和predict、measure、calculate等动词搭配","examples":[{"en":"This new instrument can measure the thickness of the material with a high degree of accuracy.","zh":"这台新仪器可以极高精准度地测量材料的厚度。"}]},{"phrase":"weather forecast","usage":"表示天气预报，是日常和气象领域的常用搭配","examples":[{"en":"According to the weather forecast, there will be a heavy snowstorm this weekend.","zh":"根据天气预报，本周末会有一场强暴风雪。"}]},{"phrase":"of the order of","usage":"表示“大约，差不多”，用来描述数量的大致范围，相当于approximately","examples":[{"en":"The cost of the project is of the order of one million dollars.","zh":"这个项目的成本大约是100万美元。"}]},{"phrase":"spaced apart","usage":"表示“间隔排列”，常和表示距离的词汇搭配，说明物体之间的间距","examples":[{"en":"The chairs in the waiting room are spaced two meters apart to keep social distance.","zh":"等候室的椅子间隔两米摆放，以保持社交距离。"}]},{"phrase":"all the way to","usage":"表示“一直到”，强调路径或范围的连续性，直到某个终点","examples":[{"en":"We walked all the way to the top of the mountain to see the sunrise.","zh":"我们一路走到山顶去看日出。"}]},{"phrase":"deviation from the average","usage":"表示“与平均值的偏差”，常用于统计、测量等场景，描述和均值的差异","examples":[{"en":"The researcher recorded the deviation from the average temperature for each month last year.","zh":"研究人员记录了去年每个月的气温与平均值的偏差。"}]},{"phrase":"and so on","usage":"表示“等等，诸如此类”，用于列举未尽的同类事物","examples":[{"en":"You can find all kinds of fruits in the market: apples, bananas, oranges, and so on.","zh":"你在市场里能找到各种水果：苹果、香蕉、橙子等等。"}]}],"grammar":[{"title":"让步状语从句：even so","definition":"用来表示转折关系，意思是“即便如此，尽管这样”，引出和前文情况相反的结果","structure":"陈述事实的句子 + , and even so, + 转折后的内容","usage":"用于在承认前文事实的基础上，引出仍然存在的相反情况","examples":[{"en":"He practiced very hard for the match, and even so, he didn't win the first prize.","zh":"他为了比赛非常努力地练习，即便如此，他也没有拿到一等奖。"},{"en":"The travel agency has prepared everything for the trip, and even so, unexpected problems may still occur.","zh":"旅行社已经为旅行准备好了一切，尽管这样，还是可能会出现意外问题。"}]},{"title":"suppose引导的假设条件句","definition":"suppose表示“假设，假定”，用来引出非真实的假设条件，后面常接虚拟语气或陈述语气的假设场景","structure":"Suppose + 假设的条件句, + 假设下的结果","usage":"用于设想一个现实中不存在或尚未发生的情况，讨论其后续结果","examples":[{"en":"Suppose you had one million dollars, what would you do first?","zh":"假设你有一百万美元，你首先会做什么？"},{"en":"Suppose there is no electricity for a whole day, how will you arrange your time?","zh":"假如一整天都没有电，你会怎么安排你的时间？"}]},{"title":"插入语的用法","definition":"插入语是句子中补充说明的成分，不影响句子的主干结构，通常用破折号或逗号隔开，用来补充额外信息","structure":"句子主干 + -- 插入语 -- + 剩余主干内容","usage":"用于对句中某个内容进行补充解释，让读者更好地理解相关概念","examples":[{"en":"The cost of the activity--and by activity I mean the autumn outing--is 200 yuan per person.","zh":"这个活动的费用——我说的活动是指秋游——是每人200元。"},{"en":"The girl in red--she is my deskmate--won the first prize in the speech contest.","zh":"那个穿红衣服的女孩——她是我的同桌——在演讲比赛中拿了一等奖。"}]}],"patterns":[{"pattern":"Why do ... make it impossible to do ...?","explanation":"","original":{"en":"Why do small errors make it impossible to predict the weather system with a high degree of accuracy?","zh":"为什么小误差使得高精度预测天气系统变得不可能？"},"examples":[{"en":"Why do frequent interruptions make it impossible to finish the report on time?","zh":"为什么频繁的干扰使得按时完成报告变得不可能？"},{"en":"Why do lack of exercises make it impossible to keep a healthy body?","zh":"为什么缺乏锻炼使得保持健康的身体变得不可能？"}]},{"pattern":"Beyond ..., ... are speculative, and beyond ... they are worthless.","explanation":"","original":{"en":"Beyond two or three days, the world's best weather forecasts are speculative, and beyond six or seven they are worthless.","zh":"超过两三天，世界上最好的天气预报也具有推测性，超过六七天的预报就毫无价值了。"},"examples":[{"en":"Beyond three days, the stored fresh vegetables are not crisp enough, and beyond a week they are worthless.","zh":"超过三天，储存的新鲜蔬菜就不够脆了，超过一周就完全不能吃了。"},{"en":"Beyond two hours, the battery of the old phone lasts for, and beyond four hours it will shut down automatically.","zh":"这部旧手机的电池续航不超过两小时，超过四小时就会自动关机。"}]},{"pattern":"... will still be unable to do ...","explanation":"","original":{"en":"The computer will still be unable to predict whether Princeton, New Jersey, will have sun or rain on a day one month away.","zh":"这台计算机仍然无法预测一个月后新泽西州的普林斯顿是晴天还是雨天。"},"examples":[{"en":"Even with enough money, we will still be unable to buy back the time we have wasted.","zh":"即便有足够的钱，我们仍然无法买回已经浪费的时间。"},{"en":"Even if you apologize now, you will still be unable to change the fact that you have hurt her feelings.","zh":"即便你现在道歉，你仍然无法改变你已经伤害了她感情的事实。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“恶化，变差” 对应的单词是？","hint":"verb · /dɪˈtɪəriəreɪt/","options":["creditor","sensor","loom","deteriorate"],"answer":3,"explain":"deteriorate · /dɪˈtɪəriəreɪt/ · verb · 恶化，变差。表示情况、质量等逐渐变得更差","source":{"kind":"vocab","word":"deteriorate"},"id":"b4-u14-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：涡流，漩涡","hint":"/ˈedi/ · noun","answer":"eddy","placeholder":"输入英文单词","explain":"eddy · /ˈedi/ · noun · 涡流，漩涡。指气流、水流的漩涡状运动","source":{"kind":"vocab","word":"eddy"},"id":"b4-u14-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The _____ explains why a small decision today can completely change your life path years later.","hint":"蝴蝶效应解释了为什么今天的一个小决定可能会完全改变你多年后的人生轨迹。","answer":"butterfly effect","placeholder":"输入缺失的短语","explain":"butterfly effect：指混沌理论中初始微小变化会导致后续系统巨大连锁反应的效应，可用于描述各领域的连锁影响现象（蝴蝶效应解释了为什么今天的一个小决定可能会完全改变你多年后的人生轨迹。）","source":{"kind":"phrase","phrase":"butterfly effect"},"id":"b4-u14-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The Butterfly _____ is the reason.","hint":"蝴蝶效应就是原因。","answer":"Effect","placeholder":"输入缺失的单词","explain":"The Butterfly Effect is the reason. — 蝴蝶效应就是原因。","source":{"kind":"sentence","en":"The Butterfly Effect is the reason."},"id":"b4-u14-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“suppose表示“假设，假定”，用来引出非真实的假设条件，后面常接虚拟语气或陈述语气的假设场景” 描述的是哪个语法点？","hint":"Suppose + 假设的条件句, + 假设下的结果","options":["if引导的条件状语从句（表让步推测）","插入语","suppose引导的假设条件句","独立主格结构"],"answer":2,"explain":"suppose引导的假设条件句：Suppose + 假设的条件句, + 假设下的结果：用于设想一个现实中不存在或尚未发生的情况，讨论其后续结果","source":{"kind":"grammar","title":"suppose引导的假设条件句"},"id":"b4-u14-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nFor small pieces of weather--","hint":"","options":["因为这个年龄段的大象几乎已经准备好承担重活，可以立即开始赚钱养活自己。","但它们确实强调了一个普遍原则：驯象师与大象之间的关系是训练成功的关键。","但我所认识和尊重的那几位作家，都立刻承认他们在首次提笔写作时，对要写什么几乎没有什么概念。","对于局部天气——"],"answer":3,"explain":"For small pieces of weather-- — 对于局部天气——","source":{"kind":"sentence","en":"For small pieces of weather--"},"id":"b4-u14-q06"}]},{"id":"b4-u15","book":4,"unit":15,"key":"15","lessonFrom":15,"lessonTo":15,"title":"Secrecy in Industry","titleZh":"工业中的保密","question":"Why is secrecy particularly important in the chemical industries?","sentences":[{"en":"Two factors weigh heavily against the effectiveness of scientific research in industry.","zh":"有两个因素严重阻碍了工业中科学研究的有效性。","t":17.82},{"en":"One is the general atmosphere of secrecy in which it is carried out,","zh":"一个是它所进行的普遍保密氛围，","t":25.27},{"en":"the other the lack of freedom of the individual research worker.","zh":"另一个是单个研究人员缺乏自由。","t":31.01},{"en":"In so far as any inquiry is a secret one,","zh":"只要任何一项调查是秘密的，","t":36.05},{"en":"it naturally limits all those engaged in carrying it out from effective contact with their fellow scientists either in other countries or in universities,","zh":"它自然会限制所有从事这项工作的人与他们在其他国家或大学的同行科学家进行有效接触，","t":40.13},{"en":"or even, often enough, in other departments of the same firm.","zh":"甚至，在很多情况下，与同一公司的其他部门也无法有效接触。","t":51.21},{"en":"The degree of secrecy naturally varies considerably.","zh":"保密程度自然差异很大。","t":57.33},{"en":"Some of the bigger firms are engaged in researches which are of such general and fundamental nature","zh":"一些大公司从事的研究具有普遍性和基础性，","t":61.76},{"en":"that it is a positive advantage to them not to keep them secret.","zh":"因此不保密对他们来说是一种积极的优势。","t":69.15},{"en":"Yet a great many processes depending on such research are sought for with complete secrecy until the stage at which patents can be taken out.","zh":"然而，许多依赖此类研究的工艺在专利可以申请之前，都以完全保密的方式进行探索。","t":75.02},{"en":"Even more processes are never patented at all but kept as secret processes.","zh":"甚至更多的工艺根本不申请专利，而是作为秘密工艺保存。","t":85.75},{"en":"This applies particularly to chemical industries,","zh":"这尤其适用于化学工业，","t":92.43},{"en":"where chance discoveries play a much larger part than they do in physical and mechanical industries.","zh":"因为在化学工业中，偶然发现所起的作用远大于在物理和机械工业中。","t":97},{"en":"Sometimes the secrecy goes to such an extent that the whole nature of the research cannot be mentioned.","zh":"有时保密程度如此之高，以至于整个研究的性质都不能被提及。","t":104.51},{"en":"Many firms, for instance have great difficulty in obtaining technical or scientific books from libraries","zh":"举例来说，许多公司在从图书馆获取技术或科学书籍时面临很大困难，","t":113.17},{"en":"because they are unwilling to have their names entered as having taken out such and such a book,","zh":"因为他们不愿留下借阅某某书籍的记录，","t":120.95},{"en":"for fear the agents of other firms should be able to trace the kind of research they are likely to be undertaking.","zh":"唯恐其他公司的代理人能够据此追踪他们可能正在进行的研究类型。","t":127.65}],"vocab":[{"word":"secrecy","phonetic":"/ˈsiːkrəsi/","meanings":[{"pos":"noun","meaning":"保密；秘密状态","usage":"不可数名词，指对信息保密的行为或状态"}]},{"word":"effectiveness","phonetic":"/ɪˈfektɪvnəs/","meanings":[{"pos":"noun","meaning":"有效性；效力","usage":"不可数名词，指产生预期结果的能力"}]},{"word":"atmosphere","phonetic":"/ˈætməsfɪə(r)/","meanings":[{"pos":"noun","meaning":"氛围；环境；大气层","usage":"作“氛围”讲时可作可数或不可数名词，指周围的整体环境和感觉"}]},{"word":"inquiry","phonetic":"/ɪnˈkwaɪəri/","meanings":[{"pos":"noun","meaning":"调查；探究；询问","usage":"指为获取信息或真相进行的询问或研究"}]},{"word":"engage","phonetic":"/ɪnˈɡeɪdʒ/","meanings":[{"pos":"verb","meaning":"从事；参与；雇用；吸引","usage":"常见搭配engage in sth. 表示“从事/参与某事”；be engaged in表示“忙于，从事于”"}]},{"word":"considerably","phonetic":"/kənˈsɪdərəbli/","meanings":[{"pos":"adverb","meaning":"相当地；非常地","usage":"用于修饰形容词或动词，表示程度大"}]},{"word":"fundamental","phonetic":"/ˌfʌndəˈmentl/","meanings":[{"pos":"adjective","meaning":"基础的；根本的","usage":"用于描述事物最核心、最重要的部分"}]},{"word":"positive","phonetic":"/ˈpɒzətɪv/","meanings":[{"pos":"adjective","meaning":"积极的；肯定的；明确的","usage":"可修饰抽象名词，表示好的、有利的性质"}]},{"word":"process","phonetic":"/ˈprəʊses/","meanings":[{"pos":"noun","meaning":"工艺；流程；过程","usage":"工业领域常指生产工艺，也可泛指事情发展的过程"}]},{"word":"patent","phonetic":"/ˈpeɪtnt/","meanings":[{"pos":"noun","meaning":"专利；专利权","usage":"指对发明创造的专属使用权；也可作动词表示“获得专利”"},{"pos":"verb","meaning":"获得专利权","usage":"take out a patent为固定搭配，意为“取得专利”"}]},{"word":"mechanical","phonetic":"/məˈkænɪkl/","meanings":[{"pos":"adjective","meaning":"机械的；力学的","usage":"与机器、机械相关的，也可指行为机械呆板的"}]},{"word":"agent","phonetic":"/ˈeɪdʒənt/","meanings":[{"pos":"noun","meaning":"代理人；特工；试剂","usage":"商务领域常指代理商，文中指商业情报人员"}]},{"word":"trace","phonetic":"/treɪs/","meanings":[{"pos":"verb","meaning":"追踪；查明；追溯","usage":"指通过线索找到人或事物的来源、行踪"}]},{"word":"undertake","phonetic":"/ˌʌndəˈteɪk/","meanings":[{"pos":"verb","meaning":"从事；承担；承诺","usage":"常接task, project, research等名词，表示承担某项工作"}]}],"phrases":[{"phrase":"weigh heavily against","usage":"表示“严重不利于；对…有很大负面影响”，主语通常为不利因素，宾语为受影响的事物","examples":[{"en":"Lack of funding weighs heavily against the development of small businesses.","zh":"资金短缺严重不利于小企业的发展。"},{"en":"His lack of experience weighs heavily against his chance of getting the job.","zh":"他经验不足，这对他获得这份工作的机会非常不利。"}]},{"phrase":"in so far as","usage":"连词短语，意为“在…范围内；就…而言”，用于引导状语从句，限定论述的范围","examples":[{"en":"In so far as you are a student, you should obey the school rules.","zh":"作为学生，你应该遵守校规。"},{"en":"I will help you in so far as I can.","zh":"我会尽我所能帮助你。"}]},{"phrase":"engage in","usage":"动词短语，意为“从事；参与”，可用于主动或被动语态be engaged in","examples":[{"en":"Many college students engage in part-time jobs during holidays.","zh":"很多大学生假期会从事兼职工作。"},{"en":"He is engaged in scientific research on environmental protection.","zh":"他正从事环境保护方面的科学研究。"}]},{"phrase":"take out a patent","usage":"固定搭配，意为“取得专利权”，指为发明申请并获得专利保护","examples":[{"en":"The company decided to take out a patent for its new invention.","zh":"这家公司决定为它的新发明申请专利。"},{"en":"It took them three years to take out a patent on this new energy technology.","zh":"他们花了三年时间才取得这项新能源技术的专利。"}]},{"phrase":"apply to","usage":"此处意为“适用于；针对”，主语为规则、情况等，宾语为适用的对象","examples":[{"en":"This regulation applies to all employees, regardless of position.","zh":"这条规定适用于所有员工，不分职位高低。"},{"en":"The discount only applies to products purchased before the end of the month.","zh":"这个折扣仅适用于月底前购买的产品。"}]},{"phrase":"to such an extent that","usage":"意为“到如此程度以至于”，用于强调程度，引导结果状语从句","examples":[{"en":"The noise from the construction site was loud to such an extent that we couldn't sleep at night.","zh":"工地的噪音大到我们晚上根本睡不着觉。"},{"en":"He was absorbed in the book to such an extent that he didn't hear the doorbell.","zh":"他看书太入迷了，以至于都没听到门铃声。"}]},{"phrase":"for fear (that)","usage":"连词短语，意为“生怕；唯恐”，引导目的状语从句，从句常用虚拟语气","examples":[{"en":"She locked the door for fear that someone might break in while she was out.","zh":"她锁了门，生怕自己出门的时候有人闯进来。"},{"en":"He left an hour early for fear he might miss the train.","zh":"他提前一小时出发，唯恐赶不上火车。"}]}],"grammar":[{"title":"定语从句的省略结构","definition":"在并列结构中，当第二个分句的主语和谓语与前一分句的主语和be动词相同时，可以省略主语和be动词，仅保留剩余成分","structure":"句子1, + 名词/代词 + 其他成分（省略与前文重复的主语+be/谓语动词）","usage":"常用于对比、列举两个并列的因素、情况，使句子更简洁凝练，避免重复","examples":[{"en":"Two factors weigh heavily against the effectiveness of scientific research in industry. One is the general atmosphere of secrecy in which it is carried out, the other the lack of freedom of the individual research worker.","zh":"有两个因素严重地妨碍着工业中科学研究的效率：一是科研工作中普遍存在的保密气氛，二是研究人员缺乏个人自由。"},{"en":"There are two rooms in the apartment. One is used as a bedroom, the other as a study.","zh":"这套公寓有两个房间，一个用作卧室，另一个用作书房。"}]},{"title":"such...that...引导的结果状语从句","definition":"用于表示“如此…以至于…”，强调程度，引出前文动作或状态带来的结果","structure":"such + (a/an) + 形容词 + 可数名词单数/不可数名词/可数名词复数 + that 从句","usage":"当修饰的中心词是名词时用such，若修饰形容词或副词则用so，that引导的从句表示结果","examples":[{"en":"Some of the bigger firms are engaged in researches which are of such general and fundamental nature that it is a positive advantage to them not to keep them secret.","zh":"某些大公司进行的研究属于一般性和基础性的研究，因此不保密对它们反而更有好处。"},{"en":"It was such a cold day that we decided to stay at home.","zh":"天气太冷了，我们决定待在家里。"}]},{"title":"状语从句中的虚拟语气","definition":"在for fear that, in case, lest等引导的目的状语从句中，常用“should + 动词原形”的虚拟语气结构，表示担忧的、可能性较小的情况","structure":"主句 + for fear that / lest / in case + 主语 + should + 动词原形","usage":"用于表达“生怕、以防、唯恐”的含义，should可以省略，尤其在口语和非正式文体中","examples":[{"en":"Many firms, for instance have great difficulty in obtaining technical or scientific books from libraries because they are unwilling to have their names entered as having taken out such and such a book, for fear the agents of other firms should be able to trace the kind of research they are likely to be undertaking.","zh":"例如，许多公司很难从图书馆借到技术或科学书籍，因为它们不愿意让自己的名字被登记为借了某某类书籍，生怕其他公司的情报人员能够据此推断出他们可能正在进行的研究类型。"},{"en":"She put the umbrella in her bag for fear that it should rain in the afternoon.","zh":"她把伞放进包里，以防下午下雨。"}]}],"patterns":[{"pattern":"Two factors weigh heavily against... One is..., the other...","explanation":"","original":{"en":"Two factors weigh heavily against the effectiveness of scientific research in industry. One is the general atmosphere of secrecy in which it is carried out, the other the lack of freedom of the individual research worker.","zh":"有两个因素严重地妨碍着工业中科学研究的效率：一是科研工作中普遍存在的保密气氛，二是研究人员缺乏个人自由。"},"examples":[{"en":"Two factors weigh heavily against the popularity of the new product. One is its high price, the other its complex operation.","zh":"有两个因素严重影响这款新产品的普及：一是价格过高，二是操作复杂。"},{"en":"Two factors weigh heavily against students' learning efficiency. One is the lack of clear learning goals, the other the distraction of electronic devices.","zh":"有两个因素严重影响学生的学习效率：一是缺乏明确的学习目标，二是电子设备的干扰。"}]},{"pattern":"This applies particularly to..., where...","explanation":"","original":{"en":"This applies particularly to chemical industries, where chance discoveries play a much larger part than they do in physical and mechanical industries.","zh":"这种情况在化学工业尤其适用，在该行业中，偶然发现的作用要比在物理和机械工业中大得多。"},"examples":[{"en":"This learning method applies particularly to language learners, where enough input is the key to improvement.","zh":"这种学习方法尤其适合语言学习者，对他们来说，足量的输入是提升的关键。"},{"en":"This regulation applies particularly to small businesses, where cash flow is more vulnerable to market changes.","zh":"这项规定尤其适用于小型企业，在这类企业中，现金流更容易受市场变化的影响。"}]},{"pattern":"Sometimes the ... goes to such an extent that...","explanation":"","original":{"en":"Sometimes the secrecy goes to such an extent that the whole nature of the research cannot be mentioned.","zh":"有时保密的程度到了连研究的性质都不能提及的地步。"},"examples":[{"en":"Sometimes the competition in the industry goes to such an extent that companies cut their prices below cost.","zh":"有时行业内的竞争激烈到了公司把价格降到成本以下的程度。"},{"en":"Sometimes parents' love for their children goes to such an extent that they arrange everything for them.","zh":"有时父母对孩子的爱到了事事都为他们安排好的地步。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“有效性；效力” 对应的单词是？","hint":"noun · /ɪˈfektɪvnəs/","options":["perilous","expedition","infinite","effectiveness"],"answer":3,"explain":"effectiveness · /ɪˈfektɪvnəs/ · noun · 有效性；效力。不可数名词，指产生预期结果的能力","source":{"kind":"vocab","word":"effectiveness"},"id":"b4-u15-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：追踪；查明；追溯","hint":"/treɪs/ · verb","answer":"trace","placeholder":"输入英文单词","explain":"trace · /treɪs/ · verb · 追踪；查明；追溯。指通过线索找到人或事物的来源、行踪","source":{"kind":"vocab","word":"trace"},"id":"b4-u15-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He was absorbed in the book _____ he didn't hear the doorbell.","hint":"他看书太入迷了，以至于都没听到门铃声。","answer":"to such an extent that","placeholder":"输入缺失的短语","explain":"to such an extent that：意为“到如此程度以至于”，用于强调程度，引导结果状语从句（他看书太入迷了，以至于都没听到门铃声。）","source":{"kind":"phrase","phrase":"to such an extent that"},"id":"b4-u15-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：or even, often enough, in other departments of the same _____","hint":"甚至，在很多情况下，与同一公司的其他部门也无法有效接触。","answer":"firm","placeholder":"输入缺失的单词","explain":"or even, often enough, in other departments of the same firm. — 甚至，在很多情况下，与同一公司的其他部门也无法有效接触。","source":{"kind":"sentence","en":"or even, often enough, in other departments of the same firm."},"id":"b4-u15-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于表示“如此…以至于…”，强调程度，引出前文动作或状态带来的结果” 描述的是哪个语法点？","hint":"such + (a/an) + 形容词 + 可数名词单数/不可数名词/可数名词复数 + that 从句","options":["such...that...引导的结果状语从句","破折号的解释说明用法","时间状语从句 (Adverbial Clause of Time)","主语从句作主语的结构"],"answer":0,"explain":"such...that...引导的结果状语从句：such + (a/an) + 形容词 + 可数名词单数/不可数名词/可数名词复数 + that 从句：当修饰的中心词是名词时用such，若修饰形容词或副词则用so，that引导的从句表示结果","source":{"kind":"grammar","title":"such...that...引导的结果状语从句"},"id":"b4-u15-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIn so far as any inquiry is a secret one,","hint":"","options":["它们可以定位并避开障碍物——或者定位它们赖以为食的飞行昆虫。","只要任何一项调查是秘密的，","那些与平均值微小的偏差。","由于海洋覆盖了地球表面的大部分，"],"answer":1,"explain":"In so far as any inquiry is a secret one, — 只要任何一项调查是秘密的，","source":{"kind":"sentence","en":"In so far as any inquiry is a secret one,"},"id":"b4-u15-q06"}]},{"id":"b4-u16","book":4,"unit":16,"key":"16","lessonFrom":16,"lessonTo":16,"title":"The Modern City","titleZh":"现代城市","question":"What is the author's main argument about the modern city?","sentences":[{"en":"In the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected.","zh":"在工业生活的组织中，工厂对工人生理和心理状态的影响已被完全忽视。","t":15.45},{"en":"Modern industry is based on the conception of the maximum production at lowest cost,","zh":"现代工业建立在以最低成本实现最大产量的概念上，","t":26.73},{"en":"in order that an individual or a group of individuals may earn as much money as possible.","zh":"以便个人或群体能够尽可能多地赚钱。","t":33.05},{"en":"It has expanded without any idea of the true nature of the human beings who run the machines,","zh":"它的扩张，完全没有考虑到操作机器的人类的真实本性，","t":40.09},{"en":"and without giving any consideration to the effects produced on the individuals and on their descendants by the artificial mode of existence imposed by the factory.","zh":"也完全没有考虑到工厂强加的人工生存模式对个体及其后代产生的影响。","t":46.55},{"en":"The great cities have been built with no regard for us.","zh":"那些大城市的建设完全没有考虑到我们。","t":58.63},{"en":"The shape and dimensions of the skyscrapers depend entirely on the necessity of obtaining the maximum income per square foot of ground,","zh":"摩天大楼的形状和尺寸完全取决于每平方英尺土地获取最大收入的需要，","t":62.65},{"en":"and of offering to the tenants offices and apartments that please them.","zh":"以及向租户提供令他们满意的办公室和公寓。","t":71.68},{"en":"This caused the construction of gigantic buildings where too large masses of human beings are crowded together.","zh":"这导致了巨型建筑的建造，大量人类被拥挤在一起。","t":76.53},{"en":"Civilized men like such a way of living.","zh":"文明人喜欢这样的生活方式。","t":84.66},{"en":"While they enjoy the comfort and banal luxury of their dwelling, they do not realize that they are deprived of the necessities of life.","zh":"当他们享受着住所的舒适和平庸的奢华时，却没有意识到他们被剥夺了生活必需品。","t":87.97},{"en":"The modern city consists of monstrous edifices and of dark, narrow streets full of petrol fumes and toxic gases,","zh":"现代城市由怪诞的建筑和充满汽油烟雾和有毒气体的黑暗狭窄街道组成，","t":97.06},{"en":"torn by the noise of the taxicabs, lorries and buses, and thronged ceaselessly by great crowds.","zh":"被出租车、卡车和公共汽车的噪音撕裂，并不断被大量人群挤满。","t":106.2},{"en":"Obviously, it has not been planned for the good of its inhabitants.","zh":"显然，它的规划并非为了居民的福祉。","t":114.58}],"vocab":[{"word":"physiological","phonetic":"/ˌfɪziəˈlɒdʒɪkl/","meanings":[{"pos":"adjective","meaning":"生理的，生理学的","usage":"用于描述与生物身体机能相关的特性或状态，常修饰state、reaction、function等名词"}]},{"word":"conception","phonetic":"/kənˈsepʃn/","meanings":[{"pos":"noun","meaning":"概念，观念；构想","usage":"指对某事物的抽象理解或想法，常搭配have a conception of（对……有概念）"}]},{"word":"maximum","phonetic":"/ˈmæksɪməm/","meanings":[{"pos":"adjective","meaning":"最大的，最高的","usage":"修饰数量、程度等名词，反义词为minimum"},{"pos":"noun","meaning":"最大值，最大限度","usage":"可作主语或宾语，搭配reach a maximum（达到最大值）"}]},{"word":"descendant","phonetic":"/dɪˈsendənt/","meanings":[{"pos":"noun","meaning":"后裔，后代，子孙","usage":"指某人的后代子嗣，也可引申为某事物的衍生物，常搭配of表示所属关系"}]},{"word":"artificial","phonetic":"/ˌɑːtɪˈfɪʃl/","meanings":[{"pos":"adjective","meaning":"人工的，人造的；人为的","usage":"强调非自然产生的，可修饰物质、环境、行为等，反义词为natural"}]},{"word":"impose","phonetic":"/ɪmˈpəʊz/","meanings":[{"pos":"verb","meaning":"强加，迫使（接受）；征收","usage":"常用搭配impose sth on sb（把某物/某事强加给某人）"}]},{"word":"dimension","phonetic":"/daɪˈmenʃn/","meanings":[{"pos":"noun","meaning":"尺寸，规模；维度","usage":"常用复数dimensions表示物体的长宽高、规模大小，也可指抽象的“方面”"}]},{"word":"skyscraper","phonetic":"/ˈskaɪskreɪpə(r)/","meanings":[{"pos":"noun","meaning":"摩天大楼","usage":"指城市中非常高的多层建筑，为可数名词"}]},{"word":"tenant","phonetic":"/ˈtenənt/","meanings":[{"pos":"noun","meaning":"租户，承租人，房客","usage":"指租用房屋、土地等的人，对应词为landlord（房东）"}]},{"word":"gigantic","phonetic":"/dʒaɪˈɡæntɪk/","meanings":[{"pos":"adjective","meaning":"巨大的，庞大的","usage":"语气强于big/large，可修饰具体事物或抽象概念，如gigantic task（艰巨的任务）"}]},{"word":"banal","phonetic":"/bəˈnɑːl/","meanings":[{"pos":"adjective","meaning":"平庸的，乏味的，陈腐的","usage":"含贬义，用于描述缺乏新意、平淡无奇的事物"}]},{"word":"deprive","phonetic":"/dɪˈpraɪv/","meanings":[{"pos":"verb","meaning":"剥夺，使丧失","usage":"固定搭配deprive sb of sth（剥夺某人的某物/使某人失去某物）"}]},{"word":"monstrous","phonetic":"/ˈmɒnstrəs/","meanings":[{"pos":"adjective","meaning":"巨大而丑陋的，骇人的；荒谬的","usage":"常带有负面感情色彩，修饰体积庞大、外形怪异或不合常理的事物"}]},{"word":"edifice","phonetic":"/ˈedɪfɪs/","meanings":[{"pos":"noun","meaning":"大厦，宏伟建筑","usage":"正式用语，指规模宏大、结构复杂的建筑物，也可引申为抽象的体系"}]},{"word":"throng","phonetic":"/θrɒŋ/","meanings":[{"pos":"verb","meaning":"挤满，拥塞","usage":"常用被动形式be thronged with（挤满了……）"},{"pos":"noun","meaning":"人群，群众","usage":"指大量聚集的人群，搭配a throng of（一大群）"}]}],"phrases":[{"phrase":"be based on","usage":"表示“以……为基础，根据……”，主语通常为理论、制度、项目等抽象事物，介词on后接基础依据","examples":[{"en":"Modern industry is based on the conception of the maximum production at lowest cost.","zh":"现代工业建立在以最低成本实现最高产量的理念之上。"},{"en":"The research paper is based on three years of field investigation.","zh":"这篇研究论文是以三年的实地调查为基础完成的。"}]},{"phrase":"in order that","usage":"引导目的状语从句，意为“为了，以便”，从句中常搭配may、might、can、could等情态动词，可与in order to do结构转换","examples":[{"en":"Modern industry runs in order that individuals may earn as much money as possible.","zh":"现代工业的运转是为了让个人能够尽可能多地赚钱。"},{"en":"He left home early in order that he could catch the first train to the town.","zh":"他早早出门，以便能赶上开往镇上的第一班火车。"}]},{"phrase":"give consideration to","usage":"表示“考虑到，顾及”，正式用语，可替换为take into consideration，to为介词，后接名词或动名词","examples":[{"en":"Factories do not give consideration to the effects of their artificial mode of existence on workers.","zh":"工厂没有顾及它们强加的人为生存模式对工人造成的影响。"},{"en":"When planning the project, we must give full consideration to the needs of local residents.","zh":"规划这个项目时，我们必须充分考虑当地居民的需求。"}]},{"phrase":"with no regard for","usage":"表示“不顾，不考虑”，含贬义，指做某事时完全不顾及相关的人或后果，可替换为without regard to","examples":[{"en":"The great cities have been built with no regard for us.","zh":"大城市的建造完全没有顾及我们的需求。"},{"en":"Some companies pursue profit with no regard for environmental protection.","zh":"一些公司追逐利润，完全不顾环境保护。"}]},{"phrase":"depend on","usage":"表示“取决于，依赖”，后可接名词或从句，可用于说明事物的决定因素或人对他人/物的依赖","examples":[{"en":"The shape and dimensions of the skyscrapers depend entirely on the necessity of obtaining the maximum income.","zh":"摩天大楼的形状和规模完全取决于获取最高收入的需求。"},{"en":"Whether we will go hiking this weekend depends on the weather.","zh":"我们这周末是否去远足取决于天气情况。"}]},{"phrase":"be deprived of","usage":"被动结构，意为“被剥夺，失去”，主语通常是人，of后接被剥夺的事物，主动形式为deprive sb of sth","examples":[{"en":"City dwellers do not realize that they are deprived of the necessities of life.","zh":"城市居民没有意识到他们被剥夺了生活的必需品。"},{"en":"Many children in remote areas were deprived of educational opportunities in the past.","zh":"过去，很多偏远地区的孩子失去了受教育的机会。"}]},{"phrase":"consist of","usage":"表示“由……组成，由……构成”，不用于被动语态和进行时态，主语为整体，of后接组成部分","examples":[{"en":"The modern city consists of monstrous edifices and dark, narrow streets.","zh":"现代城市由丑陋的巨大建筑和阴暗狭窄的街道组成。"},{"en":"The research team consists of three professors and five graduate students.","zh":"这个研究团队由三名教授和五名研究生组成。"}]},{"phrase":"be torn by","usage":"被动结构，意为“被……扰乱，受……撕裂”，可描述地点受噪音干扰，也可描述国家、组织受冲突影响","examples":[{"en":"The city streets are torn by the noise of the taxicabs, lorries and buses.","zh":"城市街道被出租车、卡车和公交车的噪音扰乱。"},{"en":"The small country was torn by years of civil war.","zh":"这个小国因多年的内战而四分五裂。"}]},{"phrase":"be thronged by","usage":"被动结构，意为“挤满了，被……拥堵”，主语通常为地点，介词by后接人群，也可用be thronged with结构","examples":[{"en":"The streets are thronged ceaselessly by great crowds.","zh":"街道上永远挤满了熙熙攘攘的人群。"},{"en":"During the Spring Festival, the railway station is thronged by passengers going home.","zh":"春节期间，火车站挤满了返乡的旅客。"}]}],"grammar":[{"title":"并列状语成分的使用","definition":"在句子中可以使用多个并列的介词短语、分词短语等作状语，共同修饰谓语动词，说明动作发生的背景、伴随情况等，通常用and连接最后两个并列成分","structure":"主语 + 谓语 + 状语1 + and + 状语2","usage":"用于丰富句子信息，从多个角度描述动作的相关条件、伴随状态或补充说明，避免拆分多个短句导致表达零散","examples":[{"en":"It has expanded without any idea of the true nature of the human beings who run the machines, and without giving any consideration to the effects produced on the individuals.","zh":"它（工业）在扩张时完全不了解操作机器的人的本质，也完全不考虑对个人造成的影响。"},{"en":"He walked into the room with a smile on his face and with a bunch of flowers in his hand.","zh":"他脸上带着笑，手里捧着一束花，走进了房间。"}]},{"title":"while引导的让步状语从句","definition":"while除了引导时间状语从句表示“当……的时候”，还可以引导让步状语从句，意为“虽然，尽管”，通常放在句首，主句说明与从句内容相反的事实","structure":"While + 从句（陈述事实）, 主句（转折内容）","usage":"用于对比两种相反的情况，突出主句内容的不合理性或出人意料，语气较although更温和，多用于书面语","examples":[{"en":"While they enjoy the comfort and banal luxury of their dwelling, they do not realize that they are deprived of the necessities of life.","zh":"虽然他们享受着住所的舒适和平庸的奢华，却没有意识到自己被剥夺了生活的必需品。"},{"en":"While the work is very challenging, it has also brought me a great sense of achievement.","zh":"尽管这份工作很有挑战性，它也给我带来了很大的成就感。"}]}],"patterns":[{"pattern":"In the organization of ... the influence of ... upon ... has been completely neglected.","explanation":"","original":{"en":"In the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected.","zh":"在工业生活的组织中，工厂对工人生理和精神状态的影响被完全忽视了。"},"examples":[{"en":"In the design of online courses the influence of long screen time upon the physical health of teenagers has been completely neglected.","zh":"在网课的设计中，长时间看屏幕对青少年身体健康的影响被完全忽视了。"},{"en":"In the development of tourist attractions the influence of over-exploitation upon the local ecosystem has been completely neglected.","zh":"在旅游景点的开发中，过度开发对当地生态系统的影响被完全忽视了。"}]},{"pattern":"... depend entirely on the necessity of ... and of ...","explanation":"","original":{"en":"The shape and dimensions of the skyscrapers depend entirely on the necessity of obtaining the maximum income per square foot of ground, and of offering to the tenants offices and apartments that please them.","zh":"摩天大楼的形状和规模完全取决于两个需求：一是获取每平方英尺土地的最高收益，二是向租户提供令他们满意的办公室和公寓。"},"examples":[{"en":"The content and length of the training course depend entirely on the necessity of improving employees' work skills, and of helping them adapt to the new business system.","zh":"培训课程的内容和时长完全取决于两个需求：一是提升员工的工作技能，二是帮助他们适应新的业务系统。"},{"en":"The location and scale of the new library depend entirely on the necessity of meeting the reading needs of nearby residents, and of holding public cultural activities regularly.","zh":"新图书馆的选址和规模完全取决于两个需求：一是满足附近居民的阅读需求，二是定期举办公共文化活动。"}]},{"pattern":"Obviously, it has not been planned for the good of ...","explanation":"","original":{"en":"Obviously, it has not been planned for the good of its inhabitants.","zh":"显然，它（现代城市）的规划并不是为了居民的利益。"},"examples":[{"en":"Obviously, the new traffic rule has not been implemented for the good of ordinary commuters.","zh":"显然，这项新的交通规则的实施并不是为了普通通勤者的利益。"},{"en":"Obviously, the school's new regulation has not been made for the good of students' all-round development.","zh":"显然，学校的这条新规定的制定并不是为了学生的全面发展。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“人工的，人造的；人为的” 对应的单词是？","hint":"adjective · /ˌɑːtɪˈfɪʃl/","options":["artificial","voltage","distribution","striking"],"answer":0,"explain":"artificial · /ˌɑːtɪˈfɪʃl/ · adjective · 人工的，人造的；人为的。强调非自然产生的，可修饰物质、环境、行为等，反义词为natural","source":{"kind":"vocab","word":"artificial"},"id":"b4-u16-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：生理的，生理学的","hint":"/ˌfɪziəˈlɒdʒɪkl/ · adjective","answer":"physiological","placeholder":"输入英文单词","explain":"physiological · /ˌfɪziəˈlɒdʒɪkl/ · adjective · 生理的，生理学的。用于描述与生物身体机能相关的特性或状态，常修饰state、reaction、function等名词","source":{"kind":"vocab","word":"physiological"},"id":"b4-u16-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Modern industry runs _____ individuals may earn as much money as possible.","hint":"现代工业的运转是为了让个人能够尽可能多地赚钱。","answer":"in order that","placeholder":"输入缺失的短语","explain":"in order that：引导目的状语从句，意为“为了，以便”，从句中常搭配may、might、can、could等情态动词，可与in order to do结构转换（现代工业的运转是为了让个人能够尽可能多地赚钱。）","source":{"kind":"phrase","phrase":"in order that"},"id":"b4-u16-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Civilized men like such a way of _____","hint":"文明人喜欢这样的生活方式。","answer":"living","placeholder":"输入缺失的单词","explain":"Civilized men like such a way of living. — 文明人喜欢这样的生活方式。","source":{"kind":"sentence","en":"Civilized men like such a way of living."},"id":"b4-u16-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“while除了引导时间状语从句表示“当……的时候”，还可以引导让步状语从句，意为“虽然，尽管”，通常放在句首，主句说明与从句内容相反的事实” 描述的是哪个语法点？","hint":"While + 从句（陈述事实）, 主句（转折内容）","options":["such...that...引导的结果状语从句","让步状语从句（however引导）","while引导的让步状语从句","条件状语从句 (Adverbial Clause of Condition)"],"answer":2,"explain":"while引导的让步状语从句：While + 从句（陈述事实）, 主句（转折内容）：用于对比两种相反的情况，突出主句内容的不合理性或出人意料，语气较although更温和，多用于书面语","source":{"kind":"grammar","title":"while引导的让步状语从句"},"id":"b4-u16-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIn the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected.","hint":"","options":["或脱离它会变成一只鸟的文学观念。","但这个年龄的动物不容易顺从人类，所以在早期阶段必须采用非常强硬的手段。","从研究生命起源的那些人的工作中，我们必须得出结论，","在工业生活的组织中，工厂对工人生理和心理状态的影响已被完全忽视。"],"answer":3,"explain":"In the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected. — 在工业生活的组织中，工厂对工人生理和心理状态的影响已被完全忽视。","source":{"kind":"sentence","en":"In the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected."},"id":"b4-u16-q06"}]},{"id":"b4-u17","book":4,"unit":17,"key":"17","lessonFrom":17,"lessonTo":17,"title":"A Man-made Disease","titleZh":"人为的疾病","question":"What factor helped to spread the disease of myxomatosis?","sentences":[{"en":"In the early days of the settlement of Australia, enterprising settlers unwisely introduced the European rabbit.","zh":"在澳大利亚早期定居时，富有进取心的定居者不明智地引进了欧洲兔。","t":18.28},{"en":"This rabbit had no natural enemies in the Antipodes, so that it multiplied with that promiscuous abandon characteristic of rabbits.","zh":"这种兔子在大洋洲没有天敌，因此它以兔子特有的滥交放纵方式大量繁殖。","t":28.42},{"en":"It overran a whole continent.","zh":"它遍布了整个大陆。","t":40.42},{"en":"It caused devastation by burrowing and by devouring the herbage which might have maintained millions of sheep and cattle.","zh":"它通过挖洞和吞食草料造成了破坏，这些草料本可以养活数百万只绵羊和牛。","t":43.87},{"en":"Scientists discovered that this particular variety of rabbit (and apparently no other animal) was susceptible to a fatal virus disease, myxomatosis.","zh":"科学家发现，这种特殊品种的兔子（显然没有其他动物）易感染一种致命的病毒性疾病——黏液瘤病。","t":52.99},{"en":"By infecting animals and letting them loose in the burrows, local epidemics of this disease could be created.","zh":"通过感染动物并将它们释放到洞穴中，可以制造这种疾病的局部流行。","t":66.84},{"en":"Later it was found that there was a type of mosquito which acted as the carrier of this disease and passed it on to the rabbits.","zh":"后来发现有一种蚊子充当这种疾病的载体，并将其传播给兔子。","t":75.06},{"en":"So while the rest of the world was trying to get rid of mosquitoes, Australia was encouraging this one.","zh":"因此，当世界其他地方都在努力消灭蚊子时，澳大利亚却在鼓励这种蚊子。","t":83.84},{"en":"It effectively spread the disease all over the continent and drastically reduced the rabit population.","zh":"它有效地将疾病传播到整个大陆，并大幅减少了兔子数量。","t":91.14},{"en":"It later became apparent that rabbits were developing a degree of resistance to this disease,","zh":"后来，很明显兔子对这种疾病正在产生一定程度的抵抗力，","t":99.62},{"en":"so that the rabbit population was unlikely to be completely exterminated.","zh":"因此兔子种群不太可能被完全消灭。","t":105.88},{"en":"There were hopes, however, that the problem of the rabbit would become manageable.","zh":"然而，人们希望兔子的（鼠害）问题能够变得可控。","t":111.88},{"en":"Ironically, Europe, which had bequeathed the rabbit as a pest to Australia, acquired this man-made disease as a pestilence.","zh":"具有讽刺意味的是，欧洲将兔子作为害虫遗赠给澳大利亚，现在却将这种人为的疾病视为一场瘟疫。","t":118.72},{"en":"A French physician decided to get rid of the wild rabbits on his own estate and introduced myxomatosis.","zh":"一位法国医生决定清除自己庄园里的野兔，并引入了黏液瘤病。","t":129.37},{"en":"It did not, however, remain within the confines of this estate.","zh":"然而，它并没有局限于这个庄园。","t":137.03},{"en":"It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful food supply,","zh":"它传播到法国，在那里野兔通常不被视为害虫，而是作为一项运动和有用的食物来源，","t":142.13},{"en":"and it spread to Britain where wild rabbits are regarded as a pest but where domesticated rabbits,","zh":"并传播到英国，在那里野兔被视为害虫，但家养兔子，","t":151.53},{"en":"equally susceptible to the disease, are the basis of a profitable fur industry.","zh":"同样易受这种疾病感染，却是利润丰厚的毛皮产业的基础。","t":158.62},{"en":"The question became one of whether Man could control the disease he had invented.","zh":"问题变成了人类是否能够控制他所制造的疾病。","t":165.5}],"vocab":[{"word":"enterprising","phonetic":"/ˈentəpraɪzɪŋ/","meanings":[{"pos":"adjective","meaning":"有事业心的，有进取心的，有开拓精神的","usage":"用来形容人有创新能力、愿意尝试新方法来获得成功"}]},{"word":"promiscuous","phonetic":"/prəˈmɪskjuəs/","meanings":[{"pos":"adjective","meaning":"不加选择的，杂乱的；交配随意的","usage":"可指行为没有选择性，也可指生物繁殖时没有固定配偶"}]},{"word":"abandon","phonetic":"/əˈbændən/","meanings":[{"pos":"noun","meaning":"放任，放纵","usage":"指毫无约束的随性状态，常用搭配with abandon"},{"pos":"verb","meaning":"放弃，遗弃","usage":"指主动丢弃、离开原本的人或事物"}]},{"word":"overrun","phonetic":"/ˌəʊvəˈrʌn/","meanings":[{"pos":"verb","meaning":"泛滥，横行；肆虐","usage":"指大量生物迅速蔓延占领某个区域，常用被动语态be overrun with/by"}]},{"word":"devastation","phonetic":"/ˌdevəˈsteɪʃn/","meanings":[{"pos":"noun","meaning":"破坏，毁坏","usage":"指大面积的严重破坏，程度较强"}]},{"word":"burrow","phonetic":"/ˈbʌrəʊ/","meanings":[{"pos":"verb","meaning":"挖洞，掘穴","usage":"指动物在地下挖洞穴居住"},{"pos":"noun","meaning":"（动物挖掘的）洞穴，地洞","usage":"特指兔子、狐狸等动物挖的地下洞穴"}]},{"word":"herbage","phonetic":"/ˈhɜːbɪdʒ/","meanings":[{"pos":"noun","meaning":"草，草本植物（尤指牧草）","usage":"集合名词，指可作为牲畜饲料的草本植物总称"}]},{"word":"susceptible","phonetic":"/səˈseptəbl/","meanings":[{"pos":"adjective","meaning":"易受影响的，易感染（疾病）的","usage":"常用搭配be susceptible to sth.，指对某种疾病或影响没有抵抗力"}]},{"word":"epidemic","phonetic":"/ˌepɪˈdemɪk/","meanings":[{"pos":"noun","meaning":"传染病，流行病；（坏事的）泛滥，盛行","usage":"指在某一地区大范围传播的疾病，也可指不良现象的普遍蔓延"}]},{"word":"carrier","phonetic":"/ˈkæriə(r)/","meanings":[{"pos":"noun","meaning":"带菌者，传播媒介；运输工具","usage":"医学上指携带病原体、会传播疾病的生物或物体"}]},{"word":"drastically","phonetic":"/ˈdræstɪkli/","meanings":[{"pos":"adverb","meaning":"急剧地，大幅度地","usage":"用来强调变化的程度非常大、速度非常快"}]},{"word":"exterminate","phonetic":"/ɪkˈstɜːmɪneɪt/","meanings":[{"pos":"verb","meaning":"消灭，根除，灭绝","usage":"指彻底杀光某一整个群体的生物，对象通常是害虫、有害动物等"}]},{"word":"bequeath","phonetic":"/bɪˈkwiːð/","meanings":[{"pos":"verb","meaning":"把…遗赠给；流传，遗留","usage":"可以指遗嘱中遗留财产，也可指历史上留下的事物（多为负面）"}]},{"word":"pestilence","phonetic":"/ˈpestɪləns/","meanings":[{"pos":"noun","meaning":"瘟疫，疫病（致命的流行性传染病）","usage":"文学或正式用语，指致死率极高的大范围传染病"}]},{"word":"domesticated","phonetic":"/dəˈmestɪkeɪtɪd/","meanings":[{"pos":"adjective","meaning":"驯化的，家养的","usage":"形容动物经过人类培育，不再适合野外生存"}]}],"phrases":[{"phrase":"with abandon","usage":"表示“肆意地，放纵地”，用来描述行为毫无约束、随心所欲的状态","examples":[{"en":"The tourists cheered with abandon when the parade began.","zh":"游行开始时，游客们尽情欢呼。"},{"en":"Children were splashing in the water with complete abandon.","zh":"孩子们毫无顾忌地在水里嬉闹泼水。"}]},{"phrase":"be susceptible to","usage":"表示“易受…影响，易感染…（疾病）”，to为介词，后接名词或动名词","examples":[{"en":"People with weak immune systems are more susceptible to the flu.","zh":"免疫系统较弱的人更容易感染流感。"},{"en":"Teenagers are often susceptible to peer pressure.","zh":"青少年往往容易受到同伴压力的影响。"}]},{"phrase":"get rid of","usage":"表示“摆脱，除去，处理掉”，后接不需要的人或事物","examples":[{"en":"We need to get rid of all the old furniture in the apartment.","zh":"我们需要把公寓里所有的旧家具都处理掉。"},{"en":"It took me a month to get rid of my cough.","zh":"我花了一个月时间才治好咳嗽。"}]},{"phrase":"act as","usage":"表示“充当，担任，起…作用”，后接表示身份、功能的名词","examples":[{"en":"She agreed to act as our interpreter during the trip.","zh":"她同意在旅行期间充当我们的翻译。"},{"en":"The lemon juice acts as a natural preservative for the jam.","zh":"柠檬汁在果酱里起到天然防腐剂的作用。"}]},{"phrase":"pass sth. on to","usage":"表示“把…传递给，把…传染给”，强调物品、疾病或信息的传递","examples":[{"en":"Please pass this message on to all the team members.","zh":"请把这条消息传达给所有团队成员。"},{"en":"The virus can be passed on to others through close contact.","zh":"这种病毒可以通过密切接触传染给其他人。"}]},{"phrase":"within the confines of","usage":"表示“在…的范围之内，在…的边界内”，confine常用复数形式表示界限、限制","examples":[{"en":"All the activities will take place within the confines of the campus.","zh":"所有活动都将在校园范围内进行。"},{"en":"He felt trapped within the confines of his boring daily routine.","zh":"他觉得自己被困在枯燥的日常琐事的牢笼里。"}]},{"phrase":"be regarded as","usage":"表示“被认为是，被看作是”，是被动语态结构，用来表达人们对事物的普遍看法","examples":[{"en":"This novel is regarded as one of the greatest works of the 20th century.","zh":"这部小说被认为是20世纪最伟大的作品之一。"},{"en":"In many cultures, the tiger is regarded as a symbol of courage.","zh":"在很多文化中，老虎被看作是勇气的象征。"}]},{"phrase":"the basis of","usage":"表示“…的基础”，常用搭配be the basis of/for sth.","examples":[{"en":"Mutual trust is the basis of a good relationship.","zh":"相互信任是良好关系的基础。"},{"en":"The research was done on the basis of hundreds of interviews.","zh":"这项研究是在数百次采访的基础上完成的。"}]}],"grammar":[{"title":"so that引导的结果状语从句","definition":"用来表示主句动作所产生的结果，通常翻译为“因此，所以，结果是”","structure":"主句 + so that + 结果状语从句","usage":"说明主句行为带来的直接后果，从句和主句之间存在明确的因果关系，从句前通常有逗号和主句隔开","examples":[{"en":"This rabbit had no natural enemies in the Antipodes, so that it multiplied with that promiscuous abandon characteristic of rabbits.","zh":"这种兔子在澳新地区没有天敌，因此就像兔子的特性那样，不加节制地大量繁殖。"},{"en":"I forgot to take my keys, so that I had to wait outside until my mom came back.","zh":"我忘了带钥匙，所以只好在外面等到我妈妈回来。"},{"en":"He left home very early, so that he caught the first train without any trouble.","zh":"他很早就出门了，因此毫不费力地赶上了第一班火车。"}]},{"title":"非限制性定语从句","definition":"对先行词进行补充说明，去掉之后不影响主句的完整意思，通常和主句之间用逗号隔开","structure":"主句 + , + which/who/whose/where + 从句","usage":"可以修饰前面的某个名词，也可以修饰整个主句的内容，不用that引导","examples":[{"en":"It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful food supply.","zh":"这种疾病传遍了法国，在那里野兔通常不被看作是有害动物，而是狩猎娱乐的目标和有用的食物来源。"},{"en":"The old house, which was built 100 years ago, is still in good condition.","zh":"这座老房子建于100年前，现在状况仍然很好。"},{"en":"Our guide, who was born in the nearby village, knew all the best hiking routes.","zh":"我们的向导出生在附近的村子，知道所有最好的徒步路线。"}]},{"title":"it作形式主语的主语从句","definition":"当主语是较长的从句时，为了避免句子头重脚轻，用it作形式主语放在句首，真正的主语从句放在句子后面","structure":"It + be + 形容词/名词 + that + 真正的主语从句","usage":"常见的形容词有obvious, apparent, clear, possible, strange等，用来表达“…是很明显/可能的”","examples":[{"en":"It later became apparent that rabbits were developing a degree of resistance to this disease.","zh":"后来人们发现，兔子对这种疾病逐渐产生了一定的抵抗力。"},{"en":"It is important that we should finish the task before the deadline.","zh":"我们要在截止日期前完成任务，这一点很重要。"},{"en":"It is a pity that you missed the wonderful concert last night.","zh":"你错过了昨晚那场精彩的音乐会，真可惜。"}]}],"patterns":[{"pattern":"Ironically, + 主句 + which引导的非限制性定语从句, + 谓语 + 结果","explanation":"","original":{"en":"Ironically, Europe, which had bequeathed the rabbit as a pest to Australia, acquired this man-made disease as a pestilence.","zh":"讽刺的是，把兔子作为有害动物传给澳大利亚的欧洲，反而染上了这种人造的瘟疫。"},"examples":[{"en":"Ironically, the library, which was supposed to encourage people to read more, closes on weekends when most people are free.","zh":"讽刺的是，本应鼓励人们多读书的图书馆，在大多数人有空的周末却闭馆。"},{"en":"Ironically, the invention, which was designed to make people closer, makes many of us communicate less face to face.","zh":"讽刺的是，这项本为拉近人们距离而设计的发明，反而让我们很多人更少面对面交流了。"}]},{"pattern":"The question became one of whether + 从句","explanation":"","original":{"en":"The question became one of whether Man could control the disease he had invented.","zh":"问题演变成了人类能否控制自己发明的这种疾病。"},"examples":[{"en":"The problem became one of whether we can raise enough money for the project.","zh":"问题演变成了我们能否为这个项目筹集到足够的资金。"},{"en":"The discussion became one of whether we should change our original plan at the last minute.","zh":"讨论演变成了我们是否应该在最后一刻改变原定计划。"}]},{"pattern":"Sth. did not, however, remain within the confines of + 范围","explanation":"","original":{"en":"It did not, however, remain within the confines of this estate.","zh":"然而，这种疾病并没有停留在他的庄园范围内。"},"examples":[{"en":"The small conflict did not, however, remain within the confines of the two villages.","zh":"然而，这场小冲突并没有局限在两个村子的范围内。"},{"en":"The good news did not, however, remain within the confines of the small office.","zh":"然而，这个好消息并没有只在这个小办公室里流传。"}]},{"pattern":"There were hopes, however, that + 同位语从句","explanation":"","original":{"en":"There were hopes, however, that the problem of the rabbit would become manageable.","zh":"不过，人们还是有希望认为兔子的问题会变得可控。"},"examples":[{"en":"There were hopes, however, that the missing hiker would be found before dark.","zh":"不过，人们还是有希望在天黑前找到失踪的徒步旅行者。"},{"en":"There were hopes, however, that the local government would take measures to reduce the air pollution.","zh":"不过，人们还是有希望当地政府会采取措施减少空气污染。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“破坏，毁坏” 对应的单词是？","hint":"noun · /ˌdevəˈsteɪʃn/","options":["accumulation","pact","devastation","significance"],"answer":2,"explain":"devastation · /ˌdevəˈsteɪʃn/ · noun · 破坏，毁坏。指大面积的严重破坏，程度较强","source":{"kind":"vocab","word":"devastation"},"id":"b4-u17-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：易受影响的，易感染（疾病）的","hint":"/səˈseptəbl/ · adjective","answer":"susceptible","placeholder":"输入英文单词","explain":"susceptible · /səˈseptəbl/ · adjective · 易受影响的，易感染（疾病）的。常用搭配be susceptible to sth.，指对某种疾病或影响没有抵抗力","source":{"kind":"vocab","word":"susceptible"},"id":"b4-u17-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：We need to _____ all the old furniture in the apartment.","hint":"我们需要把公寓里所有的旧家具都处理掉。","answer":"get rid of","placeholder":"输入缺失的短语","explain":"get rid of：表示“摆脱，除去，处理掉”，后接不需要的人或事物（我们需要把公寓里所有的旧家具都处理掉。）","source":{"kind":"phrase","phrase":"get rid of"},"id":"b4-u17-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful _____ supply,","hint":"它传播到法国，在那里野兔通常不被视为害虫，而是作为一项运动和有用的食物来源，","answer":"food","placeholder":"输入缺失的单词","explain":"It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful food supply, — 它传播到法国，在那里野兔通常不被视为害虫，而是作为一项运动和有用的食物来源，","source":{"kind":"sentence","en":"It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful food supply,"},"id":"b4-u17-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对先行词进行补充说明，去掉之后不影响主句的完整意思，通常和主句之间用逗号隔开” 描述的是哪个语法点？","hint":"主句 + , + which/who/whose/where + 从句","options":["非限定性定语从句 (Non-restrictive Attributive Clause)","同级比较的否定结构","强调句","非限制性定语从句"],"answer":3,"explain":"非限制性定语从句：主句 + , + which/who/whose/where + 从句：可以修饰前面的某个名词，也可以修饰整个主句的内容，不用that引导","source":{"kind":"grammar","title":"非限制性定语从句"},"id":"b4-u17-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThere were hopes, however, that the problem of the rabbit would become manageable.","hint":"","options":["然而，人们希望兔子的（鼠害）问题能够变得可控。","一位研究蜘蛛的权威人士在英格兰南部的一片草地上对蜘蛛进行了普查，","他估计每英亩有225万多只蜘蛛；","捕获大象进行训练最经济的年龄是15到20岁之间，"],"answer":0,"explain":"There were hopes, however, that the problem of the rabbit would become manageable. — 然而，人们希望兔子的（鼠害）问题能够变得可控。","source":{"kind":"sentence","en":"There were hopes, however, that the problem of the rabbit would become manageable."},"id":"b4-u17-q06"}]},{"id":"b4-u18","book":4,"unit":18,"key":"18","lessonFrom":18,"lessonTo":18,"title":"Porpoises","titleZh":"海豚","question":"What would you say is the main characteristic of porpoises?","sentences":[{"en":"There has long been a superstition among mariners that porpoises will save drowning men by pushing them to the surface,","zh":"长期以来，水手们中间一直流传着一种迷信，认为海豚会把溺水的人托到水面，从而救他们的命，","t":15.63},{"en":"or protect them from sharks by surrounding them in defensive formation.","zh":"或者通过组成防御队形来保护他们免受鲨鱼的袭击。","t":23.59},{"en":"Marine Studio biologists have pointed out that, however intelligent they may be,","zh":"海洋生物研究所的生物学家指出，无论海豚多么聪明，","t":29.17},{"en":"it is probably a mistake to credit dolphins with any motive of life-saving.","zh":"把它们任何行为都归结为救生动机，那可能是一种误解。","t":34.75},{"en":"On the occasions when they have pushed to shore an unconscious human being they have much more likely done it out of curiosity or for sport,","zh":"在它们把不省人事的人推到岸边时，它们很可能只是出于好奇或玩耍，","t":40.59},{"en":"as in riding the bow waves of a ship.","zh":"就像它们在船头波浪中冲浪一样。","t":49.66},{"en":"In 1928 some porpoises were photographed working like beavers to push ashore a waterlogged mattress.","zh":"1928年，有人拍摄到一些海豚像海狸一样辛勤地把一张浸透了水的褥垫推到岸边。","t":53.49},{"en":"If, as has been reported, they have protected humans from sharks,","zh":"如果像报道所说，它们保护过人类免遭鲨鱼袭击，","t":61.7},{"en":"it may have been because curiosity attracted them and because the scent of a possible meal attracted the sharks.","zh":"那可能是因为好奇心吸引了海豚，而一顿美餐的气味吸引了鲨鱼。","t":66.35},{"en":"Porpoises and sharks are natural enemies.","zh":"海豚和鲨鱼是天敌。","t":74.03},{"en":"It is possible that upon such an occasion a battle ensued, with the sharks being driven away or killed.","zh":"在这种情况下，很可能发生了一场战斗，鲨鱼被赶跑或杀死。","t":77.32},{"en":"Whether it be bird, fish or beast, the porpoise is intrigued with anything that is alive.","zh":"无论是鸟、鱼还是野兽，海豚对任何有生命的东西都充满好奇。","t":84.97},{"en":"They are constantly after the turtles, who peacefully submit to all sorts of indignities.","zh":"它们总是追逐海龟，而海龟则平静地忍受着各种羞辱。","t":91.85},{"en":"One young calf especially enjoyed raising a turtle to the surface with his snout,","zh":"有一只幼年海豚特别喜欢用它的鼻子把海龟顶到水面，","t":97.78},{"en":"and then shoving him across the tank like an aquaplane.","zh":"然后像水上飞机一样把海龟推着穿过水箱。","t":103.53},{"en":"Almost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life.","zh":"几乎每天都能看到一只幼年海豚试图把一只300磅重的海龟翻过来，它把鼻子伸到海龟壳的边缘下面，拼命地往上顶。","t":108.38},{"en":"This is not easy, and may require two porpoises working together.","zh":"这并不容易，可能需要两只海豚一起合作。","t":120.82},{"en":"In another game, as the turtle swims across the oceanarium, the first porpoise swoops down from above and butts his shell with his belly.","zh":"在另一个游戏中，当海龟游过海洋馆时，第一只海豚从上方猛扑下来，用肚子撞击它的壳。","t":126.35},{"en":"This knocks the turtle down several feet.","zh":"这把海龟撞下去好几英尺。","t":136.45},{"en":"He no sooner recovers his equilibrium than the next porpoises comes along and hits him another crack.","zh":"它刚恢复平衡，下一只海豚就过来又撞它一下。","t":139.67},{"en":"Eventually the turtle has been butted all the way down to the floor of the tank.","zh":"最终，海龟被一直撞到了水箱底部。","t":147.25},{"en":"He is now satisfied merely to try to stand up, but as soon as he does so a porpoise knocks him flat.","zh":"它现在只满足于试图站起来，但它刚一站起来，一只海豚又把它撞倒。","t":153.07},{"en":"The turtle at last gives up by pulling his feet under his shell and the game is over.","zh":"海龟最终放弃了，它把脚缩进壳里，游戏结束。","t":161.12}],"vocab":[{"word":"porpoise","phonetic":"/ˈpɔːpəs/","meanings":[{"pos":"noun","meaning":"鼠海豚（小型齿鲸类）","usage":"可数名词，复数形式为porpoises，指生活在海洋中的小型鲸类动物，常和dolphin（海豚）区分，但文中二者可通用。"}]},{"word":"superstition","phonetic":"/ˌsuːpəˈstɪʃn/","meanings":[{"pos":"noun","meaning":"迷信；迷信观念","usage":"既可作可数名词也可作不可数名词，指无科学依据的传统信仰，常见搭配：there is a superstition that...（有一个迷信说法是……）。"}]},{"word":"mariner","phonetic":"/ˈmærɪnə(r)/","meanings":[{"pos":"noun","meaning":"水手；海员","usage":"可数名词，正式用语，指以航海为职业的人，同义替换为sailor。"}]},{"word":"drowning","phonetic":"/ˈdraʊnɪŋ/","meanings":[{"pos":"adjective","meaning":"溺水的；快要淹死的","usage":"由动词drown（淹死，溺亡）的现在分词转化而来，作定语修饰名词，如drowning man（溺水者）。"}]},{"word":"defensive","phonetic":"/dɪˈfensɪv/","meanings":[{"pos":"adjective","meaning":"防御的；防守的","usage":"用于描述保护自身免受攻击的行为或状态，常见搭配：defensive formation（防御阵型），on the defensive（采取防御姿态）。"}]},{"word":"credit","phonetic":"/ˈkredɪt/","meanings":[{"pos":"verb","meaning":"把……归功于；认为……有（某种优点或能力）","usage":"常见搭配：credit sb with sth（认为某人具有某种特质/做了某事）。"},{"pos":"noun","meaning":"信用；赞扬；学分","usage":"作名词时为不可数或可数名词，如bank credit（银行信用），get credit for sth（因某事获得赞扬）。"}]},{"word":"motive","phonetic":"/ˈməʊtɪv/","meanings":[{"pos":"noun","meaning":"动机；目的","usage":"可数名词，指促使某人做某事的内在原因，常见搭配：motive for sth/doing sth（做某事的动机）。"}]},{"word":"unconscious","phonetic":"/ʌnˈkɒnʃəs/","meanings":[{"pos":"adjective","meaning":"无意识的；失去知觉的","usage":"可描述人失去意识的状态，也可指行为是无意识的，反义词为conscious。"}]},{"word":"curiosity","phonetic":"/ˌkjʊəriˈɒsəti/","meanings":[{"pos":"noun","meaning":"好奇心；求知欲","usage":"不可数名词，常见搭配：out of curiosity（出于好奇），satisfy one's curiosity（满足某人的好奇心）。"}]},{"word":"waterlogged","phonetic":"/ˈwɔːtəlɒɡd/","meanings":[{"pos":"adjective","meaning":"浸满水的；进水的","usage":"用于描述物体被水浸透、满是积水的状态，如waterlogged wood（浸满水的木头）。"}]},{"word":"scent","phonetic":"/sent/","meanings":[{"pos":"noun","meaning":"气味；香味；（动物的）臭迹","usage":"可数名词，尤指动物能闻到的气味，也可指宜人的香气，同义替换为smell（更通用）、fragrance（更指香味）。"}]},{"word":"ensue","phonetic":"/ɪnˈsjuː/","meanings":[{"pos":"verb","meaning":"接着发生；随之而来","usage":"不及物动词，正式用语，指某件事之后紧接着发生另一件事，常见搭配：ensue from sth（由某事引起）。"}]},{"word":"intrigue","phonetic":"/ɪnˈtriːɡ/","meanings":[{"pos":"verb","meaning":"激起……的兴趣；迷住","usage":"及物动词，常用被动语态be intrigued with/by sth（被某物迷住，对某物感兴趣）。"},{"pos":"noun","meaning":"阴谋；密谋","usage":"作名词时为不可数或可数名词，指秘密策划的有害计划。"}]},{"word":"indignity","phonetic":"/ɪnˈdɪɡnəti/","meanings":[{"pos":"noun","meaning":"侮辱；轻蔑；无礼的行为","usage":"可数或不可数名词，指伤害他人尊严的行为或处境，常见搭配：submit to indignities（忍受侮辱）。"}]},{"word":"shove","phonetic":"/ʃʌv/","meanings":[{"pos":"verb","meaning":"猛推；乱挤","usage":"及物或不及物动词，指用力粗暴地推，比push的力度更大、动作更粗鲁，常见搭配：shove sb/sth across/into sth（把某人/某物推到某处）。"}]}],"phrases":[{"phrase":"out of curiosity","usage":"介词短语，在句中作状语，说明做某事的动机是出于好奇心。","examples":[{"en":"I asked the question just out of curiosity, so you don't need to answer it if you don't want to.","zh":"我问这个问题只是出于好奇，所以你不想回答的话可以不用回答。"},{"en":"Out of curiosity, he opened the old box that had been stored in the attic for years.","zh":"出于好奇，他打开了那个在阁楼里存放了多年的旧箱子。"}]},{"phrase":"credit sb with sth","usage":"动词短语，意为“认为某人有某种特质、能力或做了某事”，也可写作credit sth to sb。","examples":[{"en":"We should credit the team with the success of the entire project, not just the leader.","zh":"我们应该把整个项目的成功归功于整个团队，而不仅仅是领导。"},{"en":"The old man is credited with saving more than 20 children from drowning in the past 30 years.","zh":"这位老人在过去30年里被认为救了20多名溺水的儿童。"}]},{"phrase":"defensive formation","usage":"名词短语，指军队、动物群体等为防御攻击而排列的阵型。","examples":[{"en":"The soldiers formed a defensive formation around the camp to guard against possible attacks at night.","zh":"士兵们在营地周围排成防御阵型，以防夜间可能的袭击。"},{"en":"When facing the enemy's cavalry, the infantry quickly adjusted to a tight defensive formation.","zh":"面对敌方骑兵时，步兵迅速调整为严密的防御阵型。"}]},{"phrase":"bow waves","usage":"名词短语，指船只在航行时船头激起的浪，也叫艏波。","examples":[{"en":"Dolphins love to ride the bow waves of speeding ships for fun.","zh":"海豚喜欢在快速行驶的船只的艏波上冲浪玩耍。"},{"en":"The bow waves of the large cruise ship splashed onto the nearby small fishing boats.","zh":"大型游轮的艏波溅到了附近的小渔船上。"}]},{"phrase":"natural enemies","usage":"名词短语，指生态中天生互为捕食、竞争关系的物种，也可引申指天生敌对的人。","examples":[{"en":"Cats and mice are natural enemies, so you'll rarely see them living together peacefully.","zh":"猫和老鼠是天敌，所以你很少能看到它们和平共处。"},{"en":"In the business world, the two companies have been natural enemies for decades, competing for the same market share.","zh":"在商业领域，这两家公司几十年来一直是死对头，争夺同一块市场份额。"}]},{"phrase":"submit to","usage":"动词短语，意为“屈服于；服从；忍受”，后接名词或动名词作宾语。","examples":[{"en":"He refused to submit to the unfair rules set by the new manager.","zh":"他拒绝服从新经理制定的不公平规定。"},{"en":"The citizens had to submit to the strict curfew during the emergency period.","zh":"在紧急时期，市民们不得不遵守严格的宵禁规定。"}]},{"phrase":"for dear life","usage":"副词短语，在句中作状语，意为“拼命地；竭尽全力地”，形容人在危险或紧急情况下尽最大努力做某事。","examples":[{"en":"When the dog chased him, he ran for dear life as fast as he could.","zh":"狗追他的时候，他拼命地跑，能跑多快就跑多快。"},{"en":"She held onto the rope for dear life, afraid that she would fall off the cliff.","zh":"她拼命抓住绳子，害怕自己会掉下悬崖。"}]},{"phrase":"no sooner...than...","usage":"固定句型，意为“一……就……”，引导时间状语从句，no sooner位于句首时主句要部分倒装。","examples":[{"en":"No sooner had we sat down at the table than the doorbell rang.","zh":"我们刚在桌子旁坐下，门铃就响了。"},{"en":"He no sooner finished his speech than the audience burst into warm applause.","zh":"他刚做完演讲，观众就爆发出热烈的掌声。"}]},{"phrase":"give up","usage":"动词短语，意为“放弃；投降”，可作不及物短语，也可接名词/动名词作宾语。","examples":[{"en":"No matter how difficult the task is, we should never give up easily.","zh":"不管任务有多难，我们都不应该轻易放弃。"},{"en":"He decided to give up smoking after he had a bad cough last month.","zh":"上个月他咳嗽得很厉害之后，决定戒烟。"}]}],"grammar":[{"title":"让步状语从句：however引导的让步结构","definition":"however可以引导让步状语从句，意为“无论多么，不管怎样”，相当于no matter how，用来表示不管程度如何，主句的内容依然成立。","structure":"however + 形容词/副词 + 主语 + 谓语, 主句","usage":"用于强调无论某件事的程度到了什么地步，都不会影响主句的结果，常放在句首或句中。","examples":[{"en":"However intelligent they may be, it is probably a mistake to credit dolphins with any motive of life-saving.","zh":"不管海豚有多聪明，认为它们有救人的动机很可能是错误的。"},{"en":"However hard the rain falls, we have to arrive at the destination on time.","zh":"不管雨下得多大，我们都必须准时到达目的地。"},{"en":"He will never give up pursuing his dream, however many difficulties he may meet.","zh":"不管可能遇到多少困难，他都不会放弃追求自己的梦想。"}]},{"title":"be型虚拟语气在让步状语从句中的用法","definition":"在正式书面语中，让步状语从句可以用动词原形be来表示虚拟，意为“不管是……，无论……”，用来涵盖所有可能的情况，相当于whether...is/are...的正式表达。","structure":"Whether it be + 名词A + or + 名词B, 主句","usage":"用于列举不同的可能性，说明不管是哪种情况，主句的陈述都成立，是非常正式的书面用法。","examples":[{"en":"Whether it be bird, fish or beast, the porpoise is intrigued with anything that is alive.","zh":"不管是鸟、鱼还是野兽，鼠海豚对任何有生命的东西都感兴趣。"},{"en":"Whether it be summer or winter, the old man keeps swimming in the river every morning.","zh":"不管是夏天还是冬天，这位老人都坚持每天早上在河里游泳。"},{"en":"All people, whether they be rich or poor, should be treated equally in the eyes of the law.","zh":"所有人，无论贫富，在法律面前都应该被平等对待。"}]},{"title":"with的复合结构作伴随状语","definition":"with + 宾语 + 宾语补足语的结构可以在句中作伴随状语，用来补充说明主句动作发生时的伴随状态或同时发生的情况，宾语补足语可以是现在分词、过去分词、形容词、介词短语等。","structure":"主句, with + 名词/代词 + 现在分词/过去分词/形容词/介词短语","usage":"用于丰富句子内容，把两个同时发生的动作或状态用一个句子表达出来，使句子更紧凑。当宾语和补足语是主动关系时用现在分词，是被动关系时用过去分词。","examples":[{"en":"It is possible that upon such an occasion a battle ensued, with the sharks being driven away or killed.","zh":"在这种情况下很可能随之发生了一场战斗，鲨鱼被赶走或者被杀死了。"},{"en":"She walked into the classroom, with a big smile on her face.","zh":"她走进教室，脸上带着大大的笑容。"},{"en":"With all the work finished, we decided to go to the cinema to relax ourselves.","zh":"所有工作都完成了，我们决定去电影院放松一下。"}]}],"patterns":[{"pattern":"There has long been a superstition among sb that...","explanation":"","original":{"en":"There has long been a superstition among mariners that porpoises will save drowning men by pushing them to the surface, or protect them from sharks by surrounding them in defensive formation.","zh":"长期以来，海员中有一种迷信，认为鼠海豚会把溺水的人推到水面救他们的命，或者围成防御阵形保护他们免受鲨鱼的伤害。"},"examples":[{"en":"There has long been a superstition among local villagers that walking under a ladder will bring bad luck.","zh":"长期以来，当地村民中有一种迷信，认为从梯子下面走过会带来厄运。"},{"en":"There has long been a superstition among elderly people that breaking a mirror means seven years of misfortune.","zh":"长期以来，老年人中有一种迷信，认为打碎镜子意味着七年的不幸。"}]},{"pattern":"If, as has been reported, ..., it may have been because...","explanation":"","original":{"en":"If, as has been reported, they have protected humans from sharks, it may have been because curiosity attracted them and because the scent of a possible meal attracted the sharks.","zh":"如果像报道所说的那样，它们确实保护人类免受鲨鱼的伤害，那可能是因为好奇心吸引了它们，同时可能成为食物的气味吸引了鲨鱼。"},"examples":[{"en":"If, as has been reported, the small company has defeated its much larger competitor, it may have been because they had a more creative marketing strategy.","zh":"如果像报道所说的那样，这家小公司击败了比它大得多的竞争对手，那可能是因为他们有更有创意的营销策略。"},{"en":"If, as has been reported, the old building survived the strong earthquake, it may have been because it was built with particularly solid materials.","zh":"如果像报道所说的那样，这座老建筑在强地震中幸存了下来，那可能是因为它是用特别坚固的材料建造的。"}]},{"pattern":"On the occasions when ..., they have much more likely done it out of ...","explanation":"","original":{"en":"On the occasions when they have pushed to shore an unconscious human being they have much more likely done it out of curiosity or for sport, as in riding the bow waves of a ship.","zh":"在它们把失去知觉的人推到岸边的情况中，它们这么做更有可能是出于好奇或者玩耍，就像在船只的艏波上冲浪一样。"},"examples":[{"en":"On the occasions when he has helped strangers in trouble, he has much more likely done it out of kindness, not for any reward.","zh":"在他帮助有困难的陌生人的情况中，他这么做更有可能是出于善良，而不是为了任何回报。"},{"en":"On the occasions when the team has lost important games, they have much more likely done it out of lack of practice, not lack of ability.","zh":"在球队输掉重要比赛的情况中，他们输球更有可能是因为缺乏练习，而不是缺乏能力。"}]},{"pattern":"He no sooner ... than ...","explanation":"","original":{"en":"He no sooner recovers his equilibrium than the next porpoise comes along and hits him another crack.","zh":"它刚恢复平衡，另一只鼠海豚就过来又撞了它一下。"},"examples":[{"en":"I no sooner opened the window than a gust of cold wind blew into the room.","zh":"我刚打开窗户，一阵冷风就吹进了房间。"},{"en":"The little girl no sooner saw her mother than she ran over and threw herself into her arms.","zh":"小女孩一看到妈妈，就跑过去扑进了她的怀里。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“猛推；乱挤” 对应的单词是？","hint":"verb · /ʃʌv/","options":["prestige","utmost","shove","repayment"],"answer":2,"explain":"shove · /ʃʌv/ · verb · 猛推；乱挤。及物或不及物动词，指用力粗暴地推，比push的力度更大、动作更粗鲁，常见搭配：shove sb/sth across/into sth（把某人/某物推到某处）。","source":{"kind":"vocab","word":"shove"},"id":"b4-u18-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Dolphins love to ride the _____ of speeding ships for fun.","hint":"海豚喜欢在快速行驶的船只的艏波上冲浪玩耍。","answer":"bow waves","placeholder":"输入缺失的短语","explain":"bow waves：名词短语，指船只在航行时船头激起的浪，也叫艏波。（海豚喜欢在快速行驶的船只的艏波上冲浪玩耍。）","source":{"kind":"phrase","phrase":"bow waves"},"id":"b4-u18-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life.","hint":"几乎每天都能看到一只幼年海豚试图把一只300磅重的海龟翻过来，它把鼻子伸到海龟壳的边缘下面，拼命地往上顶。","answer":"Almost","placeholder":"输入缺失的单词","explain":"Almost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life. — 几乎每天都能看到一只幼年海豚试图把一只300磅重的海龟翻过来，它把鼻子伸到海龟壳的边缘下面，拼命地往上顶。","source":{"kind":"sentence","en":"Almost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life."},"id":"b4-u18-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“在正式书面语中，让步状语从句可以用动词原形be来表示虚拟，意为“不管是……，无论……”，用来涵盖所有可能的情况，相当于whether...is/are...的正式表达。” 描述的是哪个语法点？","hint":"Whether it be + 名词A + or + 名词B, 主句","options":["given引导的条件状语","so...that...引导的结果状语从句（倒装结构）","插入语结构","be型虚拟语气在让步状语从句中的用法"],"answer":3,"explain":"be型虚拟语气在让步状语从句中的用法：Whether it be + 名词A + or + 名词B, 主句：用于列举不同的可能性，说明不管是哪种情况，主句的陈述都成立，是非常正式的书面用法。","source":{"kind":"grammar","title":"be型虚拟语气在让步状语从句中的用法"},"id":"b4-u18-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAlmost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life.","hint":"","options":["提供足够的升力和前进动力。","我们都渴望有一个行为准则。","几乎每天都能看到一只幼年海豚试图把一只300磅重的海龟翻过来，它把鼻子伸到海龟壳的边缘下面，拼命地往上顶。","他估计每英亩有225万多只蜘蛛；"],"answer":2,"explain":"Almost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life. — 几乎每天都能看到一只幼年海豚试图把一只300磅重的海龟翻过来，它把鼻子伸到海龟壳的边缘下面，拼命地往上顶。","source":{"kind":"sentence","en":"Almost any day a young porpoises may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life."},"id":"b4-u18-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 17 个单词","answer":"He no sooner recovers his equilibrium than the next porpoises comes along and hits him another crack.","placeholder":"输入完整英文句子","explain":"He no sooner recovers his equilibrium than the next porpoises comes along and hits him another crack. — 它刚恢复平衡，下一只海豚就过来又撞它一下。","playText":"He no sooner recovers his equilibrium than the next porpoises comes along and hits him another crack.","source":{"kind":"sentence","en":"He no sooner recovers his equilibrium than the next porpoises comes along and hits him another crack."},"id":"b4-u18-q06"}]},{"id":"b4-u19","book":4,"unit":19,"key":"19","lessonFrom":19,"lessonTo":19,"title":"The Stuff of Dreams","titleZh":"梦的本质","question":"What is going on when a person experiences rapid eye-movements during sleep?","sentences":[{"en":"It is fairly clear that the sleeping period must have some function, and because there is so much of it the function would seem to be important.","zh":"很清楚，睡眠期一定有某种功能，而且由于睡眠期很长，这种功能似乎很重要。","t":18.37},{"en":"Speculations about its nature have been going on for literally thousands of years,","zh":"关于其本质的猜测已经持续了几千年，","t":28.71},{"en":"and one odd finding that makes the problem puzzling is that it looks very much as if sleeping is not simply a matter of giving the body a rest.","zh":"一个令人困惑的奇怪发现是，睡眠似乎不仅仅是让身体休息。","t":35.16},{"en":"'Rest', in terms of muscle relaxation and so on, can be achieved by a brief period lying, or even sitting down.","zh":"从肌肉放松等方面来看，“休息”可以通过短暂的躺卧，甚至坐下来实现。","t":45.36},{"en":"The body's tissues are self-repairing and self-restoring to a degree, and function best when more or less continuously active.","zh":"身体的组织在一定程度上是自我修复和自我恢复的，并且在或多或少持续活动时功能最佳。","t":55.75},{"en":"In fact a basic amount of movement occurs during sleep which is specifically concerned with preventing muscle inactivity.","zh":"事实上，在睡眠期间会发生一定程度的运动，这尤其旨在防止肌肉不活动。","t":66.27},{"en":"If it is not a question of resting the body, then perhaps it is the brain that needs resting?","zh":"如果不是身体休息的问题，那么也许是大脑需要休息？","t":75.66},{"en":"This might be a plausible hypothesis were it not for two factors.","zh":"要不是有两个因素，这可能是一个合理的假设。","t":83.65},{"en":"First the electroencephalograph (which is simply a device for recording the electrical activity of the brain by attaching electrodes to the scalp)","zh":"首先，脑电图仪（它只是一种通过将电极连接到头皮来记录大脑电活动的设备）","t":89.37},{"en":"shows that while there is a change in the pattern of activity during sleep,","zh":"表明虽然睡眠期间的活动模式有所变化，","t":100.75},{"en":"there is no evidence that the total amount of activity is any less.","zh":"但没有证据表明总活动量有所减少。","t":105.8},{"en":"The second factor is more interesting and more fundamental.","zh":"第二个因素更有趣也更具根本性。","t":111.36},{"en":"Some years ago an American psychiatrist named William Dement published experiments dealing with the recording of eye-movements during sleep.","zh":"几年前，一位名叫威廉·德门特的美国精神病学家发表了关于记录睡眠期间眼球运动的实验。","t":116},{"en":"He showed that the average individual's sleep cycle is punctuated with peculiar bursts of eye-movements, some drifting and slow, others jerky and rapid.","zh":"他表明，普通人的睡眠周期会伴随着奇特的眼球运动爆发，有些是漂移而缓慢的，有些是抽搐而快速的。","t":126.91},{"en":"People woken during these periods of eye-movements generally reported that they had been dreaming.","zh":"在这些眼球运动期间被唤醒的人通常报告说他们一直在做梦。","t":140.33},{"en":"When woken at other times they reported no dreams.","zh":"而在其他时候被唤醒时，他们报告说没有做梦。","t":146.91},{"en":"If one group of people were disturbed from their eye-movement sleep for several nights on end,","zh":"如果一组人在连续几个晚上被从眼动睡眠中打扰，","t":150.85},{"en":"and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements,","zh":"而另一组人在相同的时间内被打扰，但当时他们没有表现出眼球运动，","t":156.3},{"en":"the first group began to show some personality disorders while the others seemed more or less unaffected.","zh":"第一组人开始表现出一些人格障碍，而其他人则或多或少地未受影响。","t":165.44},{"en":"The implications of all this were that it was not the disturbance of sleep that mattered, but the disturbance of dreaming.","zh":"所有这些都表明，重要的不是睡眠受到干扰，而是做梦受到干扰。","t":174.88}],"vocab":[{"word":"speculation","phonetic":"/ˌspekjuˈleɪʃn/","meanings":[{"pos":"noun","meaning":"推测，猜测","usage":"指没有足够证据的思考、推断，常搭配介词about/on引出推测的对象"}]},{"word":"literally","phonetic":"/ˈlɪtərəli/","meanings":[{"pos":"adverb","meaning":"确实地，真正地；字面上地","usage":"用于强调所说内容属实，也可指按字面意思理解"}]},{"word":"odd","phonetic":"/ɒd/","meanings":[{"pos":"adjective","meaning":"奇怪的，怪异的；奇数的","usage":"形容事物不合常理、难以解释，也可表示数字为奇数"}]},{"word":"tissue","phonetic":"/ˈtɪʃuː/","meanings":[{"pos":"noun","meaning":"（生物）组织；纸巾","usage":"生物学语境下指动植物的组织，日常语境可表示纸巾"}]},{"word":"plausible","phonetic":"/ˈplɔːzəbl/","meanings":[{"pos":"adjective","meaning":"貌似可信的，看似合理的","usage":"形容说法、解释等表面上看起来有道理，但不一定正确"}]},{"word":"hypothesis","phonetic":"/haɪˈpɒθəsɪs/","meanings":[{"pos":"noun","meaning":"假说，假设","usage":"科学研究中未经证实的设想，复数形式为hypotheses"}]},{"word":"electroencephalograph","phonetic":"/ɪˌlektrəʊenˈsefələɡrɑːf/","meanings":[{"pos":"noun","meaning":"脑电图仪","usage":"医学术语，指记录大脑电活动的设备，常缩写为EEG"}]},{"word":"electrode","phonetic":"/ɪˈlektrəʊd/","meanings":[{"pos":"noun","meaning":"电极","usage":"用于传导电流的装置，常见于医疗或电子设备语境"}]},{"word":"scalp","phonetic":"/skælp/","meanings":[{"pos":"noun","meaning":"头皮","usage":"指覆盖头骨的皮肤和毛发层"}]},{"word":"psychiatrist","phonetic":"/saɪˈkaɪətrɪst/","meanings":[{"pos":"noun","meaning":"精神病学家，精神科医生","usage":"指专门研究、治疗精神疾病的医生"}]},{"word":"punctuate","phonetic":"/ˈpʌŋktʃueɪt/","meanings":[{"pos":"verb","meaning":"不时打断；给……加标点","usage":"常见搭配be punctuated with/by，表示某过程中不时出现某事物"}]},{"word":"jerky","phonetic":"/ˈdʒɜːki/","meanings":[{"pos":"adjective","meaning":"忽动忽停的，不平稳的","usage":"形容动作不连贯、突然且急促"}]},{"word":"exhibit","phonetic":"/ɪɡˈzɪbɪt/","meanings":[{"pos":"verb","meaning":"表现出，显示；展览","usage":"正式用语，指表现出某种行为、特质或症状，也可表示展示物品"}]},{"word":"implication","phonetic":"/ˌɪmplɪˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"含义，暗示；可能的影响","usage":"指某事隐含的意义，或某事件可能带来的结果、影响"}]}],"phrases":[{"phrase":"in terms of","usage":"用于从某个角度、某个方面谈论事物，引出讨论的维度","examples":[{"en":"Rest, in terms of muscle relaxation and so on, can be achieved by a brief period lying, or even sitting down.","zh":"就肌肉放松等方面而言，短暂的躺卧甚至坐着就能得到休息。"},{"en":"In terms of customer satisfaction, the new policy is a great success.","zh":"从客户满意度来看，新政策非常成功。"}]},{"phrase":"to a degree","usage":"表示“在某种程度上”，用于说明某事物的适用范围不是绝对的","examples":[{"en":"The body's tissues are self-repairing and self-restoring to a degree, and function best when more or less continuously active.","zh":"人体组织在一定程度上有自我修复和自我恢复的能力，在或多或少持续活动时运作得最好。"},{"en":"I agree with his argument to a degree, but there are still points I doubt.","zh":"我在一定程度上同意他的论点，但仍有一些地方我持怀疑态度。"}]},{"phrase":"be concerned with","usage":"表示“与……有关；涉及”，说明事物的关联对象","examples":[{"en":"In fact a basic amount of movement occurs during sleep which is specifically concerned with preventing muscle inactivity.","zh":"事实上，睡眠期间会有少量活动，这些活动正是为了防止肌肉不活动。"},{"en":"This research is concerned with the effects of air pollution on human health.","zh":"这项研究涉及空气污染对人类健康的影响。"}]},{"phrase":"were it not for","usage":"虚拟语气结构，意为“要不是，如果没有”，表示与事实相反的假设","examples":[{"en":"This might be a plausible hypothesis were it not for two factors.","zh":"要不是有两个因素，这个假说似乎是合理的。"},{"en":"Were it not for your help, I would never have finished the project on time.","zh":"要不是你的帮助，我绝不可能按时完成这个项目。"}]},{"phrase":"on end","usage":"放在表示时间的名词后，意为“连续地，不断地”","examples":[{"en":"If one group of people were disturbed from their eye-movement sleep for several nights on end, and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements.","zh":"如果一组人连续几晚在眼动睡眠阶段被叫醒，另一组人在同样长的时间里被叫醒，但叫醒时间是在他们没有出现眼动的阶段。"},{"en":"He worked for 12 hours on end to meet the deadline.","zh":"为了赶截止日期，他连续工作了12个小时。"}]},{"phrase":"more or less","usage":"意为“几乎，差不多；大概”，表示数量、程度接近某个情况","examples":[{"en":"the first group began to show some personality disorders while the others seemed more or less unaffected.","zh":"第一组人开始出现一些性格紊乱的症状，而另一组人几乎没有受到影响。"},{"en":"The work is more or less finished, we just need to check the details.","zh":"工作差不多完成了，我们只需要检查一下细节。"}]}],"grammar":[{"title":"虚拟条件句的倒装结构","definition":"在虚拟语气的条件从句中，如果含有were, should, had等助动词，可以省略if，将这些助动词移到句首构成倒装，语义与正常语序的虚拟条件句一致","structure":"Were/Should/Had + 主语 + 其他成分，主句","usage":"用于正式书面语中，表示与事实相反的假设，或对未来的虚拟设想","examples":[{"en":"This might be a plausible hypothesis were it not for two factors.","zh":"要不是有两个因素，这个假说似乎是合理的。"},{"en":"Had I known about the meeting earlier, I would have attended it.","zh":"要是我早知道有这个会议，我就会参加了。"}]},{"title":"分隔式定语从句","definition":"指定语从句与它所修饰的先行词被其他成分隔开的情况，通常是为了保持句子平衡，避免头重脚轻","structure":"先行词 + 其他成分 + 关系代词/关系副词 + 定语从句","usage":"当先行词后面的修饰成分较短，而定语从句较长时，常使用分隔式定语从句，需要结合语境判断定语从句修饰的对象","examples":[{"en":"In fact a basic amount of movement occurs during sleep which is specifically concerned with preventing muscle inactivity.","zh":"事实上，睡眠期间会有少量活动，这些活动正是为了防止肌肉不活动。"},{"en":"A new teacher will come tomorrow who will teach you English.","zh":"明天会来一位新老师，教你们英语。"}]},{"title":"not...but... 并列结构","definition":"用于连接两个并列的成分，表示“不是……而是……”，否定前者，肯定后者，前后连接的成分语法结构需保持一致","structure":"not + 被否定的成分 + but + 被肯定的成分","usage":"用于强调后者的重要性，可连接名词、动词、介词短语等多种成分","examples":[{"en":"The implications of all this were that it was not the disturbance of sleep that mattered, but the disturbance of dreaming.","zh":"这一切表明，重要的不是睡眠受到干扰，而是做梦受到了干扰。"},{"en":"What caused the accident was not the driver's carelessness, but the bad road condition.","zh":"造成事故的不是司机的粗心，而是糟糕的路况。"}]}],"patterns":[{"pattern":"It is fairly clear that + 主语从句","explanation":"","original":{"en":"It is fairly clear that the sleeping period must have some function, and because there is so much of it the function would seem to be important.","zh":"很明显，睡眠期必然有某种作用，而且因为睡眠时间很长，这种作用似乎还很重要。"},"examples":[{"en":"It is fairly clear that regular exercise plays a key role in maintaining physical and mental health.","zh":"很明显，规律锻炼对保持身心健康起着关键作用。"},{"en":"It is fairly clear that the rapid development of digital technology has greatly changed people's way of life.","zh":"很明显，数字技术的快速发展极大地改变了人们的生活方式。"}]},{"pattern":"One odd finding that makes the problem puzzling is that + 表语从句","explanation":"","original":{"en":"one odd finding that makes the problem puzzling is that it looks very much as if sleeping is not simply a matter of giving the body a rest.","zh":"一个让这个问题变得费解的奇怪发现是，看起来睡眠似乎不仅仅是让身体得到休息。"},"examples":[{"en":"One odd finding that makes the research confusing is that the experimental results are completely opposite to what we expected.","zh":"一个让这项研究变得令人困惑的奇怪发现是，实验结果和我们预期的完全相反。"},{"en":"One odd finding that makes the phenomenon confusing is that the species can survive in extremely cold environments that were thought to be unsuitable for life.","zh":"一个让这个现象变得费解的奇怪发现是，这个物种能在之前被认为不适合生命生存的极寒环境中存活。"}]},{"pattern":"If + 一般过去时的被动语态 + and + 一般过去时的被动语态 + 主句","explanation":"","original":{"en":"If one group of people were disturbed from their eye-movement sleep for several nights on end, and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements, the first group began to show some personality disorders while the others seemed more or less unaffected.","zh":"如果一组人连续几晚在眼动睡眠阶段被叫醒，另一组人在同样长的时间里被叫醒，但叫醒时间是在他们没有出现眼动的阶段，第一组人开始出现一些性格紊乱的症状，而另一组人几乎没有受到影响。"},"examples":[{"en":"If one group of students were given 30 minutes of reading time every day, and another group were given the same amount of time to do math exercises, the first group would show significant improvement in writing skills after three months.","zh":"如果一组学生每天有30分钟的阅读时间，另一组学生有同样长的时间做数学练习，三个月后第一组学生的写作能力会有显著提升。"},{"en":"If one batch of seeds were planted in acidic soil, and another batch of the same seeds were planted in alkaline soil with the same water and sunlight, the former would grow much slower than the latter.","zh":"如果一批种子被种在酸性土壤里，另一批同样的种子被种在碱性土壤里，给予同样的水分和光照，前者会比后者生长得慢得多。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“表现出，显示；展览” 对应的单词是？","hint":"verb · /ɪɡˈzɪbɪt/","options":["hazard","exhibit","democratic","exquisite"],"answer":1,"explain":"exhibit · /ɪɡˈzɪbɪt/ · verb · 表现出，显示；展览。正式用语，指表现出某种行为、特质或症状，也可表示展示物品","source":{"kind":"vocab","word":"exhibit"},"id":"b4-u19-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：脑电图仪","hint":"/ɪˌlektrəʊenˈsefələɡrɑːf/ · noun","answer":"electroencephalograph","placeholder":"输入英文单词","explain":"electroencephalograph · /ɪˌlektrəʊenˈsefələɡrɑːf/ · noun · 脑电图仪。医学术语，指记录大脑电活动的设备，常缩写为EEG","source":{"kind":"vocab","word":"electroencephalograph"},"id":"b4-u19-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Rest, _____ muscle relaxation and so on, can be achieved by a brief period lying, or even sitting down.","hint":"就肌肉放松等方面而言，短暂的躺卧甚至坐着就能得到休息。","answer":"in terms of","placeholder":"输入缺失的短语","explain":"in terms of：用于从某个角度、某个方面谈论事物，引出讨论的维度（就肌肉放松等方面而言，短暂的躺卧甚至坐着就能得到休息。）","source":{"kind":"phrase","phrase":"in terms of"},"id":"b4-u19-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：and another group were disturbed for an equal period of time but when they were not exhibiting _____","hint":"而另一组人在相同的时间内被打扰，但当时他们没有表现出眼球运动，","answer":"eye-movements","placeholder":"输入缺失的单词","explain":"and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements, — 而另一组人在相同的时间内被打扰，但当时他们没有表现出眼球运动，","source":{"kind":"sentence","en":"and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements,"},"id":"b4-u19-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“在虚拟语气的条件从句中，如果含有were, should, had等助动词，可以省略if，将这些助动词移到句首构成倒装，语义与正常语序的虚拟条件句一致” 描述的是哪个语法点？","hint":"Were/Should/Had + 主语 + 其他成分，主句","options":["while引导的让步状语从句","完全倒装句","比较状语从句 (Comparative Adverbial Clause)","虚拟条件句的倒装结构"],"answer":3,"explain":"虚拟条件句的倒装结构：Were/Should/Had + 主语 + 其他成分，主句：用于正式书面语中，表示与事实相反的假设，或对未来的虚拟设想","source":{"kind":"grammar","title":"虚拟条件句的倒装结构"},"id":"b4-u19-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nshows that while there is a change in the pattern of activity during sleep,","hint":"","options":["技术趋势可能将硅谷推向未来。","因此，一个分裂的国家必然会产生过高的政府开支。","表明虽然睡眠期间的活动模式有所变化，","但如果他遇到这种势利，他也能很容易理解和应对。"],"answer":2,"explain":"shows that while there is a change in the pattern of activity during sleep, — 表明虽然睡眠期间的活动模式有所变化，","source":{"kind":"sentence","en":"shows that while there is a change in the pattern of activity during sleep,"},"id":"b4-u19-q06"}]},{"id":"b4-u20","book":4,"unit":20,"key":"20","lessonFrom":20,"lessonTo":20,"title":"Snake Poison","titleZh":"蛇毒","question":"What are the two different ways in which snake poison acts?","sentences":[{"en":"How in came about that snakes manufactured poison is a mystery.","zh":"蛇是怎样产生毒液的，这至今仍是个谜。","t":15.32},{"en":"Over the periods their saliva, a mild, digestive juice like our own, was converted into a poison that defies analysis even today.","zh":"经过漫长的岁月，它们的唾液——一种像我们人类唾液一样的温和的消化液——变成了毒液，这种毒液即使在今天也无法分析其成分。","t":20.33},{"en":"It was not forced upon them by the survival competition;","zh":"毒液并不是由生存竞争强加给它们的；","t":30.46},{"en":"they could have caught and lived on prey without using poison, just as the thousands of non-poisonous snakes still do.","zh":"它们本来可以不用毒液捕食猎物而生存下来，就像成千上万的无毒蛇今天仍然在做的那样。","t":34.46},{"en":"Poison to a snake is merely a luxury;","zh":"对蛇来说，毒液只是一种奢侈品；","t":42.76},{"en":"it enables it to get its food with very little effort, no more effort than one bite.","zh":"它能使蛇毫不费力地获取食物，一口咬下去便大功告成。","t":46.3},{"en":"And why only snakes?","zh":"为什么只有蛇有毒液呢？","t":53.08},{"en":"Cats, for instance, would be greatly helped;","zh":"拿猫来说，毒液对它们会大有帮助；","t":55.48},{"en":"no running fights with large, fierce rats or tussles with grown rabbits--just a bite and no more effort needed.","zh":"它们不必和凶猛的大老鼠追逐撕打，也不必和长大的兔子扭斗——只需一口咬下去，便不必再费力气了。","t":58.32},{"en":"In fact, it would be an assistance to all carnivores though it would be a two-edged weapon when they fought each other.","zh":"事实上，毒液对所有的食肉动物都会有帮助，尽管在它们互相搏斗时，毒液会变成一把双刃剑。","t":66.56},{"en":"But, of the vertebrates unpredictable Nature selected only snakes (and one lizard).","zh":"但在脊椎动物中，变幻莫测的大自然只选择了蛇（和一种蜥蜴）。","t":74.26},{"en":"One wonders also why Nature, with some snakes concocted poison of such extreme potency.","zh":"人们也想知道，为什么大自然让有些蛇产生如此剧烈的毒液。","t":80.85},{"en":"In the conversion of saliva into poison, one might suppose that a fixed process took place. It did not;","zh":"在唾液变为毒液的过程中，人们可能会认为发生了一个固定的过程。但事实并非如此；","t":88.19},{"en":"some snakes manufactured a poison different in every respect from that of others,","zh":"有些蛇产生的毒液与另一些蛇的毒液在各个方面都不同，","t":96.06},{"en":"as different as arsenic is from strychnine, and having different effects.","zh":"就像砷和士的宁的区别一样大，而且有不同的效果。","t":101.47},{"en":"One poison acts on the nerves, the other on the blood.","zh":"一种毒液作用于神经，另一种作用于血液。","t":107.07},{"en":"The makers of the nerve poison include the mambas and the cobras and their venom is called neurotoxic.","zh":"产生神经毒液的包括曼巴蛇和眼镜蛇，它们的毒液被称为神经毒素。","t":111.5},{"en":"Vipers (adders) and rattlesnakes manufacture the blood poison, which is known as haemolytic.","zh":"蝰蛇（蝮蛇）和响尾蛇产生血液毒液，这种毒液被称为溶血性毒素。","t":119.29},{"en":"Both poisons are unpleasant, but by far the more unpleasant is the blood poison.","zh":"两种毒液都不好，但更不好的是血液毒液。","t":127.07},{"en":"It is said that the nerve poison is the more primitive of the two, that the blood poison is, so to speak, a newer product from an improved formula.","zh":"据说神经毒液是两种毒液中较原始的一种，而血液毒液，可以说，是改进配方的新产品。","t":132.61},{"en":"Be that as it may, the nerve poison does its business with man far more quickly than the blood poison.","zh":"话虽如此，神经毒液对人起作用的速度比血液毒液快得多。","t":142.08},{"en":"This, however, means nothing.","zh":"然而，这并不说明什么。","t":148.44},{"en":"Snakes did not acquire their poison for use against man but for use against prey such as rats and mice,","zh":"蛇获得毒液并不是为了对付人，而是为了对付像老鼠之类的小动物，","t":150.85},{"en":"and the effects on these of viperine poison is almost immediate.","zh":"蝰蛇毒液对这些猎物几乎能立即见效。","t":158.2}],"vocab":[{"word":"poison","phonetic":"/ˈpɔɪzn/","meanings":[{"pos":"noun","meaning":"毒药，毒物","usage":"指能使生物中毒的有害物质"},{"pos":"verb","meaning":"下毒，毒害","usage":"表示投放毒物使中毒的动作"}]},{"word":"saliva","phonetic":"/səˈlaɪvə/","meanings":[{"pos":"noun","meaning":"唾液，口水","usage":"不可数名词，指口腔分泌的消化液"}]},{"word":"digestive","phonetic":"/daɪˈdʒestɪv/","meanings":[{"pos":"adjective","meaning":"消化的，助消化的","usage":"常用于修饰与消化功能相关的器官、液体等"}]},{"word":"defy","phonetic":"/dɪˈfaɪ/","meanings":[{"pos":"verb","meaning":"使不可能，违抗","usage":"后接名词，表示某事物难以被完成/理解，或公然违抗规则、权威"}]},{"word":"prey","phonetic":"/preɪ/","meanings":[{"pos":"noun","meaning":"猎物，捕获物","usage":"不可数名词，指被其他动物捕食的生物"}]},{"word":"luxury","phonetic":"/ˈlʌkʃəri/","meanings":[{"pos":"noun","meaning":"奢侈品，享受","usage":"可作可数或不可数名词，指非必需的、能带来便利或享受的事物"}]},{"word":"carnivore","phonetic":"/ˈkɑːnɪvɔː(r)/","meanings":[{"pos":"noun","meaning":"食肉动物","usage":"指以肉类为主要食物的动物，反义词为herbivore（食草动物）"}]},{"word":"vertebrate","phonetic":"/ˈvɜːtɪbrət/","meanings":[{"pos":"noun","meaning":"脊椎动物","usage":"指有脊椎骨的动物，反义词为invertebrate（无脊椎动物）"}]},{"word":"concoct","phonetic":"/kənˈkɒkt/","meanings":[{"pos":"verb","meaning":"调制，编造","usage":"可指调配物质，也可指编造故事、借口等"}]},{"word":"potency","phonetic":"/ˈpəʊtnsi/","meanings":[{"pos":"noun","meaning":"效力， potency","usage":"不可数名词，指药物、毒物等的作用强度"}]},{"word":"conversion","phonetic":"/kənˈvɜːʃn/","meanings":[{"pos":"noun","meaning":"转化，转换","usage":"常与介词of/into搭配，表示从一种形式变为另一种形式的过程"}]},{"word":"venom","phonetic":"/ˈvenəm/","meanings":[{"pos":"noun","meaning":"（蛇、昆虫等的）毒液","usage":"特指生物分泌的有毒液体，区别于普通的poison"}]},{"word":"primitive","phonetic":"/ˈprɪmətɪv/","meanings":[{"pos":"adjective","meaning":"原始的，早期的","usage":"用于描述事物发展的初期阶段，相对不够先进"}]},{"word":"formula","phonetic":"/ˈfɔːmjələ/","meanings":[{"pos":"noun","meaning":"配方，公式","usage":"可指化学配方、数学公式，也可指方案、方法"}]}],"phrases":[{"phrase":"live on","usage":"表示以某物为食、靠某物生存","examples":[{"en":"They could have caught and lived on prey without using poison.","zh":"它们本可以不用毒液，就捕获猎物并以此为生。"},{"en":"Most pandas live on bamboo in the wild.","zh":"野外的大多数大熊猫以竹子为食。"}]},{"phrase":"two-edged weapon","usage":"比喻具有利弊两面性的事物，即双刃剑","examples":[{"en":"It would be an assistance to all carnivores though it would be a two-edged weapon when they fought each other.","zh":"这对所有食肉动物都有帮助，不过当它们互相打斗时，这就会是一把双刃剑。"},{"en":"Social media is a two-edged weapon: it connects people but also spreads misinformation easily.","zh":"社交媒体是一把双刃剑：它能连接人们，但也很容易传播不实信息。"}]},{"phrase":"by far","usage":"用于形容词或副词比较级、最高级前，强调程度，意为“……得多，显然”","examples":[{"en":"Both poisons are unpleasant, but by far the more unpleasant is the blood poison.","zh":"两种毒液都很可怕，但血溶性毒液显然要更伤人。"},{"en":"This is by far the best movie I have watched this year.","zh":"这显然是我今年看过的最好的电影。"}]},{"phrase":"so to speak","usage":"插入语，用于表达比喻、不太严谨的说法，意为“可以说，打个比方”","examples":[{"en":"The blood poison is, so to speak, a newer product from an improved formula.","zh":"可以说，血溶性毒液是配方改良后的新产品。"},{"en":"In many ways, the Internet is, so to speak, a new global public space.","zh":"从很多方面来说，互联网可以说是一个全新的全球公共空间。"}]},{"phrase":"be that as it may","usage":"让步表达，意为“尽管如此，话虽如此”，用于承认前文观点后转折引出新内容","examples":[{"en":"Be that as it may, the nerve poison does its business with man far more quickly than the blood poison.","zh":"尽管如此，神经性毒液作用于人体的速度还是比血溶性毒液快得多。"},{"en":"Be that as it may, we still need to consider the potential risks of the plan.","zh":"话虽如此，我们还是需要考虑这个计划的潜在风险。"}]},{"phrase":"do its business","usage":"非正式表达，意为“发挥作用，奏效”","examples":[{"en":"The nerve poison does its business with man far more quickly than the blood poison.","zh":"神经性毒液对人体产生作用的速度比血溶性毒液快得多。"},{"en":"The medicine will do its business in half an hour and you will feel less pain.","zh":"这个药半小时后就会起效，你就不会那么疼了。"}]}],"grammar":[{"title":"虚拟语气：could have done","definition":"表示对过去本可以发生但实际没有发生的事情的假设，译为“本可以做某事（却没做）”","structure":"主语 + could have + 动词过去分词","usage":"用于评论过去的行为，表达遗憾、推测或者假设的可能性","examples":[{"en":"They could have caught and lived on prey without using poison, just as the thousands of non-poisonous snakes still do.","zh":"它们本可以不用毒液，就捕获猎物并以此为生，就像数千种无毒蛇现在仍然做的那样。"},{"en":"You could have passed the exam if you had studied harder last week.","zh":"如果你上周更努力学习的话，你本可以通过考试的。"}]},{"title":"定语从句的省略形式","definition":"当定语从句的主语与先行词一致，且从句谓语包含be动词时，可以省略关系代词和be动词，保留其余成分","structure":"先行词 + （关系代词 + be动词） + 分词/形容词/介词短语","usage":"用于简化句子结构，使表达更简洁，常见于书面语","examples":[{"en":"Over the periods their saliva, a mild, digestive juice like our own, was converted into a poison that defies analysis even today.","zh":"经过很长的时间，它们的唾液——一种和我们的唾液一样的温和消化液——转变成了一种甚至至今都无法分析清楚的毒液。"},{"en":"The book written by my favorite author has sold over 1 million copies.","zh":"我最喜欢的作家写的那本书已经卖出了超过100万册。"}]}],"patterns":[{"pattern":"How it came about that... is a mystery.","explanation":"","original":{"en":"How it came about that snakes manufactured poison is a mystery.","zh":"蛇是如何产生毒液的，这是个谜。"},"examples":[{"en":"How it came about that this ancient building survived the war is a mystery.","zh":"这座古建筑是如何在战争中幸存下来的，这是个谜。"},{"en":"How it came about that he mastered three foreign languages in two years is a mystery to all of us.","zh":"他是如何在两年内掌握三门外语的，对我们所有人来说都是个谜。"}]},{"pattern":"It is said that..., that...","explanation":"","original":{"en":"It is said that the nerve poison is the more primitive of the two, that the blood poison is, so to speak, a newer product from an improved formula.","zh":"据说在这两种毒液中，神经性毒液是更原始的一种，可以说，血溶性毒液是配方改良后的新产品。"},"examples":[{"en":"It is said that this place used to be a royal garden, that many emperors spent their summers here.","zh":"据说这个地方曾经是皇家园林，很多皇帝都在这里避暑。"},{"en":"It is said that drinking warm water in the morning is good for your stomach, that it helps speed up your metabolism.","zh":"据说早上喝温水对胃有好处，还能帮助加快新陈代谢。"}]},{"pattern":"...did not acquire... for use against... but for use against...","explanation":"","original":{"en":"Snakes did not acquire their poison for use against man but for use against prey such as rats and mice.","zh":"蛇获得毒液不是为了用来对抗人类，而是为了用来对付老鼠之类的猎物。"},"examples":[{"en":"He did not take the course for use against exams but for use against practical problems in his work.","zh":"他学这门课不是为了应付考试，而是为了解决工作中的实际问题。"},{"en":"This law was not made for use against ordinary citizens but for use against people who break public order.","zh":"这项法律的制定不是为了约束普通公民，而是为了惩治破坏公共秩序的人。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“配方，公式” 对应的单词是？","hint":"noun · /ˈfɔːmjələ/","options":["chasm","catastrophic","formula","portray"],"answer":2,"explain":"formula · /ˈfɔːmjələ/ · noun · 配方，公式。可指化学配方、数学公式，也可指方案、方法","source":{"kind":"vocab","word":"formula"},"id":"b4-u20-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：原始的，早期的","hint":"/ˈprɪmətɪv/ · adjective","answer":"primitive","placeholder":"输入英文单词","explain":"primitive · /ˈprɪmətɪv/ · adjective · 原始的，早期的。用于描述事物发展的初期阶段，相对不够先进","source":{"kind":"vocab","word":"primitive"},"id":"b4-u20-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, we still need to consider the potential risks of the plan.","hint":"话虽如此，我们还是需要考虑这个计划的潜在风险。","answer":"be that as it may","placeholder":"输入缺失的短语","explain":"be that as it may：让步表达，意为“尽管如此，话虽如此”，用于承认前文观点后转折引出新内容（话虽如此，我们还是需要考虑这个计划的潜在风险。）","source":{"kind":"phrase","phrase":"be that as it may"},"id":"b4-u20-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Cats, for instance, would be _____ helped;","hint":"拿猫来说，毒液对它们会大有帮助；","answer":"greatly","placeholder":"输入缺失的单词","explain":"Cats, for instance, would be greatly helped; — 拿猫来说，毒液对它们会大有帮助；","source":{"kind":"sentence","en":"Cats, for instance, would be greatly helped;"},"id":"b4-u20-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当定语从句的主语与先行词一致，且从句谓语包含be动词时，可以省略关系代词和be动词，保留其余成分” 描述的是哪个语法点？","hint":"先行词 + （关系代词 + be动词） + 分词/形容词/介词短语","options":["独立主格结构","定语从句的省略形式","原因状语从句 (Adverbial Clause of Cause)","倒装语序"],"answer":1,"explain":"定语从句的省略形式：先行词 + （关系代词 + be动词） + 分词/形容词/介词短语：用于简化句子结构，使表达更简洁，常见于书面语","source":{"kind":"grammar","title":"定语从句的省略形式"},"id":"b4-u20-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nBut, of the vertebrates unpredictable Nature selected only snakes (and one lizard).","hint":"","options":["如果知识的这种双重用途，","但在脊椎动物中，变幻莫测的大自然只选择了蛇（和一种蜥蜴）。","从那时起，人们就很难确定这种航行器究竟是船、是飞机，","被出租车、卡车和公共汽车的噪音撕裂，并不断被大量人群挤满。"],"answer":1,"explain":"But, of the vertebrates unpredictable Nature selected only snakes (and one lizard). — 但在脊椎动物中，变幻莫测的大自然只选择了蛇（和一种蜥蜴）。","source":{"kind":"sentence","en":"But, of the vertebrates unpredictable Nature selected only snakes (and one lizard)."},"id":"b4-u20-q06"}]},{"id":"b4-u21","book":4,"unit":21,"key":"21","lessonFrom":21,"lessonTo":21,"title":"William S. Hart and the Early \"Western\" Film","titleZh":"威廉·S·哈特和早期“西部”片","question":"How did William Hart's childhood prepare him for his acting role in Western films?","sentences":[{"en":"William S. Hart was, perhaps, the greatest of all Western stars,","zh":"威廉·S·哈特也许是所有西部片明星中最伟大的。","t":22.05},{"en":"for unlike Gary Cooper and John Wayne he appeared in nothing but Westerns.","zh":"因为他不像加里·库珀和约翰·韦恩那样，他只出演西部片。","t":29.56},{"en":"From 1914 to 1924 he was supreme and unchallenged.","zh":"从1914到1924年，他独领风骚，无人能及。","t":36.57},{"en":"It was Hart who created the basic formula of the Western film,","zh":"是哈特创造了西部片的基本模式，","t":43.99},{"en":"and devised the protagonist he played in every film he made,","zh":"并设计了他所主演的每部影片中的主角，","t":48.96},{"en":"the good-bad man, the accidental, noble outlaw,","zh":"亦正亦邪的好坏人，偶然成为的正直的歹徒，","t":53.95},{"en":"or the honest, but framed cowboy, or the sheriff made suspect by vicious gossip;","zh":"或是诚实但遭诬陷的牛仔，或是因流言蜚语而受到怀疑的警长；","t":58.84},{"en":"in short, the individual in conflict with himself and his frontier environment.","zh":"简而言之，就是与自己和其边疆环境相冲突的个体。","t":66.09},{"en":"Unlike most of his contemporaries in Hollywood,","zh":"与他在好莱坞的大多数同时代演员不同，","t":73.78},{"en":"Hart actually knew something of the old West.","zh":"哈特确实了解一些旧西部。","t":77.06},{"en":"He had lived in it as a child when it was already disappearing,","zh":"他小时候曾生活在那个已经逐渐消失的西部，","t":81.02},{"en":"and his hero was firmly rooted in his memories and experiences,","zh":"他的英雄人物深深扎根于他的记忆和经历中，","t":85},{"en":"and in both the history and the mythology of the vanished frontier,","zh":"以及在消逝边疆的历史和神话中。","t":90.03},{"en":"And although no period or place in American history has been more absurdly romanticized,","zh":"尽管美国历史上没有任何一个时期或地方比西部更被荒谬地浪漫化，","t":95.67},{"en":"myth and reality did join hands in at least one arena,","zh":"但神话和现实至少在一个领域联手了，","t":103.23},{"en":"the conflict between the individual and encroaching civilization.","zh":"那就是个体与入侵文明之间的冲突。","t":108.63},{"en":"Men accustomed to struggling for survival against the elements and Indians","zh":"习惯于与自然元素和印第安人斗争求生的人们，","t":115.22},{"en":"were bewildered by politicians, bankers and businessmen,","zh":"被政客、银行家和商人搞得手足无措，","t":120.82},{"en":"and unhorsed by fences, laws and alien taboos.","zh":"被篱笆、法律和陌生的禁忌所限制。","t":125.36},{"en":"Hart's good-bad man was always an outsider, always one of the disinherited,","zh":"哈特的“亦正亦邪的好坏人”总是一个局外人，一个被剥夺继承权的人，","t":131.49},{"en":"and if he found it necessary to shoot a sheriff or rob a bank along the way,","zh":"如果他觉得有必要射杀一名警长或沿途抢劫一家银行，","t":138.91},{"en":"his early audiences found it easy to understand and forgive,","zh":"他的早期观众很容易理解并原谅，","t":145.08},{"en":"especially when it was Hart who, in the end, overcame the attacking Indians.","zh":"尤其当最终是哈特击败了来犯的印第安人时。","t":149.62},{"en":"Audiences in the second decade of the twentieth century","zh":"二十世纪第二个十年的观众","t":156.66},{"en":"found it pleasant to escape to a time when life, though hard, was relatively simple.","zh":"乐于逃到一个虽然艰辛但相对简单的时代。","t":160.32},{"en":"We still do; living in a world in which undeclared aggression, war, hypocrisy,","zh":"我们现在仍然如此；生活在一个不宣而战的侵略、战争、虚伪、","t":166.64},{"en":"chicanery, anarchy and impending immolation are part of our daily lives,","zh":"诡计、无政府状态和即将到来的毁灭是我们日常生活一部分的世界里，","t":173.66},{"en":"we all want a code to live by.","zh":"我们都渴望有一个行为准则。","t":179.89}],"vocab":[{"word":"supreme","phonetic":"/suːˈpriːm/","meanings":[{"pos":"adjective","meaning":"最高的；至高的；无比的","usage":"常用于形容地位、权力或水平处于最高级别，没有可与之匹敌的"}]},{"word":"unchallenged","phonetic":"/ʌnˈtʃælɪndʒd/","meanings":[{"pos":"adjective","meaning":"未受到挑战的；无人质疑的","usage":"用来描述地位、观点等没有受到反对或质疑"}]},{"word":"formula","phonetic":"/ˈfɔːmjələ/","meanings":[{"pos":"noun","meaning":"公式；准则；固定模式","usage":"本文中指文艺作品的固定创作模式，也可指数学、化学公式或解决问题的固定方法"}]},{"word":"protagonist","phonetic":"/prəˈtæɡənɪst/","meanings":[{"pos":"noun","meaning":"主角；主人公","usage":"特指戏剧、电影、小说等文艺作品中的核心主要人物"}]},{"word":"outlaw","phonetic":"/ˈaʊtlɔː/","meanings":[{"pos":"noun","meaning":"逃犯；被法律排斥者","usage":"指违反法律、逃亡在外的人，西部片中常指劫富济贫的边缘人物"}]},{"word":"framed","phonetic":"/freɪmd/","meanings":[{"pos":"adjective","meaning":"被诬陷的；被栽赃的","usage":"指被人伪造证据陷害，常用搭配be framed for sth.（因某事被诬陷）"}]},{"word":"vicious","phonetic":"/ˈvɪʃəs/","meanings":[{"pos":"adjective","meaning":"恶毒的；邪恶的","usage":"用来形容行为、话语等充满恶意，会对他人造成伤害"}]},{"word":"mythology","phonetic":"/mɪˈθɒlədʒi/","meanings":[{"pos":"noun","meaning":"神话；神话集","usage":"可指某一地区、文化的神话体系，也可指虚构的传说"}]},{"word":"vanished","phonetic":"/ˈvænɪʃt/","meanings":[{"pos":"adjective","meaning":"消失的；不复存在的","usage":"用来描述已经消失、不存在的事物，强调消失的结果"}]},{"word":"absurdly","phonetic":"/əbˈsɜːdli/","meanings":[{"pos":"adverb","meaning":"荒谬地；可笑地","usage":"修饰动词或形容词，用来强调某事物不合理、脱离实际"}]},{"word":"encroaching","phonetic":"/ɪnˈkrəʊtʃɪŋ/","meanings":[{"pos":"adjective","meaning":"渐渐渗透的；逐步侵蚀的","usage":"用来描述缓慢侵入、侵占原本不属于自己的领域的事物"}]},{"word":"bewildered","phonetic":"/bɪˈwɪldəd/","meanings":[{"pos":"adjective","meaning":"困惑的；不知所措的","usage":"形容人因为遇到不理解的事物而头脑混乱、不知道该如何处理"}]},{"word":"hypocrisy","phonetic":"/hɪˈpɒkrəsi/","meanings":[{"pos":"noun","meaning":"虚伪；伪善","usage":"指故意表现出自己实际不具备的道德、品质等，为贬义词"}]},{"word":"chicanery","phonetic":"/ʃɪˈkeɪnəri/","meanings":[{"pos":"noun","meaning":"欺诈；耍花招","usage":"指为了欺骗他人、获取利益而使用的不诚实手段，为正式用词"}]},{"word":"impending","phonetic":"/ɪmˈpendɪŋ/","meanings":[{"pos":"adjective","meaning":"即将发生的；迫在眉睫的","usage":"常用来形容不好的事情即将到来，如危险、灾难等"}]}],"phrases":[{"phrase":"nothing but","usage":"用来强调除了提到的事物之外没有其他，相当于only","examples":[{"en":"Unlike Gary Cooper and John Wayne he appeared in nothing but Westerns.","zh":"和加里·库珀以及约翰·韦恩不同，他只出演西部片。"},{"en":"After the accident, he could remember nothing but his childhood.","zh":"事故发生后，他除了自己的童年什么都记不起来了。"}]},{"phrase":"be rooted in","usage":"表示事物的根源、基础来源于某处，强调稳固的起源","examples":[{"en":"His hero was firmly rooted in his memories and experiences.","zh":"他塑造的英雄角色牢牢扎根于他的记忆和经历之中。"},{"en":"The traditional custom is rooted in local culture stretching back thousands of years.","zh":"这个传统习俗扎根于延续数千年的当地文化中。"}]},{"phrase":"join hands","usage":"字面意思是“牵手”，常引申为合作、联合、共同达成某一目标","examples":[{"en":"Myth and reality did join hands in at least one arena.","zh":"至少在一个领域里神话和现实确实是共存共通的。"},{"en":"The two countries will join hands to develop new energy technology.","zh":"两国将携手开发新能源技术。"}]},{"phrase":"accustomed to","usage":"表示习惯于某事物，to为介词，后接名词或动名词","examples":[{"en":"Men accustomed to struggling for survival against the elements and Indians were bewildered by politicians.","zh":"那些习惯了与自然和印第安人搏斗求生的人被政客们搞得晕头转向。"},{"en":"She is accustomed to working late and getting up early the next day.","zh":"她习惯了熬夜工作，第二天又早起。"}]},{"phrase":"in conflict with","usage":"表示与……有冲突、有矛盾，可指人和人之间，也可指人自身的思想矛盾","examples":[{"en":"The individual in conflict with himself and his frontier environment.","zh":"与自身以及边疆环境相冲突的个体。"},{"en":"His idea is in conflict with the general plan of the team.","zh":"他的想法和团队的整体规划相冲突。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用来突出强调句子某一部分（通常是主语、宾语、状语）的句式，不强调时可以还原为普通陈述句","structure":"It is/was + 被强调部分 + that/who + 句子其余部分","usage":"当被强调部分是人时，连接词可以用who，其他情况一律用that；该结构不强调谓语动词","examples":[{"en":"It was Hart who created the basic formula of the Western film.","zh":"正是哈特创造了西部片的基本范式。"},{"en":"It was not until I got home that I realized I had left my keys in the office.","zh":"直到我回到家我才意识到我把钥匙落在了办公室。"}]},{"title":"现在分词短语作定语","definition":"现在分词可以放在名词后面作定语，相当于一个定语从句，用来描述该名词的特征或正在进行的动作","structure":"名词 + 现在分词短语","usage":"当分词的动作是由所修饰的名词主动发出时，用现在分词作定语，可和被修饰名词构成逻辑上的主谓关系","examples":[{"en":"We still do; living in a world in which undeclared aggression, war, hypocrisy, chicanery, anarchy and impending immolation are part of our daily lives, we all want a code to live by.","zh":"我们仍然如此；生活在一个不宣而战的侵略、战争、虚伪、欺诈、无政府状态和迫在眉睫的毁灭都成为日常生活一部分的世界里，我们都需要一套赖以生存的行为准则。"},{"en":"The girl standing by the window is my younger sister.","zh":"站在窗边的那个女孩是我的妹妹。"}]}],"patterns":[{"pattern":"It is/was + 被强调的人 + who + 剩余句子成分","explanation":"","original":{"en":"It was Hart who created the basic formula of the Western film, and devised the protagonist he played in every film he made.","zh":"正是哈特创造了西部片的基本范式，并且设计出了他在自己每一部电影中扮演的主角形象。"},"examples":[{"en":"It was Edison who invented the practical incandescent light bulb and changed the way people live at night.","zh":"正是爱迪生发明了实用的白炽灯泡，改变了人们夜间的生活方式。"},{"en":"It was my mother who taught me to be honest and kind to others when I was a little child.","zh":"正是我的母亲在我小的时候就教我要为人诚实、与人为善。"}]},{"pattern":"find it + 形容词 + to do sth.","explanation":"","original":{"en":"Audiences in the second decade of the twentieth century found it pleasant to escape to a time when life, though hard, was relatively simple.","zh":"20世纪第二个十年的观众发现，逃到一个虽然艰苦但相对简单的时代是很愉快的。"},"examples":[{"en":"Many young people find it difficult to balance work and personal life in big cities.","zh":"很多年轻人发现在大城市里很难平衡工作和个人生活。"},{"en":"I find it necessary to learn a second foreign language in the context of globalization.","zh":"我发现在全球化的背景下，学习第二门外语是很有必要的。"}]},{"pattern":"unlike + 名词/代词, + 主句","explanation":"","original":{"en":"Unlike most of his contemporaries in Hollywood, Hart actually knew something of the old West.","zh":"和他在好莱坞的大多数同代人不同，哈特确实了解旧日西部的一些情况。"},"examples":[{"en":"Unlike most of his classmates, Tom prefers to spend his spare time reading rather than playing games.","zh":"和他的大多数同学不同，汤姆更喜欢把业余时间花在阅读上而不是打游戏。"},{"en":"Unlike other social media platforms, this app focuses on providing users with professional learning resources.","zh":"和其他社交媒体平台不同，这款应用专注于为用户提供专业的学习资源。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“未受到挑战的；无人质疑的” 对应的单词是？","hint":"adjective · /ʌnˈtʃælɪndʒd/","options":["enterprising","cosmopolitan","hovercraft","unchallenged"],"answer":3,"explain":"unchallenged · /ʌnˈtʃælɪndʒd/ · adjective · 未受到挑战的；无人质疑的。用来描述地位、观点等没有受到反对或质疑","source":{"kind":"vocab","word":"unchallenged"},"id":"b4-u21-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：困惑的；不知所措的","hint":"/bɪˈwɪldəd/ · adjective","answer":"bewildered","placeholder":"输入英文单词","explain":"bewildered · /bɪˈwɪldəd/ · adjective · 困惑的；不知所措的。形容人因为遇到不理解的事物而头脑混乱、不知道该如何处理","source":{"kind":"vocab","word":"bewildered"},"id":"b4-u21-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The individual _____ himself and his frontier environment.","hint":"与自身以及边疆环境相冲突的个体。","answer":"in conflict with","placeholder":"输入缺失的短语","explain":"in conflict with：表示与……有冲突、有矛盾，可指人和人之间，也可指人自身的思想矛盾（与自身以及边疆环境相冲突的个体。）","source":{"kind":"phrase","phrase":"in conflict with"},"id":"b4-u21-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：and unhorsed by fences, laws and alien _____","hint":"被篱笆、法律和陌生的禁忌所限制。","answer":"taboos","placeholder":"输入缺失的单词","explain":"and unhorsed by fences, laws and alien taboos. — 被篱笆、法律和陌生的禁忌所限制。","source":{"kind":"sentence","en":"and unhorsed by fences, laws and alien taboos."},"id":"b4-u21-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来突出强调句子某一部分（通常是主语、宾语、状语）的句式，不强调时可以还原为普通陈述句” 描述的是哪个语法点？","hint":"It is/was + 被强调部分 + that/who + 句子其余部分","options":["so that引导的结果状语从句","if引导的条件状语从句（表让步推测）","强调句 (Emphatic Sentence)","原因状语从句"],"answer":2,"explain":"强调句 (Emphatic Sentence)：It is/was + 被强调部分 + that/who + 句子其余部分：当被强调部分是人时，连接词可以用who，其他情况一律用that；该结构不强调谓语动词","source":{"kind":"grammar","title":"强调句 (Emphatic Sentence)"},"id":"b4-u21-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nMen accustomed to struggling for survival against the elements and Indians","hint":"","options":["生活在水里或水边的动植物遗骸最有可能被保存下来，","习惯于与自然元素和印第安人斗争求生的人们，","因此，我们很可能在65到80岁之间去世。","原来是货物、压舱物、弹药和400名船员滑向急剧倾斜的船只的左舷，发出撞击声。"],"answer":1,"explain":"Men accustomed to struggling for survival against the elements and Indians — 习惯于与自然元素和印第安人斗争求生的人们，","source":{"kind":"sentence","en":"Men accustomed to struggling for survival against the elements and Indians"},"id":"b4-u21-q06"}]},{"id":"b4-u22","book":4,"unit":22,"key":"22","lessonFrom":22,"lessonTo":22,"title":"Knowledge and Progress","titleZh":"知识与进步","question":"In what two areas have people made no 'progress' at all?","sentences":[{"en":"Why does the idea of progress loom so large in the modern world?","zh":"为什么进步的观念在现代世界如此重要？","t":15.87},{"en":"Surely because progress of a particular kind is actually taking place around us","zh":"当然是因为某种特定的进步确实正在我们身边发生","t":21.41},{"en":"and is becoming more and more manifest.","zh":"并且变得越来越明显。","t":27.63},{"en":"Although mankind has undergone no general improvement in intelligence or morality,","zh":"尽管人类在智力或道德方面没有取得普遍的进步，","t":30.31},{"en":"it has made extraordinary progress in the accumulation of knowledge.","zh":"但在知识积累方面取得了非凡的进步。","t":36.16},{"en":"Knowledge began to increase as soon as the thoughts of one individual","zh":"知识的增长始于个体思想","t":41.37},{"en":"could be communicated to another by means of speech.","zh":"可以通过言语传达给另一个人。","t":45.69},{"en":"With the invention of writing, a great advance was made,","zh":"随着书写的发明，取得了巨大的进步，","t":50.02},{"en":"for knowledge could then be not only communicated but also stored.","zh":"因为知识不仅可以交流，还可以储存。","t":53.67},{"en":"Libraries made education possible, and education in its turn added to libraries:","zh":"图书馆使教育成为可能，而教育反过来又丰富了图书馆：","t":58.66},{"en":"the growth of knowledge followed a kind of compound interest law,","zh":"知识的增长遵循了一种复利法则，","t":65.39},{"en":"which was greatly enhanced by the invention of printing.","zh":"印刷术的发明极大地促进了这一进程。","t":70.23},{"en":"All this was comparatively slow until, with the coming of science,","zh":"所有这些都相对缓慢，直到科学的到来，","t":74.03},{"en":"the tempo was suddenly raised.","zh":"节奏突然加快。","t":79.53},{"en":"Then knowledge began to be accumulated according to a systematic plan.","zh":"于是知识开始按照系统的计划积累。","t":81.95},{"en":"The trickle became a stream: the stream has now become a torrent.","zh":"涓涓细流汇成小溪：小溪现在已变成洪流。","t":87.44},{"en":"Moreover, as soon as new knowledge is acquired, it is now turned to practical account.","zh":"此外，一旦获得新知识，它现在就会被付诸实践。","t":92.98},{"en":"What is called 'modern civilization'","zh":"所谓的“现代文明”","t":99.18},{"en":"is not the result of a balanced development of all man's nature,","zh":"并非人类所有本性平衡发展的结果，","t":102.01},{"en":"but of accumulated knowledge applied to practical life.","zh":"而是积累的知识应用于实际生活的结果。","t":106.39},{"en":"The problem now facing humanity is:","zh":"人类现在面临的问题是：","t":111.47},{"en":"What is going to be done with all this knowledge?","zh":"所有这些知识将如何利用？","t":114.53},{"en":"As is so often pointed out, knowledge is a two-edged weapon","zh":"正如人们常指出的，知识是一把双刃剑","t":118.12},{"en":"which can be used equally for good or evil.","zh":"既可以用于善，也可以用于恶。","t":122.97},{"en":"It is now being used indifferently for both.","zh":"它现在被不加区分地同时用于两者。","t":126.88},{"en":"Could any spectacle, for instance, be more grimly whimsical","zh":"比如，还有什么景象比这更令人感到残酷又荒诞呢？","t":130.65},{"en":"than that of gunners using science to shatter men's bodies","zh":"炮兵利用科学来摧毁人的身体，","t":134.99},{"en":"while, close at hand, surgeons use it to restore them?","zh":"而身边的外科医生却利用科学来修复他们？","t":139.84},{"en":"We have to ask ourselves very seriously","zh":"我们必须非常严肃地问自己","t":144.72},{"en":"what will happen if this twofold use of knowledge,","zh":"如果知识的这种双重用途，","t":147.64},{"en":"with its ever-increasing power, continues.","zh":"及其不断增长的力量，继续下去，将会发生什么。","t":151.66}],"vocab":[{"word":"loom","phonetic":"/luːm/","meanings":[{"pos":"verb","meaning":"显得突出；赫然耸现","usage":"常用来形容问题、威胁等令人担忧且看似不可避免地出现，常用搭配loom large"},{"pos":"noun","meaning":"织布机","usage":"指用于纺织的机械设备"}]},{"word":"manifest","phonetic":"/ˈmænɪfest/","meanings":[{"pos":"adjective","meaning":"明显的，显而易见的","usage":"正式用词，强调无需解释就能看出的特征或事实"},{"pos":"verb","meaning":"表明，显示","usage":"指通过行动、态度等明确表现出某种情感或特质"}]},{"word":"undergo","phonetic":"/ˌʌndəˈɡəʊ/","meanings":[{"pos":"verb","meaning":"经历，经受（变化、不快的事等）","usage":"后面常接表示变化、考验、手术等的名词，过去式underwent，过去分词undergone"}]},{"word":"morality","phonetic":"/məˈræləti/","meanings":[{"pos":"noun","meaning":"道德，道德准则","usage":"指判断行为对错的标准体系，不可数名词"}]},{"word":"accumulation","phonetic":"/əˌkjuːmjəˈleɪʃn/","meanings":[{"pos":"noun","meaning":"积累，积聚","usage":"既可指积累的动作，也可指积累下来的事物，动词形式为accumulate"}]},{"word":"enhance","phonetic":"/ɪnˈhɑːns/","meanings":[{"pos":"verb","meaning":"提高，增强，增进","usage":"强调在原有基础上提升价值、吸引力、效果等，宾语常为声誉、效率、能力等抽象名词"}]},{"word":"tempo","phonetic":"/ˈtempəʊ/","meanings":[{"pos":"noun","meaning":"速度，节奏","usage":"既可指音乐的节拍，也可指活动、进程的发展速度，复数形式为tempos或tempi"}]},{"word":"trickle","phonetic":"/ˈtrɪkl/","meanings":[{"pos":"noun","meaning":"涓流，细流；稀稀落落的流动","usage":"指缓慢、少量的流动，也可作动词表示“滴，淌，缓慢移动”"}]},{"word":"torrent","phonetic":"/ˈtɒrənt/","meanings":[{"pos":"noun","meaning":"激流，洪流；爆发，迸发","usage":"可指汹涌的水流，也可形容大量涌现的事物，如a torrent of abuse（一通劈头盖脸的辱骂）"}]},{"word":"indifferently","phonetic":"/ɪnˈdɪfrəntli/","meanings":[{"pos":"adverb","meaning":"不在乎地，冷淡地；无关紧要地","usage":"此处表示对知识的两种用途不加区分地使用，形容词形式为indifferent"}]},{"word":"grimly","phonetic":"/ˈɡrɪmli/","meanings":[{"pos":"adverb","meaning":"冷酷地，讨厌地；严肃地","usage":"用来形容带有负面、令人不快的色彩的状态，形容词形式为grim"}]},{"word":"whimsical","phonetic":"/ˈwɪmzɪkl/","meanings":[{"pos":"adjective","meaning":"异想天开的，荒诞可笑的","usage":"形容事物古怪、出人意料，有时带有滑稽或讽刺的意味"}]},{"word":"shatter","phonetic":"/ˈʃætə(r)/","meanings":[{"pos":"verb","meaning":"打碎，破碎；破坏，毁坏","usage":"既可指物体突然碎裂成小块，也可指希望、信念等被彻底摧毁"}]},{"word":"twofold","phonetic":"/ˈtuːfəʊld/","meanings":[{"pos":"adjective","meaning":"双重的，两部分的","usage":"表示包含两个方面或部分，也可作副词表示“两倍地”"}]}],"phrases":[{"phrase":"loom large","usage":"表示（问题、忧虑等）显得突出、严重，让人担忧","examples":[{"en":"The threat of war loomed large in the country.","zh":"战争的威胁在这个国家显得十分严峻。"},{"en":"Exam season is looming large for all the students.","zh":"考试季越来越近，所有学生都压力很大。"}]},{"phrase":"by means of","usage":"介词短语，表示“通过…方式，借助…手段”，后面接名词或动名词","examples":[{"en":"The load was lifted by means of a crane.","zh":"重物是用起重机吊起来的。"},{"en":"We express our thoughts by means of words.","zh":"我们通过语言表达思想。"}]},{"phrase":"compound interest law","usage":"经济学术语，指“复利法则”，文中用来比喻知识增长的滚雪球效应","examples":[{"en":"The compound interest law allows small savings to grow significantly over time.","zh":"复利法则能让小额储蓄随着时间推移大幅增长。"},{"en":"Language learning follows a kind of compound interest law: the more you learn, the faster you acquire new knowledge.","zh":"语言学习遵循类似复利的规律：你学得越多，吸收新知识的速度就越快。"}]},{"phrase":"turn sth to practical account","usage":"表示“将某物付诸实际应用，利用某物”，也可写作put sth to practical use","examples":[{"en":"It is important to turn the theoretical knowledge we learn at university to practical account.","zh":"把我们在大学学到的理论知识付诸实际应用很重要。"},{"en":"The inventor finally turned his new invention to practical account in the manufacturing industry.","zh":"这位发明家最终将他的新发明应用到了制造业中。"}]},{"phrase":"two-edged weapon","usage":"固定表达，指“双刃剑”，用来形容事物同时有好坏两种作用","examples":[{"en":"Social media is a two-edged weapon: it connects people but also spreads misinformation easily.","zh":"社交媒体是一把双刃剑：它连接了人们，但也很容易传播虚假信息。"},{"en":"Nuclear technology is a two-edged weapon that can provide clean energy or cause massive destruction.","zh":"核技术是一把双刃剑，既可以提供清洁能源，也可能造成大规模破坏。"}]},{"phrase":"close at hand","usage":"表示“在附近，在手边”，强调距离很近","examples":[{"en":"Always keep a first-aid kit close at hand when you go camping.","zh":"去露营的时候要随时把急救包放在手边。"},{"en":"The shopping mall is close at hand, so we can go there to buy groceries anytime.","zh":"购物中心就在附近，我们随时可以去那里买日用品。"}]}],"grammar":[{"title":"as引导的非限制性定语从句","definition":"as可以引导非限制性定语从句，指代整个主句的内容，可放在主句之前、之中或之后，常翻译为“正如…，正像…”","structure":"As + 从句谓语, + 主句 / 主句, + as + 从句谓语","usage":"常见的固定结构有as is known to all（众所周知）、as is often the case（情况常常如此）、as is mentioned above（正如上文提到的）等","examples":[{"en":"As is so often pointed out, knowledge is a two-edged weapon which can be used equally for good or evil.","zh":"正如人们常常指出的，知识是一把双刃剑，既可以用于造福，也同样可以用来为害。"},{"en":"As is known to all, the earth moves around the sun.","zh":"众所周知，地球绕着太阳转。"},{"en":"He is late for class again, as is often the case.","zh":"他上课又迟到了，这是常有的事。"}]},{"title":"让步状语从句：although引导的让步关系","definition":"although用来引导让步状语从句，表示“虽然，尽管”，引导的从句可以放在主句前或主句后，不能与but同时出现在同一个句子中，但可以和yet、still连用","structure":"Although + 从句, + 主句 / 主句 + although + 从句","usage":"用于陈述与主句内容相反的情况，突出主句的内容","examples":[{"en":"Although mankind has undergone no general improvement in intelligence or morality, it has made extraordinary progress in the accumulation of knowledge.","zh":"虽然人类在智力和道德上没有得到普遍提高，但在知识积累方面却取得了惊人的进步。"},{"en":"Although he is quite old, he still leads an active life.","zh":"虽然他年事已高，但仍然过着活跃的生活。"},{"en":"I didn't buy the dress although it was of good quality.","zh":"我没有买那条裙子，尽管它质量很好。"}]}],"patterns":[{"pattern":"Why does... loom so large...? Surely because...","explanation":"","original":{"en":"Why does the idea of progress loom so large in the modern world? Surely because progress of a particular kind is actually taking place around us and is becoming more and more manifest.","zh":"为什么进步这个概念在现代世界显得如此突出？无疑是因为有一种特殊的进步实际上正在我们周围发生，而且变得越来越明显。"},"examples":[{"en":"Why does the issue of environmental protection loom so large in current discussions? Surely because climate change is having an increasing impact on people's daily lives.","zh":"为什么环境保护问题在当前的讨论中如此受重视？无疑是因为气候变化正对人们的日常生活产生越来越大的影响。"},{"en":"Why does the problem of youth employment loom so large in many countries? Surely because the number of graduates is growing faster than the job market can absorb.","zh":"为什么青年就业问题在很多国家显得十分严峻？无疑是因为毕业生数量的增长速度超过了就业市场的吸纳能力。"}]},{"pattern":"What is called... is not the result of..., but of...","explanation":"","original":{"en":"What is called 'modern civilization' is not the result of a balanced development of all man's nature, but of accumulated knowledge applied to practical life.","zh":"所谓“现代文明”并不是人的天性平衡发展的结果，而是积累起来的知识应用到实际生活中的结果。"},"examples":[{"en":"What is called 'fast success' is not the result of good luck, but of years of persistent effort behind the scenes.","zh":"所谓的“快速成功”并不是运气好的结果，而是多年默默坚持努力的结果。"},{"en":"What is called 'effective learning' is not the result of spending long hours studying mindlessly, but of using proper methods and staying focused.","zh":"所谓的“高效学习”并不是漫无目的地长时间学习的结果，而是使用正确方法并保持专注的结果。"}]},{"pattern":"Could any spectacle, for instance, be more... than that of...?","explanation":"","original":{"en":"Could any spectacle, for instance, be more grimly whimsical than that of gunners using science to shatter men's bodies while, close at hand, surgeons use it to restore them?","zh":"比如说，炮手用科学毁坏人体，而就在附近，外科医生用科学抢救被炮手毁坏的人体，还有什么情况比这种景象更怪诞得令人毛骨悚然的吗？"},"examples":[{"en":"Could any spectacle, for instance, be more ironic than that of people ordering takeout in disposable packaging while posting videos calling for plastic reduction online?","zh":"比如说，人们用一次性包装点外卖，同时又在网上发视频呼吁减少塑料使用，还有什么景象比这更讽刺的吗？"},{"en":"Could any spectacle, for instance, be more heartwarming than that of strangers coming together to help a family whose house was destroyed by a fire?","zh":"比如说，陌生人齐聚一堂帮助房屋被火灾摧毁的一家人，还有什么景象比这更暖心的吗？"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“涓流，细流；稀稀落落的流动” 对应的单词是？","hint":"noun · /ˈtrɪkl/","options":["bound","respectively","trickle","fowl"],"answer":2,"explain":"trickle · /ˈtrɪkl/ · noun · 涓流，细流；稀稀落落的流动。指缓慢、少量的流动，也可作动词表示“滴，淌，缓慢移动”","source":{"kind":"vocab","word":"trickle"},"id":"b4-u22-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：经历，经受（变化、不快的事等）","hint":"/ˌʌndəˈɡəʊ/ · verb","answer":"undergo","placeholder":"输入英文单词","explain":"undergo · /ˌʌndəˈɡəʊ/ · verb · 经历，经受（变化、不快的事等）。后面常接表示变化、考验、手术等的名词，过去式underwent，过去分词undergone","source":{"kind":"vocab","word":"undergo"},"id":"b4-u22-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Social media is a _____: it connects people but also spreads misinformation easily.","hint":"社交媒体是一把双刃剑：它连接了人们，但也很容易传播虚假信息。","answer":"two-edged weapon","placeholder":"输入缺失的短语","explain":"two-edged weapon：固定表达，指“双刃剑”，用来形容事物同时有好坏两种作用（社交媒体是一把双刃剑：它连接了人们，但也很容易传播虚假信息。）","source":{"kind":"phrase","phrase":"two-edged weapon"},"id":"b4-u22-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：the tempo was suddenly _____","hint":"节奏突然加快。","answer":"raised","placeholder":"输入缺失的单词","explain":"the tempo was suddenly raised. — 节奏突然加快。","source":{"kind":"sentence","en":"the tempo was suddenly raised."},"id":"b4-u22-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“as可以引导非限制性定语从句，指代整个主句的内容，可放在主句之前、之中或之后，常翻译为“正如…，正像…”” 描述的是哪个语法点？","hint":"As + 从句谓语, + 主句 / 主句, + as + 从句谓语","options":["定语从句的分隔现象","虚拟条件句的倒装结构","原因状语从句 (Adverbial Clause of Cause)","as引导的非限制性定语从句"],"answer":3,"explain":"as引导的非限制性定语从句：As + 从句谓语, + 主句 / 主句, + as + 从句谓语：常见的固定结构有as is known to all（众所周知）、as is often the case（情况常常如此）、as is mentioned above（正如上文提到的）等","source":{"kind":"grammar","title":"as引导的非限制性定语从句"},"id":"b4-u22-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nwhich can be used equally for good or evil.","hint":"","options":["他们还假设所有动物，","既可以用于善，也可以用于恶。","那些不喜欢噪音的人有时会使用最不充分的证据","美国、俄罗斯和欧洲都充满了热情的人士——其中许多是认真而资深的科学家，他们梦想着将人类送上火星。"],"answer":1,"explain":"which can be used equally for good or evil. — 既可以用于善，也可以用于恶。","source":{"kind":"sentence","en":"which can be used equally for good or evil."},"id":"b4-u22-q06"}]},{"id":"b4-u23","book":4,"unit":23,"key":"23","lessonFrom":23,"lessonTo":23,"title":"Bird Flight","titleZh":"鸟的飞行","question":"What are the two main types of bird flight described by the author?","sentences":[{"en":"No two sorts of birds practise quite the same sort of flight;","zh":"没有两种鸟的飞行方式是完全相同的；","t":17.99},{"en":"the varieties are infinite; but two classes may be roughly seen.","zh":"种类是无限的；但大致可分为两类。","t":23.47},{"en":"Any ship that crosses the Pacific","zh":"任何一艘横渡太平洋的船只","t":29.45},{"en":"is accompanied for many days by the smaller albatross,","zh":"会有较小的信天翁伴随数日，","t":31.59},{"en":"which may keep company with the vessel for an hour","zh":"它们可以陪伴船只一个小时","t":36.85},{"en":"without visible or more than occasional movement of wing.","zh":"翅膀几乎不动或只是偶尔动一下。","t":40.1},{"en":"The currents of air that the walls of the ship direct upwards,","zh":"船体向上引导的气流，","t":45.71},{"en":"as well as in the line of its course,","zh":"以及沿其航线的气流，","t":50.11},{"en":"are enough to give the great bird with its immense wings","zh":"足以为这种有着巨大翅膀的大鸟","t":53.78},{"en":"sufficient sustenance and progress.","zh":"提供足够的升力和前进动力。","t":57.45},{"en":"The albatross is the king of the gliders,","zh":"信天翁是滑翔之王，","t":60.84},{"en":"the class of fliers which harness the air to their purpose,","zh":"这类飞行者利用空气达到目的，","t":64.3},{"en":"but must yield to its opposition.","zh":"但也必须屈服于空气的阻力。","t":68.22},{"en":"In the contrary school, the duck is supreme.","zh":"在相反的学派中，鸭子是至高无上的。","t":71.61},{"en":"It comes nearer to the engines with which man has 'conquered' the air, as he boasts.","zh":"它更接近于人类声称“征服”天空的发动机。","t":76.22},{"en":"Duck, and like them the pigeons, are endowed with steel-like muscles,","zh":"鸭子，以及像它们一样的鸽子，都拥有钢铁般的肌肉，","t":82.79},{"en":"that are a good part of the weight of the bird,","zh":"这些肌肉占据了鸟类体重很大一部分，","t":90.24},{"en":"and these will ply the short wings with such irresistible power","zh":"它们以不可抗拒的力量挥动短小的翅膀，","t":93.32},{"en":"that they can bore for long distances through an opposing gale","zh":"可以在逆风中飞行很长的距离","t":98.48},{"en":"before exhaustion follows.","zh":"而不致精疲力尽。","t":103.04},{"en":"Their humbler followers, such as partridges,","zh":"它们较小的追随者，例如鹧鸪，","t":105.74},{"en":"have a like power of strong propulsion, but soon tire.","zh":"也有类似的强大推进力，但很快就会疲劳。","t":109.64},{"en":"You may pick them up in utter exhaustion,","zh":"你可能会发现它们筋疲力尽，","t":114.3},{"en":"if wind over the sea has driven them to a long journey.","zh":"如果海上的风迫使它们长途跋涉。","t":117.52},{"en":"The swallow shares the virtues of both schools in highest measure.","zh":"燕子则兼具这两种飞行的优点，而且达到了最高境界。","t":121.78},{"en":"It tires not, nor does it boast of its power; but belongs to the air","zh":"它不疲倦，也不炫耀自己的力量；它属于天空，","t":126.53},{"en":"travelling it may be six thousand miles to and from its northern nesting home,","zh":"也许飞行六千英里往返于它的北方巢穴，","t":133.01},{"en":"feeding its flown young as it flies, and slipping through a medium","zh":"边飞边喂养已经出巢的幼鸟，滑过介质","t":138.95},{"en":"that seems to help its passage even when the wind is adverse.","zh":"即使逆风，这介质似乎也在帮助它通过。","t":143.37},{"en":"Such birds do us good,","zh":"这样的鸟对我们有益，","t":148.78},{"en":"though we no longer take omens from their flight on this side and that;","zh":"尽管我们不再从它们飞行的方向来卜吉凶；","t":150.91},{"en":"and even the most superstitious villagers no longer take off their hats to the magpie and wish it good-morning.","zh":"甚至最迷信的村民也不再向喜鹊脱帽致意并祝它早上好。","t":156.29}],"vocab":[{"word":"infinite","phonetic":"/ˈɪnfɪnət/","meanings":[{"pos":"adjective","meaning":"无限的，无穷尽的","usage":"用来形容数量、种类或范围极大，没有边界或限制"}]},{"word":"albatross","phonetic":"/ˈælbətrɒs/","meanings":[{"pos":"noun","meaning":"信天翁","usage":"指一种大型海鸟，翅膀宽大，擅长滑翔飞行"}]},{"word":"vessel","phonetic":"/ˈvesl/","meanings":[{"pos":"noun","meaning":"船，舰；容器","usage":"正式用语，可指代大型船只，也可表示盛装液体的容器"}]},{"word":"immense","phonetic":"/ɪˈmens/","meanings":[{"pos":"adjective","meaning":"巨大的，极大的","usage":"用来强调尺寸、规模、程度等超乎寻常的大"}]},{"word":"sustenance","phonetic":"/ˈsʌstənəns/","meanings":[{"pos":"noun","meaning":"维持；食物，营养","usage":"可以指维持生命、活动所需的能量或支撑，也可直接指代食物"}]},{"word":"glider","phonetic":"/ˈɡlaɪdə(r)/","meanings":[{"pos":"noun","meaning":"滑翔机；滑翔动物","usage":"指依靠气流飞行、自身无需提供动力的飞行器或生物"}]},{"word":"harness","phonetic":"/ˈhɑːnɪs/","meanings":[{"pos":"verb","meaning":"控制并利用（自然力）","usage":"指将自然资源、能量等为己所用，发挥其作用"},{"pos":"noun","meaning":"马具，挽具","usage":"指套在牲畜身上用来拉车或农具的装备"}]},{"word":"yield","phonetic":"/jiːld/","meanings":[{"pos":"verb","meaning":"屈服，让步；产生，产出","usage":"作不及物动词时表示屈服于外力；作及物动词时表示产出作物、收益等"}]},{"word":"supreme","phonetic":"/suːˈpriːm/","meanings":[{"pos":"adjective","meaning":"最高的，至高的；最好的","usage":"用来形容等级、地位、能力等处于最高水平"}]},{"word":"endow","phonetic":"/ɪnˈdaʊ/","meanings":[{"pos":"verb","meaning":"赋予（天生的能力或品质）","usage":"常用被动结构be endowed with，表示天生具有某种特质、能力"}]},{"word":"ply","phonetic":"/plaɪ/","meanings":[{"pos":"verb","meaning":"不断使用，反复摆动","usage":"指反复、持续地使用某物或做某个动作"}]},{"word":"irresistible","phonetic":"/ˌɪrɪˈzɪstəbl/","meanings":[{"pos":"adjective","meaning":"不可抗拒的，无法抵挡的","usage":"形容力量、魅力等强大到让人无法抵抗"}]},{"word":"gale","phonetic":"/ɡeɪl/","meanings":[{"pos":"noun","meaning":"大风，狂风","usage":"气象学中特指风力较强的大风，也可引申为突发的喧闹声"}]},{"word":"propulsion","phonetic":"/prəˈpʌlʃn/","meanings":[{"pos":"noun","meaning":"推进力，动力","usage":"指推动物体向前运动的力量"}]},{"word":"adverse","phonetic":"/ˈædvɜːs/","meanings":[{"pos":"adjective","meaning":"不利的，有害的；相反的","usage":"用来形容条件、情况对某人或某事有负面影响"}]}],"phrases":[{"phrase":"keep company with","usage":"表示与某人/某物结伴、陪伴，强调同行的状态","examples":[{"en":"The dog kept company with the old man every day.","zh":"这只狗每天都陪着这位老人。"}]},{"phrase":"yield to","usage":"表示屈服、让步于某种力量、要求或诱惑，后接宾语","examples":[{"en":"We should never yield to difficulties no matter how hard they are.","zh":"无论困难多大，我们都不该向它们屈服。"}]},{"phrase":"be endowed with","usage":"被动结构，指天生具有某种优秀的能力、品质或特征","examples":[{"en":"She is endowed with a beautiful singing voice.","zh":"她天生有一副好歌喉。"}]},{"phrase":"in highest measure","usage":"正式表达，意思是“在最大程度上”，用来强调程度极高","examples":[{"en":"This new policy has benefited the local people in highest measure.","zh":"这项新政策最大程度地惠及了当地民众。"}]},{"phrase":"to and from","usage":"表示往返于两地之间，用来描述来回的动作","examples":[{"en":"He commutes to and from the company by subway every day.","zh":"他每天乘地铁往返于公司和家之间。"}]},{"phrase":"take omens from","usage":"表示从某事/某物中获取预兆、征兆，多用于和迷信相关的语境","examples":[{"en":"In ancient times, people took omens from the movement of stars.","zh":"古代人们会根据星辰的运行来判断预兆。"}]},{"phrase":"for long distances","usage":"表示长距离地，用来修饰表示移动、行进的动词","examples":[{"en":"Camels can travel for long distances in the desert without drinking water.","zh":"骆驼可以在沙漠中不喝水行进很长距离。"}]},{"phrase":"in utter exhaustion","usage":"表示完全筋疲力尽的状态，用来描述人或动物耗尽体力的样子","examples":[{"en":"After running the full marathon, he collapsed in utter exhaustion.","zh":"跑完整个马拉松之后，他筋疲力尽地倒下了。"}]}],"grammar":[{"title":"非限制性定语从句","definition":"用来对主句中的某个名词或整个主句进行补充说明，去掉之后不影响主句核心意思的完整，通常和主句之间用逗号隔开","structure":"主句 + , + which/who/whom/whose + 从句","usage":"用于补充说明先行词的额外信息，不对先行词起限定、区分的作用","examples":[{"en":"Any ship that crosses the Pacific is accompanied for many days by the smaller albatross, which may keep company with the vessel for an hour without visible or more than occasional movement of wing.","zh":"任何横渡太平洋的船只都会一连好多天有小信天翁相伴，这种鸟可以跟着船只飞行一小时，翅膀几乎看不见动，只是偶尔扇动一下。"},{"en":"The book, which I bought last week, is very interesting.","zh":"这本书我上周买的，非常有意思。"}]},{"title":"倒装语序","definition":"将句子的谓语部分或全部谓语提到主语之前的语序，常用于否定词开头的句子中，起到强调的作用","structure":"否定副词/短语 + 助动词/系动词/情态动词 + 主语 + 谓语剩余部分","usage":"当never、nor、not only等含有否定意义的词放在句首时，句子需要使用部分倒装结构","examples":[{"en":"It tires not, nor does it boast of its power.","zh":"它既不疲惫，也不炫耀自己的力量。"},{"en":"Never have I seen such a beautiful sunset.","zh":"我从来没见过这么美的日落。"}]}],"patterns":[{"pattern":"..., though we no longer...","explanation":"","original":{"en":"Such birds do us good, though we no longer take omens from their flight on this side and that.","zh":"这类鸟对我们是有益的，尽管我们不再从它们向不同方向的飞行中占卜预兆了。"},"examples":[{"en":"Old folk tales are still valuable, though we no longer believe all the stories in them.","zh":"古老的民间故事仍然有价值，尽管我们不再相信其中所有的内容了。"},{"en":"Handwritten letters are warm, though we no longer send them as often as before.","zh":"手写信很温暖，尽管我们不再像以前那样频繁寄信了。"}]},{"pattern":"X is the king of..., the class of... which...","explanation":"","original":{"en":"The albatross is the king of the gliders, the class of fliers which harness the air to their purpose, but must yield to its opposition.","zh":"信天翁是滑翔鸟类之王，这类飞禽能够利用气流达到飞行的目的，但也必须顺从气流的阻力。"},"examples":[{"en":"The tiger is the king of the forest, the group of predators which hunt most large animals in their habitat, but avoid conflicts with adult elephants.","zh":"老虎是森林之王，这类捕食者能够捕猎栖息地内的大多数大型动物，但会避免和成年大象发生冲突。"},{"en":"Beethoven is the king of classical composers, the group of musicians who created timeless works, but suffered from hearing loss in his later years.","zh":"贝多芬是古典作曲家中的王者，这类音乐家创作了永恒的作品，但他晚年饱受听力丧失的折磨。"}]},{"pattern":"X shares the virtues of both A and B in highest measure.","explanation":"","original":{"en":"The swallow shares the virtues of both schools in highest measure.","zh":"燕子最大程度地兼具了这两类鸟类的优点。"},"examples":[{"en":"This new type of electric car shares the virtues of both high speed and low energy consumption in highest measure.","zh":"这款新型电动汽车最大程度地兼具了高速度和低能耗的优点。"},{"en":"The new manager shares the virtues of both strong leadership and good communication skills in highest measure.","zh":"这位新经理最大程度地兼具了出色的领导力和优秀的沟通能力这两种优点。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“大风，狂风” 对应的单词是？","hint":"noun · /ɡeɪl/","options":["futile","odds","gale","longitudinal"],"answer":2,"explain":"gale · /ɡeɪl/ · noun · 大风，狂风。气象学中特指风力较强的大风，也可引申为突发的喧闹声","source":{"kind":"vocab","word":"gale"},"id":"b4-u23-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：滑翔机；滑翔动物","hint":"/ˈɡlaɪdə(r)/ · noun","answer":"glider","placeholder":"输入英文单词","explain":"glider · /ˈɡlaɪdə(r)/ · noun · 滑翔机；滑翔动物。指依靠气流飞行、自身无需提供动力的飞行器或生物","source":{"kind":"vocab","word":"glider"},"id":"b4-u23-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：This new policy has benefited the local people _____.","hint":"这项新政策最大程度地惠及了当地民众。","answer":"in highest measure","placeholder":"输入缺失的短语","explain":"in highest measure：正式表达，意思是“在最大程度上”，用来强调程度极高（这项新政策最大程度地惠及了当地民众。）","source":{"kind":"phrase","phrase":"in highest measure"},"id":"b4-u23-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：that are a good _____ of the weight of the bird,","hint":"这些肌肉占据了鸟类体重很大一部分，","answer":"part","placeholder":"输入缺失的单词","explain":"that are a good part of the weight of the bird, — 这些肌肉占据了鸟类体重很大一部分，","source":{"kind":"sentence","en":"that are a good part of the weight of the bird,"},"id":"b4-u23-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“将句子的谓语部分或全部谓语提到主语之前的语序，常用于否定词开头的句子中，起到强调的作用” 描述的是哪个语法点？","hint":"否定副词/短语 + 助动词/系动词/情态动词 + 主语 + 谓语剩余部分","options":["the + 比较级, the + 比较级 结构","as引导的非限制性定语从句","条件状语从句：unless引导","倒装语序"],"answer":3,"explain":"倒装语序：否定副词/短语 + 助动词/系动词/情态动词 + 主语 + 谓语剩余部分：当never、nor、not only等含有否定意义的词放在句首时，句子需要使用部分倒装结构","source":{"kind":"grammar","title":"倒装语序"},"id":"b4-u23-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nand even the most superstitious villagers no longer take off their hats to the magpie and wish it good-morning.","hint":"","options":["在它所选择的系列项目进行考量时，不应对其中任何一项有偏向性地加权。","甚至最迷信的村民也不再向喜鹊脱帽致意并祝它早上好。","后来发现有一种蚊子充当这种疾病的载体，并将其传播给兔子。","中国、韩国、菲律宾和印度的工程师正从加州的大学里大量毕业。"],"answer":1,"explain":"and even the most superstitious villagers no longer take off their hats to the magpie and wish it good-morning. — 甚至最迷信的村民也不再向喜鹊脱帽致意并祝它早上好。","source":{"kind":"sentence","en":"and even the most superstitious villagers no longer take off their hats to the magpie and wish it good-morning."},"id":"b4-u23-q06"}]},{"id":"b4-u24","book":4,"unit":24,"key":"24","lessonFrom":24,"lessonTo":24,"title":"Beauty","titleZh":"美","question":"What do glimpses of beauty, either in nature or art, often suggest to the human mind?","sentences":[{"en":"A young man sees a sunset and,","zh":"一个年轻人看到日落，","t":17.37},{"en":"unable to understand or to express the emotion that it rouses in him,","zh":"无法理解或表达它在他心中唤起的情感，","t":20},{"en":"concludes that it must be the gateway to a world that lies beyond","zh":"便断定它一定是通往一个彼岸世界的门户。","t":25.08},{"en":"It is difficult for any of us in moments of intense aesthetic experience","zh":"在强烈的审美体验时刻，我们任何人都很难","t":29.91},{"en":"to resist the suggestion that we are catching a glimpse of a light","zh":"抗拒这样一种暗示：我们正瞥见一道光，","t":35.38},{"en":"that shines down to us from a different realm of existence, different and,","zh":"它从一个不同的存在领域向我们照耀，一个不同且，","t":39.5},{"en":"because the experience is intensely moving, in some way higher.","zh":"因为这种体验极其动人，在某种程度上更高。","t":45.52},{"en":"And, though the gleams blind and dazzle, yet do they convey a hint of beauty and serenity","zh":"而且，尽管这些微光令人目眩神迷，它们却传达了一种美和宁静的暗示，","t":50.94},{"en":"greater than we have known or imagined. Greater too than we can describe;","zh":"超越了我们已知或想象的一切。也超越了我们所能描述的；","t":57.44},{"en":"for language, which was invented to convey the meanings of this world","zh":"因为语言是为了传达这个世界的意义而发明的，","t":62.99},{"en":"cannot readily be fitted to the uses of another.","zh":"无法轻易地适用于另一个世界的用途。","t":68},{"en":"That all great art has this power of suggesting a world beyond is undeniable.","zh":"所有伟大艺术都具有暗示一个彼岸世界的力量，这是无可否认的。","t":72.82},{"en":"In some moods, nature shares it.","zh":"在某些心境下，大自然也分享着这种力量。","t":79.84},{"en":"There is no sky in June so blue that it does not point forward to a bluer,","zh":"六月的天空，没有一片蓝不会指向更蓝；","t":83.37},{"en":"no sunset so beautiful that it does not waken the vision of a greater beauty,","zh":"没有一轮日落如此美丽，以至于它不会唤起对更伟大美的憧憬，","t":89.09},{"en":"a vision which passes before it is fully glimpsed,","zh":"一种尚未完全捕捉便已消逝的憧憬，","t":94.63},{"en":"and in passing leaves an indefinable longing and regret.","zh":"并在消逝中留下一种难以名状的渴望与遗憾。","t":98.23},{"en":"But, if this world is not merely a bad joke,","zh":"但是，如果这个世界不仅仅是一个糟糕的玩笑，","t":102.48},{"en":"life a vulgar flare amid the cool radiance of the stars,","zh":"生命不是群星凉爽光辉中一道庸俗的闪光，","t":105.95},{"en":"and existence an empty laugh braying across the mysteries;","zh":"存在也不是在奥秘中咆哮的空洞笑声；","t":110.05},{"en":"if these intimations of a something behind and beyond","zh":"如果这些关于某种在后和在上的暗示","t":114.91},{"en":"are not evil humour born of indigestion,","zh":"不是消化不良产生的恶趣味，","t":119.14},{"en":"or whimsies sent by the devil to mock and madden us, if, in a word","zh":"也不是魔鬼送来嘲弄和使我们发狂的怪念头，如果，一言以蔽之，","t":123},{"en":"beauty means something yet we must not seek to interpret the meaning.","zh":"美有所指，那么我们就不必去诠释它的意义。","t":128.8},{"en":"If we glimpse the unutterable, it is unwise to try to utter it,","zh":"如果我们瞥见了不可言说之物，试图言说它是不明智的，","t":134.61},{"en":"nor should we seek to invest with significance that which we cannot grasp.","zh":"我们也不应试图赋予我们无法把握的事物以意义。","t":139.73},{"en":"Beauty in terms of our human meanings is meaningless.","zh":"就我们人类的意义而言，美是无意义的。","t":145.93}],"vocab":[{"word":"glimpse","phonetic":"/ɡlɪmps/","meanings":[{"pos":"noun","meaning":"一瞥，一看","usage":"指短暂、粗略的看，常搭配catch/get a glimpse of表示“瞥见”"},{"pos":"verb","meaning":"瞥见，看一看","usage":"作及物动词，后直接接看到的对象"}]},{"word":"rouse","phonetic":"/raʊz/","meanings":[{"pos":"verb","meaning":"唤起，激起（情感、反应）","usage":"常用于被动语态be roused by，或后接情感类名词作宾语"},{"pos":"verb","meaning":"叫醒，唤醒","usage":"指把人从睡眠中叫醒"}]},{"word":"intense","phonetic":"/ɪnˈtens/","meanings":[{"pos":"adjective","meaning":"强烈的，剧烈的","usage":"可修饰情感、感受、活动等，强调程度很高"}]},{"word":"aesthetic","phonetic":"/iːsˈθetɪk/","meanings":[{"pos":"adjective","meaning":"审美的，美学的","usage":"常用于修饰体验、感受、标准等和审美相关的名词"}]},{"word":"realm","phonetic":"/relm/","meanings":[{"pos":"noun","meaning":"领域，范围","usage":"可指抽象的知识、活动、存在领域，也可指王国"}]},{"word":"serenity","phonetic":"/səˈrenəti/","meanings":[{"pos":"noun","meaning":"平静，宁静","usage":"指内心的平和或者环境的安静，是不可数名词"}]},{"word":"indefinable","phonetic":"/ˌɪndɪˈfaɪnəbl/","meanings":[{"pos":"adjective","meaning":"难以形容的，无法定义的","usage":"用于描述情感、特质等难以用语言准确说明的事物"}]},{"word":"longing","phonetic":"/ˈlɒŋɪŋ/","meanings":[{"pos":"noun","meaning":"渴望，憧憬","usage":"常接介词for表示对某事物的渴望"}]},{"word":"vulgar","phonetic":"/ˈvʌlɡə(r)/","meanings":[{"pos":"adjective","meaning":"粗俗的，庸俗的","usage":"用于形容品味、行为等缺乏美感、不够高雅"}]},{"word":"radiance","phonetic":"/ˈreɪdiəns/","meanings":[{"pos":"noun","meaning":"光辉，光芒","usage":"可指发光体发出的光，也可指人容光焕发的神态"}]},{"word":"intimation","phonetic":"/ˌɪntɪˈmeɪʃn/","meanings":[{"pos":"noun","meaning":"暗示，提示","usage":"指间接的、模糊的提示，常接介词of"}]},{"word":"whimsy","phonetic":"/ˈwɪmzi/","meanings":[{"pos":"noun","meaning":"怪念头，突发奇想","usage":"指异想天开、不合常理的想法，可数不可数均可"}]},{"word":"mock","phonetic":"/mɒk/","meanings":[{"pos":"verb","meaning":"嘲笑，嘲弄","usage":"后可直接接宾语，或搭配介词at"}]},{"word":"invest","phonetic":"/ɪnˈvest/","meanings":[{"pos":"verb","meaning":"赋予（某物某种属性）","usage":"常用搭配invest sth with sth，表示赋予某事物某种意义、权利等"},{"pos":"verb","meaning":"投资","usage":"常搭配介词in表示在某方面投资"}]},{"word":"unutterable","phonetic":"/ʌnˈʌtərəbl/","meanings":[{"pos":"adjective","meaning":"难以形容的，说不出的","usage":"用于描述情感、感受等强烈到无法用语言表达"}]}],"phrases":[{"phrase":"catch a glimpse of","usage":"表示短暂、不经意地瞥见某物，强调看到的时间短、不够清晰","examples":[{"en":"I caught a glimpse of the famous singer as she got into the car.","zh":"那位著名歌手上车的时候，我瞥见了她一眼。"},{"en":"From the window, we can catch a glimpse of the mountain.","zh":"从窗户我们可以望到山的一角。"}]},{"phrase":"be fitted to","usage":"表示适合、适应某用途或情况，强调匹配度","examples":[{"en":"This policy is fitted to the needs of local residents.","zh":"这项政策适合当地居民的需求。"},{"en":"Traditional tools are not always fitted to modern production needs.","zh":"传统工具并不总能适应现代生产的需求。"}]},{"phrase":"point forward to","usage":"指向，预示着某个更高级、更美好的事物，带有展望的含义","examples":[{"en":"Every small success in your study points forward to a bigger achievement in the future.","zh":"你学习中每一次小的成功都预示着未来会有更大的成就。"},{"en":"The warm breeze in early spring points forward to the coming of a vibrant summer.","zh":"早春温暖的微风预示着充满生机的夏天即将到来。"}]},{"phrase":"in a word","usage":"用于总结前文内容，意为“总而言之，简言之”，通常放在句首","examples":[{"en":"In a word, you need to practice more if you want to improve your spoken English.","zh":"总而言之，如果你想提高英语口语，就需要多练习。"},{"en":"The plan is creative, practical and low-cost. In a word, it's perfect.","zh":"这个计划有创意、可行而且成本低。总而言之，它非常完美。"}]},{"phrase":"invest...with...","usage":"表示赋予某事物某种意义、特质或权利，常用被动形式be invested with","examples":[{"en":"People often invest natural scenery with special emotional meanings.","zh":"人们常常赋予自然风景特殊的情感意义。"},{"en":"The ancient castle is invested with a sense of mystery by local legends.","zh":"当地的传说给这座古老的城堡赋予了一种神秘感。"}]},{"phrase":"in terms of","usage":"用于引出谈论的角度或范围，意为“就……而言，在……方面”","examples":[{"en":"In terms of nutrition, this vegetable is much better than potato.","zh":"就营养而言，这种蔬菜比土豆好得多。"},{"en":"The job is great in terms of salary, but it has its disadvantages.","zh":"就薪水而言，这份工作很棒，但它也有自己的缺点。"}]}],"grammar":[{"title":"双重否定结构","definition":"通过两个否定词的使用表达肯定的含义，语气比普通肯定句更强烈，起强调作用","structure":"no + 名词 + so + 形容词 + that + 否定从句","usage":"用于强调所有该类名词都具备从句中描述的特性，没有例外","examples":[{"en":"There is no sky in June so blue that it does not point forward to a bluer, no sunset so beautiful that it does not waken the vision of a greater beauty.","zh":"六月的天空无论多蓝，总会让人向往更蓝的天际；日落无论多美，总会唤起人们对更胜一筹的美景的想象。"},{"en":"There is no book so interesting that it does not have a dull part.","zh":"没有哪本书有趣到全无枯燥的部分。"},{"en":"There is no problem so difficult that it can not be solved.","zh":"没有什么问题难到无法解决。"}]},{"title":"状语从句的省略","definition":"当状语从句的主语和主句主语一致，且从句中含有be动词时，可以省略从句的主语和be动词，让句子更简洁","structure":"连词 + 现在分词/过去分词/介词短语/形容词","usage":"常用于时间、条件、让步等状语从句的简化","examples":[{"en":"A vision which passes before it is fully glimpsed, and in passing leaves an indefinable longing and regret.","zh":"这种幻象在我们尚未看清时就已消逝，在消失的过程中留下一种难以名状的渴望和怅惘。"},{"en":"When (you are) crossing the street, you should look both sides.","zh":"过马路的时候，你应该看看两边。"},{"en":"Though (he was) tired, he still finished the work on time.","zh":"尽管很累，他还是按时完成了工作。"}]},{"title":"同级比较的否定结构","definition":"用比较级的形式表达最高级的含义，说明某事物的程度已经达到无法超越的水平","structure":"主语 + be + 比较级 + than + 主语 + 情态动词 + 动词","usage":"用于强调事物的程度超出了主语的能力范围","examples":[{"en":"Greater too than we can describe; for language, which was invented to convey the meanings of this world cannot readily be fitted to the uses of another.","zh":"这种美也宏大到我们无法描述，因为语言是为了传达这个世界的意义而创造的，很难适用于另一个世界的表达需求。"},{"en":"The scenery here is more beautiful than I can say.","zh":"这里的风景美到我无法用语言形容。"},{"en":"The problem was more complicated than they had expected.","zh":"这个问题比他们预想的还要复杂。"}]}],"patterns":[{"pattern":"It is difficult for sb. in moments of... to resist the suggestion that...","explanation":"","original":{"en":"It is difficult for any of us in moments of intense aesthetic experience to resist the suggestion that we are catching a glimpse of a light that shines down to us from a different realm of existence, different and, because the experience is intensely moving, in some way higher.","zh":"当我们经历强烈的审美体验时，我们很难不产生这样的联想：我们瞥见了一束从另一个存在领域照向我们的光，那个领域与我们的世界不同，而且因为这种体验极为动人，在某种意义上也更崇高。"},"examples":[{"en":"It is difficult for any student in moments of getting a satisfactory exam score to resist the thought that all their hard work has paid off.","zh":"当学生拿到满意的考试成绩时，很难不觉得自己所有的努力都得到了回报。"},{"en":"It is difficult for anyone in moments of hearing this nostalgic song to resist the memory of their happy childhood in the small town.","zh":"任何人听到这首怀旧的歌曲时，都很难不回忆起自己在小镇度过的快乐童年。"}]},{"pattern":"There is no... so... that it does not..., no... so... that it does not...","explanation":"","original":{"en":"There is no sky in June so blue that it does not point forward to a bluer, no sunset so beautiful that it does not waken the vision of a greater beauty, a vision which passes before it is fully glimpsed, and in passing leaves an indefinable longing and regret.","zh":"六月的天空无论多蓝，总会让人向往更蓝的天际；日落无论多美，总会唤起人们对更胜一筹的美景的想象，这种幻象在我们尚未看清时就已消逝，在消失的过程中留下一种难以名状的渴望和怅惘。"},"examples":[{"en":"There is no book so useful that it does not have its limitations, no method so perfect that it does not have room for improvement.","zh":"没有哪本书有用到全无局限，没有哪种方法完美到没有改进空间。"},{"en":"There is no autumn leaf so red that it does not remind people of the coming cold winter, no harvest so joyful that it does not make people recall the hard work in spring.","zh":"没有哪片秋叶红到不让人想到寒冬将至，没有哪次收获喜悦到不让人回想春天的辛劳。"}]},{"pattern":"If we..., it is unwise to..., nor should we...","explanation":"","original":{"en":"If we glimpse the unutterable, it is unwise to try to utter it, nor should we seek to invest with significance that which we cannot grasp.","zh":"如果我们瞥见了无法言说的事物，试图去说出来是不明智的，我们也不应当试图赋予我们无法理解的事物某种意义。"},"examples":[{"en":"If we encounter a cultural custom we don't understand, it is unwise to judge it casually, nor should we impose our own values on it.","zh":"如果我们遇到自己不理解的文化习俗，随意评判是不明智的，我们也不应当把自己的价值观强加给它。"},{"en":"If we face an unexpected difficulty, it is unwise to panic immediately, nor should we give up without trying.","zh":"如果我们面对意料之外的困难，立刻恐慌是不明智的，我们也不应该还没尝试就放弃。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“光辉，光芒” 对应的单词是？","hint":"noun · /ˈreɪdiəns/","options":["eddy","radiance","maximum","boast"],"answer":1,"explain":"radiance · /ˈreɪdiəns/ · noun · 光辉，光芒。可指发光体发出的光，也可指人容光焕发的神态","source":{"kind":"vocab","word":"radiance"},"id":"b4-u24-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：领域，范围","hint":"/relm/ · noun","answer":"realm","placeholder":"输入英文单词","explain":"realm · /relm/ · noun · 领域，范围。可指抽象的知识、活动、存在领域，也可指王国","source":{"kind":"vocab","word":"realm"},"id":"b4-u24-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：From the window, we can _____ the mountain.","hint":"从窗户我们可以望到山的一角。","answer":"catch a glimpse of","placeholder":"输入缺失的短语","explain":"catch a glimpse of：表示短暂、不经意地瞥见某物，强调看到的时间短、不够清晰（从窗户我们可以望到山的一角。）","source":{"kind":"phrase","phrase":"catch a glimpse of"},"id":"b4-u24-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：A _____ man sees a sunset and,","hint":"一个年轻人看到日落，","answer":"young","placeholder":"输入缺失的单词","explain":"A young man sees a sunset and, — 一个年轻人看到日落，","source":{"kind":"sentence","en":"A young man sees a sunset and,"},"id":"b4-u24-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当状语从句的主语和主句主语一致，且从句中含有be动词时，可以省略从句的主语和be动词，让句子更简洁” 描述的是哪个语法点？","hint":"连词 + 现在分词/过去分词/介词短语/形容词","options":["状语从句的省略","it作形式主语的主语从句","not...but... 并列结构","It作形式主语的名词性从句"],"answer":0,"explain":"状语从句的省略：连词 + 现在分词/过去分词/介词短语/形容词：常用于时间、条件、让步等状语从句的简化","source":{"kind":"grammar","title":"状语从句的省略"},"id":"b4-u24-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nbecause the experience is intensely moving, in some way higher.","hint":"","options":["因为这种体验极其动人，在某种程度上更高。","理想主义者反对露营，就像反对跟团游一样，","据记载，托马斯·卡莱尔听说他的朋友亨利·泰勒生病时，","此外，不像其他一些食虫动物，蜘蛛从不对我们或我们的财物造成丝毫损害。"],"answer":0,"explain":"because the experience is intensely moving, in some way higher. — 因为这种体验极其动人，在某种程度上更高。","source":{"kind":"sentence","en":"because the experience is intensely moving, in some way higher."},"id":"b4-u24-q06"}]},{"id":"b4-u25","book":4,"unit":25,"key":"25","lessonFrom":25,"lessonTo":25,"title":"Non-Auditory Effects of Noise","titleZh":"噪音的非听觉效应","question":"What conclusion does the author draw about noise and health in this piece?","sentences":[{"en":"Many people in industry and the Services,","zh":"许多工业界和服务行业的人，","t":20.97},{"en":"who have practical experience of noise,","zh":"对噪音有实际经验，","t":24.92},{"en":"regard any investigation of this question as a waste of time;","zh":"认为对此问题的任何调查都是浪费时间；","t":28.11},{"en":"they are not prepared even to admit the possibility that noise affects people.","zh":"他们甚至不愿承认噪音会影响人们的可能性。","t":33.52},{"en":"On the other hand,","zh":"另一方面，","t":39.59},{"en":"those who dislike noise will sometimes use most inadequate evidence","zh":"那些不喜欢噪音的人有时会使用最不充分的证据","t":41.14},{"en":"to support their pleas for a quieter society.","zh":"来支持他们对更安静社会的呼吁。","t":46.05},{"en":"This is a pity, because noise abatement really is a good cause,","zh":"这很可惜，因为减少噪音确实是一项很好的事业，","t":51.24},{"en":"and it is likely to be discredited if it gets to be associated with bad science.","zh":"如果它与糟糕的科学联系起来，就可能会声名扫地。","t":57.25},{"en":"One allegation often made is that noise produces mental illness.","zh":"常见的一种说法是噪音会引起精神疾病。","t":64.03},{"en":"A recent article in a weekly newspaper, for instance,","zh":"例如，最近一家周报上的一篇文章，","t":69.78},{"en":"was headed with a striking illustration of a lady in a state of considerable distress,","zh":"开头是一幅引人注目的插图，描绘了一位极度痛苦的女士，","t":74.08},{"en":"with the caption 'She was yet another victim, reduced to a screaming wreck'.","zh":"配文是“她又是另一个受害者，沦为尖叫的废人”。","t":80.72},{"en":"On turning eagerly to the text, one learns that the lady was a typist","zh":"焦急地读下去，人们了解到这位女士是一名打字员，","t":88.22},{"en":"who found the sound of office typewriters worried her more and more","zh":"她发现办公室打字机的声音越来越让她烦恼，","t":93.76},{"en":"until eventually she had to go into a mental hospital.","zh":"直到最后她不得不进了精神病院。","t":97.86},{"en":"Now the snag in this sort of anecdote is of course that one cannot distinguish cause and effect.","zh":"这种轶事的症结当然在于无法区分因果。","t":102.71},{"en":"Was the noise a cause of the illness,","zh":"噪音是疾病的原因，","t":110.45},{"en":"or were the complaints about noise merely a symptom?","zh":"还是对噪音的抱怨仅仅是一种症状？","t":113.18},{"en":"Another patient might equally well complain","zh":"另一位病人也可能同样抱怨说","t":117.48},{"en":"that her neighbours were combining to slander her and persecute her,","zh":"她的邻居们合伙诽谤她、迫害她，","t":120.3},{"en":"and yet one might be cautious about believing this statement.","zh":"但人们可能会对相信这种说法持谨慎态度。","t":124.92},{"en":"What is needed in the case of noise is a study of large numbers of people living under noisy conditions,","zh":"对于噪音问题，需要对大量生活在嘈杂条件下的人进行研究，","t":129.74},{"en":"to discover whether they are mentally ill more often than other people are.","zh":"以发现他们是否比其他人更容易患精神疾病。","t":137.17},{"en":"Some time ago the United States Navy, for instance,","zh":"例如，前一段时间美国海军","t":142.66},{"en":"examined a very large number of men working on aircraft carriers:","zh":"检查了大量在航空母舰上工作的男性：","t":146.76},{"en":"the study was known as Project Anehin.","zh":"这项研究被称为“阿内欣计划”。","t":152},{"en":"It can be unpleasant to live even several miles from an aerodrome;","zh":"即使住在离机场几英里远的地方也会令人不快；","t":156.39},{"en":"if you think what it must be like to share the deck of a ship with several squadrons of jet aircraft,","zh":"如果你想象一下与几个中队的喷气式飞机共享一艘船的甲板会是怎样，","t":161.67},{"en":"you will realize that a modern navy is a good place to study noise.","zh":"你就会意识到现代海军是研究噪音的好地方。","t":168.6},{"en":"But neither psychiatric interviews nor objective tests","zh":"但是，无论是精神病学访谈还是客观测试，","t":174.98},{"en":"were able to show any effects upon these American sailors.","zh":"都未能显示出对这些美国水兵有任何影响。","t":179.61},{"en":"This result merely confirms earlier American and British studies:","zh":"这一结果仅仅证实了早期的美国和英国研究：","t":184.41},{"en":"if there is any effect of noise upon mental health,","zh":"如果噪音对心理健康有任何影响，","t":189.99},{"en":"it must be so small that present methods of psychiatric diagnosis cannot find it.","zh":"那么它一定非常微小，以至于目前的精神病诊断方法无法发现。","t":193.9},{"en":"That does not prove that it does not exist; but it does mean","zh":"这并不能证明它不存在；但它确实意味着","t":202.54},{"en":"that noise is less dangerous than, say being brought up in an orphanage","zh":"噪音的危险性低于，比如在孤儿院中长大，","t":207.73},{"en":"--which really is a mental health hazard.","zh":"——那才真的是一种心理健康危害。","t":213.72}],"vocab":[{"word":"non-auditory","phonetic":"/ˌnɒn ˈɔːdətri/","meanings":[{"pos":"adjective","meaning":"非听觉的","usage":"由前缀non-（表否定）和auditory（听觉的）构成，用于描述与听觉无关的事物"}]},{"word":"abatement","phonetic":"/əˈbeɪtmənt/","meanings":[{"pos":"noun","meaning":"减少，减轻，消除","usage":"不可数名词，常与表示负面事物的名词搭配，如noise abatement（降噪），pollution abatement（污染治理）"}]},{"word":"discredit","phonetic":"/dɪsˈkredɪt/","meanings":[{"pos":"verb","meaning":"败坏…的名声，使不可信","usage":"及物动词，宾语可以是人或某类主张、事业，常用被动结构be discredited"}]},{"word":"allegation","phonetic":"/ˌæləˈɡeɪʃn/","meanings":[{"pos":"noun","meaning":"（无证据的）说法，指控","usage":"可数名词，常搭配make an allegation that... 表示“提出某一未经证实的说法”"}]},{"word":"striking","phonetic":"/ˈstraɪkɪŋ/","meanings":[{"pos":"adjective","meaning":"引人注目的，显著的","usage":"可修饰人、事物或特征，用于描述容易引起注意的对象"}]},{"word":"distress","phonetic":"/dɪˈstres/","meanings":[{"pos":"noun","meaning":"痛苦，忧虑，窘迫","usage":"不可数名词，指精神或身体上的痛苦状态，in a state of distress表示“处于痛苦状态”"}]},{"word":"caption","phonetic":"/ˈkæpʃn/","meanings":[{"pos":"noun","meaning":"（图片的）说明文字，字幕","usage":"可数名词，特指图片、视频旁边或下方的解释性文字"}]},{"word":"snag","phonetic":"/snæɡ/","meanings":[{"pos":"noun","meaning":"潜在的问题，障碍","usage":"非正式用词，指计划、情况中未预料到的小问题，the snag in sth.表示“某事物中的问题”"}]},{"word":"anecdote","phonetic":"/ˈænɪkdəʊt/","meanings":[{"pos":"noun","meaning":"轶事，趣闻，传闻","usage":"可数名词，指基于个人经历的小故事，通常未经过科学证实"}]},{"word":"slander","phonetic":"/ˈslɑːndə(r)/","meanings":[{"pos":"verb","meaning":"诽谤，诋毁","usage":"及物动词，指通过说不实的话损害他人名誉，宾语为被诽谤的对象"}]},{"word":"persecute","phonetic":"/ˈpɜːsɪkjuːt/","meanings":[{"pos":"verb","meaning":"迫害，骚扰","usage":"及物动词，常指因种族、宗教、观点等原因恶意对待他人，常用被动be persecuted"}]},{"word":"psychiatric","phonetic":"/ˌsaɪkiˈætrɪk/","meanings":[{"pos":"adjective","meaning":"精神病学的，精神疾病的","usage":"用于修饰和精神疾病、精神病治疗相关的名词，如psychiatric interview（精神科访谈）"}]},{"word":"diagnosis","phonetic":"/ˌdaɪəɡˈnəʊsɪs/","meanings":[{"pos":"noun","meaning":"诊断（结果）","usage":"可数/不可数名词，复数形式为diagnoses，medical diagnosis表示“医学诊断”"}]},{"word":"orphanage","phonetic":"/ˈɔːfənɪdʒ/","meanings":[{"pos":"noun","meaning":"孤儿院","usage":"可数名词，也可指孤儿的身份，本文中表示机构含义"}]},{"word":"hazard","phonetic":"/ˈhæzəd/","meanings":[{"pos":"noun","meaning":"危险，危害","usage":"可数名词，health hazard表示“健康危害”，safety hazard表示“安全隐患”"}]}],"phrases":[{"phrase":"a waste of time","usage":"表示认为某件事没有价值、不值得花费时间，常用在regard/consider sth. as a waste of time结构中","examples":[{"en":"Many people regard debating this trivial issue as a waste of time.","zh":"很多人认为争论这个无关紧要的问题是浪费时间。"}]},{"phrase":"on the other hand","usage":"用于引出对比的另一方面观点或情况，常和on the one hand搭配使用，也可单独使用","examples":[{"en":"Online courses are very convenient. On the other hand, they lack the face-to-face interaction of traditional classes.","zh":"在线课程非常方便。另一方面，它们缺少传统课堂的面对面互动。"}]},{"phrase":"plea for","usage":"表示对某事物的恳求、请求，plea为名词，后接介词for引出请求的对象","examples":[{"en":"The local residents made a plea for more public green spaces in the community.","zh":"当地居民恳求在社区内建设更多公共绿地。"}]},{"phrase":"distinguish cause and effect","usage":"表示区分因果关系，是学术讨论、逻辑分析中的常用表达，也可写作distinguish between cause and effect","examples":[{"en":"When studying social phenomena, it is often difficult to distinguish cause and effect clearly.","zh":"研究社会现象时，往往很难清晰地区分因果关系。"}]},{"phrase":"be cautious about","usage":"表示对某事持谨慎态度，about后接名词或动名词","examples":[{"en":"You should be cautious about believing information from unknown sources on the Internet.","zh":"你要谨慎对待互联网上来源不明的信息，不要轻信。"}]},{"phrase":"in the case of","usage":"用于引出特定的讨论对象，意为“就…而言，在…的情况下”","examples":[{"en":"In the case of emergency, press the red button to cut off the power immediately.","zh":"在紧急情况下，按下红色按钮立即切断电源。"}]},{"phrase":"be reduced to","usage":"表示“沦落到…的境地，陷入某种（糟糕的）状态”，to为介词，后接名词或动名词","examples":[{"en":"After losing his job and savings, he was reduced to begging on the street.","zh":"失去工作和积蓄后，他沦落到在街上乞讨的地步。"}]},{"phrase":"mental health hazard","usage":"固定搭配，表示“心理健康危害”，用于描述会对人的精神状态造成负面影响的因素","examples":[{"en":"Long-term excessive use of social media has been proved to be a mental health hazard for teenagers.","zh":"长期过度使用社交媒体已被证实会对青少年的心理健康造成危害。"}]}],"grammar":[{"title":"插入语结构","definition":"插入语是句子中不充当主干成分、用于补充说明信息、调整语气的结构，去掉后句子的语法仍然完整","structure":"句子主干 + , 插入语, + 剩余句子成分 / 句首 + 插入语, + 句子主干","usage":"可以是介词短语、从句、固定表达等，用于补充背景、引出例子、表明说话者态度，使句子逻辑更连贯","examples":[{"en":"A recent article in a weekly newspaper, for instance, was headed with a striking illustration of a lady in a state of considerable distress.","zh":"例如，某周报的一篇文章开头配了一张引人注目的插图，图中是一位极度痛苦的女士。"},{"en":"This restaurant, in my opinion, serves the best Italian food in the city.","zh":"在我看来，这家餐厅供应全市最好吃的意大利菜。"}]},{"title":"if引导的条件状语从句（表让步推测）","definition":"if除了引导真实条件句，还可以引导带有让步含义的推测条件句，表示“即使、就算（某情况属实）”，用于先退一步承认可能的情况，再引出更重要的观点","structure":"If + 主语 + 表示可能性的谓语（如there is any, should be等）, 主句","usage":"常用于议论文中，体现论证的严谨性，先认可对方观点的可能性，再进一步提出更有说服力的结论","examples":[{"en":"If there is any effect of noise upon mental health, it must be so small that present methods of psychiatric diagnosis cannot find it.","zh":"就算噪音对心理健康有任何影响，这种影响也一定非常小，以至于目前的精神科诊断方法都无法检测出来。"},{"en":"If this new policy has some side effects, its benefits for the majority of people far outweigh the disadvantages.","zh":"就算这项新政策有一些副作用，它对大多数人的好处也远远大于弊端。"}]}],"patterns":[{"pattern":"This is a pity, because... really is a good cause, and it is likely to... if it gets to be associated with...","explanation":"","original":{"en":"This is a pity, because noise abatement really is a good cause, and it is likely to be discredited if it gets to be associated with bad science.","zh":"这很遗憾，因为降噪确实是一项有益的事业，如果它和不严谨的科学联系在一起，很可能会名声受损。"},"examples":[{"en":"This is a pity, because animal protection really is a good cause, and it is likely to be questioned if it gets to be associated with extreme behavior.","zh":"这很遗憾，因为动物保护确实是一项有益的事业，如果它和极端行为联系在一起，很可能会遭到质疑。"},{"en":"This is a pity, because traditional culture promotion really is a good cause, and it is likely to be disliked if it gets to be associated with excessive commercialization.","zh":"这很遗憾，因为传统文化推广确实是一项有益的事业，如果它和过度商业化联系在一起，很可能会遭到人们的反感。"}]},{"pattern":"Now the snag in this sort of... is of course that one cannot...","explanation":"","original":{"en":"Now the snag in this sort of anecdote is of course that one cannot distinguish cause and effect.","zh":"当然，这类传闻的问题在于人们无法区分因果关系。"},"examples":[{"en":"Now the snag in this sort of survey is of course that one cannot guarantee the authenticity of the respondents' answers.","zh":"当然，这类调查的问题在于人们无法保证受访者回答的真实性。"},{"en":"Now the snag in this sort of weight loss method is of course that one cannot maintain the effect for a long time.","zh":"当然，这类减肥方法的问题在于人们无法长期维持效果。"}]},{"pattern":"That does not prove that...; but it does mean that...","explanation":"","original":{"en":"That does not prove that it does not exist; but it does mean that noise is less dangerous than, say being brought up in an orphanage --which really is a mental health hazard.","zh":"那并不能证明这种影响不存在，但它确实说明，噪音的危害比比如在孤儿院长大这样真正的心理健康危害要小。"},"examples":[{"en":"That does not prove that this approach is completely useless; but it does mean that it is not suitable for large-scale promotion at this stage.","zh":"那并不能证明这个方法完全没用，但它确实说明，现阶段它不适合大规模推广。"},{"en":"That does not prove that he is lying; but it does mean that his description of the incident has many questionable points.","zh":"那并不能证明他在撒谎，但它确实说明，他对事件的描述存在很多疑点。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“危险，危害” 对应的单词是？","hint":"noun · /ˈhæzəd/","options":["creditor","cod","visualize","hazard"],"answer":3,"explain":"hazard · /ˈhæzəd/ · noun · 危险，危害。可数名词，health hazard表示“健康危害”，safety hazard表示“安全隐患”","source":{"kind":"vocab","word":"hazard"},"id":"b4-u25-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：非听觉的","hint":"/ˌnɒn ˈɔːdətri/ · adjective","answer":"non-auditory","placeholder":"输入英文单词","explain":"non-auditory · /ˌnɒn ˈɔːdətri/ · adjective · 非听觉的。由前缀non-（表否定）和auditory（听觉的）构成，用于描述与听觉无关的事物","source":{"kind":"vocab","word":"non-auditory"},"id":"b4-u25-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：You should _____ believing information from unknown sources on the Internet.","hint":"你要谨慎对待互联网上来源不明的信息，不要轻信。","answer":"be cautious about","placeholder":"输入缺失的短语","explain":"be cautious about：表示对某事持谨慎态度，about后接名词或动名词（你要谨慎对待互联网上来源不明的信息，不要轻信。）","source":{"kind":"phrase","phrase":"be cautious about"},"id":"b4-u25-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：that noise is _____ dangerous than, say being brought up in an orphanage","hint":"噪音的危险性低于，比如在孤儿院中长大，","answer":"less","placeholder":"输入缺失的单词","explain":"that noise is less dangerous than, say being brought up in an orphanage — 噪音的危险性低于，比如在孤儿院中长大，","source":{"kind":"sentence","en":"that noise is less dangerous than, say being brought up in an orphanage"},"id":"b4-u25-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“if除了引导真实条件句，还可以引导带有让步含义的推测条件句，表示“即使、就算（某情况属实）”，用于先退一步承认可能的情况，再引出更重要的观点” 描述的是哪个语法点？","hint":"If + 主语 + 表示可能性的谓语（如there is any, should be等）, 主句","options":["让步状语从句（however引导）","虚拟条件句的倒装结构","if引导的条件状语从句（表让步推测）","时间状语从句的省略"],"answer":2,"explain":"if引导的条件状语从句（表让步推测）：If + 主语 + 表示可能性的谓语（如there is any, should be等）, 主句：常用于议论文中，体现论证的严谨性，先认可对方观点的可能性，再进一步提出更有说服力的结论","source":{"kind":"grammar","title":"if引导的条件状语从句（表让步推测）"},"id":"b4-u25-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nMany people in industry and the Services,","hint":"","options":["噪音的危险性低于，比如在孤儿院中长大，","许多工业界和服务行业的人，","对于噪音问题，需要对大量生活在嘈杂条件下的人进行研究，","关注应用心理学，以及一个人与同胞和睦相处的能力。"],"answer":1,"explain":"Many people in industry and the Services, — 许多工业界和服务行业的人，","source":{"kind":"sentence","en":"Many people in industry and the Services,"},"id":"b4-u25-q06"}]},{"id":"b4-u26","book":4,"unit":26,"key":"26","lessonFrom":26,"lessonTo":26,"title":"The Past Life of the Earth","titleZh":"地球上的过去生命","question":"What is the main condition for the preservation of the remains of any living creature?","sentences":[{"en":"It is animals and plants which lived in or near water whose remains are most likely to be preserved,","zh":"生活在水里或水边的动植物遗骸最有可能被保存下来，","t":17.59},{"en":"for one of the necessary conditions of preservation is quick burial,","zh":"因为保存的必要条件之一是快速掩埋，","t":24.49},{"en":"and it is only in the seas and rivers, and sometimes lakes,","zh":"而只有在海洋、河流以及有时湖泊中，","t":30.4},{"en":"where mud and silt have been continuously deposited,","zh":"泥沙不断沉积的地方，","t":34.84},{"en":"that bodies and the like can be rapidly covered over and preserved.","zh":"尸体和类似的东西才能迅速被覆盖并保存下来。","t":38.72},{"en":"But even in the most favourable circumstances","zh":"但即使在最有利的条件下，","t":44.25},{"en":"only a small fraction of the creatures that die are preserved in this way","zh":"只有一小部分死去的生物能以这种方式保存下来，","t":47.63},{"en":"before decay sets in or, even more likely, before scavengers eat them.","zh":"在腐烂发生之前，或者更有可能，在食腐动物吃掉它们之前。","t":52.96},{"en":"After all, all living creatures live by feeding on something else,","zh":"毕竟，所有生物都靠捕食其他生物而生，","t":59.09},{"en":"whether it be plant or animal, dead or alive,","zh":"无论是植物还是动物，死的还是活的，","t":63.71},{"en":"and it is only by chance that such a fate is avoided.","zh":"只有偶然才能避免这种命运。","t":67.51},{"en":"The remains of plants and animals that lived on land are much more rarely preserved,","zh":"生活在陆地上的动植物遗骸保存下来的情况要少得多，","t":71.65},{"en":"for there is seldom anything to cover them over.","zh":"因为很少有什么东西能覆盖它们。","t":77.26},{"en":"When you think of the innumerable birds that one sees flying about,","zh":"当你想到无数飞来飞去的鸟儿，","t":80.71},{"en":"not to mention the equally numerous small animals like field mice and voles which you do not see,","zh":"更不用说你看不见的同样多的像田鼠和田鼠这样的小动物，","t":85.56},{"en":"it is very rarely that one comes across a dead body, except, of course, on the roads.","zh":"你很少会碰到一具尸体，当然除了在路上。","t":92.76},{"en":"They decompose and are quickly destroyed by the weather or eaten by some other creature.","zh":"它们会分解，很快被天气破坏或被其他生物吃掉。","t":99.14},{"en":"It is almost always due to some very special circumstances that traces of land animals survive,","zh":"陆地动物的痕迹几乎总是由于某些非常特殊的情况而得以幸存，","t":106.22},{"en":"as by falling into inaccessible caves, or into an ice crevasse,","zh":"比如掉进难以进入的洞穴，或者掉进冰裂缝，","t":113.83},{"en":"like the Siberian mammoths,","zh":"就像西伯利亚猛犸象一样，","t":119.26},{"en":"when the whole animal is sometimes preserved, as in a refrigerator.","zh":"有时整个动物都被保存下来，就像放在冰箱里一样。","t":121.4},{"en":"This is what happened to the famous Beresovka mammoth which was found preserved and in good condition.","zh":"著名的别列佐夫卡猛犸象就是这样，它被发现时保存完好。","t":126.58},{"en":"In his mouth were the remains of fir trees--the last meal that he had before he fell into the crevasse and broke his back.","zh":"它的嘴里有杉树的残骸——这是它掉进裂缝摔断背之前的最后一餐。","t":133.76},{"en":"The mammoth has now been restored in the Palaeontological Museum in St. Petersburg.","zh":"这头猛犸象现已在圣彼得堡的古生物博物馆修复。","t":143.19},{"en":"Other animals were trapped in tar pits, like the elephants, sabre-toothed cats,","zh":"其他动物被困在沥青坑里，比如大象、剑齿虎，","t":149.6},{"en":"and numerous other creatures that are found at Rancho la Brea, which is now just a suburb of Los Angeles.","zh":"以及在拉布雷亚牧场发现的无数其他生物，那里现在只是洛杉矶的一个郊区。","t":155.46},{"en":"Apparently what happened was that water collected on these tar pits","zh":"显然，这些沥青坑上积水了，","t":163.22},{"en":"and the bigger animals like the elephants ventured out on to the apparently firm surface to drink,","zh":"像大象这样的大型动物冒险走到看似坚实的表面去饮水，","t":168.29},{"en":"and were promptly bogged in the tar.","zh":"随即被困在沥青中。","t":175.69},{"en":"And then, when they were dead, the carnivores,","zh":"然后，当它们死去后，食肉动物，","t":178.49},{"en":"like the sabretoothed cats and the giant wolves,","zh":"比如剑齿虎和巨型狼，","t":181.94},{"en":"came out to feed and suffered exactly the same fate.","zh":"出来捕食，也遭受了同样的命运。","t":185.48},{"en":"There are also endless numbers of birds in the tar as well.","zh":"沥青中也有无数的鸟类。","t":190.68}],"vocab":[{"word":"preservation","phonetic":"/ˌprezəˈveɪʃn/","meanings":[{"pos":"noun","meaning":"保存；保留；保护","usage":"指对事物、生物遗骸等的长期留存，常和of搭配使用"}]},{"word":"remains","phonetic":"/rɪˈmeɪnz/","meanings":[{"pos":"noun","meaning":"遗骸；遗迹；剩余物","usage":"复数形式，可指生物的遗体、古生物的化石，也可指建筑等的遗迹"}]},{"word":"silt","phonetic":"/sɪlt/","meanings":[{"pos":"noun","meaning":"淤泥；泥沙","usage":"指河流、湖泊、海洋中沉积的细颗粒泥沙，不可数名词"}]},{"word":"deposit","phonetic":"/dɪˈpɒzɪt/","meanings":[{"pos":"verb","meaning":"沉积；堆积；存放","usage":"此处指泥沙等自然堆积，也可指存钱、放置物品"},{"pos":"noun","meaning":"沉积物；存款；押金","usage":"作名词时可指地质沉积物，也可用于金融场景"}]},{"word":"fraction","phonetic":"/ˈfrækʃn/","meanings":[{"pos":"noun","meaning":"小部分；少量；分数","usage":"a fraction of 表示“一小部分”，常用于强调数量极少"}]},{"word":"decay","phonetic":"/dɪˈkeɪ/","meanings":[{"pos":"noun","meaning":"腐烂；腐朽；衰退","usage":"指生物尸体的腐烂过程，也可指社会、制度的衰败"},{"pos":"verb","meaning":"腐烂；衰退；衰减","usage":"可作不及物动词，表示逐渐腐朽的过程"}]},{"word":"scavenger","phonetic":"/ˈskævɪndʒə(r)/","meanings":[{"pos":"noun","meaning":"食腐动物；拾荒者","usage":"指以腐烂的动植物尸体为食的动物，也指捡废品的人"}]},{"word":"innumerable","phonetic":"/ɪˈnjuːmərəbl/","meanings":[{"pos":"adjective","meaning":"无数的；数不清的","usage":"用于形容数量极多，难以计数，修饰可数名词"}]},{"word":"vole","phonetic":"/vəʊl/","meanings":[{"pos":"noun","meaning":"田鼠","usage":"指生活在田野中的小型啮齿动物，可数名词"}]},{"word":"decompose","phonetic":"/ˌdiːkəmˈpəʊz/","meanings":[{"pos":"verb","meaning":"分解；腐烂","usage":"指生物尸体被微生物分解的过程，也可指化学物质的分解"}]},{"word":"crevasse","phonetic":"/krəˈvæs/","meanings":[{"pos":"noun","meaning":"（冰川的）裂缝；裂隙","usage":"特指冰川、冰面上的深裂缝，可数名词"}]},{"word":"mammoth","phonetic":"/ˈmæməθ/","meanings":[{"pos":"noun","meaning":"猛犸象；长毛象","usage":"指史前已灭绝的大型象类，也可作形容词表示“巨大的”"}]},{"word":"fir","phonetic":"/fɜː(r)/","meanings":[{"pos":"noun","meaning":"冷杉；枞树","usage":"指常绿的冷杉属树木，可数名词"}]},{"word":"palaeontological","phonetic":"/ˌpæliɒntəˈlɒdʒɪkl/","meanings":[{"pos":"adjective","meaning":"古生物学的","usage":"和古生物研究相关的形容词，修饰博物馆、研究等名词"}]},{"word":"sabre-toothed","phonetic":"/ˈseɪbə tuːθt/","meanings":[{"pos":"adjective","meaning":"长着锐利长犬齿的，剑齿的","usage":"用于描述史前的剑齿虎等动物，作定语修饰名词"}]}],"phrases":[{"phrase":"by chance","usage":"表示“偶然；碰巧；意外地”，在句中作状语，说明事件发生的随机性","examples":[{"en":"It is only by chance that such a fate is avoided.","zh":"这种命运的逃脱完全是偶然的。"},{"en":"I met my old classmate by chance on the street yesterday.","zh":"我昨天在街上偶然碰到了我的老同学。"}]},{"phrase":"not to mention","usage":"表示“更不用说；别提”，用于补充说明前面提到的内容，强调程度更进一步","examples":[{"en":"When you think of the innumerable birds that one sees flying about, not to mention the equally numerous small animals like field mice and voles which you do not see, it is very rarely that one comes across a dead body.","zh":"想一想你看到的无数飞来飞去的鸟儿，更别提那些你看不到的同样多的田鼠之类的小动物，人们极少能见到它们的尸体。"},{"en":"He can speak French and German, not to mention English.","zh":"他会说法语和德语，更不用说英语了。"}]},{"phrase":"come across","usage":"表示“偶然遇见；无意中发现”，后面接遇见的人或发现的事物，无被动语态","examples":[{"en":"It is very rarely that one comes across a dead body, except, of course, on the roads.","zh":"人们极少能见到它们的尸体，当然除了在公路上。"},{"en":"I came across this old photo when I was cleaning the drawer.","zh":"我打扫抽屉的时候偶然发现了这张老照片。"}]},{"phrase":"due to","usage":"表示“由于；因为”，后面接名词或名词短语，说明原因，可位于句首或句中","examples":[{"en":"It is almost always due to some very special circumstances that traces of land animals survive.","zh":"陆地动物的遗迹几乎总是由于某些非常特殊的情况才得以保存下来。"},{"en":"The sports meeting was put off due to the bad weather.","zh":"由于天气不好，运动会被推迟了。"}]},{"phrase":"in good condition","usage":"表示“状态良好；保存完好”，用于描述物品、生物遗骸等的保存状态","examples":[{"en":"This is what happened to the famous Beresovka mammoth which was found preserved and in good condition.","zh":"著名的别列佐夫卡猛犸象就是这种情况，它被发现时保存完好。"},{"en":"The old book published 100 years ago is still in good condition.","zh":"这本100年前出版的旧书现在仍然保存完好。"}]},{"phrase":"be bogged in","usage":"表示“陷入；被困在”，通常指陷入泥浆、沼泽等难以脱身，也可引申为陷入困境","examples":[{"en":"The bigger animals like the elephants ventured out on to the apparently firm surface to drink, and were promptly bogged in the tar.","zh":"大象之类的大型动物冒险走到看似坚固的表面喝水，立刻就陷入了沥青中。"},{"en":"The car got bogged in the mud after the heavy rain.","zh":"大雨过后，汽车陷在了泥里。"}]},{"phrase":"set in","usage":"表示“（不好的事物）开始；到来”，通常指腐烂、恶劣天气等不好的情况开始并可能持续","examples":[{"en":"Only a small fraction of the creatures that die are preserved in this way before decay sets in.","zh":"只有一小部分死亡的生物能在腐烂开始之前以这种方式被保存下来。"},{"en":"Winter has set in early this year.","zh":"今年冬天来得早。"}]},{"phrase":"after all","usage":"表示“毕竟；终究”，用于引出解释或说明理由，放在句首或句中","examples":[{"en":"After all, all living creatures live by feeding on something else, whether it be plant or animal, dead or alive.","zh":"毕竟，所有生物都靠吃其他东西生存，不管是植物还是动物，死的还是活的。"},{"en":"You shouldn't scold him too much; after all, he is only a child.","zh":"你不该太责备他，毕竟他只是个孩子。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用来突出句子中的某个成分（主语、宾语、状语等），表达强烈语气的句子结构","structure":"It is/was + 被强调部分 + that/who + 其他部分","usage":"被强调部分指人时可用who，其他情况一般用that；即使被强调的是时间、地点状语，也用that而不用when/where","examples":[{"en":"It is animals and plants which lived in or near water whose remains are most likely to be preserved.","zh":"正是生活在水中或水边的动植物，它们的遗骸最有可能被保存下来。"},{"en":"It is only in the seas and rivers, and sometimes lakes, where mud and silt have been continuously deposited, that bodies and the like can be rapidly covered over and preserved.","zh":"只有在海洋、河流，有时是湖泊里，泥沙不断沉积，尸体之类的东西才能被迅速覆盖并保存下来。"},{"en":"It was yesterday that I finished the research report.","zh":"就是在昨天我完成了这份研究报告。"}]},{"title":"虚拟语气在让步状语从句中的用法","definition":"在whether引导的让步状语从句中，表达“不管是……还是……”的含义时，可使用be型虚拟语气，即不管主语是什么人称，动词都用原形be","structure":"whether + 主语 + be + 表语 + or + 表语，主句","usage":"这种结构多用于正式文体中，口语中常用一般现在时代替；也可将whether省略，把be提前到句首构成倒装","examples":[{"en":"After all, all living creatures live by feeding on something else, whether it be plant or animal, dead or alive.","zh":"毕竟，所有生物都靠吃其他东西生存，不管是植物还是动物，死的还是活的。"},{"en":"Every person, whether he be rich or poor, has equal rights in the country.","zh":"在这个国家，每个人无论贫富，都享有平等的权利。"},{"en":"Be it rainy or sunny, we will start the journey as planned.","zh":"不管下雨还是天晴，我们都会按计划出发。"}]},{"title":"完全倒装 (Full Inversion)","definition":"将句子中的谓语动词完全移到主语之前的倒装结构，常用于强调状语或表语","structure":"表示方位/时间的副词/介词短语/表语 + 谓语动词 + 主语","usage":"当句首是表示地点、时间的介词短语，或者表语被提前时，常使用完全倒装；主语必须是名词，若主语是代词则不需要倒装","examples":[{"en":"In his mouth were the remains of fir trees--the last meal that he had before he fell into the crevasse and broke his back.","zh":"它嘴里还留着冷杉的残骸——这是它掉进冰缝摔断背之前吃的最后一餐。"},{"en":"Under the tree sat an old man reading a newspaper.","zh":"树下坐着一位老人正在看报纸。"},{"en":"Present at the meeting were experts from all over the world.","zh":"出席会议的是来自世界各地的专家。"}]}],"patterns":[{"pattern":"One of the necessary conditions of ... is ...","explanation":"","original":{"en":"One of the necessary conditions of preservation is quick burial.","zh":"保存的必要条件之一是迅速掩埋。"},"examples":[{"en":"One of the necessary conditions of success is persistent effort.","zh":"成功的必要条件之一是持续的努力。"},{"en":"One of the necessary conditions of maintaining good health is having a balanced diet.","zh":"保持身体健康的必要条件之一是均衡饮食。"}]},{"pattern":"It is almost always due to ... that ...","explanation":"","original":{"en":"It is almost always due to some very special circumstances that traces of land animals survive.","zh":"陆地动物的遗迹几乎总是由于某些非常特殊的情况才得以保存下来。"},"examples":[{"en":"It is almost always due to careful preparation that a speech is successful.","zh":"演讲的成功几乎总是由于精心的准备。"},{"en":"It is almost always due to lack of exercise that people gain weight easily.","zh":"人们容易长胖几乎总是由于缺乏锻炼。"}]},{"pattern":"Apparently what happened was that ...","explanation":"","original":{"en":"Apparently what happened was that water collected on these tar pits and the bigger animals like the elephants ventured out on to the apparently firm surface to drink, and were promptly bogged in the tar.","zh":"显然当时的情况是，这些沥青坑上积了水，大象之类的大型动物冒险走到看似坚固的表面喝水，立刻就陷入了沥青中。"},"examples":[{"en":"Apparently what happened was that he forgot to set the alarm and was late for work.","zh":"显然当时的情况是，他忘了设闹钟，所以上班迟到了。"},{"en":"Apparently what happened was that the server broke down suddenly and all the data was lost.","zh":"显然当时的情况是，服务器突然崩溃，所有数据都丢失了。"}]},{"pattern":"Only a small fraction of ... that ... are ...","explanation":"","original":{"en":"Only a small fraction of the creatures that die are preserved in this way before decay sets in or, even more likely, before scavengers eat them.","zh":"只有一小部分死亡的生物能在腐烂开始之前，或者更有可能的是，在被食腐动物吃掉之前，以这种方式被保存下来。"},"examples":[{"en":"Only a small fraction of the people that apply for the job are finally selected.","zh":"申请这份工作的人当中只有一小部分最终会被选中。"},{"en":"Only a small fraction of the ancient buildings that were built hundreds of years ago are still well preserved today.","zh":"数百年前建造的古建筑中只有一小部分至今仍保存完好。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“冷杉；枞树” 对应的单词是？","hint":"noun · /fɜː(r)/","options":["literally","irresistible","aggravate","fir"],"answer":3,"explain":"fir · /fɜː(r)/ · noun · 冷杉；枞树。指常绿的冷杉属树木，可数名词","source":{"kind":"vocab","word":"fir"},"id":"b4-u26-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：沉积；堆积；存放","hint":"/dɪˈpɒzɪt/ · verb","answer":"deposit","placeholder":"输入英文单词","explain":"deposit · /dɪˈpɒzɪt/ · verb · 沉积；堆积；存放。此处指泥沙等自然堆积，也可指存钱、放置物品","source":{"kind":"vocab","word":"deposit"},"id":"b4-u26-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, all living creatures live by feeding on something else, whether it be plant or animal, dead or alive.","hint":"毕竟，所有生物都靠吃其他东西生存，不管是植物还是动物，死的还是活的。","answer":"after all","placeholder":"输入缺失的短语","explain":"after all：表示“毕竟；终究”，用于引出解释或说明理由，放在句首或句中（毕竟，所有生物都靠吃其他东西生存，不管是植物还是动物，死的还是活的。）","source":{"kind":"phrase","phrase":"after all"},"id":"b4-u26-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：They decompose and are quickly _____ by the weather or eaten by some other creature.","hint":"它们会分解，很快被天气破坏或被其他生物吃掉。","answer":"destroyed","placeholder":"输入缺失的单词","explain":"They decompose and are quickly destroyed by the weather or eaten by some other creature. — 它们会分解，很快被天气破坏或被其他生物吃掉。","source":{"kind":"sentence","en":"They decompose and are quickly destroyed by the weather or eaten by some other creature."},"id":"b4-u26-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来突出句子中的某个成分（主语、宾语、状语等），表达强烈语气的句子结构” 描述的是哪个语法点？","hint":"It is/was + 被强调部分 + that/who + 其他部分","options":["原因状语从句 (Adverbial Clause of Cause)","强调句 (Emphatic Sentence)","虚拟语气（与现在事实相反的非真实条件句）","关系副词where与关系代词who引导的限定性定语从句"],"answer":1,"explain":"强调句 (Emphatic Sentence)：It is/was + 被强调部分 + that/who + 其他部分：被强调部分指人时可用who，其他情况一般用that；即使被强调的是时间、地点状语，也用that而不用when/where","source":{"kind":"grammar","title":"强调句 (Emphatic Sentence)"},"id":"b4-u26-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAnd then, when they were dead, the carnivores,","hint":"","options":["但如果想要取得任何真正重大的进展，就需要比这精巧得多的仪器。","我们努力避免那种老式的、浪漫的喷油井，那只会浪费石油和天然气。","你可能会决定采取激进的策略——但前提是你拥有乐观的性格，并且不会因为股价而彻夜难眠。","然后，当它们死去后，食肉动物，"],"answer":3,"explain":"And then, when they were dead, the carnivores, — 然后，当它们死去后，食肉动物，","source":{"kind":"sentence","en":"And then, when they were dead, the carnivores,"},"id":"b4-u26-q06"}]},{"id":"b4-u27","book":4,"unit":27,"key":"27","lessonFrom":27,"lessonTo":27,"title":"The \"vasa\"","titleZh":"“瓦萨”号","question":"What happened to the 'Vasa' almost immediately after she was launched?","sentences":[{"en":"From the seventeenth-century empire of Sweden,","zh":"17世纪的瑞典王国","t":20.57},{"en":"the story of a galleon that sank at the start of her maiden voyage in 1628 must be one of the strangest tales of the sea.","zh":"一艘名为“瓦萨”的帆船在1628年首次出航时就沉没了。这个故事一定是航海史上最离奇的事件之一。","t":24.32},{"en":"For nearly three and a half centuries she lay at the bottom of Stockholm harbour until her discovery in 1956.","zh":"她在斯德哥尔摩港湾海底沉睡了将近3个半世纪，直到1956年才被发现。","t":34.84},{"en":"This was the Vasa, royal flagship of the great imperial fleet.","zh":"这就是“瓦萨”号，一支强大皇家舰队的旗舰。","t":44.34},{"en":"King Gustavus Adolphus 'The Northern Hurricane',","zh":"国王古斯塔夫·阿道夫，人称“北方飓风”，","t":51.53},{"en":"then at the height of his military success in the 'Thirty Years' War,","zh":"当时正处于“三十年战争”军事胜利的巅峰时期，","t":56.23},{"en":"had dictated her measurements and armament.","zh":"亲自规定了“瓦萨”号的尺寸和武器装备。","t":61.33},{"en":"Triple gun-decks mounted sixty-four bronze cannon.","zh":"三层炮甲板上装载着64门青铜大炮。","t":65.42},{"en":"She was intended to play a leading role in the growing might of Sweden.","zh":"她注定要在瑞典日益壮大的国力中扮演重要角色。","t":70.73},{"en":"As she was prepared for her maiden voyage on August 10, 1628, Stockholm was in a ferment.","zh":"1628年8月10日，“瓦萨”号准备首次航行，斯德哥尔摩一片沸腾。","t":76.84},{"en":"From the Skeppsbron and surrounding islands","zh":"从海事博物馆码头和周围的岛屿，","t":87.58},{"en":"the people watched this thing of beauty begin to spread her sails and catch the wind.","zh":"人们看着这艘美丽的船开始张帆起航，乘风破浪。","t":90.64},{"en":"They had laboured for three years to produce this floating work of art;","zh":"人们辛劳了3年才建造出这艘漂浮的艺术品；","t":97.8},{"en":"she was more richly carved and ornamented than any previous ship.","zh":"她比以往任何一艘船都雕刻得更精美，装饰得更华丽。","t":104.16},{"en":"The high stern castle was a riot of carved gods, demons, knights, kings, warriors,","zh":"高高的船尾楼雕刻着众神、恶魔、骑士、国王、武士、","t":110.09},{"en":"mermaids, cherubs; and zoomorphic animal shapes ablaze with red and gold and blue,","zh":"美人鱼、小天使；还有栩栩如生的动物造型，它们都被漆成红、金和蓝色，","t":118.9},{"en":"symbols of courage, power, and cruelty,","zh":"象征着勇气、力量和残酷，","t":126.37},{"en":"were portrayed to stir the imaginations of the superstitious sailors of the day.","zh":"旨在激发当时迷信水手们的想象力。","t":130.57},{"en":"Then the cannons of the anchored warships thundered a salute to which the Vasa fired in reply.","zh":"锚泊的军舰鸣炮致敬，“瓦萨”号也鸣炮回敬。","t":137.23},{"en":"As she emerged from her drifting cloud of gun smoke with the water churned to foam beneath her bow,","zh":"当她从漂浮的硝烟中驶出，船头下的水花翻腾成泡沫，","t":145.64},{"en":"her flags flying, pennants waving, sails filling in the breeze,","zh":"旗帜飘扬，三角旗招展，风帆鼓满，","t":152.92},{"en":"and the red and gold or her superstructure ablaze with colour,","zh":"红金相间的上层建筑色彩斑斓，","t":159.53},{"en":"she presented a more majestic spectacle than Stockholmers had ever seen before.","zh":"她展现出斯德哥尔摩人前所未见的雄伟景象。","t":164.92},{"en":"All gun-ports were open and the muzzles peeped wickedly from them.","zh":"所有的炮门都敞开着，炮口不怀好意地探出。","t":171.5},{"en":"As the wind freshened there came a sudden squall and the ship made a strange movement, listing to port.","zh":"随着风势渐强，一阵突如其来的飑风袭来，船身做了一个奇怪的动作，向左舷倾斜。","t":178.11},{"en":"The Ordnance officer ordered all the port cannon to be heaved to starboard","zh":"炮兵军官命令将所有左舷的大炮都移到右舷，","t":186.16},{"en":"to counteract the list but the steepening angle of the decks increased.","zh":"以抵消倾斜，但甲板的倾斜角度反而加剧了。","t":191.68},{"en":"Then the sound of rumbling thunder reached the watchers on the shore,","zh":"接着，隆隆的雷鸣声传到了岸上的观望者耳中，","t":198.28},{"en":"as cargo, ballast, ammunition and 400 people went sliding and crashing down to the port side of the steeply listing ship.","zh":"原来是货物、压舱物、弹药和400名船员滑向急剧倾斜的船只的左舷，发出撞击声。","t":202.91},{"en":"The lower gun-ports were now below water and the inrush sealed the ship's fate.","zh":"下层炮门现在已在水面之下，涌入的海水注定了这艘船的命运。","t":213.99},{"en":"In that first glorious hour, the mighty Vasa, which was intended to rule the Baltic,","zh":"在那光荣的第一个小时，原本注定要称霸波罗的海的“瓦萨”号，","t":221.03},{"en":"sank with all flags flying--in the harbour of her birth.","zh":"带着所有飘扬的旗帜，沉入了她诞生时的港口。","t":228.67}],"vocab":[{"word":"maiden","phonetic":"/ˈmeɪdn/","meanings":[{"pos":"adjective","meaning":"首次的；初次的","usage":"用于描述交通工具、旅程等第一次执行的任务"},{"pos":"noun","meaning":"少女；处女","usage":"指未婚的年轻女性"}]},{"word":"imperial","phonetic":"/ɪmˈpɪəriəl/","meanings":[{"pos":"adjective","meaning":"帝国的；皇帝的","usage":"用于描述和帝国、君主相关的事物"}]},{"word":"dictate","phonetic":"/dɪkˈteɪt/","meanings":[{"pos":"verb","meaning":"指定；决定；命令","usage":"指权威人士强制规定某事的内容或规则"},{"pos":"verb","meaning":"口述；听写","usage":"指口头说出内容让他人记录"}]},{"word":"armament","phonetic":"/ˈɑːməmənt/","meanings":[{"pos":"noun","meaning":"武器装备；军备","usage":"指军队或军用交通工具配备的武器总称"}]},{"word":"ferment","phonetic":"/ˈfɜːment/","meanings":[{"pos":"noun","meaning":"骚动；动荡；激动","usage":"用于描述人群或社会气氛的兴奋、不安状态"},{"pos":"verb","meaning":"发酵；挑起动乱","usage":"指物质发酵的过程，或比喻煽动情绪"}]},{"word":"ornament","phonetic":"/ˈɔːnəmənt/","meanings":[{"pos":"verb","meaning":"装饰；点缀","usage":"指添加装饰性元素让事物更美观"},{"pos":"noun","meaning":"装饰品；饰物","usage":"指用于装饰的物品"}]},{"word":"riot","phonetic":"/ˈraɪət/","meanings":[{"pos":"noun","meaning":"丰富多彩的展示； riot of sth表示大量各种各样的事物","usage":"用于比喻颜色、元素等丰富杂乱的状态"},{"pos":"noun","meaning":"暴乱；骚乱","usage":"指人群的暴力骚乱活动"}]},{"word":"zoomorphic","phonetic":"/ˌzəʊəˈmɔːfɪk/","meanings":[{"pos":"adjective","meaning":"兽形的；动物形的","usage":"用于描述艺术、装饰中模仿动物形态的设计"}]},{"word":"ablaze","phonetic":"/əˈbleɪz/","meanings":[{"pos":"adjective","meaning":"色彩鲜艳的；闪耀的","usage":"用于描述颜色明亮夺目、发光的状态"},{"pos":"adjective","meaning":"着火的；燃烧的","usage":"指物体正在燃烧的状态"}]},{"word":"portray","phonetic":"/pɔːˈtreɪ/","meanings":[{"pos":"verb","meaning":"描绘；刻画","usage":"指用艺术、文字等方式呈现人或事物的特征"}]},{"word":"superstitious","phonetic":"/ˌsuːpəˈstɪʃəs/","meanings":[{"pos":"adjective","meaning":"迷信的","usage":"用于描述相信迷信、运气等超自然力量的人或行为"}]},{"word":"salute","phonetic":"/səˈluːt/","meanings":[{"pos":"noun","meaning":"鸣礼炮；敬礼；致敬","usage":"指表示敬意的礼仪动作或鸣炮行为"},{"pos":"verb","meaning":"敬礼；致敬","usage":"指做出致敬的动作"}]},{"word":"majestic","phonetic":"/məˈdʒestɪk/","meanings":[{"pos":"adjective","meaning":"雄伟的；壮丽的；威严的","usage":"用于描述气势宏大、给人庄重感的事物"}]},{"word":"squall","phonetic":"/skwɔːl/","meanings":[{"pos":"noun","meaning":"突起的狂风；飑","usage":"指海上或陆地上突然出现的强风，常伴随阵雨"}]},{"word":"list","phonetic":"/lɪst/","meanings":[{"pos":"verb","meaning":"（船）倾斜","usage":"专门描述船只向一侧倾斜的状态"},{"pos":"noun","meaning":"列表；清单","usage":"指记录一系列事物的清单"}]}],"phrases":[{"phrase":"at the height of","usage":"表示处于某个活动、状态或事业的顶峰、最鼎盛时期","examples":[{"en":"He was at the height of his career when he won the Nobel Prize.","zh":"获得诺贝尔奖时，他正处于事业的顶峰。"},{"en":"At the height of the summer, the temperature can reach 40℃ here.","zh":"在盛夏时节，这里的温度可达40摄氏度。"}]},{"phrase":"be intended to","usage":"表示某事物被设计、计划用于某个特定目的，主语通常是物","examples":[{"en":"This program is intended to help people with low income.","zh":"这个项目旨在帮助低收入人群。"},{"en":"The book is intended for children aged 5 to 10.","zh":"这本书是为5到10岁的儿童编写的。"}]},{"phrase":"play a leading role in","usage":"表示在某个领域、活动中起主导作用、担任重要角色","examples":[{"en":"She played a leading role in organizing the event.","zh":"她在组织这次活动中起到了主导作用。"},{"en":"China plays a leading role in global climate change cooperation.","zh":"中国在全球气候变化合作中发挥着重要的引领作用。"}]},{"phrase":"a riot of","usage":"用于描述大量丰富多彩、种类繁多的事物，尤指颜色","examples":[{"en":"The garden is a riot of colour in spring.","zh":"春天的花园里色彩缤纷，万紫千红。"},{"en":"The parade was a riot of sound and movement as dancers and musicians passed by.","zh":"当舞者和音乐家经过时，游行队伍充满了喧闹的声响和活跃的身影。"}]},{"phrase":"stir one's imagination","usage":"表示激发、唤起某人的想象力","examples":[{"en":"Science fiction stories always stir children's imagination about space.","zh":"科幻故事总能激发孩子们对太空的想象力。"},{"en":"The mysterious ancient ruins stirred the archaeologists' imagination.","zh":"这些神秘的古代遗迹唤起了考古学家的想象。"}]},{"phrase":"in reply to","usage":"表示作为对……的回应、答复","examples":[{"en":"He nodded in reply to my question.","zh":"他点了点头，作为对我问题的回应。"},{"en":"The company issued a statement in reply to the media's accusations.","zh":"公司发布了一则声明，回应媒体的指控。"}]},{"phrase":"seal one's fate","usage":"表示决定了某人或某事物的最终结局（通常是不幸的），无法再改变","examples":[{"en":"His careless mistake in the final game sealed the team's fate.","zh":"他在决赛中那个粗心的失误注定了球队的败局。"},{"en":"When the company lost its biggest client, its fate was sealed.","zh":"当公司失去了最大的客户时，它的命运就已经注定了。"}]}],"grammar":[{"title":"非限制性定语从句","definition":"对主句中某个名词或整个主句的内容进行补充说明，去掉后不影响主句的完整意思，通常和主句之间用逗号隔开","structure":"主句, which/who/whose/where/when + 从句","usage":"用于补充额外信息，而非限定修饰的对象，翻译时通常拆分为独立的句子","examples":[{"en":"In that first glorious hour, the mighty Vasa, which was intended to rule the Baltic, sank with all flags flying.","zh":"在那荣耀的第一个小时里，本打算统治波罗的海的强大的“瓦萨”号，却在自己的诞生港内，全旗飘扬地沉入了海底。"},{"en":"The old building, which was built in 1890, will be turned into a museum next year.","zh":"这栋老建筑建于1890年，明年将被改造成一座博物馆。"}]},{"title":"with的复合结构作伴随状语","definition":"用\"with + 宾语 + 宾语补足语\"的结构，描述主句动作发生时的伴随状态、背景或原因","structure":"with + 名词/代词 + 现在分词/过去分词/形容词/副词/介词短语/不定式","usage":"用于丰富句子的场景描述，让多个动作或状态同时呈现，避免堆砌多个简单句","examples":[{"en":"As she emerged from her drifting cloud of gun smoke with the water churned to foam beneath her bow, her flags flying, pennants waving, sails filling in the breeze, and the red and gold of her superstructure ablaze with colour, she presented a more majestic spectacle than Stockholmers had ever seen before.","zh":"当它从弥漫的炮烟中驶出时，船首下的海水翻滚着泡沫，旗帜飘扬，三角旗舞动，风帆在微风中胀满，上层建筑的红金两色光彩夺目，它呈现出斯德哥尔摩人前所未见的雄伟景象。"},{"en":"She walked into the classroom with a book in her hand and a smile on her face.","zh":"她走进教室，手里拿着一本书，脸上带着微笑。"}]},{"title":"时间状语从句的省略","definition":"当时间状语从句的主语和主句主语一致，且从句包含be动词时，可以省略从句的主语和be动词，简化句子结构","structure":"when/while/as/once/until/if等 + 现在分词/过去分词/形容词/介词短语","usage":"用于避免重复主语，让句子更简洁紧凑","examples":[{"en":"As prepared for her maiden voyage on August 10, 1628, Stockholm was in a ferment.","zh":"1628年8月10日，当它正准备首次航行时，斯德哥尔摩全城沸腾。"},{"en":"When asked about his plan, he said he would go abroad for further study.","zh":"当被问及他的计划时，他说他会出国深造。"}]}],"patterns":[{"pattern":"The story of ... that ... must be one of the strangest tales of ...","explanation":"","original":{"en":"the story of a galleon that sank at the start of her maiden voyage in 1628 must be one of the strangest tales of the sea.","zh":"1628年一艘大帆船在处女航刚开始就沉没了，这个故事堪称航海史上最离奇的传说之一。"},"examples":[{"en":"The story of a young painter that died poor but became world-famous after his death must be one of the strangest tales of the art world.","zh":"一位年轻画家生前穷困潦倒，去世后却举世闻名，这个故事堪称艺术界最离奇的传说之一。"},{"en":"The story of an old cat that traveled 500 kilometers to return to its owner's home must be one of the strangest tales of animal behavior.","zh":"一只老猫跋涉500公里回到主人家，这个故事堪称动物行为中最离奇的传说之一。"}]},{"pattern":"..., which was intended to ..., ...","explanation":"","original":{"en":"the mighty Vasa, which was intended to rule the Baltic, sank with all flags flying--in the harbour of her birth.","zh":"本打算统治波罗的海的强大的“瓦萨”号，却在自己的诞生港内，全旗飘扬地沉入了海底。"},"examples":[{"en":"The grand project, which was intended to solve the city's traffic problem, was stopped due to lack of funds.","zh":"本打算解决城市交通问题的宏大项目，却因为资金不足被叫停了。"},{"en":"The new policy, which was intended to encourage small businesses, has received widespread support.","zh":"本打算鼓励小微企业的新政策，得到了广泛的支持。"}]},{"pattern":"As ... there came a sudden ...","explanation":"","original":{"en":"As the wind freshened there came a sudden squall and the ship made a strange movement, listing to port.","zh":"当风力增强时，突然刮来一阵狂风，船奇怪地晃动了一下，向左舷倾斜。"},"examples":[{"en":"As the meeting was going smoothly there came a sudden objection from a young participant.","zh":"当会议进展顺利时，突然有一位年轻的参会者提出了反对意见。"},{"en":"As we were enjoying the picnic there came a sudden heavy rain and we had to rush to the car.","zh":"我们正享受野餐的时候，突然下起了大雨，我们不得不冲向车里。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“首次的；初次的” 对应的单词是？","hint":"adjective · /ˈmeɪdn/","options":["positive","maiden","secrecy","vulgar"],"answer":1,"explain":"maiden · /ˈmeɪdn/ · adjective · 首次的；初次的。用于描述交通工具、旅程等第一次执行的任务","source":{"kind":"vocab","word":"maiden"},"id":"b4-u27-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：迷信的","hint":"/ˌsuːpəˈstɪʃəs/ · adjective","answer":"superstitious","placeholder":"输入英文单词","explain":"superstitious · /ˌsuːpəˈstɪʃəs/ · adjective · 迷信的。用于描述相信迷信、运气等超自然力量的人或行为","source":{"kind":"vocab","word":"superstitious"},"id":"b4-u27-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He nodded _____ my question.","hint":"他点了点头，作为对我问题的回应。","answer":"in reply to","placeholder":"输入缺失的短语","explain":"in reply to：表示作为对……的回应、答复（他点了点头，作为对我问题的回应。）","source":{"kind":"phrase","phrase":"in reply to"},"id":"b4-u27-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：then at the height of his _____ success in the 'Thirty Years' War,","hint":"当时正处于“三十年战争”军事胜利的巅峰时期，","answer":"military","placeholder":"输入缺失的单词","explain":"then at the height of his military success in the 'Thirty Years' War, — 当时正处于“三十年战争”军事胜利的巅峰时期，","source":{"kind":"sentence","en":"then at the height of his military success in the 'Thirty Years' War,"},"id":"b4-u27-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对主句中某个名词或整个主句的内容进行补充说明，去掉后不影响主句的完整意思，通常和主句之间用逗号隔开” 描述的是哪个语法点？","hint":"主句, which/who/whose/where/when + 从句","options":["定语从句 (Attributive Clause)","非限制性定语从句","插入语","however引导的让步状语从句"],"answer":1,"explain":"非限制性定语从句：主句, which/who/whose/where/when + 从句：用于补充额外信息，而非限定修饰的对象，翻译时通常拆分为独立的句子","source":{"kind":"grammar","title":"非限制性定语从句"},"id":"b4-u27-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nand the red and gold or her superstructure ablaze with colour,","hint":"","options":["诡计、无政府状态和即将到来的毁灭是我们日常生活一部分的世界里，","他们不是焦虑的社会攀爬者，他们对物质也没有任何执着。","医疗服务机构每年的药品费用正在攀升至天文数字，","红金相间的上层建筑色彩斑斓，"],"answer":3,"explain":"and the red and gold or her superstructure ablaze with colour, — 红金相间的上层建筑色彩斑斓，","source":{"kind":"sentence","en":"and the red and gold or her superstructure ablaze with colour,"},"id":"b4-u27-q06"}]},{"id":"b4-u28","book":4,"unit":28,"key":"28","lessonFrom":28,"lessonTo":28,"title":"Patients and Doctors","titleZh":"病人与医生","question":"What are patients looking for when they visit the doctor?","sentences":[{"en":"This is a sceptical age,","zh":"这是一个怀疑的时代，","t":14.79},{"en":"but although our faith in many of the things in which our forefathers fervently believed has weakened,","zh":"尽管我们对先辈们曾笃信的许多事物的信念已动摇，","t":16.94},{"en":"our confidence in the curative properties of the bottle of medicine remains the same as theirs.","zh":"但我们对瓶装药物疗效的信心却和他们一样坚定。","t":23.7},{"en":"This modern faith in medicines is proved by the fact","zh":"对药物的这种现代信念由以下事实得到证明：","t":30.52},{"en":"that the annual drug bill of the Health Services is mounting to astronomical figures.","zh":"医疗服务机构每年的药品费用正在攀升至天文数字，","t":34.23},{"en":"and shows no signs at present of ceasing to rise.","zh":"而且目前没有停止增长的迹象。","t":40.51},{"en":"The majority of the patients attending the medical out-patients departments of our hospitals feel that","zh":"在我们医院门诊部就诊的大多数病人觉得，","t":45.25},{"en":"they have not received adequate treatment unless they are able to carry home with them","zh":"除非他们能带回家一些","t":51.22},{"en":"some tangible remedy in the shape of a bottle of medicine,","zh":"具体可见的治疗方法，比如一瓶药水、","t":56.22},{"en":"a box of pills, or a small jar of ointment,","zh":"一盒药片或一小罐药膏，","t":60.29},{"en":"and the doctor in charge of the department is only too ready to provide them with these requirements.","zh":"否则他们就没有得到充分的治疗。而负责该部门的医生也非常乐意满足他们的这些要求。","t":64.21},{"en":"There is no quicker method of disposing of patients than by giving them what they are asking for,","zh":"没有比给病人他们所要求的东西更能迅速打发他们的方法了，","t":70.98},{"en":"and since most medical men in the Health Services are overworked","zh":"而且由于医疗服务机构的大多数医务人员工作过度，","t":77.3},{"en":"and have little time for offering time-consuming and little-appreciated advice on such subjects as diet,","zh":"很少有时间提供耗时且不被重视的建议，比如关于饮食、","t":81.58},{"en":"right living, and the need for abandoning bad habits etc.,","zh":"正确生活方式以及改掉坏习惯等，","t":89.1},{"en":"the bottle, the box, and the jar are almost always granted them.","zh":"所以药水、药片和药膏几乎总是会给他们。","t":93.81},{"en":"Nor is it only the ignorant and ill-educated person who has such faith in the bottle of medicine.","zh":"并非只有无知和受教育程度不高的人才对瓶装药水有如此大的信心。","t":99.03},{"en":"It is recounted of Thomas Carlyle that when he heard of the illness of his friend, Henry Taylor,","zh":"据记载，托马斯·卡莱尔听说他的朋友亨利·泰勒生病时，","t":105.79},{"en":"he went off immediately to visit him,","zh":"立刻前去探望他，","t":112.98},{"en":"carrying with him in his pocket what remained a bottle of medicine formerly prescribed for an indisposition of Mrs. Carlyle's.","zh":"口袋里带着一瓶他妻子卡莱尔夫人以前因病服用后剩下的药水。","t":115.99},{"en":"Carlyle was entirely ignorant of what the bottle in his pocket contained,","zh":"卡莱尔完全不知道他口袋里的药瓶装着什么，","t":126.16},{"en":"of the nature of the illness from which his friend was suffering,","zh":"也不知道他的朋友患的是什么病，","t":131.22},{"en":"and of what had previously been wrong with his wife,","zh":"更不知道他妻子以前得了什么病，","t":135.02},{"en":"but a medicine that had worked so well in one form of illness would surely be of equal benefit in another,","zh":"但他认为一种疾病疗效显著的药，对另一种病也肯定同样有效，","t":138.7},{"en":"and comforted by the thought of the help he was bringing to his friend,","zh":"想到他能给朋友带来帮助，便感到欣慰，","t":145.88},{"en":"he hastened to Henry Taylor's house.","zh":"于是他匆匆赶往亨利·泰勒家。","t":150.16},{"en":"History does not relate whether his friend accepted his medical help, but in all probability he did.","zh":"历史上没有记载他的朋友是否接受了他的医疗帮助，但很可能他接受了。","t":153.66},{"en":"The great advantage of taking medicine is that it makes no demands on the taker","zh":"服药的最大优点在于它对服药者没有任何要求，","t":160.74},{"en":"beyond that of putting up for a moment with a disgusting taste,","zh":"除了忍受一小会儿难闻的味道之外，","t":165.65},{"en":"and that is what all patients demand of their doctors--to be cured at no inconvenience to themselves.","zh":"而这正是所有病人对医生提出的要求——在自己不感到任何不便的情况下被治愈。","t":169.86}],"vocab":[{"word":"sceptical","phonetic":"/ˈskeptɪkl/","meanings":[{"pos":"adjective","meaning":"怀疑的，持怀疑态度的","usage":"通常用来描述人对某件事不轻易相信，常与介词of/about搭配"}]},{"word":"fervently","phonetic":"/ˈfɜːvəntli/","meanings":[{"pos":"adverb","meaning":"热诚地，热烈地，笃信地","usage":"用来修饰表示相信、希望、支持等含义的动词"}]},{"word":"curative","phonetic":"/ˈkjʊərətɪv/","meanings":[{"pos":"adjective","meaning":"有疗效的，能治病的","usage":"多用来修饰药物、治疗方法等名词"}]},{"word":"property","phonetic":"/ˈprɒpəti/","meanings":[{"pos":"noun","meaning":"特性，属性；财产","usage":"表示“特性”时常用复数形式，指物质、事物的固有属性"}]},{"word":"astronomical","phonetic":"/ˌæstrəˈnɒmɪkl/","meanings":[{"pos":"adjective","meaning":"天文数字的，极其巨大的；天文学的","usage":"常用来修饰数量、金额等，表示数额大到惊人"}]},{"word":"tangible","phonetic":"/ˈtændʒəbl/","meanings":[{"pos":"adjective","meaning":"有形的，实实在在的，可触摸的","usage":"用来描述能被实际感知到的事物，与抽象概念相对"}]},{"word":"remedy","phonetic":"/ˈremədi/","meanings":[{"pos":"noun","meaning":"治疗方法，药物；补救方法","usage":"表示“治疗药物”时可与for搭配，指针对某种疾病的疗法"}]},{"word":"ointment","phonetic":"/ˈɔɪntmənt/","meanings":[{"pos":"noun","meaning":"药膏，软膏","usage":"指外用的膏状药物，常与a jar of搭配使用"}]},{"word":"dispose of","phonetic":"/dɪˈspəʊz ɒv/","meanings":[{"pos":"phrasal verb","meaning":"处理，应付；扔掉，丢弃","usage":"此处表示快速应付、打发走某人，也可表示处理掉不需要的物品"}]},{"word":"time-consuming","phonetic":"/ˈtaɪm kənsjuːmɪŋ/","meanings":[{"pos":"adjective","meaning":"耗费时间的，耗时的","usage":"用来描述需要花费大量时间才能完成的事务"}]},{"word":"recount","phonetic":"/rɪˈkaʊnt/","meanings":[{"pos":"verb","meaning":"讲述，叙述（过去的事）","usage":"正式用词，指详细讲述已经发生的事情，常用被动结构it is recounted that..."}]},{"word":"prescribe","phonetic":"/prɪˈskraɪb/","meanings":[{"pos":"verb","meaning":"给……开（药），规定","usage":"作为医疗相关用词时，主语通常为医生，宾语为药物或治疗方案"}]},{"word":"indisposition","phonetic":"/ˌɪndɪspəˈzɪʃn/","meanings":[{"pos":"noun","meaning":"微恙，小病","usage":"正式用词，指不严重的轻微疾病，是illness的委婉说法"}]},{"word":"hasten","phonetic":"/ˈheɪsn/","meanings":[{"pos":"verb","meaning":"赶紧，匆忙；促进","usage":"表示急忙去某地或急忙做某事，比hurry更正式"}]},{"word":"disgusting","phonetic":"/dɪsˈɡʌstɪŋ/","meanings":[{"pos":"adjective","meaning":"令人厌恶的，令人作呕的","usage":"用来形容事物的味道、外观等让人感到恶心"}]}],"phrases":[{"phrase":"in the shape of","usage":"表示“以……的形式，呈……的形状”，用来描述事物的呈现形态","examples":[{"en":"The company received help in the shape of a government loan.","zh":"这家公司得到了政府贷款形式的帮助。"},{"en":"He made a cake in the shape of a heart for his girlfriend's birthday.","zh":"他为女朋友的生日做了一个心形的蛋糕。"}]},{"phrase":"only too ready to do sth","usage":"表示“非常乐意做某事，巴不得做某事”，带有强调愿意的语气","examples":[{"en":"He is only too ready to help others when they are in trouble.","zh":"别人有困难时他非常乐意帮忙。"},{"en":"The shop assistant was only too ready to show us the latest products.","zh":"店员非常乐意向我们展示最新的产品。"}]},{"phrase":"dispose of","usage":"此处表示“应付，打发”，也可表示“处理、丢弃不需要的物品”","examples":[{"en":"The manager quickly disposed of the customer's complaint and calmed him down.","zh":"经理迅速处理了顾客的投诉，让他冷静了下来。"},{"en":"We need to dispose of all these old newspapers before moving to the new office.","zh":"搬去新办公室之前，我们需要把这些旧报纸都处理掉。"}]},{"phrase":"put up with","usage":"表示“忍受，容忍”，是常用的动词短语，宾语为令人不快的人或事","examples":[{"en":"I can't put up with his constant complaining any more.","zh":"我再也受不了他没完没了的抱怨了。"},{"en":"Many residents have to put up with the noise from the construction site nearby.","zh":"很多居民不得不忍受附近建筑工地的噪音。"}]},{"phrase":"in all probability","usage":"表示“极有可能，十有八九”，是表示可能性的正式表达","examples":[{"en":"In all probability, the meeting will be cancelled because of the bad weather.","zh":"十有八九这次会议会因为恶劣天气取消。"},{"en":"If you don't prepare for the exam, in all probability you will fail it.","zh":"如果你不为考试做准备，你很可能会不及格。"}]},{"phrase":"be of equal benefit","usage":"表示“有同等好处，同样有益”，属于“be of + 抽象名词”的结构，相当于be equally beneficial","examples":[{"en":"This training course is of equal benefit to both new and experienced employees.","zh":"这个培训课程对新员工和老员工都同样有益。"},{"en":"Regular exercise is of equal benefit to people of all age groups.","zh":"规律锻炼对所有年龄段的人都有同样的好处。"}]},{"phrase":"out-patients department","usage":"医疗场景常用短语，表示“门诊部”，对应住院部的in-patients department","examples":[{"en":"The out-patients department of this hospital is open from 8 am to 5 pm every day.","zh":"这家医院的门诊部每天早上8点到下午5点开放。"},{"en":"You need to register at the out-patients department first before seeing a doctor.","zh":"看医生之前你需要先在门诊部挂号。"}]},{"phrase":"make no demands on sb","usage":"表示“对某人没有要求，不给某人添麻烦”，用来描述某件事不需要对方付出什么","examples":[{"en":"This kind of houseplant makes no demands on the owner; it only needs occasional watering.","zh":"这种室内盆栽不需要主人费什么心思，只需要偶尔浇浇水就行。"},{"en":"The new software makes very few demands on the computer's hardware.","zh":"这个新软件对电脑硬件的要求非常低。"}]}],"grammar":[{"title":"倒装语序（Nor引导的否定倒装）","definition":"当否定词nor位于句首时，句子需要使用部分倒装结构，表示前面的否定情况也适用于后者，意为“……也不”","structure":"Nor + 助动词/系动词/情态动词 + 主语 + 谓语剩余部分","usage":"承接前面的否定陈述，补充说明另一个主体也同样符合该否定情况，保持前后时态一致","examples":[{"en":"Nor is it only the ignorant and ill-educated person who has such faith in the bottle of medicine.","zh":"并不只有无知和没受过良好教育的人才如此信任瓶装药物。"},{"en":"I don't like horror movies, nor does my sister.","zh":"我不喜欢恐怖电影，我妹妹也不喜欢。"},{"en":"He can't speak French, nor can he write it.","zh":"他不会说法语，也不会写法语。"}]},{"title":"并列的宾语从句","definition":"当及物动词后面接多个that引导的宾语从句时，第一个从句的that可以省略，后面的从句that通常不可省略，多个从句之间用and连接","structure":"主语 + 谓语 + (that) 从句1 + and that 从句2 + and that 从句3","usage":"用来陈述与同一个谓语动词相关的多个并列内容，使句子逻辑清晰，避免重复主语和谓语","examples":[{"en":"Carlyle was entirely ignorant of what the bottle in his pocket contained, of the nature of the illness from which his friend was suffering, and of what had previously been wrong with his wife.","zh":"卡莱尔完全不知道自己口袋里的瓶子装的是什么，不知道他朋友患的病是什么性质，也不知道他妻子之前得的是什么病。"},{"en":"The teacher told us that we should hand in the homework before Friday, and that we needed to prepare for the next week's test.","zh":"老师告诉我们应该在周五之前交作业，还告诉我们需要为下周的考试做准备。"}]},{"title":"同位语从句","definition":"跟在抽象名词（如fact, news, idea, belief等）后面，用来解释说明该名词的具体内容的从句，通常由that引导，that在从句中不充当成分","structure":"抽象名词 + that + 完整的陈述性句子","usage":"用来对前面的抽象名词进行内容上的补充说明，让读者明确该名词的具体所指","examples":[{"en":"This modern faith in medicines is proved by the fact that the annual drug bill of the Health Services is mounting to astronomical figures.","zh":"医疗服务机构每年的药品账单正攀升至天文数字，这一事实证明了现代人对药物的这种信任。"},{"en":"We were all excited at the news that our team had won the championship.","zh":"听到我们队赢得了冠军的消息，我们都很兴奋。"}]}],"patterns":[{"pattern":"This is a ... age, but although our faith in ... has weakened, our confidence in ... remains the same as theirs.","explanation":"","original":{"en":"This is a sceptical age, but although our faith in many of the things in which our forefathers fervently believed has weakened, our confidence in the curative properties of the bottle of medicine remains the same as theirs.","zh":"这是一个怀疑一切的时代，但是尽管我们对祖先们笃信的很多事物的信念已经减弱，我们对瓶装药物疗效的信心仍和他们一模一样。"},"examples":[{"en":"This is a digital age, but although our faith in traditional face-to-face communication has weakened, our confidence in the importance of real emotional connection remains the same as previous generations'.","zh":"这是一个数字时代，但是尽管我们对传统面对面交流的信念已经减弱，我们对真实情感连接的重要性的信心仍和前几代人一模一样。"},{"en":"This is a fast-paced age, but although our faith in slow, hand-made products has weakened, our confidence in the value of quality craftsmanship remains the same as our ancestors'.","zh":"这是一个快节奏的时代，但是尽管我们对缓慢的手工制品的信念已经减弱，我们对优质工艺价值的信心仍和我们的祖先一模一样。"}]},{"pattern":"The majority of ... feel that they have not received adequate ... unless they are able to ...","explanation":"","original":{"en":"The majority of the patients attending the medical out-patients departments of our hospitals feel that they have not received adequate treatment unless they are able to carry home with them some tangible remedy in the shape of a bottle of medicine, a box of pills, or a small jar of ointment.","zh":"大多数去医院门诊部看病的病人觉得，自己没有得到充分的治疗，除非他们能带回去一些实实在在的治疗药物，不管是一瓶药水、一盒药片还是一小罐药膏。"},"examples":[{"en":"The majority of customers shopping in physical stores feel that they have not received adequate service unless they are able to get a personal recommendation from the sales assistant.","zh":"大多数在实体店购物的顾客觉得，自己没有得到充分的服务，除非他们能得到销售助理的个人推荐。"},{"en":"The majority of students taking online courses feel that they have not received adequate education unless they are able to interact with the teacher and classmates in real time.","zh":"大多数上在线课程的学生觉得，自己没有得到充分的教育，除非他们能和老师以及同学进行实时互动。"}]},{"pattern":"It is recounted of ... that when he heard of ..., he went off immediately to ..., carrying with him ...","explanation":"","original":{"en":"It is recounted of Thomas Carlyle that when he heard of the illness of his friend, Henry Taylor, he went off immediately to visit him, carrying with him in his pocket what remained a bottle of medicine formerly prescribed for an indisposition of Mrs. Carlyle's.","zh":"据说托马斯·卡莱尔有这么一件事，当他听说朋友亨利·泰勒生病的消息后，他立刻动身去探望，口袋里还装着剩下的半瓶之前卡莱尔夫人得小病时开的药。"},"examples":[{"en":"It is recounted of the old writer that when he heard of the flood in his hometown, he went off immediately to donate money, carrying with him all the savings he had stored for years.","zh":"据说这位老作家有这么一件事，当他听说家乡遭遇洪水的消息后，他立刻动身去捐款，随身带着自己存了多年的全部积蓄。"},{"en":"It is recounted of the famous chef that when he heard of his apprentice's failure in the cooking competition, he went off immediately to comfort him, carrying with him the award he had won in the same competition many years ago.","zh":"据说这位名厨有这么一件事，当他听说自己的徒弟在烹饪比赛中失利的消息后，他立刻动身去安慰他，随身带着自己多年前在同一个比赛中赢得的奖杯。"}]},{"pattern":"The great advantage of ... is that it makes no demands on ... beyond that of ..., and that is what ... demand of ...","explanation":"","original":{"en":"The great advantage of taking medicine is that it makes no demands on the taker beyond that of putting up for a moment with a disgusting taste, and that is what all patients demand of their doctors--to be cured at no inconvenience to themselves.","zh":"服药的一大好处是，它对服药者没有任何要求，只需要暂时忍受一下难吃的味道，这就是所有病人对医生的要求——把病治好，自己却不用承担任何不便。"},"examples":[{"en":"The great advantage of using a smart speaker is that it makes no demands on the user beyond that of speaking out their needs clearly, and that is what most busy office workers demand of smart devices.","zh":"使用智能音箱的一大好处是，它对使用者没有任何要求，只需要清晰说出自己的需求，这就是大多数忙碌的上班族对智能设备的要求。"},{"en":"The great advantage of this fitness method is that it makes no demands on the practitioner beyond that of setting aside 15 minutes every day, and that is what people with busy schedules demand of a workout program.","zh":"这种健身方法的一大好处是，它对练习者没有任何要求，只需要每天抽出15分钟，这就是日程繁忙的人对健身计划的要求。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“处理，应付；扔掉，丢弃” 对应的单词是？","hint":"phrasal verb · /dɪˈspəʊz ɒv/","options":["rim","dispose of","allege","sounding"],"answer":1,"explain":"dispose of · /dɪˈspəʊz ɒv/ · phrasal verb · 处理，应付；扔掉，丢弃。此处表示快速应付、打发走某人，也可表示处理掉不需要的物品","source":{"kind":"vocab","word":"dispose of"},"id":"b4-u28-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：药膏，软膏","hint":"/ˈɔɪntmənt/ · noun","answer":"ointment","placeholder":"输入英文单词","explain":"ointment · /ˈɔɪntmənt/ · noun · 药膏，软膏。指外用的膏状药物，常与a jar of搭配使用","source":{"kind":"vocab","word":"ointment"},"id":"b4-u28-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I can't _____ his constant complaining any more.","hint":"我再也受不了他没完没了的抱怨了。","answer":"put up with","placeholder":"输入缺失的短语","explain":"put up with：表示“忍受，容忍”，是常用的动词短语，宾语为令人不快的人或事（我再也受不了他没完没了的抱怨了。）","source":{"kind":"phrase","phrase":"put up with"},"id":"b4-u28-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：beyond that of _____ up for a moment with a disgusting taste,","hint":"除了忍受一小会儿难闻的味道之外，","answer":"putting","placeholder":"输入缺失的单词","explain":"beyond that of putting up for a moment with a disgusting taste, — 除了忍受一小会儿难闻的味道之外，","source":{"kind":"sentence","en":"beyond that of putting up for a moment with a disgusting taste,"},"id":"b4-u28-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当及物动词后面接多个that引导的宾语从句时，第一个从句的that可以省略，后面的从句that通常不可省略，多个从句之间用and连接” 描述的是哪个语法点？","hint":"主语 + 谓语 + (that) 从句1 + and that 从句2 + and that 从句3","options":["宾语从句（deduce后接并列宾语从句）","形容词/名词前置的倒装结构","so that引导的结果状语从句","并列的宾语从句"],"answer":3,"explain":"并列的宾语从句：主语 + 谓语 + (that) 从句1 + and that 从句2 + and that 从句3：用来陈述与同一个谓语动词相关的多个并列内容，使句子逻辑清晰，避免重复主语和谓语","source":{"kind":"grammar","title":"并列的宾语从句"},"id":"b4-u28-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nright living, and the need for abandoning bad habits etc.,","hint":"","options":["正确生活方式以及改掉坏习惯等，","相比色盲，更多的人是“形盲”。","图书馆使教育成为可能，而教育反过来又丰富了图书馆：","那么，如果一块曲面玻璃会扭曲自然，两块又会怎样呢？"],"answer":0,"explain":"right living, and the need for abandoning bad habits etc., — 正确生活方式以及改掉坏习惯等，","source":{"kind":"sentence","en":"right living, and the need for abandoning bad habits etc.,"},"id":"b4-u28-q06"}]},{"id":"b4-u29","book":4,"unit":29,"key":"29","lessonFrom":29,"lessonTo":29,"title":"The Hovercraft","titleZh":"气垫船","question":"What is a hovercraft riding on when it is in motion?","sentences":[{"en":"Many strange new means of transport have been developed in our century,","zh":"本世纪人们发明了许多稀奇古怪的交通工具，","t":16.55},{"en":"the strangest of them being perhaps the hovercraft.","zh":"其中最奇特的也许要算是气垫船了。","t":22.29},{"en":"In 1953, a former electronics engineer in his fifties, Christopher Cockerell,","zh":"1953年，一位50多岁、曾任电子工程师的克里斯托弗·科克雷尔，","t":27.29},{"en":"who had turned to boat-building on the Norfolk Broads,","zh":"他已转行在诺福克湖区制造船只，","t":35.44},{"en":"suggested an idea on which he had been working for many years to the British Government and industrial circles.","zh":"他把多年来一直致力于研究的一种设想，呈报给了英国政府和工业界。","t":39.52},{"en":"It was the idea of supporting a craft on a 'pad', or cushion, of low-pressure air, ringed with a curtain of higher pressure air.","zh":"他的设想是：让航行器由一个低压气垫支撑，气垫四周由一道高压空气幕环绕。","t":48.13},{"en":"Ever since, people have had difficulty in deciding whether the craft should be ranged among ships, planes,","zh":"从那时起，人们就很难确定这种航行器究竟是船、是飞机，","t":60.2},{"en":"or land vehicles--for it is something in between a boat and an aircraft.","zh":"还是陆上交通工具——因为它介于船和飞机之间。","t":69.38},{"en":"As a shipbuilder, Cockerell was trying to find a solution to the problem of the wave resistance which wastes a good deal of a surface ship's power and limits its speed.","zh":"作为一名造船工程师，科克雷尔当时正试图解决波浪阻力问题，波浪阻力消耗了水面船只的大部分动力，并限制了它的航速。","t":77.57},{"en":"His answer was to lift the vessel out of the water by making it ride on a cushion of air, no more than one or two feet thick.","zh":"他的答案是让船只骑在厚度不超过一两英尺的气垫上，从而使其脱离水面。","t":91.54},{"en":"This is done by a great number of ring-shaped air jets on the bottom of the craft.","zh":"这是通过航行器底部大量的环形喷气口完成的。","t":102.6},{"en":"It 'flies', therefore, but it cannot fly higher--its action depends on the surface, water or ground, over which it rides.","zh":"因此它“飞行”，但不能飞得更高——它的运行依赖于它所行驶的水面或地面。","t":109.6},{"en":"The first tests on the Solent in 1959 caused a sensation.","zh":"1959年在索伦特海峡进行的首次试验引起了轰动。","t":122.29},{"en":"The hovercraft travelled first over the water, then mounted the beach, climbed up the dunes, and sat down on a road.","zh":"气垫船先是在水面上行驶，然后登上沙滩，爬上沙丘，最后停在一条公路上。","t":128.57},{"en":"Later it crossed the Channel, riding smoothly over the waves, which presented no problem.","zh":"后来它穿越了英吉利海峡，平稳地在海浪上行驶，这没有造成任何问题。","t":139.57},{"en":"Since that time, various types of hovercraft have appeared and taken up regular service.","zh":"从那时起，各种型号的气垫船相继问世，并投入了定期运营。","t":148.89},{"en":"The hovercraft is particularly useful in large areas with poor communications such as Africa or Australia;","zh":"气垫船在非洲或澳大利亚等交通不便的广大地区尤其有用；","t":156.31},{"en":"it can become a 'flying fruit-bowl', carrying bananas from the plantations to the ports;","zh":"它可以变成一个“飞行水果盘”，将香蕉从种植园运到港口；","t":164.82},{"en":"giant hovercraft liners could span the Atlantic;","zh":"巨型气垫船班轮可以横跨大西洋；","t":171.89},{"en":"and the railway of the future may well be the 'hovertrain',","zh":"而未来的铁路很可能就是“气垫列车”，","t":175.67},{"en":"riding on its air cushion over a single rail, which it never touches, at speeds, up to 300 m.p.h.--the possibilities appear unlimited.","zh":"它们在单轨上方的气垫上行驶，永不接触轨道，时速可达300英里——其可能性似乎无限。","t":179.99}],"vocab":[{"word":"hovercraft","phonetic":"/ˈhɒvəkrɑːft/","meanings":[{"pos":"noun","meaning":"气垫船","usage":"可数名词，单复数同形，指依靠气垫支撑航行的交通工具"}]},{"word":"transport","phonetic":"/ˈtrænspɔːt/","meanings":[{"pos":"noun","meaning":"交通工具；运输系统","usage":"表示“交通工具/运输方式”时为不可数名词"},{"pos":"verb","meaning":"运输，运送","usage":"指通过交通工具运送人或货物"}]},{"word":"former","phonetic":"/ˈfɔːmə(r)/","meanings":[{"pos":"adjective","meaning":"从前的，前任的","usage":"仅用于名词前，修饰名词表示该身份已经不存在"}]},{"word":"electronics","phonetic":"/ɪˌlekˈtrɒnɪks/","meanings":[{"pos":"noun","meaning":"电子学；电子器件","usage":"作为学科时为不可数名词，作“电子器件”时常用复数形式"}]},{"word":"industrial","phonetic":"/ɪnˈdʌstriəl/","meanings":[{"pos":"adjective","meaning":"工业的，产业的","usage":"多用于修饰和工业生产、行业相关的名词，如industrial circles工业界"}]},{"word":"cushion","phonetic":"/ˈkʊʃn/","meanings":[{"pos":"noun","meaning":"垫子；气垫","usage":"文中指支撑气垫船的空气垫，也可指日常的坐垫、靠垫"}]},{"word":"vehicle","phonetic":"/ˈviːəkl/","meanings":[{"pos":"noun","meaning":"交通工具，车辆","usage":"泛指各类陆上、水上、空中的运载工具，为可数名词"}]},{"word":"resistance","phonetic":"/rɪˈzɪstəns/","meanings":[{"pos":"noun","meaning":"阻力；抵抗","usage":"表示物理意义上的阻力时为不可数名词，wave resistance即波浪阻力"}]},{"word":"vessel","phonetic":"/ˈvesl/","meanings":[{"pos":"noun","meaning":"船，舰；容器","usage":"正式用语，指代各类水上船只，也可指盛放物品的容器"}]},{"word":"jet","phonetic":"/dʒet/","meanings":[{"pos":"noun","meaning":"喷嘴；喷气式飞机","usage":"文中air jet指喷气口，也可指代喷气式飞行器"}]},{"word":"sensation","phonetic":"/senˈseɪʃn/","meanings":[{"pos":"noun","meaning":"轰动；感觉","usage":"cause a sensation为固定搭配，指引起轰动"}]},{"word":"mount","phonetic":"/maʊnt/","meanings":[{"pos":"verb","meaning":"登上，爬上；安装","usage":"文中指气垫船驶上海滩，也可表示安装设备、登上山峰等含义"}]},{"word":"dune","phonetic":"/djuːn/","meanings":[{"pos":"noun","meaning":"沙丘","usage":"可数名词，常指海边或沙漠里由沙子堆积形成的丘状地貌"}]},{"word":"plantation","phonetic":"/plɑːnˈteɪʃn/","meanings":[{"pos":"noun","meaning":"种植园，大农场","usage":"多指热带地区大规模种植经济作物的农场，如香蕉种植园、橡胶种植园"}]},{"word":"liner","phonetic":"/ˈlaɪnə(r)/","meanings":[{"pos":"noun","meaning":"大型客轮，邮轮；衬里","usage":"文中hovercraft liner指气垫客轮，也可指衣物等的内衬"}]}],"phrases":[{"phrase":"turn to","usage":"表示“转向，开始从事（新的工作、行业）”，后接名词或动名词","examples":[{"en":"He had turned to boat-building on the Norfolk Broads.","zh":"他转而在诺福克湖区从事造船工作。"},{"en":"After graduating from art school, she turned to fashion design.","zh":"从艺术学校毕业后，她转而从事服装设计工作。"}]},{"phrase":"have difficulty in doing sth","usage":"表示“做某事有困难”，介词in可以省略","examples":[{"en":"Ever since, people have had difficulty in deciding whether the craft should be ranged among ships, planes, or land vehicles.","zh":"从那以后，人们一直难以决定这种交通工具到底应该归为船舶、飞机还是陆上车辆。"},{"en":"Many beginners have difficulty in pronouncing English words correctly.","zh":"很多初学者在正确发英语单词的音方面有困难。"}]},{"phrase":"range among","usage":"表示“把……归入、划分到某一类中”，常用于被动语态","examples":[{"en":"People can not decide whether the craft should be ranged among ships, planes, or land vehicles.","zh":"人们无法决定这种载具是否应该被归为船舶、飞机或者陆上车辆。"},{"en":"This new type of mobile device is usually ranged among portable computers.","zh":"这种新型移动设备通常被归为便携式电脑一类。"}]},{"phrase":"in between","usage":"表示“介于……之间”，可作介词短语或表语，说明两种事物的中间状态","examples":[{"en":"For it is something in between a boat and an aircraft.","zh":"因为它是介于船和飞机之间的一种东西。"},{"en":"The answer is neither yes nor no, it's somewhere in between.","zh":"答案既不是肯定也不是否定，而是介于两者之间。"}]},{"phrase":"a good deal of","usage":"表示“大量的，许多的”，仅用于修饰不可数名词","examples":[{"en":"Wave resistance wastes a good deal of a surface ship's power and limits its speed.","zh":"波浪阻力会浪费水面船舶大量的动力，还会限制它的速度。"},{"en":"The project took a good deal of time and effort before it was completed.","zh":"这个项目花费了大量时间和精力才完成。"}]},{"phrase":"no more than","usage":"表示“仅仅，不超过”，强调数量少或程度低","examples":[{"en":"His answer was to lift the vessel out of the water by making it ride on a cushion of air, no more than one or two feet thick.","zh":"他的解决方案是让船只浮在不超过一两英尺厚的气垫上，从而脱离水面。"},{"en":"The whole process takes no more than 10 minutes for an experienced worker.","zh":"对于有经验的工人来说，整个过程只需要不超过10分钟。"}]},{"phrase":"depend on","usage":"表示“取决于，依靠”，后接名词或名词性结构，说明事物的决定因素","examples":[{"en":"Its action depends on the surface, water or ground, over which it rides.","zh":"它的运行取决于它所行驶的表面，无论是水面还是地面。"},{"en":"The success of the activity depends on the weather and the number of participants.","zh":"这次活动的成功取决于天气和参与人数。"}]},{"phrase":"cause a sensation","usage":"表示“引起轰动，造成轰动效应”，主语通常是新奇的事物或事件","examples":[{"en":"The first tests on the Solent in 1959 caused a sensation.","zh":"1959年在索伦特海峡进行的首次测试引起了轰动。"},{"en":"The young artist's first exhibition in the city caused a sensation.","zh":"这位年轻艺术家在这座城市的首次展览引起了轰动。"}]},{"phrase":"take up","usage":"表示“开始从事，承担（某项工作、服务）”，文中指开始提供常规服务","examples":[{"en":"Since that time, various types of hovercraft have appeared and taken up regular service.","zh":"从那时起，各种类型的气垫船出现了，并开始提供常规服务。"},{"en":"The new bus route will take up official operation next month.","zh":"这条新的公交路线将于下月开始正式运营。"}]},{"phrase":"may well be","usage":"表示“很可能是，完全可以是”，表达带有肯定倾向的推测","examples":[{"en":"The railway of the future may well be the 'hovertrain'.","zh":"未来的铁路很可能就是“气垫火车”。"},{"en":"This discovery may well be the most important breakthrough in the field this year.","zh":"这一发现很可能是该领域今年最重要的突破。"}]}],"grammar":[{"title":"独立主格结构","definition":"由名词/代词 + 非谓语动词/形容词/副词/介词短语构成的结构，在句中作状语，其逻辑主语和主句主语不一致，因此有独立的逻辑主语，多用于书面语","structure":"名词/代词 + 现在分词/过去分词/不定式/形容词/副词/介词短语","usage":"常用于补充说明主句的背景、条件、原因等信息，使句子结构更紧凑，避免重复使用从句","examples":[{"en":"Many strange new means of transport have been developed in our century, the strangest of them being perhaps the hovercraft.","zh":"本世纪已研制出许多新奇的交通工具，其中最奇怪的可能要数气垫船了。"},{"en":"The test finished, we began to analyze the collected data.","zh":"测试结束后，我们开始分析收集到的数据。"}]},{"title":"定语从句的分隔现象","definition":"定语从句通常直接跟在先行词之后，但有时为了平衡句子结构，会把定语从句和先行词用其他成分（如状语、谓语等）隔开，这种情况就是定语从句的分隔现象","structure":"先行词 + 其他插入成分 + 关系代词/关系副词引导的定语从句","usage":"当先行词后面的定语从句过长，而主句谓语部分较短时，常使用分隔结构避免句子头重脚轻，理解时需要先找准先行词","examples":[{"en":"In 1953, a former electronics engineer in his fifties, Christopher Cockerell, who had turned to boat-building on the Norfolk Broads, suggested an idea on which he had been working for many years to the British Government and industrial circles.","zh":"1953年，一位年逾五十、曾从事电子行业的工程师，克里斯托弗·科克雷尔，转而在诺福克湖区从事造船工作，他向英国政府和工业界提出了一项他研究了多年的想法。"},{"en":"A new teacher will come tomorrow who will teach us English literature.","zh":"明天会来一位新老师，教我们英国文学。"}]},{"title":"现在分词作伴随状语","definition":"现在分词和主句主语为主动关系，所表示的动作和主句动作同时发生，补充说明主句动作发生时的伴随情况","structure":"主句 + 逗号 + 现在分词短语","usage":"用于简化复合句，使表达更简洁，现在分词的逻辑主语必须和主句主语一致","examples":[{"en":"It can become a 'flying fruit-bowl', carrying bananas from the plantations to the ports.","zh":"它可以成为一个“飞行果盘”，把香蕉从种植园运到港口。"},{"en":"The children ran out of the classroom, laughing and talking happily.","zh":"孩子们跑出教室，开心地说着笑着。"}]}],"patterns":[{"pattern":"Many + 复数名词 + have been developed in + 某段时间, the + 形容词最高级 + of them being perhaps + 具体事物.","explanation":"","original":{"en":"Many strange new means of transport have been developed in our century, the strangest of them being perhaps the hovercraft.","zh":"本世纪已研制出许多新奇的交通工具，其中最奇怪的可能要数气垫船了。"},"examples":[{"en":"Many new types of digital products have been developed in the past decade, the most popular of them being perhaps the smart watch.","zh":"过去十年里研发出了许多新型数码产品，其中最受欢迎的可能要数智能手表了。"},{"en":"Many new treatment methods have been developed in the medical field in recent years, the most effective of them being perhaps the new targeted therapy.","zh":"近年来医学领域研发出了许多新的治疗方法，其中最有效的可能要数新型靶向疗法了。"}]},{"pattern":"sb was trying to find a solution to the problem of + 问题内容 which + 问题带来的影响.","explanation":"","original":{"en":"As a shipbuilder, Cockerell was trying to find a solution to the problem of the wave resistance which wastes a good deal of a surface ship's power and limits its speed.","zh":"作为一名造船师，科克雷尔当时正试图找到解决波浪阻力问题的方案，这种阻力会浪费水面船舶大量的动力，还会限制它的速度。"},"examples":[{"en":"As an environmental scientist, she is trying to find a solution to the problem of plastic pollution which threatens marine life and pollutes the soil.","zh":"作为一名环境科学家，她正试图找到解决塑料污染问题的方案，这种污染威胁着海洋生物，还会污染土壤。"},{"en":"As a software engineer, the team leader is trying to find a solution to the problem of system lag which affects user experience and reduces work efficiency.","zh":"作为一名软件工程师，团队负责人正试图找到解决系统卡顿问题的方案，这种卡顿会影响用户体验，还会降低工作效率。"}]},{"pattern":"sth is particularly useful in + 适用场景 such as + 举例; it can + 用途1; + 用途2; and + 用途3 -- the possibilities appear unlimited.","explanation":"","original":{"en":"The hovercraft is particularly useful in large areas with poor communications such as Africa or Australia; it can become a 'flying fruit-bowl', carrying bananas from the plantations to the ports; giant hovercraft liners could span the Atlantic; and the railway of the future may well be the 'hovertrain', riding on its air cushion over a single rail, which it never touches, at speeds, up to 300 m.p.h.--the possibilities appear unlimited.","zh":"气垫船在非洲、澳大利亚等交通不发达的大地区特别有用；它可以成为“飞行果盘”，把香蕉从种植园运到港口；大型气垫客轮可以横渡大西洋；未来的铁路很可能是“气垫火车”，依靠气垫在单轨上行驶，不会接触轨道，时速可达300英里——其可能性似乎是无限的。"},"examples":[{"en":"The portable solar charger is particularly useful in outdoor areas without power supply such as mountainous regions or deserts; it can charge mobile phones and cameras for travellers; it can provide electricity for camping lamps at night; and it can even power small medical equipment in emergency rescue -- the possibilities appear unlimited.","zh":"便携式太阳能充电器在山区、沙漠等没有供电的户外地区特别有用；它可以为旅行者的手机和相机充电；夜间可以为露营灯供电；在应急救援中甚至可以为小型医疗设备供电——其可能性似乎是无限的。"},{"en":"Artificial intelligence translation tools are particularly useful in cross-cultural communication scenarios such as international conferences or foreign trade negotiations; they can help people who speak different languages communicate smoothly; they can quickly translate a large number of foreign language documents; and they can provide real-time translation services for tourists travelling abroad -- the possibilities appear unlimited.","zh":"人工智能翻译工具在国际会议、外贸谈判等跨文化交流场景中特别有用；它可以帮助说不同语言的人顺畅沟通；可以快速翻译大量外文文件；还可以为出国旅游的游客提供实时翻译服务——其可能性似乎是无限的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“轰动；感觉” 对应的单词是？","hint":"noun · /senˈseɪʃn/","options":["sensation","steer","maximum","vibration"],"answer":0,"explain":"sensation · /senˈseɪʃn/ · noun · 轰动；感觉。cause a sensation为固定搭配，指引起轰动","source":{"kind":"vocab","word":"sensation"},"id":"b4-u29-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：垫子；气垫","hint":"/ˈkʊʃn/ · noun","answer":"cushion","placeholder":"输入英文单词","explain":"cushion · /ˈkʊʃn/ · noun · 垫子；气垫。文中指支撑气垫船的空气垫，也可指日常的坐垫、靠垫","source":{"kind":"vocab","word":"cushion"},"id":"b4-u29-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The new bus route will _____ official operation next month.","hint":"这条新的公交路线将于下月开始正式运营。","answer":"take up","placeholder":"输入缺失的短语","explain":"take up：表示“开始从事，承担（某项工作、服务）”，文中指开始提供常规服务（这条新的公交路线将于下月开始正式运营。）","source":{"kind":"phrase","phrase":"take up"},"id":"b4-u29-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：riding on its air cushion over a single rail, which it _____ touches, at speeds, up to 300 m.p.h.--the possibilities appear unlimited.","hint":"它们在单轨上方的气垫上行驶，永不接触轨道，时速可达300英里——其可能性似乎无限。","answer":"never","placeholder":"输入缺失的单词","explain":"riding on its air cushion over a single rail, which it never touches, at speeds, up to 300 m.p.h.--the possibilities appear unlimited. — 它们在单轨上方的气垫上行驶，永不接触轨道，时速可达300英里——其可能性似乎无限。","source":{"kind":"sentence","en":"riding on its air cushion over a single rail, which it never touches, at speeds, up to 300 m.p.h.--the possibilities appear unlimited."},"id":"b4-u29-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“定语从句通常直接跟在先行词之后，但有时为了平衡句子结构，会把定语从句和先行词用其他成分（如状语、谓语等）隔开，这种情况就是定语从句的分隔现象” 描述的是哪个语法点？","hint":"先行词 + 其他插入成分 + 关系代词/关系副词引导的定语从句","options":["as 引导的方式状语从句","插入语","定语从句的分隔现象","so that引导的结果状语从句"],"answer":2,"explain":"定语从句的分隔现象：先行词 + 其他插入成分 + 关系代词/关系副词引导的定语从句：当先行词后面的定语从句过长，而主句谓语部分较短时，常使用分隔结构避免句子头重脚轻，理解时需要先找准先行词","source":{"kind":"grammar","title":"定语从句的分隔现象"},"id":"b4-u29-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe hovercraft travelled first over the water, then mounted the beach, climbed up the dunes, and sat down on a road.","hint":"","options":["误差和不确定性倍增，通过一系列湍流特征向上级联，","气垫船先是在水面上行驶，然后登上沙滩，爬上沙丘，最后停在一条公路上。","这个比喻就成了精确而实际的观察。","如果这种“其他东西”选择得当，如果它确实伴随着另一个兴趣领域的启迪，"],"answer":1,"explain":"The hovercraft travelled first over the water, then mounted the beach, climbed up the dunes, and sat down on a road. — 气垫船先是在水面上行驶，然后登上沙滩，爬上沙丘，最后停在一条公路上。","source":{"kind":"sentence","en":"The hovercraft travelled first over the water, then mounted the beach, climbed up the dunes, and sat down on a road."},"id":"b4-u29-q06"}]},{"id":"b4-u30","book":4,"unit":30,"key":"30","lessonFrom":30,"lessonTo":30,"title":"Exploring the Sea-Floor","titleZh":"探索海底","question":"How did people probably imagine the sea-floor before it was investigated?","sentences":[{"en":"Our knowledge of the oceans a hundred years ago was confined to the two-dimensional shape of the sea surface","zh":"一百年前，我们对海洋的了解仅限于海面的二维形状","t":17.45},{"en":"and the hazards of navigation presented by the irregularities in depth of the shallow water close to the land.","zh":"以及陆地附近浅水区深度不规则所带来的航行危险。","t":24.9},{"en":"The open sea was deep and mysterious,","zh":"开阔的海洋深邃而神秘，","t":33.53},{"en":"and anyone who gave more than a passing thought to the bottom confines of the oceans probably assumed that the sea-bed was flat.","zh":"任何对海洋底部边界稍加思考的人可能都认为海床是平坦的。","t":36.86},{"en":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839,","zh":"詹姆斯·克拉克·罗斯爵士于1839年测得超过2400噚的深度，","t":45.67},{"en":"but it was not until 1869, when H.M.S. Porcupine was put at the disposal of the Royal Society for several cruises","zh":"但直到1869年，当“豪猪号”军舰被皇家学会征用进行数次航行时，","t":53.26},{"en":"that a series of deep soundings was obtained in the Atlantic and the first samples were collected by dredging the bottom.","zh":"才在大西洋获得了一系列深海探测数据，并通过海底拖网收集了第一批样本。","t":63.38},{"en":"Shortly after this the famous H.M.S. Challenger expedition established the study of the sea-floor","zh":"此后不久，著名的“挑战者号”军舰远征队确立了海底研究","t":71.84},{"en":"as a subject worthy of the most qualified physicists and geologists.","zh":"成为值得最合格的物理学家和地质学家研究的课题。","t":79.01},{"en":"A burst of activity associated with the laying of submarine cables","zh":"随之而来的海底电缆铺设热潮","t":84.37},{"en":"soon confirmed the Challenger's observation that many parts of the ocean were two to three miles deep,","zh":"很快证实了“挑战者号”的观测结果：海洋许多地方深达两到三英里，","t":89.62},{"en":"and the existence of underwater features of considerable magnitude.","zh":"并存在着规模巨大的水下特征。","t":97.28},{"en":"Today, enough soundings are available to enable a relief map of the Atlantic to be drawn","zh":"如今，已有的测深数据足以绘制出大西洋的浮雕地图，","t":102.74},{"en":"and we know something of the great variety of the sea bed's topography.","zh":"我们对海底地形的巨大多样性有了一定的了解。","t":109.02},{"en":"Since the sea covers the greater part of the earth's surface,","zh":"由于海洋覆盖了地球表面的大部分，","t":114.78},{"en":"it is quite reasonable to regard the sea floor as the basic form of the crust of the earth,","zh":"将海底视为地壳的基本形态是相当合理的，","t":118.56},{"en":"with superimposed upon it the continents,","zh":"大陆、","t":124.88},{"en":"together with the islands and other features of the oceans.","zh":"以及岛屿和海洋的其他特征都叠加其上。","t":128.74},{"en":"The continents form rugged tablelands which stand nearly three miles above the floor of the open ocean.","zh":"大陆形成了崎岖不平的高原，它们比开阔海洋的海底高出近三英里。","t":133.05},{"en":"From the shore line, out to a distance which may be anywhere from a few miles to a few hundred miles,","zh":"从海岸线向外延伸，距离可能从几英里到几百英里不等，","t":140.95},{"en":"runs the gentle slope of the continental shelf, geologically part of the continents.","zh":"是大陆架的平缓斜坡，它在地质学上属于大陆的一部分。","t":148.63},{"en":"The real dividing line between continents and oceans occurs at the foot of a steeper slope.","zh":"大陆和海洋的真正分界线出现在一个更陡峭的斜坡底部。","t":155.45},{"en":"This continental slope usually starts at a place somewhere near the 100-fathom mark","zh":"这个大陆坡通常始于100噚标记附近的某个地方，","t":162.7},{"en":"and in the course of a few hundred miles reaches the true ocean floor at 2,500-3,500 fathoms.","zh":"并在几百英里的延伸中到达2500-3500噚的真正海底。","t":168.91},{"en":"The slope averages about 1 in 30, but contains steep,","zh":"该斜坡平均坡度约为1:30，但包含陡峭的、","t":179.08},{"en":"probably vertical, cliffs, and gentle sediment-covered terraces,","zh":"可能是垂直的悬崖，以及平缓的被沉积物覆盖的阶地，","t":183.49},{"en":"and near its lower reaches there is a long tailing-off which is almost certainly the result of","zh":"在其下部区域，有一个长长的逐渐减缓的坡段，这几乎肯定是由于","t":188.14},{"en":"material transported out to deep water after being eroded from the continental masses.","zh":"物质从大陆块体被侵蚀后输送到深水区的结果。","t":194.36}],"vocab":[{"word":"confined","phonetic":"/kənˈfaɪnd/","meanings":[{"pos":"adjective","meaning":"有限的；受限制的","usage":"常用于描述范围、空间或认知被局限在某个区域内，常与介词to搭配引出限制的范围"}]},{"word":"hazard","phonetic":"/ˈhæzəd/","meanings":[{"pos":"noun","meaning":"危险；隐患","usage":"指存在潜在风险的事物，常见搭配有safety hazard（安全隐患）、navigation hazard（航行隐患）"}]},{"word":"assume","phonetic":"/əˈsjuːm/","meanings":[{"pos":"verb","meaning":"假定；假设；认为","usage":"指在没有确凿证据的情况下做出推测，后可接that从句或宾语+宾补结构"}]},{"word":"sounding","phonetic":"/ˈsaʊndɪŋ/","meanings":[{"pos":"noun","meaning":"水深测量；测深","usage":"海洋学专业词汇，指测量水体深度的行为或测得的深度数值"}]},{"word":"fathom","phonetic":"/ˈfæðəm/","meanings":[{"pos":"noun","meaning":"英寻（测量水深单位，1英寻约等于1.8米）","usage":"海洋测量的传统深度单位，也可作动词表示“透彻理解”"}]},{"word":"expedition","phonetic":"/ˌekspəˈdɪʃn/","meanings":[{"pos":"noun","meaning":"远征；探险队；考察","usage":"指有组织的长途探险、考察活动，也可指参与考察的队伍"}]},{"word":"qualified","phonetic":"/ˈkwɒlɪfaɪd/","meanings":[{"pos":"adjective","meaning":"有资格的；合格的","usage":"用于描述人具备完成某项工作所需的技能、知识或资质，常与介词for搭配"}]},{"word":"submarine","phonetic":"/ˌsʌbməˈriːn/","meanings":[{"pos":"adjective","meaning":"水下的；海底的","usage":"用于修饰海底的事物，如submarine cable（海底电缆），也可作名词表示“潜艇”"}]},{"word":"magnitude","phonetic":"/ˈmæɡnɪtjuːd/","meanings":[{"pos":"noun","meaning":"规模；大小；重要性","usage":"用于描述事物的尺寸、规模或重要程度，常和介词of搭配"}]},{"word":"topography","phonetic":"/təˈpɒɡrəfi/","meanings":[{"pos":"noun","meaning":"地形；地貌学","usage":"地理专业词汇，指某一地区的地形特征，或研究地形的学科"}]},{"word":"crust","phonetic":"/krʌst/","meanings":[{"pos":"noun","meaning":"地壳；外壳；面包皮","usage":"作地理术语时指地球的地壳，也可指物体的坚硬外层"}]},{"word":"superimposed","phonetic":"/ˌsuːpərɪmˈpəʊzd/","meanings":[{"pos":"adjective","meaning":"叠加的；附加的","usage":"常与介词on/upon搭配，指某物被放置在另一物的上方或添加到另一事物上"}]},{"word":"rugged","phonetic":"/ˈrʌɡɪd/","meanings":[{"pos":"adjective","meaning":"崎岖的；凹凸不平的","usage":"常用于形容地形高低不平、多岩石，也可形容人健壮结实"}]},{"word":"sediment","phonetic":"/ˈsedɪmənt/","meanings":[{"pos":"noun","meaning":"沉积物；沉淀物","usage":"指水或液体中沉淀下来的固体物质，常见于地质、水环境相关语境"}]},{"word":"erode","phonetic":"/ɪˈrəʊd/","meanings":[{"pos":"verb","meaning":"侵蚀；腐蚀","usage":"指风、水等自然力量逐渐磨损、破坏物体表面，也可引申指逐步削弱抽象事物"}]}],"phrases":[{"phrase":"be confined to","usage":"表示“被局限于；被限制在”，主语通常是认知、活动、范围等事物，to为介词，后接名词或动名词","examples":[{"en":"Our knowledge of the oceans a hundred years ago was confined to the two-dimensional shape of the sea surface.","zh":"100年前，我们对海洋的认识仅局限于海洋表面的二维形状。"},{"en":"Due to the pandemic, our travel was confined to the local area last year.","zh":"受疫情影响，去年我们的旅行范围被限制在本地。"}]},{"phrase":"at the disposal of","usage":"表示“由……支配；供……使用”，主语通常是物品、资源、人员等，of后接支配的主体","examples":[{"en":"H.M.S. Porcupine was put at the disposal of the Royal Society for several cruises.","zh":"“刺猬号”军舰被交由英国皇家学会支配，用于多次航行考察。"},{"en":"All the meeting rooms are at the disposal of the organizing committee during the conference.","zh":"会议期间所有会议室都供组委会支配使用。"}]},{"phrase":"a burst of","usage":"表示“一阵；突发的”，用于描述短时间内突然爆发的活动、情绪、声音等，后接不可数名词或可数名词单数","examples":[{"en":"A burst of activity associated with the laying of submarine cables soon confirmed the Challenger's observation.","zh":"铺设海底电缆带来的一阵密集活动很快证实了“挑战者号”的观测结果。"},{"en":"There was a burst of applause when the famous scientist walked onto the stage.","zh":"当那位著名科学家走上舞台时，现场爆发出一阵掌声。"}]},{"phrase":"be worthy of","usage":"表示“值得；配得上”，后接名词或动名词，主语通常是事物，说明其具备足够的价值匹配后面的内容","examples":[{"en":"The study of the sea-floor was established as a subject worthy of the most qualified physicists and geologists.","zh":"海底研究被确立为一门值得最顶尖的物理学家和地质学家研究的学科。"},{"en":"This innovative research is worthy of further investigation and promotion.","zh":"这项创新研究值得进一步调研和推广。"}]},{"phrase":"in the course of","usage":"表示“在……过程中；在……期间”，用于引出某个过程的时间段，后接名词","examples":[{"en":"The continental slope in the course of a few hundred miles reaches the true ocean floor at 2,500-3,500 fathoms.","zh":"大陆坡在延伸几百英里的过程中，会到达2500至3500英寻深的真正洋底。"},{"en":"He collected a lot of precious first-hand data in the course of his field research.","zh":"他在实地考察的过程中收集了很多珍贵的一手数据。"}]},{"phrase":"the result of","usage":"表示“……的结果”，用于说明事物产生的原因，后接名词或动名词短语","examples":[{"en":"The long tailing-off near the slope's lower reaches is almost certainly the result of material transported out to deep water after being eroded from the continental masses.","zh":"坡脚附近长长的缓坡几乎毫无疑问是大陆块被侵蚀后搬运到深水区的物质沉积形成的结果。"},{"en":"The rapid development of the local tourism industry is the result of years of environmental protection efforts.","zh":"当地旅游业的快速发展是多年来环境保护工作的结果。"}]}],"grammar":[{"title":"not until 强调句","definition":"用于强调“直到某个时间点某个动作才发生”，突出动作发生的时间很晚，或前提条件的重要性","structure":"It is/was not until + 时间/条件状语 + that + 主句（陈述语序）","usage":"当需要强调until引导的时间状语时，将not和until一起提前到强调结构中，主句的否定转移到not until部分，主句用肯定形式","examples":[{"en":"But it was not until 1869, when H.M.S. Porcupine was put at the disposal of the Royal Society for several cruises that a series of deep soundings was obtained in the Atlantic.","zh":"但直到1869年，“刺猬号”军舰被交由英国皇家学会支配进行多次航行时，人们才在大西洋获得了一系列深度探测数据。"},{"en":"It was not until the 20th century that humans began to explore outer space systematically.","zh":"直到20世纪，人类才开始系统地探索外太空。"}]},{"title":"完全倒装句（状语前置）","definition":"当表示方位、地点的介词短语或副词放在句首，且句子主语是名词时，句子需要完全倒装，即把谓语动词完全放到主语前面，用于强调地点或方位","structure":"介词短语/副词状语 + 谓语动词 + 主语（名词）","usage":"常见于描述地点、方位的语境，使句子更有画面感，避免头重脚轻","examples":[{"en":"From the shore line, out to a distance which may be anywhere from a few miles to a few hundred miles, runs the gentle slope of the continental shelf.","zh":"从海岸线向外延伸数英里到数百英里不等的区域，是平缓的大陆架斜坡。"},{"en":"At the foot of the mountain lies a small village with a history of over 300 years.","zh":"山脚下坐落着一个有着300多年历史的小村庄。"}]},{"title":"同位语从句","definition":"用于解释说明前面抽象名词的具体内容，通常由that引导，that在从句中不充当任何成分，只起连接作用","structure":"抽象名词（observation/fact/news/idea等） + that + 完整的陈述句","usage":"常见于可以承载具体内容的抽象名词后，对名词的内容进行详细说明","examples":[{"en":"A burst of activity associated with the laying of submarine cables soon confirmed the Challenger's observation that many parts of the ocean were two to three miles deep.","zh":"铺设海底电缆带来的密集活动很快证实了“挑战者号”的观测结果，即海洋的很多区域深度可达2到3英里。"},{"en":"The fact that the Arctic ice is melting at an alarming rate has drawn global attention.","zh":"北极冰层正以惊人速度融化的事实已经引起了全球关注。"}]}],"patterns":[{"pattern":"It is quite reasonable to regard sth as ...","explanation":"","original":{"en":"Since the sea covers the greater part of the earth's surface, it is quite reasonable to regard the sea floor as the basic form of the crust of the earth.","zh":"由于海洋覆盖了地球表面的大部分区域，因此把海床看作地壳的基本形态是非常合理的。"},"examples":[{"en":"Since renewable energy has lower carbon emissions, it is quite reasonable to regard it as the core of future energy systems.","zh":"由于可再生能源碳排放更低，因此将其视作未来能源体系的核心是非常合理的。"},{"en":"Since reading can broaden our horizons and enrich our inner world, it is quite reasonable to regard it as a lifelong habit worth sticking to.","zh":"由于阅读能够拓宽视野、丰富内心世界，因此将其看作值得坚持的终身习惯是非常合理的。"}]},{"pattern":"Sb did sth in 年份, but it was not until 另一年份, when 背景事件, that 重要成果 was achieved.","explanation":"","original":{"en":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839, but it was not until 1869, when H.M.S. Porcupine was put at the disposal of the Royal Society for several cruises that a series of deep soundings was obtained in the Atlantic.","zh":"詹姆斯·克拉克·罗斯爵士早在1839年就测得超过2400英寻的深度，但直到1869年，“刺猬号”军舰被交由英国皇家学会支配进行多次航行时，人们才在大西洋获得了一系列深度探测数据。"},"examples":[{"en":"Scientists first proposed the concept of gene editing in the 1970s, but it was not until 2012, when the CRISPR technology was invented, that precise and low-cost gene modification became possible.","zh":"科学家早在20世纪70年代就首次提出了基因编辑的概念，但直到2012年CRISPR技术被发明时，精准且低成本的基因修改才成为可能。"},{"en":"The idea of driverless cars appeared in science fiction as early as the 1920s, but it was not until recent years, when artificial intelligence technology developed rapidly, that autonomous driving began to be tested on public roads.","zh":"无人驾驶汽车的设想早在20世纪20年代就出现在科幻作品中，但直到近些年人工智能技术快速发展时，自动驾驶才开始在公共道路上进行测试。"}]},{"pattern":"sth usually starts at ... and in the course of ... reaches ...","explanation":"","original":{"en":"This continental slope usually starts at a place somewhere near the 100-fathom mark and in the course of a few hundred miles reaches the true ocean floor at 2,500-3,500 fathoms.","zh":"这种大陆坡通常起于约100英寻深的位置，在延伸几百英里的过程中，到达2500至3500英寻深的真正洋底。"},"examples":[{"en":"The long-distance hiking trail usually starts at the foot of the mountain and in the course of 30 kilometers reaches the summit at an altitude of over 3,000 meters.","zh":"这条长途徒步路线通常起于山脚，在延伸30公里的过程中，到达海拔3000多米的顶峰。"},{"en":"The river usually starts at the glacier in the mountains and in the course of thousands of kilometers reaches the estuary where it flows into the sea.","zh":"这条河流通常发源于山区的冰川，在流经数千公里的过程中，到达汇入海洋的河口。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“远征；探险队；考察” 对应的单词是？","hint":"noun · /ˌekspəˈdɪʃn/","options":["expedition","chasm","migration","remedy"],"answer":0,"explain":"expedition · /ˌekspəˈdɪʃn/ · noun · 远征；探险队；考察。指有组织的长途探险、考察活动，也可指参与考察的队伍","source":{"kind":"vocab","word":"expedition"},"id":"b4-u30-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：英寻（测量水深单位，1英寻约等于1.8米）","hint":"/ˈfæðəm/ · noun","answer":"fathom","placeholder":"输入英文单词","explain":"fathom · /ˈfæðəm/ · noun · 英寻（测量水深单位，1英寻约等于1.8米）。海洋测量的传统深度单位，也可作动词表示“透彻理解”","source":{"kind":"vocab","word":"fathom"},"id":"b4-u30-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The rapid development of the local tourism industry is _____ years of environmental protection efforts.","hint":"当地旅游业的快速发展是多年来环境保护工作的结果。","answer":"the result of","placeholder":"输入缺失的短语","explain":"the result of：表示“……的结果”，用于说明事物产生的原因，后接名词或动名词短语（当地旅游业的快速发展是多年来环境保护工作的结果。）","source":{"kind":"phrase","phrase":"the result of"},"id":"b4-u30-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：A burst of activity associated with the _____ of submarine cables","hint":"随之而来的海底电缆铺设热潮","answer":"laying","placeholder":"输入缺失的单词","explain":"A burst of activity associated with the laying of submarine cables — 随之而来的海底电缆铺设热潮","source":{"kind":"sentence","en":"A burst of activity associated with the laying of submarine cables"},"id":"b4-u30-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当表示方位、地点的介词短语或副词放在句首，且句子主语是名词时，句子需要完全倒装，即把谓语动词完全放到主语前面，用于强调地点或方位” 描述的是哪个语法点？","hint":"介词短语/副词状语 + 谓语动词 + 主语（名词）","options":["条件状语从句：unless引导","虚拟语气用于对过去的推测","完全倒装句（状语前置）","方式状语从句"],"answer":2,"explain":"完全倒装句（状语前置）：介词短语/副词状语 + 谓语动词 + 主语（名词）：常见于描述地点、方位的语境，使句子更有画面感，避免头重脚轻","source":{"kind":"grammar","title":"完全倒装句（状语前置）"},"id":"b4-u30-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nSir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839,","hint":"","options":["用脚辨认出了藏在地毯下面的一幅画的轮廓和颜色。","引力便是驱使它们不断尝试将海洋表面恢复到平坦状态的力量。","詹姆斯·克拉克·罗斯爵士于1839年测得超过2400噚的深度，","欣赏雕塑取决于能够感知三维形态的能力。"],"answer":2,"explain":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839, — 詹姆斯·克拉克·罗斯爵士于1839年测得超过2400噚的深度，","source":{"kind":"sentence","en":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839,"},"id":"b4-u30-q06"}]},{"id":"b4-u31","book":4,"unit":31,"key":"31","lessonFrom":31,"lessonTo":31,"title":"The Sculptor Speaks","titleZh":"雕塑家说","question":"What do you have to be able to do to appreciate sculpture?","sentences":[{"en":"Appreciation of sculpture depends upon the ability to respond to form in 3 dimensions.","zh":"欣赏雕塑取决于能够感知三维形态的能力。","t":17.35},{"en":"That is perhaps why sculpture has been described as the most difficult of all arts;","zh":"这也许就是为什么雕塑被描述为所有艺术中最难的；","t":25.69},{"en":"certainly it is more difficult than the arts which involve appreciation of flat forms, shape in only two dimensions.","zh":"当然，它比那些涉及欣赏平面形态（仅二维形状）的艺术要难。","t":32.1},{"en":"Many more people are 'form-blind' than colour-blind.","zh":"相比色盲，更多的人是“形盲”。","t":41.91},{"en":"The child learning to see, first distinguishes only two-dimensional shape; it cannot judge distances, depths.","zh":"孩子在学习看东西时，首先只能辨别二维形状；它无法判断距离和深度。","t":48.46},{"en":"Later, for its personal safety and practical needs, it has to develop (partly by means of touch) the ability to judge roughly 3-dimensonal distances.","zh":"后来，为了自身的安全和实际需要，它必须培养（部分通过触摸）粗略判断三维距离的能力。","t":57.88},{"en":"But having satisfied the requirements of practical necessity, most people go no further.","zh":"但是，在满足了实际需要的要求之后，大多数人就不会再深入了。","t":71.81},{"en":"Though they may attain considerable accuracy in the perception of flat form,","zh":"尽管他们可能在感知平面形态方面达到相当高的准确度，","t":78.94},{"en":"they do not make the further intellectual and emotional effort needed to comprehend form in its full spatial existence.","zh":"但他们不会付出进一步的智力和情感努力，来理解形态的完整空间存在。","t":84.99},{"en":"This is what the sculptor must do.","zh":"这就是雕塑家必须做的事情。","t":95.23},{"en":"He must strive continually to think of and use, form in its full spatial completeness.","zh":"他必须不断努力思考和运用形态的完整空间性。","t":98.04},{"en":"He gets the solid shape as it were, inside his head--he thinks of it, whatever its size, as if he were holding it completely enclosed in the hollow of his hand.","zh":"他仿佛将固体形状置于脑中——无论大小，他都将其视作完全握在掌中。","t":106.88},{"en":"He mentally visualizes a complex form from all round itself;","zh":"他在脑海中从各个方向观察复杂的形态；","t":120.7},{"en":"he knows while he looks at one side what the other side is like; he identifies himself with its centre of gravity, its mass, its weight;","zh":"当他看一面时，他就知道另一面是什么样子；他将自己与它的重心、质量、重量联系起来；","t":127.3},{"en":"he realizes its volume as the space that the shape displaces in the air.","zh":"他将它的体积理解为形状在空气中排开的空间。","t":138.34},{"en":"And the sensitive observer of sculpture must also learn to feel shape simply as shape, not as description or reminiscence.","zh":"并且，敏感的雕塑观察者也必须学会将形状单纯地感受为形状，而不是描述或回忆。","t":144.81},{"en":"He must, for example, perceive an egg as a simple single solid shape quite apart from its significance as food,","zh":"例如，他必须将一个鸡蛋视为一个简单、单一的固体形状，完全脱离它作为食物的意义，","t":154.47},{"en":"or from the literary idea that it will become a bird.","zh":"或脱离它会变成一只鸟的文学观念。","t":164.43},{"en":"And so with solids such as a shell, a nut, a plum, a pear, a tadpole, a mushroom,","zh":"对于诸如贝壳、坚果、李子、梨、蝌蚪、蘑菇、","t":169.08},{"en":"a mountain peak, a kidney, a carrot, a tree-trunk, a bird, a bud, a lark, a ladybird, a bulrush, a bone.","zh":"山峰、肾脏、胡萝卜、树干、鸟、花蕾、百灵鸟、瓢虫、香蒲、骨头等固体也是如此。","t":178.09},{"en":"From these he can go on to appreciate more complex forms or combinations of several forms.","zh":"从这些事物中，他可以进一步欣赏更复杂的形态或多种形态的组合。","t":191.28}],"vocab":[{"word":"sculptor","phonetic":"/ˈskʌlptə(r)/","meanings":[{"pos":"noun","meaning":"雕刻家，雕塑家","usage":"指从事雕塑创作的职业艺术家"}]},{"word":"appreciate","phonetic":"/əˈpriːʃieɪt/","meanings":[{"pos":"verb","meaning":"欣赏，鉴赏","usage":"指对艺术、美等有深入的理解和感知"},{"pos":"verb","meaning":"感激，感谢","usage":"表示对他人的帮助或付出怀有谢意"}]},{"word":"dimension","phonetic":"/daɪˈmenʃn/","meanings":[{"pos":"noun","meaning":"维度，方面","usage":"用于描述空间的维度，也可引申为事物的某一方面"}]},{"word":"sculpture","phonetic":"/ˈskʌlptʃə(r)/","meanings":[{"pos":"noun","meaning":"雕塑，雕刻作品","usage":"指三维的造型艺术作品，也可指雕塑这一艺术形式"}]},{"word":"perception","phonetic":"/pəˈsepʃn/","meanings":[{"pos":"noun","meaning":"感知，看法","usage":"指人通过感官对事物产生的认知，也可指主观的看法"}]},{"word":"spatial","phonetic":"/ˈspeɪʃl/","meanings":[{"pos":"adjective","meaning":"空间的，与空间有关的","usage":"用于修饰和空间、位置相关的概念"}]},{"word":"strive","phonetic":"/straɪv/","meanings":[{"pos":"verb","meaning":"努力，奋斗","usage":"强调为了某个目标付出持续的努力，常见搭配strive for sth/strive to do sth"}]},{"word":"visualize","phonetic":"/ˈvɪʒuəlaɪz/","meanings":[{"pos":"verb","meaning":"想象，使可视化","usage":"指在脑海中形成清晰的图像或画面"}]},{"word":"gravity","phonetic":"/ˈɡrævəti/","meanings":[{"pos":"noun","meaning":"重力，地心引力","usage":"物理学概念，也可引申为严重性"}]},{"word":"volume","phonetic":"/ˈvɒljuːm/","meanings":[{"pos":"noun","meaning":"体积，容积","usage":"描述物体所占空间的大小，也可指音量、书卷"}]},{"word":"sensitive","phonetic":"/ˈsensətɪv/","meanings":[{"pos":"adjective","meaning":"敏感的，敏锐的","usage":"形容人对事物的感知力强，也可指易受伤害的"}]},{"word":"reminiscence","phonetic":"/ˌremɪˈnɪsns/","meanings":[{"pos":"noun","meaning":"回忆，怀旧","usage":"指对过去事物的记忆和回想"}]},{"word":"perceive","phonetic":"/pəˈsiːv/","meanings":[{"pos":"verb","meaning":"感知，认为","usage":"指通过感官察觉，也可指对事物形成某种看法"}]},{"word":"significance","phonetic":"/sɪɡˈnɪfɪkəns/","meanings":[{"pos":"noun","meaning":"意义，重要性","usage":"指事物的含义或重要程度"}]},{"word":"combination","phonetic":"/ˌkɒmbɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"结合，组合","usage":"指多个事物组合在一起的整体，或组合的过程"}]}],"phrases":[{"phrase":"depend upon/on","usage":"表示某事物由另一事物决定或取决于后者","examples":[{"en":"The success of the project depends upon the cooperation of all team members.","zh":"这个项目的成功取决于所有团队成员的合作。"},{"en":"Your grade will depend on your final exam performance.","zh":"你的成绩将取决于你期末考试的表现。"}]},{"phrase":"by means of","usage":"表示通过某种方式、方法或工具达成目的，是较正式的表达","examples":[{"en":"We can lift the heavy box by means of a pulley.","zh":"我们可以借助滑轮抬起这个重箱子。"},{"en":"The rescue team communicated with each other by means of walkie-talkies.","zh":"救援队通过对讲机互相沟通。"}]},{"phrase":"as it were","usage":"插入语，用于表示所说的话不完全准确，是一种比喻或委婉的说法，可译为“可以说，在某种程度上”","examples":[{"en":"The new shopping centre is, as it were, the heart of the city.","zh":"这个新的购物中心可以说是这座城市的心脏。"},{"en":"He is, as it were, a walking dictionary in our class.","zh":"他在我们班可以说是一本活字典。"}]},{"phrase":"identify with","usage":"表示与某人/某物产生共鸣，或者将自己等同于某人/某物，理解其感受","examples":[{"en":"Many readers identify with the main character of the novel.","zh":"很多读者都和这本小说的主角产生了共鸣。"},{"en":"It's hard for children to identify with the worries of adults.","zh":"孩子很难理解成年人的烦恼。"}]},{"phrase":"apart from","usage":"表示“除了……之外，撇开……不谈”，既可以表示包含也可以表示排除的含义","examples":[{"en":"Apart from the cost, the dress is very suitable for you.","zh":"撇开价格不谈，这条裙子非常适合你。"},{"en":"Apart from English, he can also speak French and Japanese.","zh":"除了英语之外，他还会说法语和日语。"}]},{"phrase":"strive to do sth","usage":"表示为了达成某个目标而努力奋斗，强调付出持续的努力","examples":[{"en":"Scientists strive to find a cure for this rare disease.","zh":"科学家们努力寻找这种罕见疾病的治疗方法。"},{"en":"Every student should strive to improve their learning efficiency.","zh":"每个学生都应该努力提高自己的学习效率。"}]},{"phrase":"attain accuracy in","usage":"表示在某个方面达到准确性，多用于描述技能、认知等领域的精准度提升","examples":[{"en":"After months of practice, he attained great accuracy in playing the piano.","zh":"经过几个月的练习，他弹钢琴的准度已经非常高了。"},{"en":"The weather forecast has attained high accuracy in recent years.","zh":"近年来天气预报的准确率已经很高了。"}]},{"phrase":"respond to","usage":"表示对……做出反应、回应，也可引申为对某事物有感知、有共鸣","examples":[{"en":"The audience responded positively to the speaker's wonderful speech.","zh":"观众对演讲者的精彩演讲反应很积极。"},{"en":"A good listener knows how to properly respond to others' feelings.","zh":"好的倾听者知道如何恰当回应他人的情绪。"}]}],"grammar":[{"title":"让步状语从句：though引导的让步结构","definition":"用来表示虽然存在某个情况，但主句的结果仍然成立，表达让步的逻辑关系","structure":"Though + 从句, 主句","usage":"though引导的从句可以放在句首或句中，不与but连用，但可以和yet、still搭配，语气较although更口语化","examples":[{"en":"Though they may attain considerable accuracy in the perception of flat form, they do not make the further intellectual and emotional effort needed to comprehend form in its full spatial existence.","zh":"虽然他们可能在感知平面形状方面达到相当准确的程度，但他们不会进一步付出智力和情感上的努力，去理解存在于完整空间中的形体。"},{"en":"Though he is very young, he has already published three novels.","zh":"虽然他很年轻，但他已经出版了三本小说。"},{"en":"The project is progressing well, though there are still some small problems to be solved.","zh":"项目进展很顺利，尽管还有一些小问题需要解决。"}]},{"title":"被动语态的使用","definition":"当动作的承受者是句子的主语，或者不需要明确指出动作发出者时，使用被动语态","structure":"主语 + be + 动词过去分词 + (by + 动作发出者)","usage":"常用于正式文体中，强调动作的承受者，或者当动作发出者不明确、不重要时使用","examples":[{"en":"That is perhaps why sculpture has been described as the most difficult of all arts.","zh":"这也许就是为什么雕塑被称作所有艺术中最难的一种。"},{"en":"The old temple has been preserved perfectly by the local government.","zh":"这座古老的寺庙被当地政府保护得非常完好。"},{"en":"This theory was first proposed by a scientist in the 19th century.","zh":"这个理论是19世纪的一位科学家首次提出的。"}]}],"patterns":[{"pattern":"... depends upon the ability to do sth","explanation":"","original":{"en":"Appreciation of sculpture depends upon the ability to respond to form in 3 dimensions.","zh":"对雕塑的鉴赏取决于对三维形体做出反应的能力。"},"examples":[{"en":"Learning a foreign language well depends upon the ability to use it in real communication.","zh":"学好一门外语取决于在真实交流中使用它的能力。"},{"en":"Success in the competitive job market depends upon the ability to adapt to changes quickly.","zh":"在竞争激烈的就业市场中取得成功取决于快速适应变化的能力。"}]},{"pattern":"That is perhaps why + 从句","explanation":"","original":{"en":"That is perhaps why sculpture has been described as the most difficult of all arts.","zh":"这也许就是为什么雕塑被称作所有艺术中最难的一种。"},"examples":[{"en":"That is perhaps why many people prefer to travel during off-peak seasons.","zh":"这也许就是为什么很多人更喜欢在淡季出行。"},{"en":"That is perhaps why regular exercise is always recommended by health experts.","zh":"这也许就是健康专家一直推荐规律锻炼的原因。"}]},{"pattern":"Sb must learn to do sth, not as sth else.","explanation":"","original":{"en":"And the sensitive observer of sculpture must also learn to feel shape simply as shape, not as description or reminiscence.","zh":"而敏锐的雕塑观察者也必须学会单纯地把形状当作形状去感受，而不是作为描述或者回忆。"},"examples":[{"en":"A literary critic must learn to analyze a work simply as an independent creation, not as an extension of the author's private life.","zh":"文学评论家必须学会单纯把作品当作独立的创作去分析，而不是作为作者私生活的延伸。"},{"en":"When tasting wine, you should learn to savor the flavor simply as flavor, not as a symbol of social status.","zh":"品鉴葡萄酒的时候，你应该学会单纯品味它的风味，而不是把它当作社会地位的象征。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“想象，使可视化” 对应的单词是？","hint":"verb · /ˈvɪʒuəlaɪz/","options":["talent","assume","virtual","visualize"],"answer":3,"explain":"visualize · /ˈvɪʒuəlaɪz/ · verb · 想象，使可视化。指在脑海中形成清晰的图像或画面","source":{"kind":"vocab","word":"visualize"},"id":"b4-u31-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：努力，奋斗","hint":"/straɪv/ · verb","answer":"strive","placeholder":"输入英文单词","explain":"strive · /straɪv/ · verb · 努力，奋斗。强调为了某个目标付出持续的努力，常见搭配strive for sth/strive to do sth","source":{"kind":"vocab","word":"strive"},"id":"b4-u31-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ the cost, the dress is very suitable for you.","hint":"撇开价格不谈，这条裙子非常适合你。","answer":"apart from","placeholder":"输入缺失的短语","explain":"apart from：表示“除了……之外，撇开……不谈”，既可以表示包含也可以表示排除的含义（撇开价格不谈，这条裙子非常适合你。）","source":{"kind":"phrase","phrase":"apart from"},"id":"b4-u31-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He must strive _____ to think of and use, form in its full spatial completeness.","hint":"他必须不断努力思考和运用形态的完整空间性。","answer":"continually","placeholder":"输入缺失的单词","explain":"He must strive continually to think of and use, form in its full spatial completeness. — 他必须不断努力思考和运用形态的完整空间性。","source":{"kind":"sentence","en":"He must strive continually to think of and use, form in its full spatial completeness."},"id":"b4-u31-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来表示虽然存在某个情况，但主句的结果仍然成立，表达让步的逻辑关系” 描述的是哪个语法点？","hint":"Though + 从句, 主句","options":["比较状语从句 (Comparative Adverbial Clause)","介词+which引导的定语从句","让步状语从句：though引导的让步结构","倒装语序（Nor引导的否定倒装）"],"answer":2,"explain":"让步状语从句：though引导的让步结构：Though + 从句, 主句：though引导的从句可以放在句首或句中，不与but连用，但可以和yet、still搭配，语气较although更口语化","source":{"kind":"grammar","title":"让步状语从句：though引导的让步结构"},"id":"b4-u31-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nBut having satisfied the requirements of practical necessity, most people go no further.","hint":"","options":["度假酒店往往特别迎合——有时甚至专门迎合——某一国籍的游客。","当她从漂浮的硝烟中驶出，船头下的水花翻腾成泡沫，","但是，在满足了实际需要的要求之后，大多数人就不会再深入了。","19世纪40年代用罗斯勋爵的大望远镜观察到的螺旋星云是研磨器留下的划痕的人更应受到谴责呢？"],"answer":2,"explain":"But having satisfied the requirements of practical necessity, most people go no further. — 但是，在满足了实际需要的要求之后，大多数人就不会再深入了。","source":{"kind":"sentence","en":"But having satisfied the requirements of practical necessity, most people go no further."},"id":"b4-u31-q06"}]},{"id":"b4-u32","book":4,"unit":32,"key":"32","lessonFrom":32,"lessonTo":32,"title":"Galileo Reborn","titleZh":"伽利略再生","question":"What has modified our traditional view of Galileo in recent times?","sentences":[{"en":"In his own lifetime Galileo was the centre of violent controversy, but the scientific dust has long since settled,","zh":"伽利略在他有生之年一直处于剧烈争议的中心，但科学上的尘埃早已落定，","t":17.77},{"en":"and today we can see even his famous clash with the Inquisition in something like its proper perspective.","zh":"今天我们甚至可以用一种恰当的视角来看待他与宗教裁判所的著名冲突。","t":26.84},{"en":"But, in contrast, it is only in modern times that Galileo has become a problem child for historians of science.","zh":"然而，与此相反，只是到了现代，伽利略才成了科学史家们的一个难题。","t":34.42},{"en":"The old view of Galileo was delightfully uncomplicated.","zh":"对伽利略的旧观点是简单明了的。","t":44.11},{"en":"He was, above all, a man who experimented:","zh":"首先，他是一个实验家：","t":48.63},{"en":"who despised the prejudice and book learning of the Aristotelians,","zh":"他鄙视亚里士多德学派的偏见和书本知识，","t":52.78},{"en":"who put his questions to nature instead of to the ancients, and who drew his conclusions fearlessly.","zh":"他向自然而不是向古人提问，并无所畏惧地得出结论。","t":57.49},{"en":"He had been the first to turn a telescope to the sky,","zh":"他是第一个把望远镜对准天空的人，","t":65.65},{"en":"and he had seen there evidence enough to overthrow Aristotle and Ptolemy together.","zh":"他在那里看到了足以推翻亚里士多德和托勒密的证据。","t":69.37},{"en":"He was the man who climbed the Leaning Tower of Pisa and dropped various weights from the top,","zh":"他曾登上比萨斜塔，从塔顶扔下各种重量的物体，","t":75.98},{"en":"who rolled balls down inclined planes, and then generalized the results of his many experiments into the famous law of free fall.","zh":"他曾将球滚下斜面，然后将其众多实验的结果概括为著名的自由落体定律。","t":82.4},{"en":"But a closer study of the evidence,","zh":"然而，对证据的更深入研究，","t":93.86},{"en":"supported by a deeper sense of the period, and particularly by a new consciousness of the philosophical undercurrents in the scientific revolution,","zh":"加上对那个时代更深刻的理解，特别是对科学革命中哲学暗流的新认识，","t":96.04},{"en":"has profoundly modified this view of Galileo.","zh":"已经深刻地修正了对伽利略的这一看法。","t":105.78},{"en":"Today, although the old Galileo lives on in many popular writings,","zh":"如今，尽管旧的伽利略形象依然存在于许多流行著作中，","t":109.86},{"en":"among historians of science a new and more sophisticated picture has emerged.","zh":"但在科学史家之间，一个更复杂、更精密的形象已经出现。","t":116.7},{"en":"At the same time our sympathy for Galileo's opponents has grown somewhat.","zh":"同时，我们对伽利略反对者的同情也有所增加。","t":121.49},{"en":"His telescopic observations are justly immortal;","zh":"他的望远镜观测是理所当然的不朽之举；","t":126.42},{"en":"they aroused great interest at the time,","zh":"它们在当时引起了巨大的兴趣，","t":130.41},{"en":"they had important theoretical consequences,","zh":"它们产生了重要的理论结果，","t":133.17},{"en":"and they provided a striking demonstration of the potentialities hidden in instruments and apparatus.","zh":"它们有力地展示了仪器和设备中蕴藏的潜力。","t":136.37},{"en":"But can we blame those who looked and failed to see what Galileo saw,","zh":"但是，我们能责怪那些看了却没看到伽利略所见之人吗，","t":144.6},{"en":"if we remember that to use a telescope at the limit of its powers calls for long experience and intimate familiarity with one's instrument?","zh":"如果我们考虑到要充分利用望远镜的极限功能需要长时间的经验和对仪器的深入熟悉？","t":150.04},{"en":"Was the philosopher who refused to look through Galileo's telescope more culpable than those who alleged","zh":"那些拒绝通过伽利略的望远镜观察的哲学家，是否比那些声称","t":160.5},{"en":"that the spiral nebulae observed with Lord Rosse's great telescope in the 1840s were scratches left by the grinder?","zh":"19世纪40年代用罗斯勋爵的大望远镜观察到的螺旋星云是研磨器留下的划痕的人更应受到谴责呢？","t":167.5},{"en":"We can perhaps forgive those who said the moons of Jupiter were produced by Galileo's spyglass","zh":"我们或许可以原谅那些说木星卫星是伽利略的望远镜制造出来的人，","t":177.31},{"en":"if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth;","zh":"如果我们回想起在他那个时代，就像几个世纪以前一样，曲面玻璃是制造幻觉、谎言而非真相的流行手段；","t":186.67},{"en":"and if a single curved glass would distort nature, how much more would a pair of them?","zh":"那么，如果一块曲面玻璃会扭曲自然，两块又会怎样呢？","t":196.81}],"vocab":[{"word":"controversy","phonetic":"/ˈkɒntrəvɜːsi/","meanings":[{"pos":"noun","meaning":"争论，争议","usage":"指对某一问题存在的公开、长期的不同意见，常搭配动词arouse/cause/provoke表示“引发争议”，介词over/about引出争议的具体内容"}]},{"word":"perspective","phonetic":"/pəˈspektɪv/","meanings":[{"pos":"noun","meaning":"视角，观点；客观判断力","usage":"表示看待事物的角度，常用搭配in perspective表示“正确客观地看待”，in ... perspective表示“从…角度来看”"}]},{"word":"despise","phonetic":"/dɪˈspaɪz/","meanings":[{"pos":"verb","meaning":"鄙视，蔑视","usage":"带有强烈的轻视感情色彩，宾语可以是人或事物，后可直接接名词/动名词，无被动语态的常用表达"}]},{"word":"prejudice","phonetic":"/ˈpredʒudɪs/","meanings":[{"pos":"noun","meaning":"偏见，成见","usage":"常搭配介词against表示“对…的偏见”，动词hold/have prejudice表示“持有偏见”"}]},{"word":"overthrow","phonetic":"/ˌəʊvəˈθrəʊ/","meanings":[{"pos":"verb","meaning":"推翻，颠覆（观念、制度、统治者）","usage":"既可以指推翻政权，也可以指推翻旧的理论、观念，过去式和过去分词为overthrew/overthrown"}]},{"word":"inclined","phonetic":"/ɪnˈklaɪnd/","meanings":[{"pos":"adjective","meaning":"倾斜的；有…倾向的","usage":"作“倾斜的”时修饰具体物体，如inclined plane（斜面）；作“有倾向的”时常用结构be inclined to do sth."}]},{"word":"generalize","phonetic":"/ˈdʒenrəlaɪz/","meanings":[{"pos":"verb","meaning":"概括，归纳；推广","usage":"常搭配介词from表示“从…中归纳”，into表示“归纳为…”，指从具体事例中得出普遍结论"}]},{"word":"profoundly","phonetic":"/prəˈfaʊndli/","meanings":[{"pos":"adverb","meaning":"深刻地，极大地","usage":"用于修饰表示影响、改变、感受等的抽象动词或形容词，程度比deeply更正式、强烈"}]},{"word":"sophisticated","phonetic":"/səˈfɪstɪkeɪtɪd/","meanings":[{"pos":"adjective","meaning":"复杂精密的；老练的，见多识广的","usage":"可修饰人表示精通某领域、富有经验，也可修饰事物表示结构复杂、技术先进"}]},{"word":"immortal","phonetic":"/ɪˈmɔːtl/","meanings":[{"pos":"adjective","meaning":"不朽的，流芳百世的","usage":"用于形容成就、作品、名声等可以长久留存、永远被铭记的事物，反义词为mortal"}]},{"word":"potentiality","phonetic":"/pəˌtenʃiˈæləti/","meanings":[{"pos":"noun","meaning":"潜力，可能性","usage":"正式用词，常用复数形式表示多种潜在的可能性，搭配hidden/great修饰，相当于potential的名词正式形式"}]},{"word":"intimate","phonetic":"/ˈɪntɪmət/","meanings":[{"pos":"adjective","meaning":"亲密的；详尽的，精通的","usage":"搭配knowledge/familiarity表示“对…十分精通、熟悉”，也可形容人与人的关系亲密"}]},{"word":"culpable","phonetic":"/ˈkʌlpəbl/","meanings":[{"pos":"adjective","meaning":"应受责备的，有过失的","usage":"正式法律或书面用词，指对错误、罪行负有责任，常搭配介词for表示“对…负有责任”"}]},{"word":"allege","phonetic":"/əˈledʒ/","meanings":[{"pos":"verb","meaning":"声称，断言（未证实的事）","usage":"尤其指在没有证据的情况下公开宣称某事为真，常用被动结构be alleged to do sth."}]},{"word":"distort","phonetic":"/dɪˈstɔːt/","meanings":[{"pos":"verb","meaning":"扭曲，歪曲","usage":"可指物体外形的扭曲变形，也可指对事实、观点、真相的歪曲篡改"}]}],"phrases":[{"phrase":"in contrast","usage":"用于句首或句中，表示前后两种情况形成鲜明对比，可与with/to搭配引出对比的对象","examples":[{"en":"In contrast, the new approach is much more efficient and environment-friendly.","zh":"相比之下，新方法要高效、环保得多。"},{"en":"His brother is very outgoing, in contrast, he is quiet and likes reading alone.","zh":"他的哥哥十分外向，相比之下，他很安静，喜欢独自读书。"}]},{"phrase":"above all","usage":"用于强调诸多因素中最重要的一点，通常放在句首或句中作插入语","examples":[{"en":"When you choose a career, above all, you should consider your interest and long-term development.","zh":"当你选择职业时，最重要的是要考虑自己的兴趣和长期发展。"},{"en":"The hotel offers perfect service, above all, its location is very convenient for tourists.","zh":"这家酒店服务很棒，最重要的是，它的位置对游客来说十分便利。"}]},{"phrase":"put questions to","usage":"表示向某人/某对象提出疑问、寻求答案，正式书面用法，宾语可以是人或抽象事物","examples":[{"en":"Good researchers are those who dare to put questions to established theories.","zh":"优秀的研究者是那些敢于向既定理论提出疑问的人。"},{"en":"During the press conference, reporters put a series of questions to the official.","zh":"在新闻发布会上，记者们向这位官员提出了一系列问题。"}]},{"phrase":"call for","usage":"表示“需要，要求”，主语通常为某件事、某种情况，宾语为需要的品质、行动、条件等","examples":[{"en":"This difficult task calls for patience, creativity and strong team cooperation.","zh":"这项艰巨的任务需要耐心、创造力和强有力的团队协作。"},{"en":"The current situation calls for immediate action to prevent the problem from getting worse.","zh":"当前的形势要求我们立即采取行动，防止问题进一步恶化。"}]},{"phrase":"be familiar with","usage":"表示“熟悉，了解”，主语为人，宾语为被熟悉的事物，区别于be familiar to（某物为某人所熟知）","examples":[{"en":"If you want to work in this field, you must be familiar with the latest industry regulations.","zh":"如果你想在这个领域工作，你必须熟悉最新的行业规定。"},{"en":"He has lived in the city for 10 years, so he is very familiar with every street here.","zh":"他在这座城市生活了10年，所以对这里的每一条街都非常熟悉。"}]},{"phrase":"live on","usage":"表示“继续存在，流传下去”，主语可以是人（表示靠…为生）或抽象事物（表示留存）","examples":[{"en":"Although the writer has passed away for decades, his works still live on in the hearts of readers.","zh":"尽管这位作家已经去世几十年了，他的作品仍然在读者心中流传。"},{"en":"The memory of that historic event will live on for generations to come.","zh":"对那个历史事件的记忆将会代代传承下去。"}]},{"phrase":"in one's own right","usage":"表示“凭借自身的能力、资格”，用于强调某人/某物本身具备的属性，而非依赖他人","examples":[{"en":"She is a famous artist in her own right, not just the daughter of a well-known director.","zh":"她本身就是一位著名艺术家，而不仅仅是知名导演的女儿。"},{"en":"This small town is a tourist attraction in its own right, with its unique ancient architecture.","zh":"这座小镇凭借其独特的古建筑，本身就是一个旅游景点。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用来突出强调句子的某一成分（通常是主语、宾语、状语）的句式，不改变原句的意思和语法结构","structure":"It is/was + 被强调部分 + that/who + 句子剩余部分","usage":"当被强调部分是人时可以用who代替that，其他情况一律用that；被强调的部分可以是名词、短语、状语从句，不能强调谓语动词","examples":[{"en":"It is only in modern times that Galileo has become a problem child for historians of science.","zh":"直到现代，伽利略才成了科学史学家眼中的“问题人物”。"},{"en":"It was his courage and honesty that impressed all the interviewers deeply.","zh":"正是他的勇气和诚实给所有面试官留下了深刻的印象。"},{"en":"It is when you face difficulties that you can truly find out who your real friends are.","zh":"正是在你面对困难的时候，你才能真正发现谁是你真正的朋友。"}]},{"title":"让步状语从句 (Adverbial Clause of Concession)","definition":"用来表示让步关系，即从句所述内容与主句所述内容存在相反或相对的关系，翻译为“尽管，虽然，即使”","structure":"Although/Though + 从句, 主句；或 主句 + although/though + 从句","usage":"although和though意义和用法基本一致，都不能和but在同一个句子中连用，但可以和yet/still搭配；可放在句首或句中","examples":[{"en":"Today, although the old Galileo lives on in many popular writings, among historians of science a new and more sophisticated picture has emerged.","zh":"今天，虽然旧的伽利略形象仍存在于许多通俗作品中，但在科学史学家中，一个全新的、更复杂的人物形象已经出现。"},{"en":"Although he is very young, he has already won several international awards in the field of AI research.","zh":"尽管他很年轻，他已经在人工智能研究领域获得了多个国际奖项。"},{"en":"The project is very meaningful, although it will take us a lot of time and energy to complete.","zh":"这个项目很有意义，尽管完成它会耗费我们大量的时间和精力。"}]}],"patterns":[{"pattern":"In his own lifetime ... was the centre of violent controversy, but ... has long since settled, and today we can see ... in something like its proper perspective.","explanation":"","original":{"en":"In his own lifetime Galileo was the centre of violent controversy, but the scientific dust has long since settled, and today we can see even his famous clash with the Inquisition in something like its proper perspective.","zh":"在伽利略生前，他是激烈争议的中心，但科学界的尘埃早已落定，如今我们甚至可以相对客观地看待他与宗教裁判所的著名冲突。"},"examples":[{"en":"In his own lifetime Van Gogh was the centre of violent controversy, but the artistic dust has long since settled, and today we can see even his weird behavior in something like its proper perspective.","zh":"在梵高生前，他是激烈争议的中心，但艺术界的尘埃早已落定，如今我们甚至可以相对客观地看待他那些怪异的行为。"},{"en":"When the policy was first introduced, it was the centre of violent controversy, but the social dust has long since settled, and today we can see its long-term effects in something like its proper perspective.","zh":"这项政策刚推出时，是激烈争议的中心，但社会层面的尘埃早已落定，如今我们可以相对客观地看待它的长期影响。"}]},{"pattern":"Was ... more culpable than those who ... ?","explanation":"","original":{"en":"Was the philosopher who refused to look through Galileo's telescope more culpable than those who alleged that the spiral nebulae observed with Lord Rosse's great telescope in the 1840s were scratches left by the grinder?","zh":"难道拒绝透过伽利略望远镜观看的哲学家，比那些声称19世纪40年代用罗斯勋爵的大望远镜观测到的螺旋星云是磨镜工留下的划痕的人更应受到责备吗？"},"examples":[{"en":"Was the young man who refused to donate all his savings more culpable than those who force others to give money under the name of charity?","zh":"难道拒绝捐出全部积蓄的年轻人，比那些打着慈善名义强迫他人捐款的人更应受到责备吗？"},{"en":"Was the teacher who punished the naughty student more culpable than those who ignore students' bad behavior for fear of causing trouble?","zh":"难道惩罚淘气学生的老师，比那些怕惹麻烦而对学生不良行为视而不见的人更应受到责备吗？"}]},{"pattern":"We can perhaps forgive those who ... if we recall that ...","explanation":"","original":{"en":"We can perhaps forgive those who said the moons of Jupiter were produced by Galileo's spyglass if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth.","zh":"如果我们回忆起，在伽利略的时代，以及之前的几个世纪里，曲面玻璃是用来制造幻象而非真相的常用装置，我们或许可以原谅那些声称木星的卫星是伽利略的小望远镜造出来的人。"},"examples":[{"en":"We can perhaps forgive those who doubted the new technology if we recall that similar innovations had failed many times in the past and caused huge losses.","zh":"如果我们回忆起类似的创新过去曾多次失败并造成巨大损失，我们或许可以原谅那些质疑这项新技术的人。"},{"en":"We can perhaps forgive those who got angry in that situation if we recall that they had been waiting for three hours in the heavy rain without any notice.","zh":"如果我们回忆起他们在大雨里没有收到任何通知地等了三个小时，我们或许可以原谅那些在那种情况下生气的人。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“扭曲，歪曲” 对应的单词是？","hint":"verb · /dɪˈstɔːt/","options":["distort","resistance","tipster","specimen"],"answer":0,"explain":"distort · /dɪˈstɔːt/ · verb · 扭曲，歪曲。可指物体外形的扭曲变形，也可指对事实、观点、真相的歪曲篡改","source":{"kind":"vocab","word":"distort"},"id":"b4-u32-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：视角，观点；客观判断力","hint":"/pəˈspektɪv/ · noun","answer":"perspective","placeholder":"输入英文单词","explain":"perspective · /pəˈspektɪv/ · noun · 视角，观点；客观判断力。表示看待事物的角度，常用搭配in perspective表示“正确客观地看待”，in ... perspective表示“从…角度来看”","source":{"kind":"vocab","word":"perspective"},"id":"b4-u32-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The memory of that historic event will _____ for generations to come.","hint":"对那个历史事件的记忆将会代代传承下去。","answer":"live on","placeholder":"输入缺失的短语","explain":"live on：表示“继续存在，流传下去”，主语可以是人（表示靠…为生）或抽象事物（表示留存）（对那个历史事件的记忆将会代代传承下去。）","source":{"kind":"phrase","phrase":"live on"},"id":"b4-u32-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：At the same _____ our sympathy for Galileo's opponents has grown somewhat.","hint":"同时，我们对伽利略反对者的同情也有所增加。","answer":"time","placeholder":"输入缺失的单词","explain":"At the same time our sympathy for Galileo's opponents has grown somewhat. — 同时，我们对伽利略反对者的同情也有所增加。","source":{"kind":"sentence","en":"At the same time our sympathy for Galileo's opponents has grown somewhat."},"id":"b4-u32-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来表示让步关系，即从句所述内容与主句所述内容存在相反或相对的关系，翻译为“尽管，虽然，即使”” 描述的是哪个语法点？","hint":"Although/Though + 从句, 主句；或 主句 + although/though + 从句","options":["让步状语从句 (Adverbial Clause of Concession)","主语从句作主语的结构","where引导的地点状语从句引申用法","现在分词作结果状语"],"answer":0,"explain":"让步状语从句 (Adverbial Clause of Concession)：Although/Though + 从句, 主句；或 主句 + although/though + 从句：although和though意义和用法基本一致，都不能和but在同一个句子中连用，但可以和yet/still搭配；可放在句首或句中","source":{"kind":"grammar","title":"让步状语从句 (Adverbial Clause of Concession)"},"id":"b4-u32-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nif we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth;","hint":"","options":["知识的增长遵循了一种复利法则，","他们在那里搜罗了妇女、食物和饮料，安逸的生活使他们变得软弱。","如果我们回想起在他那个时代，就像几个世纪以前一样，曲面玻璃是制造幻觉、谎言而非真相的流行手段；","因为月球的质量只有地球的八十分之一，"],"answer":2,"explain":"if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth; — 如果我们回想起在他那个时代，就像几个世纪以前一样，曲面玻璃是制造幻觉、谎言而非真相的流行手段；","source":{"kind":"sentence","en":"if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth;"},"id":"b4-u32-q06"}]},{"id":"b4-u33","book":4,"unit":33,"key":"33","lessonFrom":33,"lessonTo":33,"title":"Education","titleZh":"教育","question":"Why is education democratic in bookless tribal societies?","sentences":[{"en":"Education is one of the key words of our time.","zh":"教育是我们这个时代的一个关键词。","t":18.65},{"en":"A man without an education, many of us believe,","zh":"许多人认为，一个没有受过教育的人","t":23.29},{"en":"is an unfortunate victim of adverse circumstances, deprived of one of the greatest twentieth-century opportunities.","zh":"是不幸境遇的受害者，被剥夺了20世纪最伟大的机会之一。","t":27.4},{"en":"Convinced of the importance of education, modern states 'invest' in institutions of learning to get back 'interest'","zh":"现代国家深信教育的重要性，因此“投资”于学习机构，以期“回报”","t":37.15},{"en":"in the form of a large group of enlightened young men and women who are potential leaders.","zh":"一大批开明的青年男女，他们是潜在的领导者。","t":46.84},{"en":"Education, with its cycles of instruction so carefully worked out,","zh":"教育，有着精心设计的教学周期，","t":53.93},{"en":"punctuated by textbooks--those purchasable wells of wisdom--what would civilization be like without its benefits?","zh":"以教科书——那些可以购买的智慧源泉——作为点缀，如果没有它的益处，文明会是什么样子？","t":59.35},{"en":"So much is certain: that we would have doctors and preachers,","zh":"有一点是肯定的：我们会有医生和传教士，","t":70.77},{"en":"lawyers and defendants marriages and births--but our spiritual outlook would be different.","zh":"律师和被告，婚姻和生育——但我们的精神观念会大相径庭。","t":76.51},{"en":"We would lay less stress on 'facts and figures' and more on a good memory,","zh":"我们会更少强调“事实和数据”，而更多地关注良好的记忆力，","t":85.07},{"en":"on applied psychology, and on the capacity of a man to get along with his fellow-citizens.","zh":"关注应用心理学，以及一个人与同胞和睦相处的能力。","t":91.53},{"en":"If our educational system were fashioned after its bookless past we would have the most democratic form of 'college' imaginable.","zh":"如果我们的教育体系仿效其没有书籍的过去，我们就会拥有 imaginable 最民主的“大学”形式。","t":99.04},{"en":"Among tribal people all knowledge inherited by tradition is shared by all;","zh":"在部落民族中，所有通过传统继承的知识都由所有人共享；","t":110.08},{"en":"it is taught to every member of the tribe so that in this respect everybody is equally equipped for life.","zh":"它被传授给部落的每一个成员，因此在这方面，每个人都同样具备了生活的能力。","t":116.92},{"en":"It is the ideal condition of the 'equal start' which only our most progressive forms of modern education try to regain.","zh":"这是“平等起步”的理想条件，只有我们最进步的现代教育形式才试图重新获得。","t":126.45},{"en":"In primitive cultures the obligation to seek and to receive the traditional instruction is binding to all.","zh":"在原始文化中，寻求和接受传统教育的义务对所有人都有约束力。","t":137},{"en":"There are no'illiterates' --if the term can be applied to peoples without a script--while our own compulsory school attendance became law in Germany in 1642,","zh":"没有“文盲”——如果这个词可以用来指没有文字的民族的话——而我们自己的义务入学制度于1642年在德国成为法律，","t":145.63},{"en":"in France in 1806, and in England in 1876 and is still nonexistent in a number of 'civilized' nations.","zh":"1806年在法国，1876年在英国，并且在一些“文明”国家仍然不存在。","t":159.77},{"en":"This shows how long it was before we deemed it necessary to make sure","zh":"这表明我们花了多长时间才认为有必要确保","t":171.14},{"en":"that all our children could share in the knowledge accumulated by the 'happy few' during the past centuries.","zh":"我们的所有孩子都能分享过去几个世纪由“少数幸运儿”积累的知识。","t":176.66},{"en":"Education in the wilderness is not a matter of monetary means.","zh":"荒野中的教育并非金钱问题。","t":187.21},{"en":"All are entitled to an equal start.","zh":"所有人都有权获得平等的起步。","t":192.73},{"en":"There is none of the hurry which, in our society, often hampers the full development of a growing personality.","zh":"那里没有我们社会中常常阻碍一个成长中的人格充分发展的匆忙。","t":196.37},{"en":"There, a child grows up under the everpresent attention of his parents;","zh":"在那里，孩子在父母无时无刻的关怀下成长；","t":206.13},{"en":"therefore the jungles and the savannahs know of no 'juvenile delinquency'.","zh":"因此，丛林和热带草原上没有“青少年犯罪”。","t":212.11},{"en":"No necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to 'buy' an education for his child.","zh":"没有离家谋生的必要导致儿童被忽视，也没有父亲面临无法为孩子“购买”教育的困境。","t":219.36}],"vocab":[{"word":"democratic","phonetic":"/ˌdeməˈkrætɪk/","meanings":[{"pos":"adjective","meaning":"民主的；平等的","usage":"描述体现人人平等、权利共享的制度或状态"}]},{"word":"adverse","phonetic":"/ˈædvɜːs/","meanings":[{"pos":"adjective","meaning":"不利的；有害的","usage":"通常修饰条件、环境等负面的客观因素"}]},{"word":"deprive","phonetic":"/dɪˈpraɪv/","meanings":[{"pos":"verb","meaning":"剥夺；使丧失","usage":"常用搭配deprive sb. of sth.，表示夺走某人本该拥有的事物"}]},{"word":"invest","phonetic":"/ɪnˈvest/","meanings":[{"pos":"verb","meaning":"投资；投入（时间、精力等）","usage":"可指资金投入，也可指抽象资源的投入，常用搭配invest in sth."}]},{"word":"enlightened","phonetic":"/ɪnˈlaɪtnd/","meanings":[{"pos":"adjective","meaning":"开明的；有见识的","usage":"修饰人或政策，指具备理性认知、思想进步的"}]},{"word":"punctuate","phonetic":"/ˈpʌŋktʃueɪt/","meanings":[{"pos":"verb","meaning":"不时打断；给…加标点","usage":"文中表示“穿插、点缀”，指某事物在过程中反复出现"}]},{"word":"defendant","phonetic":"/dɪˈfendənt/","meanings":[{"pos":"noun","meaning":"被告","usage":"法律术语，对应原告plaintiff"}]},{"word":"inherit","phonetic":"/ɪnˈherɪt/","meanings":[{"pos":"verb","meaning":"继承（财产、传统、特质等）","usage":"可指继承具体财物，也可指传承文化、特征等抽象事物"}]},{"word":"binding","phonetic":"/ˈbaɪndɪŋ/","meanings":[{"pos":"adjective","meaning":"有约束力的；必须遵守的","usage":"常修饰协议、义务等，常用搭配be binding on sb."}]},{"word":"illiterate","phonetic":"/ɪˈlɪtərət/","meanings":[{"pos":"noun/adjective","meaning":"文盲；不识字的","usage":"作名词指不识字的人，作形容词表示无读写能力的"}]},{"word":"compulsory","phonetic":"/kəmˈpʌlsəri/","meanings":[{"pos":"adjective","meaning":"强制的；义务的","usage":"常修饰教育、课程、规定等，指必须执行的"}]},{"word":"deem","phonetic":"/diːm/","meanings":[{"pos":"verb","meaning":"认为；视为","usage":"正式用语，相当于consider，常用结构deem it + adj. + to do sth."}]},{"word":"hamper","phonetic":"/ˈhæmpə(r)/","meanings":[{"pos":"verb","meaning":"妨碍；阻碍","usage":"指阻碍进程、活动或人的发展，语气比hinder稍强"}]},{"word":"juvenile","phonetic":"/ˈdʒuːvənaɪl/","meanings":[{"pos":"adjective","meaning":"青少年的；未成年的","usage":"用于修饰和未成年人相关的事物，正式用语"}]},{"word":"delinquency","phonetic":"/dɪˈlɪŋkwənsi/","meanings":[{"pos":"noun","meaning":"违法行为；少年犯罪","usage":"常和juvenile搭配，指未成年人的不良或犯罪行为"}]}],"phrases":[{"phrase":"deprive sb. of sth.","usage":"表示“剥夺某人的某物，使某人丧失某物”，是被动语境下的常用搭配","examples":[{"en":"The unfair law deprived many people of their right to vote.","zh":"这项不公平的法律剥夺了许多人的投票权。"},{"en":"Lack of sleep deprived him of the energy to finish the task.","zh":"睡眠不足让他丧失了完成任务的精力。"}]},{"phrase":"invest in","usage":"既可以指资金上投资某领域，也可以指投入时间、精力等资源到某事物中","examples":[{"en":"The government plans to invest more in renewable energy.","zh":"政府计划在可再生能源领域投入更多资金。"},{"en":"It is wise to invest in your own professional skills.","zh":"为自己的职业技能投入资源是很明智的。"}]},{"phrase":"lay stress on","usage":"表示“强调；重视”，等同于put emphasis on，用于说明关注的重点","examples":[{"en":"Many schools lay too much stress on exam results.","zh":"很多学校过分强调考试成绩。"},{"en":"The company lays stress on teamwork and innovation.","zh":"这家公司重视团队合作和创新。"}]},{"phrase":"be fashioned after","usage":"表示“仿照…制作；模仿…的模式”，指以某事物为范本设计","examples":[{"en":"The new library is fashioned after a famous ancient building.","zh":"这座新图书馆是仿照一座著名古建筑设计的。"},{"en":"Their education system is fashioned after the French model.","zh":"他们的教育体系是仿照法国模式建立的。"}]},{"phrase":"be binding to/on","usage":"表示“对…有约束力”，用于说明规则、义务的强制效力","examples":[{"en":"The contract is binding on all parties involved.","zh":"这份合同对所有相关方都有约束力。"},{"en":"This regulation is binding to every employee.","zh":"这项规定对所有员工都有效力。"}]},{"phrase":"be entitled to","usage":"表示“有权享有；有资格获得”，用于说明某人理应拥有某种权利或待遇","examples":[{"en":"All citizens are entitled to equal protection under the law.","zh":"所有公民都有权受到法律的平等保护。"},{"en":"You are entitled to a 10-day paid annual leave if you work here for one year.","zh":"如果你在这里工作满一年，就有权享受10天的带薪年假。"}]},{"phrase":"be confronted with","usage":"表示“面临；面对（困难、问题等）”，强调被动遇到棘手的状况","examples":[{"en":"When he graduated, he was confronted with a very competitive job market.","zh":"他毕业时面临着竞争非常激烈的就业市场。"},{"en":"Many small businesses are confronted with financial difficulties after the pandemic.","zh":"疫情过后很多小企业都面临着财务困境。"}]},{"phrase":"a matter of","usage":"表示“是…的问题；关乎…的事”，用于说明某事物的本质","examples":[{"en":"Success in this field is not just a matter of luck.","zh":"在这个领域取得成功不仅仅是运气的问题。"},{"en":"Protecting the environment is a matter of great importance for future generations.","zh":"保护环境对后代来说是至关重要的事。"}]}],"grammar":[{"title":"虚拟语气（与现在事实相反的情况）","definition":"用来描述和当下真实情况不符的假设，表达想象、愿望、建议等含义","structure":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","usage":"当假设的条件在当前现实中不成立时使用，体现非真实的推测","examples":[{"en":"If our educational system were fashioned after its bookless past we would have the most democratic form of 'college' imaginable.","zh":"如果我们的教育制度效仿没有书籍的古代模式，我们就会拥有能想象到的最民主的“大学”形式。"},{"en":"If I had more free time, I would learn to play the piano.","zh":"如果我有更多空闲时间，我会去学弹钢琴。"},{"en":"If there were no mobile phones, people would communicate more face to face.","zh":"如果没有手机，人们会更多地面对面交流。"}]},{"title":"插入语","definition":"嵌入句子中、不作句子主干成分，用于补充说明说话者的态度、解释背景等，删除后句子语法依然完整","structure":"常置于句子中间，用逗号和主干隔开，形式可以是短语、从句等","usage":"用来丰富信息，使表达更自然，体现说话者的补充观点","examples":[{"en":"A man without an education, many of us believe, is an unfortunate victim of adverse circumstances.","zh":"我们许多人都认为，没有受过教育的人是不利环境的不幸受害者。"},{"en":"The new policy, I think, will bring great benefits to local residents.","zh":"我认为这项新政策会给当地居民带来很大好处。"},{"en":"This movie, to be honest, is not as interesting as I expected.","zh":"说实话，这部电影没有我预期的那么有趣。"}]}],"patterns":[{"pattern":"Convinced of..., sb./sth. do sth. to...","explanation":"","original":{"en":"Convinced of the importance of education, modern states 'invest' in institutions of learning to get back 'interest' in the form of a large group of enlightened young men and women who are potential leaders.","zh":"现代国家深信教育的重要性，便向教育机构“投资”，以获得大批有知识的青年男女作为“利息”，这些人是未来的潜在领导者。"},"examples":[{"en":"Convinced of the importance of physical health, many young people choose to exercise 3 times a week to keep fit.","zh":"深信身体健康的重要性，很多年轻人选择每周锻炼三次来保持身材。"},{"en":"Convinced of the value of traditional culture, the local government organizes various cultural activities every year to promote inheritance of folk art.","zh":"深信传统文化的价值，当地政府每年都会组织各类文化活动来推动民间艺术的传承。"}]},{"pattern":"This shows how long it was before we deemed it necessary to do sth.","explanation":"","original":{"en":"This shows how long it was before we deemed it necessary to make sure that all our children could share in the knowledge accumulated by the 'happy few' during the past centuries.","zh":"这说明我们过了很久才意识到，有必要让所有儿童都能共享过去几个世纪里“少数幸运儿”积累起来的知识。"},"examples":[{"en":"This shows how long it was before we deemed it necessary to strictly limit plastic use to protect the ocean.","zh":"这说明我们过了很久才意识到，有必要严格限制塑料使用来保护海洋。"},{"en":"This shows how long it was before we deemed it necessary to provide mental health support for students in primary schools.","zh":"这说明我们过了很久才意识到，有必要为小学生提供心理健康支持。"}]},{"pattern":"No necessity of doing sth. results in..., and no sb. is confronted with...","explanation":"","original":{"en":"No necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to 'buy' an education for his child.","zh":"人们没有必要外出谋生，所以不会造成对孩子的忽视，也没有父亲会面临无力为孩子“购买”教育的困境。"},"examples":[{"en":"No necessity of working overtime results in more time for people to spend with their family, and no employee is confronted with the problem of work-life imbalance.","zh":"人们没有必要加班，所以有更多时间陪伴家人，也没有员工会面临工作与生活失衡的问题。"},{"en":"No necessity of worrying about food shortage results in a stable social environment, and no resident is confronted with the difficulty of affording basic food.","zh":"人们没有必要担心食物短缺，所以社会环境稳定，也没有居民会面临负担不起基本食物的困境。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“剥夺；使丧失” 对应的单词是？","hint":"verb · /dɪˈpraɪv/","options":["deprive","predominant","aberrant","mahout"],"answer":0,"explain":"deprive · /dɪˈpraɪv/ · verb · 剥夺；使丧失。常用搭配deprive sb. of sth.，表示夺走某人本该拥有的事物","source":{"kind":"vocab","word":"deprive"},"id":"b4-u33-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：妨碍；阻碍","hint":"/ˈhæmpə(r)/ · verb","answer":"hamper","placeholder":"输入英文单词","explain":"hamper · /ˈhæmpə(r)/ · verb · 妨碍；阻碍。指阻碍进程、活动或人的发展，语气比hinder稍强","source":{"kind":"vocab","word":"hamper"},"id":"b4-u33-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It is wise to _____ your own professional skills.","hint":"为自己的职业技能投入资源是很明智的。","answer":"invest in","placeholder":"输入缺失的短语","explain":"invest in：既可以指资金上投资某领域，也可以指投入时间、精力等资源到某事物中（为自己的职业技能投入资源是很明智的。）","source":{"kind":"phrase","phrase":"invest in"},"id":"b4-u33-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：A man without an _____ many of us believe,","hint":"许多人认为，一个没有受过教育的人","answer":"education","placeholder":"输入缺失的单词","explain":"A man without an education, many of us believe, — 许多人认为，一个没有受过教育的人","source":{"kind":"sentence","en":"A man without an education, many of us believe,"},"id":"b4-u33-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来描述和当下真实情况不符的假设，表达想象、愿望、建议等含义” 描述的是哪个语法点？","hint":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","options":["形容词/名词前置的倒装结构","让步状语从句：however引导的让步结构","虚拟语气（与现在事实相反的情况）","让步状语从句 (Adverbial Clause of Concession)"],"answer":2,"explain":"虚拟语气（与现在事实相反的情况）：If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形：当假设的条件在当前现实中不成立时使用，体现非真实的推测","source":{"kind":"grammar","title":"虚拟语气（与现在事实相反的情况）"},"id":"b4-u33-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nNo necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to 'buy' an education for his child.","hint":"","options":["所有人都有权获得平等的起步。","没有离家谋生的必要导致儿童被忽视，也没有父亲面临无法为孩子“购买”教育的困境。","他鄙视亚里士多德学派的偏见和书本知识，","巨型气垫船班轮可以横跨大西洋；"],"answer":1,"explain":"No necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to 'buy' an education for his child. — 没有离家谋生的必要导致儿童被忽视，也没有父亲面临无法为孩子“购买”教育的困境。","source":{"kind":"sentence","en":"No necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to 'buy' an education for his child."},"id":"b4-u33-q06"}]},{"id":"b4-u34","book":4,"unit":34,"key":"34","lessonFrom":34,"lessonTo":34,"title":"Adolescence","titleZh":"青春期","question":"What do adolescents respect in parents?","sentences":[{"en":"Parents are often upset when their children praise the homes of their friends and regard it as a slur on their own cooking, or cleaning, or furniture,","zh":"当孩子们赞美朋友家，并将其视为对自己烹饪、清洁或家具的诋毁时，父母常常感到不安，","t":16.18},{"en":"and often are foolish enough to let the adolescents see that they are annoyed.","zh":"并且常常愚蠢到让青少年看出他们很恼火。","t":26.68},{"en":"They may even accuse them of disloyalty, or make some spiteful remark about the friends' parents.","zh":"他们甚至可能指责孩子们不忠，或者对朋友的父母说些恶毒的话。","t":32.24},{"en":"Such a loss of dignity and descent into childish behaviour on the part of the adults deeply shocks the adolescents,","zh":"这种成年人丧失尊严、行为幼稚的举动深深地震惊了青少年，","t":39.58},{"en":"and makes them resolve that in future they will not talk to their parents about the places or people they visit.","zh":"并使他们决心将来不再和父母谈论他们去过的地方或见过的人。","t":48.13},{"en":"Before very long the parents will be complaining that the child is so secretive and never tells them anything,","zh":"不久之后，父母就会抱怨孩子如此守口如瓶，从不告诉他们任何事情，","t":55.96},{"en":"but they seldom realize that they have brought this on themselves.","zh":"但他们很少意识到这是他们自找的。","t":63.19},{"en":"Disillusionment with the parents,","zh":"对父母的幻灭，","t":68.63},{"en":"however good and adequate they may be both as parents and as individuals, is to some degree inevitable.","zh":"无论他们作为父母和个人有多么优秀和称职，在某种程度上都是不可避免的。","t":71.02},{"en":"Most children have such a high ideal of their parents,","zh":"大多数孩子对父母抱有如此高的期望，","t":80.05},{"en":"unless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation.","zh":"除非父母本身表现不尽人意，否则这种期望几乎不可能经受住现实的评估。","t":83.92},{"en":"Parents would be greatly surprised and deeply touched if they realized how much belief their children usually have in their character and infallibility,","zh":"如果父母意识到孩子们通常对他们的品格和不犯错抱有多大的信念，他们会大吃一惊并深受感动，","t":91.85},{"en":"and how much this faith means to a child.","zh":"以及这种信念对一个孩子意味着什么。","t":102.99},{"en":"If parents were prepared for this adolescent reaction,","zh":"如果父母对这种青春期反应有所准备，","t":106.55},{"en":"and realized that was a sign that the child was growing up","zh":"并且意识到这是孩子正在成长","t":110.44},{"en":"and developing valuable powers of observation and independent judgment,","zh":"并发展出宝贵的观察力和独立判断力的迹象，","t":114.22},{"en":"they would not be so hurt, and therefore would not drive the child into opposition by resenting and resisting it.","zh":"他们就不会那么受伤，因此也不会因为怨恨和抵制而把孩子推向对立面。","t":119.73},{"en":"The adolescent, with his passion for sincerity,","zh":"青少年，怀着对真诚的热情，","t":128.75},{"en":"always respects a parent who admits that he is wrong, or ignorant,","zh":"总是尊重承认自己错了、无知，","t":132.93},{"en":"or even that he has been unfair or unjust.","zh":"甚至不公平或不公正的父母。","t":137.85},{"en":"What the child cannot forgive is the parents' refusal to admit these charges if the child knows them to be true.","zh":"孩子不能原谅的是，如果孩子知道这些指控是真的，父母却拒绝承认。","t":141.39},{"en":"Victorian parents believed that they kept their dignity by retreating behind an unreasoning authoritarian attitude in fact they did nothing of the kind,","zh":"维多利亚时代的父母认为，通过退缩到一种不讲道理的专制态度背后，他们能保持自己的尊严，事实上他们根本没有这样做，","t":151.04},{"en":"but children were then too cowed to let them know how they really felt.","zh":"但那时的孩子过于害怕，不敢让他们知道自己真实感受。","t":161.84},{"en":"Today we tend to go to the other extreme,","zh":"今天我们倾向于走向另一个极端，","t":166.92},{"en":"but on the whole this is a healthier attitude both for the child and the parent.","zh":"但总的来说，这对孩子和父母都是一种更健康的态度。","t":170.3},{"en":"It is always wiser and safer to face up to reality, however painful it may be at the moment.","zh":"面对现实总是更明智和更安全的，无论当下它可能多么痛苦。","t":176.57}],"vocab":[{"word":"adolescence","phonetic":"/ˌædəˈlesns/","meanings":[{"pos":"noun","meaning":"青春期","usage":"指儿童到成年的过渡阶段，为不可数名词"}]},{"word":"adolescent","phonetic":"/ˌædəˈlesnt/","meanings":[{"pos":"noun","meaning":"青少年","usage":"指处于青春期的年轻人，可数名词"},{"pos":"adjective","meaning":"青春期的；青少年的","usage":"用于修饰和青少年、青春期相关的事物"}]},{"word":"slur","phonetic":"/slɜː(r)/","meanings":[{"pos":"noun","meaning":"诋毁，诽谤","usage":"指对他人名誉的侮辱性言论，常搭配介词on/against"}]},{"word":"spiteful","phonetic":"/ˈspaɪtfl/","meanings":[{"pos":"adjective","meaning":"恶意的，怀恨的","usage":"形容人或言行带有恶意、想要伤害他人的"}]},{"word":"dignity","phonetic":"/ˈdɪɡnəti/","meanings":[{"pos":"noun","meaning":"尊严，自尊","usage":"指人应有的受尊重的地位或自身的自尊感，不可数名词"}]},{"word":"descent","phonetic":"/dɪˈsent/","meanings":[{"pos":"noun","meaning":"堕落，沦落；下降","usage":"表示身份、行为水准的降低时，常搭配介词into"}]},{"word":"resolve","phonetic":"/rɪˈzɒlv/","meanings":[{"pos":"verb","meaning":"决定，下决心","usage":"正式用法，后常接不定式或that从句"}]},{"word":"disillusionment","phonetic":"/ˌdɪsɪˈluːʒnmənt/","meanings":[{"pos":"noun","meaning":"幻想破灭，醒悟","usage":"指理想或美好想象被打破的状态，不可数名词"}]},{"word":"inevitable","phonetic":"/ɪnˈevɪtəbl/","meanings":[{"pos":"adjective","meaning":"不可避免的，必然发生的","usage":"强调某事一定会发生，无法规避"}]},{"word":"infallibility","phonetic":"/ɪnˌfæləˈbɪləti/","meanings":[{"pos":"noun","meaning":"绝对正确，无谬误","usage":"指不会犯错的特性，反义词为fallibility"}]},{"word":"opposition","phonetic":"/ˌɒpəˈzɪʃn/","meanings":[{"pos":"noun","meaning":"反对，对立","usage":"表示处于敌对、相反的立场，常搭配介词to"}]},{"word":"sincerity","phonetic":"/sɪnˈserəti/","meanings":[{"pos":"noun","meaning":"真诚，诚意","usage":"指为人坦率、不虚伪的品质，不可数名词"}]},{"word":"cowed","phonetic":"/kaʊd/","meanings":[{"pos":"adjective","meaning":"被吓住的，胆怯的","usage":"由动词cow（恐吓，威胁）演变而来，形容人因害怕而顺从的状态"}]},{"word":"authoritarian","phonetic":"/ɔːˌθɒrəˈteəriən/","meanings":[{"pos":"adjective","meaning":"独裁的，专制的","usage":"形容要求绝对服从、不允许反对的态度或体制"}]},{"word":"resent","phonetic":"/rɪˈzent/","meanings":[{"pos":"verb","meaning":"怨恨，愤恨","usage":"指对不公平的事或人感到愤怒不满，后接名词/动名词"}]}],"phrases":[{"phrase":"regard ... as ...","usage":"表示“把……视作……”，用于表达对人或事物的看法，as后接名词、形容词等","examples":[{"en":"Parents regard their children's praise of friends' homes as a slur on their own housework.","zh":"父母把孩子夸赞朋友家视作对自己家务的诋毁。"},{"en":"He regards his tutor as the person who has influenced him most in his academic career.","zh":"他把自己的导师视作学术生涯中对他影响最大的人。"}]},{"phrase":"accuse sb of sth","usage":"表示“指责/控告某人做了某事”，of后接被指责的具体行为或罪名","examples":[{"en":"Parents may even accuse adolescents of disloyalty when they speak highly of their friends' families.","zh":"当青少年夸赞朋友的家庭时，父母甚至可能指责他们不孝顺。"},{"en":"The employee was accused of leaking the company's confidential information to competitors.","zh":"这名员工被指控向竞争对手泄露公司机密信息。"}]},{"phrase":"bring sth on oneself","usage":"表示“自作自受，自己造成（不好的结果）”，强调不良后果是自身行为导致的","examples":[{"en":"Parents seldom realize that their children's secretiveness is something they have brought on themselves.","zh":"父母很少意识到孩子的沉默寡言是他们自己造成的。"},{"en":"Don't complain about the punishment - you brought it on yourself by cheating in the exam.","zh":"别抱怨惩罚了——你考试作弊，这是自作自受。"}]},{"phrase":"stand up to","usage":"表示“经得起，承受住；勇敢对抗”，文中取“经得起”的含义","examples":[{"en":"Children's high ideal of their parents can hardly stand up to a realistic evaluation.","zh":"孩子对父母的崇高想象几乎经不住现实的考量。"},{"en":"This kind of waterproof fabric can stand up to the heaviest rainstorm.","zh":"这种防水面料可以经受住最大的暴雨。"}]},{"phrase":"drive sb into opposition","usage":"表示“把某人推向对立面，使某人持反对态度”，强调行为导致对方产生对立情绪","examples":[{"en":"Parents who resent their children's adolescent reaction will drive the child into opposition.","zh":"抵触孩子青春期反应的父母会把孩子推向自己的对立面。"},{"en":"The manager's unreasonable demands drove most of the team into opposition.","zh":"经理不合理的要求让团队大部分人都产生了对立情绪。"}]},{"phrase":"face up to","usage":"表示“勇敢面对，正视”，用于指不逃避困难、现实等","examples":[{"en":"It is always wiser to face up to reality however painful it may be.","zh":"不管当下有多痛苦，正视现实永远是更明智的选择。"},{"en":"You need to face up to the fact that you failed this time and learn from the experience.","zh":"你需要正视这次失败的事实，并从中吸取经验。"}]},{"phrase":"to some degree","usage":"表示“在某种程度上”，用于弱化观点的绝对性，说明情况有一定的合理性","examples":[{"en":"Disillusionment with parents is to some degree inevitable for most adolescents.","zh":"对大多数青少年来说，对父母的幻想破灭在某种程度上是不可避免的。"},{"en":"To some degree, the success of the project depends on the support of local residents.","zh":"在某种程度上，这个项目的成功取决于当地居民的支持。"}]},{"phrase":"on the whole","usage":"表示“总体来说，大体上”，用于总结整体情况，忽略个别例外","examples":[{"en":"Today's more open attitude between parents and children is on the whole healthier.","zh":"如今父母和孩子之间更开放的相处态度总体来说更健康。"},{"en":"On the whole, the performance of the new device meets our expectations.","zh":"总体来说，这个新设备的表现符合我们的预期。"}]}],"grammar":[{"title":"虚拟语气（与现在事实相反的非真实条件句）","definition":"用来描述和现在实际情况不符的假设，或者发生可能性极低的情况，表达愿望、假设、遗憾等情绪","structure":"If + 主语 + 动词过去式（be动词用were），主语 + would/could/should/might + 动词原形","usage":"当从句的假设和现在的真实情况相反时，使用该结构，体现假设的非真实性","examples":[{"en":"If parents were prepared for this adolescent reaction, they would not be so hurt.","zh":"如果父母对青少年的这种反应有所准备，他们就不会这么受伤了。"},{"en":"If I had more spare time, I would learn to play the guitar.","zh":"如果我有更多空闲时间，我会去学弹吉他。"}]},{"title":"让步状语从句（however引导）","definition":"用来引导让步关系，表达“无论多么……，不管……”的含义，说明即使存在从句描述的情况，主句的内容依然成立","structure":"however + 形容词/副词 + 主语 + 谓语，主句","usage":"用于加强语气，强调不管程度如何，主句的结果都不会改变","examples":[{"en":"However good and adequate parents may be both as parents and as individuals, disillusionment with them is to some degree inevitable.","zh":"无论父母作为家长和个人有多么优秀称职，孩子对他们的幻想破灭在某种程度上都是不可避免的。"},{"en":"However difficult the task is, we will try our best to finish it on time.","zh":"不管这个任务有多难，我们都会尽全力按时完成。"}]},{"title":"such...that...结果状语从句","definition":"用来引导结果状语从句，表示“如此……以至于……”，强调程度带来的结果","structure":"such + (a/an) + 形容词 + 可数名词单数/不可数名词/可数名词复数 + that + 结果从句","usage":"such修饰名词，当名词前有many/much/few/little等词修饰时，用so而不用such","examples":[{"en":"Most children have such a high ideal of their parents that it can hardly hope to stand up to a realistic evaluation.","zh":"大多数孩子对父母抱有极高的理想化想象，以至于这种想象几乎经不住现实的考量。"},{"en":"It was such a boring lecture that many audience members left halfway.","zh":"这场讲座太无聊了，很多听众中途就离开了。"}]}],"patterns":[{"pattern":"Sb would be greatly surprised and deeply touched if they realized how much + 名词 + ...","explanation":"","original":{"en":"Parents would be greatly surprised and deeply touched if they realized how much belief their children usually have in their character and infallibility, and how much this faith means to a child.","zh":"如果父母意识到孩子通常多么相信他们的品行和绝对正确，以及这种信任对孩子有多重要，他们会非常震惊，而且深深被打动。"},"examples":[{"en":"Teachers would be greatly surprised and deeply touched if they realized how much influence their words have on their students' growth, and how much a small encouragement means to a child who lacks confidence.","zh":"如果老师意识到他们的话对学生的成长有多大影响，以及一句小小的鼓励对一个缺乏自信的孩子有多重要，他们会非常震惊，而且深深被打动。"},{"en":"Volunteers would be greatly surprised and deeply touched if they realized how much difference their small efforts make to the lives of people in remote areas, and how much their kindness is cherished by the local residents.","zh":"如果志愿者意识到他们小小的努力对偏远地区人们的生活有多大影响，以及他们的善意被当地居民多么珍视，他们会非常震惊，而且深深被打动。"}]},{"pattern":"What sb cannot forgive is + 名词/从句","explanation":"","original":{"en":"What the child cannot forgive is the parents' refusal to admit these charges if the child knows them to be true.","zh":"孩子所不能原谅的是，父母在孩子知道这些指责属实的情况下拒不承认。"},"examples":[{"en":"What the employees cannot forgive is the company's decision to cut salaries without any prior notice and reasonable explanation.","zh":"员工们不能原谅的是，公司没有任何提前通知和合理解释就降薪的决定。"},{"en":"What the public cannot forgive is that the celebrity lied about his illegal behavior and tried to shift the blame to others.","zh":"公众不能原谅的是，这位明星对自己的违法行为撒谎，还试图把责任推给别人。"}]},{"pattern":"Sb believed that they ... by doing sth; in fact they did nothing of the kind, but ...","explanation":"","original":{"en":"Victorian parents believed that they kept their dignity by retreating behind an unreasoning authoritarian attitude; in fact they did nothing of the kind, but children were then too cowed to let them know how they really felt.","zh":"维多利亚时代的父母认为，他们靠无理的权威姿态来维持自己的尊严；实际上他们根本没能维持尊严，只是当时的孩子太害怕，不敢让父母知道自己的真实想法。"},"examples":[{"en":"Many traditional teachers believed that they maintained classroom order by being strict and forbidding students to express different opinions; in fact they did nothing of the kind, but students were just too afraid to voice their dissatisfaction openly.","zh":"很多传统教师认为，他们靠严格、禁止学生表达不同观点来维持课堂秩序；实际上他们根本没能维持秩序，只是学生太害怕，不敢公开表达不满罢了。"},{"en":"Some managers believe that they improve the team's work efficiency by putting extra pressure on employees; in fact they do nothing of the kind, but staff just choose to pretend to be busy to avoid criticism.","zh":"一些管理者认为，他们靠给员工施加额外压力来提升团队工作效率；实际上他们根本没能提升效率，只是员工为了避免被批评，选择假装忙碌罢了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“恶意的，怀恨的” 对应的单词是？","hint":"adjective · /ˈspaɪtfl/","options":["spiteful","odd","safe","herd"],"answer":0,"explain":"spiteful · /ˈspaɪtfl/ · adjective · 恶意的，怀恨的。形容人或言行带有恶意、想要伤害他人的","source":{"kind":"vocab","word":"spiteful"},"id":"b4-u34-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：绝对正确，无谬误","hint":"/ɪnˌfæləˈbɪləti/ · noun","answer":"infallibility","placeholder":"输入英文单词","explain":"infallibility · /ɪnˌfæləˈbɪləti/ · noun · 绝对正确，无谬误。指不会犯错的特性，反义词为fallibility","source":{"kind":"vocab","word":"infallibility"},"id":"b4-u34-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, the performance of the new device meets our expectations.","hint":"总体来说，这个新设备的表现符合我们的预期。","answer":"on the whole","placeholder":"输入缺失的短语","explain":"on the whole：表示“总体来说，大体上”，用于总结整体情况，忽略个别例外（总体来说，这个新设备的表现符合我们的预期。）","source":{"kind":"phrase","phrase":"on the whole"},"id":"b4-u34-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：and _____ valuable powers of observation and independent judgment,","hint":"并发展出宝贵的观察力和独立判断力的迹象，","answer":"developing","placeholder":"输入缺失的单词","explain":"and developing valuable powers of observation and independent judgment, — 并发展出宝贵的观察力和独立判断力的迹象，","source":{"kind":"sentence","en":"and developing valuable powers of observation and independent judgment,"},"id":"b4-u34-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来引导让步关系，表达“无论多么……，不管……”的含义，说明即使存在从句描述的情况，主句的内容依然成立” 描述的是哪个语法点？","hint":"however + 形容词/副词 + 主语 + 谓语，主句","options":["让步状语从句（however引导）","not...but...并列结构","as引导的非限制性定语从句","It is + 形容词 + that从句/不定式结构"],"answer":0,"explain":"让步状语从句（however引导）：however + 形容词/副词 + 主语 + 谓语，主句：用于加强语气，强调不管程度如何，主句的结果都不会改变","source":{"kind":"grammar","title":"让步状语从句（however引导）"},"id":"b4-u34-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nunless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation.","hint":"","options":["它的习惯是他的习惯，它的信仰是他的信仰，它的不可能之事是他的不可能之事。","除非父母本身表现不尽人意，否则这种期望几乎不可能经受住现实的评估。","许多工业界和服务行业的人，","她视力正常，但也同样能用皮肤的不同部位感知事物，并能看穿厚实的墙壁。"],"answer":1,"explain":"unless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation. — 除非父母本身表现不尽人意，否则这种期望几乎不可能经受住现实的评估。","source":{"kind":"sentence","en":"unless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation."},"id":"b4-u34-q06"}]},{"id":"b4-u35","book":4,"unit":35,"key":"35","lessonFrom":35,"lessonTo":35,"title":"Space Odyssey","titleZh":"太空漫游","question":"When will it be possible for us to think seriously about colonising Mars?","sentences":[{"en":"The Moon is likely to become the industrial hub of the Solar System supplying the rocket fuels for its ships,","zh":"月球很可能成为太阳系的工业中心，为其飞船提供火箭燃料，","t":19.13},{"en":"easily obtainable from the lunar rocks in the form of liquid oxygen.","zh":"这些燃料以液氧的形式，可轻易地从月球岩石中获得。","t":27.37},{"en":"The reason lies in its gravity.","zh":"原因在于它的重力。","t":33.54},{"en":"Because the Moon has only an eightieth of the Earth's mass,","zh":"因为月球的质量只有地球的八十分之一，","t":36.79},{"en":"it requires 97% less energy","zh":"它所需的能量要少97%，","t":41.43},{"en":"to travel the quarter of a million miles from the Moon to Earth-orbit than the 200 mile-journey from Earth's surface into orbit!","zh":"即使是从月球到地球轨道25万英里的旅程，也比从地球表面进入轨道200英里的旅程所需的能量少得多！","t":46.02},{"en":"This may sound fantastic, but it is easily calculated.","zh":"这听起来可能很不可思议，但它很容易计算出来。","t":57.44},{"en":"To escape from the Earth in a rocket, one must travel at seven miles per second.","zh":"要乘坐火箭逃离地球，必须以每秒7英里的速度飞行。","t":63.17},{"en":"The comparable speed from the Moon is only 1.5 miles per second.","zh":"而从月球逃离的可比速度仅为每秒1.5英里。","t":70.27},{"en":"Because the gravity on the Moon's surface is only a sixth of Earth's (remember how easily the Apollo astronauts bounded along),","zh":"因为月球表面的重力只有地球的六分之一（还记得阿波罗宇航员在月球上跳跃得多轻松吗？），","t":77.34},{"en":"it takes much less energy to accelerate to that 1.5mps than it does on Earth.","zh":"因此，在月球上加速到每秒1.5英里所需的能量比在地球上少得多。","t":87.97},{"en":"Moon dwellers will be able to fly in space at only three percent of the cost of similar journeys by their terrestrial cousins.","zh":"月球居民将能够以其地球表亲进行类似旅程所需成本的3%在太空中飞行。","t":96.6},{"en":"Arthur C. Clark once suggested a revolutionary idea passes through three phases:","zh":"亚瑟·C·克拉克曾提出，一个革命性的想法会经历三个阶段：","t":107.18},{"en":"1. 'It's impossible--don't waste my time.'","zh":"1. “这不可能——别浪费我的时间。”","t":115.37},{"en":"2. 'It's possible, but not worth doing.'","zh":"2. “这有可能，但不值得做。”","t":121.45},{"en":"3. 'I said it was a good idea all along.'","zh":"3. “我一直都说这是个好主意。”","t":127.21},{"en":"The idea of colonising Mars--a world 160 times more distant than the Moon--will move decisively from the second phase to the third,","zh":"殖民火星——一个比月球远160倍的世界——的设想，将决定性地从第二阶段迈向第三阶段，","t":132.06},{"en":"when a significant number of people are living permanently in space.","zh":"那将是当大量人口永久居住在太空中的时候。","t":145.21},{"en":"Mars has an extraordinary fascination for would-be voyagers.","zh":"火星对未来的航海家们有着非凡的吸引力。","t":150.48},{"en":"America, Russia and Europe are filled with enthusiasts--many of them serious and senior scientists who dream of sending people to it.","zh":"美国、俄罗斯和欧洲都充满了热情的人士——其中许多是认真而资深的科学家，他们梦想着将人类送上火星。","t":155.77},{"en":"Their aim is understandable.","zh":"他们的目标是可以理解的。","t":168.64},{"en":"It is the one world in the Solar System that is most like the Earth.","zh":"它是太阳系中与地球最相似的星球。","t":171.22},{"en":"It is a world of red sandy deserts (hence its name--the Red Planet),","zh":"这是一个红色的沙质沙漠世界（因此得名——红色星球），","t":176.19},{"en":"cloudless skies, savage sandstorms, chasms wider than the Grand Canyon and at least one mountain more than twice as tall as Everest.","zh":"有着无云的天空、狂暴的沙尘暴、比大峡谷还宽的裂谷，以及至少一座比珠穆朗玛峰高两倍多的山峰。","t":182.61},{"en":"It seems ideal for settlement.","zh":"它似乎非常适合居住。","t":194.93}],"vocab":[{"word":"colonise","phonetic":"/ˈkɒlənaɪz/","meanings":[{"pos":"verb","meaning":"在……建立殖民地；（大批）移居，殖民","usage":"可指人类向其他星球或未开发地区移民定居，也可指生物在新地区生长繁殖"}]},{"word":"hub","phonetic":"/hʌb/","meanings":[{"pos":"noun","meaning":"（活动、兴趣等的）中心，枢纽","usage":"常用来指交通、产业、文化等的核心区域，常见搭配：industrial hub 工业中心，transport hub 交通枢纽"}]},{"word":"lunar","phonetic":"/ˈluːnə(r)/","meanings":[{"pos":"adjective","meaning":"月球的，月亮的","usage":"仅用于名词前，常见搭配：lunar rock 月球岩石，lunar eclipse 月食，lunar calendar 农历"}]},{"word":"gravity","phonetic":"/ˈɡrævəti/","meanings":[{"pos":"noun","meaning":"重力，引力；严重性","usage":"表示物理意义上的引力时为不可数名词；表示“严重性”时也为不可数名词，如：the gravity of the situation 局势的严重性"}]},{"word":"accelerate","phonetic":"/əkˈseləreɪt/","meanings":[{"pos":"verb","meaning":"（使）加速，加快；促进","usage":"可作及物或不及物动词，既可以指物理速度的提升，也可以指进程、节奏的加快"}]},{"word":"dweller","phonetic":"/ˈdwelə(r)/","meanings":[{"pos":"noun","meaning":"居民，居住者","usage":"通常与表示地点的名词搭配使用，如：city dweller 城市居民，moon dweller 月球居民"}]},{"word":"terrestrial","phonetic":"/təˈrestriəl/","meanings":[{"pos":"adjective","meaning":"地球的，陆地的；陆生的","usage":"正式用词，常用来与太空、海洋等概念相对，如：terrestrial life 地球生物，terrestrial ecosystem 陆地生态系统"}]},{"word":"revolutionary","phonetic":"/ˌrevəˈluːʃənəri/","meanings":[{"pos":"adjective","meaning":"革命性的，创新的，突破性的","usage":"用来形容观点、发明、技术等具有颠覆性的重大突破，可修饰抽象或具体名词"}]},{"word":"phase","phonetic":"/feɪz/","meanings":[{"pos":"noun","meaning":"阶段，时期","usage":"指事物发展过程中的特定阶段，常见搭配：phase of development 发展阶段，enter a new phase 进入新阶段"}]},{"word":"permanently","phonetic":"/ˈpɜːmənəntli/","meanings":[{"pos":"adverb","meaning":"永久地，长期地","usage":"修饰动词，表示动作或状态是持续不变的，反义词为temporarily"}]},{"word":"voyager","phonetic":"/ˈvɔɪɪdʒə(r)/","meanings":[{"pos":"noun","meaning":"航行者，旅行者，航天旅行者","usage":"指进行长途旅行，尤其是航海或太空旅行的人"}]},{"word":"enthusiast","phonetic":"/ɪnˈθjuːziæst/","meanings":[{"pos":"noun","meaning":"热衷于……的人，爱好者","usage":"常与表示领域的名词搭配，如：space enthusiast 太空爱好者，sports enthusiast 体育爱好者"}]},{"word":"savage","phonetic":"/ˈsævɪdʒ/","meanings":[{"pos":"adjective","meaning":"猛烈的，恶劣的；野蛮的","usage":"形容自然现象时表示“非常恶劣的、极具破坏性的”，形容人或行为时表示“野蛮的、残暴的”"}]},{"word":"chasm","phonetic":"/ˈkæzəm/","meanings":[{"pos":"noun","meaning":"裂缝，峡谷；鸿沟，巨大分歧","usage":"既可指地表巨大的裂缝，也可比喻观点、利益等方面的巨大差异，如：a chasm between two sides 双方的巨大分歧"}]},{"word":"settlement","phonetic":"/ˈsetlmənt/","meanings":[{"pos":"noun","meaning":"定居点，聚居地；解决，处理","usage":"表示“定居点”时为可数名词；表示“（问题、争端的）解决”时为不可数名词，如：peace settlement 和平解决"}]}],"phrases":[{"phrase":"in the form of","usage":"表示“以……的形式”，用于说明事物呈现的具体形态","examples":[{"en":"The rocket fuel is easily obtainable from the lunar rocks in the form of liquid oxygen.","zh":"火箭燃料很容易从月球岩石中以液态氧的形式获取。"},{"en":"The company will provide help in the form of financial support.","zh":"该公司将以资金支持的形式提供帮助。"}]},{"phrase":"lie in","usage":"表示“在于，存在于”，用于说明原因、问题、优势等的所在，主语通常为抽象名词","examples":[{"en":"The reason lies in its gravity.","zh":"原因在于它的引力。"},{"en":"The key to solving the problem lies in sufficient communication.","zh":"解决这个问题的关键在于充分的沟通。"}]},{"phrase":"accelerate to","usage":"表示“加速到……（速度）”，后面接具体的速度数值或目标速度","examples":[{"en":"It takes much less energy to accelerate to that 1.5mps than it does on Earth.","zh":"加速到每秒1.5英里所需的能量比在地球上少得多。"},{"en":"The train accelerated to 300 kilometers per hour within five minutes.","zh":"火车在五分钟内加速到了每小时300公里。"}]},{"phrase":"pass through","usage":"表示“经历，经过；穿过”，可指经历某个阶段、过程，也可指从某个空间穿过","examples":[{"en":"Arthur C.Clark once suggested a revolutionary idea passes through three phases.","zh":"阿瑟·C·克拉克曾提出，一个革命性的想法要经历三个阶段。"},{"en":"You need to pass through three security checks before boarding the plane.","zh":"登机前你需要经过三次安检。"}]},{"phrase":"have a fascination for","usage":"表示“对……有极大的吸引力，使……着迷”，主语通常是具有吸引力的事物，宾语是被吸引的人","examples":[{"en":"Mars has an extraordinary fascination for would-be voyagers.","zh":"火星对想要成为太空旅行者的人有着非凡的吸引力。"},{"en":"Ancient history has a special fascination for this young scholar.","zh":"古代史对这位年轻学者有着特殊的吸引力。"}]},{"phrase":"dream of","usage":"表示“梦想，渴望”，后面接名词或动名词，指向往某个还未实现的目标","examples":[{"en":"Many senior scientists dream of sending people to Mars.","zh":"许多资深科学家梦想着把人类送上火星。"},{"en":"She dreamed of becoming a professional dancer when she was a child.","zh":"她小时候梦想成为一名专业舞者。"}]},{"phrase":"would-be","usage":"作为形容词表示“想要成为的，未来可能的”，放在名词前修饰想要成为某类人或想要实现某件事的对象","examples":[{"en":"Mars has an extraordinary fascination for would-be voyagers.","zh":"火星对想要成为太空旅行者的人有着非凡的吸引力。"},{"en":"The college offers special training courses for would-be teachers.","zh":"这所学院为想要成为教师的人提供特殊培训课程。"}]}],"grammar":[{"title":"比较状语从句 (Comparative Adverbial Clause)","definition":"用于两者之间进行比较，说明人或事物的属性、程度等方面的差异，常由than引导","structure":"主语 + 谓语 + 形容词/副词比较级 + than + 比较对象 + （谓语部分，常可省略与主句相同的内容）","usage":"用于两者比较，若比较的是两个句子结构，从句中与主句相同的部分可以省略，避免重复；也可用于数量、程度的比较","examples":[{"en":"It requires 97% less energy to travel the quarter of a million miles from the Moon to Earth-orbit than the 200 mile-journey from Earth's surface into orbit!","zh":"从月球到地球轨道25万英里的旅程，比从地球表面进入轨道200英里的旅程所需的能量少97%！"},{"en":"It takes much less time to go there by high-speed train than by bus.","zh":"坐高铁去那里比坐公共汽车花费的时间少得多。"}]},{"title":"原因状语从句 (Adverbial Clause of Cause)","definition":"用来解释主句动作发生的原因，常用引导词有because, since, as, for等","structure":"Because/Since/As + 原因状语从句, 主句 / 主句 + because + 原因状语从句","usage":"because引导的从句表示直接的、明确的原因，语气最强，可用来回答why的提问，位置可在主句前或后；当原因是已知的、显而易见的，常用since或as，语气较弱，常放在句首","examples":[{"en":"Because the gravity on the Moon's surface is only a sixth of Earth's, it takes much less energy to accelerate to that 1.5mps than it does on Earth.","zh":"因为月球表面的引力只有地球的六分之一，所以加速到每秒1.5英里所需的能量比在地球上少得多。"},{"en":"Because it was raining heavily, we had to put off the outdoor sports meeting.","zh":"因为雨下得很大，我们不得不推迟户外运动会。"}]},{"title":"时间状语从句 (Adverbial Clause of Time)","definition":"用来表示主句动作发生的时间，常用引导词有when, while, as, before, after, until等","structure":"When/While + 时间状语从句, 主句 / 主句 + when + 时间状语从句","usage":"when引导的从句中动词既可以是延续性动词也可以是非延续性动词，可表示从句动作和主句动作同时发生，或从句动作先于主句动作发生；当主句为将来时态时，从句常用一般现在时表将来","examples":[{"en":"The idea of colonising Mars will move decisively from the second phase to the third, when a significant number of people are living permanently in space.","zh":"当有大量人口永久在太空居住时，殖民火星的想法就会果断地从第二阶段进入第三阶段。"},{"en":"I will call you when I arrive at the hotel.","zh":"我到酒店的时候会给你打电话。"}]}],"patterns":[{"pattern":"It is + possible/important/difficult + for sb. to do sth.","explanation":"","original":{"en":"When will it be possible for us to think seriously about colonising Mars?","zh":"我们什么时候才有可能认真考虑殖民火星？"},"examples":[{"en":"It is important for students to develop a good learning habit.","zh":"对学生来说养成良好的学习习惯很重要。"},{"en":"It is very difficult for beginners to speak English fluently in a short time.","zh":"对初学者来说短时间内流利说英语很难。"}]},{"pattern":"Sb. once suggested (that) + 从句","explanation":"","original":{"en":"Arthur C.Clark once suggested a revolutionary idea passes through three phases.","zh":"阿瑟·C·克拉克曾提出，一个革命性的想法要经历三个阶段。"},"examples":[{"en":"The educator once suggested that children should be given more time to develop their hobbies.","zh":"这位教育家曾提出，应该给孩子更多时间发展他们的爱好。"},{"en":"He once suggested that we should adjust our plan according to the new situation.","zh":"他曾建议我们应该根据新情况调整计划。"}]},{"pattern":"It is the one + 名词 + that is most like + 比较对象","explanation":"","original":{"en":"It is the one world in the Solar System that is most like the Earth.","zh":"它是太阳系中最像地球的行星。"},"examples":[{"en":"This is the one novel that is most like the author's real life experience.","zh":"这是最像作者真实生活经历的一部小说。"},{"en":"It is the one city in the country that is most like my hometown.","zh":"这是这个国家里最像我家乡的一座城市。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“阶段，时期” 对应的单词是？","hint":"noun · /feɪz/","options":["chasm","dictate","phase","undue"],"answer":2,"explain":"phase · /feɪz/ · noun · 阶段，时期。指事物发展过程中的特定阶段，常见搭配：phase of development 发展阶段，enter a new phase 进入新阶段","source":{"kind":"vocab","word":"phase"},"id":"b4-u35-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：定居点，聚居地；解决，处理","hint":"/ˈsetlmənt/ · noun","answer":"settlement","placeholder":"输入英文单词","explain":"settlement · /ˈsetlmənt/ · noun · 定居点，聚居地；解决，处理。表示“定居点”时为可数名词；表示“（问题、争端的）解决”时为不可数名词，如：peace settlement 和平解决","source":{"kind":"vocab","word":"settlement"},"id":"b4-u35-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It takes much less energy to _____ that 1.5mps than it does on Earth.","hint":"加速到每秒1.5英里所需的能量比在地球上少得多。","answer":"accelerate to","placeholder":"输入缺失的短语","explain":"accelerate to：表示“加速到……（速度）”，后面接具体的速度数值或目标速度（加速到每秒1.5英里所需的能量比在地球上少得多。）","source":{"kind":"phrase","phrase":"accelerate to"},"id":"b4-u35-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Because the gravity on the _____ surface is only a sixth of Earth's (remember how easily the Apollo astronauts bounded along),","hint":"因为月球表面的重力只有地球的六分之一（还记得阿波罗宇航员在月球上跳跃得多轻松吗？），","answer":"Moon's","placeholder":"输入缺失的单词","explain":"Because the gravity on the Moon's surface is only a sixth of Earth's (remember how easily the Apollo astronauts bounded along), — 因为月球表面的重力只有地球的六分之一（还记得阿波罗宇航员在月球上跳跃得多轻松吗？），","source":{"kind":"sentence","en":"Because the gravity on the Moon's surface is only a sixth of Earth's (remember how easily the Apollo astronauts bounded along),"},"id":"b4-u35-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于两者之间进行比较，说明人或事物的属性、程度等方面的差异，常由than引导” 描述的是哪个语法点？","hint":"主语 + 谓语 + 形容词/副词比较级 + than + 比较对象 + （谓语部分，常可省略与主句相同的内容）","options":["比较状语从句 (Comparative Adverbial Clause)","同级比较的否定结构","as引导的非限制性定语从句","granted作引导词的让步状语结构"],"answer":0,"explain":"比较状语从句 (Comparative Adverbial Clause)：主语 + 谓语 + 形容词/副词比较级 + than + 比较对象 + （谓语部分，常可省略与主句相同的内容）：用于两者比较，若比较的是两个句子结构，从句中与主句相同的部分可以省略，避免重复；也可用于数量、程度的比较","source":{"kind":"grammar","title":"比较状语从句 (Comparative Adverbial Clause)"},"id":"b4-u35-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\n3. 'I said it was a good idea all along.'","hint":"","options":["只要任何一项调查是秘密的，","波谷（最低点），波高（从波谷到波峰的垂直距离），","他立刻注意到纪律松懈：丹麦人有征服者的自信，他们的安全防范措施很随意。","3. “我一直都说这是个好主意。”"],"answer":3,"explain":"3. 'I said it was a good idea all along.' — 3. “我一直都说这是个好主意。”","source":{"kind":"sentence","en":"3. 'I said it was a good idea all along.'"},"id":"b4-u35-q06"}]},{"id":"b4-u36","book":4,"unit":36,"key":"36","lessonFrom":36,"lessonTo":36,"title":"The Cost of Government","titleZh":"政府的开支","question":"What's the most important factor, both in government or business, for keeping running costs low?","sentences":[{"en":"If a nation is essentialy disunited, it is left to the government to hold it together.","zh":"如果一个国家本质上是分裂的，就只能由政府来维系它的统一。","t":21.57},{"en":"This increases the expense of government, and reduces correspondingly the amount of economic resources that could be used for developing the country.","zh":"这增加了政府开支，并相应减少了可用于国家发展的经济资源。","t":27.97},{"en":"And it should not be forgotten how small those resources are in a poor and backward country.","zh":"而且不应忘记，在一个贫穷落后的国家，这些资源是多么微薄。","t":39.42},{"en":"Where the cost of government is high, resources for development are correspondingly low.","zh":"政府开支高的地方，发展资源也相应地少。","t":45.74},{"en":"This may be illustrated by comparing the position of a nation with that of a private business enterprise.","zh":"这可以通过比较一个国家与一个私营企业的情况来说明。","t":52.66},{"en":"An enterprise has to incur certain costs and expenses in order to stay in business.","zh":"一个企业为了维持经营，必须承担一定的成本和开支。","t":59.84},{"en":"For our purposes, we are concerned only with one kind of cost--the cost of managing and administering the business.","zh":"就我们的目的而言，我们只关注一种成本——管理和经营企业的成本。","t":66.88},{"en":"Such administrative overheads in a business are analogous to the cost of government in a nation.","zh":"企业中的此类行政管理费用类似于一个国家中的政府开支。","t":75.36},{"en":"The administrative overheads of a business are low to the extent that everyone working in the business","zh":"企业的行政管理费用之所以低，是因为企业中的每个人","t":82.53},{"en":"can be trusted to behave in a way that best promotes the interests of the firm.","zh":"都可以被信任，以最有利于公司利益的方式行事。","t":88.21},{"en":"If they can each be trusted to take such responsibilities,","zh":"如果每个人都可以被信任来承担这些责任，","t":94.06},{"en":"and to exercise such initiative as falls within their sphere, then administrative overheads will be low.","zh":"并在其职责范围内发挥主动性，那么行政管理费用就会很低。","t":97.79},{"en":"It will be low because it will be necessary to have only one man looking after each job without having another man to check upon what he is doing,","zh":"之所以低，是因为只需要一个人负责一项工作，而不需要另一个人来检查他正在做什么，","t":106.41},{"en":"keep him in line, and report on him to someone else.","zh":"约束他，并向其他人汇报他的情况。","t":116.06},{"en":"But if no one can be trusted to act in a loyal and responsible manner towards his job,","zh":"但如果没人能被信任以忠诚负责的态度对待自己的工作，","t":120.59},{"en":"then the business will require armies of administrators, checkers and foremen and administrative overheads will rise correspondingly.","zh":"那么企业将需要大量的管理人员、检查员和工头，行政管理费用也将相应地增加。","t":126.88},{"en":"As administrative overheads rise, so the earnings of the business after meeting the expense of administration, will fall;","zh":"随着行政管理费用的增加，企业在支付行政开支后的收益将下降；","t":136.66},{"en":"and the business will have less money to distribute as dividends or invest directly in its future progress and development.","zh":"企业将没有足够的资金来分配股息，或直接投资于其未来的发展。","t":144.76},{"en":"It is precisely the same with a nation.","zh":"一个国家也是如此。","t":152.86},{"en":"To the extent that the people can be relied on to behave in a loyal and responsible manner,","zh":"只要人民能够被信任以忠诚负责的方式行事，","t":156.06},{"en":"the government does not require armies of police and civil servants to keep them in order.","zh":"政府就不需要大批警察和公务员来维持秩序。","t":162.17},{"en":"But if a nation is disunited, the government cannot be sure that the actions of the people will be in the interests of the nation;","zh":"但如果一个国家是分裂的，政府就不能确定人民的行为是否符合国家利益；","t":168.6},{"en":"and it will have to watch, check, and control the people accordingly.","zh":"它就必须相应地监视、检查和控制人民。","t":177.21},{"en":"A disunited nation therefore has to incur unduly high costs of government.","zh":"因此，一个分裂的国家必然会产生过高的政府开支。","t":182.36}],"vocab":[{"word":"essentially","phonetic":"/ɪˈsenʃəli/","meanings":[{"pos":"adverb","meaning":"本质上；根本上；基本上","usage":"用来强调事物最核心的性质或特征，可修饰形容词、动词或整个句子"}]},{"word":"disunited","phonetic":"/ˌdɪsjuˈnaɪtɪd/","meanings":[{"pos":"adjective","meaning":"分裂的；不团结的","usage":"用来描述群体、国家等内部存在分歧、无法统一行动的状态"}]},{"word":"correspondingly","phonetic":"/ˌkɒrəˈspɒndɪŋli/","meanings":[{"pos":"adverb","meaning":"相应地；对应地","usage":"表示两个事物之间存在关联的变化，一个变化伴随另一个同步发生"}]},{"word":"backward","phonetic":"/ˈbækwəd/","meanings":[{"pos":"adjective","meaning":"落后的；发展缓慢的","usage":"形容地区、国家等经济、社会发展水平较低，注意该词带有一定贬义，正式语境中常用 less developed 替代"}]},{"word":"incur","phonetic":"/ɪnˈkɜː(r)/","meanings":[{"pos":"verb","meaning":"招致；遭受；带来（成本、损失等）","usage":"及物动词，常搭配 cost, expense, loss, debt 等表示负面结果的名词"}]},{"word":"administer","phonetic":"/ədˈmɪnɪstə(r)/","meanings":[{"pos":"verb","meaning":"管理；治理；行政","usage":"指对组织、机构、国家等的日常事务进行管理，名词形式为administration"}]},{"word":"overhead","phonetic":"/ˈəʊvəhed/","meanings":[{"pos":"noun","meaning":"运营成本；管理费用；经常开支","usage":"商务语境常用，指企业运营的间接成本，常用复数形式overheads"}]},{"word":"analogous","phonetic":"/əˈnæləɡəs/","meanings":[{"pos":"adjective","meaning":"类似的；可比拟的","usage":"正式用语，常用结构be analogous to/with，表示两者具有相似性可做类比"}]},{"word":"initiative","phonetic":"/ɪˈnɪʃətɪv/","meanings":[{"pos":"noun","meaning":"主动性；积极性；首创精神","usage":"不可数名词，常用搭配take initiative表示“采取主动，发挥主动性”"}]},{"word":"sphere","phonetic":"/sfɪə(r)/","meanings":[{"pos":"noun","meaning":"范围；领域；阶层","usage":"正式用语，指某人的职权、活动或兴趣的范围，常用搭配within one's sphere"}]},{"word":"foreman","phonetic":"/ˈfɔːmən/","meanings":[{"pos":"noun","meaning":"工头；领班；陪审团团长","usage":"指工厂、工地等管理基层工人的主管人员，复数形式为foremen"}]},{"word":"dividend","phonetic":"/ˈdɪvɪdend/","meanings":[{"pos":"noun","meaning":"股息；红利；回报","usage":"商务常用词，指公司按股份分配给股东的利润，也可引申为付出带来的回报"}]},{"word":"civil servant","phonetic":"/ˌsɪvl ˈsɜːvənt/","meanings":[{"pos":"noun","meaning":"公务员；文职人员","usage":"指政府部门的非军事雇佣人员，对应集体名词为civil service（行政部门）"}]},{"word":"unduly","phonetic":"/ʌnˈdjuːli/","meanings":[{"pos":"adverb","meaning":"过度地；不适当地；过分地","usage":"用来修饰形容词或副词，强调程度超出合理范围"}]}],"phrases":[{"phrase":"keep sth/sb running","usage":"表示维持某事物正常运转、某人正常工作","examples":[{"en":"It takes a lot of effort to keep a large company running smoothly.","zh":"维持一家大公司的顺利运转需要付出很多努力。"}]},{"phrase":"stay in business","usage":"商务用语，指企业维持运营、不倒闭","examples":[{"en":"Many small shops had to cut costs sharply to stay in business during the pandemic.","zh":"疫情期间很多小商店不得不大幅削减成本才能维持经营。"}]},{"phrase":"be concerned with","usage":"表示关注、涉及、以…为主题，后接名词或动名词","examples":[{"en":"This research is concerned with the impact of social media on teenagers' mental health.","zh":"这项研究关注社交媒体对青少年心理健康的影响。"}]},{"phrase":"fall within one's sphere","usage":"表示属于某人的职权、责任或兴趣范围","examples":[{"en":"Employee training issues fall within the HR manager's sphere of responsibility.","zh":"员工培训问题属于人力资源经理的职责范围。"}]},{"phrase":"keep sb in line","usage":"表示约束某人、使某人遵守规则、行为合规","examples":[{"en":"The new company rules are designed to keep all employees in line with corporate standards.","zh":"新的公司规定旨在约束所有员工符合企业规范。"}]},{"phrase":"meet the expense of","usage":"表示支付、承担某项费用，相当于cover the expense of","examples":[{"en":"The local government will meet the expense of building the new community library.","zh":"当地政府将承担新建社区图书馆的费用。"}]},{"phrase":"to the extent that","usage":"引导状语从句，表示“在…程度上；就…而言”，用来限定陈述的适用范围","examples":[{"en":"To the extent that you practice every day, your English speaking skills will improve quickly.","zh":"只要你每天练习，你的英语口语能力就会快速提升。"}]},{"phrase":"in the interests of","usage":"表示“为了…的利益；符合…的利益”，后接人或组织","examples":[{"en":"It is in the interests of the whole family to choose a house near good schools.","zh":"选一所靠近好学校的房子符合全家的利益。"}]}],"grammar":[{"title":"where引导的地点状语从句引申用法","definition":"where除了引导表示具体地点的状语从句，还可以引申为引导抽象条件的状语从句，表示“在…的情况下”","structure":"Where + 条件/情况描述, + 主句","usage":"用来表达在某种特定的抽象情形下会产生对应的结果，常见于正式论述类文本","examples":[{"en":"Where the cost of government is high, resources for development are correspondingly low.","zh":"在政府成本高的地方，可用于发展的资源就相应较少。"},{"en":"Where there is a will, there is a way.","zh":"有志者，事竟成。"}]},{"title":"as引导的比例状语从句","definition":"as可以引导表示同步变化的状语从句，意思是“随着…；与…同时”，体现两个变化的关联性","structure":"As + 从句（描述变化）, + so + 主句（描述同步的变化）","usage":"用于说明两个事物的变化成正比关系，主句中的so可以省略，也可以保留增强语气","examples":[{"en":"As administrative overheads rise, so the earnings of the business after meeting the expense of administration, will fall.","zh":"随着管理费用的上升，企业在支付管理费用后的收益就会下降。"},{"en":"As you grow older, so you will understand more about the importance of health.","zh":"随着年龄增长，你会越来越明白健康的重要性。"}]},{"title":"It作形式主语的主语从句","definition":"当主语是较长的从句时，为了避免句子头重脚轻，常用it作形式主语放在句首，真正的主语从句放在句末","structure":"It + 被动语态/形容词 + that + 真正的主语从句","usage":"常见于正式论述中，用来引出普遍认知、需要说明的事实等，常见结构有it is said that, it should be noted that等","examples":[{"en":"And it should not be forgotten how small those resources are in a poor and backward country.","zh":"不应忘记的是，在贫穷落后的国家，这些资源是多么匮乏。"},{"en":"It is widely accepted that regular exercise is beneficial to physical and mental health.","zh":"人们普遍认为规律锻炼对身心健康有益。"}]}],"patterns":[{"pattern":"A may be illustrated by comparing the position of B with that of C.","explanation":"","original":{"en":"This may be illustrated by comparing the position of a nation with that of a private business enterprise.","zh":"要说明这一点，可以把国家的状况和私营企业的状况做个比较。"},"examples":[{"en":"The importance of time management may be illustrated by comparing the efficiency of people with good habits with that of people without plans.","zh":"要说明时间管理的重要性，可以把有良好习惯的人和没有规划的人的效率做个比较。"},{"en":"The harm of air pollution may be illustrated by comparing the health condition of residents in industrial areas with that of people in rural areas.","zh":"要说明空气污染的危害，可以把工业区居民和乡村居民的健康状况做个比较。"}]},{"pattern":"A in X are analogous to B in Y.","explanation":"","original":{"en":"Such administrative overheads in a business are analogous to the cost of government in a nation.","zh":"企业的这类管理费用与国家的政府成本是类似的。"},"examples":[{"en":"The heart in the human body is analogous to the engine in a car.","zh":"人体的心脏相当于汽车的发动机。"},{"en":"Teachers in a school are analogous to coaches in a sports team.","zh":"学校里的老师相当于运动队里的教练。"}]},{"pattern":"To the extent that..., ...do/does not require...","explanation":"","original":{"en":"To the extent that the people can be relied on to behave in a loyal and responsible manner, the government does not require armies of police and civil servants to keep them in order.","zh":"只要人民的行为是忠诚可靠、有责任心的，政府就不需要大批警察和公务员来维持秩序。"},"examples":[{"en":"To the extent that all team members can be trusted to finish their tasks on time, the project manager does not require extra supervisors to check the progress every day.","zh":"只要所有团队成员都能按时完成任务，项目经理就不需要额外的监督人员每天检查进度。"},{"en":"To the extent that students are interested in the subject, teachers do not require strict rules to force them to attend classes.","zh":"只要学生对这门学科感兴趣，老师就不需要严格的规定来强迫他们上课。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“运营成本；管理费用；经常开支” 对应的单词是？","hint":"noun · /ˈəʊvəhed/","options":["indisposition","slack","hub","overhead"],"answer":3,"explain":"overhead · /ˈəʊvəhed/ · noun · 运营成本；管理费用；经常开支。商务语境常用，指企业运营的间接成本，常用复数形式overheads","source":{"kind":"vocab","word":"overhead"},"id":"b4-u36-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：工头；领班；陪审团团长","hint":"/ˈfɔːmən/ · noun","answer":"foreman","placeholder":"输入英文单词","explain":"foreman · /ˈfɔːmən/ · noun · 工头；领班；陪审团团长。指工厂、工地等管理基层工人的主管人员，复数形式为foremen","source":{"kind":"vocab","word":"foreman"},"id":"b4-u36-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ you practice every day, your English speaking skills will improve quickly.","hint":"只要你每天练习，你的英语口语能力就会快速提升。","answer":"to the extent that","placeholder":"输入缺失的短语","explain":"to the extent that：引导状语从句，表示“在…程度上；就…而言”，用来限定陈述的适用范围（只要你每天练习，你的英语口语能力就会快速提升。）","source":{"kind":"phrase","phrase":"to the extent that"},"id":"b4-u36-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：and the _____ will have less money to distribute as dividends or invest directly in its future progress and development.","hint":"企业将没有足够的资金来分配股息，或直接投资于其未来的发展。","answer":"business","placeholder":"输入缺失的单词","explain":"and the business will have less money to distribute as dividends or invest directly in its future progress and development. — 企业将没有足够的资金来分配股息，或直接投资于其未来的发展。","source":{"kind":"sentence","en":"and the business will have less money to distribute as dividends or invest directly in its future progress and development."},"id":"b4-u36-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“where除了引导表示具体地点的状语从句，还可以引申为引导抽象条件的状语从句，表示“在…的情况下”” 描述的是哪个语法点？","hint":"Where + 条件/情况描述, + 主句","options":["状语从句的省略","where引导的地点状语从句引申用法","虚拟条件句（与现在事实相反）","双重否定结构"],"answer":1,"explain":"where引导的地点状语从句引申用法：Where + 条件/情况描述, + 主句：用来表达在某种特定的抽象情形下会产生对应的结果，常见于正式论述类文本","source":{"kind":"grammar","title":"where引导的地点状语从句引申用法"},"id":"b4-u36-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAn enterprise has to incur certain costs and expenses in order to stay in business.","hint":"","options":["一个企业为了维持经营，必须承担一定的成本和开支。","甚至最迷信的村民也不再向喜鹊脱帽致意并祝它早上好。","为什么？一个困难是构建协议。","我们或许可以原谅那些说木星卫星是伽利略的望远镜制造出来的人，"],"answer":0,"explain":"An enterprise has to incur certain costs and expenses in order to stay in business. — 一个企业为了维持经营，必须承担一定的成本和开支。","source":{"kind":"sentence","en":"An enterprise has to incur certain costs and expenses in order to stay in business."},"id":"b4-u36-q06"}]},{"id":"b4-u37","book":4,"unit":37,"key":"37","lessonFrom":37,"lessonTo":37,"title":"The Process of Ageing","titleZh":"衰老的过程","question":"What is one of the most unpleasant discoveries we make about ourselves as we get older?","sentences":[{"en":"At the age of twelve years, the human body is at its most vigorous.","zh":"在十二岁时，人体处于最旺盛的状态。","t":20.55},{"en":"It has yet to reach its full size and strength, and its owner his or her full intelligence: but at this age the likelihood of death is least.","zh":"它尚未达到完全的体型和力量，其主人也尚未达到完全的智力：但在此时，死亡的可能性最小。","t":26.85},{"en":"Earlier, we were infants and young children, and consequently more vulnerable;","zh":"早些时候，我们是婴儿和幼儿，因此更容易受到伤害；","t":39.39},{"en":"later, we shall undergo a progressive loss of our vigour and resistance which, though imperceptible at first","zh":"之后，我们将经历活力和抵抗力的逐渐丧失，这起初虽然难以察觉，","t":47.25},{"en":"will finally become so steep that we can live no longer,","zh":"但最终会变得如此迅速，以至于我们无法再活下去，","t":56.61},{"en":"however well we look after ourselves, and however well society, and our doctors, look after us.","zh":"无论我们如何精心照顾自己，也无论社会和医生如何精心照顾我们。","t":61.71},{"en":"This decline in vigour with the passing of time is called ageing.","zh":"随着时间的推移，这种活力的衰退被称为衰老。","t":70.1},{"en":"It is one of the most unpleasant discoveries which we all make that we must decline in this way, that if we escape wars,","zh":"我们都发现了一个最令人不快的现实，那就是我们必然会以这种方式衰老，如果我们能够幸免于战争、","t":75.34},{"en":"accidents and diseases we shall eventually 'die of old age', and that this happens at a rate which differs little from person to person,","zh":"事故和疾病，最终我们将“老死”，而且这个过程的速度人与人之间差异很小，","t":85.35},{"en":"so that there are heavy odds in favour of our dying between the ages of 65 and 80.","zh":"因此，我们很可能在65到80岁之间去世。","t":96.9},{"en":"Some of us will die sooner, a few will live longer -- on into a ninth or tenth decade.","zh":"我们中有些人会更早去世，少数人会活得更久——进入第九或第十个十年。","t":104.68},{"en":"But the chances are against it,","zh":"但这种机会渺茫，","t":112.89},{"en":"and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are.","zh":"而且我们能期望活多久，无论我们多么幸运和健壮，都有一个实际的限制。","t":115.45},{"en":"Normal people tend to forget this process unless and until they are reminded of it.","zh":"除非被提醒，否则常人往往会忘记这个过程。","t":123.88},{"en":"We are so familiar with the fact that man ages, that people have for years assumed that the process of losing vigour with time,","zh":"我们对人会衰老这一事实非常熟悉，以至于人们多年来一直认为，随着时间流逝而失去活力，","t":130.41},{"en":"of becoming more likely to die the older we get, was something self-evident","zh":"年纪越大越可能死亡的过程，是理所当然的事情，","t":139.48},{"en":"like the cooling of a hot kettle or the wearing-out of a pair of shoes.","zh":"就像热水壶变凉或鞋子磨损一样。","t":145.37},{"en":"They have also assumed that all animals,","zh":"他们还假设所有动物，","t":150.73},{"en":"and probably other organisms such as trees, or even the universe itself, must in the nature of things 'wear out'.","zh":"以及其他生物，如树木，甚至宇宙本身，按照事物的本性都必然会“耗尽”。","t":154.17},{"en":"Most animals we commonly observe do in fact age as we do,","zh":"我们通常观察到的大多数动物，如果活得足够长，","t":164.82},{"en":"if given the chance to live long enough;","zh":"确实会像我们一样衰老；","t":169.82},{"en":"and mechanical systems like a wound watch, or the sun,","zh":"而像上弦的钟表或太阳这样的机械系统，","t":172.42},{"en":"do in fact run out of energy in accordance with the second law of thermodynamics (whether the whole universe does so is a moot point at present).","zh":"确实会根据热力学第二定律耗尽能量（整个宇宙是否如此，目前尚无定论）。","t":177.54},{"en":"But these are not analogous to what happens when man ages.","zh":"但这些与人类衰老时发生的情况并不相似。","t":189.17},{"en":"A run-down watch is still a watch and can be rewound.","zh":"一只停走的表仍然是一只表，可以重新上弦。","t":194.68},{"en":"An old watch, by contrast, becomes so worn and unreliable that it eventually is not worth mending.","zh":"相比之下，一只旧表会变得磨损不堪，不可靠，最终不值得修理。","t":199.89},{"en":"But a watch could never repair itself--it does not consist of living parts, only of metal, which wears away by friction.","zh":"但是表永远无法自我修复——它不包含活体部分，只有金属，金属会因摩擦而磨损。","t":209.98},{"en":"We could, at one time, repair ourselves--well enough, at least, to overcome all but the most instantly fatal illnesses and accidents.","zh":"我们曾经能够自我修复——至少足以克服除了最即刻致命的疾病和事故之外的所有情况。","t":220.98},{"en":"Between twelve and eighty years we gradually lose this power;","zh":"在十二岁到八十岁之间，我们逐渐失去这种能力；","t":233.69},{"en":"an illness which at 12 would knock us over, at 80 can knock us out, and into our grave.","zh":"一种在12岁时会让我们病倒的疾病，在80岁时可能就会让我们倒下，并送入坟墓。","t":239.72},{"en":"If we could stay as vigorous as we are at twelve,","zh":"如果我们能像十二岁时那样充满活力，","t":248.79},{"en":"it would take about 700 years for half of us to die, and another 700 for the survivors to be reduced by half again.","zh":"大约需要700年我们中一半的人才会去世，再过700年，幸存者数量才会再次减少一半。","t":252.54}],"vocab":[{"word":"vigorous","phonetic":"/ˈvɪɡərəs/","meanings":[{"pos":"adjective","meaning":"充满活力的；精力充沛的；强壮的","usage":"用来描述人、身体或活动充满力量和活力的状态"}]},{"word":"likelihood","phonetic":"/ˈlaɪklihʊd/","meanings":[{"pos":"noun","meaning":"可能性；可能发生的事","usage":"不可数名词，常用搭配the likelihood of (doing) sth表示某事发生的可能性"}]},{"word":"vulnerable","phonetic":"/ˈvʌlnərəbl/","meanings":[{"pos":"adjective","meaning":"易受伤害的；脆弱的；易受攻击的","usage":"常与介词to搭配，表示易受某类事物的伤害"}]},{"word":"progressive","phonetic":"/prəˈɡresɪv/","meanings":[{"pos":"adjective","meaning":"渐进的；逐步的；稳步发展的","usage":"用来描述变化是逐步发生、持续推进的"}]},{"word":"imperceptible","phonetic":"/ˌɪmpəˈseptəbl/","meanings":[{"pos":"adjective","meaning":"难以察觉的；细微得几乎感觉不到的","usage":"用来描述变化、差异等非常小，几乎无法被感知到"}]},{"word":"steep","phonetic":"/stiːp/","meanings":[{"pos":"adjective","meaning":"陡的；陡峭的；（变化）急剧的","usage":"除了形容坡度大，还可指数量、程度等突然的大幅变化"}]},{"word":"ageing","phonetic":"/ˈeɪdʒɪŋ/","meanings":[{"pos":"noun","meaning":"变老；衰老","usage":"指生物体随着时间推移机能衰退的过程，也可作形容词表示“老化的”"}]},{"word":"odds","phonetic":"/ɒdz/","meanings":[{"pos":"noun","meaning":"可能性；几率；概率","usage":"复数名词，常用搭配odds in favour of表示“……的可能性很大”，odds against表示“……的可能性很小”"}]},{"word":"virtual","phonetic":"/ˈvɜːtʃuəl/","meanings":[{"pos":"adjective","meaning":"实质上的；事实上的；几乎……的","usage":"用来描述某事物虽然没有名义上的形式，但实际上已经具备对应的性质"}]},{"word":"robust","phonetic":"/rəʊˈbʌst/","meanings":[{"pos":"adjective","meaning":"强健的；强壮的；结实的","usage":"常用来形容人的身体强壮健康，也可形容系统、组织等稳固可靠"}]},{"word":"self-evident","phonetic":"/ˌself ˈevɪdənt/","meanings":[{"pos":"adjective","meaning":"不证自明的；显而易见的","usage":"用来描述事实、道理等不需要证明就很明显的"}]},{"word":"wear-out","phonetic":"/ˈweə aʊt/","meanings":[{"pos":"phrasal verb","meaning":"磨损；用坏；耗尽","usage":"指物品因长期使用而损坏，也可指人的精力被耗尽"}]},{"word":"organism","phonetic":"/ˈɔːɡənɪzəm/","meanings":[{"pos":"noun","meaning":"有机体；生物体；生物","usage":"指有生命的生物，包括动物、植物、微生物等"}]},{"word":"thermodynamics","phonetic":"/ˌθɜːməʊdaɪˈnæmɪks/","meanings":[{"pos":"noun","meaning":"热力学","usage":"物理学科分支，研究热和其他形式能量之间的转换关系"}]},{"word":"moot","phonetic":"/muːt/","meanings":[{"pos":"adjective","meaning":"无定论的；有争议的；未决议的","usage":"常用搭配a moot point表示“有争议的问题，尚无定论的问题”"}]}],"phrases":[{"phrase":"undergo a loss of","usage":"表示“经历某种损失、衰退”，用来描述被动承受某种机能、资源等的减少","examples":[{"en":"Many old people undergo a gradual loss of hearing as they get older.","zh":"很多老年人随着年龄增长会逐渐经历听力衰退。"}]},{"phrase":"in favour of","usage":"此处表示“有利于；支持”，用在描述概率的语境中说明某种结果发生的可能性更大","examples":[{"en":"The odds are in favour of the home team winning this match.","zh":"主队赢得这场比赛的可能性很大。"}]},{"phrase":"the chances are against it","usage":"固定表达，表示“某事发生的可能性很小”，其中it指代上文提到的可能性较低的情况","examples":[{"en":"If you don't prepare for the exam, the chances are against your passing it.","zh":"如果你不备考，通过考试的可能性很小。"}]},{"phrase":"in accordance with","usage":"表示“依照；根据；与……一致”，用来引出遵循的规则、规律、法律等","examples":[{"en":"All the activities are held in accordance with the school's regulations.","zh":"所有活动都是依照学校的规定开展的。"}]},{"phrase":"be analogous to","usage":"表示“与……类似；与……相似”，用来比较两个事物有相似的特征或性质","examples":[{"en":"The function of a computer's CPU is analogous to the human brain.","zh":"计算机中央处理器的功能和人类大脑类似。"}]},{"phrase":"by contrast","usage":"表示“相比之下；与此相反”，用于连接两个形成对比的内容，突出二者的差异","examples":[{"en":"The north of the country is dry, while the south, by contrast, is very rainy.","zh":"这个国家的北部很干燥，相比之下，南部则多雨。"}]},{"phrase":"wear away","usage":"表示“磨损；侵蚀；逐渐消失”，指物体因摩擦、使用等逐步被损耗","examples":[{"en":"The inscription on the old stone has worn away over hundreds of years.","zh":"这块古老石头上的铭文经过数百年已经被磨损了。"}]},{"phrase":"all but","usage":"表示“除了……之外都；几乎”，两种常见含义，这里指“除了……之外都”","examples":[{"en":"She finished all but the last question on the test paper.","zh":"她做完了试卷上除了最后一题之外的所有题目。"}]},{"phrase":"knock sb out","usage":"表示“使某人不省人事；使某人疲惫不堪；击败某人”，文中指疾病严重到使人失去生命","examples":[{"en":"The strong punch knocked the boxer out in the first round.","zh":"重重的一拳在第一回合就把拳击手打晕了。"}]}],"grammar":[{"title":"however引导的让步状语从句","definition":"however用来引导让步状语从句，表示“无论如何；不管多么”，相当于no matter how，用来引出无论在什么情况下主句的内容都成立","structure":"however + 形容词/副词 + 主语 + 谓语，主句","usage":"用于强调无论某种情况达到什么程度，都不会影响主句的结果，从句需要用陈述语序","examples":[{"en":"However well we look after ourselves, we cannot stop the process of ageing.","zh":"无论我们把自己照顾得多好，都无法阻止衰老的过程。"},{"en":"However hard he tried, he could not solve the complicated math problem.","zh":"无论他多么努力，都解不出这道复杂的数学题。"}]},{"title":"It作形式主语的名词性从句","definition":"当主语是较长的that从句时，为了避免句子头重脚轻，常用it作形式主语放在句首，真正的主语从句放在句末","structure":"It + be + 名词/形容词 + that引导的主语从句","usage":"用来表达某个事实是怎样的，常见的结构有It is a fact that..., It is unpleasant that..., It is obvious that...等","examples":[{"en":"It is one of the most unpleasant discoveries which we all make that we must decline in this way as we age.","zh":"我们所有人都会有的最令人不快的发现之一，就是我们随着年龄增长必然会这样衰退。"},{"en":"It is a common belief that regular exercise is good for physical and mental health.","zh":"人们普遍认为规律锻炼对身心健康有益。"}]},{"title":"so...that...引导的结果状语从句","definition":"so...that...结构用来引导结果状语从句，表示“如此……以至于……”，说明前面的情况导致的结果","structure":"主语 + 谓语 + so + 形容词/副词 + that + 结果从句","usage":"so后面接形容词或副词，that后面接完整的句子表示结果，口语中that有时可以省略","examples":[{"en":"The loss of vigour will finally become so steep that we can live no longer.","zh":"精力的衰退最终会变得非常急剧，以至于我们无法再活下去。"},{"en":"The novel was so interesting that I stayed up all night reading it.","zh":"这本小说太有趣了，以至于我熬了一整夜看完它。"}]}],"patterns":[{"pattern":"This + 表示现象的名词 + with the passing of time is called + 术语名词.","explanation":"","original":{"en":"This decline in vigour with the passing of time is called ageing.","zh":"这种随着时间流逝发生的精力衰退被称为衰老。"},"examples":[{"en":"This gradual rise in global temperature with the passing of time is called global warming.","zh":"这种随着时间推移发生的全球气温逐渐上升被称为全球变暖。"},{"en":"This slow loss of memory with the passing of time is called age-related amnesia.","zh":"这种随着时间推移发生的记忆缓慢丧失被称为年龄相关性健忘。"}]},{"pattern":"We are so familiar with the fact that + 客观事实, that people have for years assumed that + 普遍看法.","explanation":"","original":{"en":"We are so familiar with the fact that man ages, that people have for years assumed that the process of losing vigour with time was something self-evident.","zh":"我们对人会衰老这一事实如此熟悉，以至于多年来人们一直认为，精力随着时间流逝而衰退的过程是不言自明的。"},"examples":[{"en":"We are so familiar with the fact that the sun rises in the east, that people have for years assumed that this rule will never change.","zh":"我们对太阳从东方升起这一事实如此熟悉，以至于多年来人们一直认为这个规律永远不会改变。"},{"en":"We are so familiar with the fact that water flows downhill, that people have for years assumed that gravity is a natural force we can never resist.","zh":"我们对水往低处流这一事实如此熟悉，以至于多年来人们一直认为重力是我们永远无法抗拒的自然力。"}]},{"pattern":"If we could stay as + 形容词 + as we are at + 年龄, it would take about + 时间段 + for + 事件发生.","explanation":"","original":{"en":"If we could stay as vigorous as we are at twelve, it would take about 700 years for half of us to die.","zh":"如果我们能一直保持12岁时的活力，那么我们中有一半人死亡需要大约700年的时间。"},"examples":[{"en":"If we could stay as curious as we are at five, it would take a lifetime for us to run out of questions to ask about the world.","zh":"如果我们能一直保持5岁时的好奇心，那么我们要花一辈子的时间才会问完对世界的所有问题。"},{"en":"If we could stay as fast as we are at twenty, it would take only 10 seconds for us to finish the 100-meter race.","zh":"如果我们能一直保持20岁时的速度，那么我们只需要10秒就能跑完100米。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“无定论的；有争议的；未决议的” 对应的单词是？","hint":"adjective · /muːt/","options":["appreciate","moot","slaughter","prestige"],"answer":1,"explain":"moot · /muːt/ · adjective · 无定论的；有争议的；未决议的。常用搭配a moot point表示“有争议的问题，尚无定论的问题”","source":{"kind":"vocab","word":"moot"},"id":"b4-u37-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：充满活力的；精力充沛的；强壮的","hint":"/ˈvɪɡərəs/ · adjective","answer":"vigorous","placeholder":"输入英文单词","explain":"vigorous · /ˈvɪɡərəs/ · adjective · 充满活力的；精力充沛的；强壮的。用来描述人、身体或活动充满力量和活力的状态","source":{"kind":"vocab","word":"vigorous"},"id":"b4-u37-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：All the activities are held _____ the school's regulations.","hint":"所有活动都是依照学校的规定开展的。","answer":"in accordance with","placeholder":"输入缺失的短语","explain":"in accordance with：表示“依照；根据；与……一致”，用来引出遵循的规则、规律、法律等（所有活动都是依照学校的规定开展的。）","source":{"kind":"phrase","phrase":"in accordance with"},"id":"b4-u37-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：They have also assumed that all _____","hint":"他们还假设所有动物，","answer":"animals","placeholder":"输入缺失的单词","explain":"They have also assumed that all animals, — 他们还假设所有动物，","source":{"kind":"sentence","en":"They have also assumed that all animals,"},"id":"b4-u37-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当主语是较长的that从句时，为了避免句子头重脚轻，常用it作形式主语放在句首，真正的主语从句放在句末” 描述的是哪个语法点？","hint":"It + be + 名词/形容词 + that引导的主语从句","options":["被动语态","定语从句","while引导的让步状语从句","It作形式主语的名词性从句"],"answer":3,"explain":"It作形式主语的名词性从句：It + be + 名词/形容词 + that引导的主语从句：用来表达某个事实是怎样的，常见的结构有It is a fact that..., It is unpleasant that..., It is obvious that...等","source":{"kind":"grammar","title":"It作形式主语的名词性从句"},"id":"b4-u37-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nof becoming more likely to die the older we get, was something self-evident","hint":"","options":["年纪越大越可能死亡的过程，是理所当然的事情，","可能会留下一个自动信使，以等待一个先进文明的可能觉醒。","图形记录显示三波在短时间内一个接一个地到达。","在工业生活的组织中，工厂对工人生理和心理状态的影响已被完全忽视。"],"answer":0,"explain":"of becoming more likely to die the older we get, was something self-evident — 年纪越大越可能死亡的过程，是理所当然的事情，","source":{"kind":"sentence","en":"of becoming more likely to die the older we get, was something self-evident"},"id":"b4-u37-q06"}]},{"id":"b4-u38","book":4,"unit":38,"key":"38","lessonFrom":38,"lessonTo":38,"title":"Water and the Traveller","titleZh":"水与旅行者","question":"What does this text describe?","sentences":[{"en":"Contamination of water supplies is usually due to poor sanitation close to water sources,","zh":"供水污染通常是由于水源附近卫生条件差，","t":13.5},{"en":"sewage disposal into the sources themselves, leakage of sewage into distribution systems or contamination with industrial or farm waste.","zh":"污水直接排入水源，污水泄漏进入分配系统，或受到工业或农业废物的污染。","t":21.3},{"en":"Even if a piped water supply is safe at its source, it is not always safe by the time it reaches the tap.","zh":"即使管道供水在其源头是安全的，但当它到达水龙头时，也并非总是安全的。","t":32.17},{"en":"Intermittent tap-water supplies should be regarded as particularly suspect.","zh":"间歇性自来水供应应被视为特别可疑。","t":39.72},{"en":"Travellers on short trips to areas with water supplies of uncertain quality","zh":"短途旅行到水质不确定地区的旅行者","t":45.76},{"en":"should avoid drinking tap-water, or untreated water from any other source.","zh":"应避免饮用自来水，或任何其他来源的未经处理的水。","t":51.08},{"en":"It is best to keep to hot drinks, bottled or canned drinks of well-known brand names-international standard of water treatment are usually followed at bottling plants.","zh":"最好只喝热饮、知名品牌的瓶装或罐装饮料——瓶装厂通常会遵循国际水处理标准。","t":56.95},{"en":"Carbonated drinks are acidic, and slightly safer.","zh":"碳酸饮料呈酸性，稍微安全一些。","t":68.27},{"en":"Make sure that all bottles are opened in your presence, and that their rims are clean and dry.","zh":"确保所有瓶子都是在你面前打开的，并且瓶口清洁干燥。","t":72.24},{"en":"Boiling is always a good way of treating water.","zh":"煮沸始终是处理水的好方法。","t":79.14},{"en":"Some hotels supply boiled water on request and this can be used for drinking, or for brushing teeth.","zh":"有些酒店应要求提供开水，可用于饮用或刷牙。","t":82.36},{"en":"Portable boiling elements that can boil small quantities of water are useful when the right voltage of electricity is available.","zh":"当有合适的电压时，能烧开少量水的便携式电热棒会很有用。","t":89.49},{"en":"Refuse politely any cold drink from an unknown source.","zh":"礼貌地拒绝任何来源不明的冷饮。","t":97.86},{"en":"Ice is only as safe as the water from which it is made,","zh":"冰的安全性取决于制作它的水，","t":103.22},{"en":"and should not be put in drinks unless it is known to be safe.","zh":"除非已知其安全，否则不应将其放入饮料中。","t":106.79},{"en":"Drinks can be cooled by placing them on ice rather than adding ice to them.","zh":"饮料可以通过放在冰块上冷却，而不是将冰块加入饮料中。","t":111.8},{"en":"Alcohol may be a medical disinfectant, but should not be relied upon to sterilize water.","zh":"酒精可能是医用消毒剂，但不应指望它能给水消毒。","t":118.17},{"en":"Ethanol is more effective at a concentration of 50-70 percent;","zh":"乙醇在50-70%的浓度下更有效；","t":125.57},{"en":"below 20 per cent, its bactericidal action is negligible.","zh":"低于20%时，其杀菌作用微乎其微。","t":130.72},{"en":"Spirits labelled 95 proof contain only about 47 per cent alcohol.","zh":"标示为95度的烈酒只含有大约47%的酒精。","t":135.91},{"en":"Beware of methylated alcohol,","zh":"警惕工业酒精（甲醇变性酒精），","t":142.63},{"en":"which is very poisonous and should never be added to drinking water.","zh":"它剧毒，绝不应加入饮用水中。","t":144.89},{"en":"If no other safe water supply can be obtained,","zh":"如果无法获得其他安全水源，","t":150.71},{"en":"tap water that is too hot to touch can be left to cool and is generally safe to drink.","zh":"热得烫手的自来水可以放凉后饮用，通常是安全的。","t":154.45},{"en":"Those planning a trip to remote areas, or intending to live in countries where drinking water is not readily available,","zh":"计划去偏远地区旅行，或打算生活在饮用水不易获得的国家的人，","t":161.5},{"en":"should know about the various possible methods for making water safe.","zh":"应该了解使水安全可饮用的各种可能方法。","t":169.29}],"vocab":[{"word":"contamination","phonetic":"/kənˌtæmɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"污染；弄脏","usage":"不可数名词，常指水、空气、食物等被有害物质污染"}]},{"word":"sanitation","phonetic":"/ˌsænɪˈteɪʃn/","meanings":[{"pos":"noun","meaning":"卫生设施；环境卫生","usage":"不可数名词，指公共卫生系统、卫生条件相关的统称"}]},{"word":"sewage","phonetic":"/ˈsuːɪdʒ/","meanings":[{"pos":"noun","meaning":"污水；污物","usage":"不可数名词，特指生活或工业排放的废水、废弃物"}]},{"word":"leakage","phonetic":"/ˈliːkɪdʒ/","meanings":[{"pos":"noun","meaning":"渗漏；泄漏","usage":"既可指渗漏的动作，也可指渗漏出的液体/气体"}]},{"word":"distribution","phonetic":"/ˌdɪstrɪˈbjuːʃn/","meanings":[{"pos":"noun","meaning":"输送；分配；分布","usage":"常表示资源、物资的分发、输送过程"}]},{"word":"intermittent","phonetic":"/ˌɪntəˈmɪtənt/","meanings":[{"pos":"adjective","meaning":"间歇的；断断续续的","usage":"用于描述不连续、时断时续的事物"}]},{"word":"suspect","phonetic":"/ˈsʌspekt/","meanings":[{"pos":"adjective","meaning":"不可靠的；可疑的","usage":"作形容词时置于系动词后或修饰名词，表事物有问题、不值得信任"}]},{"word":"untreated","phonetic":"/ˌʌnˈtriːtɪd/","meanings":[{"pos":"adjective","meaning":"未经处理的","usage":"常用于修饰水、材料等未经过加工、净化等流程的事物"}]},{"word":"carbonated","phonetic":"/ˈkɑːbəneɪtɪd/","meanings":[{"pos":"adjective","meaning":"含二氧化碳的；碳酸的","usage":"常修饰饮料，指充入了二氧化碳的饮品"}]},{"word":"acidic","phonetic":"/əˈsɪdɪk/","meanings":[{"pos":"adjective","meaning":"酸的；酸性的","usage":"用于描述物质的酸性属性"}]},{"word":"rim","phonetic":"/rɪm/","meanings":[{"pos":"noun","meaning":"（容器的）边；边缘","usage":"常指杯子、瓶子等容器的口沿部分"}]},{"word":"portable","phonetic":"/ˈpɔːtəbl/","meanings":[{"pos":"adjective","meaning":"便携式的；手提的","usage":"修饰设备、家具等，说明便于携带、移动"}]},{"word":"voltage","phonetic":"/ˈvəʊltɪdʒ/","meanings":[{"pos":"noun","meaning":"电压；伏特数","usage":"物理术语，指电力系统的电压参数"}]},{"word":"disinfectant","phonetic":"/ˌdɪsɪnˈfektənt/","meanings":[{"pos":"noun","meaning":"消毒剂","usage":"指用于杀菌、消毒的化学制剂"}]},{"word":"sterilize","phonetic":"/ˈsterəlaɪz/","meanings":[{"pos":"verb","meaning":"消毒；杀菌","usage":"指通过高温、化学试剂等方式杀灭微生物"}]}],"phrases":[{"phrase":"due to","usage":"介词短语，用于引出某事发生的原因，后面接名词或名词性短语","examples":[{"en":"The flight delay was due to bad weather.","zh":"航班延误是恶劣天气导致的。"}]},{"phrase":"disposal into","usage":"表示“排入；倒入”，特指将废弃物排放到某个地点","examples":[{"en":"The local government has banned the disposal of industrial waste into rivers.","zh":"当地政府已经禁止将工业废料排入河流。"}]},{"phrase":"regard as","usage":"动词短语，意为“把……视为；认为……是”，可用于被动语态","examples":[{"en":"The project is regarded as one of the most successful initiatives this year.","zh":"这个项目被认为是今年最成功的举措之一。"}]},{"phrase":"keep to","usage":"动词短语，此处表示“只使用；坚持食用/饮用”，也可表示遵守规则、不偏离路线","examples":[{"en":"When you have a stomachache, it's better to keep to light food.","zh":"你胃痛的时候最好只吃清淡的食物。"}]},{"phrase":"well-known brand names","usage":"名词短语，指“知名品牌”，多用于消费场景描述","examples":[{"en":"When buying electronics, many people prefer products of well-known brand names.","zh":"购买电子产品时，很多人偏好知名品牌的产品。"}]},{"phrase":"in one's presence","usage":"介词短语，意为“当着某人的面；在某人在场的情况下”","examples":[{"en":"The contract should be signed in the presence of a witness.","zh":"这份合同应该在证人在场的情况下签署。"}]},{"phrase":"on request","usage":"介词短语，表示“一经要求；根据请求”，说明服务可按需提供","examples":[{"en":"The hotel provides extra blankets on request.","zh":"酒店可以根据客人要求提供额外的毛毯。"}]},{"phrase":"rely upon","usage":"动词短语，意为“依赖；依靠”，等同于rely on，后面可接名词或动名词","examples":[{"en":"You can rely upon her to finish the task on time.","zh":"你可以放心让她按时完成这项任务。"}]},{"phrase":"beware of","usage":"动词短语，意为“当心；提防”，用于提醒他人注意危险或有害事物","examples":[{"en":"Beware of pickpockets when you take the subway during rush hour.","zh":"高峰时段乘坐地铁时要当心扒手。"}]},{"phrase":"rather than","usage":"连词短语，表示“而不是”，用于连接两个并列成分，否定后者","examples":[{"en":"I prefer to go for a walk rather than stay at home on weekends.","zh":"周末我宁愿去散步也不愿待在家里。"}]}],"grammar":[{"title":"被动语态 (Passive Voice)","definition":"表示主语是动作的承受者，而非动作的执行者，常用于强调动作的承受对象，或不需要说明动作执行者的场景","structure":"be + 动词过去分词（可搭配不同时态、情态动词）","usage":"多用于正式文本、说明类文本中，体现内容的客观性","examples":[{"en":"Intermittent tap-water supplies should be regarded as particularly suspect.","zh":"时断时续的自来水供应应该被视为格外不可靠。"},{"en":"Ice should not be put in drinks unless it is known to be safe.","zh":"冰不应该被加入饮品中，除非人们确认它是安全的。"}]},{"title":"条件状语从句 (Adverbial Clause of Condition)","definition":"用于表示某件事发生的前提条件，常由if, unless等连词引导","structure":"主句 + if/unless + 从句，从句通常用一般现在时表客观事实或普遍情况","usage":"用于给出建议、说明规则或者描述条件与结果的关系","examples":[{"en":"Even if a piped water supply is safe at its source, it is not always safe by the time it reaches the tap.","zh":"即使管道供水的水源是安全的，等到水到达水龙头时也不一定安全了。"},{"en":"If no other safe water supply can be obtained, tap water that is too hot to touch can be left to cool and is generally safe to drink.","zh":"如果找不到其他安全的水源，烫到无法触碰的自来水可以放凉后饮用，通常是安全的。"}]},{"title":"定语从句 (Attributive Clause)","definition":"修饰名词或代词的从句，用于对先行词进行补充说明，常由关系代词that, which, who等引导","structure":"先行词 + 关系代词 + 从句","usage":"可以对事物的属性、适用场景等进行更详细的描述，让句子信息更丰富","examples":[{"en":"Portable boiling elements that can boil small quantities of water are useful when the right voltage of electricity is available.","zh":"可以烧少量水的便携式烧水器在电压合适的情况下非常实用。"},{"en":"Those planning a trip to remote areas, or intending to live in countries where drinking water is not readily available, should know about the various possible methods for making water safe.","zh":"那些计划去偏远地区旅行，或是打算在饮用水不易获得的国家居住的人，应该了解各种可行的净水方法。"}]}],"patterns":[{"pattern":"... is usually due to ..., ..., ... or ...","explanation":"","original":{"en":"Contamination of water supplies is usually due to poor sanitation close to water sources, sewage disposal into the sources themselves, leakage of sewage into distribution systems or contamination with industrial or farm waste.","zh":"供水污染通常是由水源附近卫生条件差、污水直接排入水源、污水渗漏进供水系统，或是工业与农业废料污染导致的。"},"examples":[{"en":"Poor health in teenagers is usually due to lack of exercise, irregular eating habits, insufficient sleep or excessive use of electronic devices.","zh":"青少年健康不佳通常是因为缺乏锻炼、饮食习惯不规律、睡眠不足或是过度使用电子设备。"},{"en":"The decline in sales is usually due to fierce market competition, outdated product design, poor marketing strategies or rising product prices.","zh":"销量下滑通常是因为市场竞争激烈、产品设计过时、营销策略不佳或是产品价格上涨。"}]},{"pattern":"Even if ..., it is not always ... by the time ...","explanation":"","original":{"en":"Even if a piped water supply is safe at its source, it is not always safe by the time it reaches the tap.","zh":"即使管道供水的水源是安全的，等到水到达水龙头时也不一定安全了。"},"examples":[{"en":"Even if the vegetables are fresh when they are harvested, they are not always fresh by the time they reach the supermarket shelves.","zh":"即使蔬菜在收获的时候是新鲜的，等到摆上超市货架的时候也不一定新鲜了。"},{"en":"Even if the news is true when it is first released, it is not always accurate by the time it spreads on social media.","zh":"即使新闻刚发布的时候是真实的，等到在社交媒体上传播开的时候也不一定准确了。"}]},{"pattern":"... may be ..., but should not be relied upon to ...","explanation":"","original":{"en":"Alcohol may be a medical disinfectant, but should not be relied upon to sterilize water.","zh":"酒精或许是医用消毒剂，但不能依靠它来给饮用水消毒。"},"examples":[{"en":"Multivitamins may be nutritional supplements, but should not be relied upon to replace a balanced diet.","zh":"复合维生素或许是营养补充剂，但不能依靠它来替代均衡饮食。"},{"en":"Translation software may be a helpful tool, but should not be relied upon to handle all professional translation work.","zh":"翻译软件或许是实用的工具，但不能依靠它来完成所有专业翻译工作。"}]},{"pattern":"Those ... should know about ...","explanation":"","original":{"en":"Those planning a trip to remote areas, or intending to live in countries where drinking water is not readily available, should know about the various possible methods for making water safe.","zh":"那些计划去偏远地区旅行，或是打算在饮用水不易获得的国家居住的人，应该了解各种可行的净水方法。"},"examples":[{"en":"Those wanting to improve their spoken English, or preparing for international exams, should know about the effective ways to practice listening and speaking daily.","zh":"那些想要提高英语口语，或是准备国际考试的人，应该了解日常练习听说的有效方法。"},{"en":"Those interested in starting a small business, or looking for extra income, should know about the basic rules of the local market and relevant policies.","zh":"那些对创办小生意感兴趣，或是想要获得额外收入的人，应该了解本地市场的基本规则和相关政策。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“卫生设施；环境卫生” 对应的单词是？","hint":"noun · /ˌsænɪˈteɪʃn/","options":["hasten","silt","tenant","sanitation"],"answer":3,"explain":"sanitation · /ˌsænɪˈteɪʃn/ · noun · 卫生设施；环境卫生。不可数名词，指公共卫生系统、卫生条件相关的统称","source":{"kind":"vocab","word":"sanitation"},"id":"b4-u38-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：便携式的；手提的","hint":"/ˈpɔːtəbl/ · adjective","answer":"portable","placeholder":"输入英文单词","explain":"portable · /ˈpɔːtəbl/ · adjective · 便携式的；手提的。修饰设备、家具等，说明便于携带、移动","source":{"kind":"vocab","word":"portable"},"id":"b4-u38-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：When buying electronics, many people prefer products of _____.","hint":"购买电子产品时，很多人偏好知名品牌的产品。","answer":"well-known brand names","placeholder":"输入缺失的短语","explain":"well-known brand names：名词短语，指“知名品牌”，多用于消费场景描述（购买电子产品时，很多人偏好知名品牌的产品。）","source":{"kind":"phrase","phrase":"well-known brand names"},"id":"b4-u38-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Carbonated drinks are acidic, and slightly _____","hint":"碳酸饮料呈酸性，稍微安全一些。","answer":"safer","placeholder":"输入缺失的单词","explain":"Carbonated drinks are acidic, and slightly safer. — 碳酸饮料呈酸性，稍微安全一些。","source":{"kind":"sentence","en":"Carbonated drinks are acidic, and slightly safer."},"id":"b4-u38-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“修饰名词或代词的从句，用于对先行词进行补充说明，常由关系代词that, which, who等引导” 描述的是哪个语法点？","hint":"先行词 + 关系代词 + 从句","options":["让步状语从句：even if/even though引导","定语从句 (Attributive Clause)","被动语态","which引导的非限制性定语从句"],"answer":1,"explain":"定语从句 (Attributive Clause)：先行词 + 关系代词 + 从句：可以对事物的属性、适用场景等进行更详细的描述，让句子信息更丰富","source":{"kind":"grammar","title":"定语从句 (Attributive Clause)"},"id":"b4-u38-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIce is only as safe as the water from which it is made,","hint":"","options":["冰的安全性取决于制作它的水，","海豚和鲨鱼是天敌。","不久之后，父母就会抱怨孩子如此守口如瓶，从不告诉他们任何事情，","我们的环境主要由我们所相信的事物所决定。"],"answer":0,"explain":"Ice is only as safe as the water from which it is made, — 冰的安全性取决于制作它的水，","source":{"kind":"sentence","en":"Ice is only as safe as the water from which it is made,"},"id":"b4-u38-q06"}]},{"id":"b4-u39","book":4,"unit":39,"key":"39","lessonFrom":39,"lessonTo":39,"title":"What Every Writer Wants","titleZh":"每个作家都想要什么","question":"How do professional writers ignore what they were taught at school about writing?","sentences":[{"en":"I have known very few writers,","zh":"我认识的作家很少，","t":21.57},{"en":"but those I have known and whom I respect, confess at once that they have little idea where they are going when they first set pen to paper.","zh":"但我所认识和尊重的那几位作家，都立刻承认他们在首次提笔写作时，对要写什么几乎没有什么概念。","t":24.56},{"en":"They have a character, perhaps two;","zh":"他们可能有一个人物，或许两个；","t":36.13},{"en":"they are in that condition of eager discomfort which passes for inspiration all admit radical changes of destination once the journey has begun;","zh":"他们处于那种急切不安的状态，那种状态被认为是灵感，一旦旅程开始，所有人都承认目的地会发生根本性变化；","t":39.1},{"en":"one, to my certain knowledge, spent nine months on a novel about Kashmir,","zh":"据我所知，有一位作家花九个月写了一部关于克什米尔的小说，","t":50.66},{"en":"then reset the whole thing in the Scottish Highlands.","zh":"然后将整个故事背景改到了苏格兰高地。","t":57.61},{"en":"I never heard of anyone making a 'skeleton', as we were taught at school.","zh":"我从未听说有人像我们在学校里学的那样，先写好“提纲”。","t":61.38},{"en":"In the breaking and remaking, in the timing interweaving, beginning afresh,","zh":"在打破与重塑、适时交织、重新开始的过程中，","t":67.35},{"en":"the writer comes to discern things in his material which were not consciously in his mind when he began.","zh":"作家开始辨明他材料中那些在开始时并未意识到的东西。","t":74.8},{"en":"This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination.","zh":"这种有机过程，常常带来非凡的自我发现时刻，具有难以言喻的魅力。","t":82.83},{"en":"A blurred image appears; he adds a brushstroke and another and it is gone","zh":"一个模糊的图像出现了；他添上一笔又一笔，然后它消失了，","t":94.32},{"en":"but something was there, and he will not rest till he has captured it.","zh":"但有些东西曾在那儿，他不会停歇直到捕捉到它。","t":101.06},{"en":"Sometimes the yeast within a writer outlives a book he has written.","zh":"有时，作家内心的“酵母”比他写的一本书活得更久。","t":106.68},{"en":"I have heard of writers who read nothing but their own books;","zh":"我听说过有些作家除了自己的书什么都不读；","t":112.77},{"en":"like adolescents they stand before the mirror,","zh":"他们像青少年一样站在镜子前，","t":117.01},{"en":"and still cannot fathom the exact outline of the vision before them.","zh":"却仍然无法完全理解眼前景象的精确轮廓。","t":120.46},{"en":"For the same reason, writers talk interminably about their own books,","zh":"出于同样的原因，作家们滔滔不绝地谈论自己的书，","t":126.15},{"en":"winkling out hidden meanings, super-imposing new ones,","zh":"挖掘隐藏的意义，叠加新的意义，","t":132.37},{"en":"begging response from those around them.","zh":"乞求周围人的回应。","t":137.19},{"en":"Of course a writer doing this is misunderstood: he might as well try to explain a crime or a love affair.","zh":"当然，这样做会使作家被误解：他倒不如去解释一起犯罪或一段恋情。","t":140.57},{"en":"He is also, incidentally, an unforgivable bore.","zh":"顺便说一句，他也是一个不可原谅的无聊之人。","t":148.15},{"en":"This temptation to cover the distance between himself and the reader,","zh":"这种弥合自己与读者之间距离的诱惑，","t":154.63},{"en":"to study his image in the sight of those who do not know him, can be his undoing: he has begun to write to please.","zh":"在不认识他的人眼中审视自己的形象，可能会导致他的失败：他已经开始为了取悦他人而写作。","t":159.63},{"en":"A young English writer made the pertinent observation a year or two back","zh":"一两年前，一位年轻的英国作家发表了中肯的评论，","t":171.65},{"en":"that the talent goes into the first draft, and the art into the drafts that follow.","zh":"才能体现在初稿中，而艺术则体现在后续的草稿中。","t":176.85},{"en":"For this reason also the writer, like any other artist,","zh":"也正是因为这个原因，作家，像其他任何艺术家一样，","t":183.6},{"en":"has no resting place, no crowd or movement in which he may take comfort,","zh":"没有安身之所，没有可以从中寻求慰藉的人群或运动，","t":188.09},{"en":"no judgment from outside which can replace the judgment from within.","zh":"没有外部的评判能够取代其内在的评判。","t":195.18},{"en":"A writer makes order out of the anarchy of his heart;","zh":"作家从内心无序的状态中创造出秩序；","t":200.66},{"en":"he submits himself to a more ruthless discipline than any critic dreamed of,","zh":"他让自己服从于一种比任何评论家所梦想的都更无情的纪律，","t":204.7},{"en":"and when he flirts with fame, he is taking time off from living with himself,","zh":"当他追逐名利时，他是在从与自我共处中抽身，","t":210.73},{"en":"from the search for what his world contains at its inmost point.","zh":"从寻找他世界最深处包含的东西中抽身。","t":216.7}],"vocab":[{"word":"confess","phonetic":"/kənˈfes/","meanings":[{"pos":"verb","meaning":"承认；坦白","usage":"指坦率承认自己的过错、秘密或真实想法，后可接that从句、to doing sth结构"}]},{"word":"radical","phonetic":"/ˈrædɪkl/","meanings":[{"pos":"adjective","meaning":"根本的；彻底的","usage":"强调变化、差异等程度极深，涉及事物的本质层面"},{"pos":"noun","meaning":"激进分子","usage":"指主张极端社会或政治变革的人"}]},{"word":"reset","phonetic":"/ˌriːˈset/","meanings":[{"pos":"verb","meaning":"重新设置；重写","usage":"可表示调整设备参数、重新安排计划，也可指对文学作品内容进行大幅调整"}]},{"word":"discern","phonetic":"/dɪˈsɜːn/","meanings":[{"pos":"verb","meaning":"辨明；觉察出","usage":"指经过仔细观察、思考后识别出原本模糊或隐藏的事物"}]},{"word":"indescribable","phonetic":"/ˌɪndɪˈskraɪbəbl/","meanings":[{"pos":"adjective","meaning":"难以形容的；无法描述的","usage":"用于修饰感受、景象等强烈到难以用语言表达的事物"}]},{"word":"fascination","phonetic":"/ˌfæsɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"魅力；入迷","usage":"不可数名词，可表示事物本身的吸引力，也可指人对某物的着迷状态，后常接介词for/with"}]},{"word":"blurred","phonetic":"/blɜːd/","meanings":[{"pos":"adjective","meaning":"模糊不清的","usage":"可形容图像、边界等视觉上的模糊，也可指记忆、概念等抽象事物的不清晰"}]},{"word":"fathom","phonetic":"/ˈfæðəm/","meanings":[{"pos":"verb","meaning":"透彻理解；弄清","usage":"强调理解复杂、神秘的事物，常用于否定句或疑问句中"},{"pos":"noun","meaning":"英寻（测量水深单位，约合1.8米）","usage":"航海领域的长度单位"}]},{"word":"interminably","phonetic":"/ɪnˈtɜːmɪnəbli/","meanings":[{"pos":"adverb","meaning":"没完没了地；冗长地","usage":"带有贬义，修饰持续时间过长、让人厌烦的动作"}]},{"word":"pertinent","phonetic":"/ˈpɜːtɪnənt/","meanings":[{"pos":"adjective","meaning":"相关的；中肯的","usage":"指言论、问题等与讨论的主题直接相关且有价值，后常接介词to"}]},{"word":"anarchy","phonetic":"/ˈænəki/","meanings":[{"pos":"noun","meaning":"混乱；无政府状态","usage":"可指社会缺乏政府管控的混乱状态，也可形容抽象事物的无序状态"}]},{"word":"ruthless","phonetic":"/ˈruːθləs/","meanings":[{"pos":"adjective","meaning":"无情的；严格的","usage":"可形容人冷漠绝情，也可形容规则、标准等非常严苛没有转圜余地"}]},{"word":"inmost","phonetic":"/ˈɪnməʊst/","meanings":[{"pos":"adjective","meaning":"内心深处的；最深处的","usage":"用于修饰想法、感受、地点等处于最核心、最隐秘的位置"}]}],"phrases":[{"phrase":"set pen to paper","usage":"表示开始写作、动笔的固定表达，语体偏正式","examples":[{"en":"She had been planning the story for months before she finally set pen to paper.","zh":"她为这个故事构思了好几个月，才终于动笔开始写。"}]},{"phrase":"pass for","usage":"表示“被当作；被误认为”，强调事物和实际标准有差距但被当成合格的或真实的","examples":[{"en":"In this small town, a simple meal of noodles and eggs passes for a luxury.","zh":"在这个小镇里，一顿简单的鸡蛋面都被当成奢侈的食物。"}]},{"phrase":"to my certain knowledge","usage":"插入语，意为“据我所知”，强调说话者对所说内容的真实性十分确定","examples":[{"en":"To my certain knowledge, he has never lied to anyone in the team.","zh":"据我所知，他从来没有对团队里的任何人撒过谎。"}]},{"phrase":"begin afresh","usage":"表示“重新开始；从头再来”，强调抛开之前的积累或错误重头做起","examples":[{"en":"After the failure of his first business, he moved to another city to begin afresh.","zh":"第一次创业失败后，他搬到了另一个城市从头开始。"}]},{"phrase":"winkle out","usage":"表示“挖掘出；费尽周折找出”，指付出努力得到隐藏的信息或事物","examples":[{"en":"The journalist spent three months trying to winkle out the truth behind the scandal.","zh":"这名记者花了三个月的时间，试图挖出这起丑闻背后的真相。"}]},{"phrase":"might as well","usage":"表示“倒不如；不妨”，用于建议做某事，或强调两种情况结果差不多、都没有意义","examples":[{"en":"Since the train is delayed for two hours, we might as well go to the café nearby to wait.","zh":"既然火车晚点了两个小时，我们倒不如去附近的咖啡馆等着。"}]},{"phrase":"take time off","usage":"表示“抽出时间；暂时放下（手头的事）”，后可接from sth说明停下的事情","examples":[{"en":"He decided to take time off from work to spend more time with his sick mother.","zh":"他决定暂时放下工作，花更多时间陪伴生病的母亲。"}]},{"phrase":"at its inmost point","usage":"表示“在其最核心处；在最深处”，用于描述事物或情感的本质层面","examples":[{"en":"The poem touches the vulnerability at the inmost point of human nature.","zh":"这首诗触及了人性最深处的脆弱。"}]}],"grammar":[{"title":"定语从句的连用","definition":"当先行词同时被多个定语从句修饰时，多个定语从句可以并列连接，共同限定先行词的范围","structure":"先行词 + 定语从句1 + and + 定语从句2","usage":"用于从多个角度描述同一个先行词，丰富先行词的信息","examples":[{"en":"but those I have known and whom I respect, confess at once that they have little idea where they are going when they first set pen to paper.","zh":"但我所认识的、我所尊敬的那些作家，都立刻承认他们刚动笔的时候，根本不知道自己要写什么。"},{"en":"The books that my father collected and which he kept for years were all donated to the village library.","zh":"我父亲收集的、珍藏了很多年的那些书，全都捐给了乡村图书馆。"}]},{"title":"as引导的方式状语从句","definition":"as引导方式状语从句时，意为“正如；按照”，用于说明主从句动作的方式一致","structure":"主句 + as + 从句","usage":"常用来引出人们已知的事实、常规做法等，和主句的内容形成对比或参照","examples":[{"en":"I never heard of anyone making a 'skeleton', as we were taught at school.","zh":"我从来没听说过有人像我们在学校里被教的那样，先写个“提纲”。"},{"en":"Please do the experiment as the teacher demonstrated in class.","zh":"请按照老师课上演示的那样做这个实验。"}]},{"title":"which引导的非限制性定语从句","definition":"非限制性定语从句用来对先行词或者整个主句的内容进行补充说明，和主句之间用逗号隔开，去掉从句后主句意思依然完整","structure":"主句, which + 从句内容","usage":"用于补充额外信息，which可以指代前面的单个名词，也可以指代整个主句的内容","examples":[{"en":"This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination.","zh":"这种有机的过程，常常会带来非同寻常的自我发现时刻，有着难以形容的魅力。"},{"en":"She finally passed the driving test, which made her whole family very happy.","zh":"她终于通过了驾照考试，这让她全家人都很高兴。"}]}],"patterns":[{"pattern":"I have known very few + 名词, but those I have known and whom I respect, confess at once that + 从句","explanation":"","original":{"en":"I have known very few writers, but those I have known and whom I respect, confess at once that they have little idea where they are going when they first set pen to paper.","zh":"我认识的作家很少，但我所认识的、我所尊敬的那些作家，都立刻承认他们刚动笔的时候，根本不知道自己要写什么。"},"examples":[{"en":"I have known very few traditional craftsmen, but those I have known and whom I respect, confess at once that they spend at least three years mastering the basic skills.","zh":"我认识的传统手艺人很少，但我所认识的、我所尊敬的那些手艺人，都立刻承认他们要花至少三年时间才能掌握基础技艺。"},{"en":"I have known very few successful entrepreneurs, but those I have known and whom I respect, confess at once that they have faced countless failures before achieving their goals.","zh":"我认识的成功企业家很少，但我所认识的、我所尊敬的那些企业家，都立刻承认他们在达成目标前曾遭遇过无数次失败。"}]},{"pattern":"For the same reason, + 主句内容, doing sth, to do sth, begging response from sb","explanation":"","original":{"en":"For the same reason, writers talk interminably about their own books, winkling out hidden meanings, super-imposing new ones, begging response from those around them.","zh":"出于同样的原因，作家们没完没了地谈论自己的书，挖掘其中隐藏的含义，叠加新的解读，渴望从身边的人那里得到回应。"},"examples":[{"en":"For the same reason, young designers talk excitedly about their new works, explaining their original ideas, adjusting details according to feedback, begging recognition from the audience.","zh":"出于同样的原因，年轻的设计师们兴奋地谈论自己的新作品，解释他们的原创理念，根据反馈调整细节，渴望得到观众的认可。"},{"en":"For the same reason, students share their creative projects in class, showing the process of exploration, pointing out the innovations of their work, begging advice from the teacher.","zh":"出于同样的原因，学生们在课堂上分享自己的创意项目，展示探索的过程，指出作品的创新之处，渴望得到老师的建议。"}]},{"pattern":"A + 身份名词 + made the pertinent observation + 时间状语 that + 观察结论","explanation":"","original":{"en":"A young English writer made the pertinent observation a year or two back that the talent goes into the first draft, and the art into the drafts that follow.","zh":"一两年前，一位年轻的英国作家给出了一个中肯的看法：才华体现在初稿里，而艺术则体现在后续的修改稿中。"},"examples":[{"en":"A senior education expert made the pertinent observation last year that the core of quality education is to cultivate children's ability to learn independently.","zh":"去年，一位资深的教育专家给出了一个中肯的看法：素质教育的核心是培养孩子自主学习的能力。"},{"en":"A famous environmental scientist made the pertinent observation a few months ago that reducing single-use plastic is more effective than recycling in controlling plastic pollution.","zh":"几个月前，一位著名的环境科学家给出了一个中肯的看法：在治理塑料污染方面，减少一次性塑料的使用比回收更有效。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“混乱；无政府状态” 对应的单词是？","hint":"noun · /ˈænəki/","options":["initiative","anarchy","tremor","interminably"],"answer":1,"explain":"anarchy · /ˈænəki/ · noun · 混乱；无政府状态。可指社会缺乏政府管控的混乱状态，也可形容抽象事物的无序状态","source":{"kind":"vocab","word":"anarchy"},"id":"b4-u39-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Since the train is delayed for two hours, we _____ go to the café nearby to wait.","hint":"既然火车晚点了两个小时，我们倒不如去附近的咖啡馆等着。","answer":"might as well","placeholder":"输入缺失的短语","explain":"might as well：表示“倒不如；不妨”，用于建议做某事，或强调两种情况结果差不多、都没有意义（既然火车晚点了两个小时，我们倒不如去附近的咖啡馆等着。）","source":{"kind":"phrase","phrase":"might as well"},"id":"b4-u39-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：He is also, incidentally, an _____ bore.","hint":"顺便说一句，他也是一个不可原谅的无聊之人。","answer":"unforgivable","placeholder":"输入缺失的单词","explain":"He is also, incidentally, an unforgivable bore. — 顺便说一句，他也是一个不可原谅的无聊之人。","source":{"kind":"sentence","en":"He is also, incidentally, an unforgivable bore."},"id":"b4-u39-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“非限制性定语从句用来对先行词或者整个主句的内容进行补充说明，和主句之间用逗号隔开，去掉从句后主句意思依然完整” 描述的是哪个语法点？","hint":"主句, which + 从句内容","options":["并列状语成分的使用","if引导的非真实条件句（虚拟语气）","非限定性定语从句 (Non-restrictive Attributive Clause)","which引导的非限制性定语从句"],"answer":3,"explain":"which引导的非限制性定语从句：主句, which + 从句内容：用于补充额外信息，which可以指代前面的单个名词，也可以指代整个主句的内容","source":{"kind":"grammar","title":"which引导的非限制性定语从句"},"id":"b4-u39-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThis organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination.","hint":"","options":["这种有机过程，常常带来非凡的自我发现时刻，具有难以言喻的魅力。","我就像一个庞大校园里的新生，","在不认识他的人眼中审视自己的形象，可能会导致他的失败：他已经开始为了取悦他人而写作。","威廉·S·哈特也许是所有西部片明星中最伟大的。"],"answer":0,"explain":"This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. — 这种有机过程，常常带来非凡的自我发现时刻，具有难以言喻的魅力。","source":{"kind":"sentence","en":"This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination."},"id":"b4-u39-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 11 个单词","answer":"In the breaking and remaking, in the timing interweaving, beginning afresh,","placeholder":"输入完整英文句子","explain":"In the breaking and remaking, in the timing interweaving, beginning afresh, — 在打破与重塑、适时交织、重新开始的过程中，","playText":"In the breaking and remaking, in the timing interweaving, beginning afresh,","source":{"kind":"sentence","en":"In the breaking and remaking, in the timing interweaving, beginning afresh,"},"id":"b4-u39-q06"}]},{"id":"b4-u40","book":4,"unit":40,"key":"40","lessonFrom":40,"lessonTo":40,"title":"Waves","titleZh":"波浪","question":"What false impression does an ocean wave convey to the observer?","sentences":[{"en":"Waves are the children of the struggle between ocean and atmosphere, the ongoing signatures of infinity.","zh":"波浪是海洋与大气搏斗的产物，是永恒的无限的印记。","t":15.37},{"en":"Rays from the sun excite and energize the atmosphere of the earth, awakening it to flow, to movement, to rhythm, to life.","zh":"太阳的光线激发并激活了地球的大气层，使其流动、运动、有节奏、有生命。","t":23.26},{"en":"The wind then speaks the message of the sun to the sea","zh":"风将太阳的信息传递给大海","t":33.29},{"en":"and the sea transmits it on through waves--an ancient, exquisite powerful message.","zh":"大海通过波浪将其传递出去——一个古老、精致、有力的信息。","t":37.2},{"en":"These ocean waves are among the earth's most complicated natural phenomena.","zh":"这些海浪是地球上最复杂的自然现象之一。","t":45.48},{"en":"The basic features include a crest (the highest point of the wave),","zh":"基本特征包括波峰（波浪的最高点），","t":51.45},{"en":"a trough (the lowest point), a height (the vertical distance from the trough to the crest),","zh":"波谷（最低点），波高（从波谷到波峰的垂直距离），","t":56.13},{"en":"a wave length (the horizontal distance between two wave crests),","zh":"波长（两个波峰之间的水平距离），","t":63.67},{"en":"and a period (which is the time it takes awave crest to travel one wave length).","zh":"和周期（波峰传播一个波长所需的时间）。","t":68.99},{"en":"Although an ocean wave gives the impression of a wall of water moving in your direction,","zh":"尽管海浪给人一种水墙向你移动的印象，","t":76.21},{"en":"in actuality waves move through the water leaving the water about where it was.","zh":"但实际上，波浪穿过水体，使水大致停留在原来的位置。","t":82.46},{"en":"If the water was moving with the wave,","zh":"如果水体随波浪移动，","t":89.36},{"en":"the ocean and everything on it would be racing in to the shore with obviously catastrophic results.","zh":"海洋和其上的一切都会冲向海岸，显然会造成灾难性的后果。","t":92.06},{"en":"An ocean wave passing through deep water causes a particle on the surface to move in a roughly circular orbit,","zh":"海浪穿过深水时，会使水面上的粒子呈近似圆形轨道运动，","t":100.03},{"en":"drawing the particle first towards the advancing wave, then up into the wave,","zh":"首先将粒子拉向前进的波浪，然后向上进入波浪，","t":108.49},{"en":"then forward with it and then--as the wave leaves the particles behind--back to its starting point again.","zh":"然后随波浪向前，接着——当波浪将粒子留在身后时——回到其起始点。","t":114.41},{"en":"From both maturity to death, a wave is subject to the same laws as any other 'living' thing.","zh":"从形成到消亡，波浪与任何其他“有生命”的事物一样，都遵循相同的规律。","t":123.3},{"en":"For a time it assumes a miraculous individuality that, in the end, is reabsorbed into the great ocean of life.","zh":"在一段时间内，它呈现出奇妙的个体性，最终又重新融入生命的浩瀚海洋。","t":130.15},{"en":"The undulating waves of the open sea are generated by three natural causes:","zh":"开阔海域的波浪由三种自然原因产生：","t":139.11},{"en":"wind, earth movements or tremors, and the gravitational pull of the moon and the sun.","zh":"风、地壳运动或震动，以及月亮和太阳的引力。","t":145.25},{"en":"Once waves have been generated,","zh":"一旦波浪产生，","t":151.95},{"en":"gravity is the force that drives them in a continual attempt to restore the ocean surface to a flat plain.","zh":"引力便是驱使它们不断尝试将海洋表面恢复到平坦状态的力量。","t":154.14}],"vocab":[{"word":"signature","phonetic":"/ˈsɪɡnətʃə(r)/","meanings":[{"pos":"noun","meaning":"标志；特征；签名","usage":"可指人或事物独有的、可识别的特征，也可指手写签名"}]},{"word":"infinity","phonetic":"/ɪnˈfɪnəti/","meanings":[{"pos":"noun","meaning":"无限；无穷","usage":"表示没有边界、尽头的状态，常用来描述时间、空间等抽象概念"}]},{"word":"energize","phonetic":"/ˈenədʒaɪz/","meanings":[{"pos":"verb","meaning":"使充满活力；给…提供能量","usage":"主语可以是自然能量，也可以是能给人带来动力的事物，宾语多为人或抽象事物"}]},{"word":"rhythm","phonetic":"/ˈrɪðəm/","meanings":[{"pos":"noun","meaning":"节奏；律动","usage":"可指音乐的节奏，也可指自然事物、生活等有规律的运动模式"}]},{"word":"exquisite","phonetic":"/ɪkˈskwɪzɪt/","meanings":[{"pos":"adjective","meaning":"精美的；细腻的；强烈的","usage":"多用来修饰事物的精致度，也可形容感受的强烈程度"}]},{"word":"phenomenon","phonetic":"/fəˈnɒmɪnən/","meanings":[{"pos":"noun","meaning":"现象","usage":"指可观察到的自然或社会现象，复数形式为phenomena"}]},{"word":"crest","phonetic":"/krest/","meanings":[{"pos":"noun","meaning":"浪尖；顶峰；羽冠","usage":"可指波浪的最高点，也可引申为事物发展的巅峰阶段"}]},{"word":"trough","phonetic":"/trɒf/","meanings":[{"pos":"noun","meaning":"波谷；低谷；饲料槽","usage":"是crest的反义词，可指波浪的最低点，也可引申为经济、情绪等的低迷阶段"}]},{"word":"vertical","phonetic":"/ˈvɜːtɪkl/","meanings":[{"pos":"adjective","meaning":"垂直的；竖直的","usage":"描述与水平面垂直的方向，反义词是horizontal（水平的）"}]},{"word":"horizontal","phonetic":"/ˌhɒrɪˈzɒntl/","meanings":[{"pos":"adjective","meaning":"水平的；横的","usage":"描述与水平面平行的方向，反义词是vertical（垂直的）"}]},{"word":"catastrophic","phonetic":"/ˌkætəˈstrɒfɪk/","meanings":[{"pos":"adjective","meaning":"灾难性的；毁灭性的","usage":"用来修饰后果、事件等，强调破坏程度非常严重"}]},{"word":"particle","phonetic":"/ˈpɑːtɪkl/","meanings":[{"pos":"noun","meaning":"颗粒；微粒","usage":"多指物理中的微小粒子，也可指物质的细小碎块"}]},{"word":"orbit","phonetic":"/ˈɔːbɪt/","meanings":[{"pos":"noun","meaning":"轨道；势力范围","usage":"可指天体运行的轨道，也可引申为人或事物的活动范围"},{"pos":"verb","meaning":"绕…运行","usage":"主语为天体、卫星等，宾语为绕行的中心天体"}]},{"word":"tremor","phonetic":"/ˈtremə(r)/","meanings":[{"pos":"noun","meaning":"轻微地震；颤动；颤抖","usage":"可指地壳的微小震动，也可指人因情绪、疾病产生的身体颤抖"}]},{"word":"gravitational","phonetic":"/ˌɡrævɪˈteɪʃənl/","meanings":[{"pos":"adjective","meaning":"重力的；引力的","usage":"为物理领域形容词，多用来修饰与引力相关的名词，如pull, force等"}]}],"phrases":[{"phrase":"be subject to","usage":"表示“受…支配；易遭受…；取决于…”，to为介词，后接名词或动名词","examples":[{"en":"From both maturity to death, a wave is subject to the same laws as any other 'living' thing.","zh":"从成熟到消亡，波浪和其他任何“有生命”的事物一样，都受相同的规律支配。"},{"en":"All flights are subject to delay due to the bad weather.","zh":"受恶劣天气影响，所有航班都有可能延误。"}]},{"phrase":"give the impression of","usage":"表示“给人…的印象”，后可接名词、动名词或that从句","examples":[{"en":"Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality waves move through the water leaving the water about where it was.","zh":"尽管海浪给人的印象是一堵水墙朝你移动，但实际上波浪穿过水体，而水本身几乎留在原位。"},{"en":"He gives the impression of being a very hardworking person.","zh":"他给人的印象是一个非常勤奋的人。"}]},{"phrase":"in actuality","usage":"表示“实际上；事实上”，为书面用语，可替换in fact, actually","examples":[{"en":"The team seemed to be in control of the match, but in actuality they were under great pressure.","zh":"这支球队看起来掌控了比赛，但实际上他们承受着巨大的压力。"}]},{"phrase":"assume a ... individuality","usage":"表示“呈现出…的特质/个性”，assume在这里意为“呈现（外观、特质）”","examples":[{"en":"For a time it assumes a miraculous individuality that, in the end, is reabsorbed into the great ocean of life.","zh":"有那么一段时间，它呈现出一种不可思议的独特性，而最终又会被重新吸纳入生命的汪洋之中。"},{"en":"The city assumes a romantic individuality when the neon lights are on at night.","zh":"夜晚霓虹灯亮起时，这座城市呈现出一种浪漫的独特气质。"}]},{"phrase":"restore ... to ...","usage":"表示“使…恢复到…状态”，restore为及物动词，后接要恢复的对象，to后接目标状态","examples":[{"en":"Gravity is the force that drives them in a continual attempt to restore the ocean surface to a flat plain.","zh":"重力是驱动它们不断尝试将海面恢复为平坦平面的力量。"},{"en":"The volunteers helped to restore the old building to its original appearance.","zh":"志愿者们帮忙将这栋老建筑恢复到了它最初的样貌。"}]},{"phrase":"transmit ... on through","usage":"表示“通过…传递下去”，transmit意为“传输、传递”，on强调传递的延续性","examples":[{"en":"The sea transmits it on through waves--an ancient, exquisite powerful message.","zh":"海洋通过波浪将这个信息传递下去——这是一个古老、优美而充满力量的信息。"},{"en":"The culture is transmitted on through generations of folk artists.","zh":"这种文化通过一代又一代的民间艺人传承了下来。"}]}],"grammar":[{"title":"虚拟语气（与现在事实相反的情况）","definition":"用来描述与当前实际情况不相符的假设，表达假想、愿望等含义","structure":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","usage":"当假设的条件不可能在现在发生，或者与现在的事实相反时，使用该结构","examples":[{"en":"If the water was moving with the wave, the ocean and everything on it would be racing in to the shore with obviously catastrophic results.","zh":"如果水和浪一起移动的话，那么大海和海里所有的东西都会向岸边疾冲过来，显然会带来灾难性的后果。"},{"en":"If I were you, I would choose to study abroad after graduation.","zh":"如果我是你，我会选择毕业后出国留学。"}]},{"title":"现在分词作伴随状语","definition":"现在分词在句中表示与主句动作同时发生的伴随性动作，其逻辑主语与主句主语一致","structure":"主句 + , 现在分词短语","usage":"用来补充说明主句动作发生时的伴随情况，使句子更加简洁紧凑","examples":[{"en":"Rays from the sun excite and energize the atmosphere of the earth, awakening it to flow, to movement, to rhythm, to life.","zh":"太阳的光线激发并赋予地球大气能量，唤醒它流动、运动、产生律动、获得生命。"},{"en":"The little girl sat under the tree, reading a picture book carefully.","zh":"小女孩坐在树下，认真地读着一本绘本。"}]}],"patterns":[{"pattern":"A are the children of the struggle between B and C, the ongoing signatures of D.","explanation":"","original":{"en":"Waves are the children of the struggle between ocean and atmosphere, the ongoing signatures of infinity.","zh":"海浪是海洋和大气相互作用的产物，是永恒无限的持续标志。"},"examples":[{"en":"Dunes are the children of the struggle between desert and wind, the ongoing signatures of time.","zh":"沙丘是沙漠和风相互作用的产物，是时间流逝的持续标志。"},{"en":"Fossils are the children of the struggle between organisms and geology, the ongoing signatures of evolution.","zh":"化石是生物和地质作用相互影响的产物，是生物进化的持续标志。"}]},{"pattern":"Although A gives the impression of B, in actuality C.","explanation":"","original":{"en":"Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality waves move through the water leaving the water about where it was.","zh":"尽管海浪给人的印象是一堵水墙朝你移动，但实际上波浪穿过水体，而水本身几乎留在原位。"},"examples":[{"en":"Although the cartoon gives the impression of being only for children, in actuality it contains many deep thoughts for adults.","zh":"尽管这部动画片给人的印象是只适合儿童观看，但实际上它包含了很多适合成年人思考的深刻内容。"},{"en":"Although this method gives the impression of being inefficient, in actuality it can save a lot of time in the long run.","zh":"尽管这个方法给人的印象效率很低，但实际上从长远来看它能节省很多时间。"}]},{"pattern":"A are generated by three natural causes: B, C, and D.","explanation":"","original":{"en":"The undulating waves of the open sea are generated by three natural causes: wind, earth movements or tremors, and the gravitational pull of the moon and the sun.","zh":"公海上起伏的波浪是由三个自然因素产生的：风、地壳运动或地震，以及月球和太阳的引力。"},"examples":[{"en":"The rich soil of the plain is generated by three natural causes: alluvial deposits of rivers, weathering of rocks, and decomposition of plants and animals.","zh":"平原肥沃的土壤是由三个自然因素形成的：河流的冲积、岩石的风化，以及动植物的腐解。"},{"en":"The amazing aurora near the poles is generated by three natural causes: solar wind, earth's magnetic field, and gas particles in the atmosphere.","zh":"极地附近的绚丽极光由三个自然因素产生：太阳风、地球磁场，以及大气中的气体粒子。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“重力的；引力的” 对应的单词是？","hint":"adjective · /ˌɡrævɪˈteɪʃənl/","options":["frantically","gravitational","indisposition","pension"],"answer":1,"explain":"gravitational · /ˌɡrævɪˈteɪʃənl/ · adjective · 重力的；引力的。为物理领域形容词，多用来修饰与引力相关的名词，如pull, force等","source":{"kind":"vocab","word":"gravitational"},"id":"b4-u40-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：水平的；横的","hint":"/ˌhɒrɪˈzɒntl/ · adjective","answer":"horizontal","placeholder":"输入英文单词","explain":"horizontal · /ˌhɒrɪˈzɒntl/ · adjective · 水平的；横的。描述与水平面平行的方向，反义词是vertical（垂直的）","source":{"kind":"vocab","word":"horizontal"},"id":"b4-u40-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The team seemed to be in control of the match, but _____ they were under great pressure.","hint":"这支球队看起来掌控了比赛，但实际上他们承受着巨大的压力。","answer":"in actuality","placeholder":"输入缺失的短语","explain":"in actuality：表示“实际上；事实上”，为书面用语，可替换in fact, actually（这支球队看起来掌控了比赛，但实际上他们承受着巨大的压力。）","source":{"kind":"phrase","phrase":"in actuality"},"id":"b4-u40-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The undulating _____ of the open sea are generated by three natural causes:","hint":"开阔海域的波浪由三种自然原因产生：","answer":"waves","placeholder":"输入缺失的单词","explain":"The undulating waves of the open sea are generated by three natural causes: — 开阔海域的波浪由三种自然原因产生：","source":{"kind":"sentence","en":"The undulating waves of the open sea are generated by three natural causes:"},"id":"b4-u40-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“现在分词在句中表示与主句动作同时发生的伴随性动作，其逻辑主语与主句主语一致” 描述的是哪个语法点？","hint":"主句 + , 现在分词短语","options":["时间状语从句的省略","方式状语从句","现在分词作伴随状语","现在分词作结果状语"],"answer":2,"explain":"现在分词作伴随状语：主句 + , 现在分词短语：用来补充说明主句动作发生时的伴随情况，使句子更加简洁紧凑","source":{"kind":"grammar","title":"现在分词作伴随状语"},"id":"b4-u40-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nand the sea transmits it on through waves--an ancient, exquisite powerful message.","hint":"","options":["国王古斯塔夫·阿道夫，人称“北方飓风”，","理想主义者反对露营，就像反对跟团游一样，","我们无法跳出我们大脑被制约的特定模式进行思考，或者说，","大海通过波浪将其传递出去——一个古老、精致、有力的信息。"],"answer":3,"explain":"and the sea transmits it on through waves--an ancient, exquisite powerful message. — 大海通过波浪将其传递出去——一个古老、精致、有力的信息。","source":{"kind":"sentence","en":"and the sea transmits it on through waves--an ancient, exquisite powerful message."},"id":"b4-u40-q06"}]},{"id":"b4-u41","book":4,"unit":41,"key":"41","lessonFrom":41,"lessonTo":41,"title":"Training Elephants","titleZh":"训练大象","question":"At what point does the training of a captive wild elephant begin?","sentences":[{"en":"Two main techniques have been used for training elephants, which we may call respectively the tough and the gentle.","zh":"训练大象主要有两种方法，我们可以分别称之为“严酷法”和“温和法”。","t":17.74},{"en":"The former method simply consists of setting an elephant to work and beating him until he does what is expected of him.","zh":"前一种方法就是让一头大象去干活，然后鞭打它，直到它按要求去做。","t":27.25},{"en":"Apart from any moral considerations this is a stupid method of training,","zh":"撇开所有道德因素不谈，这是一种愚蠢的训练方法，","t":36.67},{"en":"for it produces a resentful animal who at a later stage may well turn man-killer.","zh":"因为它会使动物心怀怨恨，而且在以后很可能会成为“杀人犯”。","t":42.29},{"en":"The gentle method requires more patience in the early stages,","zh":"温和法在早期阶段需要更多的耐心，","t":49.31},{"en":"but produce a cheerful good-tempered elephant who will give many years of loyal service.","zh":"但它会培养出性情愉快、脾气温顺的大象，这种大象会提供多年的忠诚服务。","t":53.72},{"en":"The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job.","zh":"训练大象的首要任务是给它指派一位驯象师，由他全权负责这项工作。","t":61.86},{"en":"Elephants like to have one master just as dogs do, and are capable of a considerable degree of personal affection.","zh":"大象像狗一样喜欢只有一个主人，并且能够产生相当程度的个人感情。","t":72.02},{"en":"There are even stories of half-trained elephant calves who have refused to feed and pined to death","zh":"甚至有这样的故事：一些半驯化的小象，它们拒绝进食并悲伤而死，","t":81.71},{"en":"when by some unavoidable circumstance they have been deprived of their own trainer.","zh":"当它们因某些不可避免的情况失去了自己的驯象师时。","t":90.54},{"en":"Such extreme cases must probably be taken with a grain of salt,","zh":"这种极端的例子也许不能完全相信，","t":98.41},{"en":"but they do underline the general principle that the relationship between elephant and mahout is the key to successful training.","zh":"但它们确实强调了一个普遍原则：驯象师与大象之间的关系是训练成功的关键。","t":103.26},{"en":"The most economical age to capture an elephant for training is between 15 and 20 years,","zh":"捕获大象进行训练最经济的年龄是15到20岁之间，","t":114.24},{"en":"for it is then almost ready to undertake heavy work and can begin to earn its keep straight away.","zh":"因为这个年龄段的大象几乎已经准备好承担重活，可以立即开始赚钱养活自己。","t":121.53},{"en":"But animals of this age do not easily become subservient to man, and a very firm hand must be employed in the early stages.","zh":"但这个年龄的动物不容易顺从人类，所以在早期阶段必须采用非常强硬的手段。","t":129.29},{"en":"The captive elephant, still roped to a tree,","zh":"被俘获的大象，仍然被绳子系在一棵树上，","t":139.42},{"en":"plunges and screams every time a man approaches, and for several days will probably refuse all food through anger and fear.","zh":"每当有人靠近，它就会猛冲并尖叫，而且好几天可能会因愤怒和恐惧而拒绝所有食物。","t":142.74},{"en":"Sometimes a tame elephant is tethered nearby to give the wild one confidence,","zh":"有时，一头驯服的大象会被拴在附近，以给野象信心，","t":154.27},{"en":"and in most cases the captive gradually quietens down and begins to accept its food.","zh":"在大多数情况下，被俘获的大象会逐渐平静下来，并开始接受食物。","t":160.27},{"en":"The next stage is to get the elephant to the training establishment,","zh":"下一个阶段是将大象带到训练机构，","t":167.81},{"en":"a ticklish business which is achieved with the aid of two tame elephants roped to the captive on either side.","zh":"这是一项棘手的工作，需要两头驯服的大象分别系在被俘获的大象两侧来完成。","t":171.87},{"en":"When several elephants are being trained at one time,","zh":"当几头大象同时被训练时，","t":179.97},{"en":"it is customary for the new arrival to be placed between the stalls of two captives whose training is already well advanced.","zh":"习惯上会将新来的大象放置在两头已经训练有素的被俘大象的兽栏之间。","t":184.05},{"en":"It is then left completely undisturbed with plenty of food and water","zh":"然后它被完全地置于安静的环境中，提供充足的食物和水，","t":193.88},{"en":"so that it can absorb the atmosphere of its new home and see that nothing particularly alarming is happening to its companions.","zh":"这样它就能适应新家的环境，并看到它的同伴们没有发生什么特别令人担忧的事情。","t":199.15},{"en":"When it is eating normally, its own training begins.","zh":"当它正常进食时，它自己的训练就开始了。","t":208.39},{"en":"The trainer stands in front of the elephant holding a long stick with a sharp metal point.","zh":"驯象师站在大象前面，手持一根带有锋利金属尖头的长棍。","t":213.27},{"en":"Two assistants, mounted on tame elephants, control the captive from either side,","zh":"两名助手骑在驯服的大象上，从两侧控制被俘获的大象，","t":219.7},{"en":"while others rub their hands over his skin to the accompaniment of a monotonous and soothing chant.","zh":"同时其他人则在大象的皮肤上摩擦双手，并伴随着单调而舒缓的歌谣。","t":226.63},{"en":"This is supposed to induce pleasurable sensations in the elephant,","zh":"这应该在大象身上引起愉悦的感觉，","t":235.06},{"en":"and its effects are reinforced by the use of endearing epithets,","zh":"它的效果通过使用亲切的称呼得到加强，","t":239.73},{"en":"such as 'ho! my son', or 'ho! my father', or 'my mother', according to the age and sex of the captive.","zh":"比如“嘿！我的孩子”，“嘿！我的父亲”，或者“我的母亲”，这取决于被俘大象的年龄和性别。","t":243.69},{"en":"The elephant is not immediately susceptible to such blandishments, however, and usually lashes fiercely with its trunk in all directions.","zh":"然而，大象不会立即屈服于这种哄骗，通常会用象鼻猛烈地向四面八方挥舞。","t":255.71},{"en":"These movements are controlled by the trainer with the metal-pointed stick,","zh":"这些动作由驯象师用金属尖头棍控制，","t":265.47},{"en":"and the trunk eventually becomes so sore that the elephant curls it up and seldom afterwards uses it for offensive purposes.","zh":"象鼻最终会变得非常疼痛，以至于大象会把它卷起来，并且之后很少用于攻击目的。","t":270.01}],"vocab":[{"word":"captive","phonetic":"/ˈkæptɪv/","meanings":[{"pos":"adjective","meaning":"被俘虏的；被圈养的","usage":"修饰动物或人，指失去自由、被关起来的状态"},{"pos":"noun","meaning":"俘虏；被捕获的动物","usage":"指被关押或圈养的对象"}]},{"word":"respectively","phonetic":"/rɪˈspektɪvli/","meanings":[{"pos":"adverb","meaning":"分别地；各自地","usage":"用于按顺序对应前面提到的两个或多个事物"}]},{"word":"resentful","phonetic":"/rɪˈzentfl/","meanings":[{"pos":"adjective","meaning":"愤恨的；不满的","usage":"用来描述人或动物因受不公对待而产生怨恨情绪的状态"}]},{"word":"assign","phonetic":"/əˈsaɪn/","meanings":[{"pos":"verb","meaning":"分配；指派","usage":"常用结构assign sb. to sth./to do sth.，表示分派某人做某项工作或负责某个对象"}]},{"word":"mahout","phonetic":"/məˈhaʊt/","meanings":[{"pos":"noun","meaning":"驯象人；象夫","usage":"特指以训练、看管大象为职业的人"}]},{"word":"affection","phonetic":"/əˈfekʃn/","meanings":[{"pos":"noun","meaning":"喜爱；感情","usage":"不可数名词，指对人或事物的喜爱、眷恋之情，常与for/to搭配"}]},{"word":"pine","phonetic":"/paɪn/","meanings":[{"pos":"verb","meaning":"（因悲伤、思念而）憔悴；消瘦","usage":"常用搭配pine for sb./sth.表示思念，pine away表示日渐消瘦"}]},{"word":"deprive","phonetic":"/dɪˈpraɪv/","meanings":[{"pos":"verb","meaning":"剥夺；使丧失","usage":"固定搭配deprive sb. of sth.，表示夺去某人原本拥有的东西"}]},{"word":"underline","phonetic":"/ˌʌndəˈlaɪn/","meanings":[{"pos":"verb","meaning":"强调；突出","usage":"引申义为突出某个事实或观点的重要性，相当于emphasize"}]},{"word":"subservient","phonetic":"/səbˈsɜːviənt/","meanings":[{"pos":"adjective","meaning":"屈从的；恭顺的","usage":"常与to搭配，指愿意服从他人命令的状态"}]},{"word":"plunge","phonetic":"/plʌndʒ/","meanings":[{"pos":"verb","meaning":"猛冲；剧烈扭动","usage":"指动物或人突然用力地向前冲、扭动身体的动作"}]},{"word":"tether","phonetic":"/ˈteðə(r)/","meanings":[{"pos":"verb","meaning":"（用绳子）拴住","usage":"特指用绳索把动物拴在某个固定物体上"}]},{"word":"ticklish","phonetic":"/ˈtɪklɪʃ/","meanings":[{"pos":"adjective","meaning":"棘手的；难处理的","usage":"形容问题或任务需要小心处理，稍有不慎就会出问题"}]},{"word":"soothing","phonetic":"/ˈsuːðɪŋ/","meanings":[{"pos":"adjective","meaning":"安慰的；舒缓的","usage":"形容声音、动作等能让人或动物情绪平静下来"}]},{"word":"blandishment","phonetic":"/ˈblændɪʃmənt/","meanings":[{"pos":"noun","meaning":"奉承；哄骗的话","usage":"常用复数形式，指为了让对方听从自己而说的好听的话"}]}],"phrases":[{"phrase":"apart from","usage":"介词短语，可表示“除了……之外（还）”或“除了……之外（都不）”，相当于besides或except for","examples":[{"en":"Apart from any moral considerations this is a stupid method of training.","zh":"且不说道德方面的考虑，这种训练方法本身就很愚蠢。"},{"en":"Apart from English, he also learns French and Japanese.","zh":"除了英语之外，他还学习法语和日语。"}]},{"phrase":"take sth. with a grain of salt","usage":"固定习语，表示对某事半信半疑，不完全相信","examples":[{"en":"Such extreme cases must probably be taken with a grain of salt.","zh":"这类极端案例可能不能完全当真。"},{"en":"You should take what he says with a grain of salt, he often exaggerates.","zh":"他说的话你得打个折扣听，他经常夸张。"}]},{"phrase":"earn one's keep","usage":"习语，意为“挣钱维持生计；值得雇佣”，指通过劳动抵消自己的生活成本","examples":[{"en":"It is then almost ready to undertake heavy work and can begin to earn its keep straight away.","zh":"这个年龄的大象差不多已经可以干重活，能立刻开始干活抵偿饲养成本了。"},{"en":"Even as a teenager, he did part-time jobs to earn his keep instead of relying on his parents.","zh":"甚至十几岁的时候，他就靠打零工养活自己，不依赖父母。"}]},{"phrase":"be deprived of","usage":"被动结构，表示“被剥夺……；失去……”，后接被夺走的事物","examples":[{"en":"They have been deprived of their own trainer.","zh":"他们被夺走了自己的驯象师。"},{"en":"Many children in remote areas are deprived of the right to receive education.","zh":"很多偏远地区的孩子被剥夺了受教育的权利。"}]},{"phrase":"to the accompaniment of","usage":"介词短语，表示“在……的伴奏下；伴随着……","examples":[{"en":"Others rub their hands over his skin to the accompaniment of a monotonous and soothing chant.","zh":"其他人一边摸着它的皮肤，一边唱着单调的、让人安心的歌谣。"},{"en":"The performance began to the accompaniment of warm applause.","zh":"演出在热烈的掌声中拉开了序幕。"}]},{"phrase":"be susceptible to","usage":"固定搭配，表示“易受……影响的；对……敏感的”，后接名词或动名词","examples":[{"en":"The elephant is not immediately susceptible to such blandishments.","zh":"大象并不会立刻就吃这套哄骗的把戏。"},{"en":"Babies are susceptible to colds when the weather changes suddenly.","zh":"天气骤变的时候，婴儿很容易感冒。"}]},{"phrase":"consist of","usage":"动词短语，意为“由……组成”，不用于被动语态，主语是整体，宾语是组成部分","examples":[{"en":"The former method simply consists of setting an elephant to work and beating him until he does what is expected of him.","zh":"前一种方法无非就是强迫大象干活，打它，直到它按要求做事为止。"},{"en":"The research team consists of three professors and five graduate students.","zh":"这个研究团队由三名教授和五名研究生组成。"}]},{"phrase":"be capable of","usage":"固定搭配，表示“有能力做……；能够做出……”，后接名词或动名词","examples":[{"en":"Elephants are capable of a considerable degree of personal affection.","zh":"大象能产生相当深厚的个人感情。"},{"en":"This new device is capable of detecting even tiny leaks in the pipe.","zh":"这个新设备甚至能检测到管道里极其微小的泄漏。"}]}],"grammar":[{"title":"非限制性定语从句","definition":"对主句中的某个名词或整个主句内容进行补充说明，去掉之后不影响主句的完整意思，通常和主句之间用逗号隔开","structure":"主句 + , which/who/where/when + 从句","usage":"用来补充额外信息，which可指代前面的整个句子或句子中的某个名词，who指代人","examples":[{"en":"Two main techniques have been used for training elephants, which we may call respectively the tough and the gentle.","zh":"训练大象主要有两种方法，我们可以分别称之为强硬法和温柔法。"},{"en":"The gentle method requires more patience in the early stages, which produces a cheerful good-tempered elephant.","zh":"温柔法在初期需要更多耐心，这种方法能训练出性格开朗温顺、能多年忠诚服役的大象。"}]},{"title":"原因状语从句","definition":"用来解释主句动作或情况发生的原因，常用引导词有for, because, since, as等","structure":"主句 + for/because/since/as + 从句","usage":"for引导的原因状语从句通常不放在句首，是对前面内容的补充说明，语气比because弱","examples":[{"en":"Apart from any moral considerations this is a stupid method of training, for it produces a resentful animal who at a later stage may well turn man-killer.","zh":"且不说道德方面的考虑，这种训练方法本身就很愚蠢，因为它会让动物产生怨恨，之后很可能会变成伤人的野兽。"},{"en":"The most economical age to capture an elephant for training is between 15 and 20 years, for it is then almost ready to undertake heavy work.","zh":"捕捉大象进行训练最划算的年龄是15到20岁之间，因为这个年龄的大象差不多已经可以干重活了。"}]}],"patterns":[{"pattern":"Two main ... have been used for ..., which we may call respectively A and B.","explanation":"","original":{"en":"Two main techniques have been used for training elephants, which we may call respectively the tough and the gentle.","zh":"训练大象主要有两种方法，我们可以分别称之为强硬法和温柔法。"},"examples":[{"en":"Two main methods have been used for learning foreign languages, which we may call respectively the rote-learning method and the immersion method.","zh":"学习外语主要有两种方法，我们可以分别称之为死记硬背法和沉浸法。"},{"en":"Two main solutions have been proposed for this environmental problem, which we may call respectively the technological approach and the policy approach.","zh":"针对这个环境问题，人们提出了两种主要解决方案，我们可以分别称之为技术方案和政策方案。"}]},{"pattern":"The first essential in ... is to ... who will be responsible for ...","explanation":"","original":{"en":"The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job.","zh":"训练大象的第一要务是给大象指派一名专门的驯象师，由他全权负责这项工作。"},"examples":[{"en":"The first essential in project management is to appoint a project manager who will be entirely responsible for the whole process.","zh":"项目管理的第一要务是任命一名项目经理，由他全权负责整个流程。"},{"en":"The first essential in dog training is to let the dog recognize a sole owner who will be responsible for its daily care and instruction.","zh":"训练狗狗的第一要务是让狗狗认可唯一的主人，由主人负责它的日常照顾和指令训练。"}]},{"pattern":"Such extreme cases must probably be taken with a grain of salt, but they do underline the general principle that ...","explanation":"","original":{"en":"Such extreme cases must probably be taken with a grain of salt, but they do underline the general principle that the relationship between elephant and mahout is the key to successful training.","zh":"这类极端案例可能不能完全当真，但它们确实突出了一个普遍原则：大象和驯象师之间的关系是训练成功的关键。"},"examples":[{"en":"Such unbelievable success stories must probably be taken with a grain of salt, but they do underline the general principle that persistent effort is the foundation of achievement.","zh":"这类令人难以置信的成功故事可能不能完全当真，但它们确实突出了一个普遍原则：持续的努力是成就的基础。"},{"en":"Such rare medical cases must probably be taken with a grain of salt, but they do underline the general principle that early detection of disease greatly improves treatment effects.","zh":"这类罕见的医疗案例可能不能完全当真，但它们确实突出了一个普遍原则：疾病的早期发现能极大提升治疗效果。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“猛冲；剧烈扭动” 对应的单词是？","hint":"verb · /plʌndʒ/","options":["phenomenon","expedition","sincerity","plunge"],"answer":3,"explain":"plunge · /plʌndʒ/ · verb · 猛冲；剧烈扭动。指动物或人突然用力地向前冲、扭动身体的动作","source":{"kind":"vocab","word":"plunge"},"id":"b4-u41-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：喜爱；感情","hint":"/əˈfekʃn/ · noun","answer":"affection","placeholder":"输入英文单词","explain":"affection · /əˈfekʃn/ · noun · 喜爱；感情。不可数名词，指对人或事物的喜爱、眷恋之情，常与for/to搭配","source":{"kind":"vocab","word":"affection"},"id":"b4-u41-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ English, he also learns French and Japanese.","hint":"除了英语之外，他还学习法语和日语。","answer":"apart from","placeholder":"输入缺失的短语","explain":"apart from：介词短语，可表示“除了……之外（还）”或“除了……之外（都不）”，相当于besides或except for（除了英语之外，他还学习法语和日语。）","source":{"kind":"phrase","phrase":"apart from"},"id":"b4-u41-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：so that it can absorb the atmosphere of its new home and see that nothing _____ alarming is happening to its companions.","hint":"这样它就能适应新家的环境，并看到它的同伴们没有发生什么特别令人担忧的事情。","answer":"particularly","placeholder":"输入缺失的单词","explain":"so that it can absorb the atmosphere of its new home and see that nothing particularly alarming is happening to its companions. — 这样它就能适应新家的环境，并看到它的同伴们没有发生什么特别令人担忧的事情。","source":{"kind":"sentence","en":"so that it can absorb the atmosphere of its new home and see that nothing particularly alarming is happening to its companions."},"id":"b4-u41-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对主句中的某个名词或整个主句内容进行补充说明，去掉之后不影响主句的完整意思，通常和主句之间用逗号隔开” 描述的是哪个语法点？","hint":"主句 + , which/who/where/when + 从句","options":["同级比较的否定结构","被动语态的使用","非限制性定语从句","while引导的让步状语从句"],"answer":2,"explain":"非限制性定语从句：主句 + , which/who/where/when + 从句：用来补充额外信息，which可指代前面的整个句子或句子中的某个名词，who指代人","source":{"kind":"grammar","title":"非限制性定语从句"},"id":"b4-u41-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe next stage is to get the elephant to the training establishment,","hint":"","options":["因此，当世界其他地方都在努力消灭蚊子时，澳大利亚却在鼓励这种蚊子。","中午时，传感器之间的空间会隐藏计算机不知道的波动，","下一个阶段是将大象带到训练机构，","关于其本质的猜测已经持续了几千年，"],"answer":2,"explain":"The next stage is to get the elephant to the training establishment, — 下一个阶段是将大象带到训练机构，","source":{"kind":"sentence","en":"The next stage is to get the elephant to the training establishment,"},"id":"b4-u41-q06"}]},{"id":"b4-u42","book":4,"unit":42,"key":"42","lessonFrom":42,"lessonTo":42,"title":"Recording an Earthquake","titleZh":"记录地震","question":"What does a pen have to do to record on paper the vibrations generated by an earthquake?","sentences":[{"en":"An earthquake comes like a thief in the night, without warning.","zh":"地震如同夜间的小偷，不打招呼就来了。","t":18.95},{"en":"It was necessary, therefore, to invent instruments that neither slumbered nor slept.","zh":"因此，有必要发明出永不休眠的仪器。","t":23.69},{"en":"Some devices were quite simple.","zh":"有些装置非常简单。","t":29.84},{"en":"One, for instance, consisted of rods of various lengths and thicknesses which would stand up on end like ninepins.","zh":"例如，其中一种是由长短粗细不同的杆子组成，它们像九柱戏的木柱一样直立着。","t":32.36},{"en":"When a shock came, it shook the rigid table upon which these stood.","zh":"当震动来临时，它就会摇晃这些杆子所立的坚硬桌子。","t":41.06},{"en":"If it were gentle, only the more unstable rods fell.","zh":"如果震动轻微，只有那些更不稳定的杆子会倒下。","t":46.36},{"en":"If it were severe, they all fell.","zh":"如果震动剧烈，它们会全部倒下。","t":51.17},{"en":"Thus the rods, by falling, and by the direction in which they fell,","zh":"这样，杆子通过倒下，以及它们倒下的方向，","t":53.99},{"en":"recorded for the slumbering scientist the strength of a shock that was too weak to waken him,","zh":"为熟睡的科学家记录了不足以将他惊醒的震动的强度，","t":58.85},{"en":"and the direction from which it came.","zh":"以及它传来的方向。","t":65.7},{"en":"But instruments far more delicate than that were needed if any really serious advance was to be made.","zh":"但如果想要取得任何真正重大的进展，就需要比这精巧得多的仪器。","t":68.99},{"en":"The ideal to be aimed at was to devise an instrument that could record with a pen on paper,","zh":"理想目标是设计出一种能够用笔在纸上记录的仪器，","t":75.87},{"en":"the movements of the ground or of the table as the quake passed by.","zh":"当地震发生时，记录地面或桌子的移动。","t":82.77},{"en":"While I write my pen moves, but the paper keeps still.","zh":"我写字时笔动纸不动。","t":88.24},{"en":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved.","zh":"毫无疑问，经过练习，我最终能学会笔不动而纸动来写字。","t":92.57},{"en":"That sounds a silly suggestion,","zh":"这听起来是个愚蠢的建议，","t":99.75},{"en":"but that was precisely the idea adopted in some of the early instruments (seismometers) for recording earthquake waves.","zh":"但这正是早期一些用于记录地震波的仪器（地震仪）所采用的原理。","t":102.31},{"en":"But when table, penholder and paper are all moving, how is it possible to write legibly?","zh":"但当桌子、笔架和纸都在移动时，如何才能清晰地书写呢？","t":111.7},{"en":"The key to a solution of that problem lay in an everyday observation.","zh":"解决这个问题的关键在于一个日常观察。","t":119.02},{"en":"Why does a person standing in a bus or train tend to fall when a sudden start is made?","zh":"为什么站在公共汽车或火车上的人，在突然启动时会倾向于摔倒？","t":124.18},{"en":"It is because his feet move on, but his head stays still.","zh":"那是因为他的脚随之移动，但头部却保持静止。","t":130.59},{"en":"A simple experiment will help us a little further.","zh":"一个简单的实验会帮助我们进一步理解。","t":135.18},{"en":"Tie a heavy weight at the end of a long piece of string.","zh":"在一根长绳的末端系上一个重物。","t":138.39},{"en":"With the hand held high in the air, hold the string so that the weight nearly touches the ground.","zh":"将手高举在空中，握住绳子，使重物几乎接触地面。","t":142.24},{"en":"Now move the hand to and fro and around but not up and down.","zh":"现在，前后左右移动手，但不要上下移动。","t":148.78},{"en":"It will be found that the weight moves but slightly or not at all.","zh":"你会发现重物只移动很小，甚至完全不动。","t":153.76},{"en":"Imagine a pen attached to the weight in such a way that its point rests upon a piece of paper on the floor.","zh":"想象一支笔连接在重物上，笔尖落在地板上的一张纸上。","t":158.34},{"en":"Imagine an earthquake shock shaking the floor, the paper, you and your hand.","zh":"想象一场地震震动着地板、纸、你和你的手。","t":164.93},{"en":"In the midst of all this movement, the weight and the pen would be still.","zh":"在所有这些运动中，重物和笔会保持静止。","t":171.42},{"en":"But as the paper moved from side to side under the pen point, its movement would be recorded in ink upon its surface.","zh":"但当纸在笔尖下左右移动时，它的运动就会以墨迹的形式记录在纸面上。","t":175.97},{"en":"It was upon this principle that the first instruments were made, but the paper was wrapped round a drum which rotated slowly.","zh":"第一批仪器就是根据这个原理制造的，但纸是缠绕在一个缓慢旋转的鼓上的。","t":184.18},{"en":"As long as all was still, the pen drew a straight line,","zh":"只要一切静止，笔就画出一条直线，","t":193.2},{"en":"but while the drum was being shaken, the line that the pen was drawing wriggled from side to side.","zh":"但当鼓被摇晃时，笔所画的线就会左右扭动。","t":197.64},{"en":"The apparatus thus described, however,","zh":"然而，这样描述的装置，","t":205.18},{"en":"records only the horizontal component of the wave movement, which is, in fact, much more complicated.","zh":"只记录波浪运动的水平分量，而实际上，波浪运动要复杂得多。","t":207.85},{"en":"If we could actually see the path described by a particle,","zh":"如果我们能真正看到一个粒子所描述的路径，","t":215.21},{"en":"such as a sand grain in the rock,","zh":"例如岩石中的一个沙粒，","t":219.21},{"en":"it would be more like that of a bluebottle buzzing round the room; it would be up and down, to and fro and from side to side.","zh":"它会更像一只苍蝇在房间里嗡嗡飞舞；它会上下、前后和左右移动。","t":221.95},{"en":"Instruments have been devised and can be so placed that all three elements can be recorded in different graphs.","zh":"已经设计出仪器，并且可以这样放置，使得所有三个要素都能在不同的图表中记录下来。","t":230.54},{"en":"When the instrument is situated at more than 700 miles from the earthquake centre,","zh":"当仪器位于距震中700多英里之外时，","t":238.84},{"en":"the graphic record shows three waves arriving one after the other at short intervals.","zh":"图形记录显示三波在短时间内一个接一个地到达。","t":244.62},{"en":"The first records the arrival of longitudinal vibrations.","zh":"第一波记录了纵向振动的到达。","t":250.63},{"en":"The second marks the arrival of transverse vibrations which travel more slowly and arrive several minutes after the first.","zh":"第二波标志着横向振动的到达，它们传播速度较慢，比第一波晚几分钟到达。","t":255.56},{"en":"These two have travelled through the earth.","zh":"这两波已经穿过地球。","t":265.16},{"en":"It was from the study of these that so much was learnt about the interior of the earth.","zh":"正是通过对它们的研究，人们才对地球内部有了如此多的了解。","t":267.87},{"en":"The third, or main wave is the slowest and has travelled round the earth through the surface rocks.","zh":"第三波，即主波，速度最慢，它通过地表岩石环绕地球传播。","t":273.66}],"vocab":[{"word":"vibration","phonetic":"/vaɪˈbreɪʃn/","meanings":[{"pos":"noun","meaning":"震动；颤动；振动","usage":"指物体反复快速晃动的动作或现象，常用于描述地震、机器等产生的震动"}]},{"word":"slumber","phonetic":"/ˈslʌmbə(r)/","meanings":[{"pos":"verb","meaning":"睡眠；熟睡","usage":"正式用语，指安稳地睡眠，可引申为“蛰伏、不活动”"},{"pos":"noun","meaning":"睡眠；沉睡状态","usage":"用作不可数名词，指睡眠的状态"}]},{"word":"rigid","phonetic":"/ˈrɪdʒɪd/","meanings":[{"pos":"adjective","meaning":"坚硬的；不易弯曲的","usage":"形容物体质地坚硬、没有弹性，也可引申为“死板的、严格的”"}]},{"word":"delicate","phonetic":"/ˈdelɪkət/","meanings":[{"pos":"adjective","meaning":"精密的；灵敏的","usage":"形容仪器、设备等结构精密，对微小变化敏感；也可指“易损的、精致的”"}]},{"word":"devise","phonetic":"/dɪˈvaɪz/","meanings":[{"pos":"verb","meaning":"设计；发明；想出","usage":"侧重指通过思考、策划发明出新的方法、设备或计划，宾语通常是工具、方案等"}]},{"word":"precisely","phonetic":"/prɪˈsaɪsli/","meanings":[{"pos":"adverb","meaning":"恰好；正是；精确地","usage":"用于强调完全符合事实，没有偏差，可放在句首或动词前"}]},{"word":"legibly","phonetic":"/ˈledʒəbli/","meanings":[{"pos":"adverb","meaning":"字迹清楚地；易读地","usage":"修饰书写、印刷等行为，表示内容可以被轻松辨认"}]},{"word":"rotate","phonetic":"/rəʊˈteɪt/","meanings":[{"pos":"verb","meaning":"旋转；转动","usage":"指物体围绕自身轴心或外部某点做圆周运动，也可指“轮流、轮换”"}]},{"word":"wriggle","phonetic":"/ˈrɪɡl/","meanings":[{"pos":"verb","meaning":"扭动；蜿蜒移动","usage":"指小幅度、反复地扭动身体或某个部位，也可形容线条、路径曲折扭动"}]},{"word":"component","phonetic":"/kəmˈpəʊnənt/","meanings":[{"pos":"noun","meaning":"组成部分；成分；分量","usage":"指整体中的一个部分，常用于机械、系统、物理量等的构成要素"}]},{"word":"particle","phonetic":"/ˈpɑːtɪkl/","meanings":[{"pos":"noun","meaning":"颗粒；微粒；粒子","usage":"指非常小的物质碎片，也用于物理领域指基本粒子"}]},{"word":"longitudinal","phonetic":"/ˌlɒŋɡɪˈtjuːdɪnl/","meanings":[{"pos":"adjective","meaning":"纵向的；经度的；纵波的","usage":"物理中用于描述振动方向与传播方向一致的波，也可指长度方向的"}]},{"word":"transverse","phonetic":"/trænzˈvɜːs/","meanings":[{"pos":"adjective","meaning":"横向的；横波的","usage":"物理中用于描述振动方向与传播方向垂直的波，也可指垂直于长度方向的"}]},{"word":"interior","phonetic":"/ɪnˈtɪəriə(r)/","meanings":[{"pos":"noun","meaning":"内部；内陆；内地","usage":"常与定冠词the连用，指物体、国家或区域的内部部分，反义词为exterior"}]},{"word":"interval","phonetic":"/ˈɪntəvl/","meanings":[{"pos":"noun","meaning":"间隔；间隙；时间差","usage":"指两个事件、两个物体之间的时间或空间的间隔，常见搭配at intervals（不时；每隔一段距离）"}]}],"phrases":[{"phrase":"on end","usage":"表示“直立着；竖着”，也可指“连续地”，修饰动词stand、place等表示物体竖直放置的状态","examples":[{"en":"One, for instance, consisted of rods of various lengths and thicknesses which would stand up on end like ninepins.","zh":"例如，有一种装置是由一些长短、粗细不同的木棒组成，就像九柱戏的木棒一样直立着。"},{"en":"He placed the box on end in the corner of the room.","zh":"他把箱子竖着放在房间的角落里。"}]},{"phrase":"in time","usage":"此处表示“最终；迟早；经过一段时间之后”，另一个常见含义是“及时”","examples":[{"en":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved.","zh":"毫无疑问，经过练习，我最终能够学会笔不动而纸动来写字。"},{"en":"You will get used to the new environment in time.","zh":"你迟早会适应新环境的。"}]},{"phrase":"to and fro","usage":"副词短语，表示“来回地；往复地”，用来描述动作反复在两个点之间移动","examples":[{"en":"Now move the hand to and fro and around but not up and down.","zh":"现在把手前后左右晃，但不要上下动。"},{"en":"She paced to and fro in the waiting room, worrying about the test result.","zh":"她在候诊室里来回踱步，担心着检查结果。"}]},{"phrase":"lie in","usage":"表示“在于；存在于”，主语通常是问题、答案、原因等抽象名词，后接表示原因或内容的名词","examples":[{"en":"The key to a solution of that problem lay in an everyday observation.","zh":"解决那个问题的关键在于一个日常观察到的现象。"},{"en":"The beauty of the old town lies in its traditional architecture.","zh":"这座古镇的美在于它的传统建筑。"}]},{"phrase":"attach to","usage":"表示“把…固定在；把…附在…上”，常用被动形式be attached to，也可引申为“依恋；重视”","examples":[{"en":"Imagine a pen attached to the weight in such a way that its point rests upon a piece of paper on the floor.","zh":"设想在重物上系一支笔，笔尖刚好落在地板上的一张纸上。"},{"en":"Please attach your photo to the application form before submitting it.","zh":"提交申请表之前请把你的照片贴在上面。"}]},{"phrase":"in the midst of","usage":"表示“在…之中；正当…的时候”，既可指处于某个具体的环境中间，也可指处于某个事件的过程中","examples":[{"en":"In the midst of all this movement, the weight and the pen would be still.","zh":"在所有这些运动中，重物和笔却会保持不动。"},{"en":"The country is in the midst of an economic recovery.","zh":"这个国家正处于经济复苏的过程中。"}]},{"phrase":"from side to side","usage":"表示“左右地；从一边到另一边”，用来描述物体在水平方向上的往复运动","examples":[{"en":"But as the paper moved from side to side under the pen point, its movement would be recorded in ink upon its surface.","zh":"但是当纸在笔尖下左右移动时，纸的运动就会被墨水记录在纸面上。"},{"en":"He shook his head from side to side to show his disagreement.","zh":"他左右摇了摇头表示不同意。"}]},{"phrase":"one after the other","usage":"表示“一个接一个地；陆续地”，强调顺序上连续发生，也可写作one after another","examples":[{"en":"the graphic record shows three waves arriving one after the other at short intervals.","zh":"图形记录显示三种波间隔很短，相继到达。"},{"en":"The students entered the classroom one after the other when the bell rang.","zh":"铃响的时候，学生们一个接一个地走进了教室。"}]}],"grammar":[{"title":"强调句 (Emphatic Sentence)","definition":"用来对句子中的某个成分（主语、宾语、状语等）进行突出强调的句式，不改变原句的语义","structure":"It is/was + 被强调部分 + that/who + 句子其余部分","usage":"当被强调的部分是人时，可以用who代替that，其他情况一律用that；去掉It is/was和that/who后，句子结构和语义依然完整","examples":[{"en":"It was from the study of these that so much was learnt about the interior of the earth.","zh":"正是通过对这两种波的研究，我们才了解到了很多关于地球内部的知识。"},{"en":"It was his hard work that helped him get the promotion.","zh":"正是他的努力工作帮助他获得了晋升。"}]},{"title":"非限定性定语从句 (Non-restrictive Attributive Clause)","definition":"用来对先行词进行补充说明，去掉后不影响主句的完整性，通常用逗号与主句隔开","structure":"主句 + , + which/who/whom/whose + 从句","usage":"不能用that引导非限定性定语从句，which可以指代前面的整个主句或主句中的某个名词，用来补充额外信息","examples":[{"en":"The apparatus thus described, however, records only the horizontal component of the wave movement, which is, in fact, much more complicated.","zh":"然而，以上描述的仪器只能记录地震波运动的水平分量，而地震波的运动实际上要复杂得多。"},{"en":"She won the first prize in the competition, which made her parents very proud.","zh":"她在比赛中获得了一等奖，这让她的父母非常骄傲。"}]},{"title":"if引导的非真实条件句（虚拟语气）","definition":"用来表示与现在事实相反、或发生可能性极低的假设，主句和从句都使用虚拟语气","structure":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","usage":"从句描述假设的情况，主句描述该假设情况下会产生的结果，常用于说明理论、想象的场景","examples":[{"en":"If we could actually see the path described by a particle, such as a sand grain in the rock, it would be more like that of a bluebottle buzzing round the room.","zh":"如果我们真的能看到一个粒子（比如岩石中的沙粒）的运动路径，它会更像一只在房间里嗡嗡飞的绿头苍蝇的路径。"},{"en":"If I had more time, I would learn a second foreign language.","zh":"如果我有更多时间，我会学第二门外语。"}]}],"patterns":[{"pattern":"X come like Y, without Z.","explanation":"","original":{"en":"An earthquake comes like a thief in the night, without warning.","zh":"地震就像夜间的小偷一样，不打招呼就来了。"},"examples":[{"en":"A good idea comes like a flash of light, without any sign.","zh":"好主意就像一道闪光，毫无预兆地就来了。"},{"en":"Winter comes like a silent guest, without making a sound.","zh":"冬天就像一位安静的客人，悄无声息地就来临了。"}]},{"pattern":"The key to a solution of X lie in Y.","explanation":"","original":{"en":"The key to a solution of that problem lay in an everyday observation.","zh":"解决那个问题的关键在于一个日常观察到的现象。"},"examples":[{"en":"The key to a solution of the environmental problem lies in the joint efforts of all people.","zh":"解决环境问题的关键在于所有人的共同努力。"},{"en":"The key to a solution of the learning difficulty lies in finding a suitable method.","zh":"解决学习困难的关键在于找到合适的方法。"}]},{"pattern":"When X is situated at Y, Z show A doing B.","explanation":"","original":{"en":"When the instrument is situated at more than 700 miles from the earthquake centre, the graphic record shows three waves arriving one after the other at short intervals.","zh":"当仪器被放置在距离震中700英里以上的位置时，图形记录显示三种波间隔很短，相继到达。"},"examples":[{"en":"When the camera is situated at the top of the mountain, the video shows clouds moving slowly below the peak.","zh":"当相机被放置在山顶时，视频显示云朵在峰顶下缓慢移动。"},{"en":"When the detector is situated near the river, the data shows the water level rising gradually every spring.","zh":"当探测器被放置在河流附近时，数据显示每年春天水位都会逐渐上升。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“颗粒；微粒；粒子” 对应的单词是？","hint":"noun · /ˈpɑːtɪkl/","options":["portfolio","particle","pine","inevitable"],"answer":1,"explain":"particle · /ˈpɑːtɪkl/ · noun · 颗粒；微粒；粒子。指非常小的物质碎片，也用于物理领域指基本粒子","source":{"kind":"vocab","word":"particle"},"id":"b4-u42-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：震动；颤动；振动","hint":"/vaɪˈbreɪʃn/ · noun","answer":"vibration","placeholder":"输入英文单词","explain":"vibration · /vaɪˈbreɪʃn/ · noun · 震动；颤动；振动。指物体反复快速晃动的动作或现象，常用于描述地震、机器等产生的震动","source":{"kind":"vocab","word":"vibration"},"id":"b4-u42-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The students entered the classroom _____ when the bell rang.","hint":"铃响的时候，学生们一个接一个地走进了教室。","answer":"one after the other","placeholder":"输入缺失的短语","explain":"one after the other：表示“一个接一个地；陆续地”，强调顺序上连续发生，也可写作one after another（铃响的时候，学生们一个接一个地走进了教室。）","source":{"kind":"phrase","phrase":"one after the other"},"id":"b4-u42-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：With practice, no doubt, I could in time learn to write by holding the pen still _____ the paper moved.","hint":"毫无疑问，经过练习，我最终能学会笔不动而纸动来写字。","answer":"while","placeholder":"输入缺失的单词","explain":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved. — 毫无疑问，经过练习，我最终能学会笔不动而纸动来写字。","source":{"kind":"sentence","en":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved."},"id":"b4-u42-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来对句子中的某个成分（主语、宾语、状语等）进行突出强调的句式，不改变原句的语义” 描述的是哪个语法点？","hint":"It is/was + 被强调部分 + that/who + 句子其余部分","options":["强调句 (Emphatic Sentence)","as 引导的方式状语从句","定语从句的省略形式","完全倒装句"],"answer":0,"explain":"强调句 (Emphatic Sentence)：It is/was + 被强调部分 + that/who + 句子其余部分：当被强调的部分是人时，可以用who代替that，其他情况一律用that；去掉It is/was和that/who后，句子结构和语义依然完整","source":{"kind":"grammar","title":"强调句 (Emphatic Sentence)"},"id":"b4-u42-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIf we could actually see the path described by a particle,","hint":"","options":["美人鱼、小天使；还有栩栩如生的动物造型，它们都被漆成红、金和蓝色，","这一事件完全可以作为一场独特的王室谍报史诗！","卡莱尔完全不知道他口袋里的药瓶装着什么，","如果我们能真正看到一个粒子所描述的路径，"],"answer":3,"explain":"If we could actually see the path described by a particle, — 如果我们能真正看到一个粒子所描述的路径，","source":{"kind":"sentence","en":"If we could actually see the path described by a particle,"},"id":"b4-u42-q06"}]},{"id":"b4-u43","book":4,"unit":43,"key":"43","lessonFrom":43,"lessonTo":43,"title":"Are There Strangers in Space?","titleZh":"太空中有陌生人吗？","question":"What does the 'uniquely rational way' for us to communicate with other intelligent beings in space depend on?","sentences":[{"en":"We must conclude from the work of those who have studied the origin of life,","zh":"从研究生命起源的那些人的工作中，我们必须得出结论，","t":22.8},{"en":"that given a planet only approximately like our own, life is almost certain to start.","zh":"只要有一颗与我们地球大致相似的行星，生命几乎肯定会开始。","t":28.36},{"en":"Of all the planets in our solar system, we are now pretty certain the Earth is the only one on which life can survive.","zh":"在我们太阳系的所有行星中，我们现在非常确定地球是唯一一个生命可以存活的行星。","t":36.13},{"en":"Mars is too dry and poor in oxygen, Venus far too hot, and so is Mercury,","zh":"火星太干燥，氧气稀少；金星和水星都太热，","t":46.4},{"en":"and the outer planets have temperatures near absolute zero and hydrogen-dominated atmospheres.","zh":"而外行星的温度接近绝对零度，大气层以氢为主。","t":54.04},{"en":"But other suns, start as the astronomers call them, are bound to have planets like our own, and as is the number of stars in the universe is so vast,","zh":"但是其他太阳，天文学家称之为恒星，必定有像我们地球一样的行星，而且宇宙中恒星的数量如此之多，","t":62.12},{"en":"this possibility becomes virtual certainty.","zh":"这种可能性几乎成了必然。","t":74.38},{"en":"There are one hundred thousand million starts in our own Milky Way alone,","zh":"仅在我们的银河系中就有1000亿颗恒星，","t":78.33},{"en":"and then there are three thousand million other milky ways or galaxies, in the universe.","zh":"而宇宙中还有30亿个其他星系。","t":84.73},{"en":"so the number of stars that we know exist is now estimated at about 300 million million million.","zh":"因此，我们已知存在的恒星数量现在估计约为300万亿亿。","t":92.54},{"en":"Although perhaps only 1 percent of the life that has started somewhere will develop into highly complex and intelligent patterns,","zh":"尽管在某个地方开始的生命中，可能只有1%会发展成高度复杂和智能的模式，","t":103.29},{"en":"so vast is the number of planets, that intelligent life is bound to be a natural part of the universe.","zh":"但行星的数量如此之多，以至于智慧生命必然是宇宙的自然组成部分。","t":112.47},{"en":"If then we are so certain that other intelligent life exists in the universe, why have we had no visitors from outer space yet?","zh":"既然我们如此确定宇宙中存在其他智慧生命，那为什么我们还没有迎来外太空的访客呢？","t":120.95},{"en":"First of all, they may have come to this planet of ours thousands or millions of years ago,","zh":"首先，他们可能在几千或几百万年前就已经来到过我们的星球，","t":130.93},{"en":"and found our then prevailing primitive state completely uninteresting to their own advanced knowledge.","zh":"并发现我们当时普遍存在的原始状态对于他们自身先进的知识来说完全不感兴趣。","t":138.52},{"en":"Professor Ronald Bracewell, a leading American radio astronomer,","zh":"罗纳德·布雷斯韦尔教授，一位杰出的美国射电天文学家，","t":146.42},{"en":"argued in Nature that such a superior civilization, on a visit to our own solar system,","zh":"在《自然》杂志上提出，这样一个更高级的文明，在访问我们太阳系时，","t":152.01},{"en":"may have left an automatic messenger behind to await the possible awakening of an advanced civilization.","zh":"可能会留下一个自动信使，以等待一个先进文明的可能觉醒。","t":160.13},{"en":"Such a messenger, receiving our radio and television signals,","zh":"这样一个信使，在接收到我们的无线电和电视信号后，","t":168.54},{"en":"might well re-transmit them back to its home-planet,","zh":"很可能会将它们重新发送回它的母星，","t":173.48},{"en":"although what impression any other civilization would thus get from us is best left unsaid.","zh":"尽管其他文明会因此从我们这里得到什么样的印象最好还是不提为妙。","t":177.84},{"en":"But here we come up against the most difficult of all obstacles to contact with people on other planets","zh":"但在这里，我们遇到了与外星球人接触所有障碍中最困难的一个","t":186.46},{"en":"-- the astronomical distances which separate us.","zh":"——将我们分开的巨大天文距离。","t":194.05},{"en":"As a reasonable guess, they might, on an average, be 100 light years away.","zh":"合理猜测，他们平均可能在100光年之外。","t":198.51},{"en":"(A light year is the distance which light travels at 186,000 miles per second in one year, namely 6 million million miles.)","zh":"(一光年是光以每秒18.6万英里的速度在一年中旅行的距离，即6万亿英里。)","t":206.43},{"en":"Radio waves also travel at the speed of light,","zh":"无线电波也以光速传播，","t":218.43},{"en":"and assuming such an automatic messenger picked up our first broadcasts of the 1920's,","zh":"假设这样一个自动信使接收到了我们20世纪20年代的首次广播，","t":222.04},{"en":"the message to its home planet is barely halfway there.","zh":"那么它传回家园星球的信息才刚刚走了一半的路程。","t":228.75},{"en":"Similarly, our own present primitive chemical rockets,","zh":"同样地，我们目前原始的化学火箭，","t":233.48},{"en":"though good enough to orbit men, have no chance of transporting us to the nearest other star,","zh":"尽管足以将人类送入轨道，却没有机会将我们运送到最近的恒星，","t":238.3},{"en":"four light years away, let alone distances of tens or hundreds of light years.","zh":"距我们四光年之遥，更不用说几十或几百光年的距离了。","t":246.05},{"en":"Fortunately, there is a 'uniquely rational way' for us to communicate with other intelligent beings,","zh":"幸运的是，我们有一种“唯一理性方式”可以与其他智慧生物交流，","t":253.85},{"en":"as Walter Sullivan has put it in his excellent book,","zh":"正如沃尔特·沙利文在他的优秀著作中所说，","t":262.33},{"en":"We Are not Alone.","zh":"《我们并不孤单》。","t":266.34},{"en":"This depends on the precise radio frequency of the 21-cm wavelength, or 1420 megacycles per second.","zh":"这取决于21厘米波长，即每秒1420兆赫兹的精确无线电频率。","t":268.6},{"en":"It is the natural frequency of emission of the hydrogen atoms in space and was discovered by us in 1951;","zh":"它是太空中氢原子的自然发射频率，由我们于1951年发现；","t":281.42},{"en":"it must be known to any kind of radio astronomer in the universe.","zh":"宇宙中任何一种射电天文学家都必定知道它。","t":290.31},{"en":"Once the existence of this wave-length had been discovered,","zh":"一旦这种波长被发现，","t":295.85},{"en":"it was not long before its use as the uniquely recognizable broadcasting frequency for interstellar communication was suggested.","zh":"很快就有人建议将其用作星际通信的独特可识别广播频率。","t":299.84},{"en":"Without something of this kind,","zh":"如果没有这种东西，","t":309.3},{"en":"searching for intelligences on other planets would be like trying to meet a friend in London without a pre-arranged rendezvous","zh":"寻找其他行星上的智慧生命，就像在伦敦没有事先约定地点就试图与朋友见面一样，","t":311.49},{"en":"and absurdly wandering the streets in the hope of a chance encounter.","zh":"荒唐地在街上闲逛，希望能偶然相遇。","t":319.41}],"vocab":[{"word":"rational","phonetic":"/ˈræʃənl/","meanings":[{"pos":"adjective","meaning":"合理的；理性的；明智的","usage":"用来描述基于逻辑思考而非情绪的判断、行为等"}]},{"word":"approximately","phonetic":"/əˈprɒksɪmətli/","meanings":[{"pos":"adverb","meaning":"大约；近似地","usage":"用于修饰数量、程度等，表不十分精确的估算"}]},{"word":"prevailing","phonetic":"/prɪˈveɪlɪŋ/","meanings":[{"pos":"adjective","meaning":"普遍的；盛行的；当时存在的","usage":"用来描述某一时期最常见、占主导的情况或现象"}]},{"word":"bound","phonetic":"/baʊnd/","meanings":[{"pos":"adjective","meaning":"一定会；很可能会","usage":"常用于be bound to结构，表确定性极强的推断"}]},{"word":"estimate","phonetic":"/ˈestɪmeɪt/","meanings":[{"pos":"verb","meaning":"估计；估算；判断","usage":"指对数量、价值等做出大致的判断，常用于被动语态be estimated at"}]},{"word":"obstacle","phonetic":"/ˈɒbstəkl/","meanings":[{"pos":"noun","meaning":"障碍；阻碍；障碍物","usage":"后常接介词to，表示“对…的阻碍”"}]},{"word":"astronomical","phonetic":"/ˌæstrəˈnɒmɪkl/","meanings":[{"pos":"adjective","meaning":"天文学的；天文的；极其巨大的","usage":"既可修饰和天文相关的事物，也可夸张地形容数量、数值极大"}]},{"word":"emission","phonetic":"/iˈmɪʃn/","meanings":[{"pos":"noun","meaning":"排放；散发；发射物","usage":"常指气体、辐射、信号等的释放，后可接介词of"}]},{"word":"interstellar","phonetic":"/ˌɪntəˈstelə(r)/","meanings":[{"pos":"adjective","meaning":"星际的；星球间的","usage":"用于修饰太空里恒星之间的事物，如interstellar communication星际通讯"}]},{"word":"rendezvous","phonetic":"/ˈrɒndɪvuː/","meanings":[{"pos":"noun","meaning":"约会；会面；约会地点","usage":"可指预先约定的会面，也可指约定的会面地点，正式用法"}]},{"word":"absurdly","phonetic":"/əbˈsɜːdli/","meanings":[{"pos":"adverb","meaning":"荒谬地；荒唐地","usage":"用来修饰行为、状态等，强调其不合理、可笑的程度"}]}],"phrases":[{"phrase":"be bound to","usage":"表达对某事发生的确定性推断，语气十分肯定，相当于“一定会，必定会”","examples":[{"en":"If you work hard, you are bound to make progress sooner or later.","zh":"如果你努力，迟早一定会取得进步。"},{"en":"There are bound to be unexpected difficulties when starting a new project.","zh":"启动新项目时一定会遇到意料之外的困难。"}]},{"phrase":"come up against","usage":"表示意外遇到困难、问题、反对等，主语通常是人或组织","examples":[{"en":"We came up against a lack of funds when trying to expand the business.","zh":"我们试图拓展业务时遇到了资金短缺的问题。"},{"en":"Many new graduates come up against fierce competition in the job market.","zh":"很多应届毕业生在就业市场遇到了激烈的竞争。"}]},{"phrase":"let alone","usage":"用于进一步否定或强调更不可能的情况，通常前面是否定句，相当于“更不用说”","examples":[{"en":"I can't even afford a cheap bicycle, let alone a car.","zh":"我连便宜的自行车都买不起，更不用说汽车了。"},{"en":"He can't speak basic Japanese, let alone read Japanese novels.","zh":"他连基础日语都不会说，更不用说读日语小说了。"}]},{"phrase":"depend on","usage":"表示“取决于；依赖；依靠”，后可接名词、代词或从句","examples":[{"en":"The success of the activity depends on the weather.","zh":"活动能否成功取决于天气。"},{"en":"You should not always depend on others when you meet problems.","zh":"遇到问题时你不要总依赖别人。"}]},{"phrase":"pick up","usage":"此处含义为“接收到（信号、声音、图像等）”，此外还有“捡起；接人；学会”等含义","examples":[{"en":"My radio can pick up international stations very clearly.","zh":"我的收音机可以非常清晰地接收国际电台。"},{"en":"The equipment picked up a strange signal from outer space.","zh":"这台设备接收到了一个来自外太空的奇怪信号。"}]}],"grammar":[{"title":"given引导的条件状语","definition":"given作为介词，意为“考虑到；鉴于；如果有”，后接名词、代词或名词短语，可放在句首或句中，表前提条件","structure":"Given + 名词/名词短语, 主句","usage":"用于引出某个既定的前提，基于这个前提得出主句的结论，属于书面正式用法","examples":[{"en":"Given a chance, I believe I can do the job well.","zh":"如果有机会，我相信我能把这份工作做好。"},{"en":"Given the current situation, we have to put off the meeting.","zh":"考虑到目前的情况，我们不得不推迟会议。"}]},{"title":"so...that...引导的结果状语从句（倒装结构）","definition":"为了强调形容词或副词，可将so + 形容词/副词放在句首，此时主句需要部分倒装，that后的结果状语从句语序不变","structure":"So + 形容词/副词 + 助动词/系动词/情态动词 + 主语 + 谓语剩余部分 + that + 结果状语从句","usage":"用于正式文体中，加强语气，突出主句中描述的特征的程度之深，进而导致了从句的结果","examples":[{"en":"So fast did he run that no one could catch up with him.","zh":"他跑得太快了，没人能追上他。"},{"en":"So attractive is the book that I have read it three times.","zh":"这本书太有吸引力了，我已经读了三遍。"}]}],"patterns":[{"pattern":"We must conclude from + 来源, that + 结论","explanation":"","original":{"en":"We must conclude from the work of those who have studied the origin of life, that given a planet only approximately like our own, life is almost certain to start.","zh":"从那些研究生命起源的科学家的工作中我们必然会得出这样的结论：如果有一颗行星和地球的条件哪怕只是近似，生命就几乎肯定会起源。"},"examples":[{"en":"We must conclude from the recent surveys, that more and more young people prefer to work from home.","zh":"从最近的调查中我们必然会得出结论：越来越多的年轻人倾向于居家办公。"},{"en":"We must conclude from the data collected over the past decade, that global warming is speeding up.","zh":"从过去十年收集的数据中我们必然会得出结论：全球变暖正在加速。"}]},{"pattern":"..., why have we had + 名词 + yet?","explanation":"","original":{"en":"If then we are so certain that other intelligent life exists in the universe, why have we had no visitors from outer space yet?","zh":"那么如果我们如此确定宇宙中存在其他智慧生命，为什么我们至今还没有迎来外太空的访客呢？"},"examples":[{"en":"If you said you would send me the document yesterday, why have we had no news from you yet?","zh":"如果你说你昨天会把文件发给我，为什么我们至今还没有收到你的消息？"},{"en":"If the project was supposed to be finished last month, why have we had no final report yet?","zh":"如果这个项目本应该上个月就完成，为什么我们至今还没有看到最终报告？"}]},{"pattern":"Without something of this kind, doing sth would be like doing sth without...","explanation":"","original":{"en":"Without something of this kind, searching for intelligences on other planets would be like trying to meet a friend in London without a pre-arranged rendezvous and absurdly wandering the streets in the hope of a chance encounter.","zh":"如果没有这种频率，寻找其他行星上的智慧生命就好比没有预先约定会面地点就试图在伦敦见一个朋友，荒唐地在街上游荡，希望能偶然碰见。"},"examples":[{"en":"Without a clear study plan, preparing for the exam would be like trying to find a destination in a forest without a map and walking aimlessly in the hope of finding the way out.","zh":"如果没有清晰的学习计划，备考就好比没有地图就试图在森林里找目的地，漫无目的地行走，希望能找到出路。"},{"en":"Without enough market research, launching a new product would be like trying to sail across the ocean without a compass and drifting randomly in the hope of reaching the port.","zh":"如果没有足够的市场调研，推出新产品就好比没有指南针就试图横渡大洋，随意漂流，希望能抵达港口。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“一定会；很可能会” 对应的单词是？","hint":"adjective · /baʊnd/","options":["bound","secrecy","current","signature"],"answer":0,"explain":"bound · /baʊnd/ · adjective · 一定会；很可能会。常用于be bound to结构，表确定性极强的推断","source":{"kind":"vocab","word":"bound"},"id":"b4-u43-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：普遍的；盛行的；当时存在的","hint":"/prɪˈveɪlɪŋ/ · adjective","answer":"prevailing","placeholder":"输入英文单词","explain":"prevailing · /prɪˈveɪlɪŋ/ · adjective · 普遍的；盛行的；当时存在的。用来描述某一时期最常见、占主导的情况或现象","source":{"kind":"vocab","word":"prevailing"},"id":"b4-u43-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He can't speak basic Japanese, _____ read Japanese novels.","hint":"他连基础日语都不会说，更不用说读日语小说了。","answer":"let alone","placeholder":"输入缺失的短语","explain":"let alone：用于进一步否定或强调更不可能的情况，通常前面是否定句，相当于“更不用说”（他连基础日语都不会说，更不用说读日语小说了。）","source":{"kind":"phrase","phrase":"let alone"},"id":"b4-u43-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：As a _____ guess, they might, on an average, be 100 light years away.","hint":"合理猜测，他们平均可能在100光年之外。","answer":"reasonable","placeholder":"输入缺失的单词","explain":"As a reasonable guess, they might, on an average, be 100 light years away. — 合理猜测，他们平均可能在100光年之外。","source":{"kind":"sentence","en":"As a reasonable guess, they might, on an average, be 100 light years away."},"id":"b4-u43-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“given作为介词，意为“考虑到；鉴于；如果有”，后接名词、代词或名词短语，可放在句首或句中，表前提条件” 描述的是哪个语法点？","hint":"Given + 名词/名词短语, 主句","options":["时间状语从句的省略","as引导的非限制性定语从句","so...that...引导的结果状语从句（倒装结构）","given引导的条件状语"],"answer":3,"explain":"given引导的条件状语：Given + 名词/名词短语, 主句：用于引出某个既定的前提，基于这个前提得出主句的结论，属于书面正式用法","source":{"kind":"grammar","title":"given引导的条件状语"},"id":"b4-u43-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\n-- the astronomical distances which separate us.","hint":"","options":["这些原则可以适用于多种类型的产品，并且可能扩展到其他国家。","人们总是在谈论“青年问题”。","早些时候，我们是婴儿和幼儿，因此更容易受到伤害；","——将我们分开的巨大天文距离。"],"answer":3,"explain":"-- the astronomical distances which separate us. — ——将我们分开的巨大天文距离。","source":{"kind":"sentence","en":"-- the astronomical distances which separate us."},"id":"b4-u43-q06"}]},{"id":"b4-u44","book":4,"unit":44,"key":"44","lessonFrom":44,"lessonTo":44,"title":"Patterns of Culture","titleZh":"文化的模式","question":"What influences us from the moment of birth?","sentences":[{"en":"Custom has not commonly been regarded as a subject of any great moment.","zh":"习俗通常不被认为是一个举足轻重的问题。","t":15.46},{"en":"The inner workings of our own brains we feel to be uniquely worthy of investigation,","zh":"我们认为我们自己大脑的内部运作是独一无二地值得研究的，","t":20.81},{"en":"but custom, we have a way of thinking, is behaviour at is most commonplace.","zh":"但我们有一种想法，认为习俗是最常见的行为。","t":26.82},{"en":"As a matter of fact, it is the other way around.","zh":"事实上，情况恰恰相反。","t":33.35},{"en":"Traditional custom, taken the world over,","zh":"传统的习俗，遍布世界各地，","t":36.88},{"en":"is a mass of detailed behaviour more astonishing than what any one person can ever evolve in individual actions,","zh":"是一堆详细的行为，比任何个人在单独行动中所能演变出的行为都更令人惊讶，","t":39.96},{"en":"no matter how aberrant.","zh":"无论多么反常。","t":48.53},{"en":"Yet that is a rather trivial aspect of the matter.","zh":"然而，这只是问题的微不足道的一面。","t":50.73},{"en":"The fact of first-rate importance is the predominant role that custom plays in experience and in belief,","zh":"最重要的事实是习俗在经验和信仰中扮演的主导角色，","t":54.7},{"en":"and the very great varieties it may manifest.","zh":"以及它可能表现出的巨大多样性。","t":62.52},{"en":"No man ever looks at the world with pristine eyes.","zh":"没有人能以纯粹的眼光看待世界。","t":67.28},{"en":"He sees it edited by a definite set of customs and institutions and ways of thinking.","zh":"他看到的世界是由一套明确的习俗、制度和思维方式所塑造的。","t":71.45},{"en":"Even in his philosophical probings he cannot go behind these stereotypes;","zh":"即使在他的哲学探索中，他也无法超越这些刻板印象；","t":78.15},{"en":"his very concepts of the true and the false will still have reference to his particular traditional customs.","zh":"他对真与假的观念仍然会与他特定的传统习俗相关联。","t":83.66},{"en":"John Dewey has said in all seriousness that the part played by custom in shaping the behaviour of the individual,","zh":"约翰·杜威曾非常严肃地说，习俗在塑造个人行为中所起的作用，","t":91.5},{"en":"as against any way in which he can affect traditional custom,","zh":"与他能够影响传统习俗的任何方式相比，","t":99.36},{"en":"is as the proportion of the total vocabulary of his mother tongue","zh":"就像他母语的全部词汇量，","t":103.65},{"en":"against those words of his own baby talk that are taken up into the vernacular of his family.","zh":"与他自己咿呀学语中被家庭口语采纳的词语之比。","t":108.64},{"en":"When one seriously studies the social orders that have had the opportunity to develop autonomously,","zh":"当人们认真研究那些有机会自主发展的社会秩序时，","t":116.17},{"en":"the figure becomes no more than an exact and matter-of-fact observation.","zh":"这个比喻就成了精确而实际的观察。","t":123.58},{"en":"The life history of the individual is first and foremost an accommodation","zh":"个体的生命历程首先是一种适应，","t":129.12},{"en":"to the patterns and standards traditionally handed down in his community.","zh":"适应其社区中世代相传的模式和标准。","t":134.42},{"en":"From the moment of his birth,","zh":"从他出生那一刻起，","t":140.21},{"en":"the customs into which he is born shape his experience and behaviour.","zh":"他所降生的习俗塑造了他的经验和行为。","t":142.2},{"en":"By the time he can talk, he is the little creature of his culture,","zh":"等到他会说话时，他已是其文化的小小产物，","t":147.53},{"en":"and by the time he is grown and able to take part in its activities,","zh":"等到他长大成人并能参与其活动时，","t":152.38},{"en":"its habits are his habits, its beliefs his beliefs, its impossibilities his impossibilities.","zh":"它的习惯是他的习惯，它的信仰是他的信仰，它的不可能之事是他的不可能之事。","t":157.3},{"en":"Every child that is born into his group will share them with him,","zh":"每一个出生在他群体中的孩子都会与他分享这些，","t":165.92},{"en":"and no child born into one on the opposite side of the globe can ever achieve the thousandth part.","zh":"而出生在地球另一边的孩子连千分之一也无法做到。","t":170.38},{"en":"There is no social problem it is more incumbent upon us to understand than this of the role of custom.","zh":"没有比理解习俗的作用更重要的社会问题了。","t":177.64},{"en":"Until we are intelligent as to its laws and varieties,","zh":"在我们对其规律和多样性有充分了解之前，","t":185.73},{"en":"the main complicating facts of human life must remain unintelligible.","zh":"人类生活的主要复杂事实必然是难以理解的。","t":189.78},{"en":"The study of custom can be profitable only after certain preliminary propositions have been accepted,","zh":"对习俗的研究只有在某些初步命题被接受之后才能有所裨益，","t":195.99},{"en":"and some of these propositions have been violently opposed.","zh":"而其中一些命题曾遭到强烈反对。","t":203.68},{"en":"In the first place, any scientific study requires that there be no","zh":"首先，任何科学研究都要求，","t":208.49},{"en":"preferential weighting of one or another of the items in the series it selects for its consideration.","zh":"在它所选择的系列项目进行考量时，不应对其中任何一项有偏向性地加权。","t":213.38},{"en":"In all the less controversial fields, like the study of cacti or termites or the nature of nebulae,","zh":"在所有争议较少的领域，比如研究仙人掌、白蚁或星云的性质，","t":220.88},{"en":"the necessary method of study is to group the relevant material and to take note of all possible variant forms and conditions.","zh":"必要的研究方法是将相关材料分组，并记录所有可能的变体形式和条件。","t":228.21},{"en":"In this way, we have learned all that we know of the laws of astronomy, or of the habits of the social insects, let us say.","zh":"通过这种方式，我们掌握了天文学的所有规律，或者说，掌握了群居昆虫的习性。","t":236.75},{"en":"It is only in the study of man himself that the major social sciences","zh":"只有在研究人类自身时，主要的社会科学才","t":246.01},{"en":"have substituted the study of one local variation, that of Western civilization.","zh":"将对西方文明这一地方性变体的研究取而代之。","t":251.19},{"en":"Anthropology was by definition impossible,","zh":"人类学按定义来说是不可能的，","t":258.21},{"en":"as long as these distinctions between ourselves and the primitive,","zh":"只要我们与原始人、","t":261.58},{"en":"ourselves and the barbarian, ourselves and the pagan, held sway over people's minds.","zh":"我们与野蛮人、我们与异教徒之间的这些区别仍然主宰着人们的思想。","t":266.14},{"en":"It was necessary first to arrive at that degree of sophistication","zh":"首先，有必要达到那种成熟程度，","t":272.65},{"en":"where we no longer set our own belief against our neighbour's superstition.","zh":"即我们不再将自己的信仰与邻居的迷信对立起来。","t":277.42},{"en":"It was necessary to recognize that these institutions which are based on the same premises, let us say the supernatural,","zh":"有必要认识到，这些基于相同前提的制度，比方说超自然现象，","t":282.42},{"en":"must be considered together, our own among the rest.","zh":"必须被一并考虑，包括我们自己的。","t":291.74}],"vocab":[{"word":"aberrant","phonetic":"/æˈberənt/","meanings":[{"pos":"adjective","meaning":"异常的，偏离常规的","usage":"用于描述行为、现象等与普遍公认的标准或常态不符"}]},{"word":"predominant","phonetic":"/prɪˈdɒmɪnənt/","meanings":[{"pos":"adjective","meaning":"占主导地位的，显著的","usage":"强调在某一范围内影响力最大、地位最重要的"}]},{"word":"manifest","phonetic":"/ˈmænɪfest/","meanings":[{"pos":"verb","meaning":"显示，表明","usage":"指让原本隐藏或不明显的事物清晰展现出来"},{"pos":"adjective","meaning":"明显的，显而易见的","usage":"用于描述特征、情绪等容易被感知的"}]},{"word":"pristine","phonetic":"/ˈprɪstiːn/","meanings":[{"pos":"adjective","meaning":"未受外界影响的，质朴的；崭新的","usage":"可形容事物处于原始未被改变的状态，也可形容物品十分新、没有磨损"}]},{"word":"probing","phonetic":"/ˈprəʊbɪŋ/","meanings":[{"pos":"noun","meaning":"探查，探究","usage":"指对问题、真相进行深入的调查和探索"},{"pos":"adjective","meaning":"追根究底的，锐利的","usage":"形容问题、目光等有探索性的"}]},{"word":"stereotype","phonetic":"/ˈsteriətaɪp/","meanings":[{"pos":"noun","meaning":"刻板印象，固定模式","usage":"指对某一类群体或事物的固定、僵化的看法，通常缺乏事实依据"}]},{"word":"vernacular","phonetic":"/vəˈnækjələ(r)/","meanings":[{"pos":"noun","meaning":"方言，本地话，口语","usage":"指某一地区的人日常使用的本土语言，与官方语言、书面语相对"}]},{"word":"autonomously","phonetic":"/ɔːˈtɒnəməsli/","meanings":[{"pos":"adverb","meaning":"自主地，自治地","usage":"描述主体不受外部控制，能够独立管理自身事务的状态"}]},{"word":"accommodation","phonetic":"/əˌkɒməˈdeɪʃn/","meanings":[{"pos":"noun","meaning":"适应，调节；住处","usage":"表示为了适应新环境做出的调整，也可指居住的场所"}]},{"word":"incumbent","phonetic":"/ɪnˈkʌmbənt/","meanings":[{"pos":"adjective","meaning":"有责任的，义不容辞的；现任的","usage":"常用于it is incumbent upon sb to do sth结构，表示某人有义务做某事；也可形容在职的人员"}]},{"word":"intelligible","phonetic":"/ɪnˈtelɪdʒəbl/","meanings":[{"pos":"adjective","meaning":"可理解的，明白易懂的","usage":"形容语言、信息、逻辑等能够被人清楚理解的"}]},{"word":"preliminary","phonetic":"/prɪˈlɪmɪnəri/","meanings":[{"pos":"adjective","meaning":"初步的，预备的","usage":"用于描述在正式活动、研究开始之前的准备性的内容"}]},{"word":"proposition","phonetic":"/ˌprɒpəˈzɪʃn/","meanings":[{"pos":"noun","meaning":"主张，观点；命题","usage":"指提出的有待讨论、验证的观点或理论假设"}]},{"word":"sophistication","phonetic":"/səˌfɪstɪˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"sophisticated的名词形式，意为老练，严谨；精密","usage":"可形容人认知水平成熟、看问题全面，也可形容技术、设备等先进精密"}]},{"word":"supernatural","phonetic":"/ˌsuːpəˈnætʃrəl/","meanings":[{"pos":"adjective","meaning":"超自然的，神奇的","usage":"形容无法用自然规律解释的、超出科学认知的现象或力量"}]}],"phrases":[{"phrase":"as a matter of fact","usage":"用于引出与对方想法不同的实际情况，或强调事实的真相，相当于in fact","examples":[{"en":"As a matter of fact, it is the other way around.","zh":"事实上，情况恰恰相反。"},{"en":"As a matter of fact, I have already finished the report ahead of schedule.","zh":"实际上，我已经提前完成了报告。"}]},{"phrase":"have reference to","usage":"表示“与……有关，涉及”，用于说明事物之间的关联","examples":[{"en":"His very concepts of the true and the false will still have reference to his particular traditional customs.","zh":"他对是非的判断标准仍然和他所处的特定传统习俗有关。"},{"en":"The data collected in this research have reference to the impact of climate change on crop production.","zh":"这项研究收集的数据和气候变化对作物生产的影响有关。"}]},{"phrase":"first and foremost","usage":"用于强调最重要的、首要的因素，放在句首或主语后引出核心内容","examples":[{"en":"The life history of the individual is first and foremost an accommodation to the patterns and standards traditionally handed down in his community.","zh":"个人的生活史首先就是适应他所在社群世代相传的模式和标准的过程。"},{"en":"First and foremost, we need to ensure the safety of all the participants in the activity.","zh":"首要的是，我们需要确保活动所有参与者的安全。"}]},{"phrase":"hand down","usage":"表示“把……世代相传，传承”，常用于传统、习俗、财产、故事等从一代人传到下一代人","examples":[{"en":"These craftsmanship skills have been handed down from generation to generation in the local area.","zh":"这些工艺技能在当地代代相传。"},{"en":"The necklace was handed down to her by her grandmother.","zh":"这条项链是她奶奶传给她的。"}]},{"phrase":"be incumbent upon sb to do sth","usage":"正式表达，意为“某人有义务/责任做某事”，强调责任的不可推卸性","examples":[{"en":"There is no social problem it is more incumbent upon us to understand than this of the role of custom.","zh":"我们有责任去理解的社会问题中，没有哪个比习俗的作用这个问题更重要了。"},{"en":"It is incumbent upon the government to provide basic medical services for all citizens.","zh":"政府有义务为所有公民提供基础医疗服务。"}]},{"phrase":"hold sway over","usage":"表示“支配，控制，对……有影响力”，用于描述观点、信仰、势力等对人的思想或行为的控制作用","examples":[{"en":"As long as these distinctions between ourselves and the primitive, ourselves and the barbarian, ourselves and the pagan, held sway over people's minds.","zh":"只要我们自己和原始人、自己和野蛮人、自己和异教徒之间的这些区别还支配着人们的思想。"},{"en":"Traditional values still hold sway over many people's choices in marriage.","zh":"传统观念仍然影响着很多人的婚姻选择。"}]},{"phrase":"substitute A for B","usage":"表示“用A代替B”，说明替换的对象和替代物","examples":[{"en":"The major social sciences have substituted the study of one local variation, that of Western civilization, for the study of human beings as a whole.","zh":"主要的社会学科用对一种本地变体（即西方文明）的研究，替代了对整个人类的研究。"},{"en":"We can substitute coconut milk for dairy milk in this recipe if you are lactose intolerant.","zh":"如果你乳糖不耐受，我们可以在这个食谱里用椰奶代替牛奶。"}]},{"phrase":"arrive at","usage":"除了表示到达某地，还可表示“达成（共识），得出（结论），达到（某种水平）”，后接抽象名词","examples":[{"en":"It was necessary first to arrive at that degree of sophistication where we no longer set our own belief against our neighbour's superstition.","zh":"我们首先必须达到这种成熟的认知程度：不再把我们自己的信仰和邻人的迷信对立起来。"},{"en":"After hours of discussion, the two sides finally arrived at an agreement.","zh":"经过数小时的讨论，双方最终达成了协议。"}]},{"phrase":"set ... against ...","usage":"表示“把……和……对立起来，使……和……抗衡”，用于描述两个事物被置于对立的关系中","examples":[{"en":"We should not set economic development against environmental protection.","zh":"我们不应该把经济发展和环境保护对立起来。"},{"en":"The manager set the performance of the new employee against that of the experienced staff.","zh":"经理把新员工的表现和老员工的表现做对比。"}]}],"grammar":[{"title":"倒装语序 (Inversion)","definition":"为了强调句子成分、保持句子结构平衡，将句子的谓语或谓语的一部分放到主语之前的语序结构，本课文中出现的是宾语前置的倒装","structure":"宾语 + 主语 + 谓语","usage":"当宾语被放到句首进行强调时，句子使用自然语序，不需要助动词提前，常用于突出动作的对象，增强表达的力度","examples":[{"en":"The inner workings of our own brains we feel to be uniquely worthy of investigation.","zh":"我们觉得自己大脑的内部活动才是唯一值得研究的。"},{"en":"All these problems I have already solved carefully.","zh":"所有这些问题我都已经仔细解决了。"}]},{"title":"as ... as 比例比较结构","definition":"用于比较两个事物在程度、比例等方面的关系，说明两者的比值相当","structure":"A is as + 名词/形容词 + as B","usage":"本句中用于表示前者和后者的比例关系，说明个体对习俗的影响和习俗对个体的塑造作用的比值，就像家庭吸收的婴儿用语占母语总词汇量的比例一样小","examples":[{"en":"The part played by custom in shaping the behaviour of the individual, as against any way in which he can affect traditional custom, is as the proportion of the total vocabulary of his mother tongue against those words of his own baby talk that are taken up into the vernacular of his family.","zh":"习俗在塑造个人行为方面所起的作用，和个人对传统习俗产生的任何影响相比，就如同他母语的总词汇量，和他自己的婴儿语被家庭日常用语吸收的词汇的比例一样。"},{"en":"The impact of a single individual on the development of history is as the drop of water against the whole ocean.","zh":"单个人对历史发展的影响，就如同一滴水和整个海洋的比例一样。"}]},{"title":"It is + 形容词 + that从句/不定式结构","definition":"it作为形式主语，代替真正的主语（that引导的主语从句或者不定式短语），避免句子头重脚轻，保持结构平衡","structure":"It is + 形容词/名词短语 + (for sb) + to do sth / that从句","usage":"常用于表达必要性、重要性、可能性等含义，是正式文体中常见的结构","examples":[{"en":"It was necessary first to arrive at that degree of sophistication where we no longer set our own belief against our neighbour's superstition.","zh":"我们首先必须达到这种成熟的认知程度：不再把我们自己的信仰和邻人的迷信对立起来。"},{"en":"It is essential that we should take measures to protect the endangered species immediately.","zh":"我们必须立即采取措施保护濒危物种，这十分重要。"}]}],"patterns":[{"pattern":"A has not commonly been regarded as ... As a matter of fact, it is the other way around.","explanation":"","original":{"en":"Custom has not commonly been regarded as a subject of any great moment. As a matter of fact, it is the other way around.","zh":"习俗通常不被认为是有重要研究价值的主题。事实上，情况恰恰相反。"},"examples":[{"en":"Failure has not commonly been regarded as a valuable experience. As a matter of fact, it is the other way around.","zh":"失败通常不被认为是一种有价值的经历。事实上，情况恰恰相反。"},{"en":"Introversion has not commonly been regarded as a personal advantage. As a matter of fact, it is the other way around.","zh":"内向通常不被认为是一种个人优势。事实上，情况恰恰相反。"}]},{"pattern":"The fact of first-rate importance is ...","explanation":"","original":{"en":"The fact of first-rate importance is the predominant role that custom plays in experience and in belief, and the very great varieties it may manifest.","zh":"最重要的事实是习俗在人的体验和信仰中起到的主导作用，以及它可能表现出的极其丰富的多样性。"},"examples":[{"en":"The fact of first-rate importance is the long-term impact of early education on children's personality development.","zh":"最重要的事实是早期教育对儿童性格发展的长期影响。"},{"en":"The fact of first-rate importance is that the company's innovation capability determines its long-term competitiveness in the market.","zh":"最重要的事实是，公司的创新能力决定了它在市场上的长期竞争力。"}]},{"pattern":"... can be profitable only after ...","explanation":"","original":{"en":"The study of custom can be profitable only after certain preliminary propositions have been accepted, and some of these propositions have been violently opposed.","zh":"只有在某些初步的主张被接受之后，对习俗的研究才会有收获，而其中一些主张曾遭到激烈的反对。"},"examples":[{"en":"The promotion of this new policy can be profitable only after the public has a full understanding of its benefits.","zh":"只有在公众充分理解这项新政策的好处之后，它的推行才会有成效。"},{"en":"Language learning can be profitable only after you have accumulated a certain amount of vocabulary and mastered basic grammar rules.","zh":"只有在你积累了一定量的词汇、掌握了基础语法规则之后，语言学习才会有收获。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“探查，探究” 对应的单词是？","hint":"noun · /ˈprəʊbɪŋ/","options":["dialysis","probing","potentiality","sensor"],"answer":1,"explain":"probing · /ˈprəʊbɪŋ/ · noun · 探查，探究。指对问题、真相进行深入的调查和探索","source":{"kind":"vocab","word":"probing"},"id":"b4-u44-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：有责任的，义不容辞的；现任的","hint":"/ɪnˈkʌmbənt/ · adjective","answer":"incumbent","placeholder":"输入英文单词","explain":"incumbent · /ɪnˈkʌmbənt/ · adjective · 有责任的，义不容辞的；现任的。常用于it is incumbent upon sb to do sth结构，表示某人有义务做某事；也可形容在职的人员","source":{"kind":"vocab","word":"incumbent"},"id":"b4-u44-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The life history of the individual is _____ an accommodation to the patterns and standards traditionally handed down in his community.","hint":"个人的生活史首先就是适应他所在社群世代相传的模式和标准的过程。","answer":"first and foremost","placeholder":"输入缺失的短语","explain":"first and foremost：用于强调最重要的、首要的因素，放在句首或主语后引出核心内容（个人的生活史首先就是适应他所在社群世代相传的模式和标准的过程。）","source":{"kind":"phrase","phrase":"first and foremost"},"id":"b4-u44-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Every _____ that is born into his group will share them with him,","hint":"每一个出生在他群体中的孩子都会与他分享这些，","answer":"child","placeholder":"输入缺失的单词","explain":"Every child that is born into his group will share them with him, — 每一个出生在他群体中的孩子都会与他分享这些，","source":{"kind":"sentence","en":"Every child that is born into his group will share them with him,"},"id":"b4-u44-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于比较两个事物在程度、比例等方面的关系，说明两者的比值相当” 描述的是哪个语法点？","hint":"A is as + 名词/形容词 + as B","options":["状语从句中的虚拟语气","as ... as 比例比较结构","原因状语从句","the + 比较级, the + 比较级 结构"],"answer":1,"explain":"as ... as 比例比较结构：A is as + 名词/形容词 + as B：本句中用于表示前者和后者的比例关系，说明个体对习俗的影响和习俗对个体的塑造作用的比值，就像家庭吸收的婴儿用语占母语总词汇量的比例一样小","source":{"kind":"grammar","title":"as ... as 比例比较结构"},"id":"b4-u44-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIn all the less controversial fields, like the study of cacti or termites or the nature of nebulae,","hint":"","options":["或者通过组成防御队形来保护他们免受鲨鱼的袭击。","通过这种方式，我们掌握了天文学的所有规律，或者说，掌握了群居昆虫的习性。","有一点是肯定的：我们会有医生和传教士，","在所有争议较少的领域，比如研究仙人掌、白蚁或星云的性质，"],"answer":3,"explain":"In all the less controversial fields, like the study of cacti or termites or the nature of nebulae, — 在所有争议较少的领域，比如研究仙人掌、白蚁或星云的性质，","source":{"kind":"sentence","en":"In all the less controversial fields, like the study of cacti or termites or the nature of nebulae,"},"id":"b4-u44-q06"}]},{"id":"b4-u45","book":4,"unit":45,"key":"45","lessonFrom":45,"lessonTo":45,"title":"Of Men and Galaxies","titleZh":"人类与星系","question":"What is the most influential factor in any human society?","sentences":[{"en":"In man's early days, competition with other creatures must have been critical.","zh":"在人类早期，与其他生物的竞争一定是至关重要的。","t":18.75},{"en":"But this phase of our development is now finished.","zh":"但我们发展的这个阶段现在已经结束了。","t":25.22},{"en":"Indeed, we lack practice and experience nowadays in dealing with primitive conditions.","zh":"事实上，我们现在缺乏处理原始条件的实践和经验。","t":28.88},{"en":"I am sure that, without modern weapons,","zh":"我确信，如果没有现代武器，","t":35.97},{"en":"I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand alone.","zh":"我在与熊争夺洞穴所有权方面会表现得很糟糕，而且我认为我并非孤身一人。","t":39.21},{"en":"The last creature to compete with man was the mosquito.","zh":"最后一种与人类竞争的生物是蚊子。","t":49.65},{"en":"But even the mosquito has been subdued by attention to drainage and by chemical sprays.","zh":"但即使是蚊子也因对排水的重视和化学喷雾而被制服了。","t":53.96},{"en":"Competition between ourselves, person against person,","zh":"我们彼此之间的竞争，人与人之间，","t":61.53},{"en":"community against community, still persists, however; and it is as fierce as it ever was.","zh":"社群与社群之间，仍然存在；而且它和以往一样激烈。","t":66.13},{"en":"But the competition of man against man is not the simple process envisioned in biology.","zh":"但人与人之间的竞争并不是生物学中设想的简单过程。","t":74.55},{"en":"It is not a simple competition for a fixed amount of food determined by the physical environment,","zh":"这不是一种由物理环境决定的对固定数量食物的简单竞争，","t":81.74},{"en":"because the environment that determines our evolution is no longer essentially physical.","zh":"因为决定我们进化的环境本质上不再是物理的了。","t":88.55},{"en":"Our environment is chiefly conditoned by the things we believe.","zh":"我们的环境主要由我们所相信的事物所决定。","t":95.73},{"en":"Morocco and California are bits of the Earth in very similar latitudes,","zh":"摩洛哥和加利福尼亚是地球上纬度非常相似的两个地方，","t":101.69},{"en":"both on the west coasts of continents with similar climates, and probably with rather similar natural resources.","zh":"都位于大陆西海岸，气候相似，而且可能拥有相当相似的自然资源。","t":107.47},{"en":"Yet their present development is wholly different,","zh":"然而，它们目前的发展却截然不同，","t":115.79},{"en":"not so much because of different people even,","zh":"甚至不是因为不同的人，","t":120.02},{"en":"but because of the different thoughts that exist in the minds of their inhabitants.","zh":"而是因为其居民心中存在的不同思想。","t":123.48},{"en":"This is the point I wish to emphasize.","zh":"这就是我希望强调的重点。","t":129.45},{"en":"The most important factor in our environment is the state of our own minds.","zh":"我们环境中最重要的因素是我们自己的心智状态。","t":132.44},{"en":"It is well known that where the white man has invaded a primitive culture,","zh":"众所周知，当白人侵入原始文化时，","t":139.02},{"en":"the most destructive effects have come not from physical weapons but from ideas.","zh":"最具破坏性的影响并非来自实体武器，而是来自思想。","t":144.02},{"en":"Ideas are dangerous.","zh":"思想是危险的。","t":151.35},{"en":"The Holy Office knew this full well when it caused heretics to be burned in days gone by.","zh":"过去的异端裁判所对此心知肚明，因为它曾将异教徒烧死。","t":154.29},{"en":"Indeed, the concept of free speech only exists in our modern society because when you are inside a community,","zh":"事实上，言论自由的概念之所以存在于我们的现代社会，是因为当你身处一个社群中时，","t":161.11},{"en":"you are conditioned by the conventions of the community to such a degree that it is very difficult to conceive of anything really destructive.","zh":"你被社群的习俗所制约，以至于很难构想出任何真正具有破坏性的事物。","t":170.23},{"en":"It is only someone looking on from outside that can inject the dangerous thoughts.","zh":"只有旁观者才能注入危险的思想。","t":180.76},{"en":"I do not doubt that it would be possible to inject ideas into the modern world that would utterly destroy us.","zh":"我不怀疑有可能向现代世界注入彻底摧毁我们的思想。","t":187.35},{"en":"I would like to give you an example, but fortunately I cannot do so.","zh":"我想给你们举个例子，但幸运的是我不能。","t":195.04},{"en":"Perhaps it will suffice to mention the nuclear bomb.","zh":"也许提到核弹就足够了。","t":201.17},{"en":"Imagine the effect on a reasonably advanced technological society,","zh":"想象一下，对一个相当先进的科技社会，","t":205.22},{"en":"one that still does not possess the bomb, of making it aware of the possibility, of supplying suffcient details to enable the thing to be constructed.","zh":"一个尚未拥有核弹的社会，如果让它意识到可能性，并提供足够的细节使其能够被建造出来，那会产生什么影响。","t":211},{"en":"20 or 30 pages of information handed to any of the major world powers around the year 1925,","zh":"1925年左右，将20或30页信息交给任何一个世界主要大国，","t":222.11},{"en":"would have been sufficient to change the course of world history.","zh":"足以改变世界历史的进程。","t":230.06},{"en":"It is a strange thought, but I believe a correct one,","zh":"这是一个奇怪的想法，但我相信它是正确的，","t":234.74},{"en":"that twenty or thirty pages of ideas and information would be capable of turning the present-day world upside down, or even destroying it.","zh":"即二三十页的思想和信息就足以颠覆当今世界，甚至摧毁它。","t":239.4},{"en":"I have often tried to conceive of what those pages might contain,","zh":"我曾多次试图构想那些页面可能包含什么，","t":252.66},{"en":"but of course I cannot do so because I am a prisoner of the present-day world, just as all of you are.","zh":"但我当然做不到，因为我是当今世界的囚徒，就像你们所有人一样。","t":258.18},{"en":"We cannot think outside the particular patterns that our brains are conditioned to, or,","zh":"我们无法跳出我们大脑被制约的特定模式进行思考，或者说，","t":266.81},{"en":"to be more accurate we can think only a very little way outside and then only if we are very original.","zh":"更准确地说，我们只能稍微跳出一点，而且只有当我们非常具有原创性时才能做到。","t":273.87}],"vocab":[{"word":"influential","phonetic":"/ˌɪnfluˈenʃl/","meanings":[{"pos":"adjective","meaning":"有影响力的，有支配力的","usage":"用来描述人、事物或因素对他人/事件有重要影响，可修饰抽象名词（如factor, idea）或具体名词（如person, organization）"}]},{"word":"critical","phonetic":"/ˈkrɪtɪkl/","meanings":[{"pos":"adjective","meaning":"至关重要的，决定性的","usage":"表示某物/某事对结果有决定性作用，常见搭配为be critical to/for sth"},{"pos":"adjective","meaning":"批评的，挑剔的","usage":"表示对人或事持否定评价，常见搭配为be critical of sb/sth"}]},{"word":"phase","phonetic":"/feɪz/","meanings":[{"pos":"noun","meaning":"阶段，时期","usage":"指发展过程中的一个特定阶段，常见搭配为phase of sth，enter/go through a phase"}]},{"word":"primitive","phonetic":"/ˈprɪmətɪv/","meanings":[{"pos":"adjective","meaning":"原始的，远古的","usage":"描述人类社会发展的早期阶段，或简陋、未发展的状态"}]},{"word":"dispute","phonetic":"/dɪˈspjuːt/","meanings":[{"pos":"verb","meaning":"争论，争夺","usage":"指对某事的所有权、真实性等提出异议或争夺，常见搭配为dispute sth with sb"},{"pos":"noun","meaning":"争端，纠纷","usage":"指两方或多方的争执，常见搭配为be in dispute over sth"}]},{"word":"subdue","phonetic":"/səbˈdjuː/","meanings":[{"pos":"verb","meaning":"制服，征服，抑制","usage":"表示通过力量或手段控制人、动物或事物，正式用语"}]},{"word":"drainage","phonetic":"/ˈdreɪnɪdʒ/","meanings":[{"pos":"noun","meaning":"排水系统，排水","usage":"指排出积水的系统或排水的动作、过程"}]},{"word":"envision","phonetic":"/ɪnˈvɪʒn/","meanings":[{"pos":"verb","meaning":"想象，预想","usage":"指对未来的情形进行想象或预期，常见搭配为envision sth / envision doing sth"}]},{"word":"latitude","phonetic":"/ˈlætɪtjuːd/","meanings":[{"pos":"noun","meaning":"纬度","usage":"地理术语，指地球表面某点与赤道的南北距离，对应反义词为longitude（经度）"}]},{"word":"inhabitant","phonetic":"/ɪnˈhæbɪtənt/","meanings":[{"pos":"noun","meaning":"居民，栖息者","usage":"指长期居住在某个地区的人或动物，同义词为resident"}]},{"word":"heretic","phonetic":"/ˈherətɪk/","meanings":[{"pos":"noun","meaning":"异端分子，持异端邪说的人","usage":"历史上指违背宗教正统教义的人，现在也可引申指持与主流不同观点的人"}]},{"word":"conceive","phonetic":"/kənˈsiːv/","meanings":[{"pos":"verb","meaning":"想象，构想","usage":"指在脑中形成想法、想象某种情形，常见搭配为conceive of sth / conceive that..."},{"pos":"verb","meaning":"怀孕，受孕","usage":"表示怀上胎儿的动作"}]},{"word":"inject","phonetic":"/ɪnˈdʒekt/","meanings":[{"pos":"verb","meaning":"注入，引入","usage":"原本指注射液体，引申为将某种思想、活力等引入某个群体或环境，常见搭配为inject sth into sb/sth"}]},{"word":"utterly","phonetic":"/ˈʌtəli/","meanings":[{"pos":"adverb","meaning":"完全地，彻底地","usage":"用于加强语气，修饰形容词或动词，通常带有较强的感情色彩"}]},{"word":"original","phonetic":"/əˈrɪdʒənl/","meanings":[{"pos":"adjective","meaning":"有独创性的，原创的","usage":"描述想法、作品或人具有新颖的、与众不同的特点"},{"pos":"noun","meaning":"原件，原作","usage":"指非复制的原版物品"}]}],"phrases":[{"phrase":"make a poor show of (doing) sth","usage":"表示在做某事时表现得很糟糕、笨拙，口语和书面语中都可使用，带有调侃或自嘲的语气","examples":[{"en":"I would make a very poor show of disputing the ownership of a cave with a bear.","zh":"要是我和一头熊争夺一个山洞的所有权，我肯定会表现得十分狼狈。"},{"en":"He made a poor show of apologizing, so no one was convinced.","zh":"他道歉的样子十分敷衍，所以没有人相信他。"}]},{"phrase":"stand alone","usage":"此处表示“孤立无援，只有自己一人（处于某种情况）”，也可指某事物独一无二、无人能及","examples":[{"en":"In this I do not think that I stand alone.","zh":"在这一点上，我觉得并非只有我一个人是这样。"},{"en":"When it comes to solving complex mathematical problems, he stands alone in his class.","zh":"在解决复杂数学问题这方面，他在班里无人能及。"}]},{"phrase":"be conditioned by","usage":"表示“受……的制约、影响”，通常指环境、习俗等外部因素对人的思想、行为产生塑造作用","examples":[{"en":"Our environment is chiefly conditioned by the things we believe.","zh":"我们的环境主要由我们所信奉的事物塑造。"},{"en":"People's consumption habits are conditioned by their income level.","zh":"人们的消费习惯受其收入水平的制约。"}]},{"phrase":"not so much... but...","usage":"表示“与其说是……不如说是……”，用于否定前者、强调后者，说明某结果的主要原因","examples":[{"en":"Yet their present development is wholly different, not so much because of different people even, but because of the different thoughts that exist in the minds of their inhabitants.","zh":"然而它们现在的发展完全不同，与其说是因为人种不同，不如说是因为当地居民头脑中的思想不同。"},{"en":"The project failed, not so much because of lack of funding, but because of poor management.","zh":"这个项目失败了，与其说是因为资金不足，不如说是因为管理不善。"}]},{"phrase":"know sth full well","usage":"表示“非常清楚，深知”，强调对某事了解得十分透彻，口语和书面语通用","examples":[{"en":"The Holy Office knew this full well when it caused heretics to be burned in days gone by.","zh":"宗教法庭对此心知肚明，所以过去才会把异端分子烧死。"},{"en":"She knew full well that he was lying, but she didn't point it out on the spot.","zh":"她非常清楚他在撒谎，但并没有当场指出来。"}]},{"phrase":"in days gone by","usage":"表示“在过去，从前”，属于书面正式表达，用于指代已经过去的历史时期","examples":[{"en":"In days gone by, people had to fetch water from wells every day.","zh":"从前，人们每天都得从井里打水。"}]},{"phrase":"to be more accurate","usage":"表示“更准确地说”，用于对前面提到的内容进行补充修正，使表述更严谨","examples":[{"en":"We cannot think outside the particular patterns that our brains are conditioned to, or, to be more accurate we can think only a very little way outside.","zh":"我们无法跳出大脑受制约形成的特定思维模式，或者更准确地说，我们只能稍微跳出一点这种模式。"},{"en":"The meeting will end next week, to be more accurate, next Friday afternoon.","zh":"会议将在下周结束，更准确地说，是下周五下午。"}]}],"grammar":[{"title":"虚拟语气用于对过去的推测","definition":"表示对过去发生的事情的可能性进行主观推测，并非描述客观事实，常用来表达肯定性的判断","structure":"must have + 过去分词","usage":"用于推测过去肯定发生了某件事，语气非常肯定，通常有一定的依据","examples":[{"en":"In man's early days, competition with other creatures must have been critical.","zh":"在人类早期，和其他生物的竞争肯定是至关重要的。"},{"en":"The ground is wet, so it must have rained last night.","zh":"地面是湿的，所以昨晚肯定下雨了。"}]},{"title":"虚拟条件句（与现在事实相反）","definition":"用来描述与当前现实不相符的假设情况，以及该假设会产生的结果，假设的内容不可能或很难发生","structure":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","usage":"用于表达对现实的假设、想象，句子描述的内容并非真实发生的情况","examples":[{"en":"I am sure that, without modern weapons, I would make a very poor show of disputing the ownership of a cave with a bear.","zh":"我敢肯定，如果没有现代武器，要是我和一头熊争夺一个山洞的所有权，我肯定会表现得十分狼狈。"},{"en":"If I were you, I would choose to study abroad after graduation.","zh":"如果我是你，我会选择毕业后出国留学。"}]},{"title":"分隔式定语从句","definition":"指定语从句和它所修饰的先行词被其他成分隔开，目的是保持句子结构平衡，避免头重脚轻","structure":"先行词 + 其他成分 + 关系词 + 定语从句","usage":"当先行词后面的定语从句过长，或先行词后有其他必要的修饰成分时，会将定语从句后置，和先行词分隔","examples":[{"en":"I do not doubt that it would be possible to inject ideas into the modern world that would utterly destroy us.","zh":"我毫不怀疑，向现代世界注入一些会彻底摧毁我们的思想是有可能的。（定语从句that would utterly destroy us修饰先行词ideas，被状语into the modern world隔开）"},{"en":"A new teacher will come tomorrow who will teach us English.","zh":"明天会来一位新老师，教我们英语。（定语从句who will teach us English修饰先行词teacher，被时间状语tomorrow隔开）"}]}],"patterns":[{"pattern":"The most + 形容词 + factor in + 领域/范围 is + 名词/名词短语","explanation":"","original":{"en":"The most important factor in our environment is the state of our own minds.","zh":"我们环境中最重要的因素是我们自身的思想状态。"},"examples":[{"en":"The most critical factor in learning a language well is consistent daily practice.","zh":"学好一门语言最重要的因素是每天持续的练习。"},{"en":"The most influential factor in a company's long-term development is its corporate culture.","zh":"一家公司长期发展最有影响力的因素是它的企业文化。"}]},{"pattern":"It is well known that where + 状语从句, the most + 形容词 + effects have come not from + 名词, but from + 名词","explanation":"","original":{"en":"It is well known that where the white man has invaded a primitive culture, the most destructive effects have come not from physical weapons but from ideas.","zh":"众所周知，凡是白人入侵原始文化的地方，最具破坏性的影响并非来自物质武器，而是来自思想。"},"examples":[{"en":"It is well known that where natural disasters occur, the most needed supplies come not from individual donations, but from government support.","zh":"众所周知，在发生自然灾害的地方，最急需的物资并非来自个人捐赠，而是来自政府扶持。"},{"en":"It is well known that where education is highly valued, the most obvious progress comes not from government investment alone, but from the participation of the whole society.","zh":"众所周知，在高度重视教育的地方，最显著的进步并非只来自政府投入，而是来自全社会的参与。"}]},{"pattern":"It is a strange thought, but I believe a correct one, that + 同位语从句","explanation":"","original":{"en":"It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas and information would be capable of turning the present-day world upside down, or even destroying it.","zh":"二三十页的思想和信息就能把当今世界搅得天翻地覆，甚至将其摧毁，这是一个奇怪的想法，但我认为是正确的。"},"examples":[{"en":"It is a surprising thought, but I believe a correct one, that a small habit we stick to every day can change the trajectory of our entire life.","zh":"我们每天坚持的一个小习惯就能改变整个人生的轨迹，这是一个惊人的想法，但我认为是正确的。"},{"en":"It is a counterintuitive thought, but I believe a correct one, that sometimes slowing down is the fastest way to achieve our goals.","zh":"有时候放慢速度反而是实现目标最快的方式，这是一个违反直觉的想法，但我认为是正确的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“异端分子，持异端邪说的人” 对应的单词是？","hint":"noun · /ˈherətɪk/","options":["sculpture","heretic","ticklish","inhabitant"],"answer":1,"explain":"heretic · /ˈherətɪk/ · noun · 异端分子，持异端邪说的人。历史上指违背宗教正统教义的人，现在也可引申指持与主流不同观点的人","source":{"kind":"vocab","word":"heretic"},"id":"b4-u45-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：制服，征服，抑制","hint":"/səbˈdjuː/ · verb","answer":"subdue","placeholder":"输入英文单词","explain":"subdue · /səbˈdjuː/ · verb · 制服，征服，抑制。表示通过力量或手段控制人、动物或事物，正式用语","source":{"kind":"vocab","word":"subdue"},"id":"b4-u45-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, people had to fetch water from wells every day.","hint":"从前，人们每天都得从井里打水。","answer":"in days gone by","placeholder":"输入缺失的短语","explain":"in days gone by：表示“在过去，从前”，属于书面正式表达，用于指代已经过去的历史时期（从前，人们每天都得从井里打水。）","source":{"kind":"phrase","phrase":"in days gone by"},"id":"b4-u45-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand _____","hint":"我在与熊争夺洞穴所有权方面会表现得很糟糕，而且我认为我并非孤身一人。","answer":"alone","placeholder":"输入缺失的单词","explain":"I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand alone. — 我在与熊争夺洞穴所有权方面会表现得很糟糕，而且我认为我并非孤身一人。","source":{"kind":"sentence","en":"I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand alone."},"id":"b4-u45-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来描述与当前现实不相符的假设情况，以及该假设会产生的结果，假设的内容不可能或很难发生” 描述的是哪个语法点？","hint":"If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形","options":["关系副词where与关系代词who引导的限定性定语从句","such...that...引导的结果状语从句","现在分词作结果状语","虚拟条件句（与现在事实相反）"],"answer":3,"explain":"虚拟条件句（与现在事实相反）：If + 主语 + 动词过去式（be动词用were）, 主语 + would/could/might + 动词原形：用于表达对现实的假设、想象，句子描述的内容并非真实发生的情况","source":{"kind":"grammar","title":"虚拟条件句（与现在事实相反）"},"id":"b4-u45-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nCompetition between ourselves, person against person,","hint":"","options":["我们彼此之间的竞争，人与人之间，","即使逆风，这介质似乎也在帮助它通过。","如果我们回想起在他那个时代，就像几个世纪以前一样，曲面玻璃是制造幻觉、谎言而非真相的流行手段；","无论他们作为父母和个人有多么优秀和称职，在某种程度上都是不可避免的。"],"answer":0,"explain":"Competition between ourselves, person against person, — 我们彼此之间的竞争，人与人之间，","source":{"kind":"sentence","en":"Competition between ourselves, person against person,"},"id":"b4-u45-q06"}]},{"id":"b4-u46","book":4,"unit":46,"key":"46","lessonFrom":46,"lessonTo":46,"title":"Hobbies","titleZh":"爱好","question":"Who, according to the author, are 'Fortune's favoured children'?","sentences":[{"en":"A gifted American psychologist has said, 'Worry is a spasm of the emotion;","zh":"一位才华出众的美国心理学家说过：“忧虑是感情的一种痉挛；","t":16.63},{"en":"the mind catches hold of something and will not let it go.'","zh":"思想一旦抓住了某件事就不会松手。”","t":23.02},{"en":"It is useless to argue with the mind in this condition.","zh":"在这种情况下，跟思想进行争辩是无济于事的。","t":27.45},{"en":"The stronger the will, the more futile the task.","zh":"意志越坚强，任务就越徒劳。","t":30.89},{"en":"One can only gently insinuate something else into its convulsive grasp.","zh":"人只能轻轻地向其痉挛的掌控中渗入其他东西。","t":34.54},{"en":"And if this something else is rightly chosen, if it is really attended by the illumination of another field of interest,","zh":"如果这种“其他东西”选择得当，如果它确实伴随着另一个兴趣领域的启迪，","t":39.98},{"en":"gradually, and often quite swiftly, the old undue grip relaxes and the process of recuperation and repair begins.","zh":"那么，旧有的不当掌控就会逐渐（而且往往是相当迅速地）放松，恢复和修复的过程就会开始。","t":48.31},{"en":"The cultivation of a hobby and new forms of interest is therefore a policy of the first importance to a public man.","zh":"因此，培养爱好和新的兴趣形式对公众人物来说是首要的策略。","t":59.3},{"en":"But this is not a business that can be undertaken in a day or swiftly improvised by a mere command of the will.","zh":"但这不是一天就能完成的，也不是单凭意志命令就能迅速凑成的。","t":67.87},{"en":"The growth of alternative mental interests is a long process.","zh":"培养替代性精神兴趣是一个漫长的过程。","t":75.76},{"en":"The seeds must be carefully chosen; they must fall on good ground;","zh":"种子必须精心挑选；它们必须落在好土壤里；","t":80.65},{"en":"they must be sedulously tended, if the vivifying fruits are to be at hand when needed.","zh":"它们必须勤勉照料，才能在需要时结出充满生机的果实。","t":85.47},{"en":"To be really happy and really safe, one ought to have at least two or three hobbies, and they must all be real.","zh":"要真正快乐和真正安全，一个人至少应该有两三个爱好，而且它们都必须是真实的。","t":92.62},{"en":"It is no use starting late in life to say: 'I will take an interest in this or that.'","zh":"在晚年才开始说：“我会对这个或那个感兴趣。”是没用的。","t":100.91},{"en":"Such an attempt only aggravates the strain of mental effort.","zh":"这种尝试只会加剧精神努力的负担。","t":106.63},{"en":"A man may acquire great knowledge of topics unconnected with his daily work, and yet get hardly any benefit or relief.","zh":"一个人可能对与日常工作无关的话题获得渊博的知识，但却几乎得不到任何益处或解脱。","t":111.36},{"en":"It is no use doing what you like; you have got to like what you do.","zh":"做你喜欢的事情是没有用的；你必须喜欢你所做的事情。","t":120.13},{"en":"Broadly speaking, human beings may be divided into three classes:","zh":"广义上说，人类可以分为三类：","t":124.74},{"en":"those who are toiled to death, those who are worried to death, and those who are bored to death.","zh":"那些劳累致死的人，那些忧虑致死的人，以及那些无聊致死的人。","t":130.27},{"en":"It is no use offering the manual labourer,","zh":"向体力劳动者提供，","t":138.48},{"en":"tired out with a hard week's sweat and effort the chance of playing a game of football or baseball on Saturday afternoon.","zh":"一个星期辛苦劳作、筋疲力尽的人，在周六下午打一场足球或棒球比赛的机会是没有用的。","t":142.04},{"en":"It is no use inviting the politician or the professional or business man, who has been working or worrying about serious things for six days,","zh":"邀请一个已经工作或为严肃的事情担忧了六天的政治家、专业人士或商人，","t":149.96},{"en":"to work or worry about trifling things at the weekend.","zh":"在周末去为琐碎的事情工作或担忧是没有用的。","t":159.87},{"en":"As for the unfortunate people who can command everything they want,","zh":"至于那些能得到他们想要的一切的不幸之人，","t":164.75},{"en":"who can gratify every caprice and lay their hands on almost every object of desire--for them a new pleasure a new excitement is only an additional satiation.","zh":"那些能满足每一个任性要求，几乎能得到所有渴望之物的人——对他们来说，新的快乐，新的兴奋只是一种额外的满足。","t":169.53},{"en":"In vain they rush frantically round from place to place, trying to escape from avenging boredom by mere clatter and motion.","zh":"他们徒劳地从一个地方狂奔到另一个地方，试图通过喧哗和移动来逃避复仇般的无聊。","t":182.4},{"en":"For them discipline in one form or another is the most hopeful path.","zh":"对他们来说，某种形式的纪律才是最有希望的道路。","t":191.88},{"en":"It may also be said that rational, industrious, useful human beings are divided into two classes:","zh":"也可以说，理智、勤劳、有用的人类分为两类：","t":198.49},{"en":"first, those whose work is work and whose pleasure is pleasure;","zh":"第一类，工作是工作，娱乐是娱乐；","t":206.14},{"en":"and secondly, those whose work and pleasure are one.","zh":"第二类，工作和娱乐合二为一。","t":211.2},{"en":"Of these the former are the majority. They have their compensations.","zh":"其中，前者是大多数。他们有他们的补偿。","t":215.49},{"en":"The long hours in the office or the factory bring with them as their reward,","zh":"办公室或工厂里的长时间工作带给他们的回报，","t":220.4},{"en":"not only the means of sustenance, but a keen appetite for pleasure even in its simplest and most modest forms.","zh":"不仅是维持生计的手段，而且是对即使是最简单、最朴素的乐趣的强烈渴望。","t":225.46},{"en":"But Fortune's favoured children belong to the second class.","zh":"但命运的宠儿属于第二类。","t":233.8},{"en":"Their life is a natural harmony.","zh":"他们的生活是自然的和谐。","t":238.17},{"en":"For them the working hours are never long enough.","zh":"对他们来说，工作时间永远不够长。","t":241.28},{"en":"Each day is a holiday, and ordinary holidays, when they come, are grudged as enforced interruptions in an absorbing vocation.","zh":"每天都是节日，而普通的假期，当它们到来时，却被视为对一个引人入胜的职业的强制性打断而感到不快。","t":244.92},{"en":"Yet to both classes, the need of an alternative outlook, of a change of atmosphere of a diversion of effort, is essential.","zh":"然而，对这两类人来说，需要一种不同的视角，一种改变氛围，一种转移精力的需求是必不可少的。","t":255.26},{"en":"Indeed, it may well be that those whose work is their pleasure are those who most need the means of banishing it at intervals from their minds.","zh":"事实上，那些以工作为乐的人，可能最需要时时将工作从他们脑海中驱逐出去的手段。","t":265.22}],"vocab":[{"word":"spasm","phonetic":"/ˈspæzəm/","meanings":[{"pos":"noun","meaning":"（感情的）突发；（肌肉的）痉挛","usage":"既可指生理上的肌肉抽搐，也可指情绪的突然发作"}]},{"word":"futile","phonetic":"/ˈfjuːtaɪl/","meanings":[{"pos":"adjective","meaning":"徒劳的；无用的","usage":"强调行动无法达成预期效果，无任何意义"}]},{"word":"insinuate","phonetic":"/ɪnˈsɪnjueɪt/","meanings":[{"pos":"verb","meaning":"逐渐潜入；旁敲侧击地暗示","usage":"表示缓慢、巧妙地将事物引入，或间接表达观点"}]},{"word":"convulsive","phonetic":"/kənˈvʌlsɪv/","meanings":[{"pos":"adjective","meaning":"抽搐的；惊厥的；突然失控的","usage":"常用来描述不受控制的、剧烈的动作或情绪状态"}]},{"word":"illumination","phonetic":"/ɪˌluːmɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"启发；阐明；照明","usage":"可指光线的照明，也可指知识、思想上的启发"}]},{"word":"undue","phonetic":"/ˌʌnˈdjuː/","meanings":[{"pos":"adjective","meaning":"过度的；不适当的","usage":"用来修饰超出正常、合理范围的事物"}]},{"word":"recuperation","phonetic":"/rɪˌkuːpəˈreɪʃn/","meanings":[{"pos":"noun","meaning":"恢复；复原","usage":"侧重指体力、精力或健康的恢复过程"}]},{"word":"sedulously","phonetic":"/ˈsedjʊləsli/","meanings":[{"pos":"adverb","meaning":"勤奋地；孜孜不倦地","usage":"强调付出持续、认真的努力"}]},{"word":"vivifying","phonetic":"/ˈvɪvɪfaɪɪŋ/","meanings":[{"pos":"adjective","meaning":"使有生气的；令人焕发精神的","usage":"描述事物能带来活力、让人恢复精力的特质"}]},{"word":"aggravate","phonetic":"/ˈæɡrəveɪt/","meanings":[{"pos":"verb","meaning":"加重；使恶化；激怒","usage":"通常指让原本不好的情况、问题变得更严重"}]},{"word":"caprice","phonetic":"/kəˈpriːs/","meanings":[{"pos":"noun","meaning":"反复无常；突发的奇想","usage":"指无理由、随意的想法或行为变化"}]},{"word":"satiation","phonetic":"/ˌseɪʃiˈeɪʃn/","meanings":[{"pos":"noun","meaning":"满足；饱足","usage":"常指过度满足后产生的腻烦感"}]},{"word":"frantically","phonetic":"/ˈfræntɪkli/","meanings":[{"pos":"adverb","meaning":"疯狂地；狂暴地","usage":"描述人在焦虑、慌乱状态下的行为状态"}]},{"word":"avenging","phonetic":"/əˈvendʒɪŋ/","meanings":[{"pos":"adjective","meaning":"报复性的；报应性的","usage":"用来描述带有惩罚、报复性质的事物"}]},{"word":"grudge","phonetic":"/ɡrʌdʒ/","meanings":[{"pos":"verb","meaning":"不情愿做；吝惜；怨恨","usage":"表示对某事感到不满、不愿意接受，也可指心怀怨恨"}]}],"phrases":[{"phrase":"catch hold of","usage":"表示抓住、握住某物，也可引申为掌握、理解某个想法或事物","examples":[{"en":"The mind catches hold of something and will not let it go.","zh":"大脑抓住某个念头不肯放开。"},{"en":"He caught hold of the rope to keep himself from falling.","zh":"他抓住绳子防止自己摔倒。"}]},{"phrase":"of the first importance","usage":"用来描述事物是最重要的、处于第一优先级的","examples":[{"en":"The cultivation of a hobby is therefore a policy of the first importance to a public man.","zh":"因此，对于公众人物来说，培养爱好和新的兴趣形式是头等重要的策略。"},{"en":"Regular exercise is a matter of the first importance for office workers.","zh":"对于上班族来说，定期锻炼是头等重要的事。"}]},{"phrase":"at hand","usage":"表示在手边、即将到来，或者可以随时使用","examples":[{"en":"The vivifying fruits are to be at hand when needed.","zh":"在需要的时候，能让人焕发活力的成果就能随时可用。"},{"en":"Keep your emergency kit at hand in case of accidents.","zh":"把你的应急包放在手边，以防发生意外。"}]},{"phrase":"tired out","usage":"表示极度疲惫、筋疲力尽，通常是因体力或脑力消耗过大导致","examples":[{"en":"The manual labourer is tired out with a hard week's sweat and effort.","zh":"体力劳动者经过一周辛苦的流汗劳作后已经筋疲力尽。"},{"en":"I was tired out after finishing the 10-kilometer marathon.","zh":"完成10公里马拉松后我筋疲力尽。"}]},{"phrase":"lay one's hands on","usage":"表示得到、找到某物，尤指经过努力后获得","examples":[{"en":"They can lay their hands on almost every object of desire.","zh":"他们几乎能得到所有想要的东西。"},{"en":"I finally laid my hands on the limited edition album I had been looking for.","zh":"我终于找到了我一直想要的那张限量版专辑。"}]},{"phrase":"in vain","usage":"表示徒劳、白费功夫，强调行动没有取得预期效果","examples":[{"en":"In vain they rush frantically round from place to place.","zh":"他们疯狂地从一个地方跑到另一个地方，却都是徒劳。"},{"en":"All the efforts we made to save the old building were in vain, as it was demolished finally.","zh":"我们为拯救这栋老建筑付出的所有努力都白费了，因为它最终还是被拆除了。"}]},{"phrase":"broadly speaking","usage":"常用作插入语，表示一般来说、广义上说，用于引出概括性的观点","examples":[{"en":"Broadly speaking, human beings may be divided into three classes.","zh":"广义上说，人类可以分为三类。"},{"en":"Broadly speaking, the project has achieved most of its expected goals.","zh":"总体来说，这个项目已经达成了大部分预期目标。"}]},{"phrase":"keen appetite for","usage":"表示对某事物有强烈的兴趣、渴望","examples":[{"en":"The long hours of work bring a keen appetite for pleasure even in its simplest forms.","zh":"长时间的工作让他们即使对最简单的快乐也有强烈的渴望。"},{"en":"Children raised in a reading environment usually have a keen appetite for books.","zh":"在阅读环境中长大的孩子通常对书籍有强烈的兴趣。"}]},{"phrase":"banish... from...","usage":"表示把……从……中驱逐、排除出去，可指具体事物也可指想法、情绪","examples":[{"en":"They need the means of banishing work at intervals from their minds.","zh":"他们需要偶尔能把工作从脑海中排除出去的方法。"},{"en":"You should banish negative thoughts from your mind before the interview.","zh":"面试前你应该把消极的想法从脑海中赶出去。"}]}],"grammar":[{"title":"It is + adj./n. + to do 结构","definition":"这是英语中常见的形式主语结构，it为形式主语，真正的主语是后面的不定式短语，用来避免句子头重脚轻","structure":"It is + 形容词/名词短语 + (for sb.) + to do sth.","usage":"常用于表达做某事是怎样的，属于非常高频的书面和口语句式","examples":[{"en":"It is useless to argue with the mind in this condition.","zh":"在这种情况下和大脑争辩是没有用的。"},{"en":"It is very important for students to develop independent thinking ability.","zh":"对学生来说，培养独立思考能力非常重要。"}]},{"title":"the + 比较级, the + 比较级 结构","definition":"表示“越……，就越……”，用于描述两个变化过程的相关性","structure":"The + 形容词/副词比较级 + 陈述句，the + 形容词/副词比较级 + 陈述句","usage":"可以用来清晰表达两个变量之间的正相关或负相关关系，常用于说理类文本","examples":[{"en":"The stronger the will, the more futile the task.","zh":"意志越坚定，这个任务就越徒劳。"},{"en":"The more careful you are when doing homework, the fewer mistakes you will make.","zh":"你做作业的时候越仔细，犯的错误就越少。"}]},{"title":"定语从句的分隔用法","definition":"定语从句与先行词被其他成分分隔开的情况，通常是为了平衡句子结构，避免头重脚轻","structure":"先行词 + 其他修饰成分 + 关系代词/关系副词 + 定语从句","usage":"阅读时需要先找到先行词，理清句子结构，才能准确理解句意，常见于复杂的书面文本","examples":[{"en":"It is no use offering the manual labourer, tired out with a hard week's sweat and effort, the chance of playing a game of football.","zh":"给经过一周辛苦劳作、筋疲力尽的体力劳动者提供踢足球的机会是没有用的。"},{"en":"I know the girl in the red dress, who won the first prize in the speech contest last month.","zh":"我认识那个穿红裙子的女孩，她上个月在演讲比赛中得了一等奖。"}]}],"patterns":[{"pattern":"A gifted + 职业 + has said, '引语'.","explanation":"","original":{"en":"A gifted American psychologist has said, 'Worry is a spasm of the emotion; the mind catches hold of something and will not let it go.'","zh":"一位有天赋的美国心理学家曾说过：“忧虑是情绪的一阵痉挛；大脑抓住某个念头不肯放开。”"},"examples":[{"en":"A gifted education expert has said, 'The best way to cultivate children's creativity is to give them enough space to explore freely.'","zh":"一位有天赋的教育专家曾说过：“培养孩子创造力最好的方法就是给他们足够的自由探索空间。”"},{"en":"A gifted environmentalist has said, 'The protection of ecosystems is not a choice but a responsibility for all human beings.'","zh":"一位有天赋的环保主义者曾说过：“保护生态系统不是一种选择，而是全人类的责任。”"}]},{"pattern":"Broadly speaking, 群体 may be divided into + 数量 classes: 具体分类.","explanation":"","original":{"en":"Broadly speaking, human beings may be divided into three classes: those who are toiled to death, those who are worried to death, and those who are bored to death.","zh":"广义上说，人类可以分为三类：劳累至死的人，忧虑至死的人，以及无聊至死的人。"},"examples":[{"en":"Broadly speaking, college students may be divided into three classes: those who focus on academic research, those who actively participate in social practice, and those who are confused about their future.","zh":"广义上说，大学生可以分为三类：专注学术研究的人，积极参加社会实践的人，以及对未来感到迷茫的人。"},{"en":"Broadly speaking, fitness participants may be divided into three classes: those who want to lose weight, those who want to build muscle, and those who just want to keep healthy.","zh":"广义上说，健身人群可以分为三类：想要减重的人，想要增肌的人，以及只是想要保持健康的人。"}]},{"pattern":"Of these the former are the majority. They have their compensations.","explanation":"","original":{"en":"Of these the former are the majority. They have their compensations.","zh":"在这两类人中，前者占大多数。他们有自己的补偿。"},"examples":[{"en":"Of these two options the former is more popular with young people. They have their unique advantages.","zh":"在这两个选择中，前者更受年轻人欢迎。它们有自己独特的优势。"},{"en":"Of these two learning methods the former is more suitable for beginners. They have lower requirements for basic knowledge.","zh":"在这两种学习方法中，前者更适合初学者。它们对基础知识的要求更低。"}]},{"pattern":"Indeed, it may well be that + 从句.","explanation":"","original":{"en":"Indeed, it may well be that those whose work is their pleasure are those who most need the means of banishing it at intervals from their minds.","zh":"事实上，很可能那些以工作为乐的人最需要偶尔能把工作从脑海中排除出去的方法。"},"examples":[{"en":"Indeed, it may well be that those who always appear strong are those who need care and understanding most.","zh":"事实上，很可能那些总是看起来很坚强的人是最需要关心和理解的人。"},{"en":"Indeed, it may well be that the simplest daily habits are the key to maintaining long-term health.","zh":"事实上，很可能最简单的日常习惯是保持长期健康的关键。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“逐渐潜入；旁敲侧击地暗示” 对应的单词是？","hint":"verb · /ɪnˈsɪnjueɪt/","options":["insinuate","speculation","dignity","vulgar"],"answer":0,"explain":"insinuate · /ɪnˈsɪnjueɪt/ · verb · 逐渐潜入；旁敲侧击地暗示。表示缓慢、巧妙地将事物引入，或间接表达观点","source":{"kind":"vocab","word":"insinuate"},"id":"b4-u46-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：恢复；复原","hint":"/rɪˌkuːpəˈreɪʃn/ · noun","answer":"recuperation","placeholder":"输入英文单词","explain":"recuperation · /rɪˌkuːpəˈreɪʃn/ · noun · 恢复；复原。侧重指体力、精力或健康的恢复过程","source":{"kind":"vocab","word":"recuperation"},"id":"b4-u46-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：All the efforts we made to save the old building were _____, as it was demolished finally.","hint":"我们为拯救这栋老建筑付出的所有努力都白费了，因为它最终还是被拆除了。","answer":"in vain","placeholder":"输入缺失的短语","explain":"in vain：表示徒劳、白费功夫，强调行动没有取得预期效果（我们为拯救这栋老建筑付出的所有努力都白费了，因为它最终还是被拆除了。）","source":{"kind":"phrase","phrase":"in vain"},"id":"b4-u46-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It is no use inviting the politician or the professional or business man, who has been working or worrying about serious things for six _____","hint":"邀请一个已经工作或为严肃的事情担忧了六天的政治家、专业人士或商人，","answer":"days","placeholder":"输入缺失的单词","explain":"It is no use inviting the politician or the professional or business man, who has been working or worrying about serious things for six days, — 邀请一个已经工作或为严肃的事情担忧了六天的政治家、专业人士或商人，","source":{"kind":"sentence","en":"It is no use inviting the politician or the professional or business man, who has been working or worrying about serious things for six days,"},"id":"b4-u46-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“定语从句与先行词被其他成分分隔开的情况，通常是为了平衡句子结构，避免头重脚轻” 描述的是哪个语法点？","hint":"先行词 + 其他修饰成分 + 关系代词/关系副词 + 定语从句","options":["被动语态","定语从句的分隔用法","同位语从句","让步状语从句：however引导的让步结构"],"answer":1,"explain":"定语从句的分隔用法：先行词 + 其他修饰成分 + 关系代词/关系副词 + 定语从句：阅读时需要先找到先行词，理清句子结构，才能准确理解句意，常见于复杂的书面文本","source":{"kind":"grammar","title":"定语从句的分隔用法"},"id":"b4-u46-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nthe mind catches hold of something and will not let it go.'","hint":"","options":["它似乎非常适合居住。","作家开始辨明他材料中那些在开始时并未意识到的东西。","1953年，一位50多岁、曾任电子工程师的克里斯托弗·科克雷尔，","思想一旦抓住了某件事就不会松手。”"],"answer":3,"explain":"the mind catches hold of something and will not let it go.' — 思想一旦抓住了某件事就不会松手。”","source":{"kind":"sentence","en":"the mind catches hold of something and will not let it go.'"},"id":"b4-u46-q06"}]},{"id":"b4-u47","book":4,"unit":47,"key":"47","lessonFrom":47,"lessonTo":47,"title":"The Great Escape","titleZh":"绝妙的逃离","question":"What is one of the features of modern camping where nationality is concerned?","sentences":[{"en":"Economy is one powerful motive for camping,","zh":"经济是露营的一个强大动力，","t":18.1},{"en":"since after the initial outlay upon equipment, or through hiring it, the total expense can be far less than the cost of hotels.","zh":"因为在设备初期投入或租用之后，总费用会远低于住酒店的开销。","t":22.33},{"en":"But, contrary to a popular assumption, it is far from being the only one, or even the greatest.","zh":"但是，与一种普遍的看法相反，这绝非唯一的，甚至也不是最大的动力。","t":34.23},{"en":"The man who manoeuvres carelessly into his 20 pounds' worth of space at one of Europe's myriad permanent sites may find himself bumping a Bentley.","zh":"那个漫不经心地把车开进欧洲无数固定营地之一、仅值20英镑空间的露营者，可能会发现自己的车碰到了宾利。","t":44.23},{"en":"More likely, Ford Escort will be hub to hub with Renault or Mercedes, but rarely with bicycles made for two.","zh":"更可能的情况是，福特Escort会和雷诺或梅赛德斯并排停放，但很少会和双人自行车并排。","t":55.54},{"en":"That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox for the cynic,","zh":"现代露营设备每年都变得更加精密，这对愤世嫉俗者来说是一个有趣的悖论，","t":66.19},{"en":"a brighter promise for the hopeful traveller who has sworn to get away from it all.","zh":"对发誓要摆脱一切的满怀希望的旅行者来说则是一个更美好的前景。","t":75.25},{"en":"It also provides--and some student sociologist might care to base his thesis upon the phenomenon--an escape of another kind.","zh":"它还提供了——某个社会学学生或许会以此现象为基础撰写论文——另一种形式的逃离。","t":81.14},{"en":"The modern traveller is often a man who dislikes the Splendide and the Bellavista,","zh":"现代旅行者往往不喜欢“Splendide”和“Bellavista”这样的酒店，","t":93.12},{"en":"not because he cannot afford, or shuns their material comforts, but because he is afraid of them.","zh":"不是因为他负担不起或避开它们的物质享受，而是因为他害怕它们。","t":99.19},{"en":"Affluent he may be, but he is by no means sure what to tip the doorman or the chambermaid.","zh":"他可能很富裕，但绝不确定该给门童或女服务员多少小费。","t":107.22},{"en":"Master in his own house he has little idea of when to say boo to a manager hotel.","zh":"他在自己家里是个主人，却不知道何时该对酒店经理发号施令。","t":115.49},{"en":"From all such fears camping releases him.","zh":"露营将他从所有这些恐惧中解脱出来。","t":124.49},{"en":"Granted, a snobbery of camping itself, based upon equipment and techniques, already exists;","zh":"诚然，露营本身就存在一种基于装备和技术的势利眼；","t":128.23},{"en":"but it is of a kind that, if he meets it, he can readily understand and deal with.","zh":"但如果他遇到这种势利，他也能很容易理解和应对。","t":136.19},{"en":"There is no superior 'they' in the shape of managements and hotel hierarchies to darken his holiday days.","zh":"没有以管理层和酒店等级制度形式出现的上级“他们”来给他假期蒙上阴影。","t":142.93},{"en":"To such motives, yet another must be added.","zh":"除了这些动机，还必须加上另一个。","t":152.21},{"en":"The contemporary phenomenon of car worship is to be explained not least by the sense of independence and freedom that ownership entails.","zh":"当代汽车崇拜现象，其原因很大程度上在于拥有汽车所带来的独立和自由感。","t":156.45},{"en":"To this pleasure camping gives an exquisite refinement.","zh":"露营为这种乐趣增添了一种精致的升华。","t":167.35},{"en":"From one's own front door to home or foreign hills or sands and back again, everything is to hand.","zh":"从自家门前到国内或国外的山丘沙滩再返回，一切尽在掌握。","t":172.24},{"en":"Not only are the means of arriving at the holiday paradise entirely within one's own command and keeping,","zh":"不仅抵达度假天堂的交通工具完全由自己掌控和保管，","t":181.5},{"en":"but the means of escape from holiday hell (if the beach proves too crowded, the local weather too inclement)","zh":"而且从度假地狱中逃脱的手段（如果海滩过于拥挤，当地天气过于恶劣）","t":189.13},{"en":"are there, outside--or, as likely, part of--the tent.","zh":"就在帐篷外面——或者，更有可能的是，就在帐篷里。","t":197.68},{"en":"Idealists have objected to the practice of camping, as to the package tour,","zh":"理想主义者反对露营，就像反对跟团游一样，","t":205.2},{"en":"that the traveller abroad thereby denies himself the opportunity of getting to know the people of the country visited.","zh":"认为出国旅行者因此剥夺了自己了解所访国家人民的机会。","t":211.06},{"en":"Insularity and self-containment, it is argued, go hand in hand.","zh":"有人认为，与世隔绝和自我封闭是并存的。","t":218.46},{"en":"The opinion does not survive experience of a popular Continental camping place.","zh":"但这种观点在体验过一个受欢迎的欧洲大陆露营地后便不攻自破。","t":224.87},{"en":"Holiday hotels tend to cater for one nationality of visitors especially, sometimes exclusively.","zh":"度假酒店往往特别迎合——有时甚至专门迎合——某一国籍的游客。","t":230.49},{"en":"Camping sites, by contrast, are highly cosmopolitan.","zh":"相比之下，露营地则高度国际化。","t":239.77},{"en":"Granted, a preponderance of Germans is a characteristic that seems common to most Mediterranean sites;","zh":"诚然，德国人占多数似乎是大多数地中海营地的共同特点；","t":244.55},{"en":"but as yet there is no overwhelmingly specialized patronage.","zh":"但到目前为止，还没有出现压倒性的专业赞助。","t":252.51},{"en":"Notices forbidding the open-air drying of clothes,","zh":"禁止户外晾晒衣物、","t":258.28},{"en":"or the use of water points for car washing,","zh":"禁止使用取水点洗车，","t":261.77},{"en":"or those inviting 'our camping friends' to a dance or a boat trip are printed not only in French or Italian or Spanish, but also in English, German and Dutch.","zh":"或者邀请“我们的露营朋友”参加舞会或乘船游览的告示，不仅用法语、意大利语或西班牙语印制，也用英语、德语和荷兰语印制。","t":265.3},{"en":"At meal times the odour of sauerkraut vies with that of garlic.","zh":"用餐时，酸菜味与大蒜味相互竞争。","t":277.99},{"en":"The Frenchman's breakfast coffee competes with the Englishman's bacon and eggs.","zh":"法国人的早餐咖啡与英国人的培根鸡蛋相互抗衡。","t":283.13},{"en":"Whether the remarkable growth of organized camping means the eventual death of the more independent kind is hard to say.","zh":"有组织的露营的显著增长是否意味着更独立露营方式的最终消亡，这很难说。","t":289.73},{"en":"Municipalities naturally want to secure the campers' site fees and other custom.","zh":"市政府自然希望确保露营者的场地费和其他消费。","t":298.15},{"en":"Police are wary of itinerants who cannot be traced to a recognized camp boundary or to four walls.","zh":"警方对那些无法追溯到已认可营地边界或有四面墙壁的流浪者保持警惕。","t":304.09},{"en":"But most probably it will all depend upon campers themselves: how many heath fires they cause; how much litter they leave;","zh":"但最有可能的是，这一切都将取决于露营者自己：他们引发了多少荒地火灾；他们留下了多少垃圾；","t":312.15},{"en":"in short, whether or not they wholly alienate landowners and those who live in the countryside.","zh":"简而言之，他们是否完全疏远了土地所有者和那些住在乡村的人。","t":323.04},{"en":"Only good scouting is likely to preserve the freedoms so dear to the heart of the eternal Boy Scout.","zh":"只有良好的童子军精神才可能维护那些永恒的童子军心中珍爱的自由。","t":331.48}],"vocab":[{"word":"motive","phonetic":"/ˈməʊtɪv/","meanings":[{"pos":"noun","meaning":"动机，目的","usage":"指促使某人做某事的原因，常与for搭配"}]},{"word":"outlay","phonetic":"/ˈaʊtleɪ/","meanings":[{"pos":"noun","meaning":"（启动项目的）开支，费用","usage":"尤指一次性的初期支出，常与on/upon搭配"}]},{"word":"myriad","phonetic":"/ˈmɪriəd/","meanings":[{"pos":"adjective","meaning":"无数的，大量的","usage":"修饰可数名词复数，强调数量极多"}]},{"word":"sophisticated","phonetic":"/səˈfɪstɪkeɪtɪd/","meanings":[{"pos":"adjective","meaning":"复杂精密的；先进的","usage":"可形容设备、技术等功能复杂先进"}]},{"word":"paradox","phonetic":"/ˈpærədɒks/","meanings":[{"pos":"noun","meaning":"矛盾的现象，悖论","usage":"指看似矛盾但可能有其合理性的情况"}]},{"word":"shun","phonetic":"/ʃʌn/","meanings":[{"pos":"verb","meaning":"回避，避开","usage":"强调主动刻意避开某人或某事物，后直接接宾语"}]},{"word":"affluent","phonetic":"/ˈæfluənt/","meanings":[{"pos":"adjective","meaning":"富裕的，富足的","usage":"形容人或地区经济条件优渥"}]},{"word":"hierarchy","phonetic":"/ˈhaɪərɑːki/","meanings":[{"pos":"noun","meaning":"等级制度，统治集团","usage":"指组织中的层级结构，或处于上层的管理群体"}]},{"word":"entail","phonetic":"/ɪnˈteɪl/","meanings":[{"pos":"verb","meaning":"使必要，附带（后果）","usage":"指某事物必然包含或导致某种结果，后接名词/动名词"}]},{"word":"exquisite","phonetic":"/ɪkˈskwɪzɪt/","meanings":[{"pos":"adjective","meaning":"精致的，绝妙的","usage":"形容事物质量极高、体验极佳"}]},{"word":"inclement","phonetic":"/ɪnˈklemənt/","meanings":[{"pos":"adjective","meaning":"（天气）恶劣的，凛冽的","usage":"专门用来形容天气寒冷、下雨等不适宜外出的情况"}]},{"word":"cosmopolitan","phonetic":"/ˌkɒzməˈpɒlɪtən/","meanings":[{"pos":"adjective","meaning":"国际性的，世界性的","usage":"形容地方有来自世界各地的人，文化多元"}]},{"word":"preponderance","phonetic":"/prɪˈpɒndərəns/","meanings":[{"pos":"noun","meaning":"多数，优势","usage":"指数量上占绝大多数，常与of搭配"}]},{"word":"alienate","phonetic":"/ˈeɪliəneɪt/","meanings":[{"pos":"verb","meaning":"疏远，得罪","usage":"指行为导致他人不再友好支持，常用搭配alienate sb from sb"}]}],"phrases":[{"phrase":"far from","usage":"表示“远非，完全不”，用于否定某一说法，后可接形容词、动名词或名词","examples":[{"en":"It is far from being the only advantage of reading.","zh":"这完全不是阅读的唯一好处。"}]},{"phrase":"by no means","usage":"表示“绝不，一点也不”，用于加强否定语气，可置于句首（需倒装）或句中","examples":[{"en":"He is by no means an experienced teacher.","zh":"他绝不是一个有经验的老师。"}]},{"phrase":"go hand in hand","usage":"表示“密切相关，相伴而生”，说明两个事物同时存在、互相关联","examples":[{"en":"Poverty and poor health often go hand in hand.","zh":"贫穷和健康不佳往往是相伴而生的。"}]},{"phrase":"cater for","usage":"表示“满足需要，迎合”，主语通常为服务类机构，后接服务对象","examples":[{"en":"This restaurant caters for vegetarians.","zh":"这家餐厅提供素食餐食，满足素食者的需求。"}]},{"phrase":"be wary of","usage":"表示“提防，警惕”，指对可能的风险或问题保持谨慎","examples":[{"en":"You should be wary of strangers who ask for personal information.","zh":"你要警惕索要你个人信息的陌生人。"}]},{"phrase":"get away from it all","usage":"口语常用表达，指“远离尘嚣，彻底放松”，尤指通过度假逃离日常的压力和繁琐","examples":[{"en":"Many people go to the countryside on weekends to get away from it all.","zh":"很多人周末去乡下，彻底逃离城市的喧嚣放松自己。"}]},{"phrase":"within one's command","usage":"表示“在某人的掌控之中，可由某人自由支配”","examples":[{"en":"With enough savings, you will have more choices within your command.","zh":"有足够的存款，你就能有更多可以自主选择的机会。"}]}],"grammar":[{"title":"形容词/名词前置的倒装结构","definition":"为了强调表语内容，将作表语的形容词、名词或分词置于句首，形成“表语 + 主语 + be/系动词”的倒装结构，语义等同于正常语序，语气更强烈","structure":"Adjective/Noun + 主语 + be/系动词","usage":"多用于书面语中，突出强调表语的属性，同时让句子结构更有节奏感","examples":[{"en":"Affluent he may be, but he is by no means happy.","zh":"他或许很富裕，但他一点也不快乐。"},{"en":"Master in his own house he has little idea of how to deal with public occasions.","zh":"他在自己家里是主人，却完全不知道如何应对公开场合。"}]},{"title":"主语从句作主语的结构","definition":"用完整的句子充当主语，说明整件事的性质或影响，通常用it作形式主语置于句首，将真正的主语从句后置，避免头重脚轻","structure":"It + 系动词 + 名词/形容词 + that引导的主语从句 / That引导的主语从句 + 谓语 + 其他成分","usage":"用于描述某个事件、情况的属性，that在从句中不充当成分，无实际含义，仅起连接作用","examples":[{"en":"That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox.","zh":"现代露营装备一年比一年精密，这对愤世嫉俗的人来说是个有意思的矛盾现象。"},{"en":"It is obvious that regular exercise benefits people's health a lot.","zh":"很明显，定期锻炼对人们的健康大有裨益。"}]},{"title":"granted作引导词的让步状语结构","definition":"granted（或granted that）作为从属连词，引导让步状语从句，表示“诚然，的确”，先承认某一事实的存在，后面主句引出相反或转折的观点","structure":"Granted (that) + 让步分句, + 主句（表转折）","usage":"用于议论文中先肯定对立观点的合理性，再阐述自己的核心观点，让论证更客观严谨","examples":[{"en":"Granted, a snobbery of camping itself already exists, but it is easy to deal with.","zh":"诚然，露营本身已经存在基于装备和技术的势利现象，但这种情况很容易应对。"},{"en":"Granted that this plan has some drawbacks, its advantages far outweigh them.","zh":"诚然这个计划有一些缺点，但它的优点远多于缺点。"}]}],"patterns":[{"pattern":"... is one powerful motive for..., since...","explanation":"","original":{"en":"Economy is one powerful motive for camping, since after the initial outlay upon equipment, or through hiring it, the total expense can be far less than the cost of hotels.","zh":"省钱是露营的一大主要动机，因为除了最初购置装备的费用，或是可以租用装备，总花费要比住酒店便宜得多。"},"examples":[{"en":"Flexibility is one powerful motive for choosing remote work, since you can arrange your schedule according to your own needs.","zh":"灵活性是选择远程工作的一大主要动机，因为你可以根据自己的需求安排日程。"},{"en":"Cultural experience is one powerful motive for studying abroad, since you can get immersed in a totally different social environment.","zh":"文化体验是出国留学的一大主要动机，因为你可以沉浸在完全不同的社会环境中。"}]},{"pattern":"..., contrary to a popular assumption, it is far from being the only one, or even the greatest.","explanation":"","original":{"en":"But, contrary to a popular assumption, it is far from being the only one, or even the greatest.","zh":"但是，和普遍的设想相反，这远不是唯一的动机，甚至算不上是最主要的动机。"},"examples":[{"en":"Many people think high marks mean all for students, but contrary to a popular assumption, it is far from being the only indicator of ability, or even the greatest.","zh":"很多人觉得高分对学生来说意味着一切，但和普遍的设想相反，这远不是能力的唯一指标，甚至算不上是最重要的指标。"},{"en":"People often believe that salary is the most important factor for a job, but contrary to a popular assumption, it is far from being the only thing we care about, or even the greatest.","zh":"人们通常认为薪资是工作最重要的因素，但和普遍的设想相反，这远不是我们在意的唯一方面，甚至算不上是最主要的。"}]},{"pattern":"To such motives, yet another must be added.","explanation":"","original":{"en":"To such motives, yet another must be added.","zh":"除了这些动机之外，还有另外一个动机。"},"examples":[{"en":"To such benefits of learning a foreign language, yet another must be added: it helps you understand different ways of thinking.","zh":"除了学习外语的这些好处之外，还要加上另外一点：它能帮助你理解不同的思维方式。"},{"en":"To such reasons for the popularity of social media, yet another must be added: it makes it easier to keep in touch with old friends.","zh":"除了社交媒体流行的这些原因之外，还要加上另外一点：它让和老朋友保持联系变得更容易。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“精致的，绝妙的” 对应的单词是？","hint":"adjective · /ɪkˈskwɪzɪt/","options":["erode","alienate","exquisite","primitive"],"answer":2,"explain":"exquisite · /ɪkˈskwɪzɪt/ · adjective · 精致的，绝妙的。形容事物质量极高、体验极佳","source":{"kind":"vocab","word":"exquisite"},"id":"b4-u47-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：使必要，附带（后果）","hint":"/ɪnˈteɪl/ · verb","answer":"entail","placeholder":"输入英文单词","explain":"entail · /ɪnˈteɪl/ · verb · 使必要，附带（后果）。指某事物必然包含或导致某种结果，后接名词/动名词","source":{"kind":"vocab","word":"entail"},"id":"b4-u47-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It is _____ being the only advantage of reading.","hint":"这完全不是阅读的唯一好处。","answer":"far from","placeholder":"输入缺失的短语","explain":"far from：表示“远非，完全不”，用于否定某一说法，后可接形容词、动名词或名词（这完全不是阅读的唯一好处。）","source":{"kind":"phrase","phrase":"far from"},"id":"b4-u47-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：To this _____ camping gives an exquisite refinement.","hint":"露营为这种乐趣增添了一种精致的升华。","answer":"pleasure","placeholder":"输入缺失的单词","explain":"To this pleasure camping gives an exquisite refinement. — 露营为这种乐趣增添了一种精致的升华。","source":{"kind":"sentence","en":"To this pleasure camping gives an exquisite refinement."},"id":"b4-u47-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“为了强调表语内容，将作表语的形容词、名词或分词置于句首，形成“表语 + 主语 + be/系动词”的倒装结构，语义等同于正常语序，语气更强烈” 描述的是哪个语法点？","hint":"Adjective/Noun + 主语 + be/系动词","options":["破折号的解释说明用法","状语从句中的虚拟语气","形容词/名词前置的倒装结构","宾语从句（deduce后接并列宾语从句）"],"answer":2,"explain":"形容词/名词前置的倒装结构：Adjective/Noun + 主语 + be/系动词：多用于书面语中，突出强调表语的属性，同时让句子结构更有节奏感","source":{"kind":"grammar","title":"形容词/名词前置的倒装结构"},"id":"b4-u47-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nBut most probably it will all depend upon campers themselves: how many heath fires they cause; how much litter they leave;","hint":"","options":["但这些与人类衰老时发生的情况并不相似。","很快，这些误差将倍增到十英尺的尺度，并以此类推，直到全球范围。","口袋里带着一瓶他妻子卡莱尔夫人以前因病服用后剩下的药水。","但最有可能的是，这一切都将取决于露营者自己：他们引发了多少荒地火灾；他们留下了多少垃圾；"],"answer":3,"explain":"But most probably it will all depend upon campers themselves: how many heath fires they cause; how much litter they leave; — 但最有可能的是，这一切都将取决于露营者自己：他们引发了多少荒地火灾；他们留下了多少垃圾；","source":{"kind":"sentence","en":"But most probably it will all depend upon campers themselves: how many heath fires they cause; how much litter they leave;"},"id":"b4-u47-q06"}]},{"id":"b4-u48","book":4,"unit":48,"key":"48","lessonFrom":48,"lessonTo":48,"title":"Planning a Share Portfolio","titleZh":"规划股票投资组合","question":"How does the older investor differ in his approach to investment from the younger investor?","sentences":[{"en":"There is no shortage of tipsters around offering 'get-rich-quick' opportunities.","zh":"身边不乏提供“快速致富”机会的内幕消息者。","t":19.17},{"en":"But if you are a serious private investor, leave the Las Vegas mentality to those with money to fritter.","zh":"但如果你是一个认真的私人投资者，就把那种拉斯维加斯的心态留给那些有钱可挥霍的人吧。","t":24.88},{"en":"The serious investor needs a proper 'portfolio' --a well-planned selection of investments, with a definite structure and a clear aim.","zh":"认真的投资者需要一个合适的“投资组合”——一个精心策划的投资选择，具有明确的结构和清晰的目标。","t":32.41},{"en":"But exactly how does a newcomer to the stock market go about achieving that?","zh":"但股市新手究竟如何才能做到这一点呢？","t":41.88},{"en":"Well, if you go to five reputable stock brokers and ask them what you should do with your money,","zh":"嗯，如果你去找五位声誉良好的股票经纪人，问他们你该如何处理你的钱，","t":48.15},{"en":"you're likely to get five different answers,","zh":"你很可能会得到五种不同的答案，","t":54.44},{"en":"-- even if you give all the relevant information about your age, family, finances and what you want from your investments.","zh":"——即使你提供了所有关于你的年龄、家庭、财务状况以及你希望从投资中获得什么的相关信息。","t":57.32},{"en":"Moral? There is no one 'right' way to structure a portfolio.","zh":"结论？没有一个“正确”的方法来构建投资组合。","t":65.48},{"en":"However, there are undoubtedly some wrong ways, and you can be sure that none of our five advisers","zh":"然而，无疑有一些错误的方法，你可以肯定，我们的五位顾问中没有一人会","t":70.44},{"en":"would have suggested sinking all (or perhaps any) of your money into Periwigs.","zh":"建议你把所有（或者说任何）钱投入到Periwigs公司。","t":77.23},{"en":"So what should you do?","zh":"那么你该怎么做呢？","t":83.36},{"en":"We'll assume that you have sorted out the basics--like mortgages, pensions, insurance and access to sufficient cash reserves.","zh":"我们假设你已经解决了基本问题——比如抵押贷款、养老金、保险和拥有足够的现金储备。","t":85.21},{"en":"You should then establish your own individual aims.","zh":"然后你应该确立自己的个人目标。","t":94},{"en":"These are partly a matter of personal circumstances, partly a matter of psychology.","zh":"这些部分取决于个人情况，部分取决于心理因素。","t":97.56},{"en":"For instance, if you are older you have less time to recover from any major losses, and you may well wish to boost your pension income.","zh":"例如，如果你年龄较大，从任何重大损失中恢复的时间较短，而且你很可能希望增加你的养老金收入。","t":103.67},{"en":"So preserving your capital and generating extra income are your main priorities.","zh":"因此，保住你的本金并获得额外收入是你的主要优先事项。","t":113.09},{"en":"In this case, you'd probably construct a portfolio with some shares (but not high risk ones), along with gilts, cash deposits,","zh":"在这种情况下，你可能会构建一个包含一些股票（但不是高风险的）、政府债券、现金存款、","t":119.36},{"en":"and perhaps convertibles or the income shares of split capital investment trusts.","zh":"也许还有可转换债券或分级资本投资信托的收益股的投资组合。","t":129},{"en":"If you are younger, and in a solid financial position,","zh":"如果你比较年轻，且财务状况稳健，","t":135.11},{"en":"you may decide to take an aggressive approach--but only if you're blessed with a sanguine disposition and won't suffer sleepless nights over share prices.","zh":"你可能会决定采取激进的策略——但前提是你拥有乐观的性格，并且不会因为股价而彻夜难眠。","t":139.49},{"en":"If you recognize yourself in this description,","zh":"如果你认为自己符合这个描述，","t":149.68},{"en":"you might include a couple of heady growth stocks in your portfolio, alongside your more pedestrian investments.","zh":"你可以在你的投资组合中加入几只涨势强劲的成长股，以及一些更稳健的投资。","t":152.72},{"en":"Once you have decided on your investment aims you can then decide where to put your money.","zh":"一旦你确定了你的投资目标，你就可以决定把钱投到哪里。","t":160.96},{"en":"The golden rule here is spread your risk--if you put all of your money into Periwigs International,","zh":"这里的黄金法则是分散风险——如果你把所有钱都投入到Periwigs国际公司，","t":167.65},{"en":"you're setting yourself up as a hostage to fortune.","zh":"你就是在把自己置于命运的摆布之下。","t":175.44}],"vocab":[{"word":"portfolio","phonetic":"/pɔːtˈfəʊliəʊ/","meanings":[{"pos":"noun","meaning":"投资组合；作品集；公文包","usage":"在金融语境中特指个人或机构持有的各类投资产品的集合"}]},{"word":"tipster","phonetic":"/ˈtɪpstə(r)/","meanings":[{"pos":"noun","meaning":"提供内幕消息的人；（股票、赛马等的）情报贩子","usage":"尤指向他人提供投资、博彩等建议以获利的人，常带有一定贬义"}]},{"word":"fritter","phonetic":"/ˈfrɪtə(r)/","meanings":[{"pos":"verb","meaning":"浪费（金钱、时间）","usage":"常和away搭配，构成fritter sth away的结构，表示毫无意义地消耗资源"}]},{"word":"reputable","phonetic":"/ˈrepjətəbl/","meanings":[{"pos":"adjective","meaning":"声誉好的，值得信赖的","usage":"用于形容机构、个人等拥有良好的公众口碑，可信度高"}]},{"word":"moral","phonetic":"/ˈmɒrəl/","meanings":[{"pos":"noun","meaning":"寓意，教训","usage":"指从事件、故事中总结出的具有指导意义的道理"}]},{"word":"sink","phonetic":"/sɪŋk/","meanings":[{"pos":"verb","meaning":"投入（资金）","usage":"金融语境中表示将资金投入某一项目、投资产品中，常带有投入大量资金的含义"}]},{"word":"mortgage","phonetic":"/ˈmɔːɡɪdʒ/","meanings":[{"pos":"noun","meaning":"房屋抵押贷款，按揭","usage":"指以房产为抵押向银行申请的贷款，用于购房等用途"}]},{"word":"pension","phonetic":"/ˈpenʃn/","meanings":[{"pos":"noun","meaning":"养老金，退休金","usage":"指人们退休后定期领取的生活保障资金"}]},{"word":"reserve","phonetic":"/rɪˈzɜːv/","meanings":[{"pos":"noun","meaning":"储备（金），储备物","usage":"多指为应对特殊情况预留的资金、物资等，常用复数形式reserves"}]},{"word":"psychology","phonetic":"/saɪˈkɒlədʒi/","meanings":[{"pos":"noun","meaning":"心理特点；心理学","usage":"此处指影响人决策的心理特质、心理状态"}]},{"word":"boost","phonetic":"/buːst/","meanings":[{"pos":"verb","meaning":"增加，提高；促进","usage":"常搭配income、confidence、economy等名词，表示提升相关事物的水平"}]},{"word":"preserve","phonetic":"/prɪˈzɜːv/","meanings":[{"pos":"verb","meaning":"保护，保存，维持","usage":"此处指保障资金不受损失，也可表示保存文物、维持现状等含义"}]},{"word":"priority","phonetic":"/praɪˈɒrəti/","meanings":[{"pos":"noun","meaning":"优先事项，最重要的事","usage":"表示需要优先处理、重点关注的事务，常用搭配为top priority"}]},{"word":"sanguine","phonetic":"/ˈsæŋɡwɪn/","meanings":[{"pos":"adjective","meaning":"乐观的，充满信心的","usage":"用于形容人性格乐观，对未来持有积极态度"}]},{"word":"aggressive","phonetic":"/əˈɡresɪv/","meanings":[{"pos":"adjective","meaning":"积极进取的；激进的","usage":"在投资语境中指愿意承担较高风险追求高收益的风格，也可形容人有进取心或行为好斗"}]}],"phrases":[{"phrase":"get-rich-quick","usage":"形容词性短语，用于描述希望在短时间内迅速获得大量财富的想法、机会或行为，常带有不切实际的隐含意味","examples":[{"en":"Many people fall for scams that promise get-rich-quick schemes.","zh":"很多人落入了承诺快速致富的骗局。"},{"en":"He abandoned the get-rich-quick mindset and focused on long-term career development.","zh":"他摒弃了快速致富的心态，专注于长期的职业发展。"}]},{"phrase":"go about doing sth","usage":"动词短语，表示着手做、处理某件事，强调做事的方式和过程","examples":[{"en":"If you want to apply for this scholarship, you should go about preparing the required documents first.","zh":"如果你想申请这个奖学金，你应该首先着手准备所需的文件。"},{"en":"I have no idea how to go about repairing this broken laptop.","zh":"我不知道该怎么着手修理这台坏了的笔记本电脑。"}]},{"phrase":"sort out","usage":"动词短语，意为整理好、解决、处理妥当，多用于表示理清复杂的事务或解决问题","examples":[{"en":"You need to sort out your travel itinerary before you leave for the trip.","zh":"你出发旅行之前需要整理好你的行程安排。"},{"en":"It took me two hours to sort out the messy files on my desk.","zh":"我花了两个小时才整理好我桌上乱糟糟的文件。"}]},{"phrase":"be blessed with","usage":"固定搭配，表示有幸拥有、天生具有（某种好的特质、条件等），带有感激的意味","examples":[{"en":"She is blessed with a beautiful voice and has won many singing competitions.","zh":"她天生有一副好嗓子，已经赢得了很多歌唱比赛。"},{"en":"This small town is blessed with clear lakes and lush mountains, attracting lots of tourists every year.","zh":"这个小镇有幸拥有清澈的湖泊和葱郁的山峦，每年都吸引很多游客。"}]},{"phrase":"suffer sleepless nights over sth","usage":"习语，意为为某事焦虑得睡不着觉，强调因担忧某件事而产生巨大的心理压力","examples":[{"en":"Many students suffer sleepless nights over their final exam results.","zh":"很多学生因为担心期末考试成绩而焦虑得睡不着觉。"},{"en":"He has been suffering sleepless nights over the upcoming important business negotiation.","zh":"他因为即将到来的重要商务谈判而焦虑得夜夜失眠。"}]},{"phrase":"set sb up as","usage":"动词短语，此处表示使某人处于（某种不利的境地），也可表示扶持某人创业、使某人担任某个职位","examples":[{"en":"If you don't buy insurance for your car, you're setting yourself up as a target for huge losses in case of accidents.","zh":"如果你不给你的车买保险，一旦发生事故你就会面临巨额损失的风险。"},{"en":"His parents set him up as the manager of the family business after he graduated from university.","zh":"他大学毕业后，他的父母扶持他当上了家族企业的经理。"}]},{"phrase":"hostage to fortune","usage":"固定习语，指可能带来风险的事物、处境，意为“担风险的事；容易受到不利影响的处境”","examples":[{"en":"Putting all your savings into a single high-risk stock is a hostage to fortune.","zh":"把你所有的积蓄都投入一只高风险的股票是一件非常冒险的事。"},{"en":"Revealing too much personal information online can make you a hostage to fortune.","zh":"在网上透露太多个人信息会让你处于容易受伤害的风险中。"}]},{"phrase":"solid financial position","usage":"名词性短语，意为经济状况稳定、财务状况良好，用于描述个人或机构的财务状态健康","examples":[{"en":"Only people in a solid financial position can consider buying such an expensive property.","zh":"只有财务状况稳定的人才可以考虑购买这么贵的房产。"},{"en":"The company is in a solid financial position after three years of steady growth.","zh":"经过三年的稳定增长，该公司的财务状况十分良好。"}]},{"phrase":"spread your risk","usage":"金融领域常用短语，意为分散风险，指通过投资不同品类的资产来降低整体投资的风险","examples":[{"en":"When planning investments, the first rule is to spread your risk to avoid losing all your money at once.","zh":"规划投资时，首要原则是分散风险，避免一次性损失你所有的钱。"},{"en":"Financial advisors always remind clients to spread their risk instead of focusing on one type of asset.","zh":"理财顾问总是提醒客户要分散风险，不要只盯着一种资产投资。"}]}],"grammar":[{"title":"条件状语从句的真实条件句（零/第一条件句）","definition":"用于描述真实存在、可能发生的情况及对应的结果，是对现实情况的合理假设和推断","structure":"If + 一般现在时/现在相关时态，主句用一般现在时/将来时/情态动词（may/might/should/can等）+ 动词原形","usage":"常用于提出建议、说明规律、描述假设的情况及其合理结果，在说明事理、给出指导的文体中十分常见","examples":[{"en":"If you are older, you have less time to recover from any major losses.","zh":"如果你年龄较大，你从重大损失中恢复的时间就更少。"},{"en":"If it rains tomorrow, we will cancel the outdoor sports meeting.","zh":"如果明天下雨，我们就取消户外运动会。"},{"en":"If you have any questions during the class, you can ask the teacher for help at any time.","zh":"如果你上课期间有任何问题，你可以随时向老师求助。"}]},{"title":"破折号的解释说明用法","definition":"英文中破折号常用来对前文的内容进行补充说明、解释、举例，或者引出转折、强调的内容，使句子逻辑更清晰，补充信息更突出","structure":"完整句子 + 破折号 + 解释/补充/说明内容","usage":"在书面语中可以替代括号、冒号等，用来插入补充信息，既不打断主句的流畅性，又能突出补充的内容","examples":[{"en":"The serious investor needs a proper 'portfolio' --a well-planned selection of investments, with a definite structure and a clear aim.","zh":"认真的投资者需要一份正规的“投资组合”——即经过周密计划选定的投资项目，有明确的结构和清晰的目标。"},{"en":"Everything in the house was covered with dust --it had been empty for more than ten years.","zh":"房子里的所有东西都盖着一层灰——这房子已经空了十多年了。"},{"en":"She said she would come to the party tonight --that is, if she finishes her work on time.","zh":"她说她今晚会来参加派对——也就是说，前提是她能按时完成她的工作。"}]}],"patterns":[{"pattern":"There is no shortage of ... offering ...","explanation":"","original":{"en":"There is no shortage of tipsters around offering 'get-rich-quick' opportunities.","zh":"周围不乏情报贩子，向人们提供“快速致富”的机遇。"},"examples":[{"en":"There is no shortage of influencers online offering shortcuts to learning English.","zh":"网上不乏博主，向人们提供学习英语的捷径。"},{"en":"There is no shortage of shops in the tourist area offering local specialty products.","zh":"旅游区里不乏商店，向游客售卖当地特产。"}]},{"pattern":"If you ..., you're likely to ... -- even if ...","explanation":"","original":{"en":"if you go to five reputable stock brokers and ask them what you should do with your money, you're likely to get five different answers, -- even if you give all the relevant information about your age, family, finances and what you want from your investments.","zh":"如果你去找5位信誉良好的股票经纪人，问他们你应该用你的钱做什么，你很可能会得到5个不同的答案——即便你提供了所有相关信息，包括你的年龄、家庭、财务状况以及你想从投资中获得的目标。"},"examples":[{"en":"If you ask ten people for their opinions on this movie, you're likely to get ten different comments -- even if they all watched the same version.","zh":"如果你问10个人对这部电影的看法，你很可能会得到10种不同的评价——即便他们看的都是同一个版本。"},{"en":"If you travel to a new city, you're likely to meet some unexpected troubles -- even if you have made a very detailed travel plan.","zh":"如果你去一座新城市旅行，你很可能会遇到一些意想不到的麻烦——即便你已经做了非常详尽的旅行计划。"}]},{"pattern":"These are partly a matter of ..., partly a matter of ...","explanation":"","original":{"en":"These are partly a matter of personal circumstances, partly a matter of psychology.","zh":"这些一方面取决于个人的经济状况，另一方面取决于个人的心理因素。"},"examples":[{"en":"Whether a person can succeed in a career is partly a matter of personal effort, partly a matter of opportunity.","zh":"一个人能否在事业上取得成功，一方面取决于个人的努力，另一方面取决于机遇。"},{"en":"The price of this kind of agricultural product is partly a matter of output, partly a matter of market demand.","zh":"这种农产品的价格一方面取决于产量，另一方面取决于市场需求。"}]},{"pattern":"The golden rule here is ... -- if you ..., you're ...","explanation":"","original":{"en":"The golden rule here is spread your risk -- if you put all of your money into Periwigs International, you're setting yourself up as a hostage to fortune.","zh":"这里的黄金原则是分散风险——如果你把所有的钱都投入佩里威格斯国际公司，你就是在把自己置于风险之中。"},"examples":[{"en":"The golden rule here is to respect others -- if you always speak ill of people behind their backs, you're going to lose all your friends sooner or later.","zh":"这里的黄金原则是尊重他人——如果你总是在背后说别人的坏话，你迟早会失去所有的朋友。"},{"en":"The golden rule for preparing for exams is to review steadily every day -- if you only cram the night before the exam, you're unlikely to get a good score.","zh":"备考的黄金原则是每天稳步复习——如果你只在考试前一晚临时抱佛脚，你不太可能取得好成绩。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“声誉好的，值得信赖的” 对应的单词是？","hint":"adjective · /ˈrepjətəbl/","options":["throng","humidity","reputable","susceptible"],"answer":2,"explain":"reputable · /ˈrepjətəbl/ · adjective · 声誉好的，值得信赖的。用于形容机构、个人等拥有良好的公众口碑，可信度高","source":{"kind":"vocab","word":"reputable"},"id":"b4-u48-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：养老金，退休金","hint":"/ˈpenʃn/ · noun","answer":"pension","placeholder":"输入英文单词","explain":"pension · /ˈpenʃn/ · noun · 养老金，退休金。指人们退休后定期领取的生活保障资金","source":{"kind":"vocab","word":"pension"},"id":"b4-u48-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Only people in a _____ can consider buying such an expensive property.","hint":"只有财务状况稳定的人才可以考虑购买这么贵的房产。","answer":"solid financial position","placeholder":"输入缺失的短语","explain":"solid financial position：名词性短语，意为经济状况稳定、财务状况良好，用于描述个人或机构的财务状态健康（只有财务状况稳定的人才可以考虑购买这么贵的房产。）","source":{"kind":"phrase","phrase":"solid financial position"},"id":"b4-u48-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Well, if you go to five reputable _____ brokers and ask them what you should do with your money,","hint":"嗯，如果你去找五位声誉良好的股票经纪人，问他们你该如何处理你的钱，","answer":"stock","placeholder":"输入缺失的单词","explain":"Well, if you go to five reputable stock brokers and ask them what you should do with your money, — 嗯，如果你去找五位声誉良好的股票经纪人，问他们你该如何处理你的钱，","source":{"kind":"sentence","en":"Well, if you go to five reputable stock brokers and ask them what you should do with your money,"},"id":"b4-u48-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于描述真实存在、可能发生的情况及对应的结果，是对现实情况的合理假设和推断” 描述的是哪个语法点？","hint":"If + 一般现在时/现在相关时态，主句用一般现在时/将来时/情态动词（may/might/should/can等）+ 动词原形","options":["条件状语从句的真实条件句（零/第一条件句）","so...that...引导的结果状语从句","插入语","形容词/名词前置的倒装结构"],"answer":0,"explain":"条件状语从句的真实条件句（零/第一条件句）：If + 一般现在时/现在相关时态，主句用一般现在时/将来时/情态动词（may/might/should/can等）+ 动词原形：常用于提出建议、说明规律、描述假设的情况及其合理结果，在说明事理、给出指导的文体中十分常见","source":{"kind":"grammar","title":"条件状语从句的真实条件句（零/第一条件句）"},"id":"b4-u48-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nBut if you are a serious private investor, leave the Las Vegas mentality to those with money to fritter.","hint":"","options":["但重要的不是运动员的行为，而是观众的态度：","事实上，我们现在缺乏处理原始条件的实践和经验。","但如果你是一个认真的私人投资者，就把那种拉斯维加斯的心态留给那些有钱可挥霍的人吧。","我曾多次试图构想那些页面可能包含什么，"],"answer":2,"explain":"But if you are a serious private investor, leave the Las Vegas mentality to those with money to fritter. — 但如果你是一个认真的私人投资者，就把那种拉斯维加斯的心态留给那些有钱可挥霍的人吧。","source":{"kind":"sentence","en":"But if you are a serious private investor, leave the Las Vegas mentality to those with money to fritter."},"id":"b4-u48-q06"}]}]};
